 -- LocalServer.lua
local LS = {}
LS.VERSION = "ls-2.78-bot-fusion"

local H = {}
local S = nil
local R = { enabled = false }

local STATE_FILE = "offline_ls_state.txt"
local LOG_FILE   = "offline_ls_log.txt"
local DUMP_FILE  = "offline_dump.txt"

-- [ACCOUNT v6.32] Luu theo tai khoan: STATE_FILE (o tren) doi theo LS.set_account; file phu (replay...) them hau to
-- "_<tai khoan>" truoc duoi .txt. Khong dang nhap -> hau to rong -> ten file nhu cu.
LS._acct = { user = nil, suffix = "" }
function LS.acct_file(base, sfx)
	if sfx == nil then sfx = LS._acct.suffix end
	if sfx == nil or sfx == "" then return base end
	local stem, ext = string.match(base, "^(.*)(%.[^%.]+)$")
	if stem == nil then return base .. sfx end
	return stem .. sfx .. ext
end

local function G(name) return rawget(_G, name) end

local function ED()
	local e = rawget(_G, "_ED")
	if type(e) == "table" then return e end
	return nil
end

local function tn(v, d)
	local n = tonumber(v)
	if n == nil then return d end
	return n
end

local function fint(n) return string.format("%.0f", n) end

local function fnum(n)
	n = tonumber(n)
	if n == nil then return "-" end
	local s = fint(n)
	local neg = false
	if string.sub(s, 1, 1) == "-" then neg = true; s = string.sub(s, 2) end
	while true do
		local r, k = string.gsub(s, "^(%d+)(%d%d%d)", "%1,%2")
		s = r
		if k == 0 then break end
	end
	if neg then s = "-" .. s end
	return s
end

local function traceback(err)
	local dbg = rawget(_G, "debug")
	if type(dbg) == "table" and dbg.traceback ~= nil then
		return dbg.traceback(tostring(err), 2)
	end
	return tostring(err)
end

local function log(...)
	local t = {}
	for i = 1, select("#", ...) do t[#t + 1] = tostring((select(i, ...))) end
	local line = table.concat(t, " ")
	if H.logmsg ~= nil then H.logmsg("LS:", line) end
	R.log_n = (R.log_n or 0) + 1
	if R.log_n <= 4000 and H.append_line ~= nil then
		H.append_line(LOG_FILE, os.date("%H:%M:%S") .. " " .. line .. "\n")
	end
end

local function toast(text, secs)
	if H.notify ~= nil then pcall(H.notify, text, secs or 6) end
end

local function mark() R.dirty = true end

local RESERVED = {}
for _, w in ipairs({ "and", "break", "do", "else", "elseif", "end", "false", "for", "function", "goto",
	"if", "in", "local", "nil", "not", "or", "repeat", "return", "then", "true", "until", "while" }) do
	RESERVED[w] = true
end

-- [FIX lag 8] Ghi trang thai (offline_ls_state.txt) truoc day: ~90 cho goi save_state(true) => MOI thao tac
-- (nang cap, mua, ket thuc tran...) ser() lai TOAN BO S (~645 KB, ~160k manh) ngay trong frame do => khung hinh
-- dung hinh 0.1-0.5 s tren dien thoai. 73% dung luong la S.ws.sp (chien hon) hau nhu khong doi.
-- Nay: (1) ser() nhanh hon (bien cuc bo, so nguyen dung %d); (2) S.ws.sp duoc cache chuoi (version R.sp_ver tang trong
-- put/remove cua WS + dem so phan tu); (3) save_state(true) chi DANH DAU, viec ghi that chay chia nho theo frame
-- (coroutine, ~3 ms moi lan LS.sync) va gop nhieu lan goi lien tiep thanh 1; (4) LS.save_now()/LS.flush() ghi dong bo
-- khi can (vao nen / thoat). Noi dung file ghi ra KHONG doi dinh dang.
local sformat, mfloor, mhuge = string.format, math.floor, math.huge
local SAVE = {
	sp = { tbl = nil, ver = -1, cnt = -1, str = nil }, -- cache chuoi cua S.ws.sp
	sp_tbl = nil,   -- bang S.ws.sp dang duoc xu ly dac biet trong lan ser hien tai
	y = nil,        -- ham nhuong (chi dat khi dang chay trong coroutine ghi)
	n = 0, t0 = 0,
	job = nil, want = false, last = nil, fails = 0,
}
local sp_text

local function ser(v, buf)
	local t = type(v)
	if t == "number" then
		if v ~= v or v == mhuge or v == -mhuge then
			buf[#buf + 1] = "0"
		elseif v == mfloor(v) and v > -2147483648 and v < 2147483648 then
			buf[#buf + 1] = sformat("%d", v)
		else
			buf[#buf + 1] = sformat("%.17g", v)
		end
	elseif t == "string" then
		buf[#buf + 1] = sformat("%q", v)
	elseif t == "boolean" then
		buf[#buf + 1] = v and "true" or "false"
	elseif t == "table" then
		if v == SAVE.sp_tbl then
			buf[#buf + 1] = sp_text(v)
			return
		end
		local y = SAVE.y
		if y ~= nil then y() end
		buf[#buf + 1] = "{"
		local n = #v
		for i = 1, n do
			ser(v[i], buf)
			buf[#buf + 1] = ","
		end
		for k, x in pairs(v) do
			local skip = false
			if type(k) == "number" and k >= 1 and k <= n and k == mfloor(k) then skip = true end
			if not skip then
				if type(k) == "string" and string.match(k, "^[%a_][%w_]*$") and not RESERVED[k] then
					buf[#buf + 1] = k .. "="
				else
					buf[#buf + 1] = "["
					ser(k, buf)
					buf[#buf + 1] = "]="
				end
				ser(x, buf)
				buf[#buf + 1] = ","
			end
		end
		buf[#buf + 1] = "}"
	else
		buf[#buf + 1] = "nil"
	end
end

-- Chuoi cua S.ws.sp: dung lai neu cung bang, cung version (R.sp_ver) va cung so phan tu
sp_text = function(sp)
	local c = SAVE.sp
	local cnt = 0
	for _ in pairs(sp) do cnt = cnt + 1 end
	if c.tbl == sp and c.ver == (R.sp_ver or 0) and c.cnt == cnt and c.str ~= nil then return c.str end
	local ver = R.sp_ver or 0
	local b = {}
	SAVE.sp_tbl = nil
	ser(sp, b)
	SAVE.sp_tbl = sp
	local s = table.concat(b)
	c.tbl, c.ver, c.cnt, c.str = sp, ver, cnt, s
	return s
end

local function save_yield()
	local n = SAVE.n + 1
	SAVE.n = n
	if n % 48 == 0 and os.clock() - SAVE.t0 >= 0.003 then coroutine.yield() end
end

local function deser(src)
	local f, err
	local sfe, lst = rawget(_G, "setfenv"), rawget(_G, "loadstring")
	if sfe ~= nil and lst ~= nil then
		f, err = lst("return " .. src, "=ls_state")
		if f then sfe(f, {}) end
	else
		f, err = load("return " .. src, "=ls_state", "t", {})
	end
	if not f then return nil, err end
	local ok, res = pcall(f)
	if not ok then return nil, res end
	return res
end

local function new_state()
	return {
		v = 1,
		gold = nil, silver = nil,
		next_id = 0,
		heroes = {},
		order = {},
		formation = nil,
		free = nil, free_day = nil,
		draws = nil,
		cfg = { grant_grade = 0, mult = 1 },
		stats = {},

		props = {},
		mods = {},
		sp = nil,

		eq = { hard = {}, bag = {}, next_eid = 800000000 },

		ws = { nid = 700000000, sp = {}, del = {}, seat = {} },

		mega = {},
	}
end

function LS.load_state()
	S = nil
	local txt = nil
	if H.read_first ~= nil then txt = H.read_first(STATE_FILE) end
	if txt ~= nil and #txt > 2 then
		local t, err = deser(txt)
		if type(t) == "table" and t.v == 1 and type(t.heroes) == "table" and type(t.order) == "table" then
			S = t
		else
			log("file trang thai hong, bo qua:", tostring(err))
			if H.write_first ~= nil then H.write_first(STATE_FILE .. ".bad", txt) end
		end
	end
	if S == nil then S = new_state() end
	if type(S.cfg) ~= "table" then S.cfg = { grant_grade = 0 } end
	if tonumber(S.cfg.mult) == nil or tonumber(S.cfg.mult) <= 0 then S.cfg.mult = 1 end
	if type(S.stats) ~= "table" then S.stats = {} end
	if type(S.props) ~= "table" then S.props = {} end
	if type(S.mods) ~= "table" then S.mods = {} end
	if S.camp ~= nil and type(S.camp) ~= "table" then S.camp = nil end
	if S.user ~= nil and type(S.user) ~= "table" then S.user = nil end
	if type(S.eq) ~= "table" then S.eq = {} end
	if type(S.eq.hard) ~= "table" then S.eq.hard = {} end
	if type(S.eq.bag) ~= "table" then S.eq.bag = {} end
	if tonumber(S.eq.next_eid) == nil then S.eq.next_eid = 800000000 end
	if type(S.ws) ~= "table" then S.ws = {} end
	if tonumber(S.ws.nid) == nil then S.ws.nid = 700000000 end
	if type(S.ws.sp) ~= "table" then S.ws.sp = {} end
	if type(S.ws.del) ~= "table" then S.ws.del = {} end
	if type(S.ws.seat) ~= "table" then S.ws.seat = {} end
	if type(S.mega) ~= "table" then S.mega = {} end
	if S.tr ~= nil and type(S.tr) ~= "table" then S.tr = nil end
	if S.am ~= nil and type(S.am) ~= "table" then S.am = nil end
	if S.tl ~= nil and type(S.tl) ~= "table" then S.tl = nil end
	if S.al ~= nil and type(S.al) ~= "table" then S.al = nil end
	if S.ar ~= nil and type(S.ar) ~= "table" then S.ar = nil end
	if S.wp ~= nil and type(S.wp) ~= "table" then S.wp = nil end
	if S.cb ~= nil and type(S.cb) ~= "table" then S.cb = nil end
	if S.ic ~= nil and type(S.ic) ~= "table" then S.ic = nil end
	if S.sg ~= nil and type(S.sg) ~= "table" then S.sg = nil end
	if S.tt ~= nil and type(S.tt) ~= "table" then S.tt = nil end
	if S.ft ~= nil and type(S.ft) ~= "table" then S.ft = nil end
	if S.bg ~= nil and type(S.bg) ~= "table" then S.bg = nil end
	if S.hs ~= nil and type(S.hs) ~= "table" then S.hs = nil end
	if S.ma ~= nil and type(S.ma) ~= "table" then S.ma = nil end
	if S.af ~= nil and type(S.af) ~= "table" then S.af = nil end
	if S.fxbad ~= nil and type(S.fxbad) ~= "table" then S.fxbad = nil end
	if S.prof ~= nil and type(S.prof) ~= "table" then S.prof = nil end
	if LS._ar ~= nil and LS._ar.rep_load ~= nil then pcall(LS._ar.rep_load) end
	R.dirty = false
	return S
end

-- Ghi dong bo, ngay lap tuc (dung khi vao nen / can chac chan da xuong file).
function LS.save_now()
	if S == nil or H.write_first == nil then return false end
	SAVE.job, SAVE.y = nil, nil
	SAVE.sp_tbl = (type(S.ws) == "table") and S.ws.sp or nil
	local buf = {}
	local ok, err = pcall(ser, S, buf)
	SAVE.y = nil
	if not ok then
		log("loi ghi trang thai:", tostring(err))
		R.dirty = true
		return false
	end
	R.dirty = false
	SAVE.want = false
	SAVE.last = os.time()
	R.last_save = SAVE.last
	H.write_first(STATE_FILE, table.concat(buf))
	return true
end

-- Co gi chua ghi thi ghi ngay (goi khi game xuong nen).
function LS.flush()
	if S == nil then return false end
	if LS._ar ~= nil and LS._ar.sh_publish_current ~= nil then pcall(LS._ar.sh_publish_current) end
	if R.ar_rep_dirty and LS._ar ~= nil and LS._ar.rep_flush ~= nil then pcall(LS._ar.rep_flush) end
	if R.dirty or SAVE.want or SAVE.job ~= nil then return LS.save_now() end
	return false
end

-- save_state(true): danh dau "can ghi" -> ghi that chay chia nho trong LS.sync (gop nhieu lan goi lien tiep).
-- save_state("now"): ghi dong bo ngay.
function LS.save_state(force)
	if S == nil or H.write_first == nil then return end
	if force == "now" then return LS.save_now() end
	if force then
		R.dirty = true
		SAVE.want = true
	end
	-- (ghi dinh ky khi R.dirty do LS._save_tick lo)
end

-- Duoc goi dau moi LS.sync: bat dau / tiep tuc viec ghi chia nho (~3 ms moi lan).
function LS._save_tick()
	if S == nil or H.write_first == nil then return end
	local job = SAVE.job
	if job ~= nil and job.S0 ~= S then
		SAVE.job = nil
		job = nil
		R.dirty = true
	end
	if job == nil then
		local want = SAVE.want
		if not want and not R.dirty then return end
		-- [FIX lag] Dang nang max tuong: khong ghi giua chung; FH.finish se danh dau ghi 1 lan.
		if R.fh ~= nil then return end
		local now = os.time()
		local gap = want and 1 or 2
		if SAVE.last ~= nil and now - SAVE.last < gap then return end
		SAVE.want = false
		R.dirty = false
		SAVE.last = now
		R.last_save = now
		SAVE.sp_tbl = (type(S.ws) == "table") and S.ws.sp or nil
		local buf = {}
		job = { buf = buf, S0 = S }
		job.co = coroutine.create(function() ser(S, buf) end)
		SAVE.job = job
	end
	SAVE.n, SAVE.t0, SAVE.y = 0, os.clock(), save_yield
	local ok, err = coroutine.resume(job.co)
	SAVE.y = nil
	if not ok then
		SAVE.job = nil
		SAVE.fails = SAVE.fails + 1
		R.dirty = true
		-- bang bi sua trong luc duyet (hiem): ghi lai dong bo cho chac
		if SAVE.fails <= 5 then log("loi ghi trang thai (chia nho):", tostring(err)) end
		pcall(LS.save_now)
	elseif coroutine.status(job.co) == "dead" then
		SAVE.job = nil
		H.write_first(STATE_FILE, table.concat(job.buf))
	end
end

-- =====================================================================================================
-- [ACCOUNT v6.32] LS.set_account(uname): chuyen file luu (offline_ls_state_<tai khoan>.txt) theo tai khoan dang nhap.
--  * Ghi DONG BO trang thai tai khoan cu truoc khi doi (save_state(true) chi danh dau, se ghi nham sang file moi).
--  * [v6.33] MOI tai khoan moi bat dau tu LS MAC DINH lay tu seed (offline_ls_default.txt), doc lap nhau;
--    offline_ls_state.txt cu khong con bi tai khoan nao tu dong thua huong (van nam nguyen tren dia).
--  * Ten file dung "_" thay ky tu la; ky tu la ('.', '@') duoc ma hoa _xHH de 2 tai khoan khac nhau khong dung chung file.
-- =====================================================================================================
local LEGACY_STATE_FILE = "offline_ls_state.txt"
local LEGACY_OWNER_FILE = "offline_ls_state_owner.txt"
local LEGACY_AUX = { "offline_tn_replays.txt", "offline_ww_replays.txt", "offline_ar_replays.txt" }

local function acct_slug(uname)
	local s = tostring(uname or "")
	s = string.gsub(s, "[^%w_%-]", function(c) return string.format("_x%02x", string.byte(c)) end)
	return string.lower(s)
end

-- [ACCOUNT v6.33] Trang thai LS MAC DINH cua tai khoan moi: doc tu seed (offline_ls_default.txt, nam trong
-- client/offline/seed/, may nao cung co). Seed thieu / hong => tra false (LS tu dung trang thai trong).
LS.DEFAULT_STATE_FILE = "offline_ls_default.txt"

function LS.seed_default_state(file)
	if H.read_first == nil or H.write_first == nil then return false end
	local okd, def = pcall(H.read_first, LS.DEFAULT_STATE_FILE)
	if okd and type(def) == "string" and #def > 2 then
		local t = deser(def)
		if type(t) == "table" and t.v == 1 and type(t.heroes) == "table" and type(t.order) == "table" then
			pcall(H.write_first, file, def)
			log("tai khoan moi: nap LS mac dinh tu seed", LS.DEFAULT_STATE_FILE, "->", file)
			return true
		end
		log("seed LS mac dinh khong hop le, dung trang thai trong:", LS.DEFAULT_STATE_FILE)
	end
	return false
end

-- Goi khi DANG KY thanh cong: tao (ghi de) file du lieu cua tai khoan moi bang LS mac dinh va xoa file phu cu cung ten.
function LS.new_account(uname, uid)
	local u = acct_slug(uname)
	if u == "" or H.write_first == nil then return false end
	local sfx = "_" .. u
	local file = LS.acct_file(LEGACY_STATE_FILE, sfx)
	if file == STATE_FILE then return false end
	for i = 1, #LEGACY_AUX do pcall(H.write_first, LS.acct_file(LEGACY_AUX[i], sfx), "") end
	if not LS.seed_default_state(file) then
		local buf = {}
		if pcall(ser, new_state(), buf) then pcall(H.write_first, file, table.concat(buf)) end
	end
	log("tai khoan moi", tostring(uname), "uid", tostring(uid), "-> LS mac dinh tai", file)
	return true
end

function LS.set_account(uname, uid)
	local u = acct_slug(uname)
	local new_sfx = (u == "") and "" or ("_" .. u)
	local new_file = LS.acct_file(LEGACY_STATE_FILE, new_sfx)
	local A = LS._acct
	if new_file == STATE_FILE then
		A.user = (u ~= "") and tostring(uname) or nil
		A.uid = tonumber(uid)
		return false
	end

	-- 1) luu tai khoan cu (dong bo) vao file cu; dong thoi ghi doi hinh/hang cua tai khoan cu vao kho arena CHUNG
	if S ~= nil then
		if LS._ar ~= nil and LS._ar.sh_publish_current ~= nil then pcall(LS._ar.sh_publish_current) end
		pcall(LS.save_now)
		if LS._ar ~= nil and LS._ar.rep_flush ~= nil then pcall(LS._ar.rep_flush) end
	end
	SAVE.job, SAVE.y, SAVE.want = nil, nil, false

	-- 2) doi file luu (+ file phu theo hau to)
	STATE_FILE = new_file
	A.suffix, A.user, A.uid = new_sfx, (u ~= "") and tostring(uname) or nil, tonumber(uid)
	if LS._ar ~= nil and type(LS._ar.K) == "table" and LS._ar.K.REP_FILE ~= nil then
		LS._ar.K.REP_FILE = LS.acct_file("offline_ar_replays.txt", new_sfx)
	end

	-- 3) [v6.33] file chua co => cap LS MAC DINH tu seed. Khong con "tai khoan dau tien nhan du lieu cu":
	--    moi tai khoan bat dau tu cung 1 trang thai mac dinh, doc lap nhau (offline_ls_state.txt cu van con nguyen tren dia).
	if new_sfx ~= "" and H.read_first ~= nil and H.write_first ~= nil then
		local okc, cur = pcall(H.read_first, new_file)
		if not (okc and type(cur) == "string" and #cur > 2) then
			LS.seed_default_state(new_file)
		end
	end

	-- 4) bo nho dem runtime cua tai khoan cu + nap lai du lieu tai khoan moi
	R.tn_rep, R.tn_rep_seq, R.ww_rep, R.ww_rep_seq = nil, nil, nil, nil
	R.ar_rep, R.ar_rep_keys, R.ar_preview, R.ar_preview_epoch = nil, nil, nil, nil
	R.al_rep = nil  -- [ARENA REPLAY v1] replay bao cao Arena (nap lai tu file cua tai khoan moi)
	R.cx_rep, R.cm_rep, R.ta_rep, R.ar_rep_dirty = nil, nil, nil, false  -- kho replay lien server (se nap lai tu file cua tai khoan moi)
	R.sh_cache, R.sh_cache_t, R.sh_bad, R.sh_pub_t = nil, nil, nil, nil  -- kho arena chung: doc lai cho tai khoan moi
	if S ~= nil then
		S = nil
		LS.load_state()
		-- the gioi dang mo (neu co) nap lai bang du lieu tai khoan moi o lan LS.sync ke tiep
		R.world_ui, R.world_ships = nil, nil
		R.ready = false
	end
	R.dirty = false
	log("doi tai khoan LS ->", tostring(uname), "file", new_file)
	toast("Đã nạp dữ liệu tài khoản: " .. tostring(uname), 5)
	return true
end

local function stat_inc(key, n)
	S.stats[key] = (tn(S.stats[key], 0)) + (n or 1)
end

local MONEY = {
	gold   = { field = "user_gold" },
	silver = { field = "user_silver" },
}

local function money_write(kind)
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or S == nil or S[kind] == nil then return end
	local f = MONEY[kind].field
	local want = S[kind]
	if tn(e.user_info[f], nil) ~= want then
		e.user_info[f] = fint(want)
		R.overwrites = (R.overwrites or 0) + 1
	end
end

function LS.money_get(kind)
	if S == nil then return nil end
	return S[kind]
end

function LS.money_set(kind, v)
	if S == nil or MONEY[kind] == nil then return false end
	v = tn(v, nil)
	if v == nil then return false end
	if v < 0 then v = 0 end
	S[kind] = math.floor(v)
	mark()
	money_write(kind)
	return true
end

function LS.money_add(kind, d)
	if S == nil or S[kind] == nil then return false end
	return LS.money_set(kind, S[kind] + d)
end

function LS.money_spend(kind, n)
	if S == nil or S[kind] == nil then return false end
	if S[kind] < n then return false end
	LS.money_set(kind, S[kind] - n)
	if kind == "gold" then stat_inc("spent_gold", n) else stat_inc("spent_silver", n) end
	return true
end

local WRAP_CODES = {
	[25] = { "gold", 1 }, [26] = { "gold", -1 },
	[27] = { "silver", 1 }, [28] = { "silver", -1 },
}

local AFTER_HOOK = {}

function LS.wrap_parsers()
	local pp = G("protocol_parse")
	if type(pp) ~= "table" then
		local np = G("NetworkProtocol")
		if type(np) == "table" then pp = np.protocol_parses end
	end
	if type(pp) ~= "table" then return 0 end
	local n = 0
	for _, entry in pairs(pp) do
		if type(entry) == "table" and entry.ls_orig == nil and type(entry.parser_fun) == "function" then
			local code = entry.code
			local spec = WRAP_CODES[code]
			if spec ~= nil then
				local orig = entry.parser_fun
				local kind, sign = spec[1], spec[2]
				entry.ls_orig = orig
				entry.parser_fun = function(a, b, c, d, list, f)
					local amount = nil
					if type(list) == "table" and list.pos ~= nil then amount = tonumber(list[list.pos]) end
					local r1 = orig(a, b, c, d, list, f)
					if R.enabled and S ~= nil and S[kind] ~= nil and amount ~= nil then
						local ok, err = pcall(LS.money_add, kind, sign * amount)
						if not ok then log("loi cong/tru delta:", err) end
						stat_inc("delta_" .. kind)
					end
					return r1
				end
				n = n + 1
			elseif code == 15005 then
				local orig = entry.parser_fun
				entry.ls_orig = orig
				entry.parser_fun = function(a, b, c, d, list, f)
					local r1 = orig(a, b, c, d, list, f)
					if R.enabled and S ~= nil and R.ready then
						local ok, err = pcall(AFTER_HOOK[15005])
						if not ok then log("loi gan 15005:", err) end
					end
					return r1
				end
				n = n + 1
			end
		end
	end
	return n
end

local function sm_ok()
	local d, sm = G("dms"), G("ship_mould")
	return type(d) == "table" and type(sm) == "table" and type(d["ship_mould"]) == "table"
end

local function mstr(tid, col)
	local d, sm = G("dms"), G("ship_mould")
	if type(d) ~= "table" or type(sm) ~= "table" then return nil end
	local idx = sm[col]
	if idx == nil then return nil end
	return d.string(d["ship_mould"], tid, idx)
end

local function mnum(tid, col, def)
	local v = tonumber(mstr(tid, col))
	if v == nil then return def end
	return v
end

-- Danh sach nay chi dung cho template da xac dinh loi. Khong loc theo ability:
-- LR/SSR hop le cung co ability 17, nen loc theo tu chat se xoa nham.
local HERO_BAD = {}

-- ship_config[50] la danh sach the SP, khong phai LR. Dung danh sach nay
-- de mien tru SP khoi bo loc. LR trong bo du lieu nay co mau rieng: ability
-- 17, universal_debris = -1, va khong nam trong danh sach SP. SSR thuong
-- cung ability 17 nhung universal_debris la gia tri hop le nen van duoc giu.
local function sp_card_types()
	if R.sp_card_types ~= nil then return R.sp_card_types end
	local d, cfg = G("dms"), G("ship_config")
	if type(d) ~= "table" or type(cfg) ~= "table" or type(d["ship_config"]) ~= "table" or cfg.param == nil then
		R.sp_card_pending = true
		return nil
	end
	local ok, raw = pcall(d.string, d["ship_config"], 50, cfg.param)
	if not ok or raw == nil or raw == "" then
		R.sp_card_pending = true
		return nil
	end
	local tags, n = {}, 0
	for id, kind in string.gmatch(tostring(raw), "(%d+)%s*,%s*(%d+)") do
		id, kind = tonumber(id), tonumber(kind)
		if id ~= nil and kind ~= nil then
			tags[id] = kind
			n = n + 1
		end
	end
	R.sp_card_pending = false
	R.sp_card_types = tags
	log("loc LR: nap", n, "the SP de mien tru")
	return tags
end

-- Danh sach chan LR thu cong: file offline_lr_ban.txt (dat trong Download hoac thu muc game).
-- Moi dong: so tid (nhieu so cach nhau dau phay) hoac ten tuong (khong phan biet hoa thuong).
-- Ten ket thuc bang * la khop theo tien to. Dong bat dau bang # la ghi chu.
function LS.ban_refresh(force)
	local now = os.time()
	if not force and R.ban_t ~= nil and now - R.ban_t < 20 then return end
	R.ban_t = now
	local txt = ""
	if H.read_first ~= nil then
		local okr, v = pcall(H.read_first, "offline_lr_ban.txt")
		if okr and type(v) == "string" then txt = v end
	end
	if R.ban_ready and R.ban_txt == txt then return end
	local ids, names, prefixes = {}, {}, {}
	local nt, nn = 0, 0
	for line in string.gmatch(txt, "[^\r\n]+") do
		line = string.gsub(line, "#.*$", "")
		line = string.gsub(line, "^%s+", "")
		line = string.gsub(line, "%s+$", "")
		if line ~= "" then
			local numeric, any = true, false
			for tok in string.gmatch(line, "[^,;%s]+") do
				any = true
				if tonumber(tok) == nil then numeric = false end
			end
			if numeric and any then
				for tok in string.gmatch(line, "[^,;%s]+") do
					ids[math.floor(tonumber(tok))] = true
					nt = nt + 1
				end
			elseif any then
				local nm = string.lower(line)
				if string.sub(nm, -1) == "*" then
					prefixes[#prefixes + 1] = string.sub(nm, 1, -2)
				else
					names[nm] = true
				end
				nn = nn + 1
			end
		end
	end
	local ready = true
	local by_name = 0
	if nn > 0 then
		if sm_ok() then
			for k in pairs(G("dms")["ship_mould"]) do
				local id = tonumber(k)
				if id ~= nil and not ids[id] then
					local nm = mstr(id, "ship_name")
					if nm ~= nil then
						nm = string.lower(string.gsub(string.gsub(tostring(nm), "^%s+", ""), "%s+$", ""))
						local hit = names[nm] == true
						if not hit then
							for i = 1, #prefixes do
								if string.sub(nm, 1, #prefixes[i]) == prefixes[i] then hit = true; break end
							end
						end
						if hit then ids[id] = true; by_name = by_name + 1 end
					end
				end
			end
		else
			ready = false
		end
	end
	local changed = R.ban_set == nil
	if not changed then
		local a, b = 0, 0
		for id in pairs(ids) do a = a + 1; if R.ban_set[id] == nil then changed = true end end
		for _ in pairs(R.ban_set) do b = b + 1 end
		if a ~= b then changed = true end
	end
	R.ban_set, R.ban_txt, R.ban_ready = ids, txt, ready
	R.ban_info = { tids = nt, names = nn, by_name = by_name, bytes = #txt }
	if changed then
		R.hero_ids, R.pool = nil, nil
		log("chan LR thu cong:", nt, "tid,", nn, "ten ->", by_name, "mau khop theo ten")
	end
end

function LS.ban_hit(tid)
	LS.ban_refresh(false)
	return R.ban_set ~= nil and R.ban_set[tid] == true
end

function LS.hero_is_lr(tid)
	tid = tonumber(tid)
	if tid == nil or tid <= 0 then return false end
	tid = math.floor(tid)
	if LS.ban_hit(tid) then return true end
	local sp = sp_card_types()
	-- Chua co config SP thi khoan loc de tranh xoa nham the SP khi dang tai game.
	if sp == nil then return false end
	if sp[tid] ~= nil then return false end
	if mnum(tid, "ability", 0) ~= 17 then return false end
	local debris = tonumber(mstr(tid, "universal_debris"))
	return debris ~= nil and debris < 0
end

-- [LR DA CO HINH] LR la mau chua phat hanh. Khi game cap nhat va mau LR do da co DU file hinh
-- (icon + spine form dau + hieu ung ky nang) thi coi nhu da phat hanh va cho vao TAT CA TUONG.
-- Khong dung toi 8 the Combo (co luong rieng) va danh sach offline_lr_ban.txt van uu tien cao nhat.
function LS.lr_released(tid)
	tid = tonumber(tid)
	if tid == nil or tid <= 0 then return false end
	tid = math.floor(tid)
	if LS.ban_hit(tid) then return false end
	local cb = LS._cb
	if type(cb) == "table" and type(cb.is_card) == "function" and cb.is_card(tid) then return false end
	local A = LS._art
	if A == nil or A.complete == nil then return false end
	local ok, v = pcall(A.complete, tid)
	if ok and v == true then return true end
	-- [AUTO-UNLOCK] fallback: du file that => da phat hanh
	if A.present ~= nil then
		local ok2, v2 = pcall(A.present, tid)
		return ok2 and v2 == true
	end
	return false
end

function LS.hero_safe(tid)
	tid = tonumber(tid)
	if tid == nil or tid <= 0 then return false end
	tid = math.floor(tid)
	if HERO_BAD[tid] == true then return false end
	if not LS.hero_is_lr(tid) then return true end
	return LS.lr_released(tid)
end

-- Ngoai le rat hep cho Combo Card: chi 8 template co trong comb_mould duoc
-- giu lai. Danh sach LR thu cong (offline_lr_ban.txt) van co uu tien cao hon.
function LS.hero_combo_safe(tid)
	tid = tonumber(tid)
	if tid == nil or tid <= 0 then return false end
	tid = math.floor(tid)
	if HERO_BAD[tid] == true or LS.ban_hit(tid) then return false end
	local cb = LS._cb
	return type(cb) == "table" and type(cb.is_card) == "function" and cb.is_card(tid)
end

function LS.hero_ids()
	if R.hero_ids ~= nil then return R.hero_ids end
	local list = {}
	if sm_ok() then
		local ids = {}
		for k in pairs(G("dms")["ship_mould"]) do
			local id = tonumber(k)
			if id ~= nil then ids[#ids + 1] = id end
		end
		table.sort(ids)
		local flagged = false
		for i = 1, #ids do
			if mnum(ids[i], "can_recruit", 0) > 0 then flagged = true; break end
		end
		for i = 1, #ids do
			local id = ids[i]
			local ct = mnum(id, "captain_type", 0)
			-- [NHAN VAT MAU] mau arena_init = 1 truoc day bi loai han; nay chi giu lai neu co DU hinh (icon + spine)
			local sample_ok = mnum(id, "arena_init", 0) ~= 1
			if not sample_ok and LS._art ~= nil and LS._art.complete ~= nil then
				local okc, vc = pcall(LS._art.complete, id)
				sample_ok = okc and vc == true
			end
			if ct ~= 0 and ct ~= 2 and ct ~= 3 and mnum(id, "base_mould", -1) == id
				and sample_ok
				and (not flagged or mnum(id, "can_recruit", 0) > 0)
				and LS.hero_safe(id) then
				list[#list + 1] = id
			end
		end
	end
	if LS.art_filter ~= nil then
		local okf, fl = pcall(LS.art_filter, list)
		if okf and type(fl) == "table" then list = fl end
	end
	-- Neu ship_config chua nap xong thi khong cache danh sach tam thoi,
	-- de lan sau ap dung duoc bo loc LR thay vi giu nham tuong LR.
	if not R.art_pending and not R.sp_card_pending then R.hero_ids = list end
	return list
end

local function cfg_str(tbl, row)
	local d, sc = G("dms"), G(tbl)
	if type(d) ~= "table" or type(sc) ~= "table" or type(d[tbl]) ~= "table" or sc.param == nil then return nil end
	local ok, v = pcall(d.string, d[tbl], row, sc.param)
	if not ok or v == nil or v == "" then return nil end
	return v
end

local function cfg_list(tbl, row)
	local t = {}
	local s = cfg_str(tbl, row)
	if s == nil then return t end
	for w in string.gmatch(s, "[^,|]+") do
		local n = tonumber(w)
		if n ~= nil then t[#t + 1] = n end
	end
	return t
end

local function cfg_pairs(tbl, row)
	local s = cfg_str(tbl, row)
	if s == nil then return nil end
	local t, n = {}, 0
	for a, b in string.gmatch(s, "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		t[tonumber(a)] = tonumber(b)
		n = n + 1
	end
	if n == 0 then return nil end
	return t
end

local function rnd(x) return math.floor(x + 0.5) end

local STAT_COLS = {
	{ "initial_power", "grow_power" }, { "initial_courage", "grow_courage" },
	{ "initial_intellect", "grow_intellect" }, { "initial_nimable", "grow_nimable" },
}

local function eng_base(tid, grade)
	local lv0 = mnum(tid, "initial_level", 1)
	local out = {}
	for i = 1, 4 do
		local c = STAT_COLS[i]
		out[i] = mnum(tid, c[1], 0) + rnd(mnum(tid, c[2], 0)) * (grade - lv0)
	end
	return out
end

local RANK_PCT, STAR_PCT = 0.025, 0.06

local function factor(order, star)
	local rp = tn(S ~= nil and S.cfg.rank_pct or nil, RANK_PCT)
	local sp = tn(S ~= nil and S.cfg.star_pct or nil, STAR_PCT)
	if star < 1 then star = 1 end
	return (1 + rp * order) * (1 + sp * (star - 1))
end

local K_DEFAULT = { 1, 1, 1, 1 }

local function get_k()
	local k = S ~= nil and S.cfg.k or nil
	if type(k) == "table" and tonumber(k[1]) ~= nil and tonumber(k[2]) ~= nil
		and tonumber(k[3]) ~= nil and tonumber(k[4]) ~= nil then
		return k
	end
	return K_DEFAULT
end

local function get_mult()
	local m = tn(S ~= nil and S.cfg.mult or nil, 1)
	if m <= 0 then m = 1 end
	return m
end

local function panel_ls(tid, grade, order, star)
	local b = eng_base(tid, grade)
	local k = get_k()
	local f = factor(order, star) * get_mult()
	local out = {}
	for i = 1, 4 do out[i] = math.max(0, rnd(b[i] * tn(k[i], 1) * f)) end
	return out
end

local function lookup_le(t, k)
	local v = t[k]
	if v ~= nil then return v end
	local best = nil
	for kk in pairs(t) do
		if kk <= k and (best == nil or kk > best) then best = kk end
	end
	if best == nil then return nil end
	return t[best]
end

local function speed_model(order, star)
	if R.spd_rank == nil then
		R.spd_rank = cfg_pairs("ship_config", 11) or false
		R.spd_star = cfg_pairs("ship_config", 12) or false
	end
	if not R.spd_rank or not R.spd_star then return nil end
	local a, b = lookup_le(R.spd_rank, order), lookup_le(R.spd_star, star)
	if a == nil or b == nil then return nil end
	return a + b
end

local function calc_fight(tid, hp, atk, def, skill, star)
	local f = G("calPowerForNotOwn")
	if type(f) == "function" then
		local okf, v = pcall(f, {
			ship_template_id = tid, ship_base_courage = atk, ship_base_intellect = def,
			ship_base_health = hp, skillLevel = skill, StarRating = fint(star) })
		if okf and tonumber(v) ~= nil then return tonumber(v) end
	end
	return math.ceil((atk + def) * 0.425 + hp * 0.085)
end

local function grade_for(tid)
	local init = mnum(tid, "initial_level", 1)
	local g = tn(S.cfg.grant_grade, 0)
	if g > 0 then return math.max(init, math.floor(g)) end
	local e = ED()
	local pl = e and type(e.user_info) == "table" and tonumber(e.user_info.user_grade) or nil
	if pl ~= nil and pl > 0 then return math.max(init, math.floor(pl)) end
	return init
end

local function exp_need(tid, grade)
	local d = G("dms")
	local ab = mnum(tid, "ability", 13)
	if type(d["ship_experience_param"]) == "table" then
		local col = ab - 13 + 3
		if col < 3 or col > 10 then col = 3 end
		local okx, v = pcall(d.int, d["ship_experience_param"], grade + 1, col)
		if okx and v ~= nil then return v end
	end
	return 0
end

local EQ = {}
local WS = {}

local FIELD_LIST = { "ship_grade", "exprience", "grade_need_exprience", "ship_health", "ship_courage",
	"ship_intellect", "ship_quick", "ship_base_health", "ship_base_courage", "ship_base_intellect",
	"ship_wisdom", "hero_fight", "Order", "StarRating", "skillLevel", "equipInfo", "property_values", "ship_fighting_spirit", "qianNeng" }

local function spec_val(orig, ty)
	for part in string.gmatch(tostring(orig or ""), "[^|]+") do
		local t, v = string.match(part, "^%s*(%-?%d+)%s*:%s*(%-?[%d%.]+)")
		if tonumber(t) == ty then return tonumber(v) or 0 end
	end
	return 0
end

local function spec_has(orig, ty)
	for part in string.gmatch(tostring(orig or ""), "[^|]+") do
		local t = string.match(part, "^%s*(%-?%d+)%s*:")
		if tonumber(t) == ty then return true end
	end
	return false
end

-- Gop spec cua trang bi vao property_values ma khong cong doi:
-- - property_values goc da co type do -> chi cong phan thay doi (delta).
-- - property_values goc chua co (hoac dang 0) -> cong gia tri tuyet doi hien tai.
local function merge_spec(dw, dq, abs, orig, base_only)
	if base_only then
		for ty, v in pairs(dw) do dw[ty] = math.max(0, spec_val(orig, ty) + v) end
	end
	for ty, v in pairs(dq or {}) do
		if spec_has(orig, ty) then
			if base_only then dw[ty] = math.max(0, (dw[ty] or spec_val(orig, ty)) + v)
			else dw[ty] = (dw[ty] or 0) + v end
		end
	end
	for ty, v in pairs(abs or {}) do
		local cur = base_only and (dw[ty] or spec_val(orig, ty)) or (spec_val(orig, ty) + (dw[ty] or 0))
		if cur < v then
			if base_only then dw[ty] = v
			else dw[ty] = (dw[ty] or 0) + (v - cur) end
		end
	end
end

-- No tu amulet (type 20/41) phai la gia tri TUYET DOI trong property_values.
-- AM.delta chi tra phan chenh lech so voi luc nap game, nen neu ban luu cu da
-- lam mat no (property_values thieu type 20) thi delta = 0 -> vao tran 0 no.
-- Ham nay keo gia tri len muc AM.contrib() (tong dang mac) + spec trang bi.
local function am_floor(dw, abs, orig, sid, base_only)
	if LS._am == nil or LS._am.contrib == nil then return end
	local ok, c = pcall(LS._am.contrib, sid)
	if not ok or type(c) ~= "table" or type(c.spec) ~= "table" then return end
	for ty, v in pairs(c.spec) do
		local floor = v + ((abs and abs[ty]) or 0)
		local cur = base_only and (dw[ty] or spec_val(orig, ty)) or (spec_val(orig, ty) + (dw[ty] or 0))
		if cur < floor then
			if base_only then dw[ty] = floor
			else dw[ty] = (dw[ty] or 0) + (floor - cur) end
		end
	end
end

local function build_ship(id, tid, ov)
	ov = ov or {}
	local sid = fint(id)
	local grade = tn(ov.ship_grade, nil) or grade_for(tid)
	local order = math.floor(tn(ov.Order, nil) or mnum(tid, "initial_rank_level", 0))
	local star = math.floor(tn(ov.StarRating, nil) or mnum(tid, "ship_star", 1))
	local skill = ov.skillLevel or "1,1,1,1,1,1"
	local pn = panel_ls(tid, grade, order, star)
	local equip_info = ov.equipInfo or EQ.default_info(tid)
	local dq = EQ.delta_ls(sid, tid, equip_info)
	local dw = WS.delta(sid)
	local dm = WS.mega_delta(sid, tid)
	local dpt = WS.pot_delta(ov.qianNeng or "1,1,1", "1,1,1")
	for ty, v in pairs(dpt.spec) do dw.spec[ty] = (dw.spec[ty] or 0) + v end
	for i = 1, 4 do dq[i] = dq[i] + dw[i] + dm[i] + dpt[i] end
	local q = S ~= nil and S.eq or nil
	local hard = q and q.hard and q.hard[tostring(sid)] or nil
	local abs = EQ.stats(equip_info, tid, hard).spec
	for ty, v in pairs(abs or {}) do dw.spec[ty] = (dw.spec[ty] or 0) + v end
	am_floor(dw.spec, abs, "8:0", sid)
	EQ.adjust(pn, dq)
	if LS._tl ~= nil then LS._tl.adjust(sid, tid, pn, dw.spec, false) end
	if LS._af ~= nil then LS._af.adjust(sid, tid, pn, dw.spec, false) end
	if LS._sp ~= nil then LS._sp.adjust(sid, tid, pn, dw.spec, false) end
	if LS._cb ~= nil then LS._cb.adjust(sid, tid, pn, dw.spec, false) end
	if LS._ic ~= nil then LS._ic.adjust(sid, tid, pn, dw.spec, false) end
	if LS._cs ~= nil then LS._cs.adjust(sid, tid, pn, dw.spec, false) end
	if LS._sg ~= nil then LS._sg.adjust(sid, tid, pn, dw.spec, false) end
	if LS._hs ~= nil then LS._hs.adjust(sid, tid, pn, dw.spec, false) end
	if LS._ma ~= nil then LS._ma.adjust(sid, tid, pn, dw.spec, false) end
	local health, courage, intellect, quick = pn[1], pn[2], pn[3], pn[4]
	local spd = speed_model(order, star)
	if spd ~= nil and LS._sp ~= nil then spd = spd + LS._sp.speed(sid, tid) end
	local evo = math.max(1, math.floor(mnum(tid, "captain_name", 1)))

	local faction = mstr(tid, "faction_id") or ""
	local nfac = 0
	for _ in string.gmatch(faction, "[^,]+") do nfac = nfac + 1 end
	if nfac < 4 then nfac = 4 end
	local spirit = {}
	for i = 1, nfac do spirit[i] = "1,0" end

	local s = {
		ship_id = sid,
		ship_template_id = fint(tid),
		ship_base_template_id = mstr(tid, "base_mould") or fint(tid),
		ship_place = "0",
		captain_type = mstr(tid, "captain_type") or "1",
		shipSpirit = "",
		ship_fighting_spirit = ov.ship_fighting_spirit or table.concat(spirit, "|"),
		ship_skin_info = "",
		ship_type = mstr(tid, "ship_type") or "1",
		captain_name = mstr(tid, "captain_name") or "1",
		ship_name = mstr(tid, "ship_name") or "",
		ship_grade = fint(grade),
		ship_base_health = fint(health),
		ship_base_courage = fint(courage),
		ship_base_intellect = fint(intellect),
		ship_health = health,
		ship_courage = courage,
		ship_intellect = intellect,
		ship_quick = fint(quick),
		initial_sp_increase = 0,
		property_values = WS.prop_values("8:0", dw.spec),
		ship_picture = mstr(tid, "ship_pic") or "0",
		ship_leader = "0",
		ship_force = "0",
		ship_wisdom = (spd ~= nil) and fint(spd) or (mstr(tid, "wisdom") or "0"),
		health_growup_type = "0", courage_grade_type = "0",
		intellect_grade_type = "0", quick_grade_type = "0",
		skill_mould = mstr(tid, "skill_mould") or "0",
		skill_name = mstr(tid, "skill_name") or "",
		skill_describe = mstr(tid, "skill_describe") or "",
		deadly_skill_mould = mstr(tid, "deadly_skill_mould") or "0",
		deadly_skill_name = "", deadly_skill_describe = "",
		exprience = "0",
		grade_need_exprience = fint(exp_need(tid, grade)),
		train = "0", train_endtime = "0", ship_growup_exprience = "0",
		cart_describe = "",

		evolution_status = evo .. "|" .. "2," .. ((evo - 1) * 2) .. ",0,0",
		skillLevel = skill,
		StarRating = fint(star),
		Order = fint(order),
		equipInfo = equip_info,
		hardensInfo = EQ.hard_default_tbl(),
		qianNeng = "1,1,1",
		alloyMatrix = { mmi = {}, ma = {}, mr = {} },
		awakenLevel = 0, awakenstates = "0,0,0,0", combLockState = "0", combUpLockState = "0",
		relationship_count = "0", relationship = {},
		talent_count = "0", talents = {},
		ship_train_info = {
			train_life = "0", train_life_temp = "0", train_attack = "0", train_attack_temp = "0",
			train_physical_defence = "0", train_physical_defence_temp = "0",
			train_skill_defence = "0", train_skill_defence_temp = "0",
		},
		ship_skillstren = { skill_level = "1", skill_value = "0" },
		equipment = {},
	}
	for i = 1, 8 do s.equipment[i] = { ship_id = "0" } end

	s.hero_fight = fint(calc_fight(tid, health, courage, intellect, skill, star))

	local aes = G("aeslua")
	if type(aes) == "table" and aes.encrypt ~= nil then
		local okc, enc = pcall(aes.encrypt, "jar-world",
			s.ship_health .. s.ship_wisdom .. s.ship_leader .. s.ship_courage .. s.ship_intellect .. s.ship_quick,
			aes.AES128, aes.ECBMODE)
		if okc then s.history_info = enc end
	end

	for k, v in pairs(ov) do
		if k ~= "ship_grade" and type(v) ~= "table" then s[k] = v end
	end
	return s
end

local function count_ships(e)
	local n = 0
	for _ in pairs(e.user_ship) do n = n + 1 end
	return n
end

local function next_free_id(e)
	local id = tn(S.next_id, 0)
	if id < 100000 then id = 100000 end
	if not R.max_checked then
		for k in pairs(e.user_ship) do
			local n = tonumber(k)
			if n ~= nil and n > id then id = n end
		end
		R.max_checked = true
	end
	id = id + 1
	while e.user_ship[fint(id)] ~= nil do id = id + 1 end
	S.next_id = id
	return id
end

-- Combo Card chi duoc phep tao dung mau tuong ma bang comb_mould yeu cau.
-- Dieu nay giu bo loc LR cho nut "TAT CA TUONG", nhung khong lam 8 tuong
-- Combo Card (deu co universal_debris = -1) bi an va khong the mo the.
function LS.create_hero(tid, ov, combo_card)
	local e = ED()
	if e == nil or type(e.user_ship) ~= "table" then error("chua vao game (khong co _ED.user_ship)") end
	local combo_ok = combo_card == true and LS.hero_combo_safe(tid)
	if not LS.hero_safe(tid) and not combo_ok then error("mau tuong da nam trong danh sach loi") end
	local id = next_free_id(e)
	ov = ov or {}
	if ov.ship_grade == nil then ov.ship_grade = grade_for(tid) end
	local s = build_ship(id, tid, ov)
	local sid = s.ship_id
	S.heroes[sid] = { tid = tid, ov = ov }
	S.order[#S.order + 1] = sid
	e.user_ship[sid] = s
	e.user_ship_number = count_ships(e)
	if R.owned ~= nil then R.owned[tid] = true end
	if LS._mega_ensure ~= nil then LS._mega_ensure(e) end
	mark()
	return s
end

local function owned_set(e)
	local set = {}
	for _, v in pairs(e.user_ship) do
		local t = tonumber(v.ship_template_id)
		if t ~= nil then set[t] = true end
	end
	-- [FIX nhan ban tuong] Tuong LS da luu (S.heroes) cung tinh la "da co" ke ca khi chua duoc nap lai vao
	-- e.user_ship (inject dang chay dan / build loi). Truoc day thieu buoc nay nen TAT CA TUONG cap them ban sao.
	if S ~= nil and type(S.heroes) == "table" then
		for _, rec in pairs(S.heroes) do
			local t = type(rec) == "table" and tonumber(rec.tid) or nil
			if t ~= nil then set[t] = true end
		end
	end
	return set
end

local function read_formation(e)
	local f = {}
	for i = 1, 6 do
		local v = e.formetion and e.formetion[i + 1]
		if v == nil or v == "" then v = "0" end
		f[i] = tostring(v)
	end
	return f
end

local function write_formation(e, f)
	if type(e.formetion) ~= "table" then e.formetion = {} end
	if e.formetion[1] == nil then e.formetion[1] = "1" end

	for k, v in pairs(e.user_ship) do
		if v.formation_index ~= nil and tn(v.formation_index, 0) > 0 then
			local keep = false
			for i = 1, 6 do if f[i] == k then keep = true end end
			if not keep then v.formation_index = "0" end
		end
	end
	local st = {}
	for i = 1, 6 do
		e.formetion[i + 1] = f[i]
		st[i] = f[i]
		local s = e.user_ship[f[i]]
		if s ~= nil then s.formation_index = fint(i) end
	end
	e.user_formetion_status = st
	if LS._cb ~= nil and LS._cb.push_ed ~= nil then pcall(LS._cb.push_ed, e) end
end

local function formation_ok(e, f)
	for i = 1, 6 do
		if f[i] ~= "0" and e.user_ship[f[i]] == nil then return false end
	end
	return true
end

-- [FIX log] O doi hinh tro toi tuong KHONG con trong e.user_ship (tuong bi go khi loc file hong,
-- bi GM xoa, hoac ban ghi cu) => man hinh doi hinh bao "attempt to index ... 'ship' (a nil value)"
-- (Lformation_change_hero_cell:367, EnvironmentDatas:9639). Nhung o nay duoc dua ve "0" (o trong).
-- Tra ve so o da sua. Chi dung khi khong dang cap/nap tuong (xem LS.sync).
local function repair_formation(e)
	if type(e) ~= "table" or type(e.user_ship) ~= "table" then return 0 end
	local n = 0
	local function gone(v)
		if v == nil then return false end
		local sv = tostring(v)
		return sv ~= "0" and sv ~= "" and type(e.user_ship[sv]) ~= "table"
	end
	if type(e.formetion) == "table" then
		for i = 2, 7 do
			if gone(e.formetion[i]) then e.formetion[i] = "0"; n = n + 1 end
		end
	end
	if type(e.user_formetion_status) == "table" then
		for i = 1, 6 do
			if gone(e.user_formetion_status[i]) then e.user_formetion_status[i] = "0"; n = n + 1 end
		end
	end
	if S ~= nil and type(S.formation) == "table" then
		local sn = 0
		for i = 1, 6 do
			if gone(S.formation[i]) then S.formation[i] = "0"; sn = sn + 1 end
		end
		if sn > 0 then n = n + sn end
	end
	if n > 0 then
		R.form_repaired = (R.form_repaired or 0) + n
		if R.form_repaired <= 20 then log("doi hinh: go", n, "o tro toi tuong khong con") end
		mark()
	end
	return n
end
LS._repair_formation = repair_formation

local function apply_saved_formation(e)
	if S.formation == nil then return true end
	if not formation_ok(e, S.formation) then
		-- Dang nap/cap tuong: cho. Xong ma van thieu => tuong do da bi go, bo o do (khong ket "formation_pending" mai).
		if R.inject ~= nil or R.grant ~= nil then return false end
		repair_formation(e)
		if not formation_ok(e, S.formation) then return false end
	end
	write_formation(e, S.formation)
	return true
end

local function reply(seq, name, blocks)
	local t = { tostring(seq), name, "0" }
	for i = 1, #blocks do t[#t + 1] = blocks[i] end
	return table.concat(t, "\r\n")
end

local ERR = {
	generic = 1,
	silver = 46,
	items = 74,
	rank_max = 86,
	level_cap = 253,
	star = 303,
	skill_points = 473,
	skill_cap = 594,
	hero_level = 542,
	attempts = 533,
	equip_missing = 42,
	equip_level = 44,
	equip_max = 45,
	star_locked = 554,
	star_max = 555,
	star_frag = 556,
}

local function err_reply(seq, name, msg, code)
	code = math.floor(tn(code, ERR.generic))
	if code < 1 then code = ERR.generic end
	return tostring(seq) .. "\r\n" .. name .. "\r\n-" .. fint(code) .. "\r\n" .. (msg or "LS_loi")
end

local function parse_req(req)
	local t = {}
	local init = 1
	req = tostring(req or "")
	while true do
		local p = string.find(req, "\r\n", init, true)
		if p == nil then
			t[#t + 1] = string.sub(req, init)
			break
		end
		t[#t + 1] = string.sub(req, init, p - 1)
		init = p + 2
	end
	return t
end

local function h_formation(p, seq)
	local e = ED()
	local sid = tostring(p[1] or "")
	local pos = tn(p[2], 0)
	local mode = tostring(p[3] or "1")
	local ship = e.user_ship[sid]
	if ship == nil then return err_reply(seq, "formation_change", "LS_khong_co_tuong") end
	if pos < 1 or pos > 6 or pos ~= math.floor(pos) then
		return err_reply(seq, "formation_change", "LS_vi_tri_sai")
	end
	local f = read_formation(e)
	local cur = 0
	for i = 1, 6 do if f[i] == sid then cur = i end end

	local blocks
	if mode == "-1" then

		if cur == 0 then return reply(seq, "formation_change", { "56", "0", "0", "0", "0" }) end
		if tostring(ship.captain_type) == "0" then
			return err_reply(seq, "formation_change", "LS_khong_the_xuong_nhan_vat_chinh")
		end
		f[cur] = "0"
		blocks = { "56", "0", "0", "0", "0" }
	else
		local occ = f[pos]
		if occ == sid then
			return reply(seq, "formation_change", { "56", sid, fint(pos), "0", "0" })
		end
		if cur > 0 then

			f[cur] = occ
			f[pos] = sid
			if occ ~= "0" then
				blocks = { "56", sid, fint(pos), occ, fint(cur) }
			else
				blocks = { "56", sid, fint(pos), "0", "0" }
			end
		else

			local occship = e.user_ship[occ]
			if occship ~= nil and tostring(occship.captain_type) == "0" then
				return err_reply(seq, "formation_change", "LS_khong_the_thay_nhan_vat_chinh")
			end
			f[pos] = sid
			if occship ~= nil then occship.formation_index = "0" end
			blocks = { "56", sid, fint(pos), "0", "0" }
		end
	end
	S.formation = f
	write_formation(e, f)
	mark()
	stat_inc("formation_change")
	blocks[#blocks + 1] = "188"
	blocks[#blocks + 1] = table.concat(f, ",")
	return reply(seq, "formation_change", blocks)
end

local DEFAULT_WEIGHTS = { [12] = 30, [13] = 45, [14] = 28, [15] = 12, [16] = 4, [17] = 1, default = 10 }

local function recruit_pool()
	if R.pool ~= nil then return R.pool end
	local items, total = {}, 0
	local W = S.cfg.weights
	if type(W) ~= "table" then W = DEFAULT_WEIGHTS end
	local ids = LS.hero_ids()
	for i = 1, #ids do
		local tid = ids[i]
		local ab = mnum(tid, "ability", 13)
		local w = tn(W[ab], tn(W.default, 10))
		if w > 0 then
			total = total + w
			items[#items + 1] = { tid = tid, cum = total }
		end
	end
	R.pool = { items = items, total = total }
	return R.pool
end

local function pick_hero()
	local pool = recruit_pool()
	if #pool.items == 0 then return nil end
	local r = math.random() * pool.total
	local lo, hi = 1, #pool.items
	while lo < hi do
		local mid = math.floor((lo + hi) / 2)
		if pool.items[mid].cum >= r then hi = mid else lo = mid + 1 end
	end
	return pool.items[lo].tid
end

local function play_cfg(row)
	local d, pc = G("dms"), G("play_config")
	if type(d) ~= "table" or type(pc) ~= "table" or type(d["play_config"]) ~= "table" then return nil end
	local col = pc.param
	local ac = G("activity_config")
	if row == 255 and type(ac) == "table" and ac.param ~= nil then col = ac.param end
	if col == nil then return nil end
	return d.string(d["play_config"], row, col)
end

local function split2(s, dflt1, dflt2)
	local a, b = string.match(tostring(s or ""), "^%s*([%-%d%.]+)%s*,%s*([%-%d%.]+)")
	return tn(a, dflt1), tn(b, dflt2)
end

local function daily_free()
	local day = os.date("%Y%m%d")
	if S.free_day ~= day then
		S.free_day = day
		if tn(S.free, 0) < 1 then S.free = 1 end
		mark()
	end
end

local function ensure_recruit_info(e)
	local ri = e.newRecruitInfo
	if type(ri) ~= "table" then ri = {}; e.newRecruitInfo = ri end
	local have_rec = (type(ri.recuritInfo) == "table")
	if S.draws == nil and have_rec then S.draws = tn(ri.cur_draw_times, 0); mark() end
	if S.free == nil and have_rec then S.free = tn(ri.free_times, 0); mark() end
	if S.free ~= nil then daily_free() end
	if S.draws ~= nil then
		ri.cur_draw_times = S.draws
		if have_rec then ri.recuritInfo.totalDraw = S.draws end
	end
	if S.free ~= nil then
		ri.free_times = S.free
		if have_rec then ri.recuritInfo.totalFreeDraw = S.free end
	end
	return ri
end

AFTER_HOOK[15005] = function()
	local e = ED()
	if e ~= nil then ensure_recruit_info(e) end
end

local function decide_cost(e, times)
	if times == 1 and tn(S.free, 0) > 0 then return { kind = "free" } end
	local d1, d10 = split2(play_cfg(257), 300, 2700)
	local t1, t10 = split2(play_cfg(258), 1, 10)
	local propid = tonumber(string.match(tostring(play_cfg(255) or ""), ",%s*(%d+)"))
	local need_t = (times == 1) and t1 or t10
	local need_d = (times == 1) and d1 or d10
	if propid ~= nil and LS.prop_get(propid) >= need_t then
		return { kind = "prop", tmpl = propid, n = need_t }
	end
	if S.gold ~= nil and S.gold >= need_d then
		return { kind = "gold", n = need_d }
	end
	return nil
end

local function apply_cost(cost)
	if cost.kind == "free" then
		S.free = tn(S.free, 0) - 1
		mark()
	elseif cost.kind == "prop" then
		LS.prop_add(cost.tmpl, -cost.n)
	elseif cost.kind == "gold" then
		LS.money_spend("gold", cost.n)
	end
end

local function h_recruit(p, seq)
	local e = ED()
	local times = 1
	if tn(p[1], 1) >= 10 then times = 10 end
	if not sm_ok() then return err_reply(seq, "new_recruitment_system", "LS_chua_nap_bang_tuong") end
	local ri = ensure_recruit_info(e)
	if S.free == nil then S.free = 0 end
	daily_free()
	local cost = decide_cost(e, times)
	if cost == nil then
		toast("KC khong du de quay. Mo bang GM (nut GM) -> BU TIEN.", 6)
		return err_reply(seq, "new_recruitment_system", "Khong_du_KC", ERR.generic)
	end
	local picks = {}
	for i = 1, times do
		picks[i] = pick_hero()
		if picks[i] == nil then return err_reply(seq, "new_recruitment_system", "LS_pool_rong") end
	end
	apply_cost(cost)

	local made = {}
	for i = 1, times do
		local ok, s = pcall(LS.create_hero, picks[i])
		if not ok then
			log("loi tao tuong", picks[i], tostring(s))
			made[i] = nil
		else
			made[i] = s
			-- ban sao do nguoi choi tu quay: danh dau de bo loc ban sao tu dong khong xoa
			if type(s) == "table" and S.heroes[tostring(s.ship_id)] ~= nil then S.heroes[tostring(s.ship_id)].keep = true end
		end
	end

	S.draws = tn(S.draws, 0) + times
	stat_inc("pulls", times)
	ri.cur_draw_times = S.draws
	ri.free_times = tn(S.free, 0)
	if type(ri.recuritInfo) == "table" then
		ri.recuritInfo.totalDraw = S.draws
		ri.recuritInfo.totalFreeDraw = ri.free_times
	end
	mark()

	if type(e.random_Patch) ~= "table" then e.random_Patch = {} end
	if times == 1 and made[1] ~= nil then
		e.recruit_success_ship_id = made[1].ship_id
	end

	local blocks = { "171", "90", fint(times) }
	local reward = {}
	for i = 1, times do
		local tid = picks[i]
		blocks[#blocks + 1] = fint(tid)
		blocks[#blocks + 1] = "13"
		blocks[#blocks + 1] = "1"
		reward[i] = "13," .. fint(tid) .. ",1," .. fint(mnum(tid, "ship_star", 1))
	end
	blocks[#blocks + 1] = "15004"
	blocks[#blocks + 1] = '{"rewardInfo":{"totalRewardStr":"' .. table.concat(reward, "|") .. '"}}'
	blocks[#blocks + 1] = "15006"
	blocks[#blocks + 1] = "-1"
	LS.save_state(true)
	log("quay", times, "lan bang", cost.kind, "->", table.concat(picks, ","))
	return reply(seq, "new_recruitment_system", blocks)
end

local function jenc(v)
	local t = type(v)
	if t == "number" then
		if v ~= v or v == math.huge or v == -math.huge then return "0" end
		if v == math.floor(v) then return string.format("%.0f", v) end
		return string.format("%.14g", v)
	elseif t == "boolean" then
		return v and "true" or "false"
	elseif t == "string" then
		local out = string.gsub(v, '[%c"\\ ]', function(c)
			if c == '"' then return '\\"' end
			if c == "\\" then return "\\\\" end
			return string.format("\\u%04x", string.byte(c))
		end)
		return '"' .. out .. '"'
	elseif t == "table" then
		local n, cnt = #v, 0
		for _ in pairs(v) do cnt = cnt + 1 end
		if cnt == 0 then return "[]" end
		local parts = {}
		if n == cnt then
			for i = 1, n do parts[i] = jenc(v[i]) end
			return "[" .. table.concat(parts, ",") .. "]"
		end
		local keys = {}
		for k in pairs(v) do keys[#keys + 1] = k end
		table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
		for i = 1, #keys do parts[i] = jenc(tostring(keys[i])) .. ":" .. jenc(v[keys[i]]) end
		return "{" .. table.concat(parts, ",") .. "}"
	end
	return "null"
end

local function call_parser(fname, tokens)
	local pf = G(fname)
	if type(pf) ~= "function" then return false end
	local saved = rawget(_G, "pos")
	tokens.pos = 1
	local ok, err = pcall(pf, nil, nil, nil, nil, tokens, nil)
	rawset(_G, "pos", saved)
	if not ok then
		log("parser", fname, "loi:", tostring(err))
		return false
	end
	return true
end

local PROP_ID_BASE = 700000000

-- [FIX lag 13] pkey duoc goi cho TUNG phan tu e.user_prop trong prop_total / prop_index / ... (hang nghin lan moi
-- thao tac, moi lan tonumber + string.format => hang nghin chuoi rac). Nho ket qua theo gia tri goc (so mau prop it).
local pkey
do
	local MEMO, MEMO_N = {}, 0
	function pkey(tmpl)
		local tt = type(tmpl)
		if tt == "string" or tt == "number" then
			local m = MEMO[tmpl]
			if m ~= nil then
				if m == false then return nil end
				return m
			end
			local n = tonumber(tmpl)
			local r = nil
			if n ~= nil then r = fint(n) end
			if tmpl == tmpl and MEMO_N < 20000 then
				MEMO[tmpl] = r or false
				MEMO_N = MEMO_N + 1
			end
			return r
		end
		local n = tonumber(tmpl)
		if n == nil then return nil end
		return fint(n)
	end
end

local function prop_known(tmpl)
	local d = G("dms")
	local n = tonumber(tmpl)
	return n ~= nil and type(d) == "table" and type(d["prop_mould"]) == "table" and d["prop_mould"][n] ~= nil
end

local function prop_index(e)
	local idx = {}
	if type(e.user_prop) == "table" then
		for id, v in pairs(e.user_prop) do
			if type(v) == "table" then
				local k = pkey(v.user_prop_template)
				if k ~= nil then
					local l = idx[k]
					if l == nil then l = {}; idx[k] = l end
					l[#l + 1] = { id = tostring(id), rec = v }
				end
			end
		end
		for _, l in pairs(idx) do
			table.sort(l, function(a, b) return (tonumber(a.id) or 0) < (tonumber(b.id) or 0) end)
		end
	end
	return idx
end

local function prop_total(e, tmpl)
	local key, n = pkey(tmpl), 0
	if key == nil or type(e.user_prop) ~= "table" then return 0 end
	for _, v in pairs(e.user_prop) do
		if type(v) == "table" and pkey(v.user_prop_template) == key then n = n + (tonumber(v.prop_number) or 0) end
	end
	return n
end

local function prop_first(e, tmpl)
	local list = prop_index(e)[pkey(tmpl) or ""]
	if list ~= nil then return list[1] end
	return nil
end

-- [FIX lag 13] Danh sach cac dong user_prop cua DUNG 1 loai prop (giong prop_index()[key] nhung khong dung chi muc cho
-- tat ca loai + khong sort nhung loai khac). Truoc day moi LS.prop_set dung lai toan bo chi muc => mo Hero Saga (nap
-- ~chuc loai an ky) hay tra phi nhieu thu = dung hinh vai tram ms toi vai giay tren dien thoai.
function LS._prop_list_for(e, key)
	local list
	if type(e.user_prop) == "table" then
		for id, v in pairs(e.user_prop) do
			if type(v) == "table" and pkey(v.user_prop_template) == key then
				if list == nil then list = {} end
				list[#list + 1] = { id = tostring(id), rec = v }
			end
		end
		if list ~= nil and #list > 1 then
			table.sort(list, function(a, b) return (tonumber(a.id) or 0) < (tonumber(b.id) or 0) end)
		end
	end
	return list
end

local function prop_write(e, tmpl, amount, idx)
	local key = pkey(tmpl)
	if key == nil then return false end
	if type(e.user_prop) ~= "table" then e.user_prop = {} end
	local list
	if idx ~= nil then list = idx[key] else list = LS._prop_list_for(e, key) end
	local id
	if list ~= nil and list[1] ~= nil then
		id = list[1].id
		for i = 2, #list do call_parser("parse_user_prop_change_list", { list[i].id, key, "0" }) end
	else
		id = fint(PROP_ID_BASE + tonumber(key))
		local guard = 0
		while e.user_prop[id] ~= nil and guard < 1000 do id = fint(tonumber(id) + 1000000); guard = guard + 1 end
	end
	if prop_known(key) and type(G("parse_user_prop_change_list")) == "function" then
		if call_parser("parse_user_prop_change_list", { id, key, fint(amount) }) then return true end
	end

	if amount <= 0 then
		e.user_prop[id] = nil
	else
		local r = e.user_prop[id] or {}
		r.user_prop_id, r.user_prop_template, r.prop_number = id, key, fint(amount)
		e.user_prop[id] = r
	end
	return true
end

function LS.prop_get(tmpl)
	local key = pkey(tmpl)
	if key == nil then return 0 end
	if S ~= nil and S.props[key] ~= nil then return S.props[key] end
	local e = ED()
	if e == nil then return 0 end
	return prop_total(e, key)
end

function LS.prop_set(tmpl, amount)
	local e, key = ED(), pkey(tmpl)
	if S == nil or e == nil or key == nil then return false end
	amount = math.max(0, math.floor(tn(amount, 0)))
	if R.prop_rec ~= nil and R.prop_rec[key] == nil then R.prop_rec[key] = prop_total(e, key) end
	S.props[key] = amount
	R.prop_dirty = true
	mark()
	prop_write(e, key, amount)
	return true
end

function LS.prop_add(tmpl, delta)
	local cur = LS.prop_get(tmpl)
	if cur + delta < 0 then return false end
	return LS.prop_set(tmpl, cur + delta)
end

function LS.prop_spend_all(list)
	local need = {}
	for i = 1, #list do
		local k = pkey(list[i][1])
		need[k] = (need[k] or 0) + list[i][2]
	end
	for k, n in pairs(need) do
		if LS.prop_get(k) < n then return false end
	end
	for k, n in pairs(need) do LS.prop_set(k, LS.prop_get(k) - n) end
	return true
end

local function prop_assert(e)
	local any = false
	for _ in pairs(S.props) do any = true; break end
	if not any then return end

	if type(e.user_prop) == "table" then
		local pc = R.pk_cache
		if pc == nil then pc = {}; R.pk_cache = pc end
		local tot, cnt = {}, {}
		local props = S.props
		for _, v in pairs(e.user_prop) do
			if type(v) == "table" then
				local t = v.user_prop_template
				local k = nil
				if t ~= nil then
					k = pc[t]
					if k == nil then k = pkey(t) or false; pc[t] = k end
				end
				if k and props[k] ~= nil then
					tot[k] = (tot[k] or 0) + (tonumber(v.prop_number) or 0)
					cnt[k] = (cnt[k] or 0) + 1
				end
			end
		end
		local need = false
		for key, amount in pairs(props) do
			if (tot[key] or 0) ~= amount or (cnt[key] or 0) > 1 then need = true; break end
		end
		if not need then return end
	end
	local idx = prop_index(e)
	for key, amount in pairs(S.props) do
		local list = idx[key]
		local cur = 0
		if list ~= nil then
			for i = 1, #list do cur = cur + (tonumber(list[i].rec.prop_number) or 0) end
		end
		if cur ~= amount or (list ~= nil and #list > 1) then
			prop_write(e, key, amount, idx)
			R.overwrites = (R.overwrites or 0) + 1
		end
	end
end

local function upgrade_items()
	if R.up_items ~= nil then return R.up_items end
	local set, list = {}, {}
	local function add(t)
		local k = pkey(t)
		if k ~= nil and tonumber(k) > 0 and not set[k] and prop_known(k) then set[k] = true; list[#list + 1] = tonumber(k) end
	end
	for _, t in ipairs(cfg_list("ship_config", 1)) do add(t) end
	local d, sg = G("dms"), G("ship_grow_requirement")
	if type(d) == "table" and type(d["ship_grow_requirement"]) == "table" and type(sg) == "table" then
		local mats = {}
		for _, row in ipairs(d["ship_grow_requirement"]) do
			for k = 1, 5 do
				local ok, t = pcall(d.atoi, row, sg.need_prop1 + (k - 1) * 2)
				if ok and t ~= nil and t > 0 then mats[t] = true end
			end
		end
		local ids = {}
		for t in pairs(mats) do ids[#ids + 1] = t end
		table.sort(ids)
		for i = 1, #ids do add(ids[i]) end
	end
	R.up_items = list
	return list
end

function LS.gm_grant_items(n)
	if not LS.ready() then return nil end
	n = math.floor(tn(n, 9999))
	local list = upgrade_items()
	for i = 1, #list do
		LS.prop_set(list[i], math.min(999999, LS.prop_get(list[i]) + n))
	end
	local more = WS.extra_items(list)
	for i = 1, #more do
		LS.prop_set(more[i], math.min(999999, LS.prop_get(more[i]) + n))
	end
	stat_inc("gm_items")
	LS.save_state(true)
	log("GM VAT PHAM: +", n, "cho", #list + #more, "loai")
	return #list + #more, n
end

local function prog_get(sid)
	local h = S.heroes[sid]
	if h ~= nil then return h.ov end
	return S.mods[sid]
end

local function prog_set(sid, fields)
	local h = S.heroes[sid]
	local t
	if h ~= nil then
		if h.ov == nil then h.ov = {} end
		t = h.ov
	else
		t = S.mods[sid]
		if t == nil then t = {}; S.mods[sid] = t end
	end
	for k, v in pairs(fields) do t[k] = v end
	mark()
	return t
end

local function pick_fields(s)
	local F = {}
	for i = 1, #FIELD_LIST do F[FIELD_LIST[i]] = s[FIELD_LIST[i]] end
	return F
end

local function rec_of(s)
	local r = {
		raw = pick_fields(s),
		tid = tonumber(s.ship_template_id), cap_type = tonumber(s.captain_type),
		grade = tonumber(s.ship_grade) or 1, order = tonumber(s.Order) or 0, star = tonumber(s.StarRating) or 1,
		hp = tonumber(s.ship_health), atk = tonumber(s.ship_courage), def = tonumber(s.ship_intellect),
		qk = tonumber(s.ship_quick) or 0, spd = tonumber(s.ship_wisdom) or 0,
		fight = tonumber(s.hero_fight) or 0, skill = tostring(s.skillLevel or "1,1,1,1,1,1"),
		exp = tostring(s.exprience or "0"), need = tostring(s.grade_need_exprience or "0"),
	}
	EQ.rec_init(r, s)
	return r
end

local function snapshot_world(e)
	R.rec = {}
	R.F = {}
	R.hold = {}
	R.touched = {}
	for sid, s in pairs(e.user_ship) do
		if type(s) == "table" and S.heroes[sid] == nil then R.rec[sid] = rec_of(s) end
	end
	R.rec_total = tonumber(e.user_info.fight_capacity)
	R.rec_sp = e.skill_number_info
	R.rec_form = {}
	for i = 2, 7 do
		local v = e.formetion and e.formetion[i]
		if v ~= nil then
			v = tostring(v)
			local r = R.rec[v]
			if r ~= nil then R.rec_form[v] = r.fight end
		end
	end
end

local function ensure_rec(e, sid)
	if S.heroes[sid] ~= nil then return nil end
	if R.rec == nil then R.rec = {} end
	local r = R.rec[sid]
	if r ~= nil then return r end
	local s = e.user_ship[sid]
	if type(s) ~= "table" then return nil end
	r = rec_of(s)
	R.rec[sid] = r
	return r
end

local function median(t)
	table.sort(t)
	local n = #t
	if n == 0 then return nil end
	if n % 2 == 1 then return t[(n + 1) / 2] end
	return (t[n / 2] + t[n / 2 + 1]) / 2
end

function LS.calibrate()
	if S == nil or R.rec == nil then return false end
	local acc = { {}, {}, {}, {} }
	local n = 0
	for _, r in pairs(R.rec) do
		if r.cap_type ~= 0 and r.tid ~= nil and r.hp ~= nil and r.hp > 0 then
			local b = eng_base(r.tid, r.grade)
			local f = factor(r.order, r.star)
			local vals = { r.hp, r.atk, r.def, r.qk }
			local used = false
			for i = 1, 4 do
				if b[i] > 0 and vals[i] ~= nil and vals[i] > 0 then
					acc[i][#acc[i] + 1] = vals[i] / (b[i] * f)
					used = true
				end
			end
			if used then n = n + 1 end
		end
	end
	if n == 0 then return false end
	local k = {}
	for i = 1, 4 do
		local m = median(acc[i])
		if m == nil then m = K_DEFAULT[i] end
		k[i] = math.floor(m * 1000 + 0.5) / 1000
	end
	S.cfg.k = k
	S.cfg.k_n = n
	mark()
	log("hieu chuan K tu", n, "tuong that: hp", k[1], "cong", k[2], "thu", k[3], "phap thu", k[4])
	return true
end

local function hero_fields(e, sid)
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" then return nil end
	local h = S.heroes[sid]
	if h ~= nil then
		return pick_fields(build_ship(tonumber(sid), h.tid, h.ov))
	end
	local rec = ensure_rec(e, sid)
	if rec == nil or rec.tid == nil then return nil end
	local p = S.mods[sid] or {}
	local mult = get_mult()
	local grade = math.floor(tn(p.ship_grade, rec.grade))
	local order = math.floor(tn(p.Order, rec.order))
	local star = math.floor(tn(p.StarRating, rec.star))
	local skill = p.skillLevel or rec.skill
	local bn, br = eng_base(rec.tid, grade), eng_base(rec.tid, rec.grade)
	local fn, fr = factor(order, star), factor(rec.order, rec.star)
	local rv = { rec.hp or 0, rec.atk or 0, rec.def or 0, rec.qk or 0 }
	local pn = {}
	for i = 1, 4 do
		local denom = br[i] * fr
		if denom > 0 then
			pn[i] = rnd(rv[i] / denom * bn[i] * fn * mult)
		else
			pn[i] = rnd(rv[i] * mult)
		end
	end
	local cur_info = p.equipInfo or rec.eq_info or ""
	local dq = EQ.delta_real(sid, rec, cur_info)
	local dw = WS.delta(sid)
	local dm = WS.mega_delta(sid, rec.tid)
	local dpt = WS.pot_delta(p.qianNeng or rec.raw.qianNeng, rec.raw.qianNeng)
	for ty, v in pairs(dpt.spec) do dw.spec[ty] = (dw.spec[ty] or 0) + v end
	for i = 1, 4 do dq[i] = dq[i] + dw[i] + dm[i] + dpt[i] end
	local q = S ~= nil and S.eq or nil
	local hard = (q and q.hard and q.hard[tostring(sid)]) or rec.hard
	local abs = EQ.stats(cur_info ~= "" and cur_info or rec.eq_info or "", rec.tid, hard).spec
	merge_spec(dw.spec, dq.spec, abs, rec.raw.property_values, true)
	am_floor(dw.spec, abs, rec.raw.property_values, sid, true)
	EQ.adjust(pn, dq)
	if LS._tl ~= nil then LS._tl.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._af ~= nil then LS._af.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._sp ~= nil then LS._sp.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._cb ~= nil then LS._cb.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._ic ~= nil then LS._ic.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._cs ~= nil then LS._cs.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._sg ~= nil then LS._sg.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._hs ~= nil then LS._hs.adjust(sid, rec.tid, pn, dw.spec, true) end
	if LS._ma ~= nil then LS._ma.adjust(sid, rec.tid, pn, dw.spec, true) end
	local spd = rec.spd
	local s_new, s_old = speed_model(order, star), speed_model(rec.order, rec.star)
	if s_new ~= nil and s_old ~= nil then spd = rec.spd + (s_new - s_old) end
	if spd ~= nil and LS._sp ~= nil then spd = spd + LS._sp.speed(sid, rec.tid) end
	local cf_new = calc_fight(rec.tid, pn[1], pn[2], pn[3], skill, star)
	local cf_old = calc_fight(rec.tid, rec.hp or 0, rec.atk or 0, rec.def or 0, rec.skill, rec.star)
	local fight
	if cf_old > 0 and rec.fight > 0 then fight = rnd(rec.fight * cf_new / cf_old) else fight = cf_new end
	local need = p.grade_need_exprience
	if need == nil then
		if grade == rec.grade then need = rec.need else need = fint(exp_need(rec.tid, grade)) end
	end
	return {
		ship_grade = fint(grade), exprience = tostring(p.exprience or rec.exp), grade_need_exprience = tostring(need),
		ship_health = pn[1], ship_courage = pn[2], ship_intellect = pn[3], ship_quick = fint(pn[4]),
		ship_base_health = fint(pn[1]), ship_base_courage = fint(pn[2]), ship_base_intellect = fint(pn[3]),
		ship_wisdom = fint(spd), hero_fight = fint(fight),
		Order = fint(order), StarRating = fint(star), skillLevel = skill,
		equipInfo = (cur_info ~= "") and cur_info or nil,
		property_values = WS.prop_values(rec.raw.property_values, dw.spec, true),
		ship_fighting_spirit = p.ship_fighting_spirit,
		qianNeng = p.qianNeng,
	}
end

local function apply_fields(ship, F)
	for k, v in pairs(F) do ship[k] = v end
	local aes = G("aeslua")
	if type(aes) == "table" and aes.encrypt ~= nil then
		local okc, enc = pcall(aes.encrypt, "jar-world",
			tostring(ship.ship_health) .. tostring(ship.ship_wisdom) .. tostring(ship.ship_leader or "0")
			.. tostring(ship.ship_courage) .. tostring(ship.ship_intellect) .. tostring(ship.ship_quick),
			aes.AES128, aes.ECBMODE)
		if okc then ship.history_info = enc end
	end
end

local function same_num(a, b)
	local x, y = tonumber(a), tonumber(b)
	if x ~= nil and y ~= nil then return x == y end
	return tostring(a) == tostring(b)
end

local function hero_matches(ship, F)
	for i = 1, #FIELD_LIST do
		local k = FIELD_LIST[i]
		if F[k] ~= nil and not same_num(ship[k], F[k]) then return false end
	end
	return true
end

local function apply_hero(e, sid)
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" then return false end
	local F = hero_fields(e, sid)
	if F == nil then return false end
	R.F[sid] = F
	apply_fields(ship, F)
	if S.heroes[sid] == nil then R.touched[sid] = true end
	return true
end

local MEGA_DEFAULT = '{"megaLevel":{},"megaUse":[]}'

local function mega_ensure(e)
	if type(e.user_ship) ~= "table" then return 0 end
	if type(e.mega_info) ~= "table" then e.mega_info = {} end
	-- [FIX lag 6] mega_ensure() chay MOI FRAME: duyet het e.mega_info roi duyet het
	-- e.user_ship -> 2 vong lap toan bo x 60 fps. Nay chi chay khi so luong doi.
	local _ns, _nm = 0, 0
	for _ in pairs(e.user_ship) do _ns = _ns + 1 end
	for _ in pairs(e.mega_info) do _nm = _nm + 1 end
	if R.mg_ns == _ns and R.mg_nm == _nm and R.mg_ship == e.user_ship and R.mg_info == e.mega_info then
		return 0
	end
	R.mg_ns, R.mg_nm, R.mg_ship, R.mg_info = _ns, _nm, e.user_ship, e.mega_info
	local have, nhave = {}, 0
	for _, v in pairs(e.mega_info) do
		if type(v) == "table" and v.shipId ~= nil then have[tostring(v.shipId)] = true; nhave = nhave + 1 end
	end
	local n = 0
	for sid, ship in pairs(e.user_ship) do
		if type(ship) == "table" and not have[tostring(sid)] and tonumber(sid) ~= nil then
			e.mega_info[#e.mega_info + 1] = { shipId = tostring(sid), info = MEGA_DEFAULT }
			n = n + 1
		end
	end
	WS.mega_overlay(e)
	return n
end
LS._mega_ensure = mega_ensure

local function real_managed(sid)
	return S.mods[sid] ~= nil or (R.touched ~= nil and R.touched[sid]) or get_mult() ~= 1
end

local function apply_all_real(e)
	local n = 0
	for sid, s in pairs(e.user_ship) do
		if type(s) == "table" and S.heroes[sid] == nil and tonumber(s.captain_type) ~= 2 and real_managed(sid) then
			if apply_hero(e, sid) then n = n + 1 end
		end
	end
	return n
end

local function heroes_assert(e, fresh)
	local now = os.time()
	for sid in pairs(S.mods) do
		local ship = e.user_ship[sid]
		if type(ship) == "table" and (fresh or now >= (R.hold[sid] or 0)) then
			local F = R.F[sid]
			-- Cac he FULL thay doi bonus theo tung module. Khong duoc ghi lai
			-- cache cu sau khi module da tinh xong, neu khong chi so se nhay len roi giam.
			if fresh or F == nil then F = hero_fields(e, sid); R.F[sid] = F end
			if F ~= nil and not hero_matches(ship, F) then
				apply_fields(ship, F)
				R.touched[sid] = true
				R.overwrites = (R.overwrites or 0) + 1
			end
		end
	end
end

local function formation_sids(e)
	local out = {}
	for i = 2, 7 do
		local v = e.formetion and e.formetion[i]
		if v ~= nil then
			v = tostring(v)
			if v ~= "0" and v ~= "" then out[#out + 1] = v end
		end
	end
	return out
end

local function fight_total(e, over)
	if R.rec_total == nil then return nil end
	local total = R.rec_total
	for _, f in pairs(R.rec_form or {}) do total = total - f end
	for _, sid in ipairs(formation_sids(e)) do
		local v = nil
		if over ~= nil and over[sid] ~= nil then
			v = over[sid]
		else
			local sh = e.user_ship[sid]
			if type(sh) == "table" then v = tonumber(sh.hero_fight) end
		end
		total = total + (v or 0)
	end
	return total
end

local function fight_assert(e)
	local t = fight_total(e)
	if t == nil or type(e.user_info) ~= "table" then return end
	if tonumber(e.user_info.fight_capacity) ~= t then
		e.user_info.fight_capacity = fint(t)
		R.overwrites = (R.overwrites or 0) + 1
	end
end

local BUDGET_SEC, BUDGET_MAX = 0.008, 40

local function pump_refresh(e)
	local rf = R.refresh
	if rf == nil then return end
	local made, t0 = 0, os.clock()
	while rf.pos <= #rf.list and made < BUDGET_MAX and (made < 1 or os.clock() - t0 < BUDGET_SEC) do
		local sid = rf.list[rf.pos]
		rf.pos = rf.pos + 1
		local s = e.user_ship[sid]
		if type(s) == "table" then
			if S.heroes[sid] ~= nil or (tonumber(s.captain_type) ~= 2 and real_managed(sid)) then
				if apply_hero(e, sid) then made = made + 1 end
			end
		end
	end
	if rf.pos > #rf.list then R.refresh = nil end
end

local function start_refresh(e)
	local list = {}
	for sid, s in pairs(e.user_ship) do
		if type(s) == "table" then list[#list + 1] = sid end
	end
	R.F = {}
	R.refresh = { list = list, pos = 1 }
end

local function push_all(dst, src)
	for i = 1, #src do dst[#dst + 1] = src[i] end
end

local function tkn(v)
	if v == nil then return "" end
	if type(v) == "number" then return fint(v) end
	return tostring(v)
end

local function blk_ship(ship, F)
	local function g(k)
		if F[k] ~= nil then return tkn(F[k]) end
		return tkn(ship[k])
	end
	return {
		"14108", "1", tkn(ship.ship_id), tkn(ship.ship_template_id), g("ship_grade"),
		tkn(ship.ship_leader or "0"), tkn(ship.ship_force or "0"), g("ship_wisdom"),
		g("ship_health"), g("ship_courage"), g("ship_intellect"), g("ship_quick"),
		tkn(tonumber(ship.initial_sp_increase) or 0), g("property_values"), tkn(ship.ship_picture or "0"),
		g("exprience"), g("grade_need_exprience"), tkn(ship.train or "0"), tkn(ship.train_endtime or "0"),
		tkn(ship.shipSpirit), tkn(ship.ship_fighting_spirit), tkn(ship.ship_skin_info),
		tkn(ship.ship_type or "0"), g("hero_fight"),
	}
end

local function blk_evo(ship, F)
	local function g(k)
		if F[k] ~= nil then return tkn(F[k]) end
		return tkn(ship[k])
	end
	local alloy = ship.alloyMatrix
	if type(alloy) ~= "table" then alloy = { mmi = {}, ma = {}, mr = {} } end
	return {
		"14104", tkn(ship.ship_id), tkn(ship.evolution_status or "1|2,0,0,0"), g("Order"), g("StarRating"),
		g("skillLevel"), g("equipInfo"), (F.qianNeng ~= nil) and tkn(F.qianNeng) or tkn(ship.qianNeng or "0,0,0"), jenc(alloy),
	}
end

local function blk_fight(e, sid, F)
	local over = nil
	if sid ~= nil and F ~= nil and tonumber(F.hero_fight) ~= nil then over = { [sid] = tonumber(F.hero_fight) } end
	local t = fight_total(e, over)
	if t == nil then return {} end
	return { "128", fint(t) }
end

local function hero_state(e, sid)
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" then return nil end
	local p = prog_get(sid) or {}
	local tid = tonumber(ship.ship_template_id)
	if tid == nil then return nil end
	return {
		sid = sid, ship = ship, tid = tid,
		grade = math.floor(tn(p.ship_grade, tonumber(ship.ship_grade) or 1)),
		exp = tn(p.exprience, tonumber(ship.exprience) or 0),
		order = math.floor(tn(p.Order, tonumber(ship.Order) or 0)),
		star = math.floor(tn(p.StarRating, tonumber(ship.StarRating) or 1)),
		skill = p.skillLevel or tostring(ship.skillLevel or "1,1,1,1,1,1"),
	}
end

local function commit_hero(e, sid, fields)
	prog_set(sid, fields)
	R.F[sid] = nil
	local F = hero_fields(e, sid)
	R.F[sid] = F
	R.hold[sid] = os.time() + 3
	return F
end

local function level_cap(e)
	local cap = tn(e.user_info.user_grade, 1)
	local lim = tonumber(cfg_str("ship_config", 49))
	if lim ~= nil and lim > 0 and lim < cap then cap = lim end
	return cap
end

local function exp_provide(tmpl)
	local d, pm, sm = G("dms"), G("prop_mould"), G("ship_mould")
	if type(d) ~= "table" or type(pm) ~= "table" or type(sm) ~= "table"
		or pm.use_of_ship == nil or sm.initial_experience_supply == nil then return 0 end
	local ok, v = pcall(function()
		local tid = tonumber(d.string(d["prop_mould"], tmpl, pm.use_of_ship))
		if tid == nil or tid <= 0 then return 0 end
		return d.int(d["ship_mould"], tid, sm.initial_experience_supply) or 0
	end)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function add_exp(st, add, cap)
	local g, x = st.grade, st.exp + add
	local need = exp_need(st.tid, g)
	local guard = 0
	while need > 0 and x >= need and g < cap and guard < 600 do
		x = x - need
		g = g + 1
		need = exp_need(st.tid, g)
		guard = guard + 1
	end
	if g >= cap and need > 0 and x > need then x = need end
	return g, x, need
end

local function exp_room(st, cap)
	local g, room = st.grade, -st.exp
	local guard = 0
	while g < cap and guard < 600 do
		room = room + exp_need(st.tid, g)
		g = g + 1
		guard = guard + 1
	end
	room = room + exp_need(st.tid, g)
	return room
end

local function parse_exp_items(e, str)
	local items = {}
	for part in string.gmatch(tostring(str or ""), "[^,]+") do
		local uid, cnt = string.match(part, "^%s*(%d+)%s*:%s*(%d+)%s*$")
		if uid == nil then return nil, "LS_yeu_cau_sai", ERR.generic end
		local rec = type(e.user_prop) == "table" and e.user_prop[uid] or nil
		if type(rec) ~= "table" then return nil, "LS_khong_co_vat_pham", ERR.items end
		local tmpl = tonumber(rec.user_prop_template)
		local prov = exp_provide(tmpl)
		if prov <= 0 then return nil, "LS_khong_phai_thuoc_exp", ERR.items end
		items[#items + 1] = { uid = uid, tmpl = tmpl, count = tonumber(cnt), provide = prov }
	end
	if #items == 0 then return nil, "LS_khong_co_vat_pham", ERR.items end
	return items
end

local function do_escalate(e, sid, items, seq, name)
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local cap = level_cap(e)
	local room = exp_room(st, cap)
	if room <= 0 then
		return err_reply(seq, name, "LS_da_dat_cap_toi_da", ERR.level_cap)
	end
	local used, gain, reserved = {}, 0, {}
	for i = 1, #items do
		local it = items[i]
		local have = LS.prop_get(it.tmpl) - (reserved[it.tmpl] or 0)
		local want = math.min(it.count, have)
		local useful = math.ceil((room - gain) / it.provide)
		local n = math.max(0, math.min(want, useful))
		if n > 0 then
			used[#used + 1] = { tmpl = it.tmpl, n = n }
			reserved[it.tmpl] = (reserved[it.tmpl] or 0) + n
			gain = gain + n * it.provide
		end
	end
	if gain <= 0 then
		toast("Khong du thuoc EXP. Mo bang GM -> VAT PHAM + de them.", 6)
		return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items)
	end
	local g2, x2, need2 = add_exp(st, gain, cap)
	for i = 1, #used do LS.prop_add(used[i].tmpl, -used[i].n) end
	local F = commit_hero(e, sid, { ship_grade = g2, exprience = fint(x2), grade_need_exprience = fint(need2) })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, sid, F))
	stat_inc("escalate")
	LS.save_state(true)
	log("len cap", sid, st.grade, "->", g2, "exp", fint(x2) .. "/" .. fint(need2), "dung", #used, "loai thuoc")
	return reply(seq, name, blocks)
end

local function h_escalate(p, seq)
	local e = ED()
	if tostring(p[1] or "") ~= "0" then return nil end
	local sid = tostring(p[2] or "")
	local items, err, ecode = parse_exp_items(e, p[3])
	if items == nil then return err_reply(seq, "ship_escalate", err, ecode) end
	return do_escalate(e, sid, items, seq, "ship_escalate")
end

local function h_one_key_escalate(p, seq)
	local e = ED()
	local sid = tostring(p[1] or "")
	local items = {}
	for _, tmpl in ipairs(cfg_list("ship_config", 1)) do
		local prov = exp_provide(tmpl)
		local ent = prop_first(e, tmpl)
		local have = LS.prop_get(tmpl)
		if prov > 0 and ent ~= nil and have > 0 then
			items[#items + 1] = { uid = ent.id, tmpl = tmpl, count = have, provide = prov }
		end
	end
	table.sort(items, function(a, b) return a.provide < b.provide end)
	if #items == 0 then
		toast("Khong co thuoc EXP. Mo bang GM -> VAT PHAM + de them.", 6)
		return err_reply(seq, "ship_one_key_escalate", "LS_khong_du_vat_pham", ERR.items)
	end
	return do_escalate(e, sid, items, seq, "ship_one_key_escalate")
end

local function grow_rows(tid)
	local d, sg = G("dms"), G("ship_grow_requirement")
	if type(d) ~= "table" or type(sg) ~= "table" or type(d["ship_grow_requirement"]) ~= "table" then return nil end
	local group = mnum(tid, "required_material_id", 0)
	if R.grow_cache == nil then R.grow_cache = {} end
	local c = R.grow_cache[group]
	if c ~= nil then return c or nil end
	local ok, rows = pcall(d.searchs, d["ship_grow_requirement"], sg.need_iron, group)
	if not ok or rows == nil then R.grow_cache[group] = false; return nil end
	R.grow_cache[group] = rows
	return rows
end

local function row_int(row, col)
	local d = G("dms")
	local ok, v = pcall(d.atoi, row, col)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function h_grow_up(p, seq)
	local e = ED()
	local name = "ship_grow_up"
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local rows = grow_rows(st.tid)
	local sg = G("ship_grow_requirement")
	if rows == nil or sg == nil then return err_reply(seq, name, "LS_khong_co_bang_thang_pham") end
	local times = math.max(1, math.floor(tn(p[5], 1)))
	if times > 24 then times = 24 end
	local order, why = st.order, nil
	local silver_need, mats, plan = 0, {}, 0
	local silver_have = S.silver or 0
	for _ = 1, times do
		local row = rows[order + 1]
		if row == nil then why = "max"; break end
		if st.grade < row_int(row, sg.need_level) then why = "level:" .. row_int(row, sg.need_level); break end
		local sv = row_int(row, sg.need_silver)
		if silver_need + sv > silver_have then why = "silver"; break end
		local add, ok = {}, true
		for k = 1, 4 do
			local tm = row_int(row, sg.need_prop1 + (k - 1) * 2)
			local cnt = row_int(row, sg.need_prop1_count + (k - 1) * 2)
			if tm > 0 and cnt > 0 then
				add[#add + 1] = { tm, cnt }
				local total = cnt
				for _, m in ipairs(mats) do if m[1] == tm then total = total + m[2] end end
				if LS.prop_get(tm) < total then ok = false end
			end
		end
		if not ok then why = "mats"; break end
		silver_need = silver_need + sv
		for _, m in ipairs(add) do mats[#mats + 1] = m end
		order = order + 1
		plan = plan + 1
	end
	if plan == 0 then
		local code = ERR.generic
		if why == "max" then
			code = ERR.rank_max
		elseif why == "silver" then
			code = ERR.silver
		elseif why == "mats" then
			code = ERR.items
			toast("Khong du nguyen lieu thang pham. Mo bang GM -> VAT PHAM + de them.", 6)
		elseif why ~= nil and string.sub(why, 1, 6) == "level:" then
			code = ERR.hero_level
			toast("Can tuong cap " .. string.sub(why, 7) .. " de thang pham tiep.", 6)
		end
		return err_reply(seq, name, "LS_khong_the_thang_pham", code)
	end
	if silver_need > 0 and not LS.money_spend("silver", silver_need) then
		return err_reply(seq, name, "LS_khong_du_bac", ERR.silver)
	end
	for _, m in ipairs(mats) do LS.prop_add(m[1], -m[2]) end
	local F = commit_hero(e, sid, { Order = fint(order) })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_evo(st.ship, F))
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, sid, F))
	stat_inc("grow_up", plan)
	LS.save_state(true)
	log("thang pham", sid, "pham", st.order, "->", order, "bac", fint(silver_need), "nguyen lieu", #mats)
	return reply(seq, name, blocks)
end

local function split_skill(s)
	local t = {}
	for w in string.gmatch(tostring(s or ""), "[^,]+") do t[#t + 1] = math.floor(tn(w, 1)) end
	while #t < 6 do t[#t + 1] = 1 end
	return t
end

local function skill_silver(talent_id, level)
	local d, tm, tl = G("dms"), G("talent_mould"), G("talent_level_requirement")
	if type(d) ~= "table" or type(tm) ~= "table" or type(tl) ~= "table" then return nil end
	local ok, v = pcall(function()
		local grp = d.int(d["talent_mould"], talent_id, tm.consumption_Library_group)
		if grp == nil then return nil end
		local rows = d.searchs(d["talent_level_requirement"], tl.current_level, level)
		if rows == nil or rows[1] == nil then return nil end
		return d.atoi(rows[1], grp + 2)
	end)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return nil
end

local function sp_read(e)
	local a, b, c = string.match(tostring(e.skill_number_info or ""), "^%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)")
	return tn(a, 0), tn(b, 0), tn(c, 0)
end

local function sp_cost_each()
	local l = cfg_list("ship_config", 5)
	return l[1] or 1
end

local function sp_cap(e)
	local s = cfg_str("user_config", 14)
	local lv = tn(e.user_info.user_grade, 1)
	local cap = nil
	if s ~= nil then
		for a, b, c in string.gmatch(s, "(%d+)%-(%d+)%s*,%s*(%d+)") do
			if lv >= tonumber(a) and lv <= tonumber(b) then cap = tonumber(c); break end
		end
	end
	return cap or 20
end

local function now_ms(e)
	local nt, st = tonumber(e.native_time), tonumber(e.system_time)
	local t = os.time()
	if nt ~= nil and st ~= nil then t = t - nt + st end
	return t * 1000
end

local function skill_steps(e, st, skills, idx, talent_id, want, budget)
	local demands = cfg_list("ship_config", 2)
	local done, why = 0, nil
	if idx < 1 or idx > 6 then return 0, "idx" end
	if (demands[idx] or 0) > st.star then return 0, "locked" end

	local limit = math.min(st.grade, tn(e.user_info.user_grade, st.grade))
	for _ = 1, want do
		local lv = skills[idx]
		if lv >= limit then why = "grade"; break end
		if budget.points < budget.each then why = "points"; break end
		local sv = skill_silver(talent_id, lv)
		if sv == nil then why = "table"; break end
		if budget.silver_used + sv > (S.silver or 0) then why = "silver"; break end
		skills[idx] = lv + 1
		budget.points = budget.points - budget.each
		budget.silver_used = budget.silver_used + sv
		budget.steps = budget.steps + 1
		done = done + 1
	end
	return done, why
end

local function skill_fail_code(why)
	if why == "locked" then return ERR.star end
	if why == "grade" then return ERR.skill_cap end
	if why == "points" then
		toast("Het diem ky nang. Mo bang GM -> SKILL FULL de day diem.", 6)
		return ERR.skill_points
	end
	if why == "silver" then return ERR.silver end
	return ERR.generic
end

local function skill_commit(e, st, skills, budget, seq, name)
	if budget.steps <= 0 then return nil end
	if budget.silver_used > 0 and not LS.money_spend("silver", budget.silver_used) then
		return err_reply(seq, name, "LS_khong_du_bac", ERR.silver)
	end
	local pts, ms, buy = sp_read(e)
	local newpts = budget.points
	local newms = ms
	if pts >= sp_cap(e) then newms = now_ms(e) end
	local spstr = fint(newpts) .. "," .. fint(newms) .. "," .. fint(buy)
	S.sp = spstr
	local F = commit_hero(e, st.sid, { skillLevel = table.concat(skills, ",") })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_evo(st.ship, F))
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, st.sid, F))
	blocks[#blocks + 1] = "12040"
	blocks[#blocks + 1] = spstr
	stat_inc("skill_up", budget.steps)
	LS.save_state(true)
	log("nang ky nang", st.sid, "+", budget.steps, "cap; bac", fint(budget.silver_used), "diem con", fint(newpts))
	return reply(seq, name, blocks)
end

local function new_budget(e)
	local pts = sp_read(e)
	return { points = pts, each = sp_cost_each(), silver_used = 0, steps = 0 }
end

local function h_skill_up(p, seq)
	local e = ED()
	local name = "ship_skill_level_up"
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local idx = math.floor(tn(p[2], 0))
	local tal = tonumber(p[3])
	if tal == nil then return err_reply(seq, name, "LS_yeu_cau_sai") end
	local skills = split_skill(st.skill)
	local budget = new_budget(e)
	local n, why = skill_steps(e, st, skills, idx, tal, 1, budget)
	if n == 0 then
		return err_reply(seq, name, "LS_khong_the_nang_ky_nang", skill_fail_code(why))
	end
	return skill_commit(e, st, skills, budget, seq, name)
end

local function h_skill_up_one_key(p, seq)
	local e = ED()
	local name = "ship_skill_level_up_one_key"
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local wants, tals = {}, {}
	for a, b in string.gmatch(tostring(p[2] or ""), "(%d+)%s*:%s*(%d+)") do wants[#wants + 1] = { tonumber(a), tonumber(b) } end
	for w in string.gmatch(tostring(p[3] or ""), "[^|]+") do tals[#tals + 1] = tonumber(w) end
	if #wants == 0 or #wants ~= #tals then return err_reply(seq, name, "LS_yeu_cau_sai") end
	local skills = split_skill(st.skill)
	local budget = new_budget(e)
	local last_why = nil
	for i = 1, #wants do
		local _, why = skill_steps(e, st, skills, wants[i][1], tals[i], wants[i][2], budget)
		if why ~= nil then last_why = why end
	end
	if budget.steps == 0 then
		return err_reply(seq, name, "LS_khong_the_nang_ky_nang", skill_fail_code(last_why))
	end
	return skill_commit(e, st, skills, budget, seq, name)
end

local CP = {}
do
local function init_cp()

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function trow(tname, id)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return nil end
	local row = d[tname][id]
	if type(row) == "string" then
		row = split_tab(row)
		d[tname][id] = row
	end
	if type(row) ~= "table" then return nil end
	return row
end

local function tcell(tname, id, col)
	local row = trow(tname, id)
	if row == nil then return nil end
	return row[col]
end

local function scol(tbl, name, dflt)
	local sch = G(tbl)
	if type(sch) == "table" and tonumber(sch[name]) ~= nil then return sch[name] end
	return dflt
end

local NPC_DEF = { attack_level_limit = 5, scene_id = 108, drop_library = 115, daily_attack_count = 118,
	attack_need_food = 119, unlock_npc = 120, ship_get_exp = 128 }
local SCENE_DEF = { open_level = 5, scene_type = 6, npcs = 13, open_scene = 16, by_open_scene = 17 }

local function npc_cell(npc, name)
	return tcell("npc", npc, scol("npc", name, NPC_DEF[name]))
end

local function npc_num(npc, name, dflt)
	local v = tonumber(npc_cell(npc, name))
	if v == nil then return dflt end
	return v
end

local function num_list(s)
	local t = {}
	for w in string.gmatch(tostring(s or ""), "[^,|]+") do
		local n = tonumber(w)
		if n ~= nil and n > 0 then t[#t + 1] = math.floor(n) end
	end
	return t
end

local function scene_info(k)
	if R.sc == nil then R.sc = {} end
	local c = R.sc[k]
	if c ~= nil then return c or nil end
	local row = trow("pve_scene", k)
	if row == nil then R.sc[k] = false; return nil end
	local function cell(name) return row[scol("pve_scene", name, SCENE_DEF[name])] end
	c = { id = k, level = tonumber(cell("open_level")) or 1, stype = tonumber(cell("scene_type")) or 0,
		npcs = num_list(cell("npcs")), open = num_list(cell("open_scene")), by = num_list(cell("by_open_scene")) }
	R.sc[k] = c
	return c
end

local function tk0(v, d)
	local s = tkn(v)
	if s == "" then return d or "0" end
	return s
end

local function user_need(grade)
	local v = tonumber(tcell("user_experience_param", grade + 1, 3))
	if v == nil or v <= 0 then return nil end
	return v
end

local function user_max_food(grade)
	return tonumber(tcell("user_experience_param", grade, 4))
end

local function user_level_cap()
	local v = tonumber(cfg_str("user_config", 5))
	if v == nil or v < 1 then v = 120 end
	return v
end

local function food_period()
	local v = tonumber(cfg_str("user_config", 4))
	if v == nil or v <= 0 then v = 0.2 end
	return math.max(1, math.floor(60 / v + 0.5))
end

local function user_init(e)
	if type(S.user) == "table" and tonumber(S.user.grade) ~= nil then return S.user end
	local u = e.user_info
	local grade = math.floor(tn(u.user_grade, 1))
	S.user = {
		grade = grade, exp = tn(u.user_experience, 0),
		food = tn(u.user_food, user_max_food(grade) or 0), food_t = os.time(),
	}
	mark()
	return S.user
end

local function food_regen()
	local U = S.user
	if U == nil then return end
	local now = os.time()
	local mx = user_max_food(U.grade) or math.huge
	if U.food_t == nil or now < U.food_t then U.food_t = now; mark() end
	if U.food >= mx then
		if U.food_t ~= now then U.food_t = now end
		return
	end
	local per = food_period()
	local n = math.floor((now - U.food_t) / per)
	if n > 0 then
		U.food = math.min(mx, U.food + n)
		if U.food >= mx then U.food_t = now else U.food_t = U.food_t + n * per end
		mark()
	end
end

local function food_spend(n)
	local U = S.user
	food_regen()
	local mx = user_max_food(U.grade) or math.huge
	if U.food >= mx then U.food_t = os.time() end
	U.food = math.max(0, U.food - n)
	mark()
end

local function user_add_exp(amount)
	local U = S.user
	local old = U.grade
	local lim = user_level_cap()
	local x = U.exp + amount
	local guard = 0
	while guard < 200 do
		local need = user_need(U.grade)
		if need == nil or U.grade >= lim or x < need then break end
		x = x - need
		U.grade = U.grade + 1
		local bonus = tonumber(tcell("user_experience_param", U.grade, 9)) or 0
		if bonus > 0 then U.food = U.food + bonus end
		guard = guard + 1
	end
	local need = user_need(U.grade)
	if need == nil or U.grade >= lim then x = math.min(x, need or x) end
	U.exp = x
	mark()
	return U.grade > old, old
end

local function user_write(e)
	local U = S.user
	local u = e.user_info
	if U == nil or type(u) ~= "table" then return end
	local g, x = fint(U.grade), fint(U.exp)
	local need = user_need(U.grade)
	local mx = user_max_food(U.grade)
	local changed = false
	if u.user_grade ~= g then u.user_grade = g; changed = true end
	if u.user_experience ~= x then u.user_experience = x; changed = true end
	if need ~= nil and u.user_grade_need_experience ~= fint(need) then u.user_grade_need_experience = fint(need); changed = true end
	if mx ~= nil and tonumber(u.max_user_food) ~= mx then u.max_user_food = mx; changed = true end
	local fd = fint(U.food)
	if u.user_food ~= fd then u.user_food = fd; changed = true end

	if u.key_user_grade ~= nil and (R.key_grade ~= U.grade or u.key_user_grade ~= R.key_enc) then
		local aes = G("aeslua")
		if type(aes) == "table" and aes.encrypt ~= nil then
			local okc, enc = pcall(aes.encrypt, "jar-world", g, aes.AES128, aes.ECBMODE)
			if okc and enc ~= nil then
				u.key_user_grade = enc
				R.key_enc, R.key_grade = enc, U.grade
				changed = true
			end
		end
	end
	if changed then R.overwrites = (R.overwrites or 0) + 1 end
end

local function user_tick(e)
	local u = e.user_info
	if type(u) ~= "table" then return end

	if u.user_grade == nil or u.user_experience == nil or u.user_food == nil then return end
	if R.user_rec == nil then
		R.user_rec = { grade = u.user_grade, exp = u.user_experience, need = u.user_grade_need_experience,
			food = u.user_food, max = u.max_user_food, key = u.key_user_grade }

		local U = S.user
		if type(U) == "table" and tonumber(U.grade) ~= nil then
			local wg, wx = math.floor(tn(u.user_grade, 1)), tn(u.user_experience, 0)
			if wg > U.grade or (wg == U.grade and wx > U.exp) then
				U.grade, U.exp = wg, wx
				mark()
			end
			local wf = tn(u.user_food, 0)
			if wf > U.food then U.food = wf; U.food_t = os.time(); mark() end
		end
	end
	user_init(e)
	food_regen()
	user_write(e)
end

local function user_restore(e)
	local r, u = R.user_rec, e.user_info
	if r == nil or type(u) ~= "table" then return false end
	u.user_grade, u.user_experience, u.user_grade_need_experience = r.grade, r.exp, r.need
	u.user_food, u.max_user_food = r.food, r.max
	if r.key ~= nil then u.key_user_grade = r.key end
	R.key_enc, R.key_grade = nil, nil
	return true
end

local function blk_user(gain, leveled)
	local U = S.user
	local b = { "12002", fint(gain), fint(U.grade), fint(U.exp), fint(U.food) }
	if leveled then
		push_all(b, { "40", fint(U.grade), fint(user_need(U.grade) or 0), "41", fint(U.exp) })
	end
	return b
end

CP.user_init, CP.food_regen, CP.user_add_exp, CP.user_write, CP.blk_user = user_init, food_regen, user_add_exp, user_write, blk_user

local CAMP_ARRAYS = { "npc_state", "npc_max_state", "npc_current_attack_count", "npc_current_buy_count",
	"scene_current_state", "scene_max_state", "get_star_count", "star_reward_state" }
local CAMP_SCALARS = { "total_star_count", "remain_star_count", "elite_star_count", "total_pass_level_counts" }

local function camp_ok(e)
	if type(e.user_info) ~= "table" then return false end
	for i = 1, #CAMP_ARRAYS do
		if type(e[CAMP_ARRAYS[i]]) ~= "table" then return false end
	end
	return scene_info(1) ~= nil and trow("npc", 1) ~= nil
end

local function camp_state()
	if type(S.camp) ~= "table" then S.camp = {} end
	local C = S.camp
	if type(C.stars) ~= "table" then C.stars = {} end
	if type(C.att) ~= "table" then C.att = {} end
	C.passes = tn(C.passes, 0)
	return C
end

local function camp_touch(ch, kind, id)
	local set = ch[kind .. "_set"]
	if not set[id] then
		set[id] = true
		local l = ch[kind]
		l[#l + 1] = id
	end
end

local function new_change()
	return { npcs = {}, npcs_set = {}, scenes = {}, scenes_set = {}, first = false, gain = 0, unlocked = {} }
end

local function scene_cleared(e, k)
	local info = scene_info(k)
	if info == nil or #info.npcs == 0 then return false end
	local cur = tonumber(e.scene_current_state[k])
	return cur ~= nil and cur >= #info.npcs
end

local function camp_open_scenes(e, ch)
	local grade = (S.user ~= nil and S.user.grade) or tn(e.user_info.user_grade, 1)
	local opened = 0
	for k = 1, 100 do
		local info = scene_info(k)
		if info ~= nil and (info.stype == 0 or info.stype == 1) then
			local cur = tonumber(e.scene_current_state[k])
			if cur ~= nil and cur < 0 and grade >= info.level then
				local ok = true
				for _, b in ipairs(info.by) do
					if not scene_cleared(e, b) then ok = false; break end
				end
				if ok then
					e.scene_current_state[k] = "0"
					e.scene_max_state[k] = "0"
					if ch ~= nil then camp_touch(ch, "scenes", k) end
					opened = opened + 1

					local first = info.npcs[1]
					if first ~= nil then
						local fs = tonumber(e.npc_state[first])
						if fs == nil or fs < 0 then
							e.npc_state[first] = "0"
							local fm = tonumber(e.npc_max_state[first])
							if fm == nil or fm < 0 then e.npc_max_state[first] = "0" end
							if ch ~= nil then camp_touch(ch, "npcs", first) end
						end
					end
				end
			end
		end
	end
	return opened
end

local function camp_mark_clear(e, npc, stars)
	local ch = new_change()
	stars = math.floor(tn(stars, 0))
	if stars < 1 then return ch end
	if stars > 3 then stars = 3 end
	local old = tonumber(e.npc_state[npc])
	if old == nil then old = -1 end
	if stars > old then e.npc_state[npc] = fint(stars); camp_touch(ch, "npcs", npc) end
	local omax = tonumber(e.npc_max_state[npc])
	if omax == nil or omax < 1 then e.npc_max_state[npc] = "1"; camp_touch(ch, "npcs", npc) end
	if old < 1 then
		ch.first = true
		for _, id in ipairs(num_list(npc_cell(npc, "unlock_npc"))) do
			local s = tonumber(e.npc_state[id])
			if s == nil or s < 0 then
				ch.unlocked[id] = { state = tostring(e.npc_state[id] or "-1"), max = tostring(e.npc_max_state[id] or "-1") }
				e.npc_state[id] = "0"
				camp_touch(ch, "npcs", id)
				local m = tonumber(e.npc_max_state[id])
				if m == nil or m < 0 then e.npc_max_state[id] = "0" end
			end
		end
	end
	local sid = npc_num(npc, "scene_id", nil)
	local info = sid ~= nil and scene_info(sid) or nil
	if info ~= nil then
		local cnt, sum = 0, 0
		for _, nid in ipairs(info.npcs) do
			local s = tonumber(e.npc_state[nid]) or -1
			if s >= 1 then cnt = cnt + 1; sum = sum + s end
		end
		local oc = tonumber(e.scene_current_state[sid]) or -1
		local om = tonumber(e.scene_max_state[sid]) or -1
		local ostar = tonumber(e.get_star_count[sid]) or 0
		if cnt > oc then e.scene_current_state[sid] = fint(cnt); camp_touch(ch, "scenes", sid) end
		if cnt > om then e.scene_max_state[sid] = fint(cnt); camp_touch(ch, "scenes", sid) end
		if sum > ostar then
			local gain = sum - ostar
			e.get_star_count[sid] = fint(sum)
			camp_touch(ch, "scenes", sid)
			ch.gain = gain
			if info.stype == 1 then
				e.elite_star_count = fint(tn(e.elite_star_count, 0) + gain)
			else
				e.total_star_count = fint(tn(e.total_star_count, 0) + gain)
				e.remain_star_count = fint(tn(e.remain_star_count, 0) + gain)
			end
		end
	end
	if ch.first then camp_open_scenes(e, ch) end
	return ch
end

local function blk_npc(e, npc)
	return { "6023", fint(npc), tk0(e.npc_state[npc], "-1"), tk0(e.npc_max_state[npc], "-1"),
		tk0(e.npc_current_attack_count[npc]), tk0(e.npc_current_buy_count[npc]),
		tk0(e.npc_hard_all_attack_times), tk0(e.npc_equip_all_attack_times) }
end

local function blk_unlock(e, id)
	return { "36", fint(id), "0", "0", tk0(e.npc_current_attack_count[id]), tk0(e.npc_current_buy_count[id]) }
end

local function restore_unlocked(e, ch)
	for id, old in pairs(ch.unlocked) do
		e.npc_state[id], e.npc_max_state[id] = old.state, old.max
	end
end

local function blk_scene(e, k)
	return { "174", tk0(e.total_star_count), tk0(e.remain_star_count), tk0(e.elite_star_count), fint(k),
		tk0(e.scene_current_state[k], "-1"), tk0(e.scene_max_state[k], "-1"), tk0(e.get_star_count[k]),
		tk0(e.star_reward_state[k]), tk0(e.total_pass_level_counts) }
end

local function blk_changes(e, ch)
	local b = {}
	for _, id in ipairs(ch.npcs) do push_all(b, blk_npc(e, id)) end
	for _, k in ipairs(ch.scenes) do push_all(b, blk_scene(e, k)) end
	return b
end

local function inf_att_on()
	return R.enabled == true and S ~= nil and type(S.cfg) == "table" and S.cfg.inf_att ~= false
end

local function camp_counts(e)
	local C = camp_state()
	if inf_att_on() and next(C.att) ~= nil then C.att = {}; mark() end
	local a, b = e.npc_current_attack_count, e.npc_current_buy_count
	for k, v in pairs(a) do
		local want = fint(tn(C.att[k], 0))
		if v ~= want then a[k] = want end
	end
	for k, v in pairs(C.att) do
		local want = fint(v)
		if a[k] ~= want then a[k] = want end
	end
	for k, v in pairs(b) do
		if v ~= "0" then b[k] = "0" end
	end
end

local function camp_newday(e)
	local C = camp_state()
	local t = os.date("%Y%m%d")
	if C.day == t then return false end
	C.day = t
	C.att = {}
	mark()
	return true
end

local function camp_reassert(e)
	local C = S.camp
	if C == nil then return end
	local ids = {}
	for k in pairs(C.stars) do ids[#ids + 1] = k end
	table.sort(ids)
	for _, id in ipairs(ids) do camp_mark_clear(e, id, C.stars[id]) end
	camp_open_scenes(e, nil)
	camp_counts(e)
	if R.camp_rec ~= nil and R.camp_rec.total_pass_level_counts ~= nil then

		local base, extra = R.camp_rec.npc_state, 0
		for id in pairs(C.stars) do
			local b = tonumber(base[id])
			if b == nil or b < 1 then extra = extra + 1 end
		end
		local want = tn(R.camp_rec.total_pass_level_counts, 0) + extra
		if tonumber(e.total_pass_level_counts) ~= want then e.total_pass_level_counts = want end
	end
	R.camp_ids = {}
	for i = 1, #CAMP_ARRAYS do R.camp_ids[i] = e[CAMP_ARRAYS[i]] end
	R.overwrites = (R.overwrites or 0) + 1
end

local function camp_snapshot(e)
	R.camp_rec = {}
	for i = 1, #CAMP_ARRAYS do
		local k = CAMP_ARRAYS[i]
		local c = {}
		for kk, vv in pairs(e[k]) do c[kk] = vv end
		R.camp_rec[k] = c
	end
	for i = 1, #CAMP_SCALARS do R.camp_rec[CAMP_SCALARS[i]] = e[CAMP_SCALARS[i]] end
end

local function camp_restore(e)
	if R.camp_rec == nil then return false end
	for i = 1, #CAMP_ARRAYS do
		local k = CAMP_ARRAYS[i]
		local c = {}
		for kk, vv in pairs(R.camp_rec[k]) do c[kk] = vv end
		e[k] = c
	end
	for i = 1, #CAMP_SCALARS do e[CAMP_SCALARS[i]] = R.camp_rec[CAMP_SCALARS[i]] end
	R.camp_ids = nil
	return true
end

local function camp_changed(e)
	local C = S.camp
	if C == nil then return false end
	local ids = R.camp_ids
	if ids == nil then return true end
	for i = 1, #CAMP_ARRAYS do
		if e[CAMP_ARRAYS[i]] ~= ids[i] then return true end
	end
	for npc, st in pairs(C.stars) do
		local cur = tonumber(e.npc_state[npc])
		if cur == nil or cur < st then return true end
	end
	for npc, n in pairs(C.att) do
		if tonumber(e.npc_current_attack_count[npc]) ~= n then return true end
	end
	return false
end

local function camp_tick(e)
	if not camp_ok(e) then return end

	if R.camp_rec ~= nil and R.camp_ids ~= nil then
		for i = 1, #CAMP_ARRAYS do
			if e[CAMP_ARRAYS[i]] ~= R.camp_ids[i] then
				R.camp_rec, R.camp_ids = nil, nil
				log("bang chien dich bi game thay -> lay lai so lieu goc")
				break
			end
		end
	end
	if R.camp_rec == nil then
		camp_snapshot(e)
		camp_newday(e)
		if S.camp ~= nil then camp_reassert(e) end
	elseif camp_newday(e) then
		camp_reassert(e)
	elseif camp_changed(e) then
		camp_reassert(e)
	end
	if inf_att_on() then

		local a = e.npc_current_attack_count
		for k, v in pairs(a) do
			if v ~= "0" then a[k] = "0" end
		end
	end
end

local function drop_index()
	if R.drop_idx ~= nil then return R.drop_idx end
	local idx = {}
	local d = G("dms")
	if type(d) == "table" and type(d["scene_reward_drop"]) == "table" then
		local keys = {}
		for k in pairs(d["scene_reward_drop"]) do
			if tonumber(k) ~= nil then keys[#keys + 1] = k end
		end
		table.sort(keys, function(a, b) return tonumber(a) < tonumber(b) end)
		for _, k in ipairs(keys) do
			local r = trow("scene_reward_drop", k)
			if r ~= nil and r[2] ~= nil then
				local g = tostring(tonumber(r[2]) or r[2])
				local l = idx[g]
				if l == nil then l = {}; idx[g] = l end
				l[#l + 1] = r
			end
		end
	end
	R.drop_idx = idx
	return idx
end

local function drop_entries(s)
	local out = {}
	for part in string.gmatch(tostring(s or ""), "[^|]+") do
		local item, typ, q1, q2, w1, w2 = string.match(part,
			"^%s*(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*%-%s*(%d+)%s*,%s*(%d+)%s*%-%s*(%d+)%s*$")
		if item ~= nil then
			out[#out + 1] = { item = tonumber(item), typ = tonumber(typ), q1 = tonumber(q1), q2 = tonumber(q2),
				w1 = tonumber(w1), w2 = tonumber(w2) }
		end
	end
	return out
end

local function rint(a, b)
	if b <= a then return a end
	return math.random(a, b)
end

local function roll_group(group, add)
	local rows = drop_index()[tostring(group)]
	if rows == nil then return false end
	for _, r in ipairs(rows) do
		local dtype, times = tonumber(r[3]) or 1, tonumber(r[4]) or 1
		local ents = drop_entries(r[5])
		if dtype == 1 then
			for _, en in ipairs(ents) do add(en.item, en.typ, rint(en.q1, en.q2)) end
		else
			local total = 0
			for _, en in ipairs(ents) do if en.w2 > total then total = en.w2 end end
			for _ = 1, math.max(1, math.floor(times)) do
				if dtype == 2 and total > 0 then
					local roll = rint(1, total)
					for _, en in ipairs(ents) do
						if roll >= en.w1 and roll <= en.w2 then add(en.item, en.typ, rint(en.q1, en.q2)); break end
					end
				elseif #ents > 0 then
					local en = ents[math.random(1, #ents)]
					add(en.item, en.typ, rint(en.q1, en.q2))
				end
			end
		end
	end
	return true
end

-- [ROI DO] Co dinh x5 (khong con nut GM): moi lan roi do / quet nhan 5 lan.
local DROP_MULT_FIXED = 5
local function get_drop_mult()
	return DROP_MULT_FIXED
end
LS.get_drop_mult = get_drop_mult

local function roll_library(lib, mult)
	local order, by = {}, {}
	local function add(item, typ, qty)
		if qty == nil or qty <= 0 then return end
		local key = tostring(typ) .. ":" .. tostring(item)
		local it = by[key]
		if it == nil then it = { item = item, typ = typ, qty = 0 }; by[key] = it; order[#order + 1] = it end
		it.qty = it.qty + qty
	end
	local row = trow("scene_reward_ex", lib)
	if row ~= nil then
		for g in string.gmatch(tostring(row[7] or ""), "(%d+)%s*,%s*%d+%s*%-%s*%d+") do roll_group(g, add) end
		for it, ty, n in string.gmatch(tostring(row[8] or ""), "(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)") do
			add(tonumber(it), tonumber(ty), tonumber(n))
		end
	end
	for _, it in ipairs(order) do it.qty = it.qty * (mult or 1) end
	return order
end
LS._roll_library = roll_library

local function apply_rewards(items)
	local given = {}
	for _, it in ipairs(items) do
		if it.typ == 1 and LS.money_add("silver", it.qty) then
			given[#given + 1] = { item = -1, typ = 1, qty = it.qty }
		elseif it.typ == 2 and LS.money_add("gold", it.qty) then
			given[#given + 1] = { item = -1, typ = 2, qty = it.qty }
		elseif it.typ == 6 and prop_known(it.item) and LS.prop_add(it.item, it.qty) then
			given[#given + 1] = { item = it.item, typ = 6, qty = it.qty }
		end
	end
	return given
end
LS._apply_rewards = apply_rewards

local function hero_cap()
	local cap = S.user ~= nil and S.user.grade or 1
	local lim = tonumber(cfg_str("ship_config", 49))
	if lim ~= nil and lim > 0 and lim < cap then cap = lim end
	return cap
end

local function award_hero_exp(e, amount, blocks)
	if amount <= 0 then return 0 end
	local f = read_formation(e)
	local cap = hero_cap()
	local over, n = {}, 0
	for i = 1, 6 do
		local sid = f[i]
		if sid ~= "0" then
			local st = hero_state(e, sid)
			if st ~= nil then
				local g2, x2, need2 = add_exp(st, amount, cap)
				if g2 ~= st.grade or x2 ~= st.exp then
					local F = commit_hero(e, sid, { ship_grade = g2, exprience = fint(x2), grade_need_exprience = fint(need2) })
					if F ~= nil then
						push_all(blocks, blk_ship(st.ship, F))
						if tonumber(F.hero_fight) ~= nil then over[sid] = tonumber(F.hero_fight) end
						n = n + 1
					end
				end
			end
		end
	end
	if n > 0 then
		local t = fight_total(e, over)
		if t ~= nil then push_all(blocks, { "128", fint(t) }) end
	end
	return n
end

local function camp_prepare()
	local e = ED()
	if e == nil or not camp_ok(e) then return nil end
	user_init(e)
	if R.camp_rec == nil then camp_tick(e) end
	camp_state()
	camp_newday(e)
	return e
end

local function h_battle_start(p, seq)
	if tostring(p[1] or "") ~= "0" then return nil end
	local scene, npc = tonumber(p[2]), tonumber(p[3])
	if scene == nil or npc == nil then return nil end
	if npc_num(npc, "scene_id", nil) ~= scene then return nil end
	local e = camp_prepare()
	if e == nil then return nil end
	local C = camp_state()
	local cost = npc_num(npc, "attack_need_food", 0)
	local blocks = {}
	food_regen()
	if cost > 0 then
		local spent = math.min(cost, S.user.food)
		food_spend(cost)
		push_all(blocks, { "30", fint(spent), fint(S.user.food) })
	end
	if not inf_att_on() then
		C.att[npc] = tn(C.att[npc], 0) + 1
		e.npc_current_attack_count[npc] = fint(C.att[npc])
	end
	push_all(blocks, blk_npc(e, npc))
	stat_inc("camp_start")
	mark()
	LS.save_state(true)
	log("vao ai npc", npc, "chuong", scene, "the luc -", cost, "con", fint(S.user.food))
	return reply(seq, "battle_result_start", blocks)
end

local function h_battle_verify(p, seq)
	if tostring(p[1] or "") ~= "0" or #p < 6 then return nil end
	local a, b = string.match(tostring(p[3] or ""), "^(%d+)%-(%d+)$")
	if b == nil then return nil end
	local npc, scene = tonumber(b), tonumber(p[2])
	if scene == nil or npc_num(npc, "scene_id", nil) ~= scene then return nil end
	local e = camp_prepare()
	if e == nil then return nil end
	local fm = e._fightModule
	local result = type(fm) == "table" and tonumber(fm.fightResult) or nil
	local stars = math.floor(tn(p[4], 0))
	local win
	if result ~= nil then win = (result == 1) else win = stars >= 1 end
	if not win then
		stat_inc("camp_lose")
		log("thua ai npc", npc)
		return reply(seq, "battle_result_verify", {})
	end
	if stars < 1 then stars = 1 end
	if stars > 3 then stars = 3 end
	local C = camp_state()
	local blocks = {}

	local given = apply_rewards(roll_library(npc_num(npc, "drop_library", 0), get_drop_mult()))
	local exp_gain = npc_num(npc, "attack_need_food", 0)
	local leveled = false
	if exp_gain > 0 then leveled = user_add_exp(exp_gain) end
	local shown = {}
	for _, g in ipairs(given) do shown[#shown + 1] = g end
	if exp_gain > 0 then shown[#shown + 1] = { item = -1, typ = 8, qty = exp_gain } end
	if #shown == 0 then shown[1] = { item = -1, typ = 1, qty = 0 } end
	push_all(blocks, { "171", "2", fint(#shown) })
	for _, g in ipairs(shown) do push_all(blocks, { fint(g.item), fint(g.typ), fint(g.qty) }) end

	push_all(blocks, blk_user(exp_gain, leveled))

	if stars > tn(C.stars[npc], 0) then C.stars[npc] = stars end
	C.passes = tn(C.passes, 0) + 1
	local ch = camp_mark_clear(e, npc, stars)
	if ch.first then e.total_pass_level_counts = tn(e.total_pass_level_counts, 0) + 1 end
	if leveled then camp_open_scenes(e, ch) end
	push_all(blocks, blk_npc(e, npc))
	local seen = { [npc] = true }
	for _, id in ipairs(ch.npcs) do
		if not seen[id] then
			if ch.unlocked[id] ~= nil then push_all(blocks, blk_unlock(e, id)) else push_all(blocks, blk_npc(e, id)) end
			seen[id] = true
		end
	end
	for _, k in ipairs(ch.scenes) do push_all(blocks, blk_scene(e, k)) end

	local nh = award_hero_exp(e, npc_num(npc, "ship_get_exp", 0), blocks)
	stat_inc("camp_win")
	mark()
	LS.save_state(true)
	log("thang ai npc", npc, stars, "sao | thuong", #given, "loai | exp", fint(exp_gain), leveled and ("| LEN CAP " .. fint(S.user.grade)) or "",
		"| tuong +exp", nh, "| mo", #ch.npcs, "npc", #ch.scenes, "chuong")
	restore_unlocked(e, ch)
	return reply(seq, "battle_result_verify", blocks)
end

local function h_battle_fail(p, seq)
	stat_inc("camp_fail")
	return reply(seq, "battle_result_fail", {})
end

local function h_sweep(p, seq)
	local npc, want = tonumber(p[1]), tonumber(p[3])
	if npc == nil or want == nil or want < 1 then return nil end
	if npc_num(npc, "scene_id", nil) == nil then return nil end
	local e = camp_prepare()
	if e == nil then return nil end
	local C = camp_state()
	local state = tonumber(e.npc_state[npc]) or 0
	if state < 3 then return err_reply(seq, "sweep", "LS_chua_3_sao", ERR.generic) end
	local cost = npc_num(npc, "attack_need_food", 0)
	local daily = npc_num(npc, "daily_attack_count", 9999)
	local inf = inf_att_on()
	if inf then daily = 1000000000 end
	food_regen()
	local n = math.floor(want)
	n = math.min(n, daily - tn(C.att[npc], 0))
	if cost > 0 then n = math.min(n, math.floor(S.user.food / cost)) end
	if n <= 0 then
		if daily - tn(C.att[npc], 0) <= 0 then return err_reply(seq, "sweep", "LS_het_luot", ERR.attempts) end
		return err_reply(seq, "sweep", "LS_khong_du_the_luc", ERR.generic)
	end
	local mult = get_drop_mult()
	local lib = npc_num(npc, "drop_library", 0)
	local blocks = { "52", fint(n) }
	local any_level = false
	local old_grade = S.user.grade
	for _ = 1, n do
		local given = apply_rewards(roll_library(lib, mult))
		local silver, props = 0, {}
		for _, g in ipairs(given) do
			if g.typ == 1 then silver = silver + g.qty
			elseif g.typ == 6 then props[#props + 1] = g end
		end
		local lv = false
		if cost > 0 then lv = user_add_exp(cost) end
		if lv then any_level = true end
		push_all(blocks, { fint(cost), fint(silver), "0", fint(#props) })
		for _, g in ipairs(props) do push_all(blocks, { fint(g.item), fint(g.qty) }) end
		push_all(blocks, { "0", "0", "0", fint(S.user.grade), fint(S.user.exp), fint(user_need(S.user.grade) or 0) })
	end
	local now = fint(os.time())
	push_all(blocks, { now, now })
	if cost > 0 then food_spend(cost * n) end
	if not inf then
		C.att[npc] = tn(C.att[npc], 0) + n
		e.npc_current_attack_count[npc] = fint(C.att[npc])
	end
	local exp_total = cost * n
	push_all(blocks, blk_user(exp_total, any_level))
	push_all(blocks, blk_npc(e, npc))
	if any_level then
		local ch = new_change()
		camp_open_scenes(e, ch)
		for _, k in ipairs(ch.scenes) do push_all(blocks, blk_scene(e, k)) end
	end
	local nh = award_hero_exp(e, npc_num(npc, "ship_get_exp", 0) * n, blocks)
	stat_inc("camp_sweep", n)
	mark()
	LS.save_state(true)
	log("quet ai npc", npc, "x", n, "| the luc -", fint(cost * n), "con", fint(S.user.food),
		any_level and ("| LEN CAP " .. fint(old_grade) .. "->" .. fint(S.user.grade)) or "", "| tuong +exp", nh)
	return reply(seq, "sweep", blocks)
end

function LS.gm_refill_food()
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then return nil end
	user_init(e)
	local mx = user_max_food(S.user.grade)
	if mx ~= nil and S.user.food < mx then S.user.food = mx end
	S.user.food_t = os.time()
	mark()
	user_write(e)
	LS.save_state(true)
	log("GM: do day the luc", fint(S.user.food))
	return S.user.food
end

function LS.user_get(key)
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or type(S.user) ~= "table" then return nil end
	if key == "level" then return S.user.grade end
	if key == "food" then food_regen(); return S.user.food end
	return nil
end

function LS.gm_set_food(v)
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then return nil end
	user_init(e)
	v = math.max(0, math.floor(tn(v, 0)))
	S.user.food = v
	S.user.food_t = os.time()
	mark()
	user_write(e)
	LS.save_state(true)
	log("GM: the luc =", fint(v))
	return v
end

local DROP_STEPS = { 1, 2, 3, 5, 10 }

function LS.gm_set_drop_mult(m)
	if S == nil then return false end
	m = math.floor(tn(m, 1))
	if m < 1 then m = 1 end
	S.cfg.drop_mult = m
	mark()
	LS.save_state(true)
	log("he so roi do:", fint(m))
	return true
end

function LS.gm_cycle_drop_mult()
	local cur = get_drop_mult()
	local nxt = DROP_STEPS[1]
	for i = 1, #DROP_STEPS do
		if cur < DROP_STEPS[i] then nxt = DROP_STEPS[i]; break end
	end
	if LS.gm_set_drop_mult(nxt) then return nxt end
	return nil
end

-- One-shot GM completion for the three campaign types only. No battle rewards,
-- currency, XP, daily instances, tower or Arena state are awarded/overwritten.
function LS.gm_open_campaign()
	if not LS.ready() then return nil end
	local e = camp_prepare()
	if e == nil then return nil end
	local d = G("dms")
	if type(d) ~= "table" or type(d.pve_scene) ~= "table" then return nil end
	local ids = {}
	for k in pairs(d.pve_scene) do
		local id = tonumber(k)
		if id ~= nil and id > 0 then ids[#ids + 1] = id end
	end
	table.sort(ids)
	local C = camp_state()
	local scenes, npcs, seen = 0, 0, {}
	for _, sid in ipairs(ids) do
		local info = scene_info(sid)
		if info ~= nil and (info.stype == 0 or info.stype == 1 or info.stype == 15) then
			-- Validate the entire chapter before touching it.
			local valid = #info.npcs > 0
			for _, nid in ipairs(info.npcs) do
				if npc_num(nid, "scene_id", nil) ~= sid then valid = false end
			end
			if valid then
				local sum = 0
				for _, nid in ipairs(info.npcs) do
					local stars = math.max(3, tn(e.npc_state[nid], 0), tn(C.stars[nid], 0))
					e.npc_state[nid] = fint(stars)
					e.npc_max_state[nid] = fint(math.max(1, tn(e.npc_max_state[nid], 0)))
					if type(e.npc_last_state) == "table" then e.npc_last_state[nid] = fint(stars) end
					C.stars[nid] = stars
					sum = sum + stars
					if not seen[nid] then seen[nid] = true; npcs = npcs + 1 end
				end
				e.scene_current_state[sid] = fint(math.max(#info.npcs, tn(e.scene_current_state[sid], 0)))
				e.scene_max_state[sid] = fint(math.max(#info.npcs, tn(e.scene_max_state[sid], 0)))
				if type(e.scene_last_state) == "table" then e.scene_last_state[sid] = e.scene_current_state[sid] end
				local gain = math.max(0, sum - tn(e.get_star_count[sid], 0))
				e.get_star_count[sid] = fint(math.max(sum, tn(e.get_star_count[sid], 0)))
				-- Same accounting as normal campaign completion (camp_mark_clear).
				if info.stype == 1 then
					e.elite_star_count = fint(tn(e.elite_star_count, 0) + gain)
				else
					e.total_star_count = fint(tn(e.total_star_count, 0) + gain)
					e.remain_star_count = fint(tn(e.remain_star_count, 0) + gain)
				end
				scenes = scenes + 1
			end
		end
	end
	if scenes == 0 then return nil end
	camp_reassert(e)
	mark()
	local saved = LS.save_now()
	log("GM: mo full 3 che do chien dich", scenes, "chuong", npcs, "ai; saved=", saved)
	local sm = G("state_machine")
	if type(sm) == "table" and type(sm.excute) == "function" then
		pcall(sm.excute, "pve_map_update_draw", 0, "")
	end
	return scenes, npcs, saved
end

function LS.gm_player_level(n)
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil or not camp_ok(e) then return nil end
	user_init(e)
	n = math.max(1, math.floor(tn(n, 1)))
	local lim = user_level_cap()
	local up = 0
	for _ = 1, n do
		local need = user_need(S.user.grade)
		if need == nil or S.user.grade >= lim then break end
		user_add_exp(math.max(0, need - S.user.exp))
		up = up + 1
	end
	if up == 0 then return S.user.grade end
	camp_open_scenes(e, nil)
	R.camp_ids = nil
	user_write(e)
	stat_inc("gm_player_level", up)
	LS.save_state(true)
	log("GM: len", up, "cap -> Lv", fint(S.user.grade))
	return S.user.grade
end

-- [AUTO] Len thang toi cap toi da cua bang du lieu (user_config[5]), ghi/luu 1 lan.
function LS.gm_max_level()
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil or not camp_ok(e) then return nil end
	user_init(e)
	local lim = user_level_cap()
	local up, guard = 0, 0
	while S.user.grade < lim and guard < 400 do
		local need = user_need(S.user.grade)
		if need == nil then break end
		user_add_exp(math.max(0, need - S.user.exp))
		up = up + 1
		guard = guard + 1
	end
	if up > 0 then
		camp_open_scenes(e, nil)
		R.camp_ids = nil
		user_write(e)
		LS.save_state(true)
		log("AUTO: len cap toi da Lv", fint(S.user.grade))
	end
	return S.user.grade, up
end

CP.camp_tick, CP.user_tick = camp_tick, user_tick
CP.camp_restore, CP.user_restore = camp_restore, user_restore
CP.get_drop_mult, CP.user_need, CP.user_max_food = get_drop_mult, user_need, user_max_food
CP.inf_att_on = inf_att_on
CP.h_battle_start, CP.h_battle_verify, CP.h_battle_fail, CP.h_sweep = h_battle_start, h_battle_verify, h_battle_fail, h_sweep

end
init_cp()
end

do
local function init_eq()

local NSLOT = 6
local KEYS = { "lv", "gr", "ex", "st", "mo" }
local DEF5 = { 1, 0, 0, 0, 0 }
local EID_BASE = 800000000

local function esplit(s, sep)
	local t, init = {}, 1
	s = tostring(s or "")
	while true do
		local p = string.find(s, sep, init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + #sep
	end
	return t
end

local function ecopy(t)
	local o = {}
	if type(t) == "table" then
		for i = 1, #t do o[i] = t[i] end
	end
	return o
end

local function ecache()
	if R.eq_cache == nil then R.eq_cache = {} end
	return R.eq_cache
end

local function row_str(row, col)
	local d = G("dms")
	local ok, v = pcall(d.atos, row, col)
	if ok and v ~= nil then return tostring(v) end
	return ""
end

local function eq_state()
	if S.eq == nil then S.eq = {} end
	local q = S.eq
	if type(q.hard) ~= "table" then q.hard = {} end
	if type(q.bag) ~= "table" then q.bag = {} end
	if tonumber(q.next_eid) == nil then q.next_eid = EID_BASE end
	return q
end

local function info_parse(str)
	local parts = esplit(str, "|")
	local t = {}
	for pi = 1, 5 do
		local vals = esplit(parts[pi] or "", ",")
		local a = {}
		for s = 1, NSLOT do
			local v = tonumber(vals[s])
			if v == nil then v = DEF5[pi] end
			a[s] = v
		end
		t[KEYS[pi]] = a
	end
	return t
end

local function info_pack(t)
	local out = {}
	for pi = 1, 5 do
		local c = {}
		for s = 1, NSLOT do c[s] = fint(t[KEYS[pi]][s]) end
		out[pi] = table.concat(c, ",")
	end
	return table.concat(out, "|")
end

local function default_moulds(tid)
	local c = ecache()
	c.dm = c.dm or {}
	local r = c.dm[tid]
	if r ~= nil then return r end
	local vals = esplit(mstr(tid, "treasureSkill") or "", ",")
	r = {}
	for i = 1, NSLOT do r[i] = tonumber(vals[i]) or 0 end
	c.dm[tid] = r
	return r
end

function EQ.default_info(tid)
	local c = ecache()
	c.dinfo = c.dinfo or {}
	local r = c.dinfo[tid]
	if r == nil then
		r = info_pack({
			lv = { 1, 1, 1, 1, 1, 1 }, gr = { 0, 0, 0, 0, 0, 0 }, ex = { 0, 0, 0, 0, 0, 0 },
			st = { 0, 0, 0, 0, 0, 0 }, mo = default_moulds(tid) })
		c.dinfo[tid] = r
	end
	return r
end

local function cur_mould(t, tid, slot)
	local dm = default_moulds(tid)
	if t.st[slot] > 0 and t.mo[slot] > 0 then return t.mo[slot] end
	return dm[slot]
end

local function pcv(row, dflt)
	return tonumber(cfg_str("play_config", row)) or dflt
end

local function mould_info(mould)
	local c = ecache()
	c.mould = c.mould or {}
	local m = c.mould[mould]
	if m ~= nil then return m or nil end
	local d, em = G("dms"), G("equipment_mould")
	local res = false
	if type(d) == "table" and type(em) == "table" and type(d["equipment_mould"]) == "table" and mould ~= nil and mould > 0 then
		local ok, r = pcall(function()
			local function s(col) return d.string(d["equipment_mould"], mould, em[col]) end
			local o = { etype = tonumber(s("equipment_type")) or 0, skill = tonumber(s("skill_mould")) or -1,
				seat = tonumber(s("equipment_seat")) or -1, init = {}, grow = {} }
			local function pairs_of(str, dst)
				for i, w in ipairs(esplit(str, "|")) do
					local a, b = string.match(w, "^%s*(%-?[%d%.]+)%s*,%s*(%-?[%d%.]+)")
					dst[i] = { t = tonumber(a) or -1, v = tonumber(b) or 0 }
				end
			end
			local iv, gv = s("initial_value"), s("grow_value")
			if iv ~= nil and iv ~= "" and iv ~= "-1" then pairs_of(iv, o.init) end
			if gv ~= nil and gv ~= "" and gv ~= "-1" then pairs_of(gv, o.grow) end
			return o
		end)
		if ok and type(r) == "table" then res = r end
	end
	c.mould[mould] = res
	return res or nil
end

local function star_group(group)
	local c = ecache()
	c.star = c.star or {}
	local g = c.star[group]
	if g ~= nil then return g or nil end
	local d, es = G("dms"), G("equipment_star")
	local res = false
	if type(d) == "table" and type(es) == "table" and type(d["equipment_star"]) == "table" and group ~= nil and group >= 0 then
		local ok, rows = pcall(d.searchs, d["equipment_star"], es.group_id, group)
		if ok and type(rows) == "table" and #rows > 0 then
			res = {}
			for i = 1, #rows do
				res[i] = { star = row_int(rows[i], es.current_star), cost = row_str(rows[i], es.cost_items),
					add = row_str(rows[i], es.add_attribute_values) }
			end
		end
	end
	c.star[group] = res
	return res or nil
end

local function star_row(group, star)
	local g = star_group(group)
	if g == nil then return nil end
	for i = 1, #g do
		if g[i].star == star then return g[i] end
	end
	return nil
end

local function parse_cost(s)
	local out = {}
	for _, part in ipairs(esplit(s, "|")) do
		local a, b, c = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)")
		a, b, c = tonumber(a), tonumber(b), tonumber(c)
		if a ~= nil and c ~= nil and a > 0 and c > 0 and (b ~= -1 or a == 1 or a == 2) then
			out[#out + 1] = { a, b, c }
		end
	end
	return out
end

local function coef(row, key)
	local c = ecache()
	c.coef = c.coef or {}
	local m = c.coef[row]
	if m == nil then
		m = cfg_pairs("equipment_config", row) or false
		c.coef[row] = m
	end
	if not m then return 0 end
	return m[tonumber(key)] or 0
end

local function formula(mould, grade, star, level)
	local mi = mould_info(mould)
	if mi == nil then return {} end
	local out = {}
	if mi.etype < 4 then
		local A, B, C = coef(1, grade), coef(2, grade), coef(3, star)
		local row = star_row(mi.skill, star)
		local add = row and esplit(row.add, "|") or {}
		for i = 1, #mi.init do
			local a, g = mi.init[i], mi.grow[i]
			local gv = g and g.v or 0
			local av = 0
			if add[i] ~= nil then
				local _, v2 = string.match(add[i], "^%s*(%-?[%d%.]+)%s*,%s*(%-?[%d%.]+)")
				av = tonumber(v2) or 0
			end
			out[#out + 1] = { t = a.t, v = math.floor(a.v + gv * A * C + av + gv * (level - 1) * B * C) }
		end
	else
		local D = tonumber(cfg_str("equipment_config", 4)) or 0
		local E = tonumber(cfg_str("equipment_config", 5)) or 0
		for i = 1, #mi.init do
			local a, g = mi.init[i], mi.grow[i]
			local gv = g and g.v or 0
			local fv = a.v + D * grade + E * star + gv * (level - 1)
			out[#out + 1] = { t = a.t, v = tonumber(string.format("%.1f", fv)) or fv }
		end
	end
	return out
end
EQ.formula = formula

local function quench_star() return math.floor(pcv(196, 5)) end

local function entry_parse(s)
	local lv, ty, v = string.match(tostring(s or ""), "^%s*(%-?%d+)%s*|%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
	return tonumber(lv), tonumber(ty), tonumber(v)
end

local function harden_row(slot, lv)
	local c = ecache()
	c.hrow = c.hrow or {}
	local key = slot * 1000 + lv
	local r = c.hrow[key]
	if r ~= nil then return r or nil end
	local d = G("dms")
	local res = false
	if type(d) == "table" and type(d["equipment_harden"]) == "table" then
		local ok, rows = pcall(d.searchs, d["equipment_harden"], 7, slot, 2, lv)
		if ok and type(rows) == "table" and rows[1] ~= nil then
			local row = rows[1]
			res = { need = row_int(row, 3), gold = row_int(row, 4), b1 = row_str(row, 5), b2 = row_str(row, 6) }
		end
	end
	c.hrow[key] = res
	return res or nil
end

local function base_prop(slot, lv)
	local r = harden_row(slot, lv)
	if r == nil then return "" end
	local t = {}
	if r.b1 ~= "" and r.b1 ~= "-1" then t[#t + 1] = r.b1 end
	if r.b2 ~= "" and r.b2 ~= "-1" then t[#t + 1] = r.b2 end
	return table.concat(t, "|")
end

local function param_list(slot)
	local c = ecache()
	c.hparam = c.hparam or {}
	local r = c.hparam[slot]
	if r ~= nil then return r or nil end
	local d = G("dms")
	local res = false
	if type(d) == "table" and type(d["equipment_harden_param"]) == "table" then
		local ok, rows = pcall(d.searchs, d["equipment_harden_param"], 2, slot)
		if ok and type(rows) == "table" and #rows > 0 then
			res = {}
			for i = 1, #rows do
				local row = rows[i]
				local rec = { ty = row_int(row, 3), r = {} }
				for k = 0, 3 do rec.r[k] = row_str(row, 4 + k) end
				res[#res + 1] = rec
			end
		end
	end
	c.hparam[slot] = res
	return res or nil
end

local function range_of(rec, lvl)
	if lvl > 3 then lvl = 3 end
	if lvl < 0 then lvl = 0 end
	local lo, hi = 0, 0
	for k = 0, lvl do
		local a, b = string.match(tostring(rec.r[k] or ""), "^%s*(%-?[%d%.]+)%s*,%s*(%-?[%d%.]+)")
		lo = lo + (tonumber(a) or 0)
		hi = hi + (tonumber(b) or 0)
	end
	return lo, hi
end

local function fmt_val(v, isfloat)
	if not isfloat then return fint(math.floor(v + 0.5)) end
	local s = string.format("%.2f", v)
	s = string.gsub(s, "0+$", "")
	s = string.gsub(s, "%.$", "")
	return s
end

local function roll_entry(slot, lvl, avoid, keep_type, min_val)
	local pl = param_list(slot)
	if pl == nil then return nil end
	local rec = nil
	if keep_type ~= nil then
		for i = 1, #pl do if pl[i].ty == keep_type then rec = pl[i]; break end end
	end
	if rec == nil then
		local pool = {}
		for i = 1, #pl do
			if not (avoid and avoid[pl[i].ty]) then pool[#pool + 1] = pl[i] end
		end
		if #pool == 0 then pool = pl end
		rec = pool[math.random(1, #pool)]
	end
	local lo, hi = range_of(rec, lvl)
	local isfloat = (string.find(tostring(rec.r[0] or ""), ".", 1, true) ~= nil)
	local v = lo + math.random() * (hi - lo)
	if min_val ~= nil and v < min_val and min_val <= hi then v = min_val end
	return fint(lvl) .. "|" .. fint(rec.ty) .. "," .. fmt_val(v, isfloat)
end

local function conv_hard(tb)
	if type(tb) ~= "table" then return nil end
	local h = {}
	for s = 1, NSLOT do
		local r = tb[s]
		if type(r) == "table" then
			h[s] = { lv = math.floor(tn(r.level, 0)), ex = tn(r.exp, 0), ent = ecopy(r.entryInfos),
				rep = ecopy(r.replacedEntries), lock = tonumber(r.lockIndex) }
		else
			h[s] = { lv = 0, ex = 0, ent = {}, rep = {} }
		end
	end
	return h
end

local function hard_runtime(h)
	local out = {}
	for s = 1, NSLOT do
		local x = h[s] or { lv = 0, ex = 0, ent = {}, rep = {} }
		local r = { level = x.lv, exp = x.ex }
		local bp = base_prop(s, x.lv)
		if bp ~= "" then r.baseProperty = bp end
		if #x.ent > 0 then r.entryInfos = ecopy(x.ent) end
		if x.rep ~= nil and #x.rep > 0 then r.replacedEntries = ecopy(x.rep) end
		if x.lock ~= nil then r.lockIndex = x.lock end
		out[s] = r
	end
	return out
end

local function hard_default_tbl()
	local out = {}
	for s = 1, NSLOT do out[s] = { level = 0, exp = 0 } end
	return out
end
EQ.hard_default_tbl = hard_default_tbl
EQ.conv_hard = conv_hard

-- FULL trang bi phai co du cac dong toi luyen da mo o moc 1/3/6,
-- va moi dong o bac 3. Ban cu chi day cap toi luyen nen giao dien van thieu chi so.
local function hard_max_entries(slot, keep, rnd)
	local appear = esplit(cfg_str("play_config", 194) or "1,3,6", ",")
	local want = math.max(1, #appear)
	local pool = param_list(slot) or {}
	-- [BOT RANDOM] rnd ~= nil: xao tron (ban sao) de chon ngau nhien trong TOAN BO loai dong cua o nay
	if rnd ~= nil then
		local sh = {}
		for i = 1, #pool do sh[i] = pool[i] end
		for i = #sh, 2, -1 do
			local j = math.floor(rnd() * i) + 1
			sh[i], sh[j] = sh[j], sh[i]
		end
		pool = sh
	end
	local out, used = {}, {}
	local function emit(rec)
		used[rec.ty] = true
		local _, hi = range_of(rec, 3)
		local isfloat = string.find(tostring(rec.r[0] or ""), ".", 1, true) ~= nil
		out[#out + 1] = "3|" .. fint(rec.ty) .. "," .. fmt_val(hi, isfloat)
	end
	-- Giu nguyen LOAI dong toi luyen dang co (vd 20 = no, 43/46...), chi day
	-- gia tri len max. Neu khong, "nang max" thay bang 0/1/2 va mat no.
	if type(keep) == "table" then
		for i = 1, #keep do
			local _, ty = entry_parse(keep[i])
			if ty ~= nil and not used[ty] then
				for j = 1, #pool do
					if pool[j].ty == ty then emit(pool[j]); break end
				end
			end
			if #out >= want then break end
		end
	end
	for i = 1, #pool do
		if #out >= want then break end
		if not used[pool[i].ty] then emit(pool[i]) end
	end
	return out
end

local function hard_sig(tb)
	local parts = {}
	for s = 1, NSLOT do
		local r = type(tb) == "table" and tb[s] or nil
		if type(r) ~= "table" then
			parts[s] = "?"
		else
			parts[s] = table.concat({ tostring(tonumber(r.level)), tostring(tonumber(r.exp)), tostring(r.baseProperty or ""),
				table.concat(r.entryInfos or {}, ";"), table.concat(r.replacedEntries or {}, ";"), tostring(r.lockIndex or "") }, ",")
		end
	end
	return table.concat(parts, "|")
end

-- Buff "Cuong Hoa Trang Bi" (strengthen master) tinh theo moc trung binh cua
-- 4 trang bi + 2 bao vat. Truoc day server offline bo qua hoan toan nen cac
-- dong nhu 20,1 (no) khong bao gio vao property_values.
local function master_props(t)
	local out = {}
	local d, sc = G("dms"), G("strengthen_master_info")
	if type(d) ~= "table" or type(sc) ~= "table" or type(d["strengthen_master_info"]) ~= "table" then return out end
	local function add_slot(slots, step, mtype)
		local minv = nil
		for i = 1, #slots do
			local v = 0
			if (tonumber(t.mo[slots[i]]) or 0) > 0 then v = tonumber(t.lv[slots[i]]) or 0 end
			if minv == nil or v < minv then minv = v end
		end
		if minv == nil then return end
		local lv = math.floor(minv / step) * step
		local ok, rows = pcall(d.searchs, d["strengthen_master_info"], sc.need_level or 5, lv)
		if not ok or type(rows) ~= "table" then return end
		for _, row in ipairs(rows) do
			local mt = tonumber(d.atoi(row, sc.master_type or 3)) or 0
			if mt == mtype then
				local prop = d.atos(row, sc.additional_property or 6)
				if prop ~= nil and prop ~= "" and prop ~= "-1" then
					for part in string.gmatch(tostring(prop), "[^|]+") do
						local ty, v = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
						ty, v = tonumber(ty), tonumber(v)
						if ty ~= nil and v ~= nil then out[#out + 1] = { t = ty, v = v } end
					end
				end
				break
			end
		end
	end
	add_slot({ 1, 2, 3, 4 }, 10, 0)
	add_slot({ 5, 6 }, 5, 2)
	return out
end

function EQ.stats(info_str, tid, hard)
	local ok, res = pcall(function()
		local t = info_parse(info_str)
		local out = { 0, 0, 0, 0, spec = {} }

		local pct = { 0, 0, 0, 0 }
		out.pct = pct
		local function put(ty, v)
			if ty >= 0 and ty <= 3 then out[ty + 1] = out[ty + 1] + v
			elseif ty >= 4 and ty <= 7 then pct[ty - 3] = pct[ty - 3] + v
			else out.spec[ty] = (out.spec[ty] or 0) + v end
		end
		local need = quench_star()
		for s = 1, NSLOT do
			local mould = cur_mould(t, tid, s)
			if mould ~= nil and mould > 0 then
				local attrs = formula(mould, t.gr[s], t.st[s], t.lv[s])
				for i = 1, #attrs do put(attrs[i].t, attrs[i].v) end
			end
			if hard ~= nil and hard[s] ~= nil and t.st[s] >= need then

				if (hard[s].lv or 0) > 0 then
					for _, part in ipairs(esplit(base_prop(s, hard[s].lv), "|")) do
						local bty, bv = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
						bty, bv = tonumber(bty), tonumber(bv)
						if bty ~= nil and bv ~= nil then put(bty, bv) end
					end
				end
				local ent = hard[s].ent or {}
				for i = 1, #ent do
					local _, ty, v = entry_parse(ent[i])
					if ty ~= nil and v ~= nil then put(ty, v) end
				end
			end
		end
		for _, p in ipairs(master_props(t)) do put(p.t, p.v) end
		return out
	end)
	if ok and type(res) == "table" then return res end
	return { 0, 0, 0, 0, pct = { 0, 0, 0, 0 }, spec = {} }
end

local function sub4(a, b)
	local d = { a[1] - b[1], a[2] - b[2], a[3] - b[3], a[4] - b[4] }
	local pa, pb = a.pct or {}, b.pct or {}
	local f, any = {}, false
	for i = 1, 4 do
		local x, y = pa[i] or 0, pb[i] or 0
		if x ~= y and 100 + y > 0 and 100 + x > 0 then f[i] = (100 + x) / (100 + y); any = true else f[i] = 1 end
	end
	if any then d.f = f end
	local sa, sb = a.spec or {}, b.spec or {}
	local spec = {}
	for ty, v in pairs(sa) do
		local nv = v - (sb[ty] or 0)
		if math.abs(nv) > 1e-9 then spec[ty] = nv end
	end
	for ty, v in pairs(sb) do
		if sa[ty] == nil and math.abs(v) > 1e-9 then spec[ty] = -v end
	end
	d.spec = spec
	return d
end

function EQ.adjust(pn, dq)
	for i = 1, 4 do
		local v = pn[i] + dq[i]
		local f = dq.f ~= nil and dq.f[i] or 1
		if f ~= 1 then v = math.floor(v * f + 0.5) end
		pn[i] = math.max(0, v)
	end
end

function EQ.delta_ls(sid, tid, info_str)
	local q = S ~= nil and S.eq or nil
	local hard = q and q.hard and q.hard[tostring(sid)] or nil
	local dflt = EQ.default_info(tid)
	if hard == nil and (info_str == nil or info_str == dflt) then return { 0, 0, 0, 0 } end
	local c = ecache()
	c.base_ls = c.base_ls or {}
	local base = c.base_ls[tid]
	if base == nil then
		base = EQ.stats(dflt, tid, nil)
		c.base_ls[tid] = base
	end
	return sub4(EQ.stats(info_str or dflt, tid, hard), base)
end

function EQ.delta_real(sid, rec, info_str)
	if rec == nil or rec.tid == nil then return { 0, 0, 0, 0 } end
	local q = S ~= nil and S.eq or nil
	local hard = (q and q.hard and q.hard[tostring(sid)]) or rec.hard
	return sub4(EQ.stats(info_str or rec.eq_info or "", rec.tid, hard), rec.eq_base or { 0, 0, 0, 0 })
end

function EQ.rec_init(r, s)
	r.eq_info = tostring(s.equipInfo or "")

	if s.hardensInfo == nil then s.hardensInfo = hard_default_tbl() end
	r.hard_orig = s.hardensInfo
	r.hard = EQ.conv_hard(s.hardensInfo)
	if r.tid ~= nil and r.eq_info ~= "" then
		r.eq_base = EQ.stats(r.eq_info, r.tid, r.hard)
	else
		r.eq_base = { 0, 0, 0, 0 }
	end
end

local function ship_ctx(e, sid)
	local st = hero_state(e, sid)
	if st == nil then return nil end
	local p = prog_get(sid) or {}
	st.info_str = tostring(p.equipInfo or st.ship.equipInfo or "")
	if st.info_str == "" then st.info_str = EQ.default_info(st.tid) end
	st.info = info_parse(st.info_str)
	return st
end

local function finish(e, st, info, seq, name, extra)
	local F = commit_hero(e, st.sid, { equipInfo = info_pack(info) })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_evo(st.ship, F))
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, st.sid, F))
	if extra ~= nil then push_all(blocks, extra) end
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function lvl_rows(group)
	if group == nil then return nil end
	local c = ecache()
	c.lrows = c.lrows or {}
	local g = c.lrows[group]
	if g ~= nil then return g or nil end
	local d, ep = G("dms"), G("equipment_level_param")
	local res = false
	if type(d) == "table" and type(ep) == "table" and type(d["equipment_level_param"]) == "table" and group ~= nil then
		local ok, rows = pcall(d.searchs, d["equipment_level_param"], ep.library_group, group)
		if ok and type(rows) == "table" and #rows > 0 then
			res = { map = {}, max = 0 }
			for i = 1, #rows do
				local lv = row_int(rows[i], ep.equip_level)
				res.map[lv] = rows[i]
				if lv > res.max then res.max = lv end
			end
		end
	end
	c.lrows[group] = res
	return res or nil
end

local function slot_group(tid, slot)
	local vals = esplit(mstr(tid, "max_rank_level") or "", ",")
	return tonumber(vals[slot])
end

local function need_user_lv(row, slot)
	local ep = G("equipment_level_param")
	local s = row_str(row, ep.need_user_lv)
	if s == "" or s == "-1" then return nil end
	return tonumber(esplit(s, ",")[slot])
end

local function plan_escalate(e, st, slot, mode, target)
	local ep = G("equipment_level_param")
	local plan = { steps = 0, levels = 0, promos = 0, silver = 0, props = {}, lv = st.info.lv[slot], gr = st.info.gr[slot] }
	local rows = lvl_rows(slot_group(st.tid, slot))
	if rows == nil or ep == nil then plan.why = "table"; return plan end
	local lv, gr = plan.lv, plan.gr
	local ucap = tn(e.user_info.user_grade, 1)
	local have_silver = S.silver or 0
	local need_props = {}
	local guard = 0
	while guard < 400 do
		guard = guard + 1
		if mode == "auto" and lv >= target then break end
		if lv >= rows.max then plan.why = plan.why or "max"; break end
		local cur, nxt = rows.map[lv], rows.map[lv + 1]
		if cur == nil or nxt == nil then plan.why = "table"; break end
		if gr < row_int(nxt, ep.correspond_grade) then

			if mode == "key" then plan.why = "promo"; break end
			local nul = need_user_lv(cur, slot)
			if nul ~= nil and nul > ucap then plan.why = "player"; break end
			local sv = row_int(cur, ep.up_product_gold)
			if plan.silver + sv > have_silver then plan.why = "silver"; break end
			local add, okp = {}, true
			for k = 1, 4 do
				local pid = row_int(cur, ep.demand_prop_1 + (k - 1) * 2)
				local cnt = row_int(cur, ep.demand_number_1 + (k - 1) * 2)
				if pid > 0 and cnt > 0 then
					add[#add + 1] = { pid, cnt }
					if LS.prop_get(pid) < (need_props[pid] or 0) + cnt then okp = false end
				end
			end
			if not okp then plan.why = "items"; break end
			plan.silver = plan.silver + sv
			for _, a in ipairs(add) do need_props[a[1]] = (need_props[a[1]] or 0) + a[2] end
			gr = row_int(nxt, ep.correspond_grade)
			plan.promos = plan.promos + 1
		else

			if lv + 1 > ucap then plan.why = "player"; break end
			local sv = row_int(cur, ep.up_lv_gold)
			if plan.silver + sv > have_silver then plan.why = "silver"; break end
			plan.silver = plan.silver + sv
			lv = lv + 1
			plan.levels = plan.levels + 1
		end
		plan.steps = plan.steps + 1
		if mode == "one" then break end
	end
	plan.lv, plan.gr = lv, gr
	for pid, n in pairs(need_props) do plan.props[#plan.props + 1] = { pid, n } end
	return plan
end

local function esc_fail(why, seq, name)
	if why == "max" then return err_reply(seq, name, "LS_trang_bi_cap_toi_da", ERR.equip_max) end
	if why == "player" then return err_reply(seq, name, "LS_cap_trang_bi_vuot_cap_nguoi_choi", ERR.equip_level) end
	if why == "silver" then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
	if why == "items" then
		toast("Khong du nguyen lieu thang pham trang bi. Mo bang GM -> TRANG BI + de them.", 6)
		return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items)
	end
	if why == "promo" then
		toast("Trang bi can THANG PHAM truoc (bam nut Thang pham).", 6)
	end
	return err_reply(seq, name, "LS_khong_the_cuong_hoa", ERR.generic)
end

function EQ.h_escalate(p, seq)
	local e = ED()
	local name = "equipment_escalate"
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil or tostring(p[2] or "0") ~= "0" then return nil end
	local slot = math.floor(tn(p[3], 0))
	if slot < 1 or slot > 4 then return err_reply(seq, name, "LS_o_trang_bi_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	local mtype = math.floor(tn(p[4], 0))
	local target = math.floor(tn(p[5], -1))
	local mode = "one"
	if mtype == 1 then mode = (target > 0) and "auto" or "key" end
	local plan = plan_escalate(e, st, slot, mode, target)
	if plan.steps == 0 then return esc_fail(plan.why, seq, name) end
	if plan.silver > 0 and not LS.money_spend("silver", plan.silver) then
		return err_reply(seq, name, "LS_khong_du_bac", ERR.silver)
	end
	for _, a in ipairs(plan.props) do LS.prop_add(a[1], -a[2]) end
	local old_lv, old_gr = st.info.lv[slot], st.info.gr[slot]
	st.info.lv[slot], st.info.gr[slot] = plan.lv, plan.gr
	stat_inc("equip_escalate", plan.steps)
	log("trang bi", sid, "o", slot, "cap", old_lv, "->", plan.lv, "pham", old_gr, "->", plan.gr, "bac", fint(plan.silver))
	return finish(e, st, st.info, seq, name)
end

local function bag_count(e, tmpl)
	local n = 0
	if type(e.user_equiment) ~= "table" then return 0 end
	for _, v in pairs(e.user_equiment) do
		if type(v) == "table" and tonumber(v.user_equiment_template) == tmpl then n = n + 1 end
	end
	return n
end

local function bag_have(e, tmpl)
	local q = eq_state()
	local v = q.bag[fint(tmpl)]
	if v ~= nil then return v end
	return bag_count(e, tmpl)
end

local function new_equip_rec(id, tmpl)
	local d, em = G("dms"), G("equipment_mould")
	local function ms(col)
		if type(d) ~= "table" or type(em) ~= "table" or em[col] == nil then return "0" end
		local ok, v = pcall(d.string, d["equipment_mould"], tmpl, em[col])
		if ok and v ~= nil then return tostring(v) end
		return "0"
	end
	return {
		user_equiment_id = id, user_equiment_template = fint(tmpl), user_equiment_name = ms("equipment_name"),
		sell_price = ms("silver_price"), user_equiment_influence_type = ms("influence_type"), equipment_type = ms("equipment_type"),
		user_equiment_ability = "0", user_equiment_grade = "1", user_equiment_exprience = "0",
		user_equiment_growup_grade = ms("grow_level"), growup_value = "0", adorn_need_ship = ms("init_ship_level"),
		equiment_picture = ms("pic_index"), equiment_track_remark = "", equiment_track_scene = "0",
		equiment_track_npc = "0", equiment_track_npc_index = "0", equiment_refine_level = "0", equiment_refine_param = "",
		refining_times = "0", refining_value_life = "0", refining_value_temp_life = "0", refining_value_attack = "0",
		refining_value_temp_attack = "0", refining_value_physical_defence = "0", refining_value_temp_physical_defence = "0",
		refining_value_skill_defence = "0", refining_value_temp_skill_defence = "0", refining_value_final_damange = "0",
		refining_value_temp_final_damange = "0", refining_value_final_lessen_damange = "0",
		refining_value_temp_final_lessen_damange = "0", prop_timestamp = fint(os.time() * 1000),
		ship_id = "0", grow_level = tonumber(ms("grow_level")) or 0,
		current_star_level = "0", current_star_exp = "0", add_attribute = "0", luck_value = 0,
	}
end

local function bag_recount(e)
	local n = 0
	for _ in pairs(e.user_equiment) do n = n + 1 end
	e.user_equiment_number = n
end

local function bag_apply(e, tmpl, n)
	if type(e.user_equiment) ~= "table" then e.user_equiment = {} end
	local ids = {}
	for id, v in pairs(e.user_equiment) do
		if type(v) == "table" and tonumber(v.user_equiment_template) == tmpl then ids[#ids + 1] = id end
	end
	if #ids == n then return false end
	table.sort(ids, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	if #ids > n then
		for i = #ids, n + 1, -1 do
			if R.eq_removed == nil then R.eq_removed = {} end
			R.eq_removed[ids[i]] = e.user_equiment[ids[i]]
			e.user_equiment[ids[i]] = nil
		end
	else
		local q = eq_state()
		for _ = 1, n - #ids do
			local id = math.floor(q.next_eid)
			while e.user_equiment[fint(id)] ~= nil do id = id + 1 end
			q.next_eid = id + 1
			e.user_equiment[fint(id)] = new_equip_rec(fint(id), tmpl)
		end
		mark()
	end
	bag_recount(e)
	return true
end

function EQ.bag_set(e, tmpl, n)
	n = math.max(0, math.floor(tn(n, 0)))
	eq_state().bag[fint(tmpl)] = n
	mark()
	bag_apply(e, tmpl, n)
end

local function bag_assert(e)
	local q = S.eq
	if q == nil or type(q.bag) ~= "table" or type(e.user_equiment) ~= "table" then return end
	local any = false
	for _ in pairs(q.bag) do any = true; break end
	if not any then return end
	local counts = {}
	for _, v in pairs(e.user_equiment) do
		if type(v) == "table" then
			local t = fint(tonumber(v.user_equiment_template) or 0)
			counts[t] = (counts[t] or 0) + 1
		end
	end
	for key, n in pairs(q.bag) do
		if (counts[key] or 0) ~= n then
			bag_apply(e, tonumber(key), n)
			R.overwrites = (R.overwrites or 0) + 1
		end
	end
end

local function max_star() return math.floor(tn(cfg_str("equipment_config", 7), 5)) end

function EQ.h_up_star(p, seq)
	local e = ED()
	local name = "equipment_up_star"
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil then return nil end
	local slot = math.floor(tn(p[2], 0))
	if slot < 1 or slot > NSLOT then return err_reply(seq, name, "LS_o_trang_bi_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	local t = st.info
	local mould = cur_mould(t, st.tid, slot)
	local mi = mould_info(mould)
	if mi == nil then return err_reply(seq, name, "LS_khong_co_mau_trang_bi", ERR.equip_missing) end
	local star = t.st[slot]
	if star >= max_star() then return err_reply(seq, name, "LS_sao_toi_da", ERR.star_max) end
	local row = star_row(mi.skill, star)
	if row == nil then return err_reply(seq, name, "LS_chua_mo_thuc_tinh", ERR.star_locked) end
	local cost = parse_cost(row.cost)
	if #cost == 0 then return err_reply(seq, name, "LS_sao_toi_da", ERR.star_max) end

	local props, silver, gold = {}, 0, 0
	for _, c in ipairs(cost) do
		if c[1] == 6 then
			props[#props + 1] = { c[2], c[3] }
		elseif c[1] == 1 then
			silver = silver + c[3]
		elseif c[1] == 2 then
			gold = gold + c[3]
		end
	end
	for _, c in ipairs(cost) do
		if c[1] == 7 and bag_have(e, c[2]) < c[3] then
			toast("Thieu trang bi/manh de thuc tinh. Mo bang GM -> TRANG BI + de them.", 6)
			return err_reply(seq, name, "LS_khong_du_manh_trang_bi", ERR.star_frag)
		end
	end
	local pneed = {}
	for _, a in ipairs(props) do pneed[a[1]] = (pneed[a[1]] or 0) + a[2] end
	for pid, n in pairs(pneed) do
		if LS.prop_get(pid) < n then
			toast("Khong du da thuc tinh / nguyen lieu. Mo bang GM -> TRANG BI + de them.", 6)
			return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items)
		end
	end
	if silver > 0 and (S.silver or 0) < silver then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
	if gold > 0 and (S.gold or 0) < gold then return err_reply(seq, name, "LS_khong_du_kc", ERR.generic) end
	if silver > 0 then LS.money_spend("silver", silver) end
	if gold > 0 then LS.money_spend("gold", gold) end
	for pid, n in pairs(pneed) do LS.prop_add(pid, -n) end
	for _, c in ipairs(cost) do
		if c[1] == 7 then EQ.bag_set(e, c[2], bag_have(e, c[2]) - c[3]) end
	end
	t.st[slot] = star + 1
	if mi.seat ~= nil and mi.seat > 0 then t.mo[slot] = mi.seat else t.mo[slot] = mould end
	stat_inc("equip_up_star")
	log("thuc tinh", sid, "o", slot, "sao", star, "->", star + 1, "mau", mould, "->", t.mo[slot])
	return finish(e, st, t, seq, name)
end

local function hard_get(e, sid)
	local q = eq_state()
	local h = q.hard[sid]
	if h == nil then
		local ship = e.user_ship[sid]
		h = EQ.conv_hard(ship and ship.hardensInfo) or EQ.conv_hard(EQ.hard_default_tbl())
		q.hard[sid] = h
		mark()
	end
	return h
end

local function hard_publish(e, sid)
	local ship = e.user_ship[sid]
	local h = eq_state().hard[sid]
	if ship == nil or h == nil then return nil end
	local tb = hard_runtime(h)
	ship.hardensInfo = tb
	if R.eq_tbl == nil then R.eq_tbl = {} end
	R.eq_tbl[sid] = tb
	return tb
end

local function blk_harden(sid, h)
	local t = { "14207", "1", fint(NSLOT) }
	for s = 1, NSLOT do
		local x = h[s]
		t[#t + 1] = fint(x.lv)
		t[#t + 1] = fint(x.ex)
		t[#t + 1] = base_prop(s, x.lv)
		t[#t + 1] = fint(#x.ent)
		for i = 1, #x.ent do t[#t + 1] = x.ent[i] end
		local rep = x.rep or {}
		t[#t + 1] = fint(#rep)
		for i = 1, #rep do t[#t + 1] = rep[i] end
		t[#t + 1] = (x.lock ~= nil) and fint(x.lock) or ""
	end
	t[#t + 1] = sid
	return t
end

local function used_types(ent, skip)
	local u = {}
	for i = 1, #ent do
		if i ~= skip then
			local _, ty = entry_parse(ent[i])
			if ty ~= nil then u[ty] = true end
		end
	end
	return u
end

local function csv_index(csv, n)
	for i, w in ipairs(esplit(csv, ",")) do
		if tonumber(w) == n then return i end
	end
	return nil
end

local function on_quench_level(slot, x)
	local appear = cfg_str("play_config", 194) or "1,3,6"
	local strong = cfg_str("play_config", 195) or "9,12,15"
	local i = csv_index(appear, x.lv)
	if i ~= nil and x.ent[i] == nil and i == #x.ent + 1 then
		local ne = roll_entry(slot, 0, used_types(x.ent, nil), nil, nil)
		if ne ~= nil then x.ent[i] = ne end
	end
	local j = csv_index(strong, x.lv)
	if j ~= nil and x.ent[j] ~= nil then
		local lvl, ty, v = entry_parse(x.ent[j])
		if lvl ~= nil and ty ~= nil then
			local ne = roll_entry(slot, math.min(lvl + 1, 3), nil, ty, v)
			if ne ~= nil then x.ent[j] = ne end
		end
	end
end

function EQ.h_harden(p, seq)
	local e = ED()
	local name = "equipment_harden"
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil then return nil end
	local slot = math.floor(tn(p[2], 0))
	local qtype = math.floor(tn(p[3], 1))
	if slot < 1 or slot > NSLOT then return err_reply(seq, name, "LS_o_trang_bi_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	if st.info.st[slot] < quench_star() then
		toast("Trang bi can " .. fint(quench_star()) .. " sao thuc tinh de toi luyen.", 6)
		return err_reply(seq, name, "LS_can_thuc_tinh", ERR.generic)
	end
	local h = hard_get(e, sid)
	local x = h[slot]
	local maxlv = math.floor(pcv(182, 15))
	if x.lv >= maxlv then return err_reply(seq, name, "LS_toi_luyen_toi_da", ERR.generic) end
	local stone = math.floor(pcv(182 + slot, 2012 + slot))
	local per = pcv(191, 400)
	local mult = pcv(192, 2)
	local chance = pcv(193, 0.2)
	local loops = (qtype == 2) and 100 or 1
	local lv0 = x.lv
	local did, silver, why, crit_any = 0, 0, nil, false
	while did < loops and x.lv < maxlv do
		local row = harden_row(slot, x.lv)
		if row == nil then why = "table"; break end
		if LS.prop_get(stone) < did + 1 then why = "stone"; break end
		if silver + row.gold > (S.silver or 0) then why = "silver"; break end
		silver = silver + row.gold
		did = did + 1
		local gain = per
		if math.random() < chance then gain = per * mult; crit_any = true end
		x.ex = x.ex + gain
		while x.lv < maxlv do
			local r2 = harden_row(slot, x.lv)
			if r2 == nil or r2.need <= 0 or x.ex < r2.need then break end
			x.ex = x.ex - r2.need
			x.lv = x.lv + 1
			on_quench_level(slot, x)
		end
		if x.lv >= maxlv then x.ex = 0 end
		if qtype == 2 and x.lv > lv0 then break end
	end
	if did == 0 then
		if why == "stone" then
			toast("Het da toi luyen (prop " .. fint(stone) .. "). Mo bang GM -> TRANG BI + de them.", 6)
			return err_reply(seq, name, "LS_khong_du_da_toi_luyen", ERR.items)
		end
		if why == "silver" then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
		return err_reply(seq, name, "LS_khong_the_toi_luyen", ERR.generic)
	end
	if silver > 0 then LS.money_spend("silver", silver) end
	LS.prop_add(stone, -did)
	mark()
	hard_publish(e, sid)

	local F = commit_hero(e, sid, {})
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_harden(sid, h))
	blocks[#blocks + 1] = "14208"
	blocks[#blocks + 1] = crit_any and "2" or "1"
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, sid, F))
	stat_inc("equip_harden", did)
	LS.save_state(true)
	log("toi luyen", sid, "o", slot, "x" .. did, "cap", lv0, "->", x.lv, "bac", fint(silver))
	return reply(seq, name, blocks)
end

function EQ.h_harden_replace(p, seq)
	local e = ED()
	local name = "equipment_harden_replace"
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil then return nil end
	local slot = math.floor(tn(p[2], 0))
	if slot < 1 or slot > NSLOT then return err_reply(seq, name, "LS_o_trang_bi_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	local h = hard_get(e, sid)
	local x = h[slot]
	if #x.ent == 0 then return err_reply(seq, name, "LS_chua_co_thuoc_tinh", ERR.generic) end
	local locked = (x.lock ~= nil and x.ent[x.lock + 1] ~= nil) and 1 or 0
	if locked >= #x.ent then return err_reply(seq, name, "LS_khong_co_thuoc_tinh_chua_khoa", ERR.generic) end
	local lockstone = math.floor(pcv(189, 2019))
	if locked > 0 and LS.prop_get(lockstone) < locked then
		toast("Het da khoa (prop " .. fint(lockstone) .. "). Mo bang GM -> TRANG BI + de them.", 6)
		return err_reply(seq, name, "LS_khong_du_da_khoa", ERR.items)
	end
	local old = ecopy(x.ent)
	local avoid = used_types(x.ent, nil)
	x.rep = {}
	for i = 1, #x.ent do
		x.rep[i] = old[i]
		if not (x.lock ~= nil and x.lock + 1 == i) then
			local lvl, ty = entry_parse(old[i])
			avoid[ty or -1] = nil
			local ne = roll_entry(slot, math.min(lvl or 0, 3), avoid, nil, nil)
			if ne ~= nil then
				x.ent[i] = ne
				local _, nty = entry_parse(ne)
				if nty ~= nil then avoid[nty] = true end
			end
		end
	end
	if locked > 0 then LS.prop_add(lockstone, -locked) end
	mark()
	hard_publish(e, sid)
	local F = commit_hero(e, sid, {})
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_harden(sid, h))
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, sid, F))
	stat_inc("equip_harden_replace")
	LS.save_state(true)
	log("thay thuoc tinh toi luyen", sid, "o", slot, "khoa", locked)
	return reply(seq, name, blocks)
end

function EQ.h_harden_lock(p, seq)
	local e = ED()
	local name = "equipment_harden_locking"
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil then return nil end
	local slot = math.floor(tn(p[2], 0))
	local idx = math.floor(tn(p[3], 0))
	local op = math.floor(tn(p[4], 1))
	if slot < 1 or slot > NSLOT then return err_reply(seq, name, "LS_o_trang_bi_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	local h = hard_get(e, sid)
	local x = h[slot]
	if idx < 1 or x.ent[idx] == nil then return err_reply(seq, name, "LS_thuoc_tinh_sai", ERR.generic) end
	if op == 1 then
		if LS.prop_get(math.floor(pcv(189, 2019))) < 1 then
			toast("Het da khoa. Mo bang GM -> TRANG BI + de them.", 6)
			return err_reply(seq, name, "LS_khong_du_da_khoa", ERR.items)
		end
		x.lock = idx - 1
	else
		x.lock = nil
	end
	mark()
	hard_publish(e, sid)
	stat_inc("equip_harden_lock")
	LS.save_state(true)
	return reply(seq, name, blk_harden(sid, h))
end

local function rank_rows(group)
	local c = ecache()
	c.rank = c.rank or {}
	local g = c.rank[group]
	if g ~= nil then return g or nil end
	local d, er = G("dms"), G("equipment_rank_link")
	local res = false
	if type(d) == "table" and type(er) == "table" and type(d["equipment_rank_link"]) == "table" and group ~= nil then
		local ok, rows = pcall(d.searchs, d["equipment_rank_link"], er.library_group, group)
		if ok and type(rows) == "table" and #rows > 0 then
			res = {}
			for i = 1, #rows do
				local rw = rows[i]
				res[i] = { id = row_int(rw, er.id), cap = row_int(rw, 2), silver = row_int(rw, er.need_silver),
					grade = row_int(rw, er.compound_equipment_mould), mat = row_str(rw, er.need_material),
					nul = row_str(rw, er.need_user_lv) }
			end
			table.sort(res, function(a, b) return a.id < b.id end)
		end
	end
	c.rank[group] = res
	return res or nil
end

local function refine_need(lv)
	local c = ecache()
	c.refine = c.refine or {}
	local v = c.refine[lv]
	if v == nil then
		v = false
		local d = G("dms")
		if type(d) == "table" and type(d["equipment_refining_experience_param"]) == "table" then
			local ok, sv = pcall(d.string, d["equipment_refining_experience_param"], lv, 3)
			if ok and sv ~= nil then v = tonumber(sv) or false end
		end
		c.refine[lv] = v
	end
	return v or nil
end

local function supply_exp(tmpl)
	local c = ecache()
	c.supply = c.supply or {}
	local v = c.supply[tmpl]
	if v == nil then
		v = 0
		local d, em = G("dms"), G("equipment_mould")
		if type(d) == "table" and type(em) == "table" and type(d["equipment_mould"]) == "table" then
			local ok, sv = pcall(d.string, d["equipment_mould"], tmpl, em.initial_supply_escalate_exp)
			if ok and sv ~= nil then v = tonumber(sv) or 0 end
		end
		c.supply[tmpl] = v
	end
	return v
end

local function cur_field(kind)
	if kind == 3 then return "user_honour", "dh" end
	if kind == 18 then return "all_glories", "dg" end
	return nil, nil
end

local function cur_add(e, field, dkey, n)
	local u = e.user_info
	if type(u) ~= "table" then return false end
	local now = tn(u[field], 0)
	local new = math.max(0, now + n)
	u[field] = fint(new)
	local q = eq_state()
	q[dkey] = tn(q[dkey], 0) + (new - now)
	mark()
	return true
end

function EQ.cur_world(e)
	local u = e.user_info
	R.eq_cur0 = nil
	if type(u) ~= "table" then return end
	R.eq_cur0 = { h = tonumber(u.user_honour), g = tonumber(u.all_glories) }
	local q = eq_state()
	if R.eq_cur0.h ~= nil and tn(q.dh, 0) ~= 0 then u.user_honour = fint(math.max(0, R.eq_cur0.h + tn(q.dh, 0))) end
	if R.eq_cur0.g ~= nil and tn(q.dg, 0) ~= 0 then u.all_glories = fint(math.max(0, R.eq_cur0.g + tn(q.dg, 0))) end
end

local function bag_remove_keys(e, keys)
	local q = eq_state()
	local touched = {}
	for _, key in ipairs(keys) do
		local rec = e.user_equiment[key]
		if rec ~= nil then
			if R.eq_removed == nil then R.eq_removed = {} end
			R.eq_removed[key] = rec
			e.user_equiment[key] = nil
			touched[fint(tonumber(rec.user_equiment_template) or 0)] = true
		end
	end

	for tmpl in pairs(touched) do q.bag[tmpl] = bag_count(e, tonumber(tmpl)) end
	bag_recount(e)
	mark()
end

local function find_equip_rec(e, id)
	if type(e.user_equiment) ~= "table" then return nil, nil end
	local rec = e.user_equiment[id]
	if type(rec) == "table" then return rec, id end
	for k, v in pairs(e.user_equiment) do
		if type(v) == "table" and tostring(v.user_equiment_id) == id then return v, k end
	end
	return nil, nil
end

EQ.TR_FOD = { 183, 184, 185, 186, 187, 188 }
EQ.FOD_LOW, EQ.FOD_TOP = 30, 60
EQ.CUR_LOW, EQ.CUR_TOP = 40000, 200000

function EQ.floor(e)
	if type(S.cfg) == "table" and S.cfg.eq_auto == false then return end
	if type(e.user_equiment) ~= "table" or type(e.user_info) ~= "table" then return end
	local n = 0
	for i = 1, #EQ.TR_FOD do
		local m = EQ.TR_FOD[i]
		if supply_exp(m) > 0 and bag_have(e, m) < EQ.FOD_LOW then
			EQ.bag_set(e, m, EQ.FOD_TOP)
			n = n + 1
		end
	end
	local u = e.user_info

	local c1 = tonumber(u.user_honour) or 0
	if c1 < EQ.CUR_LOW then cur_add(e, "user_honour", "dh", EQ.CUR_TOP - c1); n = n + 1 end
	local c2 = tonumber(u.all_glories) or 0
	if c2 < EQ.CUR_LOW then cur_add(e, "all_glories", "dg", EQ.CUR_TOP - c2); n = n + 1 end
	if n > 0 then
		stat_inc("eq_floor", n)
		mark()
	end
end

local function treasure_do(p, seq, name)
	local onekey = (name == "treasure_onekey_escalate")
	local e = ED()
	local sid = tostring(p[1] or "")
	if e.user_ship[sid] == nil then return nil end
	local idcsv = tostring(p[2] or "")
	local slot = math.floor(tn(p[3], 0))
	if slot < 5 or slot > NSLOT then return err_reply(seq, name, "LS_o_bao_vat_sai", ERR.generic) end
	local st = ship_ctx(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.equip_missing) end
	local rr = rank_rows(slot_group(st.tid, slot))
	if rr == nil then return err_reply(seq, name, "LS_khong_co_bang_bao_vat", ERR.generic) end
	local t = st.info
	local grade, lv, ex = t.gr[slot], t.lv[slot], t.ex[slot]
	local crow = rr[grade + 1]
	if crow == nil then return err_reply(seq, name, "LS_bao_vat_pham_toi_da", ERR.equip_max) end

	local ids, seen = {}, {}
	for w in string.gmatch(idcsv, "[^,]+") do
		local id = string.match(w, "^%s*(%-?%d+)%s*$")
		if id ~= nil and id ~= "0" and id ~= "-1" and not seen[id] then seen[id] = true; ids[#ids + 1] = id end
	end
	local want_type = (slot == 5) and 4 or 5
	local fod, bad = {}, nil
	for _, id in ipairs(ids) do
		local rec, key = find_equip_rec(e, id)
		if rec == nil then
			bad = bad or "missing"
		else
			local tmpl = math.floor(tn(rec.user_equiment_template, 0))
			local et = tonumber(rec.equipment_type)
			local sx = supply_exp(tmpl)
			if sx > 0 and (et == nil or et == want_type) then fod[#fod + 1] = { key = key, exp = sx } else bad = bad or "invalid" end
		end
	end

	local factor = tn(cfg_str("equipment_config", 6), 50)
	local have_silver = S.silver or 0
	local spent = 0
	local cur_spent, cur_key = { user_honour = 0, all_glories = 0 }, {}
	local exp, nlv, ngr = ex, lv, grade
	local used, nused = {}, 0
	local promos = 0
	local label = { user_honour = "tien Dau truong", all_glories = "tien Thu thach" }

	local function promo_block(row)
		if row.nul ~= "" and row.nul ~= "-1" then
			local need = tonumber(esplit(row.nul, ",")[slot - 4])
			if need ~= nil and need > tn(e.user_info.user_grade, 1) then return "player" end
		end
		if spent + row.silver > have_silver then return "silver" end
		local mt = esplit(row.mat, ",")
		local field = cur_field(tonumber(mt[2]))
		local mneed = math.floor(tn(mt[3], 0))
		if field ~= nil and mneed > 0 and tn(e.user_info[field], 0) - cur_spent[field] < mneed then return "currency", field, mneed end
		return nil
	end
	local function promo_apply(row)
		spent = spent + row.silver
		local mt = esplit(row.mat, ",")
		local field, dkey = cur_field(tonumber(mt[2]))
		local mneed = math.floor(tn(mt[3], 0))
		if field ~= nil and mneed > 0 then cur_spent[field] = cur_spent[field] + mneed; cur_key[field] = dkey end
		promos = promos + 1
		return (row.grade > ngr) and row.grade or (ngr + 1)
	end
	local function fail(why, field, mneed)
		if why == "player" then return err_reply(seq, name, "LS_cap_nguoi_choi_chua_du", ERR.equip_level) end
		if why == "silver" then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
		if why == "currency" then
			toast("Khong du " .. label[field] .. " de thang pham bao vat (" .. fint(mneed) .. "). Mo bang GM -> TRANG BI + de them.", 6)
			return err_reply(seq, name, "LS_khong_du_tien_te", ERR.items)
		end
		if why == "fodder" then
			return err_reply(seq, name, (bad == "invalid") and "LS_trang_bi_khong_hop_le" or "LS_khong_co_trang_bi", ERR.equip_missing)
		end
		if why == "cap" then
			toast("Bao vat da dat cap toi da cua pham hien tai. Hay THANG PHAM truoc.", 6)
			return err_reply(seq, name, "LS_bao_vat_toi_cap", ERR.equip_max)
		end
		if why == "table" then return err_reply(seq, name, "LS_thieu_bang_exp_bao_vat", ERR.generic) end
		return err_reply(seq, name, "LS_bao_vat_pham_toi_da", ERR.equip_max)
	end
	local function commit()
		if spent > 0 then LS.money_spend("silver", spent) end
		for field, n in pairs(cur_spent) do
			if n > 0 then cur_add(e, field, cur_key[field], -n) end
		end
		if nused > 0 then bag_remove_keys(e, used) end
		t.gr[slot], t.lv[slot], t.ex[slot] = ngr, nlv, exp
		return finish(e, st, t, seq, name)
	end

	if not onekey and #ids == 0 then
		if nlv < crow.cap then
			toast("Bao vat can dat cap toi da cua pham hien tai (" .. fint(crow.cap) .. ") truoc khi thang pham.", 6)
			return err_reply(seq, name, "LS_chua_toi_cap_thang_pham", ERR.generic)
		end
		local up = crow
		if up.grade <= ngr then
			up = nil
			for i = 1, #rr do if rr[i].cap == nlv and rr[i].grade > ngr then up = rr[i]; break end end
		end
		if up == nil then return fail("max") end
		local why, fd, mn = promo_block(up)
		if why ~= nil then return fail(why, fd, mn) end
		ngr = promo_apply(up)
		exp = 0
		stat_inc("treasure_promote")
		log("bao vat", sid, "o", slot, "thang pham", grade, "->", ngr, "bac", fint(spent))
		return commit()
	end

	if not onekey then
		if nlv >= crow.cap then return fail("cap") end
		if #fod == 0 then return fail("fodder") end
		local total = 0
		for _, f in ipairs(fod) do total = total + f.exp; nused = nused + 1; used[nused] = f.key end
		spent = factor * total
		if spent > have_silver then return fail("silver") end
		exp = exp + total
		while nlv < crow.cap do
			local need = refine_need(nlv)
			if need == nil or need <= 0 then break end
			if exp >= need then exp = exp - need; nlv = nlv + 1 else break end
		end
		if nlv >= crow.cap then exp = 0 end
		stat_inc("treasure_feed", nused)
		log("bao vat", sid, "o", slot, "nuot", nused, "trang bi +exp", fint(total), "cap", lv, "->", nlv, "bac", fint(spent))
		return commit()
	end

	local maxlv = rr[#rr].cap
	local target = math.floor(tn(p[4], 0))
	if target <= 0 then target = crow.cap end
	if target > maxlv then target = maxlv end
	if target <= nlv and nlv < crow.cap then target = nlv + 1 end
	local why, wf, wn
	local fi, guard = 1, 0
	while guard < 20000 do
		guard = guard + 1
		local row = rr[ngr + 1]
		if row == nil then why = why or "max"; break end
		if nlv >= row.cap then
			if nlv >= target then break end
			local w, fd, mn = promo_block(row)
			if w ~= nil then why, wf, wn = w, fd, mn; break end
			ngr = promo_apply(row)
		else
			local need = refine_need(nlv)
			if need == nil or need <= 0 then why = "table"; break end
			if exp >= need then
				exp = exp - need
				nlv = nlv + 1
			elseif nlv >= target then
				break
			else
				local f = fod[fi]
				if f == nil then why = "fodder"; break end
				local cost = factor * f.exp
				if spent + cost > have_silver then why = "silver"; break end
				spent = spent + cost
				exp = exp + f.exp
				nused = nused + 1
				used[nused] = f.key
				fi = fi + 1
			end
		end
	end
	local rowe = rr[ngr + 1]
	if nlv >= (rowe ~= nil and rowe.cap or maxlv) then exp = 0 end
	if nused == 0 and promos == 0 and nlv == lv then
		if why == nil then why = (rowe == nil) and "max" or "cap" end
		return fail(why, wf, wn)
	end
	if why ~= nil and why ~= "max" and nlv < target then
		local txt = { silver = "het bac", fodder = "het trang bi nuot", player = "cap nguoi choi chua du",
			currency = "thieu " .. tostring(label[wf] or "tien thang pham"), table = "thieu bang EXP" }
		toast("Nang nhanh bao vat dung o cap " .. fint(nlv) .. " (" .. (txt[why] or why) .. ")", 6)
	end
	stat_inc("treasure_onekey")
	log("bao vat", sid, "o", slot, "nang nhanh muc tieu", target, "cap", lv, "->", nlv, "pham", grade, "->", ngr, "thang pham", promos,
		"nuot", nused, "bac", fint(spent), why and ("dung: " .. why) or "")
	return commit()
end

function EQ.h_treasure(p, seq) return treasure_do(p, seq, "treasure_escalate") end
function EQ.h_treasure_onekey(p, seq) return treasure_do(p, seq, "treasure_onekey_escalate") end

function EQ.tick(e)
	local q = eq_state()
	if R.eq_tbl == nil then R.eq_tbl = {} end
	for sid, ship in pairs(e.user_ship) do
		if type(ship) == "table" then
			local h = q.hard[sid]
			if h ~= nil then

				if ship.hardensInfo == nil or ship.hardensInfo ~= R.eq_tbl[sid] then
					local want = hard_runtime(h)
					if ship.hardensInfo ~= nil and hard_sig(ship.hardensInfo) == hard_sig(want) then
						R.eq_tbl[sid] = ship.hardensInfo
					else
						ship.hardensInfo = want
						R.eq_tbl[sid] = want
						R.overwrites = (R.overwrites or 0) + 1
					end
				end
			elseif ship.hardensInfo == nil then
				ship.hardensInfo = hard_default_tbl()
			end
		end
	end
	bag_assert(e)
	EQ.floor(e)
end

function EQ.max_info(tid, cap, keep_hard, rnd)
	local ep = G("equipment_level_param")
	local t = { lv = {}, gr = {}, ex = {}, st = {}, mo = {} }
	local dm = default_moulds(tid)
	local smax = max_star()
	cap = math.max(1, math.floor(tonumber(cap) or 1))
	for s = 1, NSLOT do
		local lv, gr = 1, 0
		if s <= 4 then
			local rows = lvl_rows(slot_group(tid, s))
			if rows ~= nil and ep ~= nil then
				lv = math.max(1, math.min(rows.max, cap))
				while lv > 1 and rows.map[lv] == nil do lv = lv - 1 end
				local row = rows.map[lv]
				if row ~= nil then gr = math.max(0, row_int(row, ep.correspond_grade)) end
			end
		else
			local rr = rank_rows(slot_group(tid, s))
			if rr ~= nil and #rr > 0 then
				gr = #rr - 1
				lv = math.max(1, math.min(rr[#rr].cap > 0 and rr[#rr].cap or 1, math.max(cap, 1)))
			end
		end
		local mould, star = dm[s], 0
		for k = 0, smax - 1 do
			local mi = mould_info(mould)
			if mi == nil then break end
			local row = star_row(mi.skill, k)
			if row == nil or #parse_cost(row.cost) == 0 then break end
			star = k + 1
			if mi.seat ~= nil and mi.seat > 0 then mould = mi.seat end
		end
		t.lv[s], t.gr[s], t.ex[s], t.st[s] = lv, gr, 0, star
		t.mo[s] = (star > 0) and mould or dm[s]
	end
	local hard = {}
	for s = 1, NSLOT do
		local lv = 0
		while lv < 500 and harden_row(s, lv + 1) ~= nil do lv = lv + 1 end
		hard[s] = { lv = lv, ex = 0, ent = hard_max_entries(s, keep_hard and keep_hard[s] or nil, rnd), rep = {} }
	end
	return info_pack(t), hard
end

function EQ.restore(e)
	if type(e.user_equiment) == "table" then
		for id in pairs(e.user_equiment) do
			if tonumber(id) ~= nil and tonumber(id) >= EID_BASE then e.user_equiment[id] = nil end
		end
		if R.eq_removed ~= nil then
			for id, rec in pairs(R.eq_removed) do
				if not (tonumber(id) ~= nil and tonumber(id) >= EID_BASE) then e.user_equiment[id] = rec end
			end
		end
		bag_recount(e)
	end
	R.eq_removed = nil
	R.eq_tbl = {}
	if R.eq_cur0 ~= nil and type(e.user_info) == "table" then
		if R.eq_cur0.h ~= nil then e.user_info.user_honour = fint(R.eq_cur0.h) end
		if R.eq_cur0.g ~= nil then e.user_info.all_glories = fint(R.eq_cur0.g) end
	end
	if R.rec ~= nil then
		for sid, r in pairs(R.rec) do
			local sh = e.user_ship[sid]
			if type(sh) == "table" and r.hard_orig ~= nil then sh.hardensInfo = r.hard_orig end
		end
	end
end

local function material_props()
	local c = ecache()
	if c.mats ~= nil then return c.mats end
	local set, list = {}, {}
	local function add(id)
		id = tonumber(id)
		if id ~= nil and id > 0 and not set[id] and prop_known(id) then set[id] = true; list[#list + 1] = id end
	end
	local d, ep, es = G("dms"), G("equipment_level_param"), G("equipment_star")
	if type(d) == "table" and type(ep) == "table" and type(d["equipment_level_param"]) == "table" then
		for _, row in ipairs(d["equipment_level_param"]) do
			for k = 1, 4 do add(row_int(row, ep.demand_prop_1 + (k - 1) * 2)) end
		end
	end
	if type(d) == "table" and type(es) == "table" and type(d["equipment_star"]) == "table" then
		for _, row in ipairs(d["equipment_star"]) do
			for _, cst in ipairs(parse_cost(row_str(row, es.cost_items))) do
				if cst[1] == 6 then add(cst[2]) end
			end
		end
	end
	for r = 183, 190 do add(pcv(r, 0)) end
	table.sort(list)
	c.mats = list
	return list
end

function LS.gm_grant_equip(n)
	if not LS.ready() then return nil end
	local e = ED()
	n = math.max(1, math.floor(tn(n, 99)))
	local list = material_props()
	for i = 1, #list do
		LS.prop_set(list[i], math.min(999999, LS.prop_get(list[i]) + n))
	end

	local nbag = 0
	for _, sid in ipairs(formation_sids(e)) do
		local st = ship_ctx(e, sid)
		if st ~= nil then
			for slot = 1, NSLOT do
				local mould = cur_mould(st.info, st.tid, slot)
				local mi = mould_info(mould)
				if mi ~= nil then
					for star = st.info.st[slot], max_star() - 1 do
						local row = star_row(mi.skill, star)
						if row ~= nil then
							for _, c in ipairs(parse_cost(row.cost)) do
								if c[1] == 7 then
									local want = math.max(bag_have(e, c[2]), 5 * c[3])
									if want ~= bag_have(e, c[2]) then EQ.bag_set(e, c[2], want); nbag = nbag + 1 end
								end
							end
						end

					end
				end
			end
		end
	end

	for mould = 183, 188 do
		if bag_have(e, mould) < EQ.FOD_TOP then EQ.bag_set(e, mould, EQ.FOD_TOP); nbag = nbag + 1 end
	end
	cur_add(e, "user_honour", "dh", 100 * n)
	cur_add(e, "all_glories", "dg", 100 * n)
	stat_inc("gm_equip")
	LS.save_state(true)
	log("GM TRANG BI: +", n, "cho", #list, "loai vat lieu;", nbag, "loai trang bi/manh")
	return #list, nbag
end

EQ.info_parse, EQ.info_pack = info_parse, info_pack
EQ.plan_escalate = plan_escalate
EQ.bag_have, EQ.bag_count = bag_have, bag_count
EQ.hard_get, EQ.hard_runtime, EQ.hard_sig = hard_get, hard_runtime, hard_sig
EQ.mould_info, EQ.star_row = mould_info, star_row
EQ.cur_mould = cur_mould

end
init_eq()
end

do
local function init_ws()

local WS_ID0 = 700000000
local NPOS = 4

local function wsplit(s, sep)
	local t, init = {}, 1
	s = tostring(s or "")
	while true do
		local p = string.find(s, sep, init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + #sep
	end
	return t
end

local function wdeep(v)
	if type(v) ~= "table" then return v end
	local o = {}
	for k, x in pairs(v) do
		if k ~= "extraInfo" then o[k] = wdeep(x) end
	end
	return o
end

local function wnum(x)
	x = tonumber(x) or 0
	x = math.floor(x * 1000 + 0.5) / 1000
	if x == 0 then return "0" end
	if x == math.floor(x) then return string.format("%.0f", x) end
	local s = string.format("%.3f", x)
	s = string.gsub(s, "0+$", "")
	s = string.gsub(s, "%.$", "")
	return s
end

local function wcache()
	if R.ws_cache == nil then R.ws_cache = {} end
	return R.ws_cache
end

local function ws_state()
	if type(S.ws) ~= "table" then S.ws = {} end
	local w = S.ws
	if tonumber(w.nid) == nil then w.nid = WS_ID0 end
	if type(w.sp) ~= "table" then w.sp = {} end
	if type(w.del) ~= "table" then w.del = {} end
	if type(w.seat) ~= "table" then w.seat = {} end
	return w
end

local function tcol(tname, id, cname)
	local d, sc = G("dms"), G(tname)
	if type(d) ~= "table" or type(sc) ~= "table" or type(d[tname]) ~= "table" or sc[cname] == nil then return nil end
	local ok, v = pcall(d.string, d[tname], id, sc[cname])
	if ok and v ~= nil and v ~= "" then return tostring(v) end
	return nil
end

local function tsearch(tname, c1, v1, c2, v2)
	local d, sc = G("dms"), G(tname)
	if type(d) ~= "table" or type(sc) ~= "table" or type(d[tname]) ~= "table" then return {} end
	local ok, rows = pcall(function()
		if c2 ~= nil then return d.searchs(d[tname], sc[c1], v1, sc[c2], v2) end
		return d.searchs(d[tname], sc[c1], v1)
	end)
	if ok and type(rows) == "table" then return rows end
	return {}
end

local function rcell(row, tname, cname)
	local d, sc = G("dms"), G(tname)
	local ok, v = pcall(function() return d.atos(row, sc[cname]) end)
	if ok and v ~= nil then return tostring(v) end
	return ""
end

local function rnum(row, tname, cname)
	local d, sc = G("dms"), G(tname)
	local ok, v = pcall(function() return d.atoi(row, sc[cname]) end)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function mould(mid)
	mid = tonumber(mid)
	if mid == nil then return nil end
	local c = wcache()
	c.mould = c.mould or {}
	local m = c.mould[mid]
	if m == nil then
		m = false
		local suit = tonumber(tcol("fight_spirit_mould", mid, "suit_id"))
		local quality = tonumber(tcol("fight_spirit_mould", mid, "quality"))
		if suit ~= nil and quality ~= nil then
			m = { id = mid, suit = suit, quality = quality,
				pos = tonumber(tcol("fight_spirit_mould", mid, "pos")) or 0,
				rlib = tonumber(tcol("fight_spirit_mould", mid, "random_lib_id")) or 1,
				mlib = tonumber(tcol("fight_spirit_mould", mid, "main_lib_id")) or 1,
				alib = tonumber(tcol("fight_spirit_mould", mid, "awake_lib_id")) or 1 }
		end
		c.mould[mid] = m
	end
	return m or nil
end

local function lvl_info(q)
	local c = wcache()
	c.lvl = c.lvl or {}
	local t = c.lvl[q]
	if t == nil then
		t = { cap = 0, tot = {}, nxt = {} }
		if type(G("fight_spirit_strengthen_mould")) == "table" then
			for _, row in ipairs(tsearch("fight_spirit_strengthen_mould", "quality", q)) do
				local lv = rnum(row, "fight_spirit_strengthen_mould", "cur_lev")
				t.tot[lv] = rnum(row, "fight_spirit_strengthen_mould", "total_exp")
				t.nxt[lv] = rnum(row, "fight_spirit_strengthen_mould", "next_lev_exp")
				if lv > t.cap then t.cap = lv end
			end
		end
		c.lvl[q] = t
	end
	return t
end

local function exp_to(q, lv) return lvl_info(q).tot[lv] or 0 end

local function level_for(q, total)
	local t = lvl_info(q)
	local lv = 0
	for l = 0, t.cap do
		if t.tot[l] ~= nil and t.tot[l] <= total then lv = l end
	end
	return lv
end

local function parse_one(part)
	local t, b, g = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)%s*:%s*(%-?[%d%.]+)")
	if t == nil then return nil end
	return { t = tonumber(t), b = tonumber(b), g = tonumber(g) }
end

local function main_entries(lid, q)
	local c = wcache()
	c.main = c.main or {}
	local key = fint(lid) .. ":" .. fint(q)
	local r = c.main[key]
	if r == nil then
		r = {}
		for _, row in ipairs(tsearch("fight_spirit_talent_mould", "lib_type", 2, "lib_id", lid)) do
			if rnum(row, "fight_spirit_talent_mould", "quality") == q then
				for _, part in ipairs(wsplit(rcell(row, "fight_spirit_talent_mould", "strength_attr"), "|")) do
					local en = parse_one(part)
					if en ~= nil then r[#r + 1] = en end
				end
			end
		end
		c.main[key] = r
	end
	return r
end

local function rand_pool(lid, q)
	if q > 5 then q = 5 end
	local c = wcache()
	c.rpool = c.rpool or {}
	local key = fint(lid) .. ":" .. fint(q)
	local r = c.rpool[key]
	if r == nil then
		r = {}
		for _, row in ipairs(tsearch("fight_spirit_talent_mould", "lib_type", 1, "lib_id", lid)) do
			if rnum(row, "fight_spirit_talent_mould", "quality") == q then
				local en = parse_one(rcell(row, "fight_spirit_talent_mould", "strength_attr"))
				if en ~= nil then r[#r + 1] = en end
			end
		end
		c.rpool[key] = r
	end
	return r
end

local function pool_bg(lid, q, t)
	for _, en in ipairs(rand_pool(lid, q)) do
		if en.t == t then return en.b, en.g end
	end
	return nil, nil
end

local function awake_pool(lid)
	local c = wcache()
	c.apool = c.apool or {}
	local r = c.apool[lid]
	if r == nil then
		r = {}
		for _, row in ipairs(tsearch("fight_spirit_talent_mould", "lib_type", 3, "lib_id", lid)) do
			local tid = rnum(row, "fight_spirit_talent_mould", "awake_talent_id")
			if tid > 0 then r[#r + 1] = tid end
		end
		c.apool[lid] = r
	end
	return r
end

local function pcost(s)
	local out = {}
	for _, part in ipairs(wsplit(s or "", "|")) do
		local a, b, c = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
		if a ~= nil then out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	end
	return out
end

local function cfg_group_cost(row)
	local s = cfg_str("play_config", row)
	if s == nil then return {} end
	return pcost(wsplit(s, "!")[1])
end

local function cfg_stones()
	local c = wcache()
	if c.stones == nil then
		local st = { order = {}, exp = {} }
		for _, part in ipairs(wsplit(cfg_str("play_config", 228) or "", "|")) do
			local id, ex = string.match(part, "^%s*%-?%d+%s*,%s*(%d+)%s*,%s*%d+%s*:%s*([%d%.]+)")
			if id ~= nil then
				st.order[#st.order + 1] = { tonumber(id), tonumber(ex) }
				st.exp[tonumber(id)] = tonumber(ex)
			end
		end
		c.stones = st
	end
	return c.stones
end

local function cfg_silver_per_exp()
	local v = wsplit(cfg_str("play_config", 229) or "", ",")[3]
	return tonumber(v) or 10
end

local function cfg_base_material()
	local l = pcost(cfg_str("play_config", 230))
	return l[1]
end

local function cfg_compose_silver(q)
	for _, part in ipairs(wsplit(cfg_str("play_config", 231) or "", "|")) do
		local qq, a, b, n = string.match(part, "^%s*(%d+)%s*:%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%d+)")
		if qq ~= nil and tonumber(qq) == q then return tonumber(n) or 0 end
	end
	return nil
end

local function cfg_nrand(q)
	for _, part in ipairs(wsplit(cfg_str("play_config", 227) or "", "|")) do
		local qq, n = string.match(part, "^%s*(%d+)%s*,%s*(%d+)")
		if qq ~= nil and tonumber(qq) == q then return tonumber(n) or 1 end
	end
	return 1
end

local function cfg_ret_rate()
	return tonumber(wsplit(cfg_str("play_config", 237) or "", ",")[1]) or 0.5
end

local function cfg_suit()
	local out = {}
	for i, part in ipairs(wsplit(cfg_str("play_config", 225) or "", "|")) do
		local t, v = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
		if t ~= nil then out[i] = { tonumber(t), tonumber(v) } end
	end
	return out
end

local function awake_quality()
	local s = wsplit(cfg_str("play_config", 236) or "", ",")[1]
	local b = tonumber(wsplit(s or "", "|")[2])
	return b or 6
end

local function parse_ents(str)
	local out = {}
	for _, part in ipairs(wsplit(str or "", "|")) do
		local t, b, g = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)%s*,%s*(%-?[%d%.]+)")
		if t ~= nil and tonumber(t) >= 0 then out[#out + 1] = { t = tonumber(t), b = tonumber(b), g = tonumber(g) } end
	end
	return out
end

local function ents_str(list)
	if #list == 0 then return "-1,0,0" end
	local parts = {}
	for i, en in ipairs(list) do parts[i] = fint(en.t) .. "," .. wnum(en.b) .. "," .. wnum(en.g) end
	return table.concat(parts, "|")
end

local function main_str(m, q, level)
	local ents = main_entries(m.mlib, q)
	if #ents == 0 then return nil end
	local k = math.max(level - 1, 1)
	local parts = {}
	for i, en in ipairs(ents) do parts[i] = fint(en.t) .. "," .. wnum(en.b) .. "," .. wnum(en.g * k) end
	return table.concat(parts, "|")
end

local function ri(n) return math.random(1, n) end

local function pick_types(pool, n, mode, seed)
	local out = {}
	local avail = {}
	for _, en in ipairs(pool) do avail[#avail + 1] = en end
	local start = 0
	if mode == "det" and #avail > 0 then start = math.floor(seed or 0) % #avail end
	for i = 1, n do
		if #avail == 0 then break end
		local idx
		if mode == "det" then idx = (start % #avail) + 1 else idx = ri(#avail) end
		out[#out + 1] = avail[idx]
		table.remove(avail, idx)
	end
	return out
end

local function fresh_random(m, q, seed, active)
	local pool = rand_pool(m.rlib, q)
	local picks = pick_types(pool, cfg_nrand(q), active and "rnd" or "det", seed)
	local ents = {}
	for i, en in ipairs(picks) do ents[i] = { t = en.t, b = active and en.b or 0, g = 0 } end
	return ents
end

local function is_slot_empty(en) return (en.b or 0) == 0 and (en.g or 0) == 0 end

local function new_prop(main, random, awake)
	return { main = main, random = random, randomEhanceNumber = 0, randomStrId = "0", awake = awake or 0, suitActiveState = "0" }
end

local function rebuild_list(e)
	local ids = {}
	for id in pairs(e.all_fight_spirits) do ids[#ids + 1] = id end
	table.sort(ids, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	local l = {}
	for i, id in ipairs(ids) do l[i] = e.all_fight_spirits[id] end
	e.all_fight_spirits_list = l
end

local function normalize(e)
	for id, rec in pairs(e.all_fight_spirits) do
		if type(rec) == "table" and type(rec.addProperty) == "table" then
			local m = mould(rec.mouldId)
			if m ~= nil and #parse_ents(rec.addProperty.random) == 0 then
				local zs = fresh_random(m, tonumber(rec.quality) or m.quality, tonumber(id) or 0, false)
				if #zs > 0 then rec.addProperty.random = ents_str(zs) end
			end
		end
	end
end

local function parse_seat(str)
	local out = {}
	local parts = wsplit(str or "", ",")
	for i = 1, NPOS do
		local v = tonumber(parts[i])
		out[i] = (v ~= nil and v > 0) and v or -1
	end
	return out
end

local function seat_str(arr)
	local t = {}
	for i = 1, NPOS do
		local v = tonumber(arr[i])
		t[i] = fint((v ~= nil and v > 0) and v or -1)
	end
	return table.concat(t, ",")
end

local function get_seat(e, skey)
	local st = e.all_ship_fight_spirit_info
	local cur = type(st) == "table" and st[skey] or nil
	local out = {}
	for i = 1, NPOS do
		local v = type(cur) == "table" and tonumber(cur[i]) or nil
		out[i] = (v ~= nil and v > 0) and v or -1
	end
	return out
end

local function reconcile(e)
	local sp, st = e.all_fight_spirits, e.all_ship_fight_spirit_info
	-- [FIX lag 4] reconcile() duoc WS.tick() goi MOI FRAME: table.sort toan bo key
	-- + duyet het all_fight_spirits + goi mould() tra bang trong vong lap.
	-- Nay: chi chay lai khi tap hop ban ghi thuc su thay doi.
	local sp_n = 0
	for _ in pairs(sp) do sp_n = sp_n + 1 end
	local st_n = 0
	for _ in pairs(st) do st_n = st_n + 1 end
	local sig = sp_n * 100003 + st_n
	if R.rec_sig == sig and R.rec_sp == sp and R.rec_st == st then return end
	R.rec_sig, R.rec_sp, R.rec_st = sig, sp, st
	local used = {}
	local keys = {}
	for k in pairs(st) do keys[#keys + 1] = k end
	table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
	for _, k in ipairs(keys) do
		local arr = st[k]
		if type(arr) == "table" then
			for i = 1, NPOS do
				local id = tonumber(arr[i])
				if id ~= nil and id > 0 then
					local rec = sp[id]
					if type(rec) ~= "table" then
						arr[i] = -1
					else
						local m = mould(rec.mouldId)
						if (m ~= nil and m.pos ~= i) or used[id] ~= nil then arr[i] = -1 else used[id] = tonumber(k) or k end
					end
				end
			end
		end
	end
	for id, rec in pairs(sp) do
		if type(rec) == "table" then
			local sh = used[id]
			if sh ~= nil then
				if tn(rec.shipId, -1) ~= sh then rec.shipId = sh end
			elseif tn(rec.shipId, -1) > 0 then
				rec.shipId = -1
			end
		end
	end
end

function WS.tick(e)
	if type(e) ~= "table" or S == nil then return end
	local w = ws_state()
	if type(e.all_fight_spirits) ~= "table" then
		e.all_fight_spirits = {}
		e.all_fight_spirits_list = {}
	end
	if type(e.all_ship_fight_spirit_info) ~= "table" then e.all_ship_fight_spirit_info = {} end
	local fresh = false
	local sp = e.all_fight_spirits
	if sp ~= R.ws_sp then
		R.ws_base_sp = {}
		for id, rec in pairs(sp) do R.ws_base_sp[id] = wdeep(rec) end
		R.ws_sp = sp
		for ids, rec in pairs(w.sp) do
			local id = tonumber(ids)
			if id ~= nil and type(rec) == "table" and type(rec.addProperty) == "table" then sp[id] = wdeep(rec) end
		end
		for ids in pairs(w.del) do
			local id = tonumber(ids)
			if id ~= nil then sp[id] = nil end
		end
		normalize(e)
		rebuild_list(e)
		fresh = true
	end
	local st = e.all_ship_fight_spirit_info
	if st ~= R.ws_seat then
		R.ws_base_seat = {}
		for k, arr in pairs(st) do R.ws_base_seat[k] = wdeep(arr) end
		R.ws_seat = st
		for sids, str in pairs(w.seat) do
			local k = tonumber(sids)
			if k ~= nil then st[k] = parse_seat(str) end
		end
		fresh = true
	end
	if fresh then reconcile(e) end
end

function WS.restore(e)
	if type(e) ~= "table" then return end
	if R.ws_base_sp ~= nil and type(e.all_fight_spirits) == "table" then
		local sp = e.all_fight_spirits
		for id in pairs(sp) do sp[id] = nil end
		for id, rec in pairs(R.ws_base_sp) do sp[id] = wdeep(rec) end
		R.ws_sp = sp
		normalize(e)
		rebuild_list(e)
	end
	if R.ws_base_seat ~= nil and type(e.all_ship_fight_spirit_info) == "table" then
		local st = e.all_ship_fight_spirit_info
		for k in pairs(st) do st[k] = nil end
		for k, arr in pairs(R.ws_base_seat) do st[k] = wdeep(arr) end
		R.ws_seat = st
	end

	if type(e.all_fight_spirits) == "table" and type(e.all_ship_fight_spirit_info) == "table" then reconcile(e) end
end

local function put(e, rec)
	local w = ws_state()
	local key = fint(rec.id)
	w.sp[key] = wdeep(rec)
	w.del[key] = nil
	e.all_fight_spirits[rec.id] = wdeep(rec)
	rebuild_list(e)
	R.sp_ver = (R.sp_ver or 0) + 1
	mark()
end

local function remove(e, id)
	local w = ws_state()
	local key = fint(id)
	w.sp[key] = nil
	if id < WS_ID0 then w.del[key] = true end
	e.all_fight_spirits[id] = nil
	rebuild_list(e)
	R.sp_ver = (R.sp_ver or 0) + 1
	mark()
end

local function set_seat(e, skey, arr)
	local w = ws_state()
	w.seat[fint(skey)] = seat_str(arr)
	local a = {}
	for i = 1, NPOS do a[i] = (tonumber(arr[i]) or -1) > 0 and tonumber(arr[i]) or -1 end
	e.all_ship_fight_spirit_info[skey] = a
	mark()
end

local function create(e, m)
	local w = ws_state()
	local id = math.floor(w.nid)
	while e.all_fight_spirits[id] ~= nil do id = id + 1 end
	w.nid = id + 1
	local main = main_str(m, m.quality, 0) or "0,0,0"
	local rec = {
		id = id, userId = 0, shipId = -1, mouldId = m.id, level = 0, currentExp = 0, createTime = os.time(),
		lockStatus = 0, quality = m.quality,
		addProperty = new_prop(main, ents_str(fresh_random(m, m.quality, id, true)), 0),
		newProperty = -1, awakeStatus = false,
	}
	put(e, rec)
	return e.all_fight_spirits[id]
end

local function add_ents(str, flat, spec)
	for _, en in ipairs(parse_ents(str)) do
		local v = (en.b or 0) + (en.g or 0)
		if en.t >= 0 and en.t <= 3 then
			flat[en.t + 1] = flat[en.t + 1] + v
		else
			spec[en.t] = (spec[en.t] or 0) + v
		end
	end
end

local function add_one(t, v, flat, spec)
	if t >= 0 and t <= 3 then flat[t + 1] = flat[t + 1] + v else spec[t] = (spec[t] or 0) + v end
end

local function seat_stats(seat, spmap)
	local flat, spec = { 0, 0, 0, 0 }, {}
	local suits = {}
	if type(seat) == "table" and type(spmap) == "table" then
		for i = 1, NPOS do
			local id = tonumber(seat[i])
			if id ~= nil and id > 0 then
				local rec = spmap[id]
				if type(rec) == "table" and type(rec.addProperty) == "table" then
					add_ents(rec.addProperty.main, flat, spec)
					add_ents(rec.addProperty.random, flat, spec)
					local m = mould(rec.mouldId)
					if m ~= nil then suits[m.suit] = (suits[m.suit] or 0) + 1 end
				end
			end
		end
	end
	local two, four = false, false
	for _, c in pairs(suits) do
		if c >= 2 then two = true end
		if c == 4 then four = true end
	end
	local sb = cfg_suit()
	if two and sb[1] ~= nil then add_one(sb[1][1], sb[1][2], flat, spec) end
	if four and sb[2] ~= nil then add_one(sb[2][1], sb[2][2], flat, spec) end
	return flat, spec
end

function WS.delta(sid)
	local out = { 0, 0, 0, 0, spec = {} }
	local e = ED()
	if S == nil or e == nil then return out end
	local key = tonumber(sid)
	if key == nil then return out end
	local ok, err = pcall(function()
		WS.tick(e)
		local cur = type(e.all_ship_fight_spirit_info) == "table" and e.all_ship_fight_spirit_info[key] or nil
		local base = R.ws_base_seat ~= nil and R.ws_base_seat[key] or nil
		if cur == nil and base == nil then return end
		local cf, cs = seat_stats(cur, e.all_fight_spirits)
		local bf, bs = seat_stats(base, R.ws_base_sp)
		for i = 1, 4 do out[i] = cf[i] - bf[i] end
		local spec = {}
		for t, v in pairs(cs) do spec[t] = v - (bs[t] or 0) end
		for t, v in pairs(bs) do if cs[t] == nil then spec[t] = -v end end
		out.spec = spec
	end)
	if not ok then log("loi chi so chien hon:", tostring(err)) end
	return out
end

-- [BOT RANDOM BO] Gom cac bo chien hon DU 4 vi tri (suit -> {[pos]=mould tot nhat}).
local function ws_suit_map()
	local c = wcache()
	if c.by_suit ~= nil then return c.by_suit, c.suit_ids end
	local by_suit = {}
	local d = G("dms")
	if type(d) == "table" and type(d["fight_spirit_mould"]) == "table" then
		for k in pairs(d["fight_spirit_mould"]) do
			local m = mould(tonumber(k))
			if m ~= nil and m.pos >= 1 and m.pos <= NPOS then
				local s = by_suit[m.suit]
				if s == nil then s = {}; by_suit[m.suit] = s end
				local cur = s[m.pos]
				if cur == nil or m.quality > cur.quality or (m.quality == cur.quality and m.id < cur.id) then s[m.pos] = m end
			end
		end
	end
	local ids = {}
	for suit, s in pairs(by_suit) do
		local okc = true
		for p = 1, NPOS do if s[p] == nil then okc = false; break end end
		if okc then ids[#ids + 1] = suit end
	end
	table.sort(ids)
	c.by_suit, c.suit_ids = by_suit, ids
	return by_suit, ids
end

-- Danh sach id cac bo chien hon day du (toan bo bo), da sap xep.
function WS.suit_list()
	local _, ids = ws_suit_map()
	local o = {}
	for i = 1, #ids do o[i] = ids[i] end
	return o
end

-- want == nil : bo tot nhat (nhu cu). want = suit_id : FULL chi so cua dung bo do.
function WS.full_stats(want)
	local c = wcache()
	local cached = nil
	if want == nil then cached = c.full else cached = c.fulls ~= nil and c.fulls[want] or nil end
	if cached ~= nil then
		local o = { cached[1], cached[2], cached[3], cached[4], spec = {} }
		for k, v in pairs(cached.spec) do o.spec[k] = v end
		return o
	end
	local flat, spec = { 0, 0, 0, 0 }, {}
	local by_suit = ws_suit_map()

	local best, bq, bid = nil, -1, nil
	if want ~= nil then
		local s = by_suit[want]
		if s ~= nil then
			local okc, q = true, 99
			for p = 1, NPOS do
				if s[p] == nil then okc = false; break end
				if s[p].quality < q then q = s[p].quality end
			end
			if okc then best, bq, bid = s, q, want end
		end
	else
		for suit, s in pairs(by_suit) do
			local okc, q = true, 99
			for p = 1, NPOS do
				if s[p] == nil then okc = false; break end
				if s[p].quality < q then q = s[p].quality end
			end
			if okc and (q > bq or (q == bq and (bid == nil or suit < bid))) then best, bq, bid = s, q, suit end
		end
	end
	if best ~= nil then
		local aq = awake_quality()
		for p = 1, NPOS do
			local m = best[p]
			local q = math.max(m.quality, aq)
			if #main_entries(m.mlib, q) == 0 or lvl_info(q).cap <= 0 then q = m.quality end
			local cap = lvl_info(q).cap
			for _, en in ipairs(main_entries(m.mlib, q)) do
				local v = (en.b or 0) + (en.g or 0) * math.max(cap - 1, 1)
				if en.t >= 0 and en.t <= 3 then flat[en.t + 1] = flat[en.t + 1] + v else spec[en.t] = (spec[en.t] or 0) + v end
			end
			local pool = {}
			for _, en in ipairs(rand_pool(m.rlib, q)) do pool[#pool + 1] = en end
			table.sort(pool, function(a, b)
				local x, y = (a.b or 0) + (a.g or 0), (b.b or 0) + (b.g or 0)
				if x ~= y then return x > y end
				return a.t < b.t
			end)
			local n = math.min(cfg_nrand(math.min(q, 5)), #pool)
			local trig = math.floor(cap / 3)
			local extra = math.max(0, trig - n)
			for i = 1, n do
				local en = pool[i]
				local times = math.floor(extra / n) + ((i <= extra % n) and 1 or 0)
				local v = (en.b or 0) + (en.g or 0) * times
				if en.t >= 0 and en.t <= 3 then flat[en.t + 1] = flat[en.t + 1] + v else spec[en.t] = (spec[en.t] or 0) + v end
			end
		end
		local sb = cfg_suit()
		for i = 1, 2 do
			local b = sb[i]
			if b ~= nil then
				if b[1] >= 0 and b[1] <= 3 then flat[b[1] + 1] = flat[b[1] + 1] + b[2] else spec[b[1]] = (spec[b[1]] or 0) + b[2] end
			end
		end
	end
	local rec = { flat[1], flat[2], flat[3], flat[4], spec = spec, suit = bid, quality = bq }
	if want == nil then
		c.full = rec
	else
		c.fulls = c.fulls or {}
		c.fulls[want] = rec
	end
	return WS.full_stats(want)
end

function WS.prop_values(orig, spec, base_only)
	local keys = {}
	for t, v in pairs(spec or {}) do
		if math.abs(v) > 1e-9 then keys[#keys + 1] = t end
	end
	if #keys == 0 then return orig end
	table.sort(keys)
	local parts = {}
	for _, piece in ipairs(wsplit(orig ~= nil and tostring(orig) or "", "|")) do
		if piece ~= "" then parts[#parts + 1] = piece end
	end
	for _, t in ipairs(keys) do
		local idx, val = nil, 0
		for i = #parts, 1, -1 do
			local pt, pv = string.match(parts[i], "^%s*(%-?%d+)%s*:%s*(%-?[%d%.]+)%s*$")
			if pt ~= nil and tonumber(pt) == t then idx = i; val = tonumber(pv) or 0; break end
		end
		local nv
		if base_only then nv = math.max(0, spec[t])
		else nv = math.max(0, val + spec[t]) end
		if idx ~= nil then
			parts[idx] = fint(t) .. ":" .. wnum(nv)
		elseif nv > 0 then
			parts[#parts + 1] = fint(t) .. ":" .. wnum(nv)
		end
	end
	return table.concat(parts, "|")
end

local function rec_tokens(rec, out)
	local function nz(v, d)
		v = tostring(v)
		if v == "" or string.find(v, "%s") then return d end
		return v
	end
	out[#out + 1] = fint(rec.id)
	out[#out + 1] = fint(tn(rec.userId, 0))
	out[#out + 1] = fint(tn(rec.shipId, -1))
	out[#out + 1] = fint(tn(rec.mouldId, 0))
	out[#out + 1] = fint(tn(rec.level, 0))
	out[#out + 1] = fint(tn(rec.currentExp, 0))
	out[#out + 1] = fint(tn(rec.createTime, 0))
	out[#out + 1] = fint(tn(rec.lockStatus, 0))
	out[#out + 1] = fint(tn(rec.quality, 1))
	for _, pr in ipairs({ rec.addProperty, rec.newProperty }) do
		if type(pr) ~= "table" then
			out[#out + 1] = "-1"
		else
			out[#out + 1] = nz(pr.main, "0,0,0")
			out[#out + 1] = nz(pr.random, "-1,0,0")
			out[#out + 1] = fint(tn(pr.randomEhanceNumber, 0))
			out[#out + 1] = nz(pr.randomStrId, "0")
			out[#out + 1] = fint(tn(pr.awake, 0))
			out[#out + 1] = nz(pr.suitActiveState, "0")
		end
	end
	out[#out + 1] = rec.awakeStatus and "true" or "false"
end

local function blk_spirits(code, recs)
	local b = { fint(code), fint(#recs) }
	for _, rec in ipairs(recs) do rec_tokens(rec, b) end
	return b
end

local function blk_delete(ids)
	local b = { "14134", fint(#ids) }
	for _, id in ipairs(ids) do b[#b + 1] = fint(id) end
	return b
end

local function seat_json_item(skey, arr)
	return '{"shipId":' .. fint(skey) .. ',"seatInfo":"' .. seat_str(arr) .. '"}'
end

local function blk_seat(skey, arr)
	return { "14133", "[" .. seat_json_item(skey, arr) .. "]" }
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do
		b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3])
	end
	return b
end

local function hero_blocks(e, skey, blocks)
	local sid = fint(skey)
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" then return end
	local F = commit_hero(e, sid, {})
	if F == nil then return end
	push_all(blocks, blk_ship(ship, F))
	push_all(blocks, blk_fight(e, sid, F))
end

local function fail(seq, name, msg, code, say)
	if say ~= nil then toast(say, 6) end
	return err_reply(seq, name, msg, code)
end

local function get_rec(e, id)
	id = tonumber(id)
	if id == nil then return nil end
	local rec = e.all_fight_spirits[id]
	if type(rec) == "table" and type(rec.addProperty) == "table" then return rec end
	return nil
end

local function edit_rec(e, id)
	local rec = get_rec(e, id)
	if rec == nil then return nil end
	return wdeep(rec)
end

local function is_awakened(rec)
	return (tonumber(rec.quality) or 0) >= awake_quality()
end

local function merge_props(list, into)
	for _, c in ipairs(list) do
		if c[1] == 6 and c[3] > 0 then into[c[2]] = (into[c[2]] or 0) + c[3] end
	end
end

local function props_ok(need)
	for pid, n in pairs(need) do
		if LS.prop_get(pid) < n then return false end
	end
	return true
end

local function props_spend(need)
	local list = {}
	for pid, n in pairs(need) do list[#list + 1] = { pid, n } end
	return LS.prop_spend_all(list)
end

function WS.h_compose(p, seq)
	local name = "fight_spirit_compund"
	local e = ED()
	WS.tick(e)
	local m = mould(p[1])
	if m == nil or m.quality < 1 or m.quality > 5 then return fail(seq, name, "LS_chien_hon_sai_mau", ERR.generic) end
	if (tonumber(tcol("fight_spirit_suit_mould", m.suit, "rare")) or 0) ~= 0 then
		return fail(seq, name, "LS_bo_hiem_khong_ghep_duoc", ERR.generic, "Chien hon bo hiem khong ghep duoc.")
	end
	local ids, seen = {}, {}
	for i = 2, 4 do
		local id = tonumber(p[i])
		if id == nil or id <= 0 or seen[id] then return fail(seq, name, "LS_nguyen_lieu_ghep_sai", ERR.generic, "Can 3 chien hon KHAC NHAU de ghep.") end
		seen[id] = true
		local rec = get_rec(e, id)
		if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
		if tn(rec.shipId, -1) > 0 then return fail(seq, name, "LS_chien_hon_dang_mac", ERR.generic, "Chien hon dang mac tren tuong, hay thao ra truoc.") end
		if tn(rec.lockStatus, 0) ~= 0 then return fail(seq, name, "LS_chien_hon_dang_khoa", ERR.generic, "Chien hon dang khoa, hay mo khoa truoc.") end
		if tn(rec.quality, 0) ~= m.quality then return fail(seq, name, "LS_sai_pham", ERR.generic, "Nguyen lieu ghep phai cung pham voi chien hon muc tieu.") end
		ids[#ids + 1] = id
	end
	local silver = cfg_compose_silver(m.quality)
	if silver == nil then return fail(seq, name, "LS_khong_co_gia_ghep", ERR.generic) end
	if (S.silver or 0) < silver then return fail(seq, name, "LS_khong_du_bac", ERR.silver) end
	if silver > 0 then LS.money_spend("silver", silver) end
	for _, id in ipairs(ids) do remove(e, id) end
	local rec = create(e, m)
	local blocks = {}
	push_all(blocks, blk_spirits(14132, { rec }))
	push_all(blocks, blk_delete(ids))
	push_all(blocks, blk_reward({ { m.id, 73, 1 } }))
	stat_inc("ws_compose")
	LS.save_state(true)
	log("chien hon ghep: mau", m.id, "pham", m.quality, "bac", fint(silver), "-> id", rec.id)
	return reply(seq, name, blocks)
end

local function apply_triggers(rec, m, times)
	if times <= 0 then return end
	local ents = parse_ents(rec.addProperty.random)
	if #ents > 0 then
		local q = tn(rec.quality, m.quality)
		for _ = 1, times do
			local idx = nil
			for i = 1, #ents do
				if is_slot_empty(ents[i]) then idx = i; break end
			end
			if idx ~= nil then
				local pb = pool_bg(m.rlib, q, ents[idx].t)
				ents[idx].b = pb or 0
			else
				local i = ri(#ents)
				local _, pg = pool_bg(m.rlib, q, ents[i].t)
				ents[i].g = (ents[i].g or 0) + (pg or 0)
			end
		end
		rec.addProperty.random = ents_str(ents)
	end
	rec.addProperty.randomEhanceNumber = tn(rec.addProperty.randomEhanceNumber, 0) + times
end

function WS.h_enhance(p, seq)
	local name = "fight_spirit_ehance"
	local e = ED()
	WS.tick(e)
	local rec = edit_rec(e, p[1])
	if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
	local m = mould(rec.mouldId)
	if m == nil then return fail(seq, name, "LS_chien_hon_sai_mau", ERR.generic) end
	local q = tn(rec.quality, m.quality)
	local li = lvl_info(q)
	local level = tn(rec.level, 0)
	if li.cap <= 0 or level >= li.cap then
		return fail(seq, name, "LS_chien_hon_toi_da", ERR.generic, "Chien hon da dat cap toi da.")
	end
	local st = cfg_stones()
	local stones, fodder, seen = {}, {}, {}
	local gain, nmat = 0, 0
	for i = 2, 6 do
		local s = tostring(p[i] or "-1")
		if s ~= "-1" and s ~= "" then
			nmat = nmat + 1
			local a, b = string.match(s, "^6,(%d+),(%d+)$")
			if a ~= nil then
				local pid, num = tonumber(a), tonumber(b)
				if st.exp[pid] == nil or num <= 0 then return fail(seq, name, "LS_da_hon_sai", ERR.generic) end
				stones[pid] = (stones[pid] or 0) + num
				gain = gain + st.exp[pid] * num
			else
				local fid = tonumber(s)
				local f = fid ~= nil and get_rec(e, fid) or nil
				if f == nil or seen[fid] or fid == rec.id then return fail(seq, name, "LS_nguyen_lieu_sai", ERR.generic, "Nguyen lieu cuong hoa khong hop le.") end
				seen[fid] = true
				if tn(f.shipId, -1) > 0 then return fail(seq, name, "LS_chien_hon_dang_mac", ERR.generic, "Chien hon dang mac khong the lam nguyen lieu.") end
				if tn(f.lockStatus, 0) ~= 0 then return fail(seq, name, "LS_chien_hon_dang_khoa", ERR.generic, "Chien hon dang khoa khong the lam nguyen lieu.") end
				if is_awakened(f) then return fail(seq, name, "LS_chien_hon_da_thuc_tinh", ERR.generic, "Chien hon da thuc tinh khong the lam nguyen lieu.") end
				fodder[#fodder + 1] = fid
				gain = gain + tn(f.currentExp, 0) + exp_to(tn(f.quality, 1), tn(f.level, 0))
			end
		end
	end
	if nmat == 0 then return fail(seq, name, "LS_thieu_nguyen_lieu", ERR.generic, "Chua chon nguyen lieu cuong hoa.") end
	for pid, num in pairs(stones) do
		if LS.prop_get(pid) < num then return fail(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	end
	local silver = gain * cfg_silver_per_exp()
	if (S.silver or 0) < silver then return fail(seq, name, "LS_khong_du_bac", ERR.silver) end

	if silver > 0 then LS.money_spend("silver", silver) end
	for pid, num in pairs(stones) do LS.prop_add(pid, -num) end
	for _, fid in ipairs(fodder) do remove(e, fid) end

	local total = exp_to(q, level) + tn(rec.currentExp, 0) + gain
	local nlv = level_for(q, total)
	if nlv >= li.cap then
		nlv = li.cap
		rec.currentExp = 0
	else
		rec.currentExp = total - exp_to(q, nlv)
	end
	rec.level = nlv
	if nlv > level then
		apply_triggers(rec, m, math.floor(nlv / 3) - math.floor(level / 3))
		local ms = main_str(m, q, nlv)
		if ms ~= nil then rec.addProperty.main = ms end
	end
	put(e, rec)

	local blocks = {}
	push_all(blocks, blk_spirits(14132, { e.all_fight_spirits[rec.id] }))
	if #fodder > 0 then push_all(blocks, blk_delete(fodder)) end
	if tn(rec.shipId, -1) > 0 then hero_blocks(e, tn(rec.shipId, -1), blocks) end
	stat_inc("ws_enhance")
	LS.save_state(true)
	log("chien hon cuong hoa: id", rec.id, "cap", level, "->", nlv, "exp +", fint(gain), "bac", fint(silver))
	return reply(seq, name, blocks)
end

function WS.h_awake(p, seq)
	local name = "fight_spirit_awake"
	local e = ED()
	WS.tick(e)
	local rec = edit_rec(e, p[1])
	if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
	local m = mould(rec.mouldId)
	if m == nil then return fail(seq, name, "LS_chien_hon_sai_mau", ERR.generic) end
	local aq = awake_quality()
	if is_awakened(rec) then return fail(seq, name, "LS_da_thuc_tinh", ERR.generic, "Chien hon nay da thuc tinh roi.") end
	if tn(rec.quality, 0) ~= aq - 1 then return fail(seq, name, "LS_chua_du_pham", ERR.generic, "Chi chien hon pham " .. fint(aq - 1) .. " moi thuc tinh duoc.") end
	local need = {}
	merge_props(cfg_group_cost(232), need)
	if not props_ok(need) then return fail(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	props_spend(need)

	local level = tn(rec.level, 0)
	rec.quality = aq
	rec.awakeStatus = true
	rec.newProperty = -1
	local ms = main_str(m, aq, level)
	if ms ~= nil then rec.addProperty.main = ms end
	local ap = awake_pool(m.alib)
	if #ap > 0 then rec.addProperty.awake = ap[ri(#ap)] end

	local nx = lvl_info(aq).nxt[level]
	if nx ~= nil and nx > 0 and tn(rec.currentExp, 0) >= nx then rec.currentExp = nx - 1 end
	put(e, rec)

	local blocks = {}
	push_all(blocks, blk_spirits(14132, { e.all_fight_spirits[rec.id] }))
	if tn(rec.shipId, -1) > 0 then hero_blocks(e, tn(rec.shipId, -1), blocks) end
	stat_inc("ws_awake")
	LS.save_state(true)
	log("chien hon thuc tinh: id", rec.id, "talent", rec.addProperty.awake)
	return reply(seq, name, blocks)
end

local function roll_refine(rec, m, lock_e, lock_a)
	local old = parse_ents(rec.addProperty.random)
	local q = math.min(tn(rec.quality, 5), 5)
	local pool = rand_pool(m.rlib, q)
	local used = {}
	for i, en in ipairs(old) do
		if lock_e[i] then used[en.t] = true end
	end
	local new = {}
	for i, en in ipairs(old) do
		if lock_e[i] then
			new[i] = { t = en.t, b = en.b, g = en.g }
		else
			local _, og = pool_bg(m.rlib, q, en.t)
			local k = 0
			if og ~= nil and og > 0 then k = math.floor((en.g or 0) / og + 0.5) end
			local cand, alt = {}, {}
			for _, pe in ipairs(pool) do
				if not used[pe.t] then
					cand[#cand + 1] = pe
					if pe.t ~= en.t then alt[#alt + 1] = pe end
				end
			end
			local set = (#alt > 0) and alt or cand
			if #set == 0 then
				new[i] = { t = en.t, b = en.b, g = en.g }
			else
				local pe = set[ri(#set)]
				used[pe.t] = true
				new[i] = { t = pe.t, b = pe.b, g = k * pe.g }
			end
		end
	end
	local awake = tn(rec.addProperty.awake, 0)
	if not lock_a then
		local ap = awake_pool(m.alib)
		local alt = {}
		for _, tid in ipairs(ap) do
			if tid ~= awake then alt[#alt + 1] = tid end
		end
		local set = (#alt > 0) and alt or ap
		if #set > 0 then awake = set[ri(#set)] end
	end
	return new, awake
end

function WS.h_refine(p, seq)
	local name = "fight_spirit_refine"
	local e = ED()
	WS.tick(e)
	local rec = edit_rec(e, p[1])
	if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
	local m = mould(rec.mouldId)
	if m == nil then return fail(seq, name, "LS_chien_hon_sai_mau", ERR.generic) end
	if not is_awakened(rec) then return fail(seq, name, "LS_chua_thuc_tinh", ERR.generic, "Chi chien hon da thuc tinh moi tinh luyen duoc.") end
	local ents = parse_ents(rec.addProperty.random)
	local flags = wsplit(p[2] or "", ",")
	if #flags ~= #ents + 1 then return fail(seq, name, "LS_khoa_sai", ERR.generic) end
	local lock_e, locks = {}, 0
	for i = 1, #ents do
		if flags[i] == "1" then lock_e[i] = true; locks = locks + 1
		elseif flags[i] ~= "0" then return fail(seq, name, "LS_khoa_sai", ERR.generic) end
	end
	local lock_a = false
	if flags[#ents + 1] == "1" then lock_a = true; locks = locks + 1
	elseif flags[#ents + 1] ~= "0" then return fail(seq, name, "LS_khoa_sai", ERR.generic) end
	if locks > 3 then return fail(seq, name, "LS_khoa_qua_nhieu", ERR.generic, "Toi da khoa 3 thuoc tinh.") end
	if locks >= #ents + 1 then return fail(seq, name, "LS_khoa_het", ERR.generic, "Khong the khoa tat ca thuoc tinh.") end

	local need = {}
	merge_props(cfg_group_cost(233), need)
	local extra = {}
	merge_props(cfg_group_cost(234), extra)
	for pid, n in pairs(extra) do need[pid] = (need[pid] or 0) + n * locks end
	if not props_ok(need) then return fail(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	props_spend(need)

	local new, awake = roll_refine(rec, m, lock_e, lock_a)
	rec.newProperty = {
		main = rec.addProperty.main, random = ents_str(new), randomEhanceNumber = tostring(tn(rec.addProperty.randomEhanceNumber, 0)),
		randomStrId = rec.addProperty.randomStrId or "0", awake = awake, suitActiveState = rec.addProperty.suitActiveState or "0",
	}
	put(e, rec)
	local blocks = {}
	push_all(blocks, blk_spirits(14132, { e.all_fight_spirits[rec.id] }))
	stat_inc("ws_refine")
	LS.save_state(true)
	log("chien hon tinh luyen: id", rec.id, "khoa", locks)
	return reply(seq, name, blocks)
end

function WS.h_refine_define(p, seq)
	local name = "fight_spirit_refine_define"
	local e = ED()
	WS.tick(e)
	local rec = edit_rec(e, p[1])
	if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
	if type(rec.newProperty) ~= "table" then return fail(seq, name, "LS_khong_co_ket_qua", ERR.generic) end
	local accept = tostring(p[2] or "0") == "1"
	if accept then
		local np = rec.newProperty

		rec.addProperty = {
			main = rec.addProperty.main, random = np.random, randomEhanceNumber = tn(rec.addProperty.randomEhanceNumber, 0),
			randomStrId = np.randomStrId or "0", awake = tn(np.awake, 0), suitActiveState = np.suitActiveState or "0",
		}
	end
	rec.newProperty = -1
	put(e, rec)
	local blocks = {}
	push_all(blocks, blk_spirits(14132, { e.all_fight_spirits[rec.id] }))
	if accept and tn(rec.shipId, -1) > 0 then hero_blocks(e, tn(rec.shipId, -1), blocks) end
	stat_inc(accept and "ws_refine_ok" or "ws_refine_cancel")
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function WS.h_break_down(p, seq)
	local name = "fight_spirit_break_down"
	local e = ED()
	WS.tick(e)
	local ids, recs, seen = {}, {}, {}
	for i = 1, 5 do
		local s = tostring(p[i] or "-1")
		if s ~= "-1" and s ~= "" then
			local id = tonumber(s)
			local rec = id ~= nil and get_rec(e, id) or nil
			if rec == nil or seen[id] then return fail(seq, name, "LS_nguyen_lieu_sai", ERR.generic, "Chien hon phan giai khong hop le.") end
			seen[id] = true
			if tn(rec.shipId, -1) > 0 then return fail(seq, name, "LS_chien_hon_dang_mac", ERR.generic, "Chien hon dang mac khong phan giai duoc.") end
			if tn(rec.lockStatus, 0) ~= 0 then return fail(seq, name, "LS_chien_hon_dang_khoa", ERR.generic, "Chien hon dang khoa khong phan giai duoc.") end
			if tn(rec.quality, 0) < 5 then return fail(seq, name, "LS_pham_thap", ERR.generic, "Chi phan giai chien hon tu pham 5 tro len.") end
			ids[#ids + 1] = id
			recs[#recs + 1] = rec
		end
	end
	if #ids == 0 then return fail(seq, name, "LS_chua_chon", ERR.generic, "Chua chon chien hon de phan giai.") end

	local total = 0
	local back = {}
	local rate = cfg_ret_rate()
	local costs = cfg_group_cost(232)
	for _, rec in ipairs(recs) do
		total = total + tn(rec.currentExp, 0) + exp_to(tn(rec.quality, 1), tn(rec.level, 0))
		if is_awakened(rec) then
			for _, c in ipairs(costs) do
				local n1 = math.floor(c[3] * rate)
				if c[1] == 6 and n1 > 0 then back[c[2]] = (back[c[2]] or 0) + n1 end
			end
		end
	end
	local rest = total
	local st = cfg_stones()
	for i = #st.order, 1, -1 do
		local pid, ex = st.order[i][1], st.order[i][2]
		local num = math.floor(rest / ex)
		if num > 0 then
			back[pid] = (back[pid] or 0) + num
			rest = rest - ex * num
		end
	end
	local base = cfg_base_material()
	if base ~= nil and base[1] == 6 then back[base[2]] = (back[base[2]] or 0) + #recs * base[3] end
	local silver = total * cfg_silver_per_exp()

	for _, id in ipairs(ids) do remove(e, id) end
	local items, pids = {}, {}
	for pid in pairs(back) do pids[#pids + 1] = pid end
	table.sort(pids)
	for _, pid in ipairs(pids) do
		LS.prop_add(pid, back[pid])
		items[#items + 1] = { pid, 6, back[pid] }
	end
	if silver > 0 then
		LS.money_add("silver", silver)
		items[#items + 1] = { -1, 1, silver }
	end
	local blocks = {}
	push_all(blocks, blk_delete(ids))
	push_all(blocks, blk_reward(items))
	stat_inc("ws_break", #ids)
	LS.save_state(true)
	log("chien hon phan giai:", #ids, "con, exp", fint(total), "bac +", fint(silver))
	return reply(seq, name, blocks)
end

function WS.h_lock(p, seq)
	local name = "fight_spirit_lock"
