function WS.h_change(p, seq)
	local name = "fight_spirit_change"
	local e = ED()
	WS.tick(e)
	local sid = tostring(p[1] or "")
	local skey = tonumber(sid)
	if skey == nil or type(e.user_ship[sid]) ~= "table" then return fail(seq, name, "LS_khong_co_tuong", ERR.generic) end
	if p[2] == nil or tostring(p[2]) == "" then return fail(seq, name, "LS_thieu_o", ERR.generic) end
	local want = parse_seat(p[2])
	local seen = {}
	for i = 1, NPOS do
		local id = want[i]
		if id > 0 then
			if seen[id] then return fail(seq, name, "LS_chien_hon_trung", ERR.generic) end
			seen[id] = true
			local rec = get_rec(e, id)
			if rec == nil then return fail(seq, name, "LS_chien_hon_khong_ton_tai", ERR.generic) end
			local m = mould(rec.mouldId)
			if m == nil or m.pos ~= i then return fail(seq, name, "LS_sai_o", ERR.generic, "Chien hon khong dung o nay.") end
			local sh = tn(rec.shipId, -1)
			if sh > 0 and sh ~= skey then return fail(seq, name, "LS_dang_mac_tuong_khac", ERR.generic, "Chien hon dang mac tren tuong khac.") end
		end
	end
	local cur = get_seat(e, skey)
	local changed = {}
	for i = 1, NPOS do
		local old = cur[i]
		if old > 0 and old ~= want[i] then
			local rec = edit_rec(e, old)
			if rec ~= nil and tn(rec.shipId, -1) ~= -1 then
				rec.shipId = -1
				put(e, rec)
				changed[#changed + 1] = e.all_fight_spirits[old]
			end
		end
	end
	for i = 1, NPOS do
		local id = want[i]
		if id > 0 then
			local rec = edit_rec(e, id)
			if tn(rec.shipId, -1) ~= skey then
				rec.shipId = skey
				put(e, rec)
				changed[#changed + 1] = e.all_fight_spirits[id]
			end
		end
	end
	set_seat(e, skey, want)
	local blocks = {}
	if #changed > 0 then push_all(blocks, blk_spirits(14132, changed)) end
	push_all(blocks, blk_seat(skey, want))
	hero_blocks(e, skey, blocks)
	stat_inc("ws_change")
	LS.save_state(true)
	log("chien hon mac: tuong", sid, "->", seat_str(want))
	return reply(seq, name, blocks)
end

function WS.h_init(p, seq)
	local name = "fight_spirit_init"
	local e = ED()
	WS.tick(e)
	local recs = {}
	for _, rec in ipairs(e.all_fight_spirits_list or {}) do recs[#recs + 1] = rec end
	local keys = {}
	for k in pairs(e.all_ship_fight_spirit_info) do
		if type(k) == "number" then keys[#keys + 1] = k end
	end
	table.sort(keys)
	local items = {}
	for _, k in ipairs(keys) do items[#items + 1] = seat_json_item(k, get_seat(e, k)) end
	local blocks = {}
	push_all(blocks, blk_spirits(14130, recs))
	push_all(blocks, { "14131", "[" .. table.concat(items, ",") .. "]" })
	return reply(seq, name, blocks)
end

local GM_MULT = { [2502] = 10, [2503] = 10, [2504] = 10, [2505] = 60, [2506] = 5 }

function WS.grant(n)
	local e = ED()
	if e == nil or S == nil then return nil end
	WS.tick(e)
	n = math.max(1, math.floor(tn(n, 99)))
	for pid, k in pairs(GM_MULT) do
		LS.prop_set(pid, math.min(999999, LS.prop_get(pid) + n * k))
	end
	local free = {}
	for _, rec in pairs(e.all_fight_spirits) do
		if type(rec) == "table" and tn(rec.shipId, -1) <= 0 and tn(rec.lockStatus, 0) == 0 then
			local m = mould(rec.mouldId)
			if m ~= nil then
				local key = fint(tn(rec.quality, 0)) .. ":" .. fint(m.pos)
				free[key] = (free[key] or 0) + 1
			end
		end
	end
	local added = 0
	for q = 1, 5 do
		for pos = 1, NPOS do
			local have = free[fint(q) .. ":" .. fint(pos)] or 0
			for k = have + 1, 3 do
				local suit = ((q * 4 + pos + k) % 6) + 1
				local m = mould((suit - 1) * 20 + (pos - 1) * 5 + q)
				if m ~= nil then create(e, m); added = added + 1 end
			end
		end
	end
	stat_inc("gm_warsoul")
	LS.save_state(true)
	log("GM CHIEN HON: +", added, "chien hon, vat lieu +", n)
	return added
end

function LS.ws_grant(mid, n)
	local e = ED()
	if e == nil or S == nil or not R.ready then return nil end
	WS.tick(e)
	local m = mould(mid)
	if m == nil then return nil end
	local out = {}
	for _ = 1, math.max(1, math.floor(tn(n, 1))) do out[#out + 1] = create(e, m) end
	LS.save_state(true)
	return out
end

local gm_equip_prev = LS.gm_grant_equip
function LS.gm_grant_equip(n)
	local a, b = gm_equip_prev(n)
	if a == nil then return nil end
	local okg, added = pcall(WS.grant, n)
	if okg and added ~= nil then
		toast("LS: Chien Hon +" .. fint(added) .. " con, da hon / vat lieu +", 6)
	elseif not okg then
		log("loi GM chien hon:", tostring(added))
	end
	return a, b, (okg and added or nil)
end

-- [WS FULL nhu amulet] Kho chien hon luon co du MOI mau (bo x vi tri x pham), tu bu khi mac / phan giai,
-- va MOI chien hon deu FULL cap + bac (thuc tinh khong ton vat pham, cuong hoa toi cap toi da) - xem WS.max_rec;
-- vat lieu chien hon (GM_MULT) tu nang len muc cao khi xuong duoi 500000. Tat bang S.cfg.ws_auto = false.
local WS_FLOOR_LOW, WS_FLOOR_TOP = 500000, 999999
local WS_STOCK_BATCH = 30

local function ws_auto_on() return type(S.cfg) == "table" and S.cfg.ws_auto == true end -- mac dinh TAT (chi bat khi bam nut FULL)

-- [WS FULL CAP + BAC] Dua 1 chien hon len FULL: neu dang o pham (awake-1) thi THUC TINH (pham = awake, co talent
-- thuc tinh, khong ton vat pham), roi cuong hoa toi cap toi da cua pham do (kem cac moc x3 cap cong dong ngau nhien).
-- Chi nhung pham khac (khong thuc tinh duoc) thi len cap toi da cua chinh pham do. Tra ve true neu co thay doi.
local function ws_rec_needs_max(rec)
	if type(rec) ~= "table" or type(rec.addProperty) ~= "table" then return false end
	local m = mould(rec.mouldId)
	if m == nil then return false end
	local aq = awake_quality()
	local q = tn(rec.quality, m.quality)
	if q == aq - 1 and #main_entries(m.mlib, aq) > 0 and lvl_info(aq).cap > 0 then return true end
	local cap = lvl_info(q).cap
	return cap > 0 and tn(rec.level, 0) < cap
end

function WS.max_rec(e, rec_in)
	if not ws_rec_needs_max(rec_in) then return false end
	local rec = wdeep(rec_in)
	local m = mould(rec.mouldId)
	local aq = awake_quality()
	local q = tn(rec.quality, m.quality)
	if q == aq - 1 and #main_entries(m.mlib, aq) > 0 and lvl_info(aq).cap > 0 then
		rec.quality = aq
		rec.awakeStatus = true
		rec.newProperty = -1
		local ap = awake_pool(m.alib)
		if #ap > 0 and tn(rec.addProperty.awake, 0) <= 0 then rec.addProperty.awake = ap[ri(#ap)] end
		q = aq
	end
	local cap = lvl_info(q).cap
	local level = tn(rec.level, 0)
	if cap > 0 and level < cap then
		apply_triggers(rec, m, math.floor(cap / 3) - math.floor(level / 3))
		rec.level = cap
		rec.currentExp = 0
	end
	local ms = main_str(m, q, tn(rec.level, 0))
	if ms ~= nil then rec.addProperty.main = ms end
	put(e, rec)
	return true
end

local WS_MAX_BATCH = 40

function WS.restock(e, force)
	if S == nil or not R.ready or type(e) ~= "table" or not ws_auto_on() then return 0 end
	WS.tick(e)
	if type(e.all_fight_spirits) ~= "table" then return 0 end
	R.ws_stock_n = (R.ws_stock_n or 0) + 1
	for pid in pairs(GM_MULT) do
		if LS.prop_get(pid) < WS_FLOOR_LOW then LS.prop_set(pid, WS_FLOOR_TOP) end
	end
	if not force and R.ws_stock_ver == (R.sp_ver or 0) and R.ws_max_ver == (R.sp_ver or 0) and (R.ws_stock_n % 60) ~= 0 then return 0 end
	local d = G("dms")
	if type(d) ~= "table" or type(d["fight_spirit_mould"]) ~= "table" then return 0 end
	-- [WS FULL CAP + BAC] max cap/bac MOI chien hon dang co (ca chua mac lan dang mac), moi lan toi da WS_MAX_BATCH con
	local max_complete = false
	do
		local todo = {}
		for id, rec in pairs(e.all_fight_spirits) do
			if ws_rec_needs_max(rec) then todo[#todo + 1] = id end
		end
		table.sort(todo)
		local done, worn = 0, false
		for i = 1, math.min(#todo, WS_MAX_BATCH) do
			local rec = e.all_fight_spirits[todo[i]]
			if rec ~= nil then
				local was_worn = tn(rec.shipId, -1) > 0
				local okm, chg = pcall(WS.max_rec, e, rec)
				if okm and chg then
					done = done + 1
					if was_worn then worn = true end
				elseif not okm then
					R.ws_max_errs = (R.ws_max_errs or 0) + 1
					if R.ws_max_errs <= 5 then log("loi max chien hon:", tostring(chg)) end
				end
			end
		end
		max_complete = (#todo <= WS_MAX_BATCH)
		if done > 0 then
			R.ws_max_made = (R.ws_max_made or 0) + done
			log("chien hon full: max cap + bac", done, "con (tong", R.ws_max_made, ")")
			if worn then R.stat_dirty = true; mark() end
		end
	end
	local have = {}
	for _, rec in pairs(e.all_fight_spirits) do
		if type(rec) == "table" and tn(rec.shipId, -1) <= 0 then have[tn(rec.mouldId, -1)] = true end
	end
	local ids = {}
	for k in pairs(d["fight_spirit_mould"]) do
		local id = tonumber(k)
		if id ~= nil then ids[#ids + 1] = id end
	end
	table.sort(ids)
	local made, left = 0, false
	for _, mid in ipairs(ids) do
		local m = mould(mid)
		if m ~= nil and m.pos >= 1 and m.pos <= NPOS and not have[m.id] then
			if made >= WS_STOCK_BATCH then left = true; break end
			local nrec = create(e, m)
			-- chien hon moi bu cung phai FULL cap + bac (thuc tinh neu thuc tinh duoc)
			local okm, errm = pcall(WS.max_rec, e, nrec)
			if not okm then
				R.ws_max_errs = (R.ws_max_errs or 0) + 1
				if R.ws_max_errs <= 5 then log("loi max chien hon moi:", tostring(errm)) end
			end
			made = made + 1
		end
	end
	if not left then
		R.ws_stock_ver = R.sp_ver or 0
		if max_complete then R.ws_max_ver = R.sp_ver or 0 end
	end
	if made > 0 then
		R.ws_stock_made = (R.ws_stock_made or 0) + made
		log("chien hon full: bu", made, "chien hon (tong", R.ws_stock_made, ")")
	end
	return made
end

-- [GM WAR SOUL FULL] Nut "WAR SOUL" trong bang GM (thay cho nut COMBO CARD, vi TAT CA TUONG da tu bat
-- Combo Card FULL). FULL = ws_auto bat (mac dinh): kho chien hon luon du, MOI con FULL cap + bac, vat lieu tu bu.
-- TU NANG = S.cfg.ws_auto = false: ngung tu bu / ngung max; chien hon da max van giu nguyen (khong thu hoi).
function WS.full_on() return ws_auto_on() end
function WS.apply_now(e) return WS.restock(e, true) end

WS.mould, WS.lvl_info, WS.level_for, WS.exp_to = mould, lvl_info, level_for, exp_to
WS.main_str, WS.parse_ents, WS.ents_str, WS.seat_stats = main_str, parse_ents, ents_str, seat_stats
WS.blk_spirits, WS.blk_delete, WS.blk_seat, WS.blk_reward = blk_spirits, blk_delete, blk_seat, blk_reward
WS.create, WS.put, WS.remove, WS.get_rec = create, put, remove, get_rec
WS.get_seat, WS.wnum, WS.rand_pool, WS.state = get_seat, wnum, rand_pool, ws_state
WS.set_seat = set_seat

end
init_ws()

end

do
local function init_xs()

local XS = WS

local function xsplit(s, sep)
	local t, init = {}, 1
	s = tostring(s or "")
	while true do
		local p = string.find(s, sep, init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + #sep
	end
	return t
end

local function xcache()
	if R.xs_cache == nil then R.xs_cache = {} end
	return R.xs_cache
end

local function tcol(tname, id, cname)
	local d, sc = G("dms"), G(tname)
	if type(d) ~= "table" or type(sc) ~= "table" or type(d[tname]) ~= "table" or sc[cname] == nil then return nil end
	local ok, v = pcall(d.string, d[tname], id, sc[cname])
	if ok and v ~= nil and v ~= "" then return tostring(v) end
	return nil
end

local function tsearch(tname, c1, v1)
	local d, sc = G("dms"), G(tname)
	if type(d) ~= "table" or type(sc) ~= "table" or type(d[tname]) ~= "table" then return {} end
	local ok, rows = pcall(function() return d.searchs(d[tname], sc[c1], v1) end)
	if ok and type(rows) == "table" then return rows end
	return {}
end

local function rnum(row, tname, cname)
	local d, sc = G("dms"), G(tname)
	local ok, v = pcall(function() return d.atoi(row, sc[cname]) end)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function xcfg(row, def)
	local ok, v = pcall(cfg_str, "ship_config", row)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return def
end

local SOUL_CAP = 20

local function soul_slots(tid)
	local c = xcache()
	c.slots = c.slots or {}
	local s = c.slots[tid]
	if s == nil then
		s = {}
		local okf, fac = pcall(mstr, tid, "faction_id")
		local oka, att = pcall(mstr, tid, "attribute_id")
		fac = xsplit(okf and fac or "", ",")
		att = xsplit(oka and att or "", ",")
		for i = 1, #fac do
			local fid = tonumber(fac[i])
			local unlock = (fid ~= nil and fid > 0) and tonumber(tcol("ship_soul_mould", fid, "unlock_condition")) or nil
			if unlock == nil then break end
			s[#s + 1] = { unlock = unlock, lib = tonumber(att[i]) }
		end
		c.slots[tid] = s
	end
	return s
end

local function soul_need(lib)
	local c = xcache()
	c.need = c.need or {}
	local key = fint(lib or -1)
	local t = c.need[key]
	if t == nil then
		t = {}
		if lib ~= nil then
			for _, row in ipairs(tsearch("ship_soul_experience_param", "library_group", fint(lib))) do
				local lv = rnum(row, "ship_soul_experience_param", "level")
				if lv > 0 then t[lv] = rnum(row, "ship_soul_experience_param", "need_exp") end
			end
		end
		c.need[key] = t
	end
	return t
end

local function soul_item_exp(tmpl)
	local v = tonumber(tcol("prop_mould", tmpl, "reward_type"))
	if v == nil or v <= 0 then return 0 end
	return math.floor(v)
end

local function soul_parse(str, min_n)
	local lv, ex, n = {}, {}, 0
	for part in string.gmatch(tostring(str or ""), "[^|]+") do
		n = n + 1
		local a, b = string.match(part, "^%s*(%-?%d+)%s*,%s*(%-?%d+)")
		lv[n] = math.max(1, tonumber(a) or 1)
		ex[n] = math.max(0, tonumber(b) or 0)
	end
	while n < min_n do n = n + 1; lv[n] = 1; ex[n] = 0 end
	return lv, ex, n
end

local function soul_str(lv, ex, n)
	local t = {}
	for i = 1, n do t[i] = fint(lv[i]) .. "," .. fint(ex[i]) end
	return table.concat(t, "|")
end

local function soul_room(need, lv, ex)
	if lv >= SOUL_CAP then return 0 end
	local room = -ex
	for l = lv, SOUL_CAP - 1 do
		local nd = need[l]
		if nd == nil or nd <= 0 then return nil end
		room = room + nd
	end
	if room < 0 then room = 0 end
	return room
end

local function soul_apply(need, lv, ex, add)
	local total = ex + add
	while lv < SOUL_CAP do
		local nd = need[lv]
		if nd == nil or nd <= 0 or total < nd then break end
		total = total - nd
		lv = lv + 1
	end
	if lv >= SOUL_CAP then lv = SOUL_CAP; total = 0 end
	return lv, total
end

local function soul_current(sid, ship)
	local pg = prog_get(sid)
	if pg ~= nil and pg.ship_fighting_spirit ~= nil then return pg.ship_fighting_spirit end
	return ship.ship_fighting_spirit
end

local function xfail(seq, name, msg, code, say)
	if say ~= nil then toast(say, 6) end
	return err_reply(seq, name, msg, code)
end

function XS.h_soul_up(p, seq)
	local name = "ship_soul_level_up"
	local e = ED()
	if e == nil then return nil end
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local mode = tostring(p[2] or "")
	local idx = tonumber(p[3])
	if (mode ~= "0" and mode ~= "1") or idx == nil or idx < 0 or idx ~= math.floor(idx) then
		return err_reply(seq, name, "LS_yeu_cau_sai")
	end
	local slots = soul_slots(st.tid)
	local slot = slots[idx + 1]
	if slot == nil then return xfail(seq, name, "LS_dau_hon_khong_co_o", ERR.generic) end
	if slot.unlock > st.order then
		return xfail(seq, name, "LS_dau_hon_chua_mo", ERR.generic, "Dau hon nay chua mo khoa (can tang cap tien hoa).")
	end
	local lvs, exs, n = soul_parse(soul_current(sid, st.ship), #slots)
	local k = idx + 1
	local lv, ex = lvs[k], exs[k]
	if lv >= SOUL_CAP then
		return xfail(seq, name, "LS_dau_hon_toi_da", ERR.generic, "Dau hon da dat cap toi da.")
	end
	local need = soul_need(slot.lib)
	local room = soul_room(need, lv, ex)
	if room == nil then return xfail(seq, name, "LS_thieu_bang_exp_dau_hon", ERR.generic) end

	local nlv, nex
	if mode == "0" then

		local list = {}
		for part in string.gmatch(tostring(p[4] or ""), "[^|]+") do
			local uid, cnt = string.match(part, "^%s*(%d+)%s*,%s*(%d+)")
			if uid == nil then return err_reply(seq, name, "LS_yeu_cau_sai") end
			local rec = type(e.user_prop) == "table" and e.user_prop[uid] or nil
			if type(rec) ~= "table" then return xfail(seq, name, "LS_khong_co_vat_pham", ERR.items) end
			local tmpl = pkey(rec.user_prop_template)
			local per = tmpl ~= nil and soul_item_exp(tmpl) or 0
			cnt = tonumber(cnt)
			if per <= 0 or cnt <= 0 then return xfail(seq, name, "LS_vat_pham_khong_phai_exp_dau_hon", ERR.items) end
			list[#list + 1] = { tmpl = tmpl, n = cnt, per = per }
		end
		if #list == 0 then return err_reply(seq, name, "LS_yeu_cau_sai") end
		local ask = {}
		for i = 1, #list do ask[list[i].tmpl] = (ask[list[i].tmpl] or 0) + list[i].n end
		for tmpl, c in pairs(ask) do
			if LS.prop_get(tmpl) < c then
				return xfail(seq, name, "LS_khong_du_vat_pham", ERR.items, "Khong du vat pham da chon.")
			end
		end
		local gain, used = 0, {}
		for i = 1, #list do
			local it = list[i]
			local want = math.ceil((room - gain) / it.per)
			local use = math.max(0, math.min(it.n, want))
			if use > 0 then
				used[it.tmpl] = (used[it.tmpl] or 0) + use
				gain = gain + use * it.per
			end
		end
		local eff = math.min(gain, room)
		if eff <= 0 then return xfail(seq, name, "LS_khong_co_exp", ERR.items) end
		local silver = eff * xcfg(10, 500)
		if (S.silver or 0) < silver then
			return xfail(seq, name, "LS_khong_du_bac", ERR.silver)
		end
		if silver > 0 then LS.money_spend("silver", silver) end
		for tmpl, c in pairs(used) do LS.prop_add(tmpl, -c) end
		nlv, nex = soul_apply(need, lv, ex, eff)
		stat_inc("soul_items")
		log("dau hon: tuong", sid, "o", k, "bang vat pham: cap", lv, "->", nlv, "exp +", fint(eff), "bac", fint(silver))
	else

		local nd = need[lv]
		local gold = math.max(0, nd - ex) * xcfg(9, 5)
		if (S.gold or 0) < gold then
			return xfail(seq, name, "LS_khong_du_kc", ERR.generic, "Khong du KC de Tu cuong hoa.")
		end
		if gold > 0 then LS.money_spend("gold", gold) end
		nlv, nex = lv + 1, 0
		if nlv >= SOUL_CAP then nlv = SOUL_CAP end
		stat_inc("soul_diamond")
		log("dau hon: tuong", sid, "o", k, "bang KC: cap", lv, "->", nlv, "KC", fint(gold))
	end

	lvs[k], exs[k] = nlv, nex
	local ns = soul_str(lvs, exs, n)
	local F = commit_hero(e, sid, { ship_fighting_spirit = ns })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	LS.save_state(true)
	return reply(seq, name, { "14106", sid, ns })
end

XS.soul_slots, XS.soul_need, XS.soul_room, XS.soul_apply = soul_slots, soul_need, soul_room, soul_apply
XS.soul_parse, XS.soul_str, XS.soul_item_exp = soul_parse, soul_str, soul_item_exp

local MEGA_CAP = 10
local MEGA_EMPTY = '{"megaLevel":{},"megaUse":[]}'

local function rstr(row, tname, cname)
	local sc = G(tname)
	if type(row) ~= "table" or type(sc) ~= "table" or sc[cname] == nil then return "" end
	local v = row[sc[cname]]
	if v == nil then return "" end
	return tostring(v)
end

local function mrow2(tname, a, b)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return nil end
	local ok, rows = pcall(d.searchs, d[tname], 2, a, 3, b)
	if ok and type(rows) == "table" and type(rows[1]) == "table" then return rows[1] end
	return nil
end

local function mega_shard(tid)
	local c = xcache()
	c.shard = c.shard or {}
	local v = c.shard[tid]
	if v == nil then
		v = false
		for _, row in ipairs(tsearch("prop_mould", "use_of_ship", fint(tid))) do
			if rnum(row, "prop_mould", "prop_type") == 1 then
				local id = rnum(row, "prop_mould", "id")
				if id > 0 then v = id; break end
			end
		end
		c.shard[tid] = v
	end
	return v or nil
end

local function mega_data(tid)
	local c = xcache()
	c.mega = c.mega or {}
	local m = c.mega[tid]
	if m == nil then
		m = false
		local best = nil
		for _, r in ipairs(tsearch("mega_ship", "shipID", fint(tid))) do
			if best == nil or rnum(r, "mega_ship", "skinID") == 0 then best = r end
		end
		local ab = tonumber(mstr(tid, "ability"))
		if best ~= nil and ab ~= nil then
			local link = {}
			for _, s in ipairs(xsplit(rstr(best, "mega_ship", "linkShipIds"), ",")) do
				local v = tonumber(s)
				if v ~= nil and v > 0 then link[#link + 1] = v end
			end
			m = { open = rnum(best, "mega_ship", "openStage"), ability = ab, link = link }
		end
		c.mega[tid] = m
	end
	return m or nil
end

local function mega_parse(info)
	local st = { lv = {}, use = {} }
	info = tostring(info or "")
	local lvs = string.match(info, '"megaLevel"%s*:%s*(%b{})')
	if lvs ~= nil then
		for k, v in string.gmatch(lvs, '"(%d+)"%s*:%s*"?(%-?%d+)"?') do
			local page, lv = tonumber(k), tonumber(v)
			if page >= 1 then st.lv[fint(page)] = math.max(0, math.min(MEGA_CAP, lv)) end
		end
	end
	local us = string.match(info, '"megaUse"%s*:%s*(%b[])')
	if us ~= nil then
		local seen = {}
		for v in string.gmatch(us, "%d+") do
			local n = tonumber(v)
			if not seen[n] then seen[n] = true; st.use[#st.use + 1] = n end
		end
		table.sort(st.use)
	end
	return st
end

local function mega_pages_of(st)
	local n = 0
	for _ in pairs(st.lv) do n = n + 1 end
	return n
end

local function mega_json(st)
	local pages = {}
	for k in pairs(st.lv) do pages[#pages + 1] = tonumber(k) end
	table.sort(pages)
	local a = {}
	for i = 1, #pages do
		local k = fint(pages[i])
		a[i] = '"' .. k .. '":' .. fint(st.lv[k])
	end
	local use = {}
	for i = 1, #st.use do use[i] = fint(st.use[i]) end
	table.sort(use, function(x, y) return tonumber(x) < tonumber(y) end)
	return '{"megaLevel":{' .. table.concat(a, ",") .. '},"megaUse":[' .. table.concat(use, ",") .. ']}'
end

local function mega_copy(st)
	local o = { lv = {}, use = {} }
	for k, v in pairs(st.lv) do o.lv[k] = v end
	for i = 1, #st.use do o.use[i] = st.use[i] end
	return o
end

local function mega_entry(e, sid)
	local list = e.mega_info
	if type(list) ~= "table" then return nil end
	local found = nil
	for i = 1, #list do
		local v = list[i]
		if type(v) == "table" and tostring(v.shipId) == sid then found = v end
	end
	return found
end

local function mega_cur(e, sid)
	local m = S.mega ~= nil and S.mega[sid] or nil
	if m ~= nil then return mega_copy(m) end
	local en = mega_entry(e, sid)
	return mega_parse(en ~= nil and en.info or MEGA_EMPTY)
end

local function mega_base_of(k)
	if S.heroes[k] ~= nil then return MEGA_EMPTY end
	R.mega_base = R.mega_base or {}
	local b = R.mega_base[k]
	if b == nil then
		local e = ED()
		local en = e ~= nil and mega_entry(e, k) or nil
		if en == nil then return MEGA_EMPTY end
		b = (en.info ~= nil) and tostring(en.info) or MEGA_EMPTY
		R.mega_base[k] = b
	end
	return b
end

local function mega_commit(e, sid, st)
	if S.mega == nil then S.mega = {} end
	mega_base_of(sid)
	S.mega[sid] = mega_copy(st)
	mark()
	XS.mega_overlay(e)
end
XS.mega_commit = mega_commit

function XS.mega_overlay(e)
	if S == nil or type(S.mega) ~= "table" or type(e.mega_info) ~= "table" then return end
	local want = nil
	for sid, m in pairs(S.mega) do
		want = want or {}
		want[tostring(sid)] = mega_json(m)
	end
	if want == nil then return end
	for k in pairs(want) do mega_base_of(k) end
	for _, v in pairs(e.mega_info) do
		if type(v) == "table" and v.shipId ~= nil then
			local c = want[tostring(v.shipId)]
			if c ~= nil and v.info ~= c then
				v.info = c
				R.overwrites = (R.overwrites or 0) + 1
			end
		end
	end
end

function XS.mega_restore(e)
	if S == nil or type(e.mega_info) ~= "table" then return end
	local drop, back = {}, {}
	for sid in pairs(S.heroes or {}) do drop[tostring(sid)] = true end
	for sid in pairs(S.mega or {}) do
		if not drop[tostring(sid)] then back[tostring(sid)] = mega_base_of(tostring(sid)) end
	end
	local keep = {}
	for i = 1, #e.mega_info do
		local v = e.mega_info[i]
		if type(v) == "table" and v.shipId ~= nil then
			local k = tostring(v.shipId)
			if not drop[k] then
				if back[k] ~= nil then v.info = back[k] end
				keep[#keep + 1] = v
			end
		else
			keep[#keep + 1] = v
		end
	end
	for i = #e.mega_info, 1, -1 do e.mega_info[i] = nil end
	for i = 1, #keep do e.mega_info[i] = keep[i] end
	R.mega_base = {}
end

local function mega_cum(ab, page)
	local c = xcache()
	c.cum = c.cum or {}
	local key = fint(ab) .. ":" .. fint(page)
	local t = c.cum[key]
	if t == nil then
		t = false
		local row = mrow2("mega_property", ab, page)
		if row ~= nil then
			t = {}
			local acc = { 0, 0, 0, 0 }
			for L = 0, MEGA_CAP do
				for tok in string.gmatch(tostring(row[4 + L] or ""), "[^|]+") do
					local ty, v = string.match(tok, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
					ty, v = tonumber(ty), tonumber(v)
					if ty ~= nil and v ~= nil and ty >= 0 and ty <= 3 then acc[ty + 1] = acc[ty + 1] + v end
				end
				t[L] = { acc[1], acc[2], acc[3], acc[4] }
			end
		end
		c.cum[key] = t
	end
	return t or nil
end

local function mega_bonus(ab, st)
	local out = { 0, 0, 0, 0 }
	for k, lv in pairs(st.lv) do
		local cum = mega_cum(ab, tonumber(k))
		if cum ~= nil then
			local L = math.max(0, math.min(MEGA_CAP, math.floor(lv)))
			for i = 1, 4 do out[i] = out[i] + cum[L][i] end
		end
	end
	return out
end

function XS.mega_delta(sid, tid)
	local out = { 0, 0, 0, 0 }
	if S == nil or type(S.mega) ~= "table" then return out end
	local k = tostring(sid)
	local m = S.mega[k]
	if m == nil then return out end
	local md = mega_data(tonumber(tid))
	if md == nil then return out end
	local cur = mega_bonus(md.ability, m)
	local base = { 0, 0, 0, 0 }
	if S.heroes[k] == nil then base = mega_bonus(md.ability, mega_parse(mega_base_of(k))) end
	for i = 1, 4 do out[i] = cur[i] - base[i] end
	return out
end

local function split_nums(s, sep)
	local o = {}
	for _, x in ipairs(xsplit(s, sep)) do
		local v = tonumber(x)
		if v ~= nil then o[#o + 1] = v end
	end
	return o
end

local function equip_stars(sid, ship)
	local p = prog_get(sid)
	local info = (p ~= nil and p.equipInfo) or ship.equipInfo or ""
	local sec = xsplit(info, "|")[4]
	local sum = 0
	for _, v in ipairs(split_nums(sec or "", ",")) do sum = sum + v end
	return sum
end

local function alloy_info(e, ship)
	local am = ship.alloyMatrix
	if type(am) ~= "table" or type(am.mmi) ~= "table" then return nil end
	local lvl, cnt, minq = 0, 0, nil
	local d = G("dms")
	for _, v in pairs(am.mmi) do
		if type(v) == "table" then
			for _, s in pairs(v) do
				local m = type(e.user_alloy_matrix) == "table" and e.user_alloy_matrix[tonumber(s)] or nil
				if type(m) ~= "table" then return nil end
				cnt = cnt + 1
				lvl = lvl + (tonumber(m.metalLevel) or 0)
				local q = nil
				local sc = G("ship_metal_mould")
				if type(d) == "table" and type(sc) == "table" and type(d["ship_metal_mould"]) == "table" then
					local okq, qv = pcall(d.int, d["ship_metal_mould"], m.metalMould, sc.quality)
					if okq then q = tonumber(qv) end
				end
				if q ~= nil and (minq == nil or q < minq) then minq = q end
			end
		end
	end
	if cnt == 0 then return nil end
	return { level = lvl, count = cnt, minq = minq }
end

local function owned_by_tid(e, tid)
	local out = {}
	for sid, sh in pairs(e.user_ship) do
		if type(sh) == "table" and tonumber(sh.ship_template_id) == tid then out[#out + 1] = tostring(sid) end
	end
	table.sort(out, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	return out
end

local function mega_check(e, sid, st, ms, md, t, a, b)
	if t == 1 then
		return st.star >= b
	elseif t == 2 then
		return st.order >= b
	elseif t == 3 then
		local slots = soul_slots(st.tid)
		local lvs = soul_parse(soul_current(sid, st.ship), 0)
		local total = 0
		for i = 1, #lvs do
			local sl = slots[i]
			if sl ~= nil and sl.unlock <= st.order then total = total + lvs[i] end
		end
		return total >= b
	elseif t == 4 then
		local n = mega_pages_of(ms)
		if n > a then return true end
		if n == a then return (ms.lv[fint(n)] or 0) >= b end
		return false
	elseif t == 5 then
		return equip_stars(sid, st.ship) >= b
	elseif t == 6 then
		local al = alloy_info(e, st.ship)
		if al == nil then return true end
		return al.level >= b
	elseif t == 9 then
		local al = alloy_info(e, st.ship)
		if al == nil then return true end
		if al.count < 18 then return false end
		return al.minq == nil or al.minq >= b
	elseif t == 7 or t == 8 then
		if #md.link == 0 then return false end
		for _, ltid in ipairs(md.link) do
			local okone = false
			for _, osid in ipairs(owned_by_tid(e, ltid)) do
				if t == 7 then
					local os_ = hero_state(e, osid)
					if os_ ~= nil and os_.order >= b then okone = true; break end
				else
					local o = mega_cur(e, osid)
					local n = mega_pages_of(o)
					if n > a or (n == a and (o.lv[fint(n)] or 0) >= b) then okone = true; break end
				end
			end
			if not okone then return false end
		end
		return true
	end
	return true
end

local function mega_conditions(ab, page)
	local row = mrow2("mega_unblock", ab, page)
	if row == nil then return nil end
	local out = {}
	for _, tok in ipairs(xsplit(tostring(row[4] or ""), "|")) do
		local v = split_nums(tok, ",")
		if #v >= 3 then out[#out + 1] = { v[1], v[2], v[3] } end
	end
	return out
end

local function mega_cost(ab, page, level, tid)
	local row = mrow2("mega_expend", ab, page)
	if row == nil then return nil end
	local cell = row[4 + level]
	if cell == nil or cell == "" then return nil end
	local cost = { silver = 0, props = {}, waived = {} }
	for _, tok in ipairs(xsplit(tostring(cell), "|")) do
		local v = split_nums(tok, ",")
		if #v >= 2 and v[2] > 0 then
			if v[1] == 2 then
				cost.silver = cost.silver + v[2]
			elseif v[1] == 1 then
				local sh = mega_shard(tid)
				if sh ~= nil then cost.props[sh] = (cost.props[sh] or 0) + v[2] end
			elseif v[1] == 3 then
				cost.props[223] = (cost.props[223] or 0) + v[2]
			else
				cost.waived[#cost.waived + 1] = v[1]
			end
		end
	end
	return cost
end

local function mega_reply(e, seq, name, sid)
	local ship = e.user_ship[sid]
	local F = commit_hero(e, sid, {})
	if F == nil or type(ship) ~= "table" then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	local blocks = {}
	push_all(blocks, blk_ship(ship, F))
	push_all(blocks, blk_fight(e, sid, F))
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function mega_ctx(p, seq, name, need_page_open)
	local e = ED()
	if e == nil then return nil end
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return nil, err_reply(seq, name, "LS_khong_co_tuong") end
	local page = tonumber(p[2])
	if page == nil or page < 1 or page ~= math.floor(page) then return nil, err_reply(seq, name, "LS_yeu_cau_sai") end
	local md = mega_data(st.tid)
	if md == nil or md.open <= 0 then
		return nil, xfail(seq, name, "LS_sieu_tien_hoa_chua_mo", ERR.generic, "Tuong nay chua mo Kame-Sen.")
	end
	if page > md.open or mrow2("mega_property", md.ability, page) == nil then
		return nil, xfail(seq, name, "LS_trang_chua_mo", ERR.generic, "Trang nay chua mo.")
	end
	mega_ensure(e)
	return { e = e, sid = sid, st = st, page = page, md = md, ms = mega_cur(e, sid) }
end

function XS.h_mega_unblock(p, seq)
	local name = "mega_unblock"
	local c, errs = mega_ctx(p, seq, name)
	if c == nil then return errs end
	local key = fint(c.page)
	if c.ms.lv[key] ~= nil then return xfail(seq, name, "LS_trang_da_mo", ERR.generic, "Trang nay da mo roi.") end
	if c.page ~= mega_pages_of(c.ms) + 1 then
		return xfail(seq, name, "LS_phai_mo_tuan_tu", ERR.generic, "Hay mo cac trang theo thu tu.")
	end
	local conds = mega_conditions(c.md.ability, c.page)
	if conds == nil then return xfail(seq, name, "LS_thieu_bang_dieu_kien", ERR.generic) end
	for i, cd in ipairs(conds) do
		if not mega_check(c.e, c.sid, c.st, c.ms, c.md, cd[1], cd[2], cd[3]) then
			return xfail(seq, name, "LS_chua_du_dieu_kien", ERR.generic, "Chua du dieu kien mo trang (dieu kien " .. i .. ").")
		end
	end
	c.ms.lv[key] = 0
	mega_commit(c.e, c.sid, c.ms)
	stat_inc("mega_unblock")
	log("kame-sen: tuong", c.sid, "mo trang", c.page)
	return mega_reply(c.e, seq, name, c.sid)
end

function XS.h_mega_level_up(p, seq)
	local name = "mega_level_up"
	local c, errs = mega_ctx(p, seq, name)
	if c == nil then return errs end
	local key = fint(c.page)
	local cur = c.ms.lv[key]
	if cur == nil then return xfail(seq, name, "LS_trang_chua_mo_khoa", ERR.generic, "Hay mo trang nay truoc.") end
	if cur >= MEGA_CAP then return xfail(seq, name, "LS_trang_toi_da", ERR.generic, "Trang nay da dat cap toi da.") end
	local cost = mega_cost(c.md.ability, c.page, cur, c.st.tid)
	if cost == nil then return xfail(seq, name, "LS_thieu_bang_chi_phi", ERR.generic) end
	if cost.silver > 0 and (S.silver or 0) < cost.silver then
		return xfail(seq, name, "LS_khong_du_bac", ERR.silver, "Khong du Vang.")
	end
	for tmpl, n in pairs(cost.props) do
		if LS.prop_get(tmpl) < n then
			return xfail(seq, name, "LS_khong_du_vat_pham", ERR.items, "Khong du vat pham nang cap Kame-Sen.")
		end
	end
	if cost.silver > 0 then LS.money_spend("silver", cost.silver) end
	for tmpl, n in pairs(cost.props) do LS.prop_add(tmpl, -n) end
	c.ms.lv[key] = cur + 1
	mega_commit(c.e, c.sid, c.ms)
	stat_inc("mega_level_up")
	log("kame-sen: tuong", c.sid, "trang", c.page, "bac", cur, "->", cur + 1, "bac", fint(cost.silver))
	return mega_reply(c.e, seq, name, c.sid)
end

function XS.h_mega_use_skill(p, seq)
	local name = "mega_use_skill"
	local flag = tostring(p[3] or "")
	if flag ~= "1" and flag ~= "2" then return err_reply(seq, name, "LS_yeu_cau_sai") end
	local c, errs = mega_ctx(p, seq, name)
	if c == nil then return errs end
	local list = {}
	for i = 1, #c.ms.use do
		if c.ms.use[i] ~= c.page then list[#list + 1] = c.ms.use[i] end
	end
	if flag == "1" then
		if c.page ~= 2 and c.page ~= 4 and c.page ~= 6 then
			return xfail(seq, name, "LS_trang_khong_co_ky_nang", ERR.generic, "Trang nay khong co ky nang de chon.")
		end
		if (c.ms.lv[fint(c.page)] or 0) < MEGA_CAP then
			return xfail(seq, name, "LS_ky_nang_chua_mo", ERR.generic, "Can dat bac 10 cua trang nay de dung ky nang.")
		end
		list[#list + 1] = c.page
	end
	table.sort(list)
	c.ms.use = list
	mega_commit(c.e, c.sid, c.ms)
	stat_inc("mega_skill")
	log("kame-sen: tuong", c.sid, "trang", c.page, flag == "1" and "dung ky nang" or "bo ky nang")
	return mega_reply(c.e, seq, name, c.sid)
end

local STAR_MAX = 7
local POT_STAR = 7
local POT_GRADES = 3

local function star_cost(tid, star)
	local group = tonumber(mstr(tid, "base_mould2"))
	if group == nil then return nil end
	local row = mrow2("awaken_requirement", group, star)
	if row == nil then return nil end
	local cards = rnum(row, "awaken_requirement", "need_same_card_count")
	if cards <= 0 then return nil end
	return {
		cards = cards,
		silver = math.max(0, rnum(row, "awaken_requirement", "need_silver")),
		limit = rnum(row, "awaken_requirement", "ship_level_limit"),
	}
end

local function pot_parse(str)
	local t = { 0, 0, 0 }
	local i = 0
	for v in string.gmatch(tostring(str or ""), "[^,]+") do
		i = i + 1
		if i <= POT_GRADES then t[i] = math.max(0, math.floor(tonumber(v) or 0)) end
	end
	return t
end

local function pot_str(t)
	return fint(t[1]) .. "," .. fint(t[2]) .. "," .. fint(t[3])
end

local function pot_table()
	local c = xcache()
	if c.pot == nil then
		local t = {}
		for _, part in ipairs(xsplit(cfg_str("ship_config", 33) or "", "|")) do
			local lo, hi, n, m = string.match(part, "^%s*(%d+)%s*%-%s*(%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)")
			if lo ~= nil then t[#t + 1] = { lo = tonumber(lo), hi = tonumber(hi), cards = tonumber(n), silver = tonumber(m) } end
		end
		c.pot = t
	end
	return c.pot
end

local function pot_cost(grade)
	grade = math.max(1, grade)
	for _, r in ipairs(pot_table()) do
		if grade >= r.lo and grade <= r.hi then return r end
	end
	return nil
end

local function pot_props(i)
	local c = xcache()
	c.potp = c.potp or {}
	local t = c.potp[i]
	if t == nil then
		t = { 0, 0, 0, 0, spec = {} }
		local d = G("dms")
		if type(d) == "table" and type(d["potential_attribute"]) == "table" then
			local okp, prop = pcall(d.string, d["potential_attribute"], i, 5)
			if okp and prop ~= nil then
				for tok in string.gmatch(tostring(prop), "[^|]+") do
					local ty, v = string.match(tok, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)")
					ty, v = tonumber(ty), tonumber(v)
					if ty ~= nil and v ~= nil and ty >= 0 and ty <= 3 then
						t[ty + 1] = t[ty + 1] + v
					elseif ty ~= nil and v ~= nil and ty > 3 then
						t.spec[ty] = (t.spec[ty] or 0) + v
					end
				end
			end
		end
		c.potp[i] = t
	end
	return t
end

function XS.pot_delta(cur, base)
	local out = { 0, 0, 0, 0, spec = {} }
	local a, b = pot_parse(cur), pot_parse(base)
	for i = 1, POT_GRADES do
		local per = pot_props(i)
		local d = a[i] - b[i]
		for k = 1, 4 do out[k] = out[k] + per[k] * d end
		for ty, v in pairs(per.spec) do out.spec[ty] = (out.spec[ty] or 0) + v * d end
	end
	return out
end

local function pot_current(sid, ship)
	local pg = prog_get(sid)
	if pg ~= nil and pg.qianNeng ~= nil then return pg.qianNeng end
	return ship.qianNeng
end

local function star_reply(e, seq, name, st, F)
	local blocks = {}
	push_all(blocks, blk_evo(st.ship, F))
	push_all(blocks, blk_ship(st.ship, F))
	push_all(blocks, blk_fight(e, st.sid, F))
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function XS.h_awaken(p, seq)
	local name = "ship_awaken"
	local e = ED()
	if e == nil then return nil end
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	if st.star >= STAR_MAX then
		return xfail(seq, name, "LS_sao_toi_da", ERR.rank_max, "Tuong da dat sao toi da.")
	end
	local cost = star_cost(st.tid, st.star)
	if cost == nil then return xfail(seq, name, "LS_thieu_bang_len_sao", ERR.generic) end
	if st.grade < cost.limit then
		return xfail(seq, name, "LS_cap_tuong_chua_du", ERR.hero_level, "Can tuong cap " .. fint(cost.limit) .. " de len sao.")
	end
	local shard = mega_shard(st.tid)
	if shard == nil then return xfail(seq, name, "LS_khong_co_manh_tuong", ERR.items) end
	if LS.prop_get(shard) < cost.cards then
		return xfail(seq, name, "LS_khong_du_manh_tuong", ERR.items, "Khong du manh tuong (can " .. fint(cost.cards) .. ").")
	end
	if (S.silver or 0) < cost.silver then
		return xfail(seq, name, "LS_khong_du_bac", ERR.silver, "Khong du Vang.")
	end
	if cost.silver > 0 then LS.money_spend("silver", cost.silver) end
	LS.prop_add(shard, -cost.cards)
	local star = st.star + 1
	local fields = { StarRating = fint(star) }
	if star >= POT_STAR then
		local g = pot_parse(pot_current(sid, st.ship))
		local changed = false
		for i = 1, POT_GRADES do
			if g[i] < 1 then g[i] = 1; changed = true end
		end
		if changed then fields.qianNeng = pot_str(g) end
	end
	local F = commit_hero(e, sid, fields)
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	stat_inc("star_up")
	log("tang sao: tuong", sid, "sao", st.star, "->", star, "manh", fint(cost.cards), "bac", fint(cost.silver))
	return star_reply(e, seq, name, st, F)
end

function XS.h_potential_up(p, seq)
	local name = "ship_potential_up"
	local e = ED()
	if e == nil then return nil end
	local sid = tostring(p[1] or "")
	local st = hero_state(e, sid)
	if st == nil then return err_reply(seq, name, "LS_khong_co_tuong") end
	local idx = tonumber(p[2])
	if idx == nil or idx < 1 or idx > POT_GRADES or idx ~= math.floor(idx) then
		return err_reply(seq, name, "LS_yeu_cau_sai")
	end
	if st.star < POT_STAR then
		return xfail(seq, name, "LS_chua_du_sao", ERR.star, "Can tuong 7 sao de nang Tiem nang.")
	end
	local g = pot_parse(pot_current(sid, st.ship))
	local cost = pot_cost(g[idx])
	if cost == nil then
		return xfail(seq, name, "LS_tiem_nang_toi_da", ERR.rank_max, "Tiem nang da dat cap toi da.")
	end
	local shard = mega_shard(st.tid)
	if shard == nil then return xfail(seq, name, "LS_khong_co_manh_tuong", ERR.items) end
	if LS.prop_get(shard) < cost.cards then
		return xfail(seq, name, "LS_khong_du_manh_tuong", ERR.items, "Khong du manh tuong (can " .. fint(cost.cards) .. ").")
	end
	if (S.silver or 0) < cost.silver then
		return xfail(seq, name, "LS_khong_du_bac", ERR.silver, "Khong du Vang.")
	end
	if cost.silver > 0 then LS.money_spend("silver", cost.silver) end
	LS.prop_add(shard, -cost.cards)
	g[idx] = g[idx] + 1
	local F = commit_hero(e, sid, { qianNeng = pot_str(g) })
	if F == nil then return err_reply(seq, name, "LS_loi_tinh_chi_so") end
	stat_inc("potential_up")
	log("tiem nang: tuong", sid, "o", idx, "cap", g[idx] - 1, "->", g[idx], "manh", fint(cost.cards), "bac", fint(cost.silver))
	return star_reply(e, seq, name, st, F)
end

XS.star_cost, XS.pot_parse, XS.pot_cost, XS.pot_props = star_cost, pot_parse, pot_cost, pot_props

function XS.full_soul(tid)
	local n = #soul_slots(tonumber(tid))
	if n < 4 then n = 4 end
	local t = {}
	for i = 1, n do t[i] = fint(SOUL_CAP) .. ",0" end
	return table.concat(t, "|")
end

function XS.full_pot()
	local mx = 1
	for _, r in ipairs(pot_table()) do
		if r.hi + 1 > mx then mx = r.hi + 1 end
	end
	return pot_str({ mx, mx, mx }), mx
end

function XS.full_mega(tid)
	local md = mega_data(tonumber(tid))
	if md == nil or md.open <= 0 then return nil end
	local st = { lv = {}, use = {} }
	for p = 1, md.open do
		if mrow2("mega_property", md.ability, p) ~= nil then st.lv[fint(p)] = MEGA_CAP end
	end
	if next(st.lv) == nil then return nil end
	for _, p in ipairs({ 2, 4, 6 }) do
		if st.lv[fint(p)] ~= nil then st.use[#st.use + 1] = p end
	end
	return { json = mega_json(st), bonus = mega_bonus(md.ability, st), pages = md.open, use = st.use }
end

XS.STAR_MAX, XS.SOUL_CAP, XS.MEGA_CAP = STAR_MAX, SOUL_CAP, MEGA_CAP

function XS.extra_items(skip)
	local list, seen = {}, {}
	for i = 1, #(skip or {}) do seen[tonumber(skip[i])] = true end
	local function add(t)
		t = tonumber(t)
		if t ~= nil and t > 0 and not seen[t] and prop_known(t) then seen[t] = true; list[#list + 1] = t end
	end
	add(223)
	for _, t in ipairs({ 243, 231, 232, 233, 234 }) do add(t) end
	local e = ED()
	if e ~= nil and type(e.user_ship) == "table" then
		local tids, ids = {}, {}
		for _, sh in pairs(e.user_ship) do
			if type(sh) == "table" then tids[tonumber(sh.ship_template_id) or 0] = true end
		end
		for t in pairs(tids) do ids[#ids + 1] = t end
		table.sort(ids)
		for _, tid in ipairs(ids) do
			local sh = mega_shard(tid)
			if sh ~= nil then add(sh) end
		end
	end
	return list
end

XS.mega_data, XS.mega_parse, XS.mega_json, XS.mega_cur = mega_data, mega_parse, mega_json, mega_cur
XS.mega_check, XS.mega_cost, XS.mega_bonus, XS.mega_conditions = mega_check, mega_cost, mega_bonus, mega_conditions
XS.mega_shard, XS.mega_cum, XS.mega_pages_of = mega_shard, mega_cum, mega_pages_of

function XS.mega_check_sid(sid, t, a, b)
	local e = ED()
	if e == nil then return nil end
	sid = tostring(sid)
	local st = hero_state(e, sid)
	if st == nil then return nil end
	local md = mega_data(st.tid)
	if md == nil then return nil end
	return mega_check(e, sid, st, mega_cur(e, sid), md, t, a, b)
end

end
init_xs()
end

do
local function init_tr()

local TR = {}

local ACT = 148
local DAY = 86400

local function tcell(tname, id, col)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return nil end
	local ok, v = pcall(d.string, d[tname], id, col)
	if ok and v ~= nil then return tostring(v) end
	return nil
end

local function trows(tname)
	local d = G("dms")
	local ids = {}
	if type(d) == "table" and type(d[tname]) == "table" then
		for k in pairs(d[tname]) do
			if type(k) == "number" then ids[#ids + 1] = k end
		end
		table.sort(ids)
	end
	return ids
end

local function tlist(s)
	local t = {}
	for w in string.gmatch(tostring(s or ""), "%-?%d+") do
		local n = tonumber(w)
		if n ~= nil and n > 0 then t[#t + 1] = n end
	end
	table.sort(t)
	return t
end

function TR.items()
	if R.tr_items ~= nil then return R.tr_items end
	local by, order, top = {}, {}, 0
	for _, id in ipairs(trows("activity_treasures_item")) do
		local reward = tonumber(tcell("activity_treasures_item", id, 2))
		local rare = (tcell("activity_treasures_item", id, 3) == "1")
		local w = tonumber(tcell("activity_treasures_item", id, 4)) or 0
		local cnt = tonumber(tcell("activity_treasures_item", id, 5)) or 0
		local pity = tlist(tcell("activity_treasures_item", id, 6))
		local flag = (tcell("activity_treasures_item", id, 7) == "1")
		if id > top then top = id end
		if reward ~= nil and reward > 0 and cnt >= 1 then
			by[id] = { id = id, reward = math.floor(reward), rare = rare, w = math.max(0, w), cnt = math.floor(cnt),
				pity = pity, flag = flag }
			order[#order + 1] = id
		end
	end
	R.tr_items = { by = by, order = order, top = top }
	return R.tr_items
end

local function cfgn(row, def)
	local v = tonumber(cfg_str("activity_config", row))
	if v == nil then return def end
	return v
end

function TR.conf()
	if R.tr_conf ~= nil then return R.tr_conf end
	local c = {
		free = math.max(0, math.floor(cfgn(24, 3))),
		ticket = math.floor(cfgn(25, 552)),
		s1 = math.max(0, math.floor(cfgn(26, 10))),
		s10 = math.max(0, math.floor(cfgn(27, 110))),
		gem = math.max(0, math.floor(cfgn(28, 68))),
		rfree = math.max(0, math.floor(cfgn(30, 3))),
		shown = math.max(1, math.floor(cfgn(34, 16))),
		rare_n = math.max(0, math.floor(cfgn(35, 4))),
		rcost = {},
	}
	for w in string.gmatch(tostring(cfg_str("activity_config", 29) or ""), "%d+") do
		c.rcost[#c.rcost + 1] = tonumber(w)
	end
	if #c.rcost == 0 then c.rcost = { 10, 10, 20, 20, 50, 100, 100, 100, 100, 100 } end
	if c.rare_n > c.shown then c.rare_n = c.shown end
	R.tr_conf = c
	return c
end

local function parse_item(s)
	local a, b, c = string.match(tostring(s or ""), "^%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)")
	if a == nil then return nil end
	return tonumber(a), tonumber(b), tonumber(c)
end

function TR.shop()
	if R.tr_shop ~= nil then return R.tr_shop end
	local out = {}
	for _, id in ipairs(trows("activity_treasures_shop")) do
		local item = tcell("activity_treasures_shop", id, 3)
		local price = tonumber(tcell("activity_treasures_shop", id, 4))
		local limit = tonumber(tcell("activity_treasures_shop", id, 5))
		local ty, mid, num = parse_item(item)
		if ty ~= nil and price ~= nil and price > 0 and num ~= nil and num > 0 then
			out[#out + 1] = { item = tostring(item), price = math.floor(price), limit = math.floor(limit or -1),
				ty = ty, mid = mid, num = math.floor(num) }
		end
	end
	R.tr_shop = out
	return out
end

local function jnum(n) return fint(tn(n, 0)) end

local function jarr(list)
	local b = {}
	for i = 1, #list do b[i] = jnum(list[i]) end
	return "[" .. table.concat(b, ",") .. "]"
end

local function jq(s)
	local r = string.gsub(tostring(s), '[%c"\\ ]', function(ch)
		if ch == '"' then return '\\"' end
		if ch == "\\" then return "\\\\" end
		if ch == " " then return "\194\160" end
		return string.format("\\u%04x", string.byte(ch))
	end)
	return '"' .. r .. '"'
end

local function jget(s, key)
	s = tostring(s or "")
	local v = string.match(s, '"' .. key .. '"%s*:%s*"([^"]*)"')
	if v ~= nil then return v end
	return string.match(s, '"' .. key .. '"%s*:%s*(%-?[%d%.]+)')
end

local function today() return os.date("%Y%m%d") end

local function shuffle(list)
	for i = #list, 2, -1 do
		local j = math.floor(math.random() * i) + 1
		if j > i then j = i end
		list[i], list[j] = list[j], list[i]
	end
	return list
end

function TR.shuffle_board(t)
	local it, c = TR.items(), TR.conf()
	local pool, rares, spare = {}, {}, {}
	for _, id in ipairs(it.order) do
		local x = it.by[id]
		if x.rare then
			rares[#rares + 1] = id
		elseif x.w > 0 then
			pool[#pool + 1] = id
		else
			spare[#spare + 1] = id
		end
	end
	if #pool == 0 then pool = spare end
	local nn = c.shown - c.rare_n
	if nn < 1 then nn = 1 end
	shuffle(pool)
	shuffle(rares)
	t.normal, t.rare = {}, {}
	for i = 1, math.min(nn, #pool) do t.normal[i] = pool[i] end
	for i = 1, math.min(c.rare_n, #rares) do t.rare[i] = rares[i] end
	t.hit = {}
end

local function new_tr()
	local c = TR.conf()
	local t = { v = 1, score = 0, spent = 0, draws = 0, day = today(), fdraw = c.free, frefresh = c.rfree,
		prefresh = 0, pity = {}, shop = {}, normal = {}, rare = {}, hit = {} }
	TR.shuffle_board(t)
	return t
end

local function clean_int(v, hi)
	local x = tonumber(v)
	if x == nil or x ~= x or x < 0 then return 0 end
	if x > hi then return hi end
	return math.floor(x)
end

local function board_ok(t)
	local it, c = TR.items(), TR.conf()
	if type(t.normal) ~= "table" or type(t.rare) ~= "table" then return false end
	local npool, nrare, nspare = 0, 0, 0
	for _, id in ipairs(it.order) do
		local x = it.by[id]
		if x.rare then nrare = nrare + 1 elseif x.w > 0 then npool = npool + 1 else nspare = nspare + 1 end
	end
	if npool == 0 then npool = nspare end
	local nn = math.max(1, c.shown - c.rare_n)
	if #t.normal ~= math.min(nn, npool) or #t.rare ~= math.min(c.rare_n, nrare) then return false end
	local seen = {}
	for _, spec in ipairs({ { t.normal, false }, { t.rare, true } }) do
		local list, want_rare = spec[1], spec[2]
		for i = 1, #list do
			local id = list[i]
			local x = (type(id) == "number") and it.by[id] or nil
			if x == nil or x.rare ~= want_rare or seen[id] then return false end
			seen[id] = true
		end
	end
	return true
end

local function repair(t)
	local it = TR.items()
	local changed = false
	if type(t.pity) ~= "table" then t.pity = {}; changed = true end
	if type(t.shop) ~= "table" then t.shop = {}; changed = true end
	if type(t.hit) ~= "table" then t.hit = {}; changed = true end
	local c = TR.conf()
	local caps = { score = 1e15, spent = 1e15, draws = 1e15, fdraw = c.free, frefresh = c.rfree, prefresh = 1e9 }
	for _, k in ipairs({ "score", "spent", "draws", "fdraw", "frefresh", "prefresh" }) do
		local v = clean_int(t[k], caps[k])
		if t[k] ~= v then t[k] = v; changed = true end
	end
	for _, m in ipairs({ t.pity, t.shop }) do
		for k, v in pairs(m) do
			local x = clean_int(v, 1e9)
			if type(k) ~= "string" or tonumber(k) == nil then
				m[k] = nil; changed = true
			elseif m[k] ~= x then
				m[k] = x; changed = true
			end
		end
	end
	for i = 1, #t.hit do
		local id = t.hit[i]
		if type(id) ~= "number" or it.by[id] == nil then t.hit = {}; changed = true; break end
	end
	if type(t.day) ~= "string" then t.day = today(); changed = true end
	if not board_ok(t) then
		TR.shuffle_board(t)
		changed = true
	end
	if changed then
		R.tr_dirty = true
		mark()
	end
end

local function rollover(t)
	local d = today()
	if t.day ~= d then
		local c = TR.conf()
		t.day = d
		t.fdraw, t.frefresh, t.prefresh = c.free, c.rfree, 0
		R.tr_dirty = true
		mark()
	end
end

function TR.params(t)
	local it = TR.items()
	local ar = {}
	for i = 1, it.top do ar[i] = it.by[i] and it.by[i].reward or 0 end
	local dr = {}
	for _, id in ipairs(it.order) do
		local x = it.by[id]
		dr[#dr + 1] = jq(jnum(x.reward)) .. ":" .. jq("6," .. jnum(x.reward) .. "," .. jnum(x.cnt))
	end
	local sh = {}
	for i, r in ipairs(TR.shop()) do
		sh[i] = '{"item":' .. jq(r.item) .. ',"score":' .. jnum(r.price) .. ',"num":' .. jnum(r.limit) .. "}"
	end
	local keys = {}
	for k in pairs(t.shop) do keys[#keys + 1] = k end
	table.sort(keys, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	local si = {}
	for _, k in ipairs(keys) do si[#si + 1] = jq(k) .. ":" .. jnum(t.shop[k]) end
	local parts = {
		'"score":' .. jnum(t.score),
		'"freeRefreshTimes":' .. jnum(t.frefresh),
		'"payRefreshTimes":' .. jnum(t.prefresh),
		'"freeDrawTimes":' .. jnum(t.fdraw),
		'"normalItemList":' .. jarr(t.normal),
		'"diamondItemList":' .. jarr(t.rare),
		'"actConfig":{"allReward":' .. jarr(ar) .. ',"detailRewards":{' .. table.concat(dr, ",") .. '},"shop":['
			.. table.concat(sh, ",") .. "]}",
		'"shopInfo":{' .. table.concat(si, ",") .. "}",
	}
	if #t.hit > 0 then parts[#parts + 1] = '"ex":{"hitItemList":' .. jarr(t.hit) .. "}" end
	return "{" .. table.concat(parts, ",") .. "}"
end

local function rare_info()
	if R.tr_info ~= nil then return R.tr_info end
	local it = TR.items()
	local list = {}
	for _, id in ipairs(it.order) do
		local x = it.by[id]
		if x.rare then
			list[#list + 1] = {
				activityInfo_name = "", activityInfo_silver = "0", activityInfo_gold = "0", activityInfo_food = "0",
				activityInfo_honour = "0", index = #list + 1, activityInfo_general_soul = "0",
				activityInfo_prop_count = "0", activityInfo_prop_info = {}, activityInfo_equip_count = "0",
				activityInfo_equip_info = {}, activityInfo_icon = "0", activityInfo_exp = "0", activityInfo_isReward = "1",
				activityInfo_need_day = jnum(x.cnt), activityInfo_reward_select = "6," .. jnum(x.reward) .. "," .. jnum(x.cnt),
			}
		end
	end
	local c = TR.conf()
	while #list > c.rare_n do list[#list] = nil end
	R.tr_info = list
	return list
end

local function refresh_home()
	local sm = G("state_machine")
	if type(sm) == "table" and type(sm.excute) == "function" then
		pcall(sm.excute, "home_update_top_activity_info_state", 0, nil)
	end
end

function TR.ensure(e)
	if S == nil or type(e) ~= "table" or type(e.active_activity) ~= "table" then return false end
	if #TR.items().order == 0 then return false end
	local t = S.tr
	if type(t) ~= "table" then
		t = new_tr()
		S.tr = t
		R.tr_dirty = true
		mark()
	end
	repair(t)
	rollover(t)
	local a = e.active_activity[ACT]
	local made = false
	if type(a) ~= "table" then
		a = {}
		e.active_activity[ACT] = a
		made = true
	end
	if R.tr_dirty or R.tr_json == nil or R.tr_for ~= t then
		R.tr_json = TR.params(t)
		R.tr_for = t
		R.tr_dirty = false
	end
	if a.activity_id == nil or tostring(a.activity_id) == "" or tonumber(a.activity_id) == nil then
		a.activity_id = "1480001"
	end
	if a.activity_describe == nil then a.activity_describe = "-1" end
	if a.activity_isReward == nil then a.activity_isReward = "0" end
	if a.activity_params ~= R.tr_json then a.activity_params = R.tr_json end
	local info = rare_info()
	if a.activity_Info ~= info then
		a.activity_Info = info
		a.activity_count = jnum(#info)
	end
	if a.activity_limit_time == nil then a.activity_limit_time = "0" end
	if a.total_recharge_count == nil then a.total_recharge_count = "0" end
	if a.need_recharge_count == nil then a.need_recharge_count = "0" end
	local now = os.time()
	local cur = tonumber(a.end_time)
	if cur == nil or cur / 1000 - now < 30 * DAY then
		a.end_time = fint((now + 400 * DAY) * 1000)
	end
	if tonumber(a.begin_time) == nil then a.begin_time = fint((now - DAY) * 1000) end
	if made then
		log("su kien Dragon Treasure: da tao muc _ED.active_activity[148]")
		refresh_home()
	end
	return made
end

function TR.pick(t)
	local it = TR.items()
	local lst, total = {}, 0
	for _, list in ipairs({ t.normal, t.rare }) do
		for i = 1, #list do
			local x = it.by[list[i]]
			if x ~= nil then
				lst[#lst + 1] = list[i]
				total = total + x.w
			end
		end
	end
	if #lst == 0 then return nil end
	if total <= 0 then return lst[math.floor(math.random() * #lst) + 1] or lst[#lst] end
	local r = math.random() * total
	local acc = 0
	for i = 1, #lst do
		local w = it.by[lst[i]].w
		if w > 0 then
			acc = acc + w
			if r < acc then return lst[i] end
		end
	end
	for i = #lst, 1, -1 do
		if it.by[lst[i]].w > 0 then return lst[i] end
	end
	return lst[#lst]
end

function TR.pity_hit(t)
	local it = TR.items()
	local on = {}
	for _, list in ipairs({ t.normal, t.rare }) do
		for i = 1, #list do on[list[i]] = true end
	end
	for _, id in ipairs(it.order) do
		local x = it.by[id]
		if on[id] and #x.pity > 0 then
			local k = tn(t.pity[fint(id)], 0)
			if k < #x.pity and t.spent >= x.pity[k + 1] then
				t.pity[fint(id)] = k + 1
				return id
			end
		end
	end
	return nil
end

local function tfail(seq, name, msg, code, say)
	if say ~= nil then toast(say, 6) end
	return err_reply(seq, name, msg, code)
end

local function blk_params(e, t)
	local a = e.active_activity[ACT]
	return { "13023", fint(ACT), fint(tn(a.activity_id, 1480001)), a.activity_params }
end

local function live()
	local e = ED()
	if e == nil or S == nil or type(e.active_activity) ~= "table" then return nil end
	if #TR.items().order == 0 then return nil end
	TR.ensure(e)
	local t = S.tr
	if type(t) ~= "table" or type(e.active_activity[ACT]) ~= "table" then return nil end
	return e, t
end

local function player_name(e)
	local n = (type(e.user_info) == "table") and e.user_info.user_name or nil
	n = tostring(n or "")
	if n == "" then n = "Player" end
	return n
end

local function blk_notice(name, reward, cnt)
	return { "13036", "{" .. '"name":' .. jq(name) .. ',"value":' .. jq("6," .. jnum(reward) .. "," .. jnum(cnt)) .. "}" }
end

function TR.h_activity(p, seq)
	local at = tonumber(jget(p[1], "actType"))
	if at ~= ACT then return nil end
	local e, t = live()
	if e == nil then return nil end
	return reply(seq, "activity_refresh", blk_params(e, t))
end

function TR.h_info(p, seq)
	local e, t = live()
	if e == nil then return nil end
	return reply(seq, "treasures_shop_info", blk_params(e, t))
end

function TR.h_draw(p, seq)
	local name = "treasures_draw"
	local e, t = live()
	if e == nil then return nil end
	local ty = tonumber(jget(p[1], "type"))
	if ty ~= 0 and ty ~= 1 then return err_reply(seq, name, "LS_yeu_cau_sai") end
	local n = (ty == 0) and 1 or 10
	local c, it = TR.conf(), TR.items()

	local cost
	if n == 1 and t.fdraw > 0 then
		cost = { kind = "free" }
	elseif c.ticket > 0 and LS.prop_get(c.ticket) >= n then
		cost = { kind = "prop", n = n }
	elseif S.gold ~= nil and S.gold >= c.gem * n then
		cost = { kind = "gold", n = c.gem * n }
	else
		return tfail(seq, name, "LS_khong_du_KC", ERR.generic, "Khong du KC (" .. fint(c.gem * n) .. ") hoac ve quay.")
	end
	if cost.kind == "free" then
		t.fdraw = t.fdraw - 1
	elseif cost.kind == "prop" then
		LS.prop_add(c.ticket, -cost.n)
	else
		LS.money_spend("gold", cost.n)
	end
	local hits = {}
	for i = 1, n do
		if cost.kind == "gold" then t.spent = t.spent + c.gem end
		local id = TR.pity_hit(t) or TR.pick(t)
		hits[i] = id
	end

	local got, order, notes = {}, {}, {}
	for i = 1, #hits do
		local x = it.by[hits[i]]
		if got[x.reward] == nil then got[x.reward] = 0; order[#order + 1] = x.reward end
		got[x.reward] = got[x.reward] + x.cnt
		if x.flag then notes[#notes + 1] = x end
	end
	local list = {}
	for _, k in ipairs(order) do
		LS.prop_add(k, got[k])
		list[#list + 1] = { k, 6, got[k] }
	end
	t.score = t.score + ((n == 1) and c.s1 or c.s10)
	t.draws = t.draws + n
	t.hit = hits
	stat_inc("treasure_draw", n)
	R.tr_dirty = true
	mark()
	TR.ensure(e)
	local blocks = {}
	push_all(blocks, blk_params(e, t))
	push_all(blocks, WS.blk_reward(list))
	local who = player_name(e)
	for _, x in ipairs(notes) do push_all(blocks, blk_notice(who, x.reward, x.cnt)) end
	LS.save_state(true)
	log("treasure: quay", n, cost.kind, "diem", t.score, "KC da tieu", t.spent, "trung", table.concat(hits, ","))
	return reply(seq, name, blocks)
end

function TR.h_refresh(p, seq)
	local name = "treasures_refresh"
	local e, t = live()
	if e == nil then return nil end
	local c = TR.conf()
	if t.frefresh > 0 then
		t.frefresh = t.frefresh - 1
	else
		local k = t.prefresh + 1
		if k > #c.rcost then k = #c.rcost end
		local price = c.rcost[k]
		if S.gold == nil or S.gold < price then
			return tfail(seq, name, "LS_khong_du_KC", ERR.generic, "Khong du KC de lam moi (" .. fint(price) .. ").")
		end
		LS.money_spend("gold", price)
		t.prefresh = t.prefresh + 1
	end
	TR.shuffle_board(t)
	stat_inc("treasure_refresh")
	R.tr_dirty = true
	mark()
	TR.ensure(e)
	LS.save_state(true)
	return reply(seq, name, blk_params(e, t))
end

function TR.h_shop_buy(p, seq)
	local name = "treasures_shop_buy"
	local e, t = live()
	if e == nil then return nil end
	local idx = tonumber(jget(p[1], "itemId"))
	local cnt = tonumber(jget(p[1], "buyCount")) or 1
	local rows = TR.shop()
	if idx == nil or idx ~= math.floor(idx) or rows[idx] == nil or cnt < 1 or cnt ~= math.floor(cnt) then
		return err_reply(seq, name, "LS_yeu_cau_sai")
	end
	local r = rows[idx]
	local key = fint(idx)
	local bought = tn(t.shop[key], 0)
	if r.limit ~= -1 and bought + cnt > r.limit then
		return tfail(seq, name, "LS_het_luot_mua", ERR.generic, "Da het luot doi vat pham nay.")
	end
	local price = r.price * cnt
	if t.score < price then
		return tfail(seq, name, "LS_khong_du_diem", ERR.generic, "Khong du diem (can " .. fint(price) .. ").")
	end
	local total = r.num * cnt
	if r.ty == 6 then
		if not LS.prop_add(r.mid, total) then return err_reply(seq, name, "LS_loi_cap_vat_pham") end
	elseif r.ty == 7 then
		EQ.bag_set(e, r.mid, EQ.bag_have(e, r.mid) + total)
	elseif r.ty == 1 then
		LS.money_add("silver", total)
	elseif r.ty == 2 then
		LS.money_add("gold", total)
	else
		return tfail(seq, name, "LS_loai_thuong_chua_ho_tro", ERR.generic, "Loai phan thuong nay chua ho tro offline.")
	end
	t.score = t.score - price
	t.shop[key] = bought + cnt
	stat_inc("treasure_buy", cnt)
	R.tr_dirty = true
	mark()
	TR.ensure(e)
	local blocks = {}
	push_all(blocks, blk_params(e, t))
	push_all(blocks, WS.blk_reward({ { r.mid, r.ty, total } }))
	LS.save_state(true)
	log("treasure: doi", r.item, "x", cnt, "tru", price, "diem, con", t.score)
	return reply(seq, name, blocks)
end

function LS.gm_treasure()
	if not LS.ready() then return nil end
	local e = ED()
	if e == nil then return nil end
	if #TR.items().order == 0 then return nil end
	TR.ensure(e)
	local t = S.tr
	if type(t) ~= "table" then return nil end
	local c = TR.conf()
	t.score = t.score + 10000
	t.fdraw, t.frefresh, t.prefresh = c.free, c.rfree, 0
	if c.ticket > 0 then LS.prop_add(c.ticket, 100) end
	stat_inc("gm_treasure")
	R.tr_dirty = true
	mark()
	TR.ensure(e)
	LS.save_state(true)
	log("GM SU KIEN: +10000 diem, +100 ve quay")
	return 10000, 100
end

function TR.status_line()
	local t = S ~= nil and S.tr or nil
	if type(t) ~= "table" then return "[LS treasure] chua tao" end
	local pk = {}
	for k, v in pairs(t.pity) do pk[#pk + 1] = k .. "=" .. fint(v) end
	table.sort(pk)
	return "[LS treasure] diem " .. fint(t.score) .. " quay " .. fint(t.draws) .. " KC-da-tieu " .. fint(t.spent)
		.. " mien-phi " .. fint(t.fdraw) .. "/" .. fint(t.frefresh) .. " moc-bao-ve {" .. table.concat(pk, ",") .. "}"
end

TR.jget, TR.jq, TR.jarr, TR.parse_item, TR.rare_info = jget, jq, jarr, parse_item, rare_info
TR.today, TR.repair, TR.rollover, TR.new_state = today, repair, rollover, new_tr
TR.ACT = ACT
LS._tr = TR

end
init_tr()
end

do
local function init_inf()

local INF = {}

local REG = rawget(_G, "__LS_INF_REG")
if type(REG) ~= "table" then
	REG = {}
	rawset(_G, "__LS_INF_REG", REG)
end
if type(REG.hooked) ~= "table" then REG.hooked = setmetatable({}, { __mode = "k" }) end
REG.cur = INF
INF.CAP = 200
INF.CAPS = { 100, 200, 500, 1000 }

function INF.cap()
	local c = (S ~= nil and type(S.cfg) == "table") and tonumber(S.cfg.round_cap) or nil
	if c ~= nil and c >= 20 and c <= 5000 then return math.floor(c) end
	return INF.CAP
end

local function cfg_on(key)
	return S ~= nil and type(S.cfg) == "table" and S.cfg[key] ~= false
end

function INF.round_active()
	return false -- offline table round limits are mandatory
end

local function lift(fm)
	if type(fm) ~= "table" then return end
	-- [FIX Cell Game] tran the gioi boss o che do Cell Game bi KHOA 5 round: khong nang len muc vo han
	local rl = LS.round_lock
	if rl ~= nil and rl(fm) ~= nil then return end
	local t = tonumber(fm.totalRound)
	local cap = INF.cap()
	if t ~= nil and t < cap then
		fm.totalRound = cap
		R.inf_lifts = (R.inf_lifts or 0) + 1
	end
end
INF._lift = lift

function INF.wrap(FM)
	if type(FM) ~= "table" or rawget(FM, "_ls_inf") == true then return false end
	local rc, ib = rawget(FM, "roundCountChange"), rawget(FM, "initBattleInfo")
	if type(rc) ~= "function" then return false end
	FM.roundCountChange = function(self, ...)
		local cur = REG.cur
		if cur ~= nil and cur.round_active() then cur._lift(self) end
		return rc(self, ...)
	end
	if type(ib) == "function" then
		FM.initBattleInfo = function(self, ...)
			local a, b = ib(self, ...)
			local cur = REG.cur
			if cur ~= nil and cur.round_active() then cur._lift(self) end
			return a, b
		end
	end
	FM._ls_inf = true
	return true
end

function INF.patch_class()
	local ok, res = pcall(INF.wrap, G("FightModule"))
	if ok and res then
		R.inf_wraps = (R.inf_wraps or 0) + 1
		log("vo han round: da boc FightModule (lan", R.inf_wraps, ")")
	elseif not ok then
		R.inf_errs = (R.inf_errs or 0) + 1
		if R.inf_errs <= 5 then log("loi boc FightModule:", tostring(res)) end
	end
	return ok and res or false
end

function INF.hook_load()
	local app = G("app")
	if type(app) ~= "table" or type(app.load) ~= "function" or REG.hooked[app.load] then return false end
	local orig = app.load
	local w
	w = function(path, ...)
		local a, b = orig(path, ...)
		if type(path) == "string" and (string.find(path, "FightModule", 1, true) ~= nil
			or string.find(path, "BattleReport", 1, true) ~= nil) then
			local cur = REG.cur
			if cur ~= nil then pcall(cur.patch_class) end
		end
		return a, b
	end
	REG.hooked[w] = true
	app.load = w
	return true
end

function INF.tick()
	INF.patch_class()
	INF.hook_load()
end

function LS.inf_state()
	return false, cfg_on("inf_att"), nil
end

function LS.gm_cycle_round_cap()
    -- Kept for compatibility with older GM panels; never changes saved limits.
    return nil
end

function LS.gm_toggle_inf_round()
    return false
end

function LS.gm_toggle_inf_att()
	if S == nil then return nil end
	S.cfg.inf_att = not cfg_on("inf_att")
	if S.cfg.inf_att and type(S.camp) == "table" then S.camp.att = {} end
	if S.cfg.inf_att and type(S.ud) == "table" then S.ud.used = 0 end
	R.camp_ids = nil
	mark()
	LS.save_state(true)
	log("vo han luot:", S.cfg.inf_att and "BAT" or "TAT")
	return S.cfg.inf_att
end

LS._inf = INF
INF.cfg_on = cfg_on

end
init_inf()
end

do
local function init_art()

local ART = {}
-- [AUTO-UNLOCK v2] Truoc day cam cung tid 367 (Goku Perfected UI) va 371 => khong bao gio duoc cap du game da co file.
-- Nay bo cam cung: ban co file that (icon + spine + atlas + ky nang) la tu duoc cap; file hong thi bo loc dong (S.fxbad)
-- tu loai, va quen lai sau moi lan game cap nhat. Muon cam tay 1 tuong: dung offline_lr_ban.txt.
ART.BAD = {}
ART.MAX_REJECT = 1.01
-- [FIX tat ca tuong] Tuong DA CO HINH (icon + spine form dang dung) thi duoc cap, khong bi loai chi vi
-- thieu / hong file hieu ung ky nang. Game da co co che thay "hieu ung gia" khi file hieu ung hong
-- (xem SPINE thieu/hong -> dung hieu ung gia trong offline_errors.txt). Dat true de bat lai kiem tra chat.
ART.FX_STRICT = false

local function d_int(tname, id, col)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return 0 end
	local ok, v = pcall(d.int, d[tname], id, col)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function d_str(tname, id, col)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return "" end
	local ok, v = pcall(d.string, d[tname], id, col)
	if ok and v ~= nil then return tostring(v) end
	return ""
end

local function scol(tbl, name, dflt)
	local sch = G(tbl)
	if type(sch) == "table" and tonumber(sch[name]) ~= nil then return sch[name] end
	return dflt
end

function ART.exists(path)
	local cc = G("cc")
	if type(cc) ~= "table" or cc.FileUtils == nil then return nil end
	local ok, v = pcall(function() return cc.FileUtils:getInstance():isFileExist(path) end)
	if not ok or v == nil then return nil end
	return v == true
end

function ART.forms(tid)
	local out = {}
	local s = d_str("ship_mould", tid, scol("ship_mould", "fitSkillTwo", 72))
	for w in string.gmatch(s, "[^,]+") do
		local eid = tonumber(w)
		if eid ~= nil and eid > 0 then
			local f = d_int("ship_evo_mould", eid, scol("ship_evo_mould", "form_id", 5))
			out[#out + 1] = f
		else
			out[#out + 1] = 0
		end
	end
	return out
end

function ART.paths(form)
	return string.format("images/ui/props/props_%d.png", form), string.format("sprite/spirte_%d.json", form)
end

function ART.form_state(form)
	R.art_cache = R.art_cache or {}
	local c = R.art_cache[form]
	if c ~= nil then return c end
	local ip, sp = ART.paths(form)
	local ic = ART.exists(ip)
	-- [AUTO-UNLOCK] icon tuong moi co the nam o images/face/hero_head/ thay vi images/ui/props/
	if ic ~= true then
		local alt = ART.exists(string.format("images/face/hero_head/props_%d.png", form))
		if alt == true then ic = true end
	end
	c = { icon = ic, spine = ART.exists(sp) }
	R.art_cache[form] = c
	return c
end

function ART.mode()
	if R.art_mode ~= nil then return R.art_mode end
	local m = { on = false, spine = false, reason = "", pending = false }
	local e = ED()
	local real = {}
	if e ~= nil and type(e.user_ship) == "table" then
		for sid, sh in pairs(e.user_ship) do
			if type(sh) == "table" and (S == nil or S.heroes[tostring(sid)] == nil) and tonumber(sh.ship_template_id) ~= nil then
				real[#real + 1] = sh
				if #real >= 12 then break end
			end
		end
	end
	if #real == 0 then
		m.pending = true
		m.reason = "chua co tuong that de hieu chuan"
		return m
	end
	local any_icon, any_spine, unknown = false, false, 0
	for i = 1, #real do
		local sh = real[i]
		local forms = ART.forms(tonumber(sh.ship_template_id))
		local stage = tonumber(string.match(tostring(sh.evolution_status or "1"), "^(%d+)")) or 1
		local f = forms[stage] or forms[1]
		if f ~= nil and f > 0 then
			local st = ART.form_state(f)
			if st.icon == nil then unknown = unknown + 1 end
			if st.icon == true then any_icon = true end
			if st.spine == true then any_spine = true end
		end
	end
	if any_icon then
		m.on = true
		m.spine = any_spine
		m.reason = "hieu chuan tu " .. #real .. " tuong that" .. (any_spine and "" or " (khong doi hinh trong tran)")
	else
		m.reason = (unknown > 0 and "isFileExist khong dung duoc" or "hinh tuong that cung bao khong ton tai") .. " -> bo loc TAT"
	end
	R.art_mode = m
	return m
end

-- ===========================================================================================
-- [FIX tuong chua phat hanh] KIEM TRA DAY DU file cua tuong truoc khi CAP / chon lam doi thu.
-- Loi that tren may (offline_errors.txt): "Invalid skeleton JSON: scale / name / translate ..."
-- o spine_effect (Fight:LoadAssetsInTigerGate, FightRole:createEffect) = file HIEU UNG ky nang
-- co trong may nhung bi cat cut / hong. Bo loc cu chi xet icon + spine cua DANG 1 nen khong thay.
-- Nay kiem tra:
--   1. form o cap tien hoa ma tuong se duoc tao (captain_name), khong chi dang 1;
--   2. moi hieu ung cua ky nang thuong + tuyet ky (+ chuoi hieu dung noi tiep): file .json + .atlas;
--   3. noi dung JSON (dau / cuoi / ngoac can doi) neu may doc duoc file;
--   4. file da tung gay loi luc chay (S.fxbad, hoc qua LS.on_bad_spine).
-- Moi phep do deu hieu chuan bang TUONG THAT cua nguoi choi; khong hieu chuan duoc thi tat phan do.
-- Chi ap dung khi CAP / CHON tuong moi (ART.filter). ART.check / ART.prune giu nguyen => khong
-- bao gio xoa tuong da co (da nang cap).
-- ===========================================================================================
ART.SLICE = 0.002           -- giay / frame cho cong viec nen ([FIX lag 9] 4 ms -> 2 ms)
ART.CAL_TTL = 7 * 86400     -- ket qua hieu chuan "khong doc noi dung" duoc nho bao lau (giay)
ART.VALVE = 0.85            -- loai hon 85% ung vien => khong tin phep kiem tra sau
local BIG_FILE = 300 * 1024 -- file lon hon: chi xet dau / cuoi (khong dem ngoac)
local MAX_FXBAD = 400

local function d_row(tname, id)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" or id == nil then return nil end
	local ok, r = pcall(d.element, d[tname], id)
	if ok then return r end
	return nil
end

local function id_list(s)
	local out = {}
	for w in string.gmatch(tostring(s or ""), "%-?%d+") do
		local n = tonumber(w)
		if n ~= nil then out[#out + 1] = n end
	end
	return out
end

local function fx_paths(id)
	return string.format("effect/effice_%d.json", id), string.format("effect/effice_%d.atlas", id)
end

local function atlas_of(spine_json)
	return (string.gsub(spine_json, "%.json$", ".atlas"))
end

local function read_text(path)
	local cc = G("cc")
	if type(cc) ~= "table" or cc.FileUtils == nil then return nil end
	local ok, s = pcall(function() return cc.FileUtils:getInstance():getStringFromFile(path) end)
	if ok and type(s) == "string" then return s end
	return nil
end

-- JSON spine hop le o muc "co the parse": bat dau '{', ket thuc '}', ngoac can doi, co "animations".
-- (file bi cat cut giua chung -> spine bao dung "Invalid skeleton JSON: <doan cuoi>")
function ART.json_sane(s)
	if type(s) ~= "string" or #s < 16 then return false, "file rong / qua ngan" end
	local head = string.match(string.sub(s, 1, 64), "^%s*(%S)")
	if head ~= "{" then return false, "khong bat dau bang {" end
	local tail = string.match(string.sub(s, -64), "(%S)%s*$")
	if tail ~= "}" then return false, "bi cat cut (khong ket thuc bang })" end
	if #s <= BIG_FILE then
		local t = string.gsub(s, "\\.", "")
		t = string.gsub(t, '"[^"]*"', '""')
		local _, o1 = string.gsub(t, "{", "")
		local _, c1 = string.gsub(t, "}", "")
		local _, o2 = string.gsub(t, "%[", "")
		local _, c2 = string.gsub(t, "%]", "")
		if o1 ~= c1 or o2 ~= c2 then return false, "ngoac khong can doi" end
	end
	if string.find(s, '"animations"', 1, true) == nil then return false, "khong co animations" end
	return true
end

-- Cac bang du lieu can thiet da nap xong chua (chua xong thi KHONG ket luan gi ve tuong)
local function tables_ready()
	local d = G("dms")
	if type(d) ~= "table" then return false end
	for _, t in ipairs({ "ship_mould", "ship_evo_mould", "skill_mould", "skill_influence" }) do
		if type(d[t]) ~= "table" or next(d[t]) == nil then return false end
	end
	return true
end

-- Cac file 1 tuong can: form dang dung + hieu ung ky nang (theo du lieu bang, khong can file)
function ART.need(tid)
	if not tables_ready() then return { fx = {}, ok = true, pending = true, why = "" } end
	R.art_need = R.art_need or {}
	local c = R.art_need[tid]
	if c ~= nil then return c end
	c = { fx = {}, ok = true, why = "" }
	R.art_need[tid] = c
	local function bad(why)
		if c.ok then c.ok = false; c.why = why end
	end
	local stage = math.max(1, math.floor(mnum(tid, "captain_name", 1)))
	local forms = ART.forms(tid)
	local f = forms[stage]
	c.stage = stage
	if f == nil or f <= 0 then bad("khong co form o cap " .. stage) else c.form = f end
	local col_h = scol("skill_mould", "health_affect", 9)
	local col_b = scol("skill_mould", "buff_affect", 10)
	local col_nx = scol("skill_influence", "next_skill_influence", 36)
	local cols_fx = {
		scol("skill_influence", "forepart_lighting_effect_id", 17),
		scol("skill_influence", "posterior_lighting_effect_id", 20),
		scol("skill_influence", "bear_lighting_effect_id", 26),
	}
	local seen, set = {}, {}
	local function influence(iid, depth)
		if iid == nil or iid <= 0 or seen[iid] or depth > 6 then return end
		seen[iid] = true
		if d_row("skill_influence", iid) == nil then bad("thieu skill_influence " .. iid); return end
		for k = 1, #cols_fx do
			local lst = id_list(d_str("skill_influence", iid, cols_fx[k]))
			for i = 1, #lst do
				if lst[i] > 0 then set[lst[i]] = true end
			end
		end
		local nx = tonumber(d_str("skill_influence", iid, col_nx))
		if nx ~= nil and nx > 0 then influence(math.floor(nx), depth + 1) end
	end
	for _, col in ipairs({ "skill_mould", "deadly_skill_mould" }) do
		local sid = math.floor(mnum(tid, col, 0))
		if sid > 0 then
			if d_row("skill_mould", sid) == nil then
				bad("thieu " .. col .. " " .. sid)
			else
				local a = id_list(d_str("skill_mould", sid, col_h))
				for i = 1, #a do influence(a[i], 0) end
				local b = id_list(d_str("skill_mould", sid, col_b))
				for i = 1, #b do influence(b[i], 0) end
			end
		end
	end
	for id in pairs(set) do c.fx[#c.fx + 1] = id end
	table.sort(c.fx)
	return c
end

local function learned_bad(path)
	if R.art_bad ~= nil and R.art_bad[path] then return true end
	if S ~= nil and type(S.fxbad) == "table" and S.fxbad[path] ~= nil then return true end
	return false
end

-- true = dung duoc; false,ly do = hong / thieu; nil = chua kiem tra xong (coi la dung)
function ART.file_ok(path, use_state)
	if learned_bad(path) then return false, "da gap loi luc choi" end
	if not use_state then return true end
	local st = R.art_file ~= nil and R.art_file[path] or nil
	if st == nil then return nil end
	if st.ex == false then return false, "thieu file" end
	if st.ex == nil then return nil end
	if st.sane == false and R.art_content == true then return false, st.why or "json hong" end
	return true
end

local function inspect_file(path)
	local ex = ART.exists(path)
	if ex ~= true then return { ex = ex, why = (ex == false) and "thieu file" or "khong ro" } end
	local st = { ex = true }
	-- [FIX lag 9] Hieu chuan da ket luan "KHONG doc noi dung" (json hop le < 90% tren may nay) thi viec doc
	-- ca file spine/hieu ung (co file > 200 KB) + json_sane() hoan toan vo ich nhung ton ~30-40 s CPU nen
	-- moi lan vao game (618 file trong log that) => chi kiem tra file co ton tai.
	if string.sub(path, -5) == ".json" and not R.art_nocontent then
		local s = read_text(path)
		if s == nil then
			st.why = "khong doc duoc noi dung"
		else
			st.size = #s
			local ok, why = ART.json_sane(s)
			st.sane = ok
			if not ok then st.why = why end
		end
	end
	return st
end

local function job()
	local j = R.art_job
	if j == nil then
		j = { list = {}, pos = 1, seen = {} }
		R.art_job = j
	end
	return j
end

local function enqueue(path)
	local j = job()
	if j.seen[path] then return end
	if R.art_file ~= nil and R.art_file[path] ~= nil then return end
	j.seen[path] = true
	j.list[#j.list + 1] = path
end

function ART.busy()
	local j = R.art_job
	return j ~= nil and j.pos <= #j.list
end

local function real_ships(max)
	local out = {}
	local e = ED()
	if e ~= nil and type(e.user_ship) == "table" then
		for sid, sh in pairs(e.user_ship) do
			if type(sh) == "table" and (S == nil or S.heroes[tostring(sid)] == nil) and tonumber(sh.ship_template_id) ~= nil then
				out[#out + 1] = sh
				if #out >= max then break end
			end
		end
	end
	return out
end

-- Hieu chuan: file cua cac tuong THAT (chac chan dung) phai duoc phep kiem tra do hop le
function ART.calibrate_finish()
	local j = R.art_job
	if j == nil or j.calib_fin then return end
	j.calib_fin = true
	local fx_t, fx_e, js_t, js_ok = 0, 0, 0, 0
	for path, kind in pairs(j.calib or {}) do
		local st = R.art_file ~= nil and R.art_file[path] or nil
		if st ~= nil then
			if kind == "fx" then
				fx_t = fx_t + 1
				if st.ex == true then fx_e = fx_e + 1 end
			end
			if st.ex == true and st.sane ~= nil then
				js_t = js_t + 1
				if st.sane == true then js_ok = js_ok + 1 end
			end
		end
	end
	R.art_fx_on = fx_t >= 2 and (fx_e / fx_t) >= 0.85
	R.art_content = js_t >= 3 and (js_ok / js_t) >= 0.9
	R.art_cal = { fx_t = fx_t, fx_e = fx_e, js_t = js_t, js_ok = js_ok }
	-- [FIX lag 9] nho ket luan (dung cho cac lan mo game sau) + tu day khong doc noi dung file nua
	R.art_nocontent = (R.art_content ~= true)
	if S ~= nil and not R.art_cal_cached then
		S.art_cal = { content = (R.art_content == true), t = os.time(), js = js_ok .. "/" .. js_t }
		mark()
	end
	log("kiem tra file tuong: hieu chuan tu tuong that | hieu ung " .. fx_e .. "/" .. fx_t .. " co file -> "
		.. (R.art_fx_on and "BAT" or "TAT") .. " | json hop le " .. js_ok .. "/" .. js_t .. " -> "
		.. (R.art_content and "BAT doc noi dung" or "TAT doc noi dung"))
	R.hero_ids, R.pool = nil, nil
end

function ART.calibrate_start()
	if R.art_calib_started then return end
	local m = ART.mode()
	if not m.on then return end
	R.art_calib_started = true
	-- [FIX lag 9] lan truoc da ket luan "khong doc noi dung" (con han) => bo qua doc noi dung ngay ca luc hieu chuan
	local old = (S ~= nil and type(S.art_cal) == "table") and S.art_cal or nil
	if old ~= nil and old.content == false and (tonumber(old.t) or 0) > 0
		and os.time() - (tonumber(old.t) or 0) >= 0 and os.time() - (tonumber(old.t) or 0) < ART.CAL_TTL then
		R.art_nocontent = true
		R.art_cal_cached = true
	end
	local j = job()
	local cal = {}
	local function add(path, kind)
		if cal[path] == nil then
			cal[path] = kind
			enqueue(path)
		end
	end
	local real = real_ships(14)
	for i = 1, #real do
		local sh = real[i]
		local tid = tonumber(sh.ship_template_id)
		local forms = ART.forms(tid)
		local stage = tonumber(string.match(tostring(sh.evolution_status or "1"), "^(%d+)")) or 1
		local f = forms[stage] or forms[1]
		if m.spine and f ~= nil and f > 0 then
			local _, sp = ART.paths(f)
			add(sp, "form")
			add(atlas_of(sp), "forma")
		end
		local need = ART.need(tid)
		for k = 1, #need.fx do
			local jp, ap = fx_paths(need.fx[k])
			add(jp, "fx")
			add(ap, "fxa")
		end
	end
	j.calib = cal
	j.calib_n = #j.list
	if j.calib_n == 0 then ART.calibrate_finish() end
end

-- Dua file cua cac ung vien vao hang doi kiem tra (moi tuong 1 lan)
function ART.plan(list)
	local m = ART.mode()
	if not m.on then return end
	ART.calibrate_start()
	R.art_planned = R.art_planned or {}
	for i = 1, #list do
		local tid = list[i]
		if not R.art_planned[tid] then
			local need = ART.need(tid)
			if not need.pending then R.art_planned[tid] = true end
			if need.ok and not need.pending then
				if m.spine and need.form ~= nil then
					local _, sp = ART.paths(need.form)
					enqueue(sp)
					enqueue(atlas_of(sp))
				end
				if ART.FX_STRICT then
					for k = 1, #need.fx do
						local jp, ap = fx_paths(need.fx[k])
						enqueue(jp)
						enqueue(ap)
					end
				end
			end
		end
	end
end

-- Chay hang doi kiem tra trong gioi han thoi gian (goi moi frame khi dang co viec)
function ART.pump(budget)
	local j = R.art_job
	if j == nil or j.pos > #j.list then return 0 end
	R.art_file = R.art_file or {}
	local t0, n = os.clock(), 0
	while j.pos <= #j.list and (n < 1 or os.clock() - t0 < (budget or ART.SLICE)) do
		local path = j.list[j.pos]
		j.pos = j.pos + 1
		local ok, st = pcall(inspect_file, path)
		if not ok then st = { ex = nil, why = "loi: " .. tostring(st) } end
		R.art_file[path] = st
		n = n + 1
		if j.calib_n ~= nil and not j.calib_fin and j.pos > j.calib_n then ART.calibrate_finish() end
	end
	if j.pos > #j.list then
		R.hero_ids, R.pool = nil, nil
		local nf, nb = 0, 0
		for _, st in pairs(R.art_file) do
			nf = nf + 1
			if st.ex == false or (st.sane == false and R.art_content == true) then nb = nb + 1 end
		end
		log("kiem tra file tuong xong:", nf, "file,", nb, "file thieu / hong")
	end
	return n
end

function ART.finish_now(max_sec)
	if not ART.busy() then return true end
	local t0 = os.clock()
	while ART.busy() and os.clock() - t0 < (max_sec or 2) do ART.pump(0.05) end
	return not ART.busy()
end

-- Tuong dung duoc khong? true / false,ly do / nil (khong kiem tra duoc)
function ART.deep(tid)
	tid = tonumber(tid)
	if tid == nil then return nil end
	local m = ART.mode()
	if not m.on then return nil end
	local need = ART.need(tid)
	if need.pending then return nil end
	if not need.ok then return false, need.why end
	if need.form ~= nil then
		local st = ART.form_state(need.form)
		if st.icon == false then return false, "thieu icon form " .. need.form end
		local _, sp = ART.paths(need.form)
		local ok, why = ART.file_ok(sp, m.spine)
		if ok == false then return false, "spine form " .. need.form .. ": " .. tostring(why) end
		if m.spine then
			local ok2 = ART.file_ok(atlas_of(sp), true)
			if ok2 == false then return false, "thieu atlas form " .. need.form end
		end
	end
	if ART.FX_STRICT then
		local use = R.art_fx_on == true
		for i = 1, #need.fx do
			local jp, ap = fx_paths(need.fx[i])
			local ok, why = ART.file_ok(jp, use)
			if ok == false then return false, "hieu ung " .. need.fx[i] .. ": " .. tostring(why) end
			if use then
				local ok2 = ART.file_ok(ap, true)
				if ok2 == false then return false, "thieu atlas hieu ung " .. need.fx[i] end
			end
		end
	end
	return true
end

-- Game bao file spine hong luc dang choi (display.lua -> OfflineMock.noteBadSpine -> day).
-- Nho lai (ca khi tat game) de khong cap / chon lai tuong dung file do.
function LS.on_bad_spine(json, atlas, why)
	if S == nil then return end
	local path = tostring(json or "")
	if path == "" or path == "nil" then return end
	local w = tostring(why or "")
	if string.find(w, "not enough memory", 1, true) or string.find(w, "out of memory", 1, true) then return end
	R.art_bad = R.art_bad or {}
	if R.art_bad[path] then return end
	R.art_bad[path] = true
	if type(S.fxbad) ~= "table" then S.fxbad = {} end
	if S.fxbad[path] == nil then
		local n, oldk, oldt = 0, nil, nil
		for k, t in pairs(S.fxbad) do
			n = n + 1
			if oldt == nil or (tonumber(t) or 0) < oldt then oldk, oldt = k, tonumber(t) or 0 end
		end
		if n >= MAX_FXBAD and oldk ~= nil then S.fxbad[oldk] = nil end
		S.fxbad[path] = os.time()
		mark()
		log("file spine / hieu ung hong luc choi:", path, "|", string.sub(string.gsub(w, "[\r\n]+.*$", ""), 1, 70),
			"-> tuong dung file nay se khong duoc cap / chon nua")
	end
	R.hero_ids, R.pool = nil, nil
end

-- Chay nen: khoi dong viec kiem tra sau khi vao game (de luc bam TAT CA TUONG da co ket qua)
function ART.tick(e)
	if S == nil or not R.ready then return end
	if not R.art_started then
		if ART.mode().pending then return end
		R.art_started = true
		-- [CAP NHAT GAME] Goi tai nguyen / phien ban doi => quen danh sach "file hong da hoc" (S.fxbad):
		-- ban cap nhat co the da sua file, giu lai se chan mai nhung tuong dung file do.
		local okp, sig = pcall(function()
			local ud = G("cc").UserDefault:getInstance()
			local app = G("app")
			return table.concat({ tostring(ud:getStringForKey("package", "")), tostring(ud:getStringForKey("package_md5", "")),
				tostring(type(app) == "table" and app.version or "") }, "|")
		end)
		if okp and type(sig) == "string" and sig ~= "||" then
			if S.art_sig ~= nil and S.art_sig ~= sig then
				local n = 0
				if type(S.fxbad) == "table" then for _ in pairs(S.fxbad) do n = n + 1 end end
				S.fxbad, R.art_bad = nil, nil
				R.hero_ids, R.pool = nil, nil
				log("game cap nhat (" .. tostring(S.art_sig) .. " -> " .. sig .. "): xoa", n, "file hong da hoc de kiem tra lai")
			end
			if S.art_sig ~= sig then S.art_sig = sig; mark() end
		end
		pcall(LS.hero_ids)
	end
end

function ART.check(tid)
	tid = tonumber(tid)
	if tid == nil then return nil end
	-- [FIX combo card reset] Tuong the combo (LR) duoc hero_safe coi la KHONG an toan
	-- -> ART.prune xoa khoi S.heroes + e.user_ship + save_state(true) => thoat game
	-- vao lai mat cap/pham/sao. Cho qua neu la the combo (co trong comb_mould).
	local safe = LS.hero_safe ~= nil and LS.hero_safe(tid)
	if not safe and not (LS.hero_combo_safe ~= nil and LS.hero_combo_safe(tid)) then return false end
	if ART.BAD[tid] then return false end
	local m = ART.mode()
	if not m.on then return nil end
	local forms = ART.forms(tid)
	local f = forms[1]
	if f == nil or f <= 0 then return false end
	local st = ART.form_state(f)
	if st.icon == false then return false end
	if m.spine and st.spine == false then return false end
	return true
end

function ART.filter(list)
	local m = ART.mode()
	R.art_pending = m.pending == true
	local keep, skip = {}, {}
	for i = 1, #list do
		local v = ART.check(list[i])
		if v == false then skip[#skip + 1] = list[i] else keep[#keep + 1] = list[i] end
	end
	local dyn = 0
	for i = 1, #skip do if not ART.BAD[skip[i]] then dyn = dyn + 1 end end
	if #list > 0 and dyn / #list > ART.MAX_REJECT then

		R.art_mode = { on = false, spine = false, reason = "bo loc dinh loai " .. dyn .. "/" .. #list .. " tuong (qua nhieu) -> TAT", pending = false }
		keep, skip = {}, {}
		for i = 1, #list do
			if ART.BAD[list[i]] then skip[#skip + 1] = list[i] else keep[#keep + 1] = list[i] end
		end
	end
	-- [FIX tuong chua phat hanh] kiem tra sau: form dang dung + hieu ung ky nang + file da gay loi
	R.art_why = nil
	R.art_deep_note = nil
	if (R.art_mode or m).on and #keep > 0 then
		local okp, errp = pcall(ART.plan, keep)
		if not okp then log("loi len ke hoach kiem tra file tuong:", tostring(errp)) end
		local kept, dropped, why = {}, {}, {}
		for i = 1, #keep do
			local okd, v, w = pcall(ART.deep, keep[i])
			if okd and v == false then
				dropped[#dropped + 1] = keep[i]
				why[keep[i]] = w
			else
				kept[#kept + 1] = keep[i]
			end
		end
		if #keep >= 20 and #dropped > ART.VALVE * #keep then
			R.art_deep_note = "kiem tra sau loai " .. #dropped .. "/" .. #keep .. " tuong (qua nhieu) -> bo qua"
			dropped = {}
			why = {}
			kept = keep
		end
		if #dropped > 0 then
			for i = 1, #dropped do skip[#skip + 1] = dropped[i] end
			R.art_why = why
		end
		keep = kept
	end
	if ART.busy() or ((R.art_mode or m).on and not tables_ready()) then R.art_pending = true end
	R.art_skip = skip
	return keep
end

function ART.prune()
	if R.art_pruned or S == nil or not R.ready then return 0 end
	local m = ART.mode()
	if m.pending then return 0 end
	R.art_pruned = true
	local e = ED()
	if e == nil or type(e.user_ship) ~= "table" then return 0 end
	local gone = {}
	for sid, rec in pairs(S.heroes) do
		if type(rec) == "table" and ART.check(rec.tid) == false then
			-- [FIX combo card reset] Khong bao gio xoa tuong the combo: mat hinh
			-- chi la thieu asset, xoa la mat luon cap/pham/sao da nang.
			local keep = LS.hero_combo_safe ~= nil and LS.hero_combo_safe(rec.tid)
			if not keep then gone[#gone + 1] = sid end
		end
	end
	if #gone == 0 then return 0 end
	table.sort(gone, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	local set = {}
	for i = 1, #gone do set[gone[i]] = true end

	local f = read_formation(e)
	local changed = false
	for i = 1, 6 do
		if set[tostring(f[i])] then f[i] = "0"; changed = true end
	end
	if changed then write_formation(e, f) end
	if type(S.formation) == "table" then
		for i = 1, 6 do
			if S.formation[i] ~= nil and set[tostring(S.formation[i])] then S.formation[i] = "0" end
		end
	end
	for i = 1, #gone do
		local sid = gone[i]
		e.user_ship[sid] = nil
		S.heroes[sid] = nil
		if type(S.eq) == "table" and type(S.eq.hard) == "table" then S.eq.hard[sid] = nil end
		if type(S.mega) == "table" then S.mega[sid] = nil end
		if type(S.mods) == "table" then S.mods[sid] = nil end
	end
	local order = {}
	for i = 1, #S.order do
		if not set[tostring(S.order[i])] then order[#order + 1] = S.order[i] end
	end
	S.order = order
	e.user_ship_number = count_ships(e)
	R.owned = owned_set(e)
	R.hero_ids, R.pool = nil, nil
	R.art_gone = (R.art_gone or 0) + #gone
	mark()
	LS.save_state(true)
	log("loc hinh tuong: da go", #gone, "tuong LS khong co hinh:", table.concat(gone, ","))
	return #gone
end

function ART.dump_line()
	local m = R.art_mode
	if m == nil then m = ART.mode() end
	local sk = R.art_skip or {}
	local ids = {}
	for i = 1, math.min(#sk, 30) do ids[#ids + 1] = tostring(sk[i]) end
	local line = "[LS hinh tuong] loc=" .. (m.on and "BAT" or "TAT") .. " (" .. tostring(m.reason) .. ") | bo qua " .. #sk .. " mau"
		.. (#ids > 0 and (": " .. table.concat(ids, ",") .. (#sk > 30 and ",..." or "")) or "")
		.. " | da go " .. tostring(R.art_gone or 0) .. " tuong LS khong hinh"
	-- kiem tra sau (form dang dung + hieu ung ky nang)
	local cal = R.art_cal
	local j = R.art_job
	local nbad = 0
	if S ~= nil and type(S.fxbad) == "table" then for _ in pairs(S.fxbad) do nbad = nbad + 1 end end
	line = line .. "\n[LS kiem tra file tuong] " .. (cal ~= nil
		and ("hieu chuan: hieu ung " .. cal.fx_e .. "/" .. cal.fx_t .. " co file, json hop le " .. cal.js_ok .. "/" .. cal.js_t)
		or "chua hieu chuan")
		.. " | kiem tra hieu ung=" .. tostring(R.art_fx_on) .. " doc noi dung=" .. tostring(R.art_content)
		.. " | hang doi " .. (j ~= nil and tostring(math.min(j.pos - 1, #j.list)) .. "/" .. #j.list or "0/0")
		.. " | file hong da hoc " .. nbad
	if R.art_deep_note ~= nil then line = line .. " | " .. R.art_deep_note end
	if type(R.art_why) == "table" then
		local parts, n = {}, 0
		for tid, why in pairs(R.art_why) do
			n = n + 1
			if #parts < 12 then parts[#parts + 1] = tostring(tid) .. "=" .. tostring(why) end
		end
		if n > 0 then
			table.sort(parts)
			line = line .. "\n[LS tuong bi loai boi kiem tra sau] " .. n .. " mau: " .. table.concat(parts, "; ") .. (n > 12 and "; ..." or "")
		end
	end
	return line
end

-- Mau co DU hinh (khong goi hero_safe de tranh vong lap). true / false / nil (chua kiem tra duoc)
function ART.complete(tid)
	tid = tonumber(tid)
	if tid == nil then return nil end
	tid = math.floor(tid)
	if ART.BAD[tid] then return false end
	local m = ART.mode()
	if not m.on then return nil end
	local forms = ART.forms(tid)
	local f = forms[1]
	if f == nil or f <= 0 then return false end
	local st = ART.form_state(f)
	if st.icon ~= true or st.spine ~= true then return false end
	local ok = ART.deep(tid)
	if ok == nil then return nil end
	return ok == true
end

-- [AUTO-UNLOCK] Tuong co DU file thuc te (icon + spine json + atlas form cap 1, ky nang co trong bang) => coi la da phat hanh,
-- ke ca khi ART.complete tra nil (bo loc chua hieu chuan xong / dang cho) hay false vi chi tiet phu.
function ART.present(tid)
	tid = tonumber(tid)
	if tid == nil then return false end
	tid = math.floor(tid)
	if ART.BAD[tid] then return false end
	local forms = ART.forms(tid)
	local f = forms[1]
	if f == nil or f <= 0 then return false end
	local st = ART.form_state(f)
	if st.icon ~= true or st.spine ~= true then return false end
	local _, sp = ART.paths(f)
	if learned_bad(sp) then return false end
	if ART.exists(atlas_of(sp)) == false then return false end
	local need = ART.need(tid)
	if need.pending then return false end
	if need.ok == false then return false end
	return true
end

-- Ly do 1 mau tuong khong duoc cap (de ghi log, gui lai de chan doan)
function ART.why_not(tid)
	if ART.BAD[tid] then return "ART.BAD (danh sach cam co dinh)" end
	if LS.ban_hit ~= nil and LS.ban_hit(tid) then return "offline_lr_ban.txt" end
	local forms = ART.forms(tid)
	local f = forms[1]
	if f == nil or f <= 0 then return "khong co form cap 1 (fitSkillTwo/ship_evo_mould)" end
	local st = ART.form_state(f)
	if st.icon ~= true then return "thieu icon form " .. f end
	if st.spine ~= true then return "thieu spine form " .. f end
	local _, sp = ART.paths(f)
	if learned_bad(sp) then return "file spine hong da hoc luc choi" end
	if ART.exists(atlas_of(sp)) == false then return "thieu atlas form " .. f end
	local need = ART.need(tid)
	if need.pending then return "bang chua nap xong" end
	if need.ok == false then return "bang: " .. tostring(need.why) end
	if LS.hero_is_lr(tid) and not LS.lr_released(tid) then return "LR chua phat hanh (lr_released=false)" end
	return "khong ro (dang cho ART.deep / bo loc)"
end

LS.art_filter = ART.filter
LS.art_ok = function(tid) return ART.check(tid) ~= false end
LS._art = ART

end
init_art()
end

do
local function init_wb()

local SB, WB = {}, {}
local FIGHT_HDR = "100\r\nbattle_field_init\r\n0\r\n"
local MAX_BOSS = 100
local SIM_SEC = 45

-- [FIX Cell Game] Che do Cell Game (mac dinh BAT, nut GM "CELL GAME"):
--   * boss the gioi luon la boss toi da (MAX_BOSS), mau luon day, BAT TU (khong bao gio chet trong tran);
--   * moi tran toi da CELL_ROUNDS (5) round, bat ke "vo han round";
--   * sau moi tran, sat thuong cua tran do GHI DE len bang chi so cu (khong cong don).
local CELL_ROUNDS = 5
-- [Cell HP x100] Chi tang mau boss 100 khi CELL GAME bat; khong doi cong/thu hay phe minh.
local CELL_HP_MULT = 100
-- [NHAP SO] He so mau boss Cell nhap tay tu bang GM (luu S.cfg.wb_cell_hp, mac dinh CELL_HP_MULT).
local function cell_hp_mult()
	local v = (S ~= nil and type(S.cfg) == "table") and tonumber(S.cfg.wb_cell_hp) or nil
	if v == nil or v <= 0 then return CELL_HP_MULT end
	if v > 1000000 then return 1000000 end
	return v
end

local function cell_on()
	return R.enabled == true and S ~= nil and type(S.cfg) == "table" and S.cfg.wb_cell ~= false
end

-- Cell Game keeps its 5-round mode. Other fights use BattleRules.
function LS.round_lock(fm)
    if R.cell_lock ~= nil then return R.cell_lock end
    if type(fm) == "table" and tonumber(rawget(fm, "fightType")) == 218 and cell_on() then
        return CELL_ROUNDS
    end
    return nil
end

function LS.cell_state()
	return cell_on(), CELL_ROUNDS, MAX_BOSS
end

function LS.get_cell_hp() return cell_hp_mult() end

function LS.gm_set_cell_hp(n)
	if S == nil or type(S.cfg) ~= "table" then return nil end
	n = tonumber(n) or CELL_HP_MULT
	n = math.floor(n * 100 + 0.5) / 100
	if n < 1 then n = 1 end
	if n > 1000000 then n = 1000000 end
	S.cfg.wb_cell_hp = n
	mark()
	LS.save_state(true)
	log("GM Cell HP x" .. tostring(n))
	return n
end

function LS.gm_toggle_cell()
	if S == nil or type(S.cfg) ~= "table" then return nil end
	S.cfg.wb_cell = not cell_on()
	mark()
	LS.save_state(true)
	log("Cell Game:", S.cfg.wb_cell and "BAT" or "TAT")
	return S.cfg.wb_cell
end

-- cac hook cho engine (FightUtil / BattleObject): khoa round + boss bat tu
rawset(_G, "ZZ_ROUND_LOCK", function(fm)
	local ok, v = pcall(LS.round_lock, fm)
	if ok then return v end
	return nil
end)
-- Scope the deliberate Cell Game boss lock to that fight only.
function LS.boss_immortal(object)
    if R.cell_imm ~= true then return false end
    local fm = type(object) == "table" and object.fightObject and object.fightObject.fightModule or nil
    if fm == nil then local e = ED(); fm = e and e._fightModule end
    return type(fm) == "table" and tonumber(fm.fightType) == 218
end
rawset(_G, "ZZ_BOSS_IMMORTAL", LS.boss_immortal)

local function trim_crlf(s)
	s = tostring(s or "")
	while string.sub(s, -2) == "\r\n" do s = string.sub(s, 1, -3) end
	return s
end

function SB.classes()
	local app = G("app")
	if type(app) == "table" and type(app.load) == "function" then
		pcall(app.load, "client.battle.fight.FightEnum")
		pcall(app.load, "client.battle.report.BattleReport")
	end
	local FM = G("FightModule")
	if type(FM) ~= "table" or FM.new == nil then return nil end
	return FM
end

function SB.wire(chunks)
	local out, nr = {}, 0
	local i = 1
	while i <= #chunks do
		local r = chunks[i].round
		local j = i
		while j + 1 <= #chunks and chunks[j + 1].round == r do j = j + 1 end
		local parts, ok = {}, true
		for k = i, j do
			local hdr, rest = string.match(chunks[k].text, "^(%d+)\r\n(.*)$")
			if hdr == nil or tonumber(hdr) ~= tonumber(r) or string.sub(rest, -1) ~= "1" or string.sub(rest, -2, -2) ~= " " then
				ok = false
				break
			end
			if k < j then rest = string.sub(rest, 1, -2) .. "0" end
			parts[#parts + 1] = trim_crlf(rest)
		end
		if not ok then return nil, "nua round khong dung dinh dang (round " .. tostring(r) .. ")" end
		nr = nr + 1
		out[#out + 1] = tostring(r) .. "\r\n" .. table.concat(parts, "\r\n")
		i = j + 1
	end
	return table.concat(out, "\r\n"), nr
end

function SB.run(spec)
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then return nil, "chua co the gioi" end
	local FM = SB.classes()
	if FM == nil then return nil, "khong nap duoc FightModule" end
	local snap = { fm = e._fightModule, ad = e.attackData, bc = e.user_info.battleCache,
		sn = e._scene_npc_id, cs = e._current_scene_id, nd = e._npc_difficulty_index }
	local out
	-- [FIX Cell Game] tran Cell Game: khoa 5 round + boss bat tu trong luc mo phong (go ngay sau xpcall)
	if spec.cell == true then R.cell_lock, R.cell_imm = CELL_ROUNDS, true end
	local ok, err = xpcall(function()
		e._scene_npc_id = spec.npc
		e._current_scene_id = tostring(spec.scene)
		e._npc_difficulty_index = "1"
		local fm = FM:new()
		e._fightModule = fm
		e.attackData = { roundCount = fm.totalRound, roundData = {} }
		local rb = {}
		fm[spec.init](fm, tostring(spec.npc), "1", spec.ftype, rb)
		local init = table.concat(rb, "")
		if string.sub(init, 1, #FIGHT_HDR) ~= FIGHT_HDR then error("tieu de battle_field_init la: " .. string.sub(init, 1, 40)) end
		init = trim_crlf(string.sub(init, #FIGHT_HDR + 1))
		fm:initFightOrder(e.user_info, {})
		-- tong mau phe boss luc vao tran (de tinh sat thuong Cell Game = mau mat di)
		local hp0 = 0
		for _, bo in pairs(fm.byAttackObjects or {}) do
			if bo ~= nil then hp0 = hp0 + (tonumber(bo.healthPoint) or 0) end
		end
		local chunks, guard, cut = {}, 0, false
		local t0 = os.clock()
		local cap = (LS._inf ~= nil and LS._inf.cap ~= nil) and LS._inf.cap() or 200
		if R.cell_lock ~= nil then cap = R.cell_lock end
		local limit = math.max(cap, tonumber(fm.totalRound) or 0) * 4 + 100
		if R.cell_lock ~= nil then limit = 1200 end
		while fm.hasNextRound == true do
			guard = guard + 1
			if guard > limit or os.clock() - t0 > SIM_SEC then cut = true; break end
			local rc = fm.roundCount
			local buf = {}
			fm:rountdFight(buf)
			chunks[#chunks + 1] = { round = rc, text = table.concat(buf, "") }
			if rc ~= fm.roundCount then fm:resetAllRoleSkillStatus() end
		end
		pcall(fm.checkDefenceResult, fm)
		local body, nr = SB.wire(chunks)
		if body == nil then error(nr) end
		local left = 0
		for _, bo in pairs(fm.byAttackObjects or {}) do
			if bo ~= nil and bo.isDead ~= true then left = left + (tonumber(bo.healthPoint) or 0) end
		end
		local win = (cut and 0) or (tonumber(fm.fightResult) or 0)
		out = { init = init, body = body, nr = nr, win = win, total = tonumber(fm.totalRound) or nr,
			left = left, rounds = tonumber(fm.roundCount) or nr, cut = cut, hp0 = hp0 }
	end, traceback)
	R.cell_lock, R.cell_imm = nil, nil
	e._fightModule, e.attackData, e.user_info.battleCache = snap.fm, snap.ad, snap.bc
	e._scene_npc_id, e._current_scene_id, e._npc_difficulty_index = snap.sn, snap.cs, snap.nd
	if not ok then return nil, err end
	return out
end

function SB.block39(r)
	return "39\r\n" .. tostring(r.win) .. "\r\n" .. tostring(r.total) .. "\r\n" .. tostring(r.nr) .. "\r\n" .. r.body
end

LS._sb = SB

local function scol(tbl, name, dflt)
	local sch = G(tbl)
	if type(sch) == "table" and tonumber(sch[name]) ~= nil then return sch[name] end
	return dflt
end

local function d_int(tname, id, col)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" then return 0 end
	local ok, v = pcall(d.int, d[tname], id, col)
	if ok and tonumber(v) ~= nil then return tonumber(v) end
	return 0
end

local function floor_n(v) return math.floor((tonumber(v) or 0) + 0.5) end

function WB.st()
	if type(S.wb) ~= "table" then S.wb = {} end
	local w = S.wb
	local b = math.floor(tn(w.boss, 1))
	if b < 1 then b = 1 end
	if b > MAX_BOSS then b = MAX_BOSS end
	w.boss = b
	w.kills = math.max(0, math.floor(tn(w.kills, 0)))
	w.atk = math.max(0, math.floor(tn(w.atk, 0)))
	w.total = math.max(0, tn(w.total, 0))
	w.best = math.max(0, tn(w.best, 0))
	if w.left ~= nil and tonumber(w.left) == nil then w.left = nil end
	return w
end

function WB.boss_data(id)
	local scene = d_int("world_boss", id, 3)
	local npc_id = d_int("pve_scene", scene, scol("pve_scene", "npcs", 13))
	local f1 = d_int("npc", npc_id, scol("npc", "environment_formation1", 9))
	local seat1 = scol("environment_formation", "seat_one", 8)
	local pw = scol("environment_ship", "power", 12)
	local hp = 0
	for i = 0, 5 do
		local sid = d_int("environment_formation", f1, seat1 + i)
		if sid ~= 0 then hp = d_int("environment_ship", sid, pw); break end
	end
	-- WB.cur dung HP nay cho maxHp/leftHp; initWordBossFight cung doc leftHp,
	-- nen mau tren giao dien, mau trong tran va mau toi da khop nhau (khong nhan chong).
	if cell_on() and tonumber(id) == MAX_BOSS and hp > 0 then
		hp = math.floor(hp * cell_hp_mult())
	end
	return scene, npc_id, hp
end

local function wb_fw_open()
	local fw = G("fwin")
	if type(fw) ~= "table" or type(fw.find) ~= "function" then return false end
	local ok, v = pcall(fw.find, fw, "WorldBossWindowClass")
	return ok and v ~= nil
end

-- id boss dang hien thi / dang danh (Cell Game: luon la boss toi da)
function WB.bid(w)
	if cell_on() then return MAX_BOSS end
	return w.boss
end

function WB.cur()
	local w = WB.st()
	if cell_on() then
		-- Cell Game: boss toi da, bat tu => mau luon day (khong luu mau con lai)
		local scene, npc_id, max = WB.boss_data(MAX_BOSS)
		if max <= 0 then max = 1 end
		return w, scene, npc_id, max, floor_n(max)
	end
	local scene, npc_id, max = WB.boss_data(w.boss)
	if max <= 0 then max = 1 end
	if w.left ~= nil and w.left <= 0 then
		if w.boss < MAX_BOSS then w.boss = w.boss + 1 end
		w.left = nil
		scene, npc_id, max = WB.boss_data(w.boss)
		if max <= 0 then max = 1 end
		mark()
	end
	if w.left == nil or w.left > max then w.left = max end
	w.left = floor_n(w.left)
	return w, scene, npc_id, max, w.left
end

local function my_name(e)
	local n = e ~= nil and type(e.user_info) == "table" and tostring(e.user_info.user_name or "") or ""
	if n == "" then n = "Player" end
	return n
end

local function my_uid(e)
	return (e ~= nil and type(e.user_info) == "table" and tostring(e.user_info.user_id or "1")) or "1"
end

function WB.union_name()
	if type(S.union) == "table" and tostring(S.union.name or "") ~= "" then return tostring(S.union.name) end
	return nil
end

function WB.j_boss(w, max, left)
	return jenc({ bossId = WB.bid(w), leftHp = floor_n(left), maxHp = floor_n(max),
		surprisedRewardUserInfo = {}, lastAttackUser = {} })
end

function WB.j_my(e)
	local w = WB.st()
	local ids, info = {}, { ["1"] = w.atk, ["2"] = floor_n(w.total), ["3"] = w.kills }
	local n = 0
	local d = G("dms")
	if type(d) == "table" and type(d["world_boss_daily_reward"]) == "table" then
		for k in pairs(d["world_boss_daily_reward"]) do
			if type(k) == "number" and k > n then n = k end
		end

		for k = 1, n do
			local c = d_int("world_boss_daily_reward", k, 2)
			if c > 0 and info[tostring(c)] == nil then info[tostring(c)] = 0 end
		end
	end
	if n < 9 then n = 9 end
	for k = 1, n do ids[#ids + 1] = k end
	return jenc({ nextAttackDate = 0, refAttackDateTime = 0, allTask = { taskInfo = info, drawTaskId = ids } })
end

function WB.j_open(e)
	local t = (os.time() + tn(e.time_add_or_sub, 0)) * 1000 + 6 * 3600 * 1000
	return jenc({ status = 1, time = floor_n(t) })
end

function WB.b_personal(e, no_entries)
	local w = WB.st()
	local rank, my = {}, nil
	if w.total > 0 then
		my = { nickName = my_name(e), score = floor_n(w.total), userId = my_uid(e) }
		if not no_entries then rank[1] = my end
	end
	local t = { rankInfo = rank, myRank = (my ~= nil) and 1 or 1000 }
	if my ~= nil then t.myRankInfo = my end
	return "12657\r\n" .. tostring(#rank) .. "\r\n" .. jenc(t)
end

function WB.b_union(e)
	local w = WB.st()
	local list = {}
	local un = WB.union_name()
	if un ~= nil and w.total > 0 then
		list[1] = { unionName = un, score = floor_n(w.total), unionId = tostring(tn(S.union.id, 1)) }
	end
	return "12660\r\n" .. tostring(#list) .. "\r\n" .. jenc(list)
end

function WB.h_init(p, seq)
	local e = ED()
	local w, _, _, max, left = WB.cur()
	local blocks = {
		"12656\r\n" .. WB.j_my(e),
		"12658\r\n" .. WB.j_boss(w, max, left),
		WB.b_personal(e),
		WB.b_union(e),
	}

	if not wb_fw_open() or type(e.world_boss_open_info) ~= "table" then
		blocks[#blocks + 1] = "12659\r\n" .. WB.j_open(e)
	end
	stat_inc("wb_init")
	return reply(seq, "pokemon_world_boss_init", blocks)
end

function WB.h_attack(p, seq)
	local name = "world_boss_attack"
	local e = ED()
	local cell = cell_on()
	local w, scene, npc_id, max, left = WB.cur()
	if left <= 0 then return err_reply(seq, name, "LS_boss_da_chet") end

	e.world_boss_info = { bossId = WB.bid(w), leftHp = floor_n(left), maxHp = floor_n(max),
		surprisedRewardUserInfo = {}, lastAttackUser = {} }
	local res, err = SB.run({ ftype = 218, npc = npc_id, scene = scene, init = "initWordBossFight", cell = cell })
	if res == nil then
		R.wb_errs = (R.wb_errs or 0) + 1
		log("boss the gioi: loi tinh tran:", tostring(err))
		stat_inc("wb_fail")
		return err_reply(seq, name, "LS_loi_tinh_tran")
	end

	local left2, dmg
	if cell then
		-- [FIX Cell Game] boss bat tu: sat thuong = tong mau boss mat di trong tran (toi da 5 round),
		-- mau boss sau tran van DAY; bang chi so bi tran moi nhat GHI DE (khong cong don).
		dmg = floor_n((tonumber(res.hp0) or left) - (tonumber(res.left) or 0))
		if dmg < 0 then dmg = 0 end
		left2 = floor_n(max)
		w.atk = w.atk + 1
		w.total = dmg
		if dmg > w.best then w.best = dmg end
		w.left = nil
	else
		left2 = floor_n(res.left)
		if res.left > 0 and left2 < 1 then left2 = 1 end
		if res.win == 1 and not res.cut then left2 = 0 end
		if left2 < 0 then left2 = 0 end
		if left2 > left then left2 = left end
		dmg = left - left2
		w.atk = w.atk + 1
		w.total = w.total + dmg
		if dmg > w.best then w.best = dmg end
		if left2 <= 0 then
			w.kills = w.kills + 1
			left2 = 0
		end
		w.left = left2
	end
	R.wb_last = { boss = WB.bid(w), dmg = dmg, rounds = res.rounds, nr = res.nr, win = res.win, cut = res.cut, cell = cell }
	mark()
	LS.save_state(true)
	local blocks = {
		res.init,
		SB.block39(res),
		"12658\r\n" .. WB.j_boss(w, max, left2),
		"12656\r\n" .. WB.j_my(e),
		"12667\r\n" .. jenc({ damage = floor_n(dmg) }),
	}
	stat_inc("wb_attack")
	log("boss the gioi:", cell and "[CELL GAME bat tu]" or "", "boss", WB.bid(w), "danh", res.rounds, "round, sat thuong", fnum(dmg),
		"con", fnum(left2), "/", fnum(max), res.cut and "(CAT TRAN: qua thoi gian)" or "")
	return reply(seq, name, blocks)
end

function WB.h_ref_cd(p, seq)
	stat_inc("wb_refcd")
	return reply(seq, "world_boss_ref_cd", { "12656\r\n" .. WB.j_my(ED()) })
end

function WB.h_order(p, seq)
	local e = ED()
	local t = tonumber(p[1]) or 1
	local start = tonumber(p[2]) or 1
	local block
	if t == 2 then
		block = (start > 1) and "12660\r\n0\r\n[]" or WB.b_union(e)
	else
		block = WB.b_personal(e, start > 1)
	end
	stat_inc("wb_order")
	return reply(seq, "world_boss_get_order", { block })
end

function WB.h_draw(p, seq)
	stat_inc("wb_draw")
	return reply(seq, "world_boss_draw_task_reward", { "12656\r\n" .. WB.j_my(ED()) })
end

function WB.dump_line()
	local w = WB.st()
	local _, _, _, max, left = WB.cur()
	local l = R.wb_last
	return "[LS boss the gioi] " .. (cell_on() and "CELL GAME(HP x" .. tostring(cell_hp_mult()) .. ", bat tu, " .. CELL_ROUNDS .. " round) " or "") .. "boss " .. WB.bid(w) .. "/" .. MAX_BOSS .. " mau " .. fnum(left) .. "/" .. fnum(max)
		.. " ha " .. w.kills .. " luot " .. w.atk .. " tong sat thuong " .. fnum(w.total) .. " cao nhat " .. fnum(w.best)
		.. " loi " .. tostring(R.wb_errs or 0)
		.. (l ~= nil and (" | tran cuoi: " .. l.rounds .. " round, sat thuong " .. fnum(l.dmg) .. (l.cut and " (cat)" or "")) or "")
end

function WB.reset()
	S.wb = nil
	mark()
end

LS._wb = WB

end
init_wb()
end

do
local function init_ud()

local UD = {}
local SCENE = 155
local COPY_CFG = 3

local function scol(tbl, name, dflt)
	local sch = G(tbl)
	if type(sch) == "table" and tonumber(sch[name]) ~= nil then return sch[name] end
	return dflt
end

local function d_raw(fn, tname, id, col)
	local d = G("dms")
	if type(d) ~= "table" or type(d[tname]) ~= "table" or type(d[fn]) ~= "function" or col == nil then return nil end
	local ok, v = pcall(d[fn], d[tname], id, col)
	if ok then return v end
	return nil
end

local function d_int(tname, id, col)
	local v = tonumber(d_raw("int", tname, id, col))
	if v == nil then return 0 end
	return v
end

local function d_str(tname, id, col)
	local v = d_raw("string", tname, id, col)
	if v == nil then return "" end
	return tostring(v)
end

local function floor_n(v) return math.floor((tonumber(v) or 0) + 0.5) end

local function att_unlimited()
	if type(LS.inf_state) ~= "function" then return true end
	local okx, _, a = pcall(LS.inf_state)
	if okx then return a ~= false end
	return true
end

local function tok(s, dflt)
	s = tostring(s == nil and "" or s)
	s = (string.gsub(s, "%s", "&nbsp;"))
	s = (string.gsub(s, "%c", ""))
	if s == "" then return dflt end
	return s
end

function UD.ids()
	local s = d_str("pve_scene", SCENE, scol("pve_scene", "npcs", 13))
	local ids = {}
	for w in string.gmatch(s, "[^,]+") do
		local v = tonumber(w)
		if v ~= nil and v > 0 then ids[#ids + 1] = math.floor(v) end
	end
	if #ids == 0 then

		for i = 1201, 1257 do ids[#ids + 1] = i end
		for i = 1509, 1551 do ids[#ids + 1] = i end
	end
	return ids
end

function UD.total(ids)
	ids = ids or UD.ids()
	local cap = d_int("copy_config", COPY_CFG, scol("copy_config", "param", nil))
	if cap <= 0 then cap = 100 end
	local col = scol("npc", "first_reward", nil)
	local n = 0
	if col ~= nil then
		for i = 1, #ids do
			if d_int("npc", ids[i], col) > 0 then n = i else break end
		end
	end
	if n == 0 then n = #ids end

	return math.max(1, math.min(n, cap))
end

function UD.base_hp(id)
	local f1 = d_int("npc", id, scol("npc", "environment_formation1", nil))
	local seat1 = scol("environment_formation", "seat_one", nil)
	local pw = scol("environment_ship", "power", nil)
	if seat1 == nil or pw == nil then return 0 end
	for k = 0, 5 do
		local sid = d_int("environment_formation", f1, seat1 + k)
		if sid ~= 0 then return d_int("environment_ship", sid, pw) end
	end
	return 0
end

function UD.maxhp(u, i, ids)
	local id = ids[i]
	if id == nil then return 0 end
	local hp = UD.base_hp(id)
	if hp <= 0 then hp = tn(u.mx[tostring(i)], 0) end
	if hp > 0 then
		local pct = tn(S.cfg.ud_hp, 100)
		if pct > 0 and pct ~= 100 then hp = math.max(1, floor_n(hp * pct / 100)) end
		-- [BOSS GUILD BOT] mau toi da cung tang theo boss (cung he so voi chi so tuong bot)
		if type(LS.ub_factor) == "function" then hp = math.max(1, floor_n(hp * LS.ub_factor(i))) end
	end
	return floor_n(hp)
end

function UD.st(total)
	if type(S.ud) ~= "table" then S.ud = {} end
	local u = S.ud
	total = total or UD.total()
	u.cleared = math.max(0, math.min(total, math.floor(tn(u.cleared, 0))))
	if u.left ~= nil and tonumber(u.left) == nil then u.left = nil end
	if type(u.dmg) ~= "table" then u.dmg = {} end
	if type(u.kt) ~= "table" then u.kt = {} end
	if type(u.mx) ~= "table" then u.mx = {} end
	if type(u.seed) ~= "table" then u.seed = {} end
	u.atk = math.max(0, math.floor(tn(u.atk, 0)))
	u.used = math.max(0, math.floor(tn(u.used, 0)))
	local today = os.date("%Y%m%d")
	if u.day ~= today then u.day = today; u.used = 0 end
	return u
end

function UD.max_att()
	local v = d_int("union_config", 21, scol("union_config", "param", nil))
	if v <= 0 then v = 3 end
	return math.floor(v)
end

function UD.att_count(u)
	if att_unlimited() then return 0 end
	return math.min(u.used, UD.max_att())
end

function UD.unlocked(u, total) return math.min(total, u.cleared + 1) end

function UD.info_of(u, i, ids)
	local mx = UD.maxhp(u, i, ids)
	if i <= u.cleared then
		return { id = ids[i], status = 1, cur = 0, max = mx, kills = 1 }
	end
	local cur = mx
	if i == u.cleared + 1 and u.left ~= nil and mx > 0 then
		cur = math.max(1, math.min(mx, floor_n(u.left)))
	end
	return { id = ids[i], status = 0, cur = cur, max = mx, kills = 0 }
end

function UD.b_list(u, ids, total)
	local n = UD.unlocked(u, total)
	local t = { "14659", tostring(n) }
	for i = 1, n do
		local x = UD.info_of(u, i, ids)
		t[#t + 1] = tostring(i)
		t[#t + 1] = fint(x.id)
		t[#t + 1] = tostring(x.status)
		t[#t + 1] = fint(x.cur)
		t[#t + 1] = fint(x.max)
		t[#t + 1] = "1"
		t[#t + 1] = tostring(x.kills)
	end
	return table.concat(t, "\r\n")
end

function UD.reward_state(u, ids, total)
	local n = UD.unlocked(u, total)
	local t = {}
	for i = 1, n do t[i] = fint(ids[i]) .. ":" .. ((i <= u.cleared) and "3" or "1") end
	return table.concat(t, "|")
end

local function ukeep(uu, k, d)
	local v = uu[k]
	if v == nil or tonumber(v) == nil then return d end
	return fint(tonumber(v))
end

function UD.b_user(e, u, ids, total)
	local uu = (type(e.union) == "table" and type(e.union.user_union_info) == "table") and e.union.user_union_info or {}
	local function keep(k, d) return ukeep(uu, k, d) end
	local f = {
		"1005",
		keep("union_post", "3"),
		keep("rest_contribution", "0"),
		keep("build_count", "0"),
		keep("build_reward", "0"),
		fint(UD.att_count(u)),
		keep("duplicate_reward", "0"),
		(uu.union_fight_reward == true) and "1" or "0",
		"0",
		keep("mail_times", "0"),
		UD.reward_state(u, ids, total),
	}
	return table.concat(f, "\r\n")
end

function UD.union_of(e)
	local ui = (type(e.union) == "table" and type(e.union.union_info) == "table") and e.union.union_info or {}
	local id = tn(ui.union_id, 0)
	if id <= 0 then id = tn(type(S.union) == "table" and S.union.id or nil, 1) end
	local name = tok(ui.union_name, "")
	if name == "" or name == "0" then
		name = tok(type(S.union) == "table" and S.union.name or nil, "Guild")
	end
	local icon = tn(ui.union_icon, 1)
	if icon < 0 then icon = 1 end
	return { id = fint(id), name = name, icon = fint(icon) }
end

function UD.b_rank(e, u, i, ids)
	local x = UD.info_of(u, i, ids)
	local ui = UD.union_of(e)
	local kt = "-1"
	if x.status == 1 then kt = fint(tn(u.kt[tostring(i)], os.time() * 1000)) end
	return table.concat({ "14654", "1", ui.id, ui.name, ui.icon, fint(x.cur), fint(x.max), fint(tn(u.dmg[tostring(i)], 0)), kt }, "\r\n")
end

function UD.b_member(e, u, i)
	local hurt = tn(u.dmg[tostring(i)], 0)
	if hurt <= 0 then return "14657\r\n0" end
	local ui = type(e.user_info) == "table" and e.user_info or {}
	return table.concat({ "14657", "1", tok(ui.user_id, "1"), tok(ui.user_name, "Player"), fint(hurt) }, "\r\n")
end

function UD.members_owned(e)
	local un = e.union
	if type(un) ~= "table" then return true end
	local l = un.union_member_list_info
	if type(l) ~= "table" then return true end
	local n = 0
	for _ in pairs(l) do n = n + 1 end
	if n == 0 then return true end
	if n ~= 1 then return false end
	local m = l[1]
	local ui = type(e.user_info) == "table" and e.user_info or {}
	return type(m) == "table" and tostring(m.id) == tostring(tok(ui.user_id, "1"))
end

function UD.b_members(e, u)
	local ui = type(e.user_info) == "table" and e.user_info or {}
	local uu = (type(e.union) == "table" and type(e.union.user_union_info) == "table") and e.union.user_union_info or {}
	local rest = ukeep(uu, "rest_contribution", "0")
	return table.concat({
		"1004", "1",
		tok(ui.user_id, "1"),
		tok(ui.user_name, "Player"),
		fint(math.max(1, tn(ui.user_grade, 1))),
		"1", "1",
		fint(math.max(0, tn(ui.vip_grade, tn(e.vip_grade, 0)))),
		fint(math.max(0, tn(ui.fight_capacity, 0))),
		ukeep(uu, "union_post", "3"),
		"0",
		rest, rest,
		"0",
		fint(UD.att_count(u)),
		"0", "0",
	}, "\r\n")
end

local function trim_pve(e, n)
	local t = e.union_pve_info
	if type(t) ~= "table" then return end
	for k in pairs(t) do
		if type(k) == "number" and k > n then t[k] = nil end
	end
end

local function ctx()
	local e = ED()
	if e == nil then error("chua co the gioi") end
	local ids = UD.ids()
	local total = UD.total(ids)
	local u = UD.st(total)
	return e, u, ids, total
end

-- [BOSS GUILD] Da ha het boss (co u.full do h_fight dat) -> lan mo man ke tiep reset ca vong, boc tuong random moi.
function UD.roll_full(u, total)
	if u.full ~= true or u.cleared < total then return false end
	u.full = nil
	u.cleared = 0
	u.left = nil
	u.dmg, u.kt, u.mx, u.seed = {}, {}, {}, {}
	u.gen = math.floor(tn(u.gen, 0)) + 1
	mark()
	LS.save_state(true)
	log("boss guild: da ha het", total, "boss -> reset vong moi (#" .. tostring(u.gen) .. "), tuong random moi")
	return true
end

function UD.h_init(p, seq)
	local e, u, ids, total = ctx()
	UD.roll_full(u, total)
	trim_pve(e, UD.unlocked(u, total))
	stat_inc("ud_init")
	local blocks = { UD.b_user(e, u, ids, total), "14630\r\n0", UD.b_list(u, ids, total) }

	if UD.members_owned(e) then blocks[#blocks + 1] = UD.b_members(e, u) end
	return reply(seq, "union_copy_init", blocks)
end

function UD.h_members(p, seq)
	local e, u = ctx()
	if not UD.members_owned(e) then return nil end
	stat_inc("ud_members")
	return reply(seq, "union_persion_list", { UD.b_members(e, u) })
end

function UD.h_look(p, seq)
	local name = "union_copy_look_npc_info"
	local e, u, ids, total = ctx()
	UD.roll_full(u, total)
	local mode = math.floor(tn(p[1], 0))
	local idx = math.floor(tn(p[2], -1)) + 1
	local n = UD.unlocked(u, total)
	if idx < 1 or idx > n then return err_reply(seq, name, "LS_boss_chua_mo") end
	trim_pve(e, n)
	local blocks
	if mode == 1 then
		blocks = { UD.b_member(e, u, idx) }
	elseif mode == 2 then
		blocks = { UD.b_rank(e, u, idx, ids) }
	else
		blocks = { UD.b_user(e, u, ids, total), UD.b_list(u, ids, total), UD.b_rank(e, u, idx, ids) }
	end
	stat_inc("ud_look")
	return reply(seq, name, blocks)
end

-- [union265] block 401 = parse_both_sides_fight_damage: our_fight_is_hurt, enemy_fighting_damage.
-- SmUnionBattleReward:onUpdateDraw reads _ED.BothSidesFightDamage, which only this block creates.
function UD.b_hurt(our, enemy)
	return "401\r\n" .. fint(math.max(0, tn(our, 0))) .. "\r\n" .. fint(math.max(0, tn(enemy, 0)))
end

function UD.h_fight(p, seq)
	local name = "union_copy_fight"
	local e, u, ids, total = ctx()
	local idx = math.floor(tn(p[1], -1)) + 1
	local n = UD.unlocked(u, total)
	if idx < 1 or idx > n then return err_reply(seq, name, "LS_boss_chua_mo") end
	local zzHurt = math.max(0, floor_n(tn(p[2], 0)))  -- damage we dealt (clamped below when the boss is still alive)
	if idx > u.cleared then
		if not att_unlimited() and u.used >= UD.max_att() then return err_reply(seq, name, "LS_het_luot_danh_hom_nay", ERR.attempts) end
		local dmg = math.max(0, floor_n(tn(p[2], 0)))
		local cmax = math.max(0, floor_n(tn(p[3], 0)))
		local mx = UD.maxhp(u, idx, ids)
		if mx <= 0 then

			mx = math.max(cmax, dmg, 1)
			u.mx[tostring(idx)] = mx
		end
		local cur = mx
		if u.left ~= nil then cur = math.max(1, math.min(mx, floor_n(u.left))) end
		if dmg > cur then dmg = cur end
		zzHurt = dmg
		local left = cur - dmg
		u.atk = u.atk + 1
		if not att_unlimited() then u.used = u.used + 1 end
		u.dmg[tostring(idx)] = tn(u.dmg[tostring(idx)], 0) + dmg
		if left <= 0 then
			u.cleared = idx
			u.left = nil
			if u.cleared >= total then u.full = true end
			u.kt[tostring(idx)] = os.time() * 1000
			stat_inc("ud_kill")
			log("boss guild: ha guc boss", idx, "(id", ids[idx], ") sat thuong", fnum(dmg), "-> da ha", u.cleared, "/", total)
		else
			u.left = left
			log("boss guild: boss", idx, "sat thuong", fnum(dmg), "con", fnum(left), "/", fnum(mx))
		end
		R.ud_last = { idx = idx, dmg = dmg, left = math.max(0, left), max = mx }
		stat_inc("ud_fight")
		mark()
		LS.save_state(true)
	end
	trim_pve(e, UD.unlocked(u, total))
	-- enemy_fighting_damage: the local sim does not report what the boss dealt to us, so 0.
	return reply(seq, name, { UD.b_user(e, u, ids, total), UD.b_list(u, ids, total), UD.b_rank(e, u, idx, ids), UD.b_hurt(zzHurt, 0) })
end

function UD.h_lucky(p, seq)
	stat_inc("ud_lucky")
	return reply(seq, "union_copy_get_lucky_reward_info", { "14658\r\n0" })
end

function UD.h_draw(p, seq)
	stat_inc("ud_draw")
	return err_reply(seq, "union_copy_draw_npc_reward", "LS_boss_guild_khong_co_qua")
end

function UD.h_draw_all(p, seq)
	stat_inc("ud_draw")
	return err_reply(seq, "one_key_draw_union_copy_draw_reward", "LS_boss_guild_khong_co_qua")
end

function UD.dump_line()
	local ids = UD.ids()
	local total = UD.total(ids)
	local u = UD.st(total)
	local nxt = math.min(total, u.cleared + 1)
	local x = UD.info_of(u, nxt, ids)
	local l = R.ud_last
	return "[LS boss guild] da ha " .. u.cleared .. "/" .. total .. " | dang danh boss " .. nxt .. " (id " .. tostring(x.id) .. ") mau "
		.. fnum(x.cur) .. "/" .. fnum(x.max) .. " | so tran " .. u.atk
		.. (att_unlimited() and " | vo han luot" or (" | luot hom nay " .. u.used .. "/" .. UD.max_att()))
		.. " | ti le mau " .. tostring(tn(S.cfg.ud_hp, 100)) .. "%"
		.. (l ~= nil and (" | tran cuoi: boss " .. l.idx .. " sat thuong " .. fnum(l.dmg)) or "")
end

function UD.set_cleared(n)
	local total = UD.total()
	local u = UD.st(total)
	u.cleared = math.max(0, math.min(total, math.floor(tn(n, 0))))
	u.left = nil
	mark()
	LS.save_state(true)
	return u.cleared, total
end

function UD.set_hp_pct(pct)
	pct = tn(pct, 100)
	if pct < 1 then pct = 1 end
	if pct > 1000 then pct = 1000 end
	S.cfg.ud_hp = pct
	mark()
	return pct
end

function UD.reset()
	S.ud = nil
	R.ud_last = nil
	mark()
end

LS._ud = UD

end
init_ud()
end

do
local function init_am()

local AM = {}
local ESSENCE = 1554
local ID_BASE = 9100000
local FLOOR_TOP, FLOOR_LOW = 999999, 500000
local MAX_RESOLVE = 200
local DEF_POTIONS = { { 6, 1555, 100 }, { 6, 1556, 200 }, { 6, 1557, 1000 } }
local DEF_MAXLV = { [2] = 40, [3] = 60, [4] = 100, [5] = 150 }

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function plist(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		out[#out + 1] = { t = tonumber(a), v = tonumber(b) }
	end
	return out
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) }
	end
	return out
end

local function ci(r, i, d)
	local v = tonumber(r[i])
	if v == nil then return d end
	return v
end

function AM.T()
	local T = R.am_t
	if T ~= nil then return T end
	T = { m = {}, normal = {}, excl = {}, by_ex = {}, lv = {}, br = {}, ok = false, disp = {} }
	R.am_t = T
	local mt = dtab("ship_silk_bag_mould")
	if mt == nil then return T end
	local C = {
		id = schema("ship_silk_bag_mould", "id", 1), ty = schema("ship_silk_bag_mould", "mould_type", 4),
		ex = schema("ship_silk_bag_mould", "exclusive_id", 5), q = schema("ship_silk_bag_mould", "quality_level", 6),
		dec = schema("ship_silk_bag_mould", "decompose_output", 8), base = schema("ship_silk_bag_mould", "base_property", 10),
		extra = schema("ship_silk_bag_mould", "extra_property", 11), up = schema("ship_silk_bag_mould", "upgrade_group", 12),
		br = schema("ship_silk_bag_mould", "breake_group", 14),
	}
	for k, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local id = ci(r, C.id, nil) or (type(k) == "number" and k or nil)
			if id ~= nil then
				id = math.floor(id)
				local m = {
					id = id, ty = math.floor(ci(r, C.ty, 0)), ex = math.floor(ci(r, C.ex, -1)), q = math.floor(ci(r, C.q, 1)),
					dec = triples(r[C.dec]), base = plist(r[C.base]), extra = plist(r[C.extra]),
					up = math.floor(ci(r, C.up, 0)), br = math.floor(ci(r, C.br, 0)),
				}
				T.m[id] = m
				if m.ty == 1 then T.normal[#T.normal + 1] = id
				elseif m.ty == 2 then
					T.excl[#T.excl + 1] = id
					local l = T.by_ex[m.ex]
					if l == nil then l = {}; T.by_ex[m.ex] = l end
					l[#l + 1] = id
				end
			end
		end
	end
	table.sort(T.normal)
	table.sort(T.excl)

	local lt = dtab("silk_bag_level_up_group_mould")
	if lt ~= nil then
		local LI = { lib = schema("ship_silk_bag_level", "lib_id", 2), rng = schema("ship_silk_bag_level", "cur_level_range", 3),
			exp = schema("ship_silk_bag_level", "up_level_exp", 5) }
		for _, row in pairs(lt) do
			local r = cells(row)
			if r ~= nil then
				local lib = ci(r, LI.lib, nil)
				local lo, hi = string.match(tostring(r[LI.rng] or ""), "^%s*(%d+)%s*,%s*(%d+)")
				local ex = ci(r, LI.exp, nil)
				if lib ~= nil and lo ~= nil and ex ~= nil then
					lib = math.floor(lib)
					local l = T.lv[lib]
					if l == nil then l = {}; T.lv[lib] = l end
					l[#l + 1] = { lo = tonumber(lo), hi = tonumber(hi), exp = ex }
				end
			end
		end
		for _, l in pairs(T.lv) do table.sort(l, function(a, b) return a.lo < b.lo end) end
	end

	local bt = dtab("silk_bag_break_group_mould")
	if bt ~= nil then
		local BI = { lib = schema("ship_silk_bag_breake", "lib_id", 2), cur = schema("ship_silk_bag_breake", "cur_breake_level", 3),
			cost = schema("ship_silk_bag_breake", "breake_consume", 5) }
		for _, row in pairs(bt) do
			local r = cells(row)
			if r ~= nil then
				local lib, cur = ci(r, BI.lib, nil), ci(r, BI.cur, nil)
				if lib ~= nil and cur ~= nil then
					lib, cur = math.floor(lib), math.floor(cur)
					local l = T.br[lib]
					if l == nil then l = { rows = {}, max = 0 }; T.br[lib] = l end
					l.rows[cur] = { cost = triples(r[BI.cost]), grow = plist(r[BI.cost + 1]) }
					if cur > l.max then l.max = cur end
				end
			end
		end
	end

	T.maxlv = {}
	local mp = cfg_pairs("ship_config", 44)
	if mp ~= nil then for q, v in pairs(mp) do T.maxlv[q] = math.floor(v) end end
	for q, v in pairs(DEF_MAXLV) do if T.maxlv[q] == nil and mp == nil then T.maxlv[q] = v end end
	T.potions = triples(cfg_str("ship_config", 45))
	if #T.potions == 0 then T.potions = DEF_POTIONS end
	local ds = cfg_str("ship_config", 46)
	if ds ~= nil then
		for q, a, b, c in string.gmatch(ds, "(%d+)%s*:%s*(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
			T.disp[tonumber(q)] = { tonumber(a), tonumber(b), tonumber(c) }
		end
	end
	T.ok = (#T.normal + #T.excl) > 0
	return T
end

function AM.mould(mid)
	return AM.T().m[mid]
end

local function stage_row(lib, st)
	local l = AM.T().br[lib]
	if l == nil then return nil end
	if st < 0 then st = 0 end
	if st > l.max then st = l.max end
	return l.rows[st]
end

function AM.maxlv(m)
	local T = AM.T()
	local v = T.maxlv[m.q]
	if v ~= nil then return v end
	local best = 0
	for _, x in pairs(T.maxlv) do if x > best then best = x end end
	if best <= 0 then best = 40 end
	return best
end

function AM.exp_need(m, level)
	local rows = AM.T().lv[m.up]
	if rows == nil or #rows == 0 then return 0 end
	for i = 1, #rows do
		local r = rows[i]
		if level >= r.lo and level <= r.hi then return r.exp end
	end
	return rows[#rows].exp
end

function AM.attrs(m, level)
	local acc, order = {}, {}
	for _, p in ipairs(m.base) do
		if acc[p.t] == nil then order[#order + 1] = p.t; acc[p.t] = 0 end
		acc[p.t] = acc[p.t] + p.v
	end
	local top = level - 1
	if top >= 1 then
		for st = 0, math.floor(top / 10) do
			local lo, hi = math.max(1, st * 10), math.min(top, st * 10 + 9)
			local steps = hi - lo + 1
			if steps > 0 then
				local row = stage_row(m.br, st)
				if row ~= nil then
					for _, g in ipairs(row.grow) do
						if acc[g.t] ~= nil then acc[g.t] = acc[g.t] + g.v * steps end
					end
				end
			end
		end
	end
	return acc, order
end

function AM.props_str(m, level)
	local key = m.id * 1000 + math.min(level, 999)
	local c = R.am_s
	if c == nil then c = {}; R.am_s = c end
	local s = c[key]
	if s ~= nil then return s end
	local acc, order = AM.attrs(m, level)
	local parts = {}
	for _, t in ipairs(order) do parts[#parts + 1] = fint(t) .. "," .. fint(acc[t]) end
	s = table.concat(parts, "|")
	if s == "" then s = "0,0" end
	c[key] = s
	return s
end

function AM.invested_exp(m, level, exp)
	local t = exp
	for l = 1, level - 1 do t = t + AM.exp_need(m, l) end
	return t
end

function AM.resolve_list(b)
	local m = AM.mould(b.m)
	if m == nil then return { { 6, ESSENCE, 1 } } end
	local got = {}
	local function add(id, n) if n > 0 then got[id] = (got[id] or 0) + n end end
	for _, tr in ipairs(m.dec) do if tr[1] == 6 then add(tr[2], tr[3]) end end
	for st = 0, b.q - 1 do
		local row = stage_row(m.br, st)
		if row ~= nil and row.cost[1] ~= nil and row.cost[1][1] == 6 then add(row.cost[1][2], row.cost[1][3]) end
	end
	local rest = AM.invested_exp(m, b.l, b.x)
	local pots = {}
	for i, p in ipairs(AM.T().potions) do pots[i] = p end
	table.sort(pots, function(x, y) return x[3] > y[3] end)
	for _, p in ipairs(pots) do
		if p[3] > 0 then
			local n = math.floor(rest / p[3])
			if n > 0 then add(p[2], n); rest = rest - n * p[3] end
		end
	end
	local ids = {}
	for id in pairs(got) do ids[#ids + 1] = id end
	table.sort(ids)
	local out = {}
	for _, id in ipairs(ids) do out[#out + 1] = { 6, id, got[id] } end
	if #out == 0 then out[1] = { 6, ESSENCE, 1 } end
	return out
end

function AM.resolve_str(b)
	local parts = {}
	for _, r in ipairs(AM.resolve_list(b)) do parts[#parts + 1] = fint(r[1]) .. "," .. fint(r[2]) .. "," .. fint(r[3]) end
	return table.concat(parts, "|")
end

local function st()
	local a = S.am
	if type(a) ~= "table" then a = { v = 0, nid = ID_BASE, b = {}, base = {} }; S.am = a end
	if type(a.b) ~= "table" then a.b = {} end
	if type(a.base) ~= "table" then a.base = {} end
	a.nid = math.max(ID_BASE, math.floor(tn(a.nid, ID_BASE)))
	return a
end

local function invalidate()
	R.am_idx, R.am_ship = nil, nil
end

local function find(id)
	id = tonumber(id)
	if id == nil then return nil end
	local ix = R.am_idx
	if ix == nil then
		ix = {}
		for _, b in ipairs(st().b) do ix[b.id] = b end
		R.am_idx = ix
	end
	return ix[math.floor(id)]
end

local function by_ship(sid)
	local mp = R.am_ship
	if mp == nil then
		mp = {}
		for _, b in ipairs(st().b) do
			if b.s > 0 and b.i > 0 then
				local l = mp[b.s]
				if l == nil then l = {}; mp[b.s] = l end
				l[#l + 1] = b
			end
		end
		R.am_ship = mp
	end
	return mp[tonumber(sid) or -1]
end

local function new_bag(mid)
	local a = st()
	local b = { id = a.nid, m = mid, l = 1, x = 0, q = 0, s = 0, i = -1 }
	a.nid = a.nid + 1
	a.b[#a.b + 1] = b
	invalidate()
	return b
end

function AM.give(e, mid, n)
	mid = math.floor(tonumber(mid) or -1)
	if not AM.T().ok or AM.mould(mid) == nil then return 0 end
	if e ~= nil and AM.ensure(e) == nil then return 0 end
	local k = 0
	for _ = 1, math.max(1, math.floor(tn(n, 1))) do new_bag(mid); k = k + 1 end
	mark()
	if e ~= nil then pcall(AM.rewrite, e) end
	return k
end

function AM.restock()
	local T = AM.T()
	local created = {}
	if not T.ok then return created end
	local a = st()
	local have = {}
	for _, b in ipairs(a.b) do
		if b.s <= 0 then have[b.m] = true end
	end
	for _, mid in ipairs(T.normal) do
		if not have[mid] then created[#created + 1] = new_bag(mid) end
	end
	for _, mid in ipairs(T.excl) do
		if not have[mid] then created[#created + 1] = new_bag(mid) end
	end
	if #created > 0 then mark() end
	return created
end

local function auto_on()
	return not (type(S.cfg) == "table" and S.cfg.am_auto == false)
end

local SPEC_SKIP = { [43] = true, [46] = true }

local function add_bag_contrib(b, out)
	local m = AM.mould(b.m)
	if m == nil then return end
	local acc = AM.attrs(m, b.l)
	for t, v in pairs(acc) do
		if t >= 0 and t <= 3 then out[t + 1] = out[t + 1] + v
		elseif not SPEC_SKIP[t] then out.spec[t] = (out.spec[t] or 0) + v end
	end
	for _, p in ipairs(m.extra) do
		if p.t >= 0 and p.t <= 3 then out[p.t + 1] = out[p.t + 1] + p.v
		elseif not SPEC_SKIP[p.t] then out.spec[p.t] = (out.spec[p.t] or 0) + p.v end
	end
end

function AM.contrib(sid)
	local out = { 0, 0, 0, 0, spec = {} }
	local l = by_ship(sid)
	if l ~= nil then for _, b in ipairs(l) do add_bag_contrib(b, out) end end
	return out
end

-- [BOT RANDOM] Amulet ngau nhien cho bot: o 1 doc quyen dung tuong (neu co), o 2-4 thuong, o 5-8 ho vi.
-- Moi o chon ngau nhien trong cac mau pham cao nhat cua nhom, max cap. base = ship_base_template_id.
function AM.bot_stats(base, rnd)
	local out = { 0, 0, 0, 0, spec = {} }
	local T = AM.T()
	if not T.ok then return out end
	local g = R.am_guard
	if g == nil then
		g = {}
		for id, m in pairs(T.m) do
			if m.ty ~= 1 and m.ty ~= 2 then g[#g + 1] = id end
		end
		table.sort(g)
		R.am_guard = g
	end
	local function top_list(list)
		local tq, res = -1, {}
		for _, id in ipairs(list) do
			local m = T.m[id]
			if m ~= nil then
				if m.q > tq then tq, res = m.q, { id }
				elseif m.q == tq then res[#res + 1] = id end
			end
		end
		return res
	end
	local function put(mid)
		local m = T.m[mid]
		if m ~= nil then add_bag_contrib({ m = mid, l = AM.maxlv(m) }, out) end
	end
	local function pick(list, n)
		local pool = top_list(list)
		for k = 1, math.min(n, #pool) do
			local j = k + math.floor(rnd() * (#pool - k + 1))
			pool[k], pool[j] = pool[j], pool[k]
			put(pool[k])
		end
	end
	local ex = T.by_ex[tonumber(base)]
	if ex ~= nil and #ex > 0 then pick(ex, 1) end
	pick(T.normal, 3)
	pick(g, 4)
	return out
end

function AM.delta(sid)
	local out = { 0, 0, 0, 0, spec = {} }
	if S == nil or type(S.am) ~= "table" then return out end
	local key = tostring(math.floor(tonumber(sid) or -1))
	local cur = AM.contrib(sid)
	local base = nil
	if S.heroes[key] == nil then base = S.am.base ~= nil and S.am.base[key] or nil end
	for i = 1, 4 do out[i] = cur[i] - ((base ~= nil and tonumber(base[i])) or 0) end
	for t, v in pairs(cur.spec) do out.spec[t] = v end
	if type(base) == "table" and type(base.spec) == "table" then
		for t, v in pairs(base.spec) do out.spec[t] = (out.spec[t] or 0) - v end
	end
	return out
end

function AM.tokens(e, b, t)
	local m = AM.mould(b.m)
	if m == nil then return false end
	local uid = 0
	if type(e.user_info) == "table" then uid = math.floor(tn(e.user_info.user_id, 0)) end
	t[#t + 1] = fint(b.id)
	t[#t + 1] = fint(b.l)
	t[#t + 1] = fint((b.s > 0 and b.i > 0) and b.s or -1)
	t[#t + 1] = fint((b.s > 0 and b.i > 0) and b.i or -1)
	t[#t + 1] = AM.resolve_str(b)
	t[#t + 1] = fint(uid)
	t[#t + 1] = fint(b.x)
	t[#t + 1] = AM.props_str(m, b.l)
	t[#t + 1] = fint(b.q)
	t[#t + 1] = fint(b.m)
	return true
end

function AM.blk_bags(e, list)
	local body, n = {}, 0
	for i = 1, #list do
		if AM.tokens(e, list[i], body) then n = n + 1 end
	end
	local t = { "14117", fint(n) }
	for i = 1, #body do t[#t + 1] = body[i] end
	return table.concat(t, "\r\n")
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do
		b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3])
	end
	return table.concat(b, "\r\n")
end

local function hero_blocks(e, sid, blocks)
	local key = tostring(math.floor(tonumber(sid) or -1))
	local ship = e.user_ship[key]
	if type(ship) ~= "table" then return end
	local F = commit_hero(e, key, {})
	if F == nil then return end
	push_all(blocks, blk_ship(ship, F))
	push_all(blocks, blk_fight(e, key, F))
end

function AM.in_sync(e)
	local lst = e.silkbag_pack_info
	if type(lst) ~= "table" then return false end
	local n = 0
	for _, d in pairs(lst) do
		n = n + 1
		if type(d) ~= "table" then return false end
		local b = find(d.id)
		if b == nil then return false end
		if tonumber(d.level) ~= b.l or tonumber(d.exp) ~= b.x or tonumber(d.quality) ~= b.q or tonumber(d.silkBagMouldId) ~= b.m then return false end
		local es = (b.s > 0 and b.i > 0) and b.s or -1
		local ei = (b.s > 0 and b.i > 0) and b.i or -1
		if tonumber(d.onUseShipId) ~= es or tonumber(d.onUseIndex) ~= ei then return false end
	end
	return n == #st().b
end

function AM.rewrite(e)
	local a = st()
	e.silkbag_pack_info = nil
	local body, n = {}, 0
	for i = 1, #a.b do
		if AM.tokens(e, a.b[i], body) then n = n + 1 end
	end
	local toks = { fint(n) }
	for i = 1, #body do toks[#toks + 1] = body[i] end
	local ok = call_parser("parse_silkbag_pack_info", toks)
	if not ok or type(e.silkbag_pack_info) ~= "table" then
		local lst = {}
		local pos = 1
		for i = 1, n do
			lst[i] = {
				id = tonumber(body[pos]), level = tonumber(body[pos + 1]), onUseShipId = tonumber(body[pos + 2]), onUseIndex = tonumber(body[pos + 3]),
				resolveRescouce = body[pos + 4], userInfo = tonumber(body[pos + 5]), exp = tonumber(body[pos + 6]), addBaseProperty = body[pos + 7],
				quality = tonumber(body[pos + 8]), silkBagMouldId = tonumber(body[pos + 9]),
			}
			pos = pos + 10
		end
		e.silkbag_pack_info = lst
	end
	R.am_rw = (R.am_rw or 0) + 1
	if R.am_rw <= 5 then log("amulet: ghi lai danh sach vao game:", n, "cai (lan", R.am_rw, ")") end
end

function AM.free_orphans(e)
	if R.inject ~= nil or R.grant ~= nil or type(e.user_ship) ~= "table" then return 0 end
	local n = 0
	for _, b in ipairs(st().b) do
		if b.s > 0 and e.user_ship[tostring(b.s)] == nil then b.s, b.i = 0, -1; n = n + 1 end
	end
	if n > 0 then invalidate(); mark(); log("amulet: tra ve kho", n, "cai cua tuong da bi go") end
	return n
end

function AM.seed(e)
	local T = AM.T()
	local a = { v = 1, nid = ID_BASE, b = {}, base = {} }
	S.am = a
	invalidate()
	local rec = {}
	local lst = e.silkbag_pack_info
	if type(lst) == "table" then
		for _, d in pairs(lst) do
			if type(d) == "table" and tonumber(d.id) ~= nil then rec[#rec + 1] = d end
		end
		table.sort(rec, function(x, y) return tonumber(x.id) < tonumber(y.id) end)
	end
	local seen = {}
	for _, d in ipairs(rec) do
		local id, mid = math.floor(tonumber(d.id)), tonumber(d.silkBagMouldId)
		if mid ~= nil and T.m[math.floor(mid)] ~= nil and not seen[id] and id > 0 then
			seen[id] = true
			local sid, ix = tonumber(d.onUseShipId), tonumber(d.onUseIndex)
			local eq = sid ~= nil and ix ~= nil and sid > 0 and ix > 0
			local b = {
				id = id, m = math.floor(mid), l = math.max(1, math.floor(tn(d.level, 1))), x = math.max(0, math.floor(tn(d.exp, 0))),
				q = math.max(0, math.floor(tn(d.quality, 0))), s = eq and math.floor(sid) or 0, i = eq and math.floor(ix) or -1,
			}
			a.b[#a.b + 1] = b
			if id >= a.nid then a.nid = id + 1 end
			if eq then
				local key = tostring(b.s)
				local bs = a.base[key]
				if bs == nil then bs = { 0, 0, 0, 0, spec = {} }; a.base[key] = bs end
				add_bag_contrib(b, bs)
			end
		end
	end
	local made = AM.restock()
	mark()
	LS.save_state(true)
	log("amulet: khoi tao kho:", #a.b, "cai (gom", #rec, "cai goc trong ban ghi,", #made, "cai LS tao)")
	return a
end

function AM.clean()
	local T = AM.T()
	if not T.ok then return 0 end
	local a = st()
	local keep, gone, seen, slot, top = {}, 0, {}, {}, 0
	for _, b in ipairs(a.b) do
		local good = false
		if type(b) == "table" and tonumber(b.id) ~= nil and tonumber(b.m) ~= nil then
			b.id, b.m = math.floor(tonumber(b.id)), math.floor(tonumber(b.m))
			local m = T.m[b.m]
			if m ~= nil and b.id > 0 and not seen[b.id] then
				seen[b.id] = true
				b.l = math.min(AM.maxlv(m), math.max(1, math.floor(tn(b.l, 1))))
				b.x = math.max(0, math.floor(tn(b.x, 0)))
				b.q = math.min(60, math.max(0, math.floor(tn(b.q, 0))))
				b.s = math.max(0, math.floor(tn(b.s, 0)))
				b.i = math.floor(tn(b.i, -1))
				if b.s <= 0 or b.i <= 0 or b.i > 8 then b.s, b.i = 0, -1 end
				if b.s > 0 then
					local key = b.s .. ":" .. b.i
					if slot[key] then b.s, b.i = 0, -1 else slot[key] = true end
				end
				if b.id > top then top = b.id end
				good = true
			end
		end
		if good then keep[#keep + 1] = b else gone = gone + 1 end
	end
	if gone > 0 then a.b = keep; invalidate(); mark(); log("amulet: bo", gone, "cai khong ro mau / trung id") end
	if top >= a.nid then a.nid = top + 1 end
	return gone
end

function AM.ensure(e)
	local a = S.am
	if type(a) == "table" and a.v == 1 and type(a.b) == "table" then
		if not R.am_clean then R.am_clean = true; AM.clean() end
		R.am_ready = true
		return a
	end
	if not AM.T().ok then return nil end
	R.am_ready = true
	R.am_clean = true
	return AM.seed(e)
end

function AM.items()
	local T = AM.T()
	local ids = { ESSENCE }
	for _, p in ipairs(T.potions) do ids[#ids + 1] = p[2] end
	return ids
end

function AM.floor()
	if not auto_on() then return 0 end
	local n = 0
	for _, id in ipairs(AM.items()) do
		if LS.prop_get(id) < FLOOR_LOW then
			LS.prop_set(id, FLOOR_TOP)
			n = n + 1
		end
	end
	return n
end

function AM.patch_config()
	-- [FIX lag 8] Chay moi tick nhung chi can 1 lan (idempotent).
	if R.am_cfg then return false end
	local d = G("dms")
	if type(d) ~= "table" or type(d.equipment_config) ~= "table" then return false end
	local t = d.equipment_config
	if t[19] ~= nil then return false end
	t[19] = "19\t[LS] dieu kien ho vi\t19\t999,99|999,99"
	R.am_cfg = true
	log("amulet: them equipment_config dong 19 (de tran khong bi loi khi mac amulet doc quyen)")
	return true
end

function AM.on_world(e)
	R.am_t, R.am_s = nil, nil
	invalidate()
	R.am_ready = false
	R.am_clean = false
	R.am_tick = 0

	local cp = {}
	local lst = e.silkbag_pack_info
	if type(lst) == "table" then
		for _, d in pairs(lst) do
			if type(d) == "table" and tonumber(d.id) ~= nil and tonumber(d.id) < ID_BASE then
				local c = {}
				for k, v in pairs(d) do c[k] = v end
				cp[#cp + 1] = c
			end
		end
	end
	R.am_rec = cp
	AM.patch_config()
end

function AM.restore(e)
	if type(e) ~= "table" then return end
	local lst = {}
	for i, d in ipairs(R.am_rec or {}) do
		local c = {}
		for k, v in pairs(d) do c[k] = v end
		lst[i] = c
	end
	e.silkbag_pack_info = lst
	invalidate()
	R.am_ready = false
	R.am_clean = false
end

function AM.tick(e)
	if S == nil or not R.ready then return end
	AM.patch_config()
	local a = AM.ensure(e)
	if a == nil then return end
	R.am_tick = (R.am_tick or 0) + 1
	if auto_on() then
		local made = AM.restock()
		if #made > 0 then R.am_dirty = true end
		AM.floor()
	end
	if R.am_tick % 40 == 0 then AM.free_orphans(e) end
	if not AM.in_sync(e) then AM.rewrite(e) end
end

local function ctx(name)
	local e = ED()
	if e == nil then error("chua co the gioi") end
	AM.patch_config()
	if AM.ensure(e) == nil then error("khong co bang amulet") end
	return e
end

local function fin(e, seq, name, changed, sids)

	if auto_on() then
		local made = AM.restock()
		for i = 1, #made do changed[#changed + 1] = made[i] end
		AM.floor()
	end
	local blocks = { AM.blk_bags(e, changed) }
	for _, sid in ipairs(sids or {}) do hero_blocks(e, sid, blocks) end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function uniq(list, b)
	for i = 1, #list do if list[i] == b then return end end
	list[#list + 1] = b
end

function AM.h_use(p, seq)
	local name = "ship_slik_bag_use"
	local e = ctx(name)
	local sid = tostring(math.floor(tn(p[1], -1)))
	local idx = math.floor(tn(p[3], 0))
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" then return err_reply(seq, name, "LS_khong_co_tuong", 15002) end
	local b = find(p[2])
	if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
	local m = AM.mould(b.m)
	if m == nil then return err_reply(seq, name, "LS_sai_mau_amulet", ERR.generic) end
	if idx < 1 or idx > 8 then return err_reply(seq, name, "LS_sai_o_amulet", ERR.generic) end
	if m.ty == 2 then
		if idx ~= 1 then return err_reply(seq, name, "LS_doc_quyen_chi_o_1", 15024) end
		if m.ex ~= tonumber(ship.ship_base_template_id) then return err_reply(seq, name, "LS_doc_quyen_khong_khop", 15019) end
	elseif m.ty == 1 then
		if idx == 1 then return err_reply(seq, name, "LS_o_1_chi_cho_doc_quyen", 15019) end
		if idx > 4 then return err_reply(seq, name, "LS_o_ho_vi_chua_mo", 15023) end
	else
		if idx < 5 then return err_reply(seq, name, "LS_ho_vi_chi_o_5_8", 15023) end
	end
	local shipn = math.floor(tonumber(sid))
	if b.s > 0 and b.i > 0 and b.s ~= shipn then return err_reply(seq, name, "LS_amulet_dang_mac_tuong_khac", 15018) end
	local changed, sids = {}, {}

	for _, o in ipairs(st().b) do
		if o ~= b and o.s == shipn and o.i == idx then
			o.s, o.i = 0, -1
			uniq(changed, o)
		end
	end
	b.s, b.i = shipn, idx
	invalidate()
	uniq(changed, b)
	sids[1] = sid
	stat_inc("am_use")
	return fin(e, seq, name, changed, sids)
end

function AM.h_unuse(p, seq)
	local name = "ship_slik_bag_un_use"
	local e = ctx(name)
	local sid = tostring(math.floor(tn(p[1], -1)))
	local b = find(p[2])
	if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
	if b.s <= 0 or b.i <= 0 then return err_reply(seq, name, "LS_amulet_chua_mac", 15017) end
	local owner = tostring(b.s)
	b.s, b.i = 0, -1
	invalidate()
	stat_inc("am_unuse")
	local sids = { owner }
	if owner ~= sid then sids[2] = sid end
	return fin(e, seq, name, { b }, sids)
end

local function parse_use(str)
	local out = {}
	for a, b in string.gmatch(tostring(str or ""), "(%d+)%s*:%s*(%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b) }
	end
	return out
end

local function potion_exp(id)
	for _, p in ipairs(AM.T().potions) do if p[2] == id then return p[3] end end
	return nil
end

local function room_to(m, b, cap)
	local need = -b.x
	for l = b.l, cap - 1 do need = need + AM.exp_need(m, l) end
	return need
end

local function do_level(p, seq, name, list, auto_promote)
	local e = ctx(name)
	local b = find(p[1])
	if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
	local m = AM.mould(b.m)
	if m == nil then return err_reply(seq, name, "LS_sai_mau_amulet", ERR.generic) end
	local maxlv = AM.maxlv(m)
	if b.l >= maxlv then return err_reply(seq, name, "LS_amulet_cap_toi_da", 15011) end
	local cap = math.min(maxlv, (b.q + 1) * 10)
	if not auto_promote and b.l >= cap then return err_reply(seq, name, "LS_can_dot_pha", 15011) end
	if #list == 0 then return err_reply(seq, name, "LS_khong_co_thuoc", ERR.items) end
	if AM.exp_need(m, b.l) <= 0 then return err_reply(seq, name, "LS_thieu_bang_kinh_nghiem", ERR.generic) end
	local left = {}
	for i, it in ipairs(list) do
		if potion_exp(it[1]) == nil or potion_exp(it[1]) <= 0 or it[2] <= 0 then return err_reply(seq, name, "LS_thuoc_khong_hop_le", ERR.generic) end
		if LS.prop_get(it[1]) < it[2] then return err_reply(seq, name, "LS_khong_du_thuoc", ERR.items) end
		left[i] = it[2]
	end
	local lv0, promoted, gained = b.l, 0, 0
	while b.l < maxlv do
		cap = math.min(maxlv, (b.q + 1) * 10)
		if b.l < cap then
			local room, gain = room_to(m, b, cap), 0
			for i, it in ipairs(list) do
				if room > 0 and left[i] > 0 then
					local val = potion_exp(it[1])
					local k = math.min(left[i], math.ceil(room / val))
					if k > 0 then
						LS.prop_add(it[1], -k)
						left[i] = left[i] - k
						gain = gain + k * val
						room = room - k * val
					end
				end
			end
			if gain <= 0 then break end
			gained = gained + gain
			b.x = b.x + gain
			while b.l < cap do
				local need = AM.exp_need(m, b.l)
				if need > 0 and b.x >= need then b.x = b.x - need; b.l = b.l + 1 else break end
			end
			if b.l >= cap then b.x = 0 end
		end
		if b.l < cap or b.l >= maxlv or not auto_promote then break end
		local row = stage_row(m.br, b.q)
		local cost = row ~= nil and row.cost[1] or nil
		if cost == nil or cost[1] ~= 6 or cost[3] <= 0 or LS.prop_get(cost[2]) < cost[3] then break end
		LS.prop_add(cost[2], -cost[3])
		b.q = b.q + 1
		promoted = promoted + 1
	end
	if b.l == lv0 and promoted == 0 and gained == 0 then
		return err_reply(seq, name, "LS_can_dot_pha", 15011)
	end
	stat_inc("am_level")
	if promoted > 0 then stat_inc("am_promote", promoted) end
	R.am_last = "cap " .. fint(lv0) .. " -> " .. fint(b.l) .. (promoted > 0 and " | dot pha +" .. fint(promoted) or "")
	local sids = nil
	if b.s > 0 and b.i > 0 then sids = { tostring(b.s) } end
	return fin(e, seq, name, { b }, sids)
end

function AM.h_level(p, seq)
	return do_level(p, seq, "ship_slik_bag_level_up", parse_use(p[2]))
end

function AM.h_onekey(p, seq)
	return do_level(p, seq, "ship_slik_bag_one_key_level_up", parse_use(p[2]), true)
end

function AM.h_promote(p, seq)
	local name = "ship_slik_bag_promote"
	local e = ctx(name)
	local b = find(p[1])
	if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
	local m = AM.mould(b.m)
	if m == nil then return err_reply(seq, name, "LS_sai_mau_amulet", ERR.generic) end
	if b.l >= AM.maxlv(m) then return err_reply(seq, name, "LS_amulet_cap_toi_da", 15011) end
	if b.l < (b.q + 1) * 10 then return err_reply(seq, name, "LS_chua_du_cap_dot_pha", 15021) end
	local row = stage_row(m.br, b.q)
	local cost = row ~= nil and row.cost[1] or nil
	if cost == nil or cost[1] ~= 6 then return err_reply(seq, name, "LS_het_dot_pha", 15011) end
	if LS.prop_get(cost[2]) < cost[3] then return err_reply(seq, name, "LS_khong_du_tinh_hoa", ERR.items) end
	LS.prop_add(cost[2], -cost[3])
	b.q = b.q + 1
	stat_inc("am_promote")
	local sids = nil
	if b.s > 0 and b.i > 0 then sids = { tostring(b.s) } end
	return fin(e, seq, name, { b }, sids)
end

function AM.h_change(p, seq)
	local name = "ship_slik_bag_change_mould"
	local e = ctx(name)
	local b = find(p[1])
	if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
	local m = AM.mould(b.m)
	if m == nil then return err_reply(seq, name, "LS_sai_mau_amulet", ERR.generic) end
	if m.ty ~= 1 then return err_reply(seq, name, "LS_chi_doi_amulet_thuong", 15023) end
	local T = AM.T()
	local cost = T.disp[m.q]
	local cands = {}
	for _, mid in ipairs(T.normal) do
		local o = T.m[mid]
		if mid ~= m.id and o.q == m.q then cands[#cands + 1] = mid end
	end
	if #cands == 0 then return err_reply(seq, name, "LS_khong_co_mau_de_doi", 15023) end
	if cost ~= nil and cost[1] == 6 and cost[3] > 0 then
		if LS.prop_get(cost[2]) < cost[3] then return err_reply(seq, name, "LS_khong_du_tinh_hoa", ERR.items) end
		LS.prop_add(cost[2], -cost[3])
	end
	local pick = cands[math.random(#cands)]
	b.m = pick
	stat_inc("am_change")
	local sids = nil
	if b.s > 0 and b.i > 0 then sids = { tostring(b.s) } end
	return fin(e, seq, name, { b }, sids)
end

function AM.h_resolve(p, seq)
	local name = "ship_slik_bag_resolve"
	local e = ctx(name)
	local ids, seen = {}, {}
	for w in string.gmatch(tostring(p[1] or ""), "[^,%s]+") do
		local id = tonumber(w)
		if id == nil then return err_reply(seq, name, "LS_id_amulet_sai", ERR.generic) end
		id = math.floor(id)
		if not seen[id] then seen[id] = true; ids[#ids + 1] = id end
	end
	if #ids == 0 then return err_reply(seq, name, "LS_chua_chon_amulet", ERR.generic) end
	if #ids > MAX_RESOLVE then return err_reply(seq, name, "LS_phan_giai_toi_da_200", 15010) end
	local bags = {}
	for _, id in ipairs(ids) do
		local b = find(id)
		if b == nil then return err_reply(seq, name, "LS_khong_co_amulet", 15017) end
		if b.s > 0 and b.i > 0 then return err_reply(seq, name, "LS_amulet_dang_mac_khong_phan_giai", 15022) end
		bags[#bags + 1] = b
	end
	local got = {}
	for _, b in ipairs(bags) do
		for _, r in ipairs(AM.resolve_list(b)) do got[r[2]] = (got[r[2]] or 0) + r[3] end
	end

	local gone = {}
	for _, b in ipairs(bags) do gone[b.id] = true end
	local keep = {}
	for _, b in ipairs(st().b) do
		if not gone[b.id] then keep[#keep + 1] = b end
	end
	st().b = keep
	invalidate()
	local gids = {}
	for id in pairs(got) do gids[#gids + 1] = id end
	table.sort(gids)
	local items = {}
	for _, id in ipairs(gids) do
		items[#items + 1] = { id, 6, got[id] }
		LS.prop_set(id, math.min(FLOOR_TOP * 10, LS.prop_get(id) + got[id]))
	end
	local made = {}
	if auto_on() then
		made = AM.restock()
		AM.floor()
	end
	local sl = {}
	for _, id in ipairs(ids) do sl[#sl + 1] = fint(id) end
	local blocks = { "14118\r\n" .. table.concat(sl, ",") }

	if #made > 0 then blocks[#blocks + 1] = AM.blk_bags(e, made) end
	blocks[#blocks + 1] = blk_reward(items)
	stat_inc("am_resolve", #ids)
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function AM.counts()
	local a = S ~= nil and S.am or nil
	if type(a) ~= "table" or type(a.b) ~= "table" then return nil end
	local T = AM.T()
	local n, nn, nx, np, eq = 0, 0, 0, 0, 0
	for _, b in ipairs(a.b) do
		n = n + 1
		local m = T.m[b.m]
		if m ~= nil then
			if m.ty == 1 then nn = nn + 1 elseif m.ty == 2 then nx = nx + 1 else np = np + 1 end
		end
		if b.s > 0 and b.i > 0 then eq = eq + 1 end
	end
	return n, nn, nx, np, eq
end

function AM.dump_line()
	local n, nn, nx, np, eq = AM.counts()
	if n == nil then return "[LS amulet] chua khoi tao" end
	return "[LS amulet] kho " .. n .. " cai (thuong " .. nn .. ", doc quyen " .. nx .. ", ho vi " .. np .. ") | dang mac " .. eq
		.. " | thuoc/tinh hoa " .. table.concat((function()
			local t = {}
			for _, id in ipairs(AM.items()) do t[#t + 1] = fint(id) .. "=" .. fnum(LS.prop_get(id)) end
			return t
		end)(), " ")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT")
		.. (R.am_last ~= nil and (" | len cap cuoi: " .. R.am_last) or "")
		.. " | ghi lai " .. tostring(R.am_rw or 0) .. " lan"
end

function AM.reset()
	S.am = nil
	R.am_ready = false
	invalidate()
	mark()
end

do
	local ws_delta = WS.delta
	WS.delta = function(sid)
		local out = ws_delta(sid)
		local ok, d = pcall(AM.delta, sid)
		if ok and type(d) == "table" then
			for i = 1, 4 do out[i] = out[i] + d[i] end
			out.spec = out.spec or {}
			for t, v in pairs(d.spec) do out.spec[t] = (out.spec[t] or 0) + v end
		elseif not ok then
			R.am_errs = (R.am_errs or 0) + 1
			if R.am_errs <= 5 then log("loi chi so amulet:", tostring(d)) end
		end
		return out
	end
end

LS._am = AM

end
init_am()
end

do
local function init_tl()

local TL = {}
local POINT_TYPE = 34
local PTS_LOW, PTS_TOP = 6000, 12000
local SILVER_LOW, SILVER_TOP = 1500000000, 3000000000
local ERR_NOT_OPEN, ERR_MAX, ERR_PREREQ = 34036, 34038, 34039
local BATCH = 25

local PASS = { [8] = true, [10] = true, [33] = true, [34] = true, [40] = true, [42] = true, [55] = true, [70] = true, [71] = true }

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function ci(r, i, d)
	local v = tonumber(r[i])
	if v == nil then return d end
	return v
end

local function rnd(x) return math.floor(x + 0.5) end

local function plist(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		out[#out + 1] = { t = tonumber(a), v = tonumber(b) }
	end
	return out
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) }
	end
	return out
end

local function nlist(s)
	local out = {}
	for a in string.gmatch(tostring(s or ""), "(%-?%d+)") do out[#out + 1] = tonumber(a) end
	return out
end

function TL.T()
	local T = R.tl_t
	if T ~= nil then return T end
	T = { ok = false, g = {}, m = {}, bounds = {}, n = 0 }
	R.tl_t = T
	local gt, mt, pt = dtab("ship_talent_group"), dtab("ship_talent_mould"), dtab("ship_talent_param")
	if gt == nil or mt == nil or pt == nil then return T end
	local GC = { id = schema("ship_talent_group", "id", 1), first = schema("ship_talent_group", "first_mould", 4),
		unlock = schema("ship_talent_group", "unlock_lv", 5) }
	local MC = { id = schema("ship_talent_mould", "id", 1), max = schema("ship_talent_mould", "max_lv", 4),
		cond = schema("ship_talent_mould", "unlock_condition", 6) }
	local PC = { mould = schema("ship_talent_param", "need_mould", 2), lv = schema("ship_talent_param", "level", 3),
		need = schema("ship_talent_param", "level_need", 4), att = schema("ship_talent_param", "attribute_bonus", 5),
		cond = schema("ship_talent_param", "effective_condition", 6) }

	local groups = {}
	for k, row in pairs(gt) do
		local r = cells(row)
		if r ~= nil then
			local id = math.floor(ci(r, GC.id, tonumber(k) or 0))
			local first = tonumber(string.match(tostring(r[GC.first] or ""), "%-?%d+"))
			local terms = {}
			for part in string.gmatch(tostring(r[GC.unlock] or ""), "[^|]+") do
				local n = nlist(part)
				if n[1] == 1 and n[2] ~= nil then terms[#terms + 1] = { k = 1, a = n[2], b = 0 }
				elseif n[1] ~= nil and n[2] ~= nil and n[3] ~= nil then terms[#terms + 1] = { k = 2, a = n[2], b = n[3] } end
			end
			if id >= 1 and first ~= nil then groups[#groups + 1] = { id = id, first = first, terms = terms } end
		end
	end
	table.sort(groups, function(a, b) return a.id < b.id end)
	for i, g in ipairs(groups) do
		T.g[i] = g
		T.bounds[i] = g.first
	end

	for k, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local id = math.floor(ci(r, MC.id, tonumber(k) or 0))
			local cond = tostring(r[MC.cond] or "")
			local terms = {}
			for part in string.gmatch(cond, "[^|]+") do
				local n = nlist(part)
				if n[1] == 1 and n[2] ~= nil then terms[#terms + 1] = { k = 1, a = n[2], b = 0 }
				elseif n[1] ~= nil and n[2] ~= nil and n[3] ~= nil then terms[#terms + 1] = { k = 4, a = n[2], b = n[3] } end
			end
			local page = 1
			for i, b in ipairs(T.bounds) do if id >= b then page = i end end
			if id >= 1 then
				T.m[id] = { id = id, max = math.floor(ci(r, MC.max, 0)), root = (string.match(cond, "^%s*(%-?%d+)%s*$") == "3"),
					terms = terms, page = page, rows = {} }
			end
		end
	end

	for _, row in pairs(pt) do
		local r = cells(row)
		if r ~= nil then
			local mid, lv = ci(r, PC.mould, nil), ci(r, PC.lv, nil)
			local m = mid ~= nil and T.m[math.floor(mid)] or nil
			if m ~= nil and lv ~= nil then
				local s, p = 0, 0
				for _, t in ipairs(triples(r[PC.need])) do
					if t[1] == 1 then s = s + t[3] elseif t[1] == POINT_TYPE then p = p + t[3] end
				end
				local atts, conds, bonus = plist(r[PC.att]), nlist(r[PC.cond]), {}
				for o, a in ipairs(atts) do bonus[#bonus + 1] = { t = a.t, v = a.v, c = conds[o] or conds[#conds] or 0 } end
				m.rows[math.floor(lv)] = { s = s, p = p, bonus = bonus }
			end
		end
	end

	for id, m in pairs(T.m) do
		local n = 0
		while m.rows[n + 1] ~= nil and n < m.max do n = n + 1 end
		m.max = n
		T.n = T.n + 1
	end
	T.ok = T.n > 0 and #T.g >= 1
	return T
end

function TL.mould(id)
	local T = TL.T()
	return T.m[math.floor(tonumber(id) or -1)]
end

local function st()
	local a = S.tl
	if type(a) ~= "table" then a = { v = 0, l = {}, p = 0 }; S.tl = a end
	if type(a.l) ~= "table" then a.l = {} end
	a.p = math.max(0, math.floor(tn(a.p, 0)))
	return a
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.tl_auto == false) end
local function stats_on() return not (type(S.cfg) == "table" and S.cfg.tl_stats == false) end

local function lvl(mid)
	return math.floor(tn(st().l[tostring(math.floor(mid))], 0))
end

-- [FIX] GM FULL TALENT (thien phu): mo toan bo + max cap + du diem
function TL.full_on()
	return type(S) == "table" and type(S.cfg) == "table" and S.cfg.tl_full == true
end

-- [FIX FULL Thien phu] ------------------------------------------------------------------------
-- Ban cu: gm_full chi chay 1 lan luc bam nut. "Dat lai thien phu" (ship_talent_reset) trong luc FULL
-- xoa sach cap va khong ai nang lai; TAT FULL khong tra lai gi (cap + diem van bi giu max).
-- Nay: bat FULL = chup cap + diem cu (a.manual), nang MOI thien phu len max va giu du diem; TL.tick
-- kiem tra lai moi nhip nen sau khi dat lai van tu ve max; TAT FULL = khoi phuc.
local function tl_need_all(T)
	local n = T.need_all
	if n == nil then
		n = 0
		for _, m in pairs(T.m) do
			if m.max ~= nil and m.max > 0 then
				for i = 1, m.max do
					local row = m.rows[i]
					if row ~= nil then n = n + (tonumber(row.p) or 0) end
				end
			end
		end
		T.need_all = n
	end
	return n
end

local function tl_make_full(a)
	local T = TL.T()
	if not T.ok then return false end
	local changed = false
	if not a.full then
		local l = {}
		for k, v in pairs(a.l) do l[k] = v end
		a.manual, a.full = { l = l, p = a.p }, true
		changed = true
	end
	for id, m in pairs(T.m) do
		if m.max ~= nil and m.max > 0 then
			local k = m.key
			if k == nil then k = tostring(id); m.key = k end
			if tonumber(a.l[k]) ~= m.max then a.l[k] = m.max; changed = true end
		end
	end
	local need = tl_need_all(T)
	if a.p < need then a.p = math.floor(need); changed = true end
	return changed
end

local function tl_unfull(a)
	if not a.full then return false end
	local m = a.manual
	a.l = {}
	if type(m) == "table" then
		if type(m.l) == "table" then for k, v in pairs(m.l) do a.l[k] = v end end
		a.p = math.max(0, math.floor(tn(m.p, a.p)))
	end
	a.manual, a.full = nil, nil
	R.tl_clean = nil
	R.tl_last = "tat full: tra thien phu ve cap/diem tu nang"
	mark()
	return true
end

local function tl_full_pass(a)
	local changed
	if TL.full_on() then changed = tl_make_full(a) else changed = tl_unfull(a) end
	if changed then
		R.tl_grade = nil
		R.stat_dirty = true
		mark()
	end
	return changed
end

function TL.apply_now(e)
	if e == nil then return end
	local a = TL.ensure(e)
	if a == nil then return end
	local ok, err = pcall(tl_full_pass, a)
	if not ok then log("loi GM full talent:", tostring(err)) end
	local ok2, err2 = pcall(TL.rewrite, e)
	if not ok2 then log("loi rewrite talent:", tostring(err2)) end
end

function TL.clean()
	local T = TL.T()
	local a = st()
	local drop, put, n = {}, {}, 0
	for k, l in pairs(a.l) do
		local mid, v = tonumber(k), tonumber(l)
		local m = (mid ~= nil and mid == mid) and T.m[math.floor(mid)] or nil
		if m == nil or v == nil or v ~= v or v < 1 then
			drop[#drop + 1] = k
		else
			local nk, nv = tostring(m.id), math.min(m.max, math.floor(v))
			if k ~= nk or l ~= nv then
				drop[#drop + 1] = k
				put[#put + 1] = { nk, nv }
			end
		end
	end
	for _, k in ipairs(drop) do a.l[k] = nil; n = n + 1 end
	for _, kv in ipairs(put) do
		local cur = tonumber(a.l[kv[1]])
		if cur == nil or kv[2] > cur then a.l[kv[1]] = kv[2] end
	end
	if n > 0 then mark(); log("thien phu: sua", n, "muc khong hop le trong trang thai") end
	return n
end

function TL.ensure(e)
	local T = TL.T()
	if not T.ok then return nil end
	local a = st()
	if a.v ~= 1 then
		a.l = {}
		a.p = 0
		local rec = R.tl_rec
		if rec ~= nil then
			for k, l in pairs(rec.l) do a.l[k] = l end
			a.p = math.max(0, math.floor(tn(rec.p, 0)))
		end
		a.v = 1
		mark()
		local n = 0
		for _ in pairs(a.l) do n = n + 1 end
		log("thien phu: khoi tao tu ban ghi goc:", n, "thien phu, diem", fnum(a.p))
	end
	if not R.tl_clean then
		R.tl_clean = true
		TL.clean()
	end
	return a
end

function TL.used(levels)
	local T = TL.T()
	levels = levels or st().l
	local u = { 0, 0, 0, 0 }
	for k, l in pairs(levels) do
		local mid, v = tonumber(k), tonumber(l)
		local m = mid ~= nil and T.m[math.floor(mid)] or nil
		if m ~= nil and v ~= nil then
			for i = 1, math.min(v, m.max) do
				local row = m.rows[i]
				if row ~= nil and u[m.page] ~= nil then u[m.page] = u[m.page] + row.p end
			end
		end
	end
	return u
end

function TL.page_locked(pg, e, used)
	local T = TL.T()
	local g = T.g[pg]
	if g == nil then return true end
	local grade = tn(e.user_info.user_grade, 1)
	for _, t in ipairs(g.terms) do
		if t.k == 1 then
			if grade < t.a then return true end
		elseif (used[t.a] or 0) < t.b then
			return true
		end
	end
	return false
end

function TL.why_locked(e, mid)
	local T = TL.T()
	local m = T.m[mid]
	if m == nil then return ERR.generic end
	if m.root then
		if TL.page_locked(m.page, e, TL.used()) then return ERR_NOT_OPEN end
		return nil
	end
	local grade = tn(e.user_info.user_grade, 1)
	for _, t in ipairs(m.terms) do
		if t.k == 1 then
			if grade < t.a then return ERR_NOT_OPEN end
		elseif lvl(t.a) < t.b then
			return ERR_PREREQ
		end
	end
	return nil
end

function TL.cost(mid, from, to)
	local m = TL.mould(mid)
	local s, p = 0, 0
	if m == nil then return 0, 0 end
	for i = from + 1, to do
		local row = m.rows[i]
		if row ~= nil then s = s + row.s; p = p + row.p end
	end
	return s, p
end

local function state_of(levels)
	local ids = {}
	for k, l in pairs(levels) do
		local id, v = tonumber(k), tonumber(l)
		if id ~= nil and v ~= nil and v > 0 then ids[#ids + 1] = math.floor(id) end
	end
	table.sort(ids)
	if #ids == 0 then return "null" end
	local parts = {}
	for _, id in ipairs(ids) do parts[#parts + 1] = fint(id) .. ":" .. fint(levels[tostring(id)] or levels[id]) .. ",0" end
	return table.concat(parts, "|")
end

function TL.state_str() return state_of(st().l) end

local function blk_state() return "12559\r\n" .. TL.state_str() end
local function blk_points() return "6043\r\n5\r\n" .. fint(st().p) end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do
		b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3])
	end
	return table.concat(b, "\r\n")
end

function TL.in_sync_state(e)
	local cur = e.digital_talent_state_info
	if cur == nil or cur == "" then cur = "null" end
	if cur ~= TL.state_str() then return false end
	if R.tl_grade ~= tn(e.user_info.user_grade, 0) then return false end
	return type(e.digital_talent_page_is_lock) == "table" and type(e.digital_talent_already_add) == "table"
		and type(e.digital_talent_page_use_point_array) == "table"
end

function TL.in_sync_points(e)
	return tn(e.user_info.talent_point, -1) == st().p
end

function TL.write_points(e)
	if not TL.in_sync_points(e) then e.user_info.talent_point = fint(st().p) end
end

function TL.rewrite(e)
	local ok = call_parser("parse_digital_talent_state_info", { TL.state_str() })
	if not ok then

		local T = TL.T()
		e.digital_talent_state_info = (TL.state_str() ~= "null") and TL.state_str() or nil
		e.digital_talent_already_add = {}
		for k, l in pairs(st().l) do e.digital_talent_already_add[tostring(k)] = { level = tonumber(l), params = "0" } end
		local u = TL.used()
		e.digital_talent_page_use_point_array = { u[1], u[2], u[3], u[4] }
		local lock = {}
		for i = 1, 4 do lock[i] = T.g[i] ~= nil and TL.page_locked(i, e, u) or true end
		e.digital_talent_page_is_lock = lock
	end
	R.tl_grade = tn(e.user_info.user_grade, 0)
	TL.write_points(e)
	R.tl_rw = (R.tl_rw or 0) + 1
	if R.tl_rw <= 5 then log("thien phu: ghi lai trang thai vao game (lan", R.tl_rw, ")") end
end

function TL.floor_pts()
	if not auto_on() then return false end
	local a = st()
	if a.p < PTS_LOW then a.p = PTS_TOP; mark(); return true end
	return false
end

function TL.floor_silver()
	if not auto_on() then return false end
	if (S.silver or 0) < SILVER_LOW then LS.money_set("silver", SILVER_TOP); return true end
	return false
end

local ZERO = { f = { 0, 0 }, p = { 0, 0 }, spec = {} }

local function place_of(e, sid)
	local f = e.formetion
	if type(f) ~= "table" then return 0 end
	for i = 2, 7 do
		local v = f[i]
		if v ~= nil and tostring(v) == sid then return (i <= 4) and 1 or 2 end
	end
	return 0
end

local function formation_list(e)
	local out = {}
	if type(e.formetion) ~= "table" or type(e.user_ship) ~= "table" then return out end
	for i = 2, 7 do
		local v = e.formetion[i]
		if v ~= nil then
			v = tostring(v)
			if v ~= "0" and v ~= "" and type(e.user_ship[v]) == "table" then out[#out + 1] = v end
		end
	end
	return out
end

local function plain_hero(ship)
	local ct = tonumber(ship.captain_type)
	return ct == nil or (ct ~= 0 and ct ~= 2 and ct ~= 3)
end

function TL.bonus(levels, place, camp)
	local T = TL.T()
	local out = { f = { 0, 0 }, p = { 0, 0 }, spec = {} }
	for k, l in pairs(levels) do
		local mid, lv = tonumber(k), tonumber(l)
		local m = mid ~= nil and T.m[math.floor(mid)] or nil
		local row = (m ~= nil and lv ~= nil and lv >= 1) and m.rows[math.min(math.floor(lv), m.max)] or nil
		if row ~= nil then
			for _, b in ipairs(row.bonus) do
				local c = b.c
				if c == 0 or (c == 1 and place == 1) or (c == 2 and place == 2) or (c == 3 and camp == 1)
					or (c == 4 and camp == 3) or (c == 5 and camp == 2) then
					local t, v = b.t, b.v
					if t == 0 then out.f[1] = out.f[1] + v
					elseif t == 1 then out.f[2] = out.f[2] + v
					elseif t == 4 then out.p[1] = out.p[1] + v
					elseif t == 5 then out.p[2] = out.p[2] + v
					elseif PASS[t] then out.spec[t] = (out.spec[t] or 0) + v end
				end
			end
		end
	end
	return out
end

local function camp_of(tid)
	if tid == nil then return 0 end
	return math.floor(mnum(tid, "camp_preference", 0) or 0)
end

local function now_base(e, sid, tid, is_rec)
	local camp = camp_of(tid)
	local now = TL.bonus(st().l, place_of(e, sid), camp)
	local base = ZERO
	local rec = R.tl_rec
	if is_rec and rec ~= nil then base = TL.bonus(rec.l, rec.place[sid] or 0, camp) end
	return now, base
end

local function differs(now, base)
	for i = 1, 2 do
		if math.abs(now.f[i] - base.f[i]) > 1e-9 or math.abs(now.p[i] - base.p[i]) > 1e-9 then return true end
	end
	for t, v in pairs(now.spec) do
		if math.abs(v - (base.spec[t] or 0)) > 1e-9 then return true end
	end
	for t, v in pairs(base.spec) do
		if now.spec[t] == nil and math.abs(v) > 1e-9 then return true end
	end
	return false
end

function TL.differs(e, sid, tid, is_rec)
	if S == nil or type(S.tl) ~= "table" or S.tl.v ~= 1 or not stats_on() then return false end
	local now, base = now_base(e, sid, tid, is_rec)
	return differs(now, base)
end

function TL.adjust(sid, tid, pn, spec, is_rec)
	if S == nil or type(S.tl) ~= "table" or S.tl.v ~= 1 or not stats_on() then return end
	local e = ED()
	if e == nil or type(pn) ~= "table" then return end
	local T = R.tl_t
	if T == nil or not T.ok then return end
	local ok, err = pcall(function()
		local now, base = now_base(e, sid, tid, is_rec)
		if not differs(now, base) then return end
		for i = 1, 2 do
			local x = pn[i]
			if type(x) == "number" then
				local scale = 1 + base.p[i] / 100
				local add = (now.f[i] - base.f[i]) + (x / scale) * ((now.p[i] - base.p[i]) / 100)
				pn[i] = math.max(0, rnd(x + add))
			end
		end
		if type(spec) == "table" then
			for t, v in pairs(now.spec) do spec[t] = (spec[t] or 0) + v - (base.spec[t] or 0) end
			for t, v in pairs(base.spec) do
				if now.spec[t] == nil then spec[t] = (spec[t] or 0) - v end
			end
		end
	end)
	if not ok then
		R.tl_errs = (R.tl_errs or 0) + 1
		if R.tl_errs <= 5 then log("loi chi so thien phu:", tostring(err)) end
	end
end

local function queue_list(list)
	local q = R.tl_queue
	if q == nil or q.pos > #q.list then q = { list = {}, pos = 1, seen = {} }; R.tl_queue = q end
	for _, sid in ipairs(list) do
		if not q.seen[sid] then q.seen[sid] = true; q.list[#q.list + 1] = sid; q.cards = nil end
	end
end

-- [FIX full: the Combo Card] Chi so cua the phu thuoc suc chien (hero_fight) cua tuong ngoi trong o.
-- Neu the duoc tinh TRUOC tuong thi doc phai so cu -> bat/tat FULL o module khac de lai the lech
-- (khi nhay len, khi nhay xuong tuy thu tu duyet bang). Moi luot tinh lai xong thi tinh lai rieng
-- cac the them mot lan o CUOI (luc tuong da xong), nen ket qua khong con phu thuoc thu tu.
local function card_sids(e)
	local out = {}
	local cb = LS._cb
	if cb == nil or type(cb.any) ~= "function" or type(e) ~= "table" or type(e.user_ship) ~= "table" then return out end
	for sid, s in pairs(e.user_ship) do
		if type(s) == "table" and tonumber(sid) ~= nil and plain_hero(s) then
			local ok, yes = pcall(cb.any, sid)
			if ok and yes then out[#out + 1] = sid end
		end
	end
	table.sort(out, function(a, b) return (tonumber(a) or 0) < (tonumber(b) or 0) end)
	return out
end

local function queue_cards_last(e)
	local cards = card_sids(e)
	if #cards == 0 then return false end
	local q = { list = {}, pos = 1, seen = {}, cards = true }
	for _, sid in ipairs(cards) do q.seen[sid] = true; q.list[#q.list + 1] = sid end
	R.tl_queue = q
	return true
end

local function queue_all(e)
	local list = {}
	for _, sid in ipairs(formation_list(e)) do list[#list + 1] = sid end
	for sid, s in pairs(e.user_ship) do
		if type(s) == "table" and tonumber(sid) ~= nil and plain_hero(s) then list[#list + 1] = sid end
	end
	R.tl_queue = nil
	queue_list(list)
end

local function refresh_one(e, sid)
	local ship = e.user_ship[sid]
	if type(ship) ~= "table" or not plain_hero(ship) then return false end
	local tid = tonumber(ship.ship_template_id)
	if S.heroes[sid] ~= nil then
		return apply_hero(e, sid)
	end
	if S.mods[sid] == nil then
		if tid == nil or not TL.differs(e, sid, tid, true) then return false end
		commit_hero(e, sid, {})
	end
	return apply_hero(e, sid)
end

local function pump_queue(e)
	local q = R.tl_queue
	if q == nil then return 0 end
	local n = 0
	while q.pos <= #q.list and n < BATCH do
		local sid = q.list[q.pos]
		q.pos = q.pos + 1
		local ok, res = pcall(refresh_one, e, sid)
		if ok and res then n = n + 1
		elseif not ok then
			R.tl_errs = (R.tl_errs or 0) + 1
			if R.tl_errs <= 5 then log("loi tinh lai tuong (thien phu):", tostring(res)) end
		end
	end
	q.done = (q.done or 0) + n
	if q.pos > #q.list then
		R.tl_queue = nil
		if not q.cards and (q.done or 0) > 0 then queue_cards_last(e) end
	end
	return n
end

local function refresh_blocks(e, blocks)
	if not stats_on() then return end
	for _, sid in ipairs(formation_list(e)) do
		local ship = e.user_ship[sid]
		if plain_hero(ship) then
			local tid = tonumber(ship.ship_template_id)
			if S.heroes[sid] ~= nil or S.mods[sid] ~= nil or (tid ~= nil and TL.differs(e, sid, tid, true)) then
				local F = commit_hero(e, sid, {})
				if F ~= nil then
					apply_hero(e, sid)
					push_all(blocks, blk_ship(ship, F))
					push_all(blocks, blk_fight(e, sid, F))
				end
			end
		end
	end
end

local function form_sig(e)
	local f = {}
	for i = 2, 7 do f[#f + 1] = tostring(e.formetion and e.formetion[i] or "0") end
	return table.concat(f, ",")
end

local function lvl_sig()
	local ids = {}
	for k, l in pairs(st().l) do
		local id = tonumber(k)
		if id ~= nil then ids[#ids + 1] = id end
	end
	table.sort(ids)
	local p = {}
	for _, id in ipairs(ids) do p[#p + 1] = fint(id) .. "=" .. fint(lvl(id)) end
	return table.concat(p, ",")
end

function TL.watch(e)
	local ls, fs = lvl_sig(), form_sig(e)
	if R.tl_sig_l == nil then

		R.tl_sig_l, R.tl_sig_f = ls, fs
		R.tl_form_prev = formation_list(e)
		if stats_on() then queue_all(e) end
		return
	end
	local list = nil
	if ls ~= R.tl_sig_l then
		R.tl_sig_l, R.tl_sig_f = ls, fs
		R.tl_form_prev = formation_list(e)
		if stats_on() then queue_all(e) end
		return
	end
	if fs ~= R.tl_sig_f then
		R.tl_sig_f = fs
		list = {}
		for _, sid in ipairs(R.tl_form_prev or {}) do list[#list + 1] = sid end
		R.tl_form_prev = formation_list(e)
		for _, sid in ipairs(R.tl_form_prev) do list[#list + 1] = sid end
		if stats_on() then queue_list(list) end
	end
end

function TL.on_world(e)
	R.tl_t = nil
	R.tl_sig_l, R.tl_sig_f, R.tl_queue, R.tl_form_prev, R.tl_hint, R.tl_grade, R.tl_clean = nil, nil, nil, nil, nil, nil, nil
	local rec = { l = {}, place = {}, p = 0, ptstr = "0" }
	local T = TL.T()
	local add = e.digital_talent_already_add
	if type(add) == "table" then
		for k, v in pairs(add) do
			local mid = tonumber(k)
			local lv = type(v) == "table" and tonumber(v.level) or nil
			local m = mid ~= nil and T.m[math.floor(mid)] or nil
			if m ~= nil and lv ~= nil and lv >= 1 then rec.l[tostring(math.floor(mid))] = math.min(m.max, math.floor(lv)) end
		end
	end
	if type(e.user_info) == "table" then
		rec.p = math.max(0, math.floor(tn(e.user_info.talent_point, 0)))
		rec.ptstr = tostring(e.user_info.talent_point or "0")
	end
	for i = 2, 7 do
		local v = type(e.formetion) == "table" and e.formetion[i] or nil
		if v ~= nil and tostring(v) ~= "0" and tostring(v) ~= "" then rec.place[tostring(v)] = (i <= 4) and 1 or 2 end
	end
	R.tl_rec = rec
	TL.ensure(e)
end

function TL.restore(e)
	if type(e) ~= "table" then return end
	local rec = R.tl_rec
	if rec ~= nil then
		call_parser("parse_digital_talent_state_info", { state_of(rec.l) })
		if type(e.user_info) == "table" then e.user_info.talent_point = rec.ptstr end
	end
	R.tl_grade = nil
	R.tl_sig_l, R.tl_sig_f, R.tl_queue, R.tl_form_prev, R.tl_clean = nil, nil, nil, nil, nil
end

function TL.tick(e)
	if S == nil or not R.ready or type(e.user_info) ~= "table" then return end
	local a = TL.ensure(e)
	if a == nil then return end
	if auto_on() then TL.floor_pts() end
	if a.full or TL.full_on() then tl_full_pass(a) end
	if not TL.in_sync_state(e) then TL.rewrite(e) end
	TL.write_points(e)
	TL.watch(e)
	if R.tl_queue ~= nil then pump_queue(e) end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if TL.ensure(e) == nil then error("khong co bang thien phu") end
	return e
end

function TL.hint(e)
	if R.tl_hint then return end
	R.tl_hint = true
	local T = TL.T()
	local grade = tn(e.user_info.user_grade, 1)
	local need = nil
	for i = 2, #T.g do
		for _, t in ipairs(T.g[i].terms) do
			if t.k == 1 and grade < t.a and (need == nil or t.a < need) then need = t.a end
		end
	end
	if need ~= nil then
		toast("LS Thien phu: cay tiep theo can cap nguoi choi " .. fint(need) .. " (hien Lv" .. fint(grade) .. ") - dung nut Cap nguoi choi trong bang GM", 10)
	end
end

local function finish(e, seq, name, blocks)
	if auto_on() then TL.floor_pts(); TL.floor_silver() end
	TL.write_points(e)

	local out = { blk_points(), blk_state() }
	for _, b in ipairs(blocks) do out[#out + 1] = b end
	refresh_blocks(e, out)
	R.tl_sig_l, R.tl_sig_f = lvl_sig(), form_sig(e)
	R.tl_form_prev = formation_list(e)
	if stats_on() then queue_all(e) end
	mark()
	LS.save_state(true)
	return reply(seq, name, out)
end

function TL.h_init(p, seq)
	local e = ctx()
	if auto_on() then TL.floor_pts(); TL.floor_silver() end
	TL.write_points(e)
	TL.hint(e)
	stat_inc("tl_inits")
	mark()
	return reply(seq, "ship_talent_init", { blk_points(), blk_state() })
end

function TL.h_level(p, seq)
	local name = "ship_talent_level_up"
	local e = ctx()
	local mid = tonumber(p[1])
	local m = mid ~= nil and TL.mould(mid) or nil
	if m == nil then return err_reply(seq, name, "LS_thien_phu_khong_ton_tai", ERR.generic) end
	mid = m.id
	local times = tonumber(p[2])
	if times == nil or times < 1 then times = 1 end
	times = math.floor(times)
	local cur = lvl(mid)
	if cur >= m.max then return err_reply(seq, name, "LS_thien_phu_da_toi_da", ERR_MAX) end
	local why = TL.why_locked(e, mid)
	if why ~= nil then return err_reply(seq, name, "LS_thien_phu_chua_mo", why) end
	local n = math.min(times, m.max - cur)
	local cs, cp = TL.cost(mid, cur, cur + n)
	local a = st()
	if auto_on() then
		if (S.silver or 0) < cs then LS.money_set("silver", cs + SILVER_TOP) end
		if a.p < cp then a.p = cp + PTS_TOP end
	else
		if (S.silver or 0) < cs then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
		if a.p < cp then return err_reply(seq, name, "LS_khong_du_diem_thien_phu", ERR.items) end
	end
	if cs > 0 then LS.money_spend("silver", cs) end
	a.p = a.p - cp
	a.l[tostring(mid)] = cur + n
	stat_inc("tl_levels", n)
	R.tl_last = "thien phu " .. fint(mid) .. ": cap " .. fint(cur) .. " -> " .. fint(cur + n)
	log("thien phu:", R.tl_last, "| ton", fnum(cs), "bac,", fnum(cp), "diem")
	return finish(e, seq, name, {})
end

function TL.h_reset(p, seq)
	local name = "ship_talent_reset"
	local e = ctx()
	local a = st()
	local u = TL.used()
	local total = u[1] + u[2] + u[3] + u[4]
	local any = false
	for _ in pairs(a.l) do any = true; break end
	if not any then return err_reply(seq, name, "LS_khong_co_thien_phu_de_dat_lai", ERR.generic) end
	a.l = {}
	a.p = a.p + total
	stat_inc("tl_resets")
	R.tl_last = "dat lai: hoan " .. fint(total) .. " diem"
	log("thien phu:", R.tl_last)
	return finish(e, seq, name, { blk_reward({ { -1, POINT_TYPE, total } }) })
end

function TL.counts()
	local a = S ~= nil and S.tl or nil
	if type(a) ~= "table" or a.v ~= 1 then return nil end
	local n, sum = 0, 0
	for _, l in pairs(a.l) do n = n + 1; sum = sum + (tonumber(l) or 0) end
	return n, sum
end

function TL.dump_line()
	local n, sum = TL.counts()
	if n == nil then return "[LS thien phu] chua khoi tao" end
	local qn = 0
	if R.tl_queue ~= nil then qn = #R.tl_queue.list - R.tl_queue.pos + 1 end
	return "[LS thien phu] " .. n .. " thien phu (tong cap " .. sum .. ") | diem " .. fnum(S.tl.p)
		.. " | full " .. (TL.full_on() and "BAT" or "TAT")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | cong chi so " .. (stats_on() and "BAT" or "TAT")
		.. " | hang doi " .. qn .. (R.tl_last ~= nil and (" | cuoi: " .. R.tl_last) or "")
		.. " | ghi lai " .. tostring(R.tl_rw or 0) .. " lan"
end

function TL.reset()
	S.tl = nil
	R.tl_clean = nil
	mark()
end

TL.queue_all = queue_all
TL.queue_list = queue_list
TL.refresh_blocks = refresh_blocks
LS._tl = TL

end
init_tl()
end

do
local function init_al()

local AL = {}
local ID_BASE = 9200000
local ESS_LOW, ESS_TOP = 2000000, 20000000
local SIL_LOW, SIL_TOP = 300000000, 1000000000
local MAX_LV = 120
local TIERS = 3
local ESS_TYPE = 67
local PASS = { [33] = true, [34] = true, [85] = true }
local DEF_C35 = { [0] = 1, 2, 3, 4, 5, 7, 10 }
local DEF_C36 = { [0] = 1, 2, 3, 4, 5, 12, 18 }
local DEF_UNLOCK = { { 30, 30, 30, 30 }, { 31, 31, 32, 32, 33, 33 }, { 34, 34, 35, 35, 35, 36, 36, 36 } }

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function ci(r, i, d)
	local v = tonumber(r[i])
	if v == nil then return d end
	return v
end

local function plist(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		out[#out + 1] = { t = tonumber(a), v = tonumber(b) }
	end
	return out
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) }
	end
	return out
end

function AL.T()
	local T = R.al_t
	if T ~= nil then return T end
	T = { ok = false, mm = {}, ids = {}, par = {}, mx = {}, mp = {}, c35 = DEF_C35, c36 = DEF_C36, r_ess = 1, r_sil = 0.8,
		maxsel = 200, unlock = DEF_UNLOCK, claim = { { ESS_TYPE, -1, 50 }, { 1, -1, 10000 } } }
	R.al_t = T
	local mt, pt, xt, xp = dtab("ship_metal_mould"), dtab("ship_metal_param"), dtab("ship_matrix_mould"), dtab("ship_matrix_param")
	if mt == nil or pt == nil or xt == nil or xp == nil then return T end

	local MC = { id = schema("ship_metal_mould", "id", 1), name = schema("ship_metal_mould", "name", 2), head = schema("ship_metal_mould", "head", 3),
		mt = schema("ship_metal_mould", "mould_type", 4), at = schema("ship_metal_mould", "add_type", 5), q = schema("ship_metal_mould", "quality", 6) }
	for k, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local id = ci(r, MC.id, tonumber(k))
			local head, mty, at, q = ci(r, MC.head, nil), ci(r, MC.mt, nil), ci(r, MC.at, nil), ci(r, MC.q, nil)
			if id ~= nil and head ~= nil and mty ~= nil and at ~= nil and q ~= nil then
				id = math.floor(id)
				T.mm[id] = { id = id, head = math.floor(head), mt = math.floor(mty), at = math.floor(at), q = math.floor(q) }
			end
		end
	end
	for id in pairs(T.mm) do T.ids[#T.ids + 1] = id end
	table.sort(T.ids)

	local PC = { group = schema("ship_metal_param", "group_id", 2), grade = schema("ship_metal_param", "metal_grade", 3),
		rank = schema("ship_metal_param", "metal_level", 4), add = schema("ship_metal_param", "metal_add", 5),
		exp = schema("ship_metal_param", "next_need_exp", 6), gold = schema("ship_metal_param", "next_level_gold", 7) }
	for _, row in pairs(pt) do
		local r = cells(row)
		if r ~= nil then
			local g, lv, rk = ci(r, PC.group, nil), ci(r, PC.grade, nil), ci(r, PC.rank, nil)
			if g ~= nil and lv ~= nil and rk ~= nil then
				g, lv, rk = math.floor(g), math.floor(lv), math.floor(rk)
				local a = T.par[g]
				if a == nil then a = {}; T.par[g] = a end
				local b = a[lv]
				if b == nil then b = {}; a[lv] = b end
				b[rk] = { exp = ci(r, PC.exp, -1), gold = ci(r, PC.gold, -1), add = plist(r[PC.add]) }
			end
		end
	end

	local XC = { id = schema("ship_matrix_mould", "id", 1), need = schema("ship_matrix_mould", "metal_need", 3), group = schema("ship_matrix_mould", "group_id", 4) }
	for k, row in pairs(xt) do
		local r = cells(row)
		if r ~= nil then
			local id, gid = ci(r, XC.id, tonumber(k)), ci(r, XC.group, nil)
			if id ~= nil and gid ~= nil then
				local need, total = {}, 0
				for a, b in string.gmatch(tostring(r[XC.need] or ""), "(%d+)%s*,%s*(%d+)") do
					need[#need + 1] = { mt = tonumber(a), n = tonumber(b) }
					total = total + tonumber(b)
				end
				if #need > 0 then
					id = math.floor(id)
					T.mx[id] = { id = id, gid = math.floor(gid), need = need, total = total }
				end
			end
		end
	end
	local YC = { group = schema("ship_matrix_param", "group_id", 2), q = schema("ship_matrix_param", "quality", 3), add = schema("ship_matrix_param", "add", 4) }
	for _, row in pairs(xp) do
		local r = cells(row)
		if r ~= nil then
			local g, q = ci(r, YC.group, nil), ci(r, YC.q, nil)
			if g ~= nil and q ~= nil then
				g, q = math.floor(g), math.floor(q)
				local a = T.mp[g]
				if a == nil then a = { top = 0 }; T.mp[g] = a end
				a[q] = plist(r[YC.add])
				if q > a.top then a.top = q end
			end
		end
	end

	local c35, c36 = cfg_pairs("ship_config", 35), cfg_pairs("ship_config", 36)
	if c35 ~= nil then T.c35 = c35 end
	if c36 ~= nil then T.c36 = c36 end
	local s37 = cfg_str("ship_config", 37)
	if s37 ~= nil then
		local a, b = string.match(s37, "([%d%.]+)%s*,%s*([%d%.]+)")
		if a ~= nil then T.r_ess, T.r_sil = tonumber(a) or 1, tonumber(b) or 0.8 end
	end
	local s38 = tonumber(cfg_str("ship_config", 38))
	if s38 ~= nil and s38 >= 1 then T.maxsel = math.floor(s38) end
	local s39 = cfg_str("ship_config", 39)
	if s39 ~= nil then
		local un, ti = {}, 0
		for part in string.gmatch(s39, "[^!]+") do
			ti = ti + 1
			local l = {}
			for a, b in string.gmatch(part, "(%d+)%s*:%s*(%d+)") do l[tonumber(a)] = tonumber(b) end
			un[ti] = l
		end
		if ti == TIERS then T.unlock = un end
	end
	local t40 = triples(cfg_str("ship_config", 40))
	if #t40 > 0 then T.claim = t40 end
	local nmx, npar = 0, 0
	for _ in pairs(T.mx) do nmx = nmx + 1 end
	for _ in pairs(T.par) do npar = npar + 1 end
	T.ok = #T.ids > 0 and nmx > 0 and npar > 0
	return T
end

local function st()
	local a = S.al
	if type(a) ~= "table" then a = { v = 0, nid = ID_BASE, ess = 0, m = {}, eq = {}, mr = {} }; S.al = a end
	if type(a.m) ~= "table" then a.m = {} end
	if type(a.eq) ~= "table" then a.eq = {} end
	if type(a.mr) ~= "table" then a.mr = {} end
	a.nid = math.max(ID_BASE, math.floor(tn(a.nid, ID_BASE)))
	a.ess = math.max(0, math.floor(tn(a.ess, 0)))
	return a
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.al_auto == false) end
local function stats_on() return not (type(S.cfg) == "table" and S.cfg.al_stats == false) end

local function invalidate()
	R.al_idx, R.al_own = nil, nil
end

local function find(id)
	id = tonumber(id)
	if id == nil then return nil end
	local ix = R.al_idx
	if ix == nil then
		ix = {}
		for _, m in ipairs(st().m) do ix[m.id] = m end
		R.al_idx = ix
	end
	return ix[math.floor(id)]
end

local function owners()
	local mp = R.al_own
	if mp == nil then
		mp = {}
		for sid, tiers in pairs(st().eq) do
			if type(tiers) == "table" then
				for t, slots in pairs(tiers) do
					if type(slots) == "table" then
						for p, id in pairs(slots) do
							local n = tonumber(id)
							if n ~= nil then mp[n] = { sid = tonumber(sid), t = tonumber(t), p = tonumber(p) } end
						end
					end
				end
			end
		end
		R.al_own = mp
	end
	return mp
end

local function skey(sid) return tostring(math.floor(tonumber(sid) or -1)) end

local function new_metal(mm)
	local a = st()
	local m = { id = a.nid, mm = mm, lv = 1, rk = 0, x = 0, cs = 0, ce = 0 }
	a.nid = a.nid + 1
	a.m[#a.m + 1] = m
	invalidate()
	return m
end

function AL.give(e, mm, n)
	mm = math.floor(tonumber(mm) or -1)
	local T = AL.T()
	if not T.ok or T.mm[mm] == nil then return 0 end
	if e ~= nil and AL.ensure(e) == nil then return 0 end
	local k = 0
	for _ = 1, math.max(1, math.floor(tn(n, 1))) do new_metal(mm); k = k + 1 end
	mark()
	if e ~= nil then pcall(AL.rewrite, e) end
	return k
end
function AL.give_ess(e, n)
	if e ~= nil and AL.ensure(e) == nil then return false end
	local a = st()
	a.ess = a.ess + math.max(0, math.floor(tn(n, 0)))
	mark()
	if e ~= nil then pcall(AL.rewrite, e) end
	return true
end

local function prow(m)
	local T = AL.T()
	local mm = T.mm[m.mm]
	if mm == nil then return nil end
	local g = T.par[mm.at]
	local a = g ~= nil and g[m.lv] or nil
	return a ~= nil and a[m.rk] or nil, mm
end

-- [FIX] GM FULL Z ALLOY (hop kim): moi hop kim max cap + max pham, du nguyen lieu
function AL.full_on()
	return type(S) == "table" and type(S.cfg) == "table" and S.cfg.al_full == true
end

-- [FIX FULL Hop kim] ------------------------------------------------------------------------
-- Ban cu: gm_full chi nang cac vien DANG CO luc bam nut. Vien du phong moi (AL.restock tao them
-- khi ban gan 1 vien, hoac GM tang them) luon la cap 1 / bac 0 nen kho khong bao gio "full" that su,
-- va TAT FULL khong tra lai gi. Nay: bat FULL = chup cap/bac cu cua tung vien (a.manual), nang MOI
-- vien (ke ca vien sinh them sau do - AL.tick/fin goi lai) len cap + bac cao nhat co trong bang
-- du lieu; TAT FULL = khoi phuc tung vien (vien sinh ra trong luc FULL ve cap 1).
local function al_top(m)
	local T = AL.T()
	local mm = T.mm[m.mm]
	if mm == nil then return nil end
	local cache = T.top
	if cache == nil then cache = {}; T.top = cache end
	local c = cache[mm.at]
	if c == nil then
		c = false
		local g = T.par[mm.at]
		if g ~= nil then
			-- cap cao nhat THAT SU co du lieu (khong dung o lo hong dau tien), roi bac cao nhat cua cap do
			local lv = 0
			for l in pairs(g) do
				if type(l) == "number" and l <= MAX_LV and l > lv then lv = l end
			end
			local rk = 0
			if lv > 0 and type(g[lv]) == "table" then
				for r in pairs(g[lv]) do
					if type(r) == "number" and r > rk then rk = r end
				end
			end
			if lv > 0 then c = { lv, rk } end
		end
		cache[mm.at] = c
	end
	if c == false then return nil end
	return c[1], c[2]
end

local function al_make_full(a)
	if not AL.T().ok then return false end
	local changed = false
	if not a.full then
		local snap = {}
		for _, m in ipairs(a.m) do
			if type(m) == "table" then snap[tostring(m.id)] = { lv = m.lv, rk = m.rk, x = m.x } end
		end
		a.manual, a.full = snap, true
		changed = true
	end
	for _, m in ipairs(a.m) do
		if type(m) == "table" then
			local lv, rk = al_top(m)
			if lv ~= nil and (m.lv ~= lv or m.rk ~= rk or m.x ~= 0) then
				m.lv, m.rk, m.x = lv, rk, 0
				changed = true
			end
		end
	end
	-- nguyen lieu (tinh hoa) de khoi thieu khi nguoi choi nau/hoi them
	if (tonumber(a.ess) or 0) < 999999 then a.ess = 999999; mark() end
	return changed
end

local function al_unfull(a)
	if not a.full then return false end
	local snap = a.manual
	for _, m in ipairs(a.m) do
		if type(m) == "table" then
			local s = type(snap) == "table" and snap[tostring(m.id)] or nil
			if type(s) == "table" then
				m.lv = math.max(1, math.floor(tn(s.lv, 1)))
				m.rk = math.max(0, math.floor(tn(s.rk, 0)))
				m.x = math.max(0, math.floor(tn(s.x, 0)))
			else
				m.lv, m.rk, m.x = 1, 0, 0
			end
		end
	end
	a.manual, a.full = nil, nil
	R.al_last = "tat full: tra hop kim ve cap/bac tu nang"
	mark()
	return true
end

-- ap/bo FULL len kho hien tai; tra ve true neu cap/bac cua vien nao do da doi
local function al_full_pass(a, e)
	local changed
	if AL.full_on() then changed = al_make_full(a) else changed = al_unfull(a) end
	if changed then
		R.stat_dirty = true
		mark()
		-- Tuong LS (S.heroes) khong nam trong S.mods nen stat_dirty/heroes_assert KHONG tinh lai ho:
		-- phai dua cac tuong dang gan hop kim vao hang doi tinh lai cua Thien phu (TL.tick bom dan).
		local tl = LS._tl
		if e ~= nil and tl ~= nil and tl.queue_list ~= nil then
			local list = {}
			for sid in pairs(a.eq) do list[#list + 1] = sid end
			if #list > 0 then pcall(tl.queue_list, list) end
		end
	end
	return changed
end

function AL.apply_now(e)
	if e == nil then return end
	local ok, err = pcall(AL.tick, e)
	if not ok then log("loi GM full alloy:", tostring(err)) end
end

function AL.step(m)
	local row, mm = prow(m)
	if row == nil then return "max", 0 end
	local T = AL.T()
	if row.exp ~= nil and row.exp > 0 then
		local g = T.par[mm.at]
		local nx = g[m.lv + 1]
		if m.lv < MAX_LV and nx ~= nil and nx[m.rk] ~= nil then
			return "lv", math.max(0, math.floor(row.exp * (T.c35[mm.q] or 1) - m.x + 0.5))
		end
		return "max", 0
	end
	if row.gold ~= nil and row.gold > 0 then
		local g = T.par[mm.at]
		local nx = g[m.lv]
		if nx ~= nil and nx[m.rk + 1] ~= nil then
			return "rank", math.floor(row.gold * (T.c36[mm.q] or 1) + 0.5)
		end
	end
	return "max", 0
end

local function metal_adds(m)
	local row, mm = prow(m)
	if row == nil then return {} end
	local T = AL.T()
	local c = T.c35[mm.q] or 1
	local out = {}
	for _, a in ipairs(row.add) do out[#out + 1] = { t = a.t, v = a.v * c } end
	return out
end

local function add_into(out, t, v)
	if t >= 0 and t <= 3 then out[t + 1] = out[t + 1] + v
	elseif PASS[t] then out.spec[t] = (out.spec[t] or 0) + v end
end

local function ship_list(tid)
	local out = {}
	if tid == nil then return out end
	local s = mstr(tid, "sign_msg")
	for w in string.gmatch(tostring(s or ""), "%d+") do out[#out + 1] = tonumber(w) end
	return out
end

function AL.matrix_of(list, tid)
	local T = AL.T()
	local ids = ship_list(tid)
	if #ids == 0 or #list == 0 then return nil end
	local by = {}
	for _, m in ipairs(list) do
		local mm = T.mm[m.mm]
		if mm ~= nil then
			local a = by[mm.mt]
			if a == nil then a = {}; by[mm.mt] = a end
			a[#a + 1] = mm.q
		end
	end
	for _, a in pairs(by) do table.sort(a, function(x, y) return x > y end) end
	local best, bq, bk = nil, 0, nil
	for _, mid in ipairs(ids) do
		local x = T.mx[mid]
		if x ~= nil then
			local ok, minq = true, 99
			for _, nd in ipairs(x.need) do
				local a = by[nd.mt]
				if a == nil or #a < nd.n then ok = false; break end
				for k = 1, nd.n do if a[k] < minq then minq = a[k] end end
			end
			if ok then
				local key = x.total * 1000000 + x.gid * 1000 - mid
				if bk == nil or key > bk then
					local mp = T.mp[x.gid]
					local q = math.max(0, minq)
					if mp ~= nil then q = math.min(q, mp.top) end
					best, bq, bk = mid, q, key
				end
			end
		end
	end
	return best, bq
end

local function tier_metals(key, ts)
	local out = {}
	local eq = st().eq[key]
	local slots = eq ~= nil and eq[ts] or nil
	if type(slots) ~= "table" then return out end
	local ps = {}
	for p in pairs(slots) do ps[#ps + 1] = tonumber(p) or 0 end
	table.sort(ps)
	for _, p in ipairs(ps) do
		local m = find(slots[tostring(p)])
		if m ~= nil then out[#out + 1] = m end
	end
	return out
end

function AL.contrib(sid, tid)
	local out = { 0, 0, 0, 0, spec = {} }
	if not stats_on() then return out end
	local key = skey(sid)
	local eq = st().eq[key]
	if type(eq) ~= "table" then return out end
	local T = AL.T()
	for ti = 1, TIERS do
		local list = tier_metals(key, tostring(ti))
		for _, m in ipairs(list) do
			for _, a in ipairs(metal_adds(m)) do add_into(out, a.t, a.v) end
		end
		local mid, q = AL.matrix_of(list, tid)
		if mid ~= nil then
			local mp = T.mp[T.mx[mid].gid]
			local add = mp ~= nil and mp[q] or nil
			if add ~= nil then
				for _, a in ipairs(add) do add_into(out, a.t, a.v) end
			end
		end
	end
	return out
end

function AL.delta(sid)
	local out = { 0, 0, 0, 0, spec = {} }
	if S == nil or type(S.al) ~= "table" or S.al.v ~= 1 then return out end
	local e = ED()
	local ship = (e ~= nil and type(e.user_ship) == "table") and e.user_ship[skey(sid)] or nil
	local tid = ship ~= nil and tonumber(ship.ship_template_id) or nil
	return AL.contrib(sid, tid)
end

-- [BOT RANDOM] Hop kim (Z Alloy) ngau nhien cho bot: moi tang chon 1 ma tran hop le cua tuong,
-- du vien (pham cao nhat cua tung loai, max cap/bac). Tra { hp, atk, def, spd, spec = {} } de cong vao bot.
function AL.bot_stats(tid, rnd)
	local out = { 0, 0, 0, 0, spec = {} }
	if not stats_on() then return out end
	local T = AL.T()
	if not T.ok then return out end
	local ids = ship_list(tid)
	if #ids == 0 then return out end
	local best = T.bot_best
	if best == nil then
		best = {}
		for _, id in ipairs(T.ids) do
			local mm = T.mm[id]
			local b = best[mm.mt]
			if b == nil or mm.q > b.q then
				best[mm.mt] = { q = mm.q, list = { id } }
			elseif mm.q == b.q then
				b.list[#b.list + 1] = id
			end
		end
		T.bot_best = best
	end
	for ti = 1, TIERS do
		local slots = 0
		for _ in pairs(T.unlock[ti] or {}) do slots = slots + 1 end
		local cand, any = {}, {}
		for _, mid in ipairs(ids) do
			local x = T.mx[mid]
			if x ~= nil then
				local ok = true
				for _, nd in ipairs(x.need) do
					if best[nd.mt] == nil then ok = false; break end
				end
				if ok then
					any[#any + 1] = mid
					if slots == 0 or x.total <= slots then cand[#cand + 1] = mid end
				end
			end
		end
		if #cand == 0 then cand = any end
		if #cand > 0 then
			local mid = cand[math.floor(rnd() * #cand) + 1]
			local x = T.mx[mid]
			local minq = 99
			for _, nd in ipairs(x.need) do
				local b = best[nd.mt]
				for _ = 1, nd.n do
					local id = b.list[math.floor(rnd() * #b.list) + 1]
					local m = { mm = id }
					local lv, rk = al_top(m)
					if lv ~= nil then
						m.lv, m.rk = lv, rk
						for _, a in ipairs(metal_adds(m)) do add_into(out, a.t, a.v) end
					end
					if b.q < minq then minq = b.q end
				end
			end
			local mp = T.mp[x.gid]
			if mp ~= nil then
				local q = math.min(math.max(0, minq), mp.top)
				for _, a in ipairs(mp[q] or {}) do add_into(out, a.t, a.v) end
			end
		end
	end
	return out
end

function AL.ship_alloy(sid, tid, settle)
	local key = skey(sid)
	local out = { mmi = {}, ma = {}, mr = {} }
	local a = st()
	local eq = a.eq[key]
	if type(eq) == "table" then
		for ti = 1, TIERS do
			local ts = tostring(ti)
			local slots = eq[ts]
			if type(slots) == "table" then
				local mm, any = {}, false
				for p, id in pairs(slots) do
					local n = tonumber(id)
					if n ~= nil and find(n) ~= nil then mm[tostring(p)] = n; any = true end
				end
				if any then
					out.mmi[ts] = mm
					local mid, q = AL.matrix_of(tier_metals(key, ts), tid)
					if mid ~= nil then
						out.ma[ts] = { [tostring(mid)] = q }
						if settle then
							local r = a.mr[key]
							if r == nil then r = {}; a.mr[key] = r end
							if r[tostring(mid)] == nil then r[tostring(mid)] = 0; mark() end
						end
					end
				end
			end
		end
	end
	local r = a.mr[key]
	if type(r) == "table" then
		for k, v in pairs(r) do out.mr[tostring(k)] = tonumber(v) or 0 end
	end
	return out
end

local function same_map(a, b)
	if type(a) ~= "table" then a = {} end
	if type(b) ~= "table" then b = {} end
	for k, v in pairs(a) do
		local w = b[k]
		if type(v) == "table" then
			if not same_map(v, w) then return false end
		elseif tonumber(v) ~= tonumber(w) then
			return false
		end
	end
	for k, w in pairs(b) do
		if a[k] == nil then
			if type(w) == "table" then
				if not same_map({}, w) then return false end
			else
				return false
			end
		end
	end
	return true
end

function AL.sync_ships(e)
	if type(e.user_ship) ~= "table" then return 0 end
	-- [FIX lag 7] sync_ships() duyet TOAN BO e.user_ship va goi AL.ship_alloy()
	-- cho tung tuong -> lap lai moi tick. Nay chi chay khi so tuong doi.
	local _ns = 0
	for _ in pairs(e.user_ship) do _ns = _ns + 1 end
	if R.al_ship_n == _ns and R.al_ship_ship == e.user_ship and not R.al_now then return 0 end
	R.al_ship_n, R.al_ship_ship = _ns, e.user_ship
	-- [FIX hop kim] R.al_now truoc day khong noi nao dat => gan/thao da xong (so tuong khong doi) thi
	-- ship.alloyMatrix + o thuong ma tran (a.mr) khong bao gio duoc cap nhat. fin()/free_orphans dat co nay.
	R.al_now = nil
	local n = 0
	for key, ship in pairs(e.user_ship) do
		if type(ship) == "table" then
			local want = AL.ship_alloy(key, tonumber(ship.ship_template_id), true)
			local have = ship.alloyMatrix
			if type(have) ~= "table" or not same_map(have.mmi, want.mmi) or not same_map(have.ma, want.ma) or not same_map(have.mr, want.mr) then
				ship.alloyMatrix = want
				n = n + 1
			end
		end
	end
	if n > 0 then R.al_ship_fix = (R.al_ship_fix or 0) + n end
	return n
end

local function uid_of(e)
	if type(e.user_info) == "table" then return math.floor(tn(e.user_info.user_id, 0)) end
	return 0
end

function AL.tokens(e, m, t)
	local o = owners()[m.id]
	t[#t + 1] = fint(m.id)
	t[#t + 1] = fint(m.rk)
	t[#t + 1] = fint(m.x)
	t[#t + 1] = fint(uid_of(e))
	t[#t + 1] = fint(m.cs)
	t[#t + 1] = fint(m.ce)
	t[#t + 1] = fint(o ~= nil and o.sid or -1)
	t[#t + 1] = fint(m.mm)
	t[#t + 1] = fint(m.lv)
end

function AL.in_sync(e)
	local lst = e.user_alloy_matrix
	if type(lst) ~= "table" then return false end
	local a = st()
	local ow = owners()
	local n = 0
	for _, d in pairs(lst) do
		n = n + 1
		if type(d) ~= "table" then return false end
		local m = find(d.id)
		if m == nil then return false end
		local o = ow[m.id]
		if tonumber(d.metalLevel) ~= m.lv or tonumber(d.metalRankLevel) ~= m.rk or tonumber(d.experience) ~= m.x
			or tonumber(d.consumeSilver) ~= m.cs or tonumber(d.consumeEssence) ~= m.ce or tonumber(d.metalMould) ~= m.mm
			or tonumber(d.shipId) ~= (o ~= nil and o.sid or -1) then
			return false
		end
	end
	if n ~= #a.m then return false end
	return tonumber(e.maxtrix_essence_num) == a.ess
end

function AL.rewrite(e)
	local a = st()
	e.user_alloy_matrix = nil
	local toks = { fint(#a.m) }
	for _, m in ipairs(a.m) do AL.tokens(e, m, toks) end
	local ok = call_parser("parse_user_alloy_matrix_info", toks)
	if not ok or type(e.user_alloy_matrix) ~= "table" then
		local lst, pos = {}, 2
		for _ = 1, #a.m do
			local id = tonumber(toks[pos])
			lst[id] = { id = id, metalRankLevel = tonumber(toks[pos + 1]), experience = tonumber(toks[pos + 2]), userInfo = tonumber(toks[pos + 3]),
				consumeSilver = tonumber(toks[pos + 4]), consumeEssence = tonumber(toks[pos + 5]), shipId = tonumber(toks[pos + 6]),
				metalMould = tonumber(toks[pos + 7]), metalLevel = tonumber(toks[pos + 8]) }
			pos = pos + 9
		end
		e.user_alloy_matrix = lst
		e.user_alloy_matrix_num = tostring(#a.m)
	end
	e.maxtrix_essence_num = a.ess
	R.al_rw = (R.al_rw or 0) + 1
	if R.al_rw <= 5 then log("hop kim: ghi lai danh sach vao game:", #a.m, "vien (lan", R.al_rw, ")") end
end

function AL.blk_metals(e, list)
	local t = { "14112", fint(#list) }
	for _, m in ipairs(list) do AL.tokens(e, m, t) end
	return table.concat(t, "\r\n")
end

local function blk_delete(ids)
	local t = { "14114", fint(#ids) }
	for _, id in ipairs(ids) do t[#t + 1] = fint(id) end
	return table.concat(t, "\r\n")
end

local function blk_ess()
	return "12047\r\n" .. fint(st().ess)
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do
		b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3])
	end
	return table.concat(b, "\r\n")
end

local function hero_blocks(e, sid, blocks)
	local key = skey(sid)
	local ship = e.user_ship[key]
	if type(ship) ~= "table" then return end
	local F = commit_hero(e, key, {})
	if F == nil then return end
	push_all(blocks, blk_evo(ship, F))
	push_all(blocks, blk_ship(ship, F))
	push_all(blocks, blk_fight(e, key, F))
end

function AL.restock()
	local T = AL.T()
	local made = {}
	if not T.ok then return made end
	local ow = owners()
	local have = {}
	for _, m in ipairs(st().m) do
		if ow[m.id] == nil then have[m.mm] = (have[m.mm] or 0) + 1 end
	end
	for _, id in ipairs(T.ids) do
		if (have[id] or 0) < 1 then made[#made + 1] = new_metal(id) end
	end
	if #made > 0 then mark(); R.al_made = (R.al_made or 0) + #made end
	return made
end

function AL.floor(nosilver)
	if not auto_on() then return 0 end
	local a = st()
	local n = 0
	if a.ess < ESS_LOW then a.ess = ESS_TOP; n = n + 1; mark() end
	local sv = LS.money_get("silver")
	if not nosilver and sv ~= nil and sv < SIL_LOW then LS.money_set("silver", SIL_TOP); n = n + 1 end
	return n
end

function AL.seed(e)
	local T = AL.T()
	local a = { v = 1, nid = ID_BASE, ess = 0, m = {}, eq = {}, mr = {} }
	S.al = a
	invalidate()
	local rec = {}
	local lst = e.user_alloy_matrix
	if type(lst) == "table" then
		for _, d in pairs(lst) do
			if type(d) == "table" and tonumber(d.id) ~= nil then rec[#rec + 1] = d end
		end
		table.sort(rec, function(x, y) return tonumber(x.id) < tonumber(y.id) end)
	end
	local seen = {}
	for _, d in ipairs(rec) do
		local id, mm = math.floor(tonumber(d.id)), tonumber(d.metalMould)
		if mm ~= nil and T.mm[math.floor(mm)] ~= nil and id > 0 and not seen[id] then
			seen[id] = true
			a.m[#a.m + 1] = { id = id, mm = math.floor(mm), lv = math.max(1, math.floor(tn(d.metalLevel, 1))), rk = math.max(0, math.floor(tn(d.metalRankLevel, 0))),
				x = math.max(0, math.floor(tn(d.experience, 0))), cs = math.max(0, math.floor(tn(d.consumeSilver, 0))), ce = math.max(0, math.floor(tn(d.consumeEssence, 0))) }
			if id >= a.nid then a.nid = id + 1 end
		end
	end
	a.ess = math.max(0, math.floor(tn(e.maxtrix_essence_num, 0)))
	AL.clean()
	local made = AL.restock()
	mark()
	LS.save_state(true)
	log("hop kim: khoi tao kho:", #a.m, "vien (gom", #rec, "vien goc trong ban ghi,", #made, "vien LS tao), tinh hoa", a.ess)
	return a
end

function AL.clean()
	local T = AL.T()
	if not T.ok then return 0 end
	local a = st()
	local keep, gone, seen, top = {}, 0, {}, 0
	for _, m in ipairs(a.m) do
		local good = false
		if type(m) == "table" and tonumber(m.id) ~= nil and tonumber(m.mm) ~= nil then
			m.id, m.mm = math.floor(tonumber(m.id)), math.floor(tonumber(m.mm))
			if T.mm[m.mm] ~= nil and m.id > 0 and not seen[m.id] then
				seen[m.id] = true
				m.lv = math.min(MAX_LV, math.max(1, math.floor(tn(m.lv, 1))))
				m.rk = math.max(0, math.floor(tn(m.rk, 0)))
				m.x = math.max(0, math.floor(tn(m.x, 0)))
				m.cs = math.max(0, math.floor(tn(m.cs, 0)))
				m.ce = math.max(0, math.floor(tn(m.ce, 0)))
				if prow(m) == nil then
					local fixed = false
					for rk = 0, 20 do
						m.rk = rk
						if prow(m) ~= nil then fixed = true; break end
					end
					if not fixed then m.lv, m.rk, m.x = 1, 0, 0 end
				end
				if m.id > top then top = m.id end
				good = true
			end
		end
		if good then keep[#keep + 1] = m else gone = gone + 1 end
	end
	if gone > 0 then a.m = keep; mark(); log("hop kim: bo", gone, "vien khong ro mau / trung id") end
	if top >= a.nid then a.nid = top + 1 end
	invalidate()

	local ids = {}
	for k in pairs(a.eq) do ids[#ids + 1] = k end
	table.sort(ids, function(x, y) return tostring(x) < tostring(y) end)
	local neq, used, dropped = {}, {}, 0
	for _, k in ipairs(ids) do
		local tiers = a.eq[k]
		local sidn = tonumber(k)
		if type(tiers) == "table" and sidn ~= nil and sidn > 0 then
			local tks = {}
			for tk in pairs(tiers) do tks[#tks + 1] = tk end
			table.sort(tks, function(x, y) return tostring(x) < tostring(y) end)
			for _, tk in ipairs(tks) do
				local tnum, slots = tonumber(tk), tiers[tk]
				if tnum ~= nil and tnum >= 1 and tnum <= TIERS and type(slots) == "table" then
					local pks = {}
					for pk in pairs(slots) do pks[#pks + 1] = pk end
					table.sort(pks, function(x, y) return tostring(x) < tostring(y) end)
					local seen_mm, seen_sp = {}, false
					for _, pk in ipairs(pks) do
						local pnum, idn = tonumber(pk), tonumber(slots[pk])
						local m = idn ~= nil and find(idn) or nil
						local mm = m ~= nil and T.mm[m.mm] or nil
						local ok = pnum ~= nil and pnum >= 1 and pnum <= (tnum + 1) * 2 and mm ~= nil and not used[m.id] and not seen_mm[m.mm]
							and not (mm.head == 2 and seen_sp)
						if ok then
							used[m.id] = true
							seen_mm[m.mm] = true
							if mm.head == 2 then seen_sp = true end
							local d = neq[tostring(math.floor(sidn))]
							if d == nil then d = {}; neq[tostring(math.floor(sidn))] = d end
							local t = d[tostring(math.floor(tnum))]
							if t == nil then t = {}; d[tostring(math.floor(tnum))] = t end
							t[tostring(math.floor(pnum))] = m.id
						else
							dropped = dropped + 1
						end
					end
				else
					dropped = dropped + 1
				end
			end
		else
			dropped = dropped + 1
		end
	end
	if dropped > 0 then mark(); log("hop kim: bo", dropped, "vi tri gan khong hop le") end
	a.eq = neq

	for k, r in pairs(a.mr) do
		if type(r) ~= "table" then a.mr[k] = nil
		else
			for mk, v in pairs(r) do
				local nv = tonumber(v)
				if nv == nil then r[mk] = nil else r[mk] = (nv >= 1) and 1 or 0 end
			end
		end
	end
	invalidate()
	return gone
end

function AL.ensure(e)
	local a = S.al
	if type(a) == "table" and a.v == 1 and type(a.m) == "table" then
		if not R.al_clean then R.al_clean = true; AL.clean() end
		R.al_ready = true
		return a
	end
	if not AL.T().ok then return nil end
	R.al_ready = true
	R.al_clean = true
	return AL.seed(e)
end

function AL.free_orphans(e)
	if R.inject ~= nil or R.grant ~= nil or type(e.user_ship) ~= "table" then return 0 end
	local a = st()
	local n = 0
	for k in pairs(a.eq) do
		if e.user_ship[k] == nil then a.eq[k] = nil; n = n + 1 end
	end
	if n > 0 then invalidate(); R.al_now = true; mark(); log("hop kim: go da cua", n, "tuong da bi go") end
	return n
end

function AL.on_world(e)
	R.al_t = nil
	invalidate()
	R.al_ready, R.al_clean, R.al_tick = false, false, 0
	R.al_draw_sig, R.al_pool = nil, nil

	local cp = {}
	local lst = e.user_alloy_matrix
	if type(lst) == "table" then
		for _, d in pairs(lst) do
			if type(d) == "table" and tonumber(d.id) ~= nil and tonumber(d.id) < ID_BASE then
				local c = {}
				for k, v in pairs(d) do c[k] = v end
				cp[#cp + 1] = c
			end
		end
	end
	R.al_rec = cp
	R.al_rec_ess = tonumber(e.maxtrix_essence_num)
end

function AL.restore(e)
	if type(e) ~= "table" then return end
	local lst = {}
	for _, d in ipairs(R.al_rec or {}) do
		local c = {}
		for k, v in pairs(d) do c[k] = v end
		c.shipId = -1
		lst[tonumber(c.id)] = c
	end
	e.user_alloy_matrix = lst
	e.user_alloy_matrix_num = tostring(#(R.al_rec or {}))
	if R.al_rec_ess ~= nil then e.maxtrix_essence_num = R.al_rec_ess end
	if type(e.user_ship) == "table" then
		for _, ship in pairs(e.user_ship) do
			if type(ship) == "table" then ship.alloyMatrix = { mmi = {}, ma = {}, mr = {} } end
		end
	end
	invalidate()
	R.al_ready, R.al_clean = false, false
end

function AL.tick(e)
	if S == nil or not R.ready then return end
	local a = AL.ensure(e)
	if a == nil then return end
	R.al_tick = (R.al_tick or 0) + 1
	if auto_on() then
		AL.restock()
		AL.floor(true)
	end
	al_full_pass(a, e)
	if R.al_tick % 40 == 0 then AL.free_orphans(e) end
	if not AL.in_sync(e) then AL.rewrite(e) end
	AL.sync_ships(e)
	if AL.draw_sync ~= nil and (R.al_draw_sig == nil or R.al_tick % 20 == 0) then pcall(AL.draw_sync, false) end
end

local function ctx()
	local e = ED()
	if e == nil then error("chua co the gioi") end
	if AL.ensure(e) == nil then error("khong co bang hop kim") end
	return e
end

local function addu(list, v)
	for i = 1, #list do if list[i] == v then return end end
	list[#list + 1] = v
end

local function fin(e, seq, name, changed, deleted, sids, extra)
	if auto_on() then
		local made = AL.restock()
		for i = 1, #made do changed[#changed + 1] = made[i] end
		AL.floor()
	end
	-- [FIX FULL Hop kim] vien du phong vua sinh ra cung phai max ngay trong goi tra ve
	al_full_pass(st(), e)
	R.al_now = true
	AL.sync_ships(e)
	local blocks = {}
	if #changed > 0 then blocks[#blocks + 1] = AL.blk_metals(e, changed) end
	if #deleted > 0 then blocks[#blocks + 1] = blk_delete(deleted) end
	blocks[#blocks + 1] = blk_ess()
	for _, b in ipairs(extra or {}) do blocks[#blocks + 1] = b end
	for _, sid in ipairs(sids or {}) do hero_blocks(e, sid, blocks) end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function AL.h_set(p, seq)
	local name = "ship_metal_set"
	local e = ctx()
	local T = AL.T()
	local a = st()
	local sid, ti, ty = tonumber(p[1]), tonumber(p[2]), tonumber(p[3])
	local info = tostring(p[4] or "")
	if sid == nil or ti == nil or ty == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
	sid, ti, ty = math.floor(sid), math.floor(ti), math.floor(ty)
	local key = skey(sid)
	if e.user_ship[key] == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.generic) end
	if ti < 1 or ti > TIERS then return err_reply(seq, name, "LS_tang_khong_hop_le", ERR.generic) end
	local ts = tostring(ti)
	local cap = (ti + 1) * 2
	local grade = math.floor(tn(e.user_info and e.user_info.user_grade, 0))
	local ow = owners()

	local work = {}
	do
		local eq = a.eq[key]
		local cur = eq ~= nil and eq[ts] or nil
		if type(cur) == "table" then
			for pk, id in pairs(cur) do work[tonumber(pk)] = tonumber(id) end
		end
	end
	local before = {}
	for _, id in pairs(work) do before[id] = true end
	local taken = {}
	local function in_work(id)
		for pk, v in pairs(work) do if v == id then return pk end end
		return nil
	end
	local function place(id, pos)
		local m = find(id)
		if m == nil then return "LS_khong_co_da" end
		if pos == nil or pos < 1 or pos > cap then return "LS_o_khong_hop_le" end
		local need = T.unlock[ti] ~= nil and T.unlock[ti][pos] or nil
		if need ~= nil and grade < need then return "LS_o_chua_mo" end
		local mm = T.mm[m.mm]

		local old = in_work(m.id)
		if old ~= nil then work[old] = nil end
		work[pos] = nil
		for pk, v in pairs(work) do
			local o = find(v)
			local om = o ~= nil and T.mm[o.mm] or nil
			if o ~= nil and o.mm == m.mm then return "LS_trung_loai_da" end
			if om ~= nil and mm ~= nil and om.head == 2 and mm.head == 2 then return "LS_chi_1_da_dac_biet" end
		end
		work[pos] = m.id
		if old == nil and ow[m.id] ~= nil and not (ow[m.id].sid == sid and ow[m.id].t == ti) then taken[#taken + 1] = m.id end
		return nil
	end
	local err = nil
	if ty == 2 then
		work = {}
	elseif ty == 0 then
		local id, pos = string.match(info, "(%-?%d+)%s*,%s*(%d+)")
		if id == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
		id, pos = tonumber(id), tonumber(pos)
		if id < 0 then
			if pos >= 1 and pos <= cap then work[pos] = nil end
		else
			err = place(id, pos)
		end
	elseif ty == 1 then
		work = {}
		local n = 0
		for id, pos in string.gmatch(info, "(%d+)%s*,%s*(%d+)") do
			err = place(tonumber(id), tonumber(pos))
			if err ~= nil then break end
			n = n + 1
		end
		if err == nil and n == 0 then err = "LS_khong_co_da" end
	else
		err = "LS_kieu_khong_ho_tro"
	end
	if err ~= nil then return err_reply(seq, name, err, ERR.generic) end

	local sids, changed, after = { sid }, {}, {}
	for _, id in pairs(work) do after[id] = true end
	for _, id in ipairs(taken) do
		local o = ow[id]
		if o ~= nil then
			local d = a.eq[skey(o.sid)]
			local t = d ~= nil and d[tostring(o.t)] or nil
			if t ~= nil then t[tostring(o.p)] = nil end
			addu(sids, o.sid)
		end
	end
	local d = a.eq[key]
	if d == nil then d = {}; a.eq[key] = d end
	local nt = {}
	for pos, id in pairs(work) do nt[tostring(pos)] = id end
	d[ts] = nt
	invalidate()
	for id in pairs(before) do if not after[id] then addu(changed, find(id)) end end
	for id in pairs(after) do addu(changed, find(id)) end
	for _, id in ipairs(taken) do addu(changed, find(id)) end
	stat_inc("al_sets")
	R.al_last = "gan tang " .. fint(ti) .. " tuong " .. fint(sid) .. ": " .. fint(#changed) .. " vien doi"
	return fin(e, seq, name, changed, {}, sids)
end

local function pay(kind, cost)
	local a = st()
	if kind == "lv" then
		if a.ess < cost then
			if not auto_on() then return ERR.items, "LS_khong_du_tinh_hoa" end
			a.ess = cost + ESS_TOP
		end
		a.ess = a.ess - cost
	else
		if (LS.money_get("silver") or 0) < cost then
			if not auto_on() then return ERR.silver, "LS_khong_du_bac" end
			LS.money_set("silver", cost + SIL_TOP)
		end
		LS.money_spend("silver", cost)
	end
	return nil
end

local function apply_step(m, kind, cost)
	if kind == "lv" then
		m.lv = m.lv + 1
		m.x = 0
		m.ce = m.ce + cost
	else
		m.rk = m.rk + 1
		m.cs = m.cs + cost
	end
end

function AL.h_escalate(p, seq)
	local name = "ship_metal_escalate"
	local e = ctx()
	local m = find(p[1])
	if m == nil then return err_reply(seq, name, "LS_khong_co_da", ERR.generic) end
	local ty = tonumber(p[2]) or 0
	local limit = (ty == 1) and (MAX_LV * 2) or 1
	local n, lvs = 0, 0
	while n < limit do
		local kind, cost = AL.step(m)
		if kind == "max" then
			if n == 0 then return err_reply(seq, name, "LS_da_toi_da", ERR.rank_max) end
			break
		end
		if kind == "rank" and ty == 1 and n > 0 then break end
		local code, msg = pay(kind, cost)
		if code ~= nil then
			if n == 0 then return err_reply(seq, name, msg, code) end
			break
		end
		apply_step(m, kind, cost)
		n = n + 1
		if kind == "lv" then lvs = lvs + 1 end
		if kind == "rank" and ty == 1 then break end
	end
	stat_inc("al_levels", lvs)
	R.al_last = "da " .. fint(m.id) .. ": cap " .. fint(m.lv) .. " bac " .. fint(m.rk)
	local o = owners()[m.id]
	return fin(e, seq, name, { m }, {}, o ~= nil and { o.sid } or {})
end

function AL.h_onekey(p, seq)
	local name = "ship_metal_onekey_escalate"
	local e = ctx()
	local sid, ti, target = tonumber(p[1]), tonumber(p[2]), tonumber(p[3])
	if sid == nil or ti == nil or target == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
	sid, ti = math.floor(sid), math.floor(ti)
	target = math.min(MAX_LV, math.floor(target))
	local key = skey(sid)
	if e.user_ship[key] == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.generic) end
	local list = tier_metals(key, tostring(ti))
	if #list == 0 then return err_reply(seq, name, "LS_tang_trong", ERR.generic) end
	local changed, steps, lastcode, lastmsg = {}, 0, nil, nil
	for _, m in ipairs(list) do
		local did = false
		local guard = 0
		while m.lv < target and guard < 1000 do
			guard = guard + 1
			local kind, cost = AL.step(m)
			if kind == "max" then break end
			local code, msg = pay(kind, cost)
			if code ~= nil then lastcode, lastmsg = code, msg; break end
			apply_step(m, kind, cost)
			steps = steps + 1
			did = true
		end
		if did then changed[#changed + 1] = m end
	end
	if steps == 0 then
		if lastcode ~= nil then return err_reply(seq, name, lastmsg, lastcode) end
		return err_reply(seq, name, "LS_khong_co_gi_de_nang", ERR.generic)
	end
	stat_inc("al_levels", steps)
	R.al_last = "tang " .. fint(ti) .. " tuong " .. fint(sid) .. ": len cap " .. fint(target) .. " (" .. fint(steps) .. " buoc)"
	return fin(e, seq, name, changed, {}, { sid })
end

function AL.h_dissolve(p, seq)
	local name = "ship_metal_dissolve"
	local e = ctx()
	local T = AL.T()
	local a = st()
	local ids, seen = {}, {}
	for w in string.gmatch(tostring(p[1] or ""), "%-?%d+") do
		local n = tonumber(w)
		if n ~= nil and not seen[n] then seen[n] = true; ids[#ids + 1] = n end
	end
	if #ids == 0 then return err_reply(seq, name, "LS_chua_chon_da", ERR.generic) end
	if #ids > T.maxsel then return err_reply(seq, name, "LS_chon_qua_nhieu", ERR.generic) end
	local ow = owners()
	local re, rs = 0, 0
	for _, id in ipairs(ids) do
		local m = find(id)
		if m == nil then return err_reply(seq, name, "LS_khong_co_da", ERR.generic) end
		if ow[m.id] ~= nil then return err_reply(seq, name, "LS_da_dang_gan", ERR.generic) end
		re = re + m.ce * T.r_ess
		rs = rs + m.cs * T.r_sil
	end
	re, rs = math.floor(re + 1e-9), math.floor(rs + 1e-9)
	local gone = {}
	for _, id in ipairs(ids) do gone[id] = true end
	local keep = {}
	for _, m in ipairs(a.m) do if not gone[m.id] then keep[#keep + 1] = m end end
	a.m = keep
	invalidate()
	a.ess = a.ess + re
	if rs > 0 then LS.money_add("silver", rs) end
	stat_inc("al_dissolved", #ids)
	R.al_last = "nau chay " .. fint(#ids) .. " vien: +" .. fint(re) .. " tinh hoa, +" .. fint(rs) .. " bac"
	local extra = {}
	local items = {}
	if re > 0 then items[#items + 1] = { -1, ESS_TYPE, re } end
	if rs > 0 then items[#items + 1] = { -1, 1, rs } end
	if #items > 0 then extra[1] = blk_reward(items) end
	return fin(e, seq, name, {}, ids, {}, extra)
end

function AL.h_claim(p, seq)
	local name = "draw_matrix_reward"
	local e = ctx()
	local T = AL.T()
	local a = st()
	local sid = tonumber(p[1])
	if sid == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
	local key = skey(sid)
	if e.user_ship[key] == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.generic) end
	AL.sync_ships(e)
	local r = a.mr[key] or {}
	local n = 0
	for w in string.gmatch(tostring(p[2] or ""), "%d+") do
		if r[w] ~= nil and tonumber(r[w]) == 0 then
			r[w] = 1
			n = n + 1
		end
	end
	if n == 0 then return err_reply(seq, name, "LS_khong_co_thuong_de_nhan", ERR.generic) end
	a.mr[key] = r
	local items, sums = {}, {}
	for _, tr in ipairs(T.claim) do
		local ty, val = tr[1], tr[3] * n
		if ty == ESS_TYPE then a.ess = a.ess + val
		elseif ty == 1 then LS.money_add("silver", val)
		elseif ty == 2 then LS.money_add("gold", val)
		else val = 0 end
		if val > 0 then items[#items + 1] = { tr[2], ty, val } end
	end
	stat_inc("al_claims", n)
	R.al_last = "nhan thuong " .. fint(n) .. " ma tran (tuong " .. fint(sid) .. ")"
	local extra = {}
	if #items > 0 then extra[1] = blk_reward(items) end
	return fin(e, seq, name, {}, {}, { sid }, extra)
end

function AL.counts()
	local a = S ~= nil and S.al or nil
	if type(a) ~= "table" or type(a.m) ~= "table" then return nil end
	local n, eq, mx = 0, 0, 0
	local ow = owners()
	for _, m in ipairs(a.m) do
		n = n + 1
		if ow[m.id] ~= nil then eq = eq + 1 end
		if m.lv > mx then mx = m.lv end
	end
	return n, eq, mx
end

function AL.dump_line()
	local n, eq, mx = AL.counts()
	if n == nil then return "[LS hop kim] chua khoi tao" end
	return "[LS hop kim] kho " .. n .. " vien | dang gan " .. eq .. " | cap cao nhat " .. mx .. " | tinh hoa " .. fnum(st().ess)
		.. " | full " .. (AL.full_on() and "BAT" or "TAT")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.al_last ~= nil and (" | cuoi: " .. R.al_last) or "")
		.. " | ghi lai " .. tostring(R.al_rw or 0) .. " lan, sua tuong " .. tostring(R.al_ship_fix or 0)
end

function AL.reset()
	S.al = nil
	R.al_ready = false
	invalidate()
	mark()
end

do
	local ws_delta = WS.delta
	WS.delta = function(sid)
		local out = ws_delta(sid)
		local ok, d = pcall(AL.delta, sid)
		if ok and type(d) == "table" then
			for i = 1, 4 do out[i] = out[i] + d[i] end
			out.spec = out.spec or {}
			for t, v in pairs(d.spec) do out.spec[t] = (out.spec[t] or 0) + v end
		elseif not ok then
			R.al_errs = (R.al_errs or 0) + 1
			if R.al_errs <= 5 then log("loi chi so hop kim:", tostring(d)) end
		end
		return out
	end
end

-- =====================================================================================
-- [VONG QUAY HOP KIM] ship_bounty / ship_batch_bounty cho cua so rut hop kim
--   ship_bounty       : 4 = vang x1 (nut 1)      5 = kim cuong x1 (nut 4)
--   ship_batch_bounty : 5 = vang x10 (nut 2)     6 = vang x50 (nut 3)   7 = kim cuong x10 (nut 5)
-- Cac type khac (rut tuong 1,2,3...) tra nil -> giu nguyen hanh vi cu.
-- =====================================================================================
local DRAW_SINGLE = { [4] = { idx = 1, n = 1 }, [5] = { idx = 4, n = 1 } }
local DRAW_BATCH = { [5] = { idx = 2, n = 10 }, [6] = { idx = 3, n = 50 }, [7] = { idx = 5, n = 10 } }
local DRAW_BASE = 3        -- moi bac pham chat cao hon hiem gap DRAW_BASE lan
local DRAW_RATE = {}       -- ghi de ti le tung bac: DRAW_RATE[pham_chat] = trong_so
local DRAW_PITY = true     -- moi 10 vien bao dam >= 1 vien pham chat cao nhat/nhi
local DRAW_DEF_MAX = 9999  -- luot toi da/ngay neu ship_config 41 khong doc duoc

local function draw_cfg()
	local out = {}
	local s = cfg_str("ship_config", 41)
	if s ~= nil then
		for a, b in string.gmatch(s, "(%d+)%s*,%s*(%d+)") do out[#out + 1] = { pid = tonumber(a), max = tonumber(b) } end
	end
	return out
end

local function draw_row(pid)
	if pid == nil then return {} end
	local t = dtab("partner_bounty_param")
	if t == nil then return {} end
	return cells(t[pid]) or {}
end

local function draw_cost(pid)
	local r = draw_row(pid)
	return ci(r, schema("partner_bounty_param", "spend_silver", 4), 0), ci(r, schema("partner_bounty_param", "spend_gold", 5), 0)
end

local function draw_free(slot)
	if slot == nil then return false end
	return ci(draw_row(slot.pid), schema("partner_bounty_param", "free_count", 3), 0) > 0
end

local function draw_state()
	local a = st()
	local c = a.rc
	if type(c) ~= "table" then c = { use = { 0, 0, 0, 0, 0 }, gf = 0, df = 0, day = "" }; a.rc = c end
	if type(c.use) ~= "table" then c.use = { 0, 0, 0, 0, 0 } end
	local day = os.date("%Y%m%d")
	if c.day ~= day or c.v ~= 2 then
		local same = (c.day == day)
		local cfg = draw_cfg()
		-- tinh xong het roi moi gan: neu loi giua chung thi khong de lai trang thai nua vo
		local gf = draw_free(cfg[1]) and 1 or 0
		local df = draw_free(cfg[4]) and 1 or 0
		if same then
			-- ngay hom nay da khoi tao hong (luot mien phi bi mat): cap lai neu chua rut x1 nao
			if math.floor(tn(c.use[1], 0)) > 0 then gf = 0 end
			if math.floor(tn(c.use[4], 0)) > 0 then df = 0 end
		else
			c.use = { 0, 0, 0, 0, 0 }
		end
		c.day, c.gf, c.df, c.v = day, gf, df, 2
		mark()
	end
	for i = 1, 5 do c.use[i] = math.max(0, math.floor(tn(c.use[i], 0))) end
	c.gf, c.df = math.floor(tn(c.gf, 0)), math.floor(tn(c.df, 0))
	return c
end

local function draw_use_str(c)
	return fint(c.use[1]) .. "," .. fint(c.use[2]) .. "," .. fint(c.use[3]) .. "," .. fint(c.use[4]) .. "," .. fint(c.use[5])
end

local function blk_draw_state(c)
	return "14113\r\n" .. fint(c.gf) .. "\r\n" .. fint(c.df) .. "\r\n" .. draw_use_str(c)
end

-- dua trang thai rut (luot mien phi / da rut) vao _ED.alloy_matrix_recruit de giao dien khong bi nil
function AL.draw_sync(force)
	local c = draw_state()
	local sig = c.day .. ":" .. fint(c.gf) .. fint(c.df) .. draw_use_str(c)
	if not force and R.al_draw_sig == sig then return end
	if call_parser("parse_alloy_matrix_get_reword", { fint(c.gf), fint(c.df), draw_use_str(c) }) then R.al_draw_sig = sig end
end

local function draw_pool()
	local T = AL.T()
	if not T.ok then return nil end
	local P = R.al_pool
	if P ~= nil and P.T == T then return P end
	local top, cnt = 0, {}
	for _, id in ipairs(T.ids) do
		local q = T.mm[id].q
		cnt[q] = (cnt[q] or 0) + 1
		if q > top then top = q end
	end
	P = { T = T, top = top, gq = top - 1, all = {}, hi = {}, tot = 0, hitot = 0 }
	for _, id in ipairs(T.ids) do
		local q = T.mm[id].q
		local w = (DRAW_RATE[q] or (DRAW_BASE ^ (top - q))) / cnt[q]
		P.all[#P.all + 1] = { id = id, w = w }
		P.tot = P.tot + w
		if q >= P.gq then
			P.hi[#P.hi + 1] = { id = id, w = w }
			P.hitot = P.hitot + w
		end
	end
	R.al_pool = P
	return P
end

local function draw_pick(list, tot)
	local x = math.random() * tot
	for _, it in ipairs(list) do
		x = x - it.w
		if x <= 0 then return it.id end
	end
	return list[#list].id
end

local function draw_roll(n)
	local P = draw_pool()
	if P == nil or #P.all == 0 then return nil end
	math.randomseed(os.time() + math.floor((os.clock() * 1000000) % 1000000) + (R.al_seed_n or 0) * 7919)
	R.al_seed_n = ((R.al_seed_n or 0) + 1) % 100000
	local mm = P.T.mm
	local out, nhi = {}, 0
	for i = 1, n do
		local id = draw_pick(P.all, P.tot)
		out[i] = id
		if mm[id].q >= P.gq then nhi = nhi + 1 end
	end
	local need = (DRAW_PITY and n >= 10) and math.floor(n / 10) or 0
	if nhi < need and #P.hi > 0 then
		local order = {}
		for i = 1, n do order[i] = i end
		table.sort(order, function(x, y) return mm[out[x]].q < mm[out[y]].q end)
		for _, i in ipairs(order) do
			if nhi >= need then break end
			if mm[out[i]].q < P.gq then
				out[i] = draw_pick(P.hi, P.hitot)
				nhi = nhi + 1
			end
		end
	end
	return out
end

local function draw_do(p, seq, name, rules)
	local t = tonumber(p[1])
	local rule = t ~= nil and rules[t] or nil
	if rule == nil then return nil end
	local e = ctx()
	local cfg = draw_cfg()
	local slot = cfg[rule.idx]
	local c = draw_state()
	local maxn = slot ~= nil and slot.max or DRAW_DEF_MAX
	if c.use[rule.idx] >= maxn then return err_reply(seq, name, "LS_het_luot_rut", ERR.attempts) end

	local free = (rule.idx == 1 and c.gf == 1) or (rule.idx == 4 and c.df == 1)
	if not free and slot ~= nil then
		local sil, gold = draw_cost(slot.pid)
		if sil > 0 then
			if not LS.money_spend("silver", sil) then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
		elseif gold > 0 then
			if not LS.money_spend("gold", gold) then return err_reply(seq, name, "LS_khong_du_kim_cuong", ERR.items) end
		end
	end

	local rolled = draw_roll(rule.n)
	if rolled == nil then return err_reply(seq, name, "LS_khong_co_bang_hop_kim", ERR.generic) end
	local created = {}
	for i = 1, #rolled do created[i] = new_metal(rolled[i]) end
	if free then
		if rule.idx == 1 then c.gf = 0 else c.df = 0 end
	end
	c.use[rule.idx] = c.use[rule.idx] + 1
	if type(e.random_Patch) ~= "table" then e.random_Patch = {} end
	stat_inc("al_draws", rule.n)
	R.al_draw_sig = nil
	R.al_last = "rut hop kim x" .. fint(rule.n) .. (free and " (mien phi)" or "")
	log("vong quay hop kim: type", fint(t), "x", fint(rule.n), free and "| mien phi" or "", "| da rut", fint(c.use[rule.idx]), "/", fint(maxn))
	return fin(e, seq, name, created, {}, {}, { blk_draw_state(c) })
end

function AL.h_bounty(p, seq) return draw_do(p, seq, "ship_bounty", DRAW_SINGLE) end
function AL.h_batch(p, seq) return draw_do(p, seq, "ship_batch_bounty", DRAW_BATCH) end

LS._al = AL

end
init_al()
end

do
local function init_ar()

local AR = {}
local SB, WB = LS._sb, LS._wb

local MAX_RANK = 30000
local TOP_N = 10
local NEAR_N = 5
local FREE_TIMES = 5
local WORSHIP_MAX, WORSHIP_SILVER = 10, 10000
local F_LOW, F_HIGH = 0.85, 2.0
local START_RANK = 8000
local LOG_MAX = 11
local ID_BASE = 800000000

local function st()
	local a = S.ar
	if type(a) ~= "table" then
		a = { v = 1 }
		S.ar = a
	end
	a.rank = math.floor(tn(a.rank, START_RANK))
	if a.rank < 1 then a.rank = 1 end
	if a.rank > MAX_RANK + 5000 then a.rank = MAX_RANK + 5000 end
	a.best = math.floor(tn(a.best, a.rank))
	if a.best > a.rank then a.best = a.rank end
	a.score = math.max(0, math.floor(tn(a.score, 0)))
	a.win = math.max(0, math.floor(tn(a.win, 0)))
	a.lose = math.max(0, math.floor(tn(a.lose, 0)))
	a.batch = math.max(1, math.floor(tn(a.batch, 1)))
	a.day = tostring(a.day or "")
	a.wn = math.max(0, math.floor(tn(a.wn, 0)))
	if type(a.wor) ~= "table" then a.wor = {} end
	if type(a.dr) ~= "table" then a.dr = {} end
	if type(a.ds) ~= "table" then a.ds = {} end
	if type(a.logs) ~= "table" then a.logs = {} end
	for i = #a.logs, 1, -1 do
		if type(a.logs[i]) ~= "table" then table.remove(a.logs, i) end
	end
	if type(a.wv) ~= "table" then a.wv = {} end
	return a
end

local function power_mult()
	local v = type(S.cfg) == "table" and tonumber(S.cfg.ar_power) or nil
	if v == nil or v <= 0 then v = 1 end
	if v > 10000 then v = 10000 end -- [NHAP SO] tran buff arena 10000 (nhap tay)
	return v
end

local function today()
	return os.date("%Y%j", os.time())
end

local function split_tab(str)
	local t = {}
	for w in string.gmatch(tostring(str) .. "\t", "(.-)\t") do t[#t + 1] = w end
	return t
end

local function reward_rows(name)
	local d = G("dms")
	local out = {}
	if type(d) ~= "table" or type(d[name]) ~= "table" then return out end
	local ids = {}
	for k in pairs(d[name]) do
		if type(k) == "number" then ids[#ids + 1] = k end
	end
	table.sort(ids)
	for i, id in ipairs(ids) do
		local r = d[name][id]
		if type(r) == "string" then r = split_tab(r) end
		if type(r) == "table" then
			local tgt = tonumber(r[2])
			if tgt ~= nil then out[#out + 1] = { idx = i, target = tgt, info = tostring(r[3] or "") } end
		end
	end
	return out
end

local function triples(s)
	local out = {}
	for ty, it, qty in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { typ = tonumber(ty), item = tonumber(it), qty = tonumber(qty) }
	end
	return out
end

local function arena_cfg_num(id, dflt)
	local v = tonumber(cfg_str("arena_config", id))
	if v == nil then return dflt end
	return v
end

local function score_points()
	local s = tostring(cfg_str("arena_config", 7) or "")
	local w, l = string.match(s, "(%d+)%s*,%s*(%d+)")
	return tonumber(w) or 2, tonumber(l) or 1
end

local function my_id(e)
	return tostring(e.user_info and e.user_info.user_id or "0")
end

local function my_name(e)
	local n = tostring(e.user_info and e.user_info.user_name or "Player")
	-- [SHARED ARENA] da dang nhap bang tai khoan => hien ten tai khoan (nguoi choi khac nhin thay ten nay trong Arena)
	if LS._acct ~= nil and LS._acct.user ~= nil and LS._acct.user ~= "" then n = tostring(LS._acct.user) end
	n = string.gsub(n, "%s+", "_")
	if n == "" then n = "Player" end
	return n
end

local function my_force(e)
	local f = tonumber(e.user_info and e.user_info.fight_capacity) or 0
	if f <= 0 then f = 100000 end
	return math.floor(f)
end

local function my_grade(e)
	return math.max(1, math.floor(tonumber(e.user_info and e.user_info.user_grade) or 1))
end

local function my_head(e)
	local h = tonumber(e.user_info and e.user_info.user_head)
	if h == nil or h < 1 then h = 1 end
	return math.floor(h)
end

local function rng(seed)
	local s = (math.floor(seed) % 2147483629) + 1
	return function()
		s = (s * 48271) % 2147483629
		return s / 2147483629
	end
end

function AR.factor(rank)
	rank = math.max(1, math.min(MAX_RANK, math.floor(tonumber(rank) or MAX_RANK)))
	local t = 1 - math.log(rank) / math.log(MAX_RANK)
	return (F_LOW + (F_HIGH - F_LOW) * t) * power_mult()
end

local function ship_list(e)
	local out = {}
	if type(e.user_ship) ~= "table" then return out end
	for k, s in pairs(e.user_ship) do
		if type(s) == "table" and tonumber(s.ship_template_id) ~= nil then
			out[#out + 1] = { key = tostring(k), ship = s, tid = tonumber(s.ship_template_id), g = tonumber(s.ship_grade) or 0,
				id = tonumber(s.ship_id) or tonumber(k) or 0 }
		end
	end
	table.sort(out, function(a, b)
		if a.g ~= b.g then return a.g > b.g end
		return a.id < b.id
	end)
	return out
end

-- [TEN BOT v6.34] Ten bot Arena RANDOM kieu tre trau nghien Dragon Ball hay dat (xX_Vegeta_Xx, Goku_SSJ4_2k9, TuanBroly,
-- Vua_Frieza, G0ku_VN ...). Chi dung ASCII, khong dau cach, toi da 16 ky tu (vua o ten trong danh sach Arena).
-- Ten GAN CO DINH theo (hang, dot lam moi): cung hang + cung dot => cung ten, nen danh sach khong nhay ten moi lan mo.
-- Bam "Doi" (lam moi dot) => bot hang gan doi ten moi. Muon ten co dinh: dat S.cfg.ar_name = "ten"; ar_name = false/khong dat => random.
-- (khai bao bang AR.* thay vi local de khong cham gioi han 200 local cua Lua)
