function AR.rand_name(rn)
	local N = AR.NM
	local function pick(t) return t[math.floor(rn() * #t) + 1] end
	local kind = math.floor(rn() * 100)
	local base, post = "", ""
	local usepost = rn() < 0.55
	if kind < 14 then
		base = "xX_" .. pick(N.hero) .. "_Xx"                          -- xX_Vegeta_Xx
		usepost = false
	elseif kind < 28 then
		base = pick(N.hero) .. "_" .. pick(N.form)                     -- Goku_SSJ4
	elseif kind < 42 then
		base = pick(N.given) .. pick(N.hero)                           -- TuanBroly
	elseif kind < 54 then
		base = pick(N.pre) .. "_" .. pick(N.hero)                      -- Vua_Frieza
	elseif kind < 64 then
		base = pick(N.hero)                                            -- Goku2k9
		usepost = true
	elseif kind < 74 then
		-- leet kieu game thu: Goku -> G0ku, Vegeta -> V3g3ta
		base = string.gsub(pick(N.hero), "[oea]", function(c)
			if rn() < 0.6 then return (c == "o" and "0") or (c == "e" and "3") or "4" end
			return c
		end)
		usepost = true                                                 -- G0ku2k9 (them duoi cho khoi trung)
	elseif kind < 82 then
		base = pick(N.hero) .. pick(N.hero)                            -- GokuVegeta (hop the)
	else
		base = pick(N.fixed)
		usepost = rn() < 0.3
	end
	if usepost then post = pick(N.post) end
	local name = base .. post
	if #name > 16 then name = base end               -- qua dai: bo duoi 2k9/_VN
	if #name > 16 then name = string.sub(name, 1, 16) end
	return name
end

function AR.opp_name(rank, r)
	-- giu NGUYEN so lan goi r() nhu truoc (2 lan) de doi hinh/icon bot sinh sau do khong bi doi
	local x, y = r(), r()
	local cn = nil
	if type(S.cfg) == "table" then cn = S.cfg.ar_name end
	if type(cn) == "string" and cn ~= "" then
		cn = string.gsub(cn, "%s+", "_")
		return cn
	end
	local rn = rng(math.floor(x * 1000000007) + math.floor(y * 99991) + math.floor(tonumber(rank) or 0) * 31 + 7)
	rn(); rn()   -- bo 2 so dau (hat giong gan nhau => so dau hay giong nhau)
	return AR.rand_name(rn)
end

local function opp_name(rank, r) return AR.opp_name(rank, r) end

local function full_on() return not (type(S.cfg) == "table" and S.cfg.ar_full == false) end

function AR.opp_copy(e, rank, batch)
	rank = math.max(1, math.floor(tonumber(rank) or 1))
	batch = batch or 1
	local pool = ship_list(e)
	local r = rng(rank * 7919 + batch * 104729 + 17)
	local f = AR.factor(rank)
	local o = {
		rank = rank, id = ID_BASE + rank, name = opp_name(rank, r), icon = 1 + math.floor(r() * 8),
		level = math.max(1, my_grade(e) + (rank <= 100 and 3 or (rank <= 1000 and 1 or 0))),
		vip = math.floor(r() * 12), f = f, team = {},
	}
	o.force = math.floor(my_force(e) * f * (0.96 + 0.08 * r()))
	if #pool == 0 then return o end

	local top = math.max(12, math.floor(#pool / 2))
	if top > #pool then top = #pool end
	local picked, seen, guard = {}, {}, 0
	while #picked < 6 and guard < 400 do
		guard = guard + 1
		local c = pool[math.floor(r() * top) + 1]
		if c ~= nil and not seen[c.tid] then
			seen[c.tid] = true
			picked[#picked + 1] = c
		end
	end

	local i = 1
	while #picked < 6 and #pool > 0 do
		picked[#picked + 1] = pool[((i - 1) % #pool) + 1]
		i = i + 1
	end
	local per = math.floor(o.force / 6)
	for slot, c in ipairs(picked) do
		local s = c.ship
		o.team[slot] = { ship = s, tid = c.tid, g = math.floor(tonumber(s.ship_grade) or 1), evo = tostring(s.evolution_status or "1|0,0,0,0"),
			star = tostring(s.StarRating or 3), order = tostring(s.Order or 1), skin = tostring(s.skin_id or 0), force = per }
	end
	return o
end

local BOT_SID0 = 880000000
local NOT_IN_FIGHT = { [43] = true, [46] = true }
local MEGA_EMPTY_JSON = '{"megaLevel":{},"megaUse":[]}'

local function bot_pool()
	local ids = LS.hero_ids()
	if R.ar_pool ~= nil and R.ar_pool_src == ids then return R.ar_pool end
	local sp = {}
	for a in string.gmatch(tostring(cfg_str("ship_config", 50) or ""), "(%d+)%s*,%s*%d+") do sp[tonumber(a)] = true end
	local list, best = {}, 0
	for _, id in ipairs(ids) do
		local ab = mnum(id, "ability", 0)
		if ab > best then best = ab end
	end
	local want = math.max(17, best)
	for _, id in ipairs(ids) do
		if mnum(id, "ability", 0) >= want or sp[id] then list[#list + 1] = id end
	end
	if #list < 6 then
		local all = {}
		for _, id in ipairs(ids) do all[#all + 1] = id end
		table.sort(all, function(a, b)
			local x, y = mnum(a, "ability", 0), mnum(b, "ability", 0)
			if x ~= y then return x > y end
			return a < b
		end)
		list = {}
		for i = 1, math.min(#all, 24) do list[i] = all[i] end
	end
	-- [BOT DUNG TUONG COMBO] Tuong the Combo la LR nen LS.hero_ids() loai ra. Them cac the con hop le
	-- (the bi bo vi loi anh da bi CB.T loai san) vao kho cua bot Arena / Thap Bot / Dau truong.
	local cb_ready = false
	local cb = LS._cb
	if cb ~= nil and cb.T ~= nil then
		local okT, T = pcall(cb.T)
		if okT and type(T) == "table" and T.ok == true then
			cb_ready = true
			local have = {}
			for _, id in ipairs(list) do have[id] = true end
			for _, tid in ipairs(T.tids) do
				if not have[tid] then list[#list + 1] = tid; have[tid] = true end
			end
		end
	end
	-- chua nap xong bang Combo thi khong cache, lan sau se tinh lai va them vao
	if cb_ready then R.ar_pool, R.ar_pool_src, R.ar_sp = list, ids, sp end
	return list
end

local function lv_max()
	local v = tonumber(cfg_str("user_config", 5))
	if v == nil or v < 1 then v = 120 end
	local lim = tonumber(cfg_str("ship_config", 49))
	if lim ~= nil and lim > 0 and lim < v then v = lim end
	return math.floor(v)
end

local function skill_cap(L)
	local d, tl = G("dms"), G("talent_level_requirement")
	local mx = nil
	if type(d) == "table" and type(tl) == "table" and tl.current_level ~= nil and type(d["talent_level_requirement"]) == "table" then
		for _, row in pairs(d["talent_level_requirement"]) do
			local okv, v = pcall(d.atoi, row, tl.current_level)
			if okv and tonumber(v) ~= nil and (mx == nil or v > mx) then mx = v end
		end
	end
	if mx == nil then return L end
	return math.max(1, math.min(L, mx + 1))
end

local function evo_max(tid)
	local n = 0
	for w in string.gmatch(tostring(mstr(tid, "fitSkillTwo") or ""), "[^,]+") do
		if (tonumber(w) or 0) > 0 then n = n + 1 end
	end
	return math.max(1, n)
end

local function order_max(tid)
	local rows = grow_rows(tid)
	if rows == nil then return math.floor(mnum(tid, "initial_rank_level", 0)) end
	return #rows
end

local function shallow(t)
	local o = {}
	for k, v in pairs(t) do o[k] = v end
	return o
end

-- [FIX BOT-BUFF] Bot copy ship tu doi hinh nguoi choi nen da mang san chi so
-- da nhan mult (vd x100). Neu o.f == 1 thi scale_obj khong chay -> thu bot =
-- thu_ban * mult, cong ban = cong * mult -> ti le y nguyen, danh khong vao.
-- Giai phap: tra 4 chi so co ban ve gia tri goc (chia lai cho mult).
local function strip_bot_buff(fo)
	local mult = get_mult()
	if mult == 1 then return end
	for _, k in ipairs({ "healthPoint", "attack", "physicalDefence", "skillDefence" }) do
		local v = tonumber(fo[k])
		if v ~= nil and v > 0 then
			fo[k] = math.floor(v / mult + 0.5)
			if fo[k] < 1 then fo[k] = 1 end
		end
	end
end

local function full_consts(M)
	local c = R.ar_fullc
	if c ~= nil then return c end
	c = { L = lv_max() }
	c.SK = skill_cap(c.L)
	if WS.full_pot ~= nil then c.pot = WS.full_pot() else c.pot = "1,1,1" end
	if WS.full_stats ~= nil then
		local okw, w = pcall(WS.full_stats)
		if okw then c.ws = w end
	end

	if M.af ~= nil and M.af.T ~= nil then
		local okt, T = pcall(M.af.T)
		if okt and T.ok then
			local tot = {}
			for _, id in ipairs(T.ids) do
				local m = T.m[id]
				for _, key in ipairs(m.keys) do
					local g = m.ug[key]
					local lim = g ~= nil and T.lim[g] or nil
					local v = lim ~= nil and lim.v[lim.max] or nil
					if v ~= nil and v ~= 0 then tot[key] = (tot[key] or 0) + v end
				end
			end
			c.af = tot
		end
	end

	if M.hs ~= nil and M.hs.T ~= nil and M.hs.totals ~= nil then
		local okt, T = pcall(M.hs.T)
		if okt and type(T) == "table" and type(T.bio) == "table" then
			local a = { v = 1, a = {}, ach = {}, d = {} }
			for id, b in pairs(T.bio) do a.a[tostring(id)] = b.max end
			for _, id in ipairs(T.aids or {}) do a.ach[tostring(id)] = 1 end
			local save = S.hs
			S.hs = a
			local okh, tot = pcall(M.hs.totals)
			S.hs = save
			if okh then c.hs = tot end
		end
	end

	if M.ma ~= nil and M.ma.T ~= nil and M.ma.totals ~= nil then
		local okt, T = pcall(M.ma.T)
		if okt and type(T) == "table" and T.ok then
			local a = { v = 1, a = {}, lg = {}, sk = { -1, -1, -1 }, rel = 0, fate = { step = T.nstage, prog = 0 }, task = {} }
			for _, id in ipairs(T.ids) do
				local an = T.an[id]
				local sg, fg = T.star[an.sg], T.forge[an.fg]
				a.a[tostring(id)] = { star = sg ~= nil and sg.max or 1, stage = fg ~= nil and fg.max or 0, u = { 0, 0, 0 } }
			end
			local save = S.ma
			S.ma = a
			local okm, tot = pcall(M.ma.totals)
			S.ma = save
			if okm then c.ma = tot end
		end
	end

	if M.tl ~= nil and M.tl.T ~= nil and M.tl.bonus ~= nil then
		local okt, T = pcall(M.tl.T)
		if okt and type(T) == "table" and T.ok then
			local lv = {}
			for id, m in pairs(T.m) do if (m.max or 0) > 0 then lv[tostring(id)] = m.max end end
			c.tl = lv
		end
	end
	R.ar_fullc = c
	return c
end

local function apply_tot(pn, spec, tot)
	if type(tot) ~= "table" then return end
	for i = 1, 3 do
		local x = pn[i]
		if type(x) == "number" then
			local flat, pct = tot[i - 1] or 0, tot[i + 3] or 0
			if flat ~= 0 or pct ~= 0 then pn[i] = math.max(0, rnd(x + flat + x * pct / 100)) end
		end
	end
	if type(spec) == "table" then
		for key, v in pairs(tot) do
			if type(key) == "number" and key >= 7 and not NOT_IN_FIGHT[key] then spec[key] = (spec[key] or 0) + v end
		end
	end
end

local function sp_full_row(M, tid)
	if M.sp == nil or M.sp.T == nil or M.sp.attr_group == nil then return nil end
	local okt, T = pcall(M.sp.T)
	if not okt or type(T) ~= "table" or not T.ok then return nil end
	local okg, _, ag = pcall(M.sp.attr_group, tid, tonumber(mstr(tid, "base_mould")))
	if not okg or ag == nil or ag <= 0 then return nil end
	local a = T.mx[ag]
	local b = a ~= nil and a[T.maxs] or nil
	if b == nil then return nil end
	local lv = nil
	for k in pairs(b) do if lv == nil or k > lv then lv = k end end
	return lv ~= nil and b[lv] or nil
end

local function eq_full(tid, L, rnd)
	if EQ.max_info == nil then return nil end
	local okm, info, hard = pcall(EQ.max_info, tid, L, nil, rnd)
	if not okm or info == nil then return nil end
	local cur = EQ.stats(info, tid, hard)
	local base = EQ.stats(EQ.default_info(tid), tid, nil)
	local d = { cur[1] - base[1], cur[2] - base[2], cur[3] - base[3], cur[4] - base[4] }
	local pa, pb = cur.pct or {}, base.pct or {}
	local f, any = {}, false
	for i = 1, 4 do
		local x, y = pa[i] or 0, pb[i] or 0
		if x ~= y and 100 + y > 0 and 100 + x > 0 then f[i] = (100 + x) / (100 + y); any = true else f[i] = 1 end
	end
	if any then d.f = f end
	return d, info
end

local function copy4(d)
	local o = { d[1] or 0, d[2] or 0, d[3] or 0, d[4] or 0 }
	if d.f ~= nil then o.f = { d.f[1], d.f[2], d.f[3], d.f[4] } end
	if type(d.spec) == "table" then
		o.spec = {}
		for k, v in pairs(d.spec) do o.spec[k] = v end
	end
	return o
end

-- [BOT RANDOM BO ALL] Moi bot random 1 bo chien hon trong TOAN BO cac bo day du + random dong toi luyen
-- trang bi trong toan bo loai dong. Tat bang S.cfg.bot_rand = false. So bien the trang bi / tuong:
local BOT_EQ_BUCKETS = 3
local function bot_rand_on() return not (type(S.cfg) == "table" and S.cfg.bot_rand == false) end

function AR.bot_ship(tid, place, variant, rseed)
	variant = variant or "full"
	if variant == true then variant = "safe" end
	local safe = (variant == "safe")
	local rs, suit, eqv = tonumber(rseed), nil, 0
	if rs ~= nil and bot_rand_on() then
		local sl = (WS.suit_list ~= nil) and WS.suit_list() or {}
		if #sl > 0 then suit = sl[(math.floor(rs) % #sl) + 1] end
		eqv = (math.floor(rs / 7) % BOT_EQ_BUCKETS) + 1
	end
	local key = fint(tid) .. ":" .. fint(place) .. ":" .. variant
	if suit ~= nil then key = key .. ":s" .. fint(suit) .. ":e" .. fint(eqv) end
	R.ar_bots = R.ar_bots or {}
	local hit = R.ar_bots[key]
	if hit == false then return nil end
	if hit ~= nil then return hit end
	local M = { tl = LS._tl, af = LS._af, sp = LS._sp, cb = LS._cb, hs = LS._hs, ma = LS._ma }
	local c = full_consts(M)
	local L = c.L
	-- [BOT FULL IC/CS/SG] Bot khong lay Deck / Constellation / Soul Guard cua nguoi choi: dung ban max rieng (SG = 0).
	local ict = (LS._ic ~= nil and LS._ic.bot_tot ~= nil) and LS._ic.bot_tot() or nil
	local cst = (LS._cs ~= nil and LS._cs.bot_tot ~= nil) and LS._cs.bot_tot() or nil
	local sk = {}
	for i = 1, 6 do sk[i] = fint(c.SK) end
	local evo = evo_max(tid)
	local eqd, info = eq_full(tid, L, (eqv > 0) and rng((tonumber(tid) or 0) * 7919 + eqv * 104729 + 3) or nil)
	local mega = (WS.full_mega ~= nil) and WS.full_mega(tid) or nil
	local spr = sp_full_row(M, tid)
	local wsx = c.ws
	if suit ~= nil and WS.full_stats ~= nil then
		local okw, w = pcall(WS.full_stats, suit)
		if okw and type(w) == "table" then wsx = w end
	end
	if rs ~= nil and suit ~= nil then
		-- [BOT RANDOM] + Hop kim (Z Alloy) + Amulet ngau nhien (xac dinh theo tuong/bo/bien the => cache nhat quan)
		local rr = rng((tonumber(tid) or 0) * 104729 + (tonumber(suit) or 0) * 7919 + eqv * 131 + 29)
		local base = tonumber(mstr(tid, "base_mould")) or tonumber(tid) or 0
		local extra = { 0, 0, 0, 0, spec = {} }
		local function addx(fn, arg)
			if fn == nil then return end
			local okx, d = pcall(fn, arg, rr)
			if okx and type(d) == "table" then
				for i = 1, 4 do extra[i] = extra[i] + (d[i] or 0) end
				for t2, v in pairs(d.spec or {}) do extra.spec[t2] = (extra.spec[t2] or 0) + v end
			elseif not okx then
				R.ar_errs = (R.ar_errs or 0) + 1
				if R.ar_errs <= 5 then log("bot hop kim/amulet: loi", tostring(d)) end
			end
		end
		addx(LS._al ~= nil and LS._al.bot_stats or nil, tid)
		addx(LS._am ~= nil and LS._am.bot_stats or nil, base)
		local b0 = wsx or { 0, 0, 0, 0, spec = {} }
		local mg = { (b0[1] or 0) + extra[1], (b0[2] or 0) + extra[2], (b0[3] or 0) + extra[3], (b0[4] or 0) + extra[4], spec = {} }
		if b0.f ~= nil then mg.f = b0.f end
		for t2, v in pairs(b0.spec or {}) do mg.spec[t2] = v end
		for t2, v in pairs(extra.spec) do mg.spec[t2] = (mg.spec[t2] or 0) + v end
		wsx = mg
	end
	local camp = math.floor(mnum(tid, "camp_preference", 0) or 0)
	local ov = {
		ship_grade = L, Order = order_max(tid), StarRating = (WS.STAR_MAX or 7), skillLevel = table.concat(sk, ","),
		qianNeng = c.pot, ship_fighting_spirit = (WS.full_soul ~= nil) and WS.full_soul(tid) or nil,
		evolution_status = fint(evo) .. "|2," .. fint((evo - 1) * 2) .. ",0,0",
	}
	if info ~= nil then ov.equipInfo = info end
	local W = {
		tl = { adjust = function(sid, t2, pn, spec)
			if c.tl == nil or M.tl == nil then return end
			local b = M.tl.bonus(c.tl, place, camp)
			for i = 1, 2 do
				local x = pn[i]
				if type(x) == "number" then pn[i] = math.max(0, rnd(x + b.f[i] + x * b.p[i] / 100)) end
			end
			if type(spec) == "table" then for t, v in pairs(b.spec) do spec[t] = (spec[t] or 0) + v end end
		end },
		af = { adjust = function(sid, t2, pn, spec) apply_tot(pn, spec, c.af) end },
		sp = { adjust = function(sid, t2, pn, spec)
			if spr == nil then return end
			local flat = {}
			for _, kv in ipairs(spr.add or {}) do
				local k, v = kv[1], kv[2]
				if k >= 0 and k <= 2 then flat[k] = (flat[k] or 0) + v
				elseif k >= 7 and not NOT_IN_FIGHT[k] and type(spec) == "table" then spec[k] = (spec[k] or 0) + v end
			end
			for i = 1, 3 do
				if type(pn[i]) == "number" and flat[i - 1] ~= nil then pn[i] = math.max(0, rnd(pn[i] + flat[i - 1])) end
			end
		end, speed = function() return spr ~= nil and math.floor(spr.sp or 0) or 0 end },
		hs = { adjust = function(sid, t2, pn, spec) apply_tot(pn, spec, c.hs) end },
		ma = { adjust = function(sid, t2, pn, spec)
			if type(c.ma) ~= "table" then return end
			for i = 1, 3 do
				if type(pn[i]) == "number" and (c.ma[i] or 0) ~= 0 then pn[i] = math.max(0, rnd(pn[i] + c.ma[i])) end
			end
		end },
		ic = { adjust = function(sid, t2, pn, spec)
			if type(ict) ~= "table" or type(pn) ~= "table" then return end
			for ty = 0, 2 do
				local add = ict[ty] or 0
				if add ~= 0 and type(pn[ty + 1]) == "number" then pn[ty + 1] = math.max(0, rnd(pn[ty + 1] + add)) end
			end
			if type(spec) == "table" then
				for _, ty in ipairs({ 33, 34 }) do
					local v = ict[ty] or 0
					if v ~= 0 then spec[ty] = (spec[ty] or 0) + v * 100 end
				end
			end
		end },
		cs = { adjust = function(sid, t2, pn, spec)
			if type(cst) ~= "table" or type(pn) ~= "table" then return end
			for ty = 0, 2 do
				local v = cst[ty] or 0
				if v ~= 0 and type(pn[ty + 1]) == "number" then pn[ty + 1] = math.max(0, rnd(pn[ty + 1] + v)) end
			end
		end },
		sg = { adjust = function() end },
	}
	local save = { tl = LS._tl, af = LS._af, sp = LS._sp, cb = LS._cb, hs = LS._hs, ma = LS._ma,
		ic = LS._ic, cs = LS._cs, sg = LS._sg,
		eqd = EQ.delta_ls, wsd = WS.delta, wsm = WS.mega_delta }
	local okb, s = pcall(function()
		LS._tl, LS._af, LS._sp, LS._cb, LS._hs, LS._ma = W.tl, W.af, W.sp, nil, W.hs, W.ma
		LS._ic, LS._cs, LS._sg = W.ic, W.cs, W.sg
		if eqd ~= nil then EQ.delta_ls = function() return copy4(eqd) end end
		WS.delta = function()
			if wsx ~= nil then return copy4(wsx) end
			return { 0, 0, 0, 0, spec = {} }
		end
		WS.mega_delta = function()
			if mega ~= nil then return copy4(mega.bonus) end
			return { 0, 0, 0, 0 }
		end
		return build_ship(BOT_SID0, tid, ov)
	end)
	LS._tl, LS._af, LS._sp, LS._cb, LS._hs, LS._ma = save.tl, save.af, save.sp, save.cb, save.hs, save.ma
	LS._ic, LS._cs, LS._sg = save.ic, save.cs, save.sg
	EQ.delta_ls, WS.delta, WS.mega_delta = save.eqd, save.wsd, save.wsm
	if not okb then
		R.ar_errs = (R.ar_errs or 0) + 1
		if R.ar_errs <= 5 then log("dau truong: loi dung tuong full", tid, tostring(s)) end
		return nil
	end

	local evo0 = math.max(1, math.floor(mnum(tid, "captain_name", 1)))
	local cands = {}
	for ev = evo, 1, -1 do
		if variant == "full" then cands[#cands + 1] = { ev = ev, use = true } end
		cands[#cands + 1] = { ev = ev, use = false }
	end
	if safe then cands = { { ev = evo0, use = false } } end
	local pick, why_last = nil, nil
	for _, cd in ipairs(cands) do
		local sh = shallow(s)
		sh.evolution_status = fint(cd.ev) .. "|2," .. fint((cd.ev - 1) * 2) .. ",0,0"
		local mj = nil
		if mega ~= nil then
			mj = mega.json
			if not cd.use then mj = string.gsub(mj, '"megaUse"%s*:%s*%b[]', '"megaUse":[]') end
		end
		if cd.use and (mega == nil or #(mega.use or {}) == 0) then

		else
			local okv, why = AR.validate(sh, mj)
			if okv then pick = { ship = sh, mega = mj, ev = cd.ev, use = cd.use }; break end
			why_last = why
		end
	end
	if pick == nil then
		R.ar_bad = (R.ar_bad or 0) + 1
		if R.ar_bad <= 5 then log("dau truong: tuong", tid, "khong qua kiem tra engine:", tostring(why_last)) end
		R.ar_bots[key] = false
		return nil
	end
	local rec = { ship = pick.ship, tid = tid, mega = pick.mega, evo = tostring(pick.ship.evolution_status),
		order = tostring(s.Order), star = tostring(s.StarRating), g = math.floor(tonumber(s.ship_grade) or L),
		force = math.floor(tonumber(s.hero_fight) or 0), ev = pick.ev, use = pick.use, suit = suit, eqv = eqv }
	R.ar_bots[key] = rec
	return rec
end

function AR.validate(ship, mega_json)
	local FM = SB.classes()
	local FOC, d = G("FightObject"), G("dms")
	if FM == nil or type(FOC) ~= "table" or type(d) ~= "table" then return true end
	local e = ED()
	if e == nil or type(e.user_ship) ~= "table" then return true end
	if LS._lv ~= nil and LS._lv.fix_all ~= nil then LS._lv.fix_all() end
	local sid = tostring(ship.ship_id)
	local snap = e._fightModule
	local added_ship, added_mega = false, nil
	local ok, why = pcall(function()
		local fm = FM:new()
		fm.attackLineupSoulState, fm.defenderLineupSoulState = 2, 2
		e._fightModule = fm
		if e.user_ship[sid] == nil then e.user_ship[sid] = ship; added_ship = true end
		if type(e.mega_info) == "table" then
			added_mega = { shipId = sid, info = mega_json or MEGA_EMPTY_JSON }
			e.mega_info[#e.mega_info + 1] = added_mega
		end
		local fo = FOC:new()
		if fo:initWithUserData(1, ship, 1, BOT_SID0, fm) == false then error("history") end
		local nsm = tonumber(fo.normalSkillMould)
		if nsm ~= nil and d.element(d["skill_mould"], nsm) == nil then error("thieu ky nang thuong " .. tostring(nsm)) end
		if type(fo.commonSkill) ~= "table" or fo.commonSkill.id == nil then error("thieu ky nang chung") end
		if fo.specialSkill ~= nil and (type(fo.specialSkill) ~= "table" or fo.specialSkill.id == nil) then error("thieu ky nang dac biet") end
		for _, tm in ipairs(fo.talentMouldList or {}) do
			if type(tm) ~= "table" or tm.id == nil then error("thieu thien phu") end
		end
	end)
	e._fightModule = snap
	if added_ship then e.user_ship[sid] = nil end
	if added_mega ~= nil then
		for i = #e.mega_info, 1, -1 do
			if e.mega_info[i] == added_mega then table.remove(e.mega_info, i) end
		end
	end
	return ok, why
end

-- [XEP TRAN BOT] Xep doi hinh bot theo do trau: HP hieu dung = HP * (1 + thu / cong trung binh doi).
-- 3 tuong trau nhat dung hang truoc (slot 1-3, trau nhat o slot 1); tuong con lai o hang sau (slot 4-6),
-- sat thuong cao nhat dung dau hang sau. Truoc day slot = thu tu bot chon ngau nhien nen tuong mong co the o truoc, tank o sau.
-- Tra ve: da_doi, tong_luc_moi. Loi/khong doi duoc => giu nguyen doi hinh cu (o.team chi bi thay o buoc cuoi).
-- tong_luc_moi = tong force cac tuong sau khi doi (da nhan o.f) => AR.opp gan thang vao o.force.
-- rs_of[tid] = hat ngau nhien luc dung tuong: tuong doi hang truoc<->sau duoc dung lai dung bo do cu o hang moi (bonus hang nam trong ship).
-- Tat bang S.cfg.bot_arrange = false.
function AR.arrange_bot(o, rs_of, variant, c, rank)
	if type(S.cfg) == "table" and S.cfg.bot_arrange == false then return false end
	local team = o.team
	local n = type(team) == "table" and #team or 0
	if n < 2 then return false end
	local function stat(ship, k)
		local v = type(ship) == "table" and ship[k] or nil
		local x = tonumber(v)
		if x == nil then x = tonumber(string.match(tostring(v or ""), "^%-?%d+%.?%d*")) end
		if x == nil or x ~= x or x == math.huge or x == -math.huge then return 0 end
		return x
	end
	local hp, df, at, sum_at = {}, {}, {}, 0
	for i = 1, n do
		hp[i], df[i], at[i] = stat(team[i].ship, "ship_health"), stat(team[i].ship, "ship_intellect"), stat(team[i].ship, "ship_courage")
		sum_at = sum_at + at[i]
	end
	local avg = sum_at / n
	if avg <= 0 then return false end
	local ehp, idx = {}, {}
	for i = 1, n do
		ehp[i] = hp[i] * (1 + math.max(0, df[i]) / avg)
		idx[i] = i
	end
	table.sort(idx, function(a, b)
		if ehp[a] ~= ehp[b] then return ehp[a] > ehp[b] end
		return a < b
	end)
	local nf = math.min(3, n)
	local back = {}
	for i = nf + 1, n do back[#back + 1] = idx[i] end
	table.sort(back, function(a, b)
		if at[a] ~= at[b] then return at[a] > at[b] end
		return a < b
	end)
	-- order[s] = chi so CU cua tuong se dung o slot s moi
	local order = {}
	for i = 1, nf do order[i] = idx[i] end
	for i = 1, #back do order[nf + i] = back[i] end
	local same = true
	for s = 1, n do
		if order[s] ~= s then same = false; break end
	end
	if same then return false end
	local f = tonumber(o.f) or 1
	if f <= 0 then f = 1 end
	local newteam, total = {}, 0
	for s = 1, n do
		local old = order[s]
		local t = team[old]
		local nt = {}
		for k, v in pairs(t) do nt[k] = v end
		local row, old_row = (s <= 3) and 1 or 2, (old <= 3) and 1 or 2
		if row ~= old_row then
			local rsel = type(rs_of) == "table" and rs_of[t.tid] or nil
			if rsel == nil then return false end
			local b = AR.bot_ship(t.tid, row, variant, rsel)
			if b == nil then return false end
			nt.ship, nt.g, nt.evo, nt.star, nt.order, nt.mega = b.ship, b.g, b.evo, b.star, b.order, b.mega
			nt.force = math.floor(b.force * f)
		end
		nt.sid = fint(BOT_SID0 + (rank % 100000) * 10 + s)
		newteam[s] = nt
		total = total + (tonumber(nt.force) or 0)
	end
	o.team = newteam
	return true, total
end

function AR.opp(e, rank, batch, mode)
	do
		local rk = math.max(1, math.floor(tonumber(rank) or 1))
		local okr, real = pcall(AR.sh_opp, rk)
		if okr and real ~= nil then return real end
	end
	if not full_on() then return AR.opp_copy(e, rank, batch) end
	rank = math.max(1, math.floor(tonumber(rank) or 1))
	batch = batch or 1
	local okey = fint(rank) .. ":" .. fint(batch)
	R.ar_mode = R.ar_mode or {}
	mode = mode or R.ar_mode[okey]
	if mode == "copy" then return AR.opp_copy(e, rank, batch) end
	local safe = (mode == "safe")
	local pool = bot_pool()
	local r = rng(rank * 7919 + batch * 104729 + 17)
	local c = full_consts({ tl = LS._tl, af = LS._af, sp = LS._sp, cb = LS._cb, hs = LS._hs, ma = LS._ma })
	local o = {
		rank = rank, id = ID_BASE + rank, name = opp_name(rank, r), icon = 1 + math.floor(r() * 8),
		level = c.L, vip = math.floor(r() * 12), f = power_mult(), team = {}, full = true,
	}
	local picked, seen, guard = {}, {}, 0
	local total = 0
	local rs_of = {} -- [XEP TRAN BOT] tid -> hat ngau nhien luc dung tuong
	while #o.team < 6 and guard < 600 and #pool > 0 do
		guard = guard + 1
		local tid = pool[math.floor(r() * #pool) + 1]
		if tid ~= nil and not seen[tid] then
			seen[tid] = true
			local slot = #o.team + 1
			local rsel = math.floor(r() * 1000000) + 1
			rs_of[tid] = rsel
			local b = AR.bot_ship(tid, (slot <= 3) and 1 or 2, safe and "safe" or (mode == "nomega" and "nomega" or "full"), rsel)
			if b ~= nil then
				local sid = fint(BOT_SID0 + (rank % 100000) * 10 + slot)
				o.team[#o.team + 1] = { ship = b.ship, tid = tid, g = b.g, evo = b.evo, star = b.star, order = b.order, skin = "0",
					force = math.floor(b.force * o.f), sid = sid, mega = b.mega, bot = true }
				total = total + b.force
			end
		end
	end
	if #o.team == 0 then return AR.opp_copy(e, rank, batch) end
	o.force = math.floor(total * o.f)
	o.mode = safe and "safe" or (mode == "nomega" and "nomega" or "full")
	-- [XEP TRAN BOT] tank hang truoc, sat thuong cao dau hang sau (xem AR.arrange_bot). Loi => giu doi hinh cu.
	do
		local oka, moved, newforce = pcall(AR.arrange_bot, o, rs_of, o.mode, c, rank)
		if not oka then
			log("dau truong: xep tran bot loi -> giu doi hinh cu:", tostring(moved):sub(1, 120))
		elseif moved and tonumber(newforce) ~= nil then
			o.force = math.floor(newforce)
		end
	end
	if o.mode == "nomega" then
		for _, t in ipairs(o.team) do
			if t.mega ~= nil then t.mega = string.gsub(t.mega, '"megaUse"%s*:%s*%b[]', '"megaUse":[]') end
		end
	end
	o.okey = okey
	o.bot_team = true
	return o
end

-- [battle-fix-20261028] One immutable roster for preview, launch, and sweep.
function AR.copy_roster(value, seen)
    if type(value) ~= "table" then return value end
    seen = seen or {}
    if seen[value] ~= nil then return seen[value] end
    local copy = {}
    seen[value] = copy
    for k, v in pairs(value) do copy[k] = AR.copy_roster(v, seen) end
    return copy
end

function AR.preview(e, rank, batch)
    rank = math.max(1, math.floor(tonumber(rank) or 1))
    batch = math.max(1, math.floor(tonumber(batch) or 1))
    local epoch = tostring(batch)
    if rank <= TOP_N then epoch = "top" end
    R.ar_preview = R.ar_preview or {}
    if rank > TOP_N and R.ar_preview_epoch ~= epoch then
        for k, v in pairs(R.ar_preview) do
            if (tonumber(v.rank) or 0) > TOP_N then R.ar_preview[k] = nil end
        end
        R.ar_preview_epoch = epoch
    end
    local key = fint(rank) .. ":" .. epoch
    if R.ar_preview[key] == nil then
        R.ar_preview[key] = AR.copy_roster(AR.opp(e, rank, batch, "full"))
    end
    return R.ar_preview[key]
end

local function team_str(team)
	local parts = {}
	for _, t in ipairs(team) do
		parts[#parts + 1] = table.concat({ fint(t.tid), fint(t.g), t.evo, t.star, t.order, fint(t.force or 0), t.skin }, ":")
	end
	return table.concat(parts, "!")
end

local function my_team(e)
	local team = {}
	local f = e.formetion
	if type(f) ~= "table" then return team end
	for i = 2, 7 do
		local sid = f[i]
		local s = sid ~= nil and e.user_ship ~= nil and e.user_ship[tostring(sid)] or nil
		if type(s) == "table" then
			team[#team + 1] = { tid = tonumber(s.ship_template_id) or 0, g = math.floor(tonumber(s.ship_grade) or 1), evo = tostring(s.evolution_status or "1|0,0,0,0"),
				star = tostring(s.StarRating or 3), order = tostring(s.Order or 1), skin = tostring(s.skin_id or 0), force = math.floor(tonumber(s.hero_fight) or 0) }
		end
	end
	return team
end

function AR.near_ranks(a)
	local r = rng(a.rank * 31 + a.batch * 977 + 5)
	local out, used = {}, {}
	local cur = a.rank
	while #out < NEAR_N and cur > TOP_N + 1 do
		local gap = math.max(1, math.floor(cur * (0.02 + 0.06 * r())))
		cur = cur - gap
		if cur > TOP_N and cur ~= a.rank and not used[cur] then
			used[cur] = true
			out[#out + 1] = cur
		end
	end

	local below = a.rank + 1
	while #out < NEAR_N do
		if below > TOP_N and not used[below] and below ~= a.rank then
			used[below] = true
			out[#out + 1] = below
		end
		below = below + 1
		if below > MAX_RANK + 50 then break end
	end
	-- [SHARED ARENA] nguoi choi that (tai khoan khac) CHI xuat hien khi hang cua ho nam TRONG khoang hang ma danh sach
	-- gan do phu (tu hang xa nhat den hang cua minh) - tuc la theo dung logic hang Arena, giong bot.
	-- [FIX v6.34] Truoc day luon ep 2 acc that gan nhat vao danh sach du cach xa hang (vd minh 6877 ma luc nao cung thay 8005/8043)
	-- => bi "ghim cung". Gio acc o xa thi khong hien; muon gap thi leo/tut hang den gan, hoac ho nam dung hang bot (AR.opp tu thay).
	local lo, hi = a.rank, a.rank
	for _, v in ipairs(out) do
		if v < lo then lo = v end
		if v > hi then hi = v end
	end
	local okr, reals = pcall(AR.sh_near_real, a, lo, hi)
	if okr and type(reals) == "table" and #reals > 0 then
		local inreal, have = {}, {}
		for _, rr in ipairs(reals) do inreal[rr] = true end
		for _, v in ipairs(out) do have[v] = true end
		for _, rr in ipairs(reals) do
			if not have[rr] then
				-- thay bot co hang GAN rr nhat (khong dung vao o dang la nguoi that) => thu tu hang van hop ly
				local fi, fd = nil, nil
				for i, v in ipairs(out) do
					if not inreal[v] and AR.sh_real_at(v) == nil then
						local d = math.abs(v - rr)
						if fd == nil or d < fd then fd, fi = d, i end
					end
				end
				if fi ~= nil then
					out[fi] = rr
					have[rr] = true
				end
			end
		end
	end
	table.sort(out, function(x, y) return x > y end)
	return out
end

local function entry_from_opp(e, a, o)
	local wv = math.floor(tn(a.wv[tostring(o.rank)], 0)) + (o.rank <= TOP_N and (31 - o.rank * 2) or 0)
	return { arena_id = o.id, id = o.id, name = o.name, icon = o.icon, team = team_str(o.team), level = o.level, rank = o.rank,
		vip = o.vip, force = o.force, wv = wv }
end

local function entry_self(e, a)
	return { arena_id = tonumber(my_id(e)) or 0, id = tonumber(my_id(e)) or 0, name = my_name(e), icon = my_head(e), team = team_str(my_team(e)),
		level = my_grade(e), rank = a.rank, vip = tonumber(e.vip_grade) or 0, force = my_force(e), wv = math.floor(tn(a.wv[tostring(a.rank)], 0)) }
end

function AR.list(e, a)
	local out = {}
	for r = 1, TOP_N do
		if r == a.rank then out[#out + 1] = entry_self(e, a)
		else out[#out + 1] = entry_from_opp(e, a, AR.preview(e, r, 1)) end
	end
	for _, r in ipairs(AR.near_ranks(a)) do
		out[#out + 1] = entry_from_opp(e, a, AR.preview(e, r, a.batch))
	end
	return out
end

local function worship_state(a)

	local ids = {}
	for id in pairs(a.wor) do ids[#ids + 1] = tonumber(id) end
	table.sort(ids)
	local t = { fint(a.wn) }
	for _, id in ipairs(ids) do t[#t + 1] = fint(id) end
	return table.concat(t, ",")
end

local function csv_ids(set)
	local ids = {}
	for k in pairs(set) do ids[#ids + 1] = tonumber(k) end
	table.sort(ids)
	local t = { "0" }
	for _, id in ipairs(ids) do t[#t + 1] = fint(id) end
	return table.concat(t, ",")
end

function AR.blk45(e)
	local a = st()
	local now_ms = (os.time() + (tonumber(e.time_add_or_sub) or 0)) * 1000
	local b = {
		"45", "0", "0", fint(now_ms + 3600 * 1000), "0",
		fint(a.rank), "0", "0", fint(my_head(e)),
		"0", "0", "0", "0",
		"0", "0", fint(FREE_TIMES), fint(a.win), "0", "0",
	}
	local list = AR.list(e, a)
	b[#b + 1] = fint(#list)
	for _, en in ipairs(list) do
		for _, v in ipairs({ en.arena_id, en.id, en.name, en.icon, en.team, "0", "0", "0", en.level, en.rank, "0", "0", "0", en.vip, "0", "Saiyan", en.force, en.wv, "-1", "-1" }) do
			b[#b + 1] = tostring(v)
		end
	end
	local logs = a.logs
	b[#b + 1] = fint(#logs)
	for _, l in ipairs(logs) do
		for _, v in ipairs({ l.tag, l.name, l.win, l.chg, fint(l.t) }) do b[#b + 1] = tostring(v) end
	end
	b[#b + 1] = fint(my_force(e))
	b[#b + 1] = "0"
	b[#b + 1] = "0"
	b[#b + 1] = worship_state(a)
	b[#b + 1] = csv_ids(a.dr)
	b[#b + 1] = csv_ids(a.ds)
	b[#b + 1] = fint(a.score)
	b[#b + 1] = fint(a.best)
	return table.concat(b, "\r\n")
end

local function classes()
	local FM = SB.classes()
	local fo = G("FightObject")
	local cdb = G("ConfigDB")
	if FM == nil or type(fo) ~= "table" or type(cdb) ~= "table" then return nil end
	return FM, fo, cdb
end

local function scale_obj(fo, f)
	for _, k in ipairs({ "healthPoint", "attack", "physicalDefence", "skillDefence" }) do
		local v = tonumber(fo[k])
		if v ~= nil then fo[k] = math.floor(v * f + 0.5) end
	end
end

local function watchdog_start(budget, progress)
	local budget_sec = tonumber(budget) or 0
	if budget_sec <= 0 then return nil end
	local dbg = G("debug")
	if type(dbg) ~= "table" or type(dbg.sethook) ~= "function" then return nil end
	local w = { dbg = dbg, progress = progress == true }
	local j = G("jit")
	if type(j) == "table" and type(j.status) == "function" and type(j.off) == "function" then
		local okst, on = pcall(j.status)
		if okst and on then
			w.j = j
			pcall(j.off)
			if type(j.flush) == "function" then pcall(j.flush) end
		end
	end
	if type(dbg.gethook) == "function" then w.oh, w.om, w.oc = dbg.gethook() end
	w.t0 = os.clock()
	w.started = w.t0
	-- Lua 5.1 / luajit luu hook trong registry theo TEN toan cuc `debug`. Neu script
	-- khac (json.lua) ghi de `debug` bang ban sao cua table hoac dat lai hook thi
	-- watchdog bien mat; khi do khong con ai cat vong lap -> R.ar_watchdog = 0.
	-- Giu lai ban `debug` that de watchdog_stop luon go duoc hook.
	w.rdbg = rawget(_G, "debug")
	w.hooked = pcall(dbg.sethook, function()
		local now = os.clock()
		if w.progress and now - w.started > 30 then
			R.ar_watchdog = (R.ar_watchdog or 0) + 1
			error("LS_watchdog: tong thoi gian tinh tran qua 30 giay", 2)
		end
		if now - w.t0 > budget_sec then
			R.ar_watchdog = (R.ar_watchdog or 0) + 1
			local phase = w.progress and "buoc tinh tran qua " or "tran qua "
			error("LS_watchdog: " .. phase .. tostring(budget_sec) .. " giay", 2)
		end
	end, "", 20000)
	return w
end

-- Arena co the can hon 4 giay cho nhieu round hop le. Chi reset khi engine da
-- tra ve tu mot buoc; vong lap ben ngoai van giu gioi han 30 giay / so buoc.
-- Budget rieng cua tran thu thap / Tournament van tinh tren TOAN BO tran.
local function watchdog_touch(w)
	if w ~= nil and w.progress then w.t0 = os.clock() end
end

local function watchdog_stop(w)
	if w == nil then return end
	-- Go hook qua CA HAI tham chieu: `debug` hien tai va ban goc luc bat watchdog.
	-- Lua giu hook theo ten global `debug`, nen neu script khac ghi de global nay
	-- thi go tren `w.dbg` se khong co tac dung va hook cu van con treo.
	pcall(w.dbg.sethook)
	if w.rdbg ~= nil and w.rdbg ~= w.dbg then pcall(w.rdbg.sethook) end
	if w.oh ~= nil then pcall(w.dbg.sethook, w.oh, w.om, w.oc) end
	if w.j ~= nil then pcall(w.j.on) end
end

local function wd_budget()
	local v = type(S.cfg) == "table" and tonumber(S.cfg.ar_watchdog) or nil
	if v == nil or v <= 0 then v = 4 end
	return v
end

-- [v6] AR.run = vo boc: ghi moc SIM+/SIM- (bo nho Lua truoc/sau, thoi gian) vao hop den. Game chet GIUA LUC mo phong => lan sau
-- thay SIM+ khong co SIM-. Loi o day KHONG bao gio lam hong tran (moi loi duoc nuot).
function AR.run(e, o)
	local t0, k0 = os.clock(), collectgarbage("count")
	local bb = H.bb_event
	if bb ~= nil then
		pcall(bb, "SIM+", string.format("bot=%s rank=%s lua=%.1fMB", tostring(o ~= nil and o.bot_team and "1" or "0"),
			tostring(o ~= nil and o.rank or "-"), k0 / 1024))
	end
	local res, err = AR.run_core(e, o)
	if bb ~= nil then
		local k1 = collectgarbage("count")
		pcall(bb, "SIM-", string.format("ok=%s rounds=%s cut=%s ms=%.0f lua=%.1fMB delta=%.1fMB err=%s", res ~= nil and "1" or "0",
			tostring(res ~= nil and res.rounds or "-"), tostring(res ~= nil and res.cut or "-"), (os.clock() - t0) * 1000,
			k1 / 1024, (k1 - k0) / 1024, err ~= nil and string.sub(tostring(err), 1, 80) or "-"))
	end
	return res, err
end

-- [HOP THE BOT] module Fusion (client.offline.Fusion) KHONG phai bien toan cuc: OfflineMock nap bang require => lay tu package.loaded (chua co thi thu require, toi da 3 lan).
function AR.fusion_mod()
	local m = package.loaded["client.offline.Fusion"]
	if type(m) ~= "table" and (AR._fu_req or 0) < 3 then
		AR._fu_req = (AR._fu_req or 0) + 1
		local ok, r = pcall(require, "client.offline.Fusion")
		if ok then m = r end
	end
	if type(m) == "table" then return m end
	return nil
end

function AR.run_core(e, o)
	local FM, FOC, CDB = classes()
	if FM == nil then return nil, "khong nap duoc engine tran" end
	local FU = AR.fusion_mod() -- [HOP THE BOT] Fusion.lua (fu-2.7): moi tran mo phong bat dau bang bang than hop the cua bot rong
	if type(FU) == "table" and type(FU.foe_clear) == "function" then pcall(FU.foe_clear) end
	if LS._lv ~= nil and LS._lv.fix_all ~= nil then LS._lv.fix_all() end

	if LS._ts ~= nil and LS._ts.force_for_fight ~= nil then
		pcall(LS._ts.force_for_fight, e)
	elseif LS._ts ~= nil and LS._ts.update ~= nil then
		pcall(LS._ts.update, e)
	end
	local scene, npc_id = WB.boss_data(1)
	if tonumber(npc_id) == nil or npc_id <= 0 then return nil, "khong co npc mau" end
	local snap = { fm = e._fightModule, ad = e.attackData, bc = e.user_info.battleCache,
		sn = e._scene_npc_id, cs = e._current_scene_id, nd = e._npc_difficulty_index,
		as = e.attackShiftValue, ps = e.physicalDefenceShiftValue, hs = e.healthShiftValue,
		speed = e.user_info.speed_sum }
	local out
	local phase, actions = "init", 0
	local added = { ships = {}, mega = {} }
	-- [FIX buff dau tran] khoi 14710-14714 (buff dau tran / dau round / doi phe) do engine tu day cho parser client luc mo phong
	-- roi bi xoa khi client parse lai khoi init (tao _ED.battleData moi). Bat lai de gui kem trong phan hoi dau truong.
	local inf_cap, inf_np, inf_orig = {}, nil, nil
	local wd = o.bot_team and watchdog_start(o.budget or wd_budget(), o.budget == nil) or nil
	local ok, err = xpcall(function()
		e._scene_npc_id = npc_id
		e._current_scene_id = tostring(scene)
		e._npc_difficulty_index = "1"
		local fm = FM:new()
		-- Arena: stop immediate self-refill chains, not merely after 32 supers.
		-- Trial/tournament reuses battle type 11 with an explicit budget.
		fm._lsArenaChainBypass = o.budget ~= nil
		if o.bot_team and (o.budget == nil or o.tower_bot == true) then
			fm._lsSuperChainLimit = 1
			fm._lsBattleChainLimit = function(obj, count)
				log(o.tower_bot == true and "thap bot: defer super chain" or "dau truong: defer super chain", "round=" .. tostring(fm.roundCount),
					"camp=" .. tostring(obj.battleTag), "slot=" .. tostring(obj.coordinate),
					"tid=" .. tostring(obj.shipMould), "skill=" .. tostring(obj.specialSkillMould and obj.specialSkillMould.id),
					"casts=" .. tostring(count), "sp=" .. tostring(obj.skillPoint))
			end
		end
		-- A round may contain many completed skill effects. Reset the idle budget
		-- after each completed effect, never on entry/recursive calls. The hook
		-- still enforces the independent 30-second total deadline.
		fm._lsBattleProgress = function()
			actions = actions + 1
			phase = "skill_done:" .. tostring(actions) .. ":round:" .. tostring(fm.roundCount)
			local actor = fm.currentObject
			if actor ~= nil then
				phase = phase .. ":camp:" .. tostring(actor.battleTag) .. ":slot:" .. tostring(actor.coordinate)
					.. ":tid:" .. tostring(actor.shipMould) .. ":sp:" .. tostring(actor.skillPoint)
			end
			watchdog_touch(wd)
		end
		e._fightModule = fm
		e.attackData = { roundCount = fm.totalRound, roundData = {} }
		local npc = CDB.load("npc", npc_id)
		local rb = {}
		fm:initBattleField(npc, "1", tonumber(o.btype) or 11, rb, nil, false) -- [FRIEND] o.btype=13: khieu chien ban be
		watchdog_touch(wd)
		local bc = e.user_info.battleCache
		if type(bc) ~= "table" then error("khong co battleCache") end
		local objs, spd = {}, 0
		-- [HOP THE BOT] ke hoach ngau nhien (Fusion.bot_plan): 1 than chinh + 1-2 tuong phu LAY TU CHINH doi hinh bot (cac o cuoi => cac o con lai van 1..m).
		-- [fu-2.8] Mac dinh (Fusion.bot.keep_team) tuong phu VAN o lai doi hinh (fplan.skip rong) - chi la nguon cho than hop the; keep_team = false => bi loai nhu fu-2.7.
		-- Kiem tra truoc bang ban sao (chua dang ky gi). Loi o bat ky buoc nao => bot danh binh thuong, khong bao gio lam hong tran.
		local fplan = nil
		if o.arena_fuse == true and type(FU) == "table" and type(FU.bot_plan) == "function" and type(FU.bot_fuse) == "function" then
			local okp, pl = pcall(function()
				if FU.bot_ready ~= nil and not FU.bot_ready() then return nil end
				local plan = FU.bot_plan(o)
				if plan == nil then return nil end
				for li, grp in pairs(plan.lead_of) do
					local lt = o.team[li]
					if type(lt) ~= "table" or type(lt.ship) ~= "table" then error("than chinh thieu ho so", 0) end
					local ships = { AR.copy_roster(lt.ship) }
					for _, mi in ipairs(grp.partners) do
						local pt = o.team[mi]
						if type(pt) ~= "table" or type(pt.ship) ~= "table" then error("tuong phu thieu ho so", 0) end
						ships[#ships + 1] = AR.copy_roster(pt.ship)
					end
					local f, why = FU.bot_fuse(ships)
					if type(f) ~= "table" then error(tostring(why or "bot_fuse nil"), 0) end
				end
				return plan
			end)
			if okp then fplan = pl else log("dau truong: hop the bot loi -> bot danh binh thuong:", tostring(pl):sub(1, 120)) end
		end
		-- ban sao ho so + dang ky tuong bot tam thoi (e.user_ship / mega_info); go lai o cuoi AR.run_core
		local mega_done = {} -- [fu-2.8] tuong phu cua bot van o lai doi hinh => foe_prep chay 2 lan cho cung 1 tuong: chi dang ky mega_info 1 lan / tuong
		local function foe_prep(t)
			local ship = AR.copy_roster(t.ship)
			if t.bot then
				ship.ship_id = t.sid
				if e.user_ship[t.sid] == nil then
					e.user_ship[t.sid] = ship
					added.ships[#added.ships + 1] = t.sid
				end
				local mkey = tostring(t.sid)
				if type(e.mega_info) == "table" and not mega_done[mkey] then
					mega_done[mkey] = true
					local en = { shipId = t.sid, info = t.mega or MEGA_EMPTY_JSON }
					e.mega_info[#e.mega_info + 1] = en
					added.mega[#added.mega + 1] = en
				end
			end
			return ship
		end
		for i, t in ipairs(o.team) do
			if not (fplan ~= nil and fplan.skip[i]) then
				phase = "foe_init:" .. tostring(i) .. ":tid:" .. tostring(t.tid)
				local ship = foe_prep(t)
				local fships = nil -- khac nil: than chinh hop the (fships[1] = than chinh, [2..] = tuong phu)
				local grp = fplan ~= nil and fplan.lead_of[i] or nil
				if grp ~= nil then
					local okf, fused, mships = pcall(function()
						local ships = { ship }
						for _, mi in ipairs(grp.partners) do ships[#ships + 1] = foe_prep(o.team[mi]) end
						local f, why = FU.bot_fuse(ships)
						if type(f) ~= "table" then error(tostring(why or "bot_fuse nil"), 0) end
						return f, ships
					end)
					if okf and type(fused) == "table" then
						if t.bot and e.user_ship[t.sid] == ship then e.user_ship[t.sid] = fused end -- ho so dang ky cung la ban hop the (chi khi la ban cua minh)
						ship, fships = fused, mships
					else
						-- tuong phu o phia SAU than chinh (chi so lon hon) => tra lai cho chung danh binh thuong
						for _, mi in ipairs(grp.partners) do fplan.skip[mi] = nil end
						log("dau truong: ghep chi so hop the bot loi -> khong hop the:", tostring(fused):sub(1, 120))
					end
				end
				local fo = FOC:new()
				fo:initWithUserData(i, ship, 1, o.id, fm)
				if t.bot and not t.real then strip_bot_buff(fo) end
				if o.f ~= 1 then scale_obj(fo, o.f) end
				fo.id = o.id * 10 + i
				if fships ~= nil then
					phase = "foe_fusion:" .. tostring(i)
					local okfin, errfin = pcall(FU.bot_finish, fo, fships, function(s)
						local po = FOC:new()
						po:initWithUserData(i, s, 1, o.id, fm)
						return po
					end)
					if okfin then
						stat_inc("ar_bot_fusion")
						log("dau truong: bot hop the - than chinh o", i, "tid=" .. tostring(t.tid), "+", #fships - 1, "tuong phu (o cuoi)",
							(fplan ~= nil and fplan.keep) and "- van o lai doi hinh" or "- bi loai khoi tran")
					else
						log("dau truong: gop talent/buff/than hop the cua bot loi (giu chi so da ghep):", tostring(errfin):sub(1, 120))
					end
				end
				objs[i] = fo
				spd = spd + (tonumber(fo.attackSpeed) or 0)
				watchdog_touch(wd)
			end
		end
		if next(objs) == nil then error("doi thu rong") end
		bc.byAttackerObjectsList = { objs }
		bc.maxBattleCount = 1
		bc.byAttackName = o.name
		bc.defender_name = o.name

		local mine_spd = tonumber(e.ship_all_speed_info) or tonumber(e.user_info.speed_sum) or 0
		if mine_spd < 0 then mine_spd = 0 end
		bc.attackerSpeedValue = mine_spd
		if objs[1] ~= nil then objs[1].attackSpeed = spd end
		bc.defender_priority = spd
		bc.byAttackComobatForce = o.force
		fm:writeBattleFieldInit(bc, 0, 1, rb)
		watchdog_touch(wd)
		table.insert(rb, 1, 100)
		table.insert(rb, 2, "\r\n")
		table.insert(rb, 3, "battle_field_init")
		table.insert(rb, 4, "\r\n")
		table.insert(rb, 5, "0")
		table.insert(rb, 6, "\r\n")
		for i = 1, #rb do
			local tv = type(rb[i])
			if tv ~= "string" and tv ~= "number" then
				R.ar_badtok = (R.ar_badtok or 0) + 1
				if R.ar_badtok <= 3 then log("dau truong: khoi 182 phan tu " .. i .. " la " .. tv .. " -> 0") end
				rb[i] = "0"
			end
		end
		local init = table.concat(rb, "")
		local np = G("NetworkProtocol")
		if type(np) == "table" and type(np.parser_func) == "function" then np.parser_func({ resouce = init }) end
		watchdog_touch(wd)
		local HDR = "100\r\nbattle_field_init\r\n0\r\n"
		if string.sub(init, 1, #HDR) ~= HDR then error("tieu de battle_field_init la: " .. string.sub(init, 1, 40)) end
		init = string.gsub(string.sub(init, #HDR + 1), "[\r\n]+$", "")

		local live_bc = e.user_info.battleCache
		if type(live_bc) == "table" then
			live_bc.attackerSpeedValue = mine_spd
			live_bc.defender_priority = spd
			local live_foes = live_bc.byAttackerObjectsList
				and live_bc.byAttackerObjectsList[1]
			if type(live_foes) == "table" and live_foes[1] ~= nil then live_foes[1].attackSpeed = spd end
		end
		phase = "fight_order"
		inf_np = G("NetworkProtocol")
		if type(inf_np) == "table" and type(inf_np.parser_func) == "function" then
			inf_orig = inf_np.parser_func
			inf_np.parser_func = function(data, ...)
				if type(data) == "table" and type(data.resouce) == "string" then
					local _, _, rest = string.find(data.resouce, "^[^\r\n]*\r\n[^\r\n]*\r\n[^\r\n]*\r\n(.*)$")
					local code = rest ~= nil and tonumber(string.match(rest, "^(%d+)")) or nil
					if code ~= nil and code >= 14710 and code <= 14714 then
						if #inf_cap < 4000 then inf_cap[#inf_cap + 1] = (string.gsub(rest, "[\r\n]+$", "")) end
						return
					end
				end
				return inf_orig(data, ...)
			end
		else
			inf_np, inf_orig = nil, nil
		end
		fm:initFightOrder(e.user_info, {})
		watchdog_touch(wd)
		R.ar_speed_last = { mine = mine_spd, foe = spd, first = (mine_spd >= spd) and "ban" or "dich" }
		local chunks, guard, cut = {}, 0, false
		local t0 = os.clock()
		local cap = (LS._inf ~= nil and LS._inf.cap ~= nil) and LS._inf.cap() or 200
		local limit = math.max(cap, tonumber(fm.totalRound) or 0) * 4 + 100
		while fm.hasNextRound == true do
			guard = guard + 1
			if guard > limit or os.clock() - t0 > 30 then cut = true; break end
			local rc = fm.roundCount
			phase = "round:" .. tostring(rc) .. ":effects:" .. tostring(actions)
			local buf = {}
			fm:rountdFight(buf)
			watchdog_touch(wd)
			for i = 1, #buf do
				local tv = type(buf[i])
				if tv ~= "string" and tv ~= "number" then
					R.ar_badtok = (R.ar_badtok or 0) + 1
					if R.ar_badtok <= 3 then log("dau truong: round " .. tostring(rc) .. " phan tu " .. i .. " la " .. tv .. " -> 0 (truoc: " .. tostring(buf[i - 2]) .. "," .. tostring(buf[i - 1]) .. ")") end
					buf[i] = "0"
				end
			end
			chunks[#chunks + 1] = { round = rc, text = table.concat(buf, "") }
			if rc ~= fm.roundCount then fm:resetAllRoleSkillStatus() end
		end
		local body, nr = SB.wire(chunks)
		if body == nil then error(nr) end
		local win = (cut and 0) or (tonumber(fm.fightResult) or 0)
		out = { init = init, body = body, nr = nr, win = win, total = tonumber(fm.totalRound) or nr,
			rounds = tonumber(fm.roundCount) or nr, cut = cut,
			inf = (#inf_cap > 0) and table.concat(inf_cap, "\r\n") or nil }
	end, function(err)
		-- Go hook truoc khi tao traceback de timeout khong ngat ca nhanh don dep.
		watchdog_stop(wd)
		wd = nil
		return traceback(err)
	end)
	watchdog_stop(wd)
	e._fightModule, e.attackData, e.user_info.battleCache = snap.fm, snap.ad, snap.bc
	e._scene_npc_id, e._current_scene_id, e._npc_difficulty_index = snap.sn, snap.cs, snap.nd
	e.attackShiftValue, e.physicalDefenceShiftValue, e.healthShiftValue = snap.as, snap.ps, snap.hs
	if inf_np ~= nil and inf_orig ~= nil then inf_np.parser_func = inf_orig end
	e.user_info.speed_sum = snap.speed
	for _, k in ipairs(added.ships) do e.user_ship[k] = nil end
	if #added.mega > 0 and type(e.mega_info) == "table" then
		local drop = {}
		for _, en in ipairs(added.mega) do drop[en] = true end
		for i = #e.mega_info, 1, -1 do
			if drop[e.mega_info[i]] then table.remove(e.mega_info, i) end
		end
	end
	if not ok then
		return nil, "phase=" .. phase .. " effects=" .. tostring(actions) .. "\n" .. tostring(err)
	end
	return out
end

-- Keep an uncapped, standalone latest-error report: the general LS log has a
-- 4,000-line session cap. A failed fight must never settle rank or rewards.
function AR.report_error(o, err, command)
	local roster = {}
	for i, t in ipairs(o.team or {}) do
		roster[#roster + 1] = tostring(i) .. ":" .. tostring(t.tid)
	end
	local text = os.date("%Y-%m-%d %H:%M:%S") .. " " .. LS.VERSION
		.. "\ncommand=" .. tostring(command) .. " rank=" .. tostring(o.rank)
		.. " team=" .. table.concat(roster, ",") .. "\n" .. tostring(err) .. "\n"
	if H.write_first ~= nil then pcall(H.write_first, "offline_arena_last_error.txt", text) end
	log("dau truong:", text)
end

function AR.vet_team(e, o)
	if not o.bot_team then return 0 end
	R.ar_vet = R.ar_vet or {}
	local changed = 0
	for i, t in ipairs(o.team) do
		local key = fint(t.tid) .. ":" .. ((i <= 3) and "1" or "2")
		local v = R.ar_vet[key]
		if v == nil and t.mega ~= nil and not string.find(t.mega, '"megaUse":[]', 1, true) then
			local solo = { rank = o.rank, id = ID_BASE + 99999, name = o.name, f = 1, force = t.force, bot_team = true, budget = 2,
				team = { { ship = t.ship, tid = t.tid, sid = t.sid, mega = t.mega, bot = true, g = t.g, evo = t.evo, star = t.star, order = t.order, skin = "0", force = t.force } } }
			local res, err = AR.run(e, solo)
			if res == nil then
				v = "nomega"
				R.ar_vet_bad = (R.ar_vet_bad or 0) + 1
				log("dau truong: tuong", t.tid, "ky nang Kame lam engine loi -> bo ky nang Kame:", tostring(err):sub(1, 120))
			else
				v = "ok"
			end
			R.ar_vet[key] = v
		end
		if v == "nomega" and t.mega ~= nil then
			t.mega = string.gsub(t.mega, '"megaUse"%s*:%s*%b[]', '"megaUse":[]')
			changed = changed + 1
		end
	end
	return changed
end

-- [HOP THE BOT] ban sao doi thu cho tran Arena thuong (bot, khong phai nguoi choi that / thap bot / giai dau / ban be): bat co arena_fuse =>
-- AR.run_core hoi Fusion.bot_plan co ghep ngau nhien tuong cua bot thanh than hop the khong. Tat het: S.cfg.bot_fusion = false.
function AR.arena_copy(o)
    local c = AR.copy_roster(o)
    if type(c) == "table" and c.bot_team and not c.real and c.budget == nil and c.tower_bot ~= true
        and (c.btype == nil or tonumber(c.btype) == 11)
        and not (type(S.cfg) == "table" and S.cfg.bot_fusion == false) then
        c.arena_fuse = true
    end
    return c
end

function AR.run_safe(e, o, rank, batch)
    -- Run a private copy. A failing simulation must not regenerate heroes, lower
    -- evolution, or replace the preview with the player's copied formation.
    local oc = AR.arena_copy(o)
    local res, err = AR.run(e, oc)
    if res == nil and oc.arena_fuse == true then
        -- [HOP THE BOT] tran co hop the loi engine => chay lai y nguyen doi hinh nhung KHONG hop the (khong de hop the lam hong tran Arena)
        log("dau truong: tran co bot hop the loi engine -> chay lai khong hop the:", tostring(err):sub(1, 120))
        res, err = AR.run(e, AR.copy_roster(o))
    end
    if res == nil and o ~= nil and o.real == true then
        R.sh_bad = R.sh_bad or {}
        R.sh_bad[tostring(o.real_key)] = true
        log("dau truong: doi hinh nguoi choi", tostring(o.name), "loi engine -> doi bot cung hang:", tostring(err):sub(1, 160))
        R.ar_preview, R.ar_preview_epoch = nil, nil
        local bot = AR.opp(e, rank, batch, "full")
        res, err = AR.run(e, AR.arena_copy(bot))
        return res, bot, err
    end
    if res == nil then
        log("dau truong: giu nguyen doi da hien thi, khong thay doi thu khi loi:", tostring(err):sub(1, 160))
    end
    return res, o, err
end

function AR.settle(e, a, o, win)
	local before = a.rank
	local w, l = score_points()
	a.score = a.score + (win and w or l)
	local chg = 0
	if win then
		a.win = a.win + 1
		if o.rank < a.rank then
			a.rank = o.rank
			chg = before - a.rank
			if a.rank < a.best then a.best = a.rank end
		end
	else
		a.lose = a.lose + 1
	end
	table.insert(a.logs, 1, { tag = "1", name = o.name, win = win and "1" or "0", chg = fint(chg), t = (os.time() + (tonumber(e.time_add_or_sub) or 0)) * 1000 })
	while #a.logs > LOG_MAX do table.remove(a.logs) end
	if o.real == true then pcall(AR.sh_after_fight, e, a, o, win, before) end
	return before, a.rank
end

-- [BOT KHIEU CHIEN] Bot tu thach dau nguoi choi nhu nguoi that.
-- Moi ~25-60 phut (thoi gian that, ke ca luc offline, toi da 6 tran/lan) co the co bot hang thap hon
-- khieu chien. Ket qua theo ti le luc; bot thang => nguoi choi tut hang (doi cho). Ghi vao nhat ky voi gio rai deu.
-- [BOT KHIEU CHIEN v3] 2 che do (khong dung local moi de tranh vuot gioi han 200 local):
--  * DANG TRONG GAME: moi cua so 5 phut co dung 1 tran, vao giay ngau nhien 0..299 (khong co dinh gio).
--  * KHONG VAO GAME (thoat game / may ngu > 10 phut): MOI GIO random 1-5 lan, moi lan vao giay ngau nhien trong gio do
--    (gio le dau/cuoi tinh theo ti le), toi da 24 tran gan nhat moi lan quay lai. Nhat ky ghi dung gio cua tung moc. Nhip dong ho a.sim_t luu cung state.
-- =====================================================================================================
-- [SHARED ARENA v1] KHO NGUOI CHOI CHUNG cho moi tai khoan (offline_arena_shared.txt) => cac tai khoan tren cung
-- may gap nhau va danh nhau o Arena.
--   * Moi tai khoan DA DANG NHAP ghi 1 ban chup (ten tai khoan, hang, luc chien, doi hinh toi da 6 tuong) vao file CHUNG.
--   * Tai khoan khac chiem hang nao thi o hang do trong Arena la ho (AR.opp) thay vi bot; toi da 2 nguoi
--     choi that gan hang nhat luon duoc chen vao danh sach (AR.near_ranks).
--   * Thang nguoi that => doi hang (ho nhan hang cu cua ban) + ho nhan 1 dong nhat ky khi vao Arena lan sau.
--   * Doi hinh nguoi that chay loi engine => tu dong dung bot cung hang (AR.run_safe), khong lam ket tran.
--   * Chua dang nhap bang tai khoan (LS._acct.user == nil) => khong dung kho chung, Arena chay nhu cu.
-- =====================================================================================================
AR.SH_FILE = "offline_arena_shared.txt"
AR.SH_TTL  = 3   -- giay: thoi gian giu ban doc file trong bo nho

function AR.st_ar() return st() end

function AR.sh_key()
	local u = LS._acct ~= nil and LS._acct.user or nil
	if u == nil or u == "" then return nil end
	return string.lower(tostring(u))
end

function AR.sh_read(force)
	local now = os.time()
	if not force and R.sh_cache ~= nil and R.sh_cache_t ~= nil and now - R.sh_cache_t < AR.SH_TTL then return R.sh_cache end
	local db = nil
	if H.read_first ~= nil then
		local ok, txt = pcall(H.read_first, AR.SH_FILE)
		if ok and type(txt) == "string" and #txt > 2 then
			local t = deser(txt)
			if type(t) == "table" and type(t.players) == "table" then db = t end
		end
	end
	if db == nil then db = { v = 1, players = {} } end
	R.sh_cache, R.sh_cache_t = db, now
	return db
end

function AR.sh_write(db)
	if H.write_first == nil then return false end
	local buf = {}
	local ok, err = pcall(ser, db, buf)
	if not ok then log("arena chung: loi ghi:", tostring(err)); return false end
	pcall(H.write_first, AR.SH_FILE, table.concat(buf))
	R.sh_cache, R.sh_cache_t = db, os.time()
	return true
end

-- Sao chep an toan (so / chuoi / boolean / bang long nhau toi da 6 cap; bo qua ham, userdata, vong lap).
function AR.sh_clean(v, depth, seen)
	local t = type(v)
	if t == "number" or t == "string" or t == "boolean" then return v end
	if t ~= "table" or depth > 6 then return nil end
	seen = seen or {}
	if seen[v] then return nil end
	seen[v] = true
	local out = {}
	for k, x in pairs(v) do
		local tk = type(k)
		if tk == "string" or tk == "number" then
			local c = AR.sh_clean(x, depth + 1, seen)
			if c ~= nil then out[k] = c end
		end
	end
	seen[v] = nil
	return out
end

function AR.sh_snapshot(e, a)
	if AR.sh_key() == nil then return nil end
	local team = {}
	local f = e.formetion
	if type(f) == "table" and type(e.user_ship) == "table" then
		for i = 2, 7 do
			local sid = f[i]
			local s = sid ~= nil and e.user_ship[tostring(sid)] or nil
			if type(s) == "table" and tonumber(s.ship_template_id) ~= nil then
				local mega = MEGA_EMPTY_JSON
				if type(e.mega_info) == "table" then
					for _, en in ipairs(e.mega_info) do
						if type(en) == "table" and tostring(en.shipId) == tostring(sid) and type(en.info) == "string" then mega = en.info; break end
					end
				end
				team[#team + 1] = { ship = AR.sh_clean(s, 1, nil), tid = tonumber(s.ship_template_id), g = math.floor(tonumber(s.ship_grade) or 1),
					evo = tostring(s.evolution_status or "1|0,0,0,0"), star = tostring(s.StarRating or 3), order = tostring(s.Order or 1),
					skin = tostring(s.skin_id or 0), force = math.floor(tonumber(s.hero_fight) or 0), mega = mega }
			end
		end
	end
	return { user = tostring(LS._acct.user), uid = math.floor(tonumber(LS._acct.uid) or 0), name = my_name(e), icon = my_head(e),
		level = my_grade(e), vip = math.floor(tonumber(e.vip_grade) or 0), force = my_force(e), rank = a.rank,
		rank_t = tonumber(a.sh_t) or 0, t = os.time(), team = team }
end

-- Ghi ban chup cua tai khoan hien tai vao kho chung (giu hang / nhat ky cho moi hon tren file neu co).
function AR.sh_publish(e, a)
	local key = AR.sh_key()
	if key == nil or R.inject ~= nil then return false end -- the gioi con dang dung lai tuong => doi hinh chua day du
	local snap = AR.sh_snapshot(e, a)
	if snap == nil or #snap.team == 0 then return false end
	local db = AR.sh_read(true)
	local old = db.players[key]
	if old ~= nil then
		if (tonumber(old.rank_t) or 0) > (tonumber(a.sh_t) or 0) then snap.rank, snap.rank_t = old.rank, old.rank_t end
		snap.pend = old.pend
	end
	db.players[key] = snap
	R.sh_pub_t = os.time()
	return AR.sh_write(db)
end

function AR.sh_publish_current()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or S == nil or not R.ready or AR.sh_key() == nil then return false end
	return AR.sh_publish(e, st())
end

-- Nap hang moi (do nguoi khac vua danh doi) + nhat ky cho tu kho chung vao tai khoan hien tai.
-- Tai khoan hoan toan moi (chua tung dat hang) duoc cap hang khoi dau KHAC cac nguoi choi khac.
function AR.sh_sync(e, a)
	local key = AR.sh_key()
	if key == nil then return false end
	local db = AR.sh_read(true)
	local me = db.players[key]
	local changed = false
	if me == nil then
		if a.sh_t == nil and a.win == 0 and a.lose == 0 and #a.logs == 0 then
			local used = {}
			for _, pl in pairs(db.players) do
				if type(pl) == "table" then used[math.floor(tonumber(pl.rank) or 0)] = true end
			end
			local r = START_RANK
			while used[r] and r < MAX_RANK do r = r + 1 end
			if r ~= a.rank then a.rank, a.best = r, r; changed = true end
		end
		if a.sh_t == nil then a.sh_t = 0; changed = true end
		if changed then mark() end
		return changed
	end
	if (tonumber(me.rank_t) or 0) > (tonumber(a.sh_t) or 0) then
		a.rank = math.max(1, math.min(MAX_RANK + 5000, math.floor(tonumber(me.rank) or a.rank)))
		if a.rank < a.best then a.best = a.rank end
		a.sh_t = tonumber(me.rank_t)
		changed = true
	end
	if type(me.pend) == "table" and #me.pend > 0 then
		for i = 1, #me.pend do
			if type(me.pend[i]) == "table" then table.insert(a.logs, 1, me.pend[i]) end
		end
		while #a.logs > LOG_MAX do table.remove(a.logs) end
		me.pend = nil
		AR.sh_write(db)
		changed = true
	end
	if changed then mark() end
	return changed
end

-- Dong bo + ghi ban chup + bo cac doi thu dang luu trong bo nho dem neu do la (hoac vua doi thanh) nguoi choi that.
function AR.sh_refresh(e, a)
	if AR.sh_key() == nil then return end
	AR.sh_sync(e, a)
	AR.sh_publish(e, a)
	if R.ar_preview ~= nil then
		for k, v in pairs(R.ar_preview) do
			if type(v) == "table" and (v.real == true or AR.sh_real_at(tonumber(v.rank) or 0) ~= nil) then R.ar_preview[k] = nil end
		end
	end
end

function AR.sh_real_at(rank)
	local key = AR.sh_key()
	if key == nil then return nil end
	local db = AR.sh_read(false)
	local best, bk = nil, nil
	for k, pl in pairs(db.players) do
		if k ~= key and type(pl) == "table" and not (R.sh_bad ~= nil and R.sh_bad[k]) and type(pl.team) == "table" and #pl.team > 0
			and math.floor(tonumber(pl.rank) or -1) == rank then
			if best == nil or (tonumber(pl.uid) or 0) < (tonumber(best.uid) or 0) then best, bk = pl, k end
		end
	end
	return best, bk
end

-- Doi thu la nguoi choi that o hang `rank` (nil neu hang do khong co nguoi that).
function AR.sh_opp(rank)
	local pl, pk = AR.sh_real_at(rank)
	if pl == nil then return nil end
	local o = { rank = rank, id = math.floor(tonumber(pl.uid) or 0), name = (string.gsub(tostring(pl.user or pl.name or "Player"), "%s+", "_")),
		icon = math.floor(tonumber(pl.icon) or 1), level = math.floor(tonumber(pl.level) or 1), vip = math.floor(tonumber(pl.vip) or 0),
		f = 1, team = {}, full = true, real = true, real_key = pk, bot_team = true }
	for slot, t in ipairs(pl.team) do
		if type(t) == "table" and type(t.ship) == "table" then
			local sid = fint(BOT_SID0 + 7000000 + (o.id % 100000) * 10 + slot)
			o.team[#o.team + 1] = { ship = AR.copy_roster(t.ship), tid = math.floor(tonumber(t.tid) or 0), g = math.floor(tonumber(t.g) or 1),
				evo = tostring(t.evo), star = tostring(t.star), order = tostring(t.order), skin = "0",
				force = math.floor(tonumber(t.force) or 0), sid = sid, mega = (type(t.mega) == "string") and t.mega or MEGA_EMPTY_JSON,
				bot = true, real = true }
		end
	end
	if #o.team == 0 then return nil end
	o.force = math.floor(tonumber(pl.force) or 0)
	o.mode = "real"
	o.okey = fint(rank) .. ":real"
	return o
end

-- Toi da 2 hang cua nguoi choi that (tai khoan khac) gan hang cua minh nhat (khong tinh top 10: da luon hien).
-- [FIX v6.34] chi lay nguoi co hang nam trong [lo, hi] (khoang hang danh sach gan do dang phu); lo/hi = nil => khong loc (cu).
function AR.sh_near_real(a, lo, hi)
	local key = AR.sh_key()
	if key == nil then return nil end
	local db = AR.sh_read(false)
	local list = {}
	for k, pl in pairs(db.players) do
		if k ~= key and type(pl) == "table" and not (R.sh_bad ~= nil and R.sh_bad[k]) and type(pl.team) == "table" and #pl.team > 0 then
			local rk = math.floor(tonumber(pl.rank) or 0)
			if rk > TOP_N and rk ~= a.rank and rk <= MAX_RANK + 5000 and (lo == nil or rk >= lo) and (hi == nil or rk <= hi) then
				list[#list + 1] = { rk = rk, d = math.abs(rk - a.rank), uid = tonumber(pl.uid) or 0 }
			end
		end
	end
	table.sort(list, function(x, y)
		if x.d ~= y.d then return x.d < y.d end
		return x.uid < y.uid
	end)
	local out, seen = {}, {}
	for i = 1, #list do
		if #out >= 2 then break end
		if not seen[list[i].rk] then seen[list[i].rk] = true; out[#out + 1] = list[i].rk end
	end
	return out
end

-- Sau 1 tran voi nguoi that: thang & len hang => hai ben doi hang; ghi nhat ky "bi thach dau" cho ho.
function AR.sh_after_fight(e, a, o, win, before)
	local key = AR.sh_key()
	if key == nil or o.real ~= true or o.real_key == nil then return end
	local now = os.time()
	AR.sh_publish(e, a)
	local db = AR.sh_read(true)
	local me, opp = db.players[key], db.players[o.real_key]
	if opp == nil then return end
	local moved = win and (o.rank < before)
	if moved then
		a.sh_t = now
		if me ~= nil then me.rank, me.rank_t = a.rank, now end
		opp.rank, opp.rank_t = before, now
	end
	if type(opp.pend) ~= "table" then opp.pend = {} end
	opp.pend[#opp.pend + 1] = { tag = "0", name = my_name(e), win = win and "0" or "1", chg = moved and fint(-(before - o.rank)) or "0", t = now * 1000 }
	while #opp.pend > LOG_MAX do table.remove(opp.pend, 1) end
	AR.sh_write(db)
	mark()
end

-- [FIX v6.34] Bot thang minh va chiem hang `rk` dang la acc that => acc do tut xuong hang cu cua minh (`to_rank`).
function AR.sh_swap_real(rk, to_rank)
	local pl, pk = AR.sh_real_at(rk)
	if pl == nil or pk == nil then return false end
	local db = AR.sh_read(true)
	local p = db.players[pk]
	if type(p) ~= "table" then return false end
	p.rank, p.rank_t = math.floor(tonumber(to_rank) or rk), os.time()
	return AR.sh_write(db)
end

AR.BOT = { hmin = 1, hmax = 5, maxev = 24, maxh = 48, win = 300, susp = 600, save_every = 120, sim_cap = 8, sim_last = 3 }

-- [BOT SIM v1] sim_ok = true => tran bot khieu chien chay bang ENGINE THAT (nhu minh danh bot cung hang) => thang/thua theo tran that + co replay.
-- Loi / het ngan sach thoi gian (AR.BOT.sim_cap giay / lan goi) / cut => quay lai random cu (khong co replay).
-- Tat bang cfg ar_bot_sim = 0.
function AR.bot_event(e, a, when, nowt, sim_ok)
	if a.rank >= MAX_RANK then return false end
	local rk = math.min(MAX_RANK, a.rank + math.random(1, 12))
	local ok, o = pcall(AR.preview, e, rk, a.batch)
	if not ok or type(o) ~= "table" then return false end
	local mine = math.max(1, my_force(e))
	local ratio = (tonumber(o.force) or mine) / mine
	local pwin = math.max(0.1, math.min(0.9, 0.5 - (ratio - 1) * 1.5 + 0.35))
	local bot_win = math.random() > pwin
	local res = nil
	local simcfg = type(S.cfg) == "table" and tonumber(S.cfg.ar_bot_sim) or nil
	if sim_ok and simcfg ~= 0 and (os.clock() - (AR._sim_t0 or os.clock())) < AR.BOT.sim_cap then
		local FUm = AR.fusion_mod() -- [HOP THE BOT] mo phong nen (bot khieu chien) khong duoc lam mat than hop the cua tran dang xem
		local keep_foe = type(FUm) == "table" and FUm.foe_battle or nil
		local okr, r, o2 = pcall(AR.run_safe, e, o, rk, a.batch)
		if keep_foe ~= nil and type(FUm) == "table" then FUm.foe_battle = keep_foe end
		if okr and type(r) == "table" and not r.cut then
			res = r
			o = o2 or o
			bot_win = not (r.win == 1)
		elseif not okr then
			log("dau truong: bot sim loi (dung random):", tostring(r):sub(1, 120))
		end
	end
	local chg = 0
	local old_rank = a.rank
	if bot_win then
		chg = -(rk - a.rank)
		a.rank = rk
		a.sh_t = os.time()
		-- [FIX v6.34] hang rk dang la acc that (tai khoan khac) => doi cho (ho nhan hang cu cua minh), tranh 2 nguoi cung 1 hang
		pcall(AR.sh_swap_real, rk, old_rank)
	end
	a.lose = a.lose + (bot_win and 1 or 0)
	local when_s = math.min(nowt, when)
	table.insert(a.logs, 1, { tag = "0", name = o.name, win = bot_win and "0" or "1", chg = fint(chg), t = when_s * 1000 })
	while #a.logs > LOG_MAX do table.remove(a.logs) end
	if res ~= nil then
		local okp, errp = pcall(AR.report_add, e, a, o, res, false, bot_win, old_rank, a.rank, when_s * 1000)
		if not okp then log("dau truong: luu replay bot loi:", tostring(errp):sub(1, 120)) end
	end
	return true
end

function AR.bot_challenges(e, a)
	local B = AR.BOT
	AR._sim_t0 = os.clock()
	local nowt = os.time()
	local last = tonumber(a.sim_t)
	if last == nil or last ~= last or last > nowt + 60 then
		a.sim_t = nowt
		a.on_w0 = nil
		mark()
		return 0
	end
	local done, cnt = 0, 0
	if nowt - last > B.susp then
		-- khong vao game: moi gio random 1-5 lan, giay ngau nhien (gio le dau/cuoi giam theo ti le)
		local evs = {}
		local h0 = math.floor(last / 3600) * 3600
		if nowt - h0 > B.maxh * 3600 then h0 = math.floor(nowt / 3600) * 3600 - B.maxh * 3600 end
		local hs = h0
		while hs < nowt do
			local lo, hi = math.max(hs, last), math.min(hs + 3600, nowt)
			if hi > lo then
				local n = math.random(B.hmin, B.hmax) * (hi - lo) / 3600
				local k = math.floor(n)
				if math.random() < n - k then k = k + 1 end
				for _ = 1, k do evs[#evs + 1] = lo + math.random(0, math.max(0, hi - lo - 1)) end
			end
			hs = hs + 3600
		end
		table.sort(evs)
		for idx = math.max(1, #evs - B.maxev + 1), #evs do
			if AR.bot_event(e, a, evs[idx], nowt, idx > #evs - B.sim_last) then done = done + 1 end
		end
		a.on_w0 = nil
	end
	a.sim_t = nowt
	-- dang trong game: 1 tran / cua so 5 phut, giay ngau nhien
	local w0 = tonumber(a.on_w0)
	if w0 == nil or w0 > nowt or nowt - w0 > 6 * B.win then
		w0 = nowt
		a.on_w0 = w0
		a.on_ev = w0 + math.random(0, B.win - 1)
		a.on_done = false
	end
	for _ = 1, 6 do
		local ev = tonumber(a.on_ev) or w0
		if a.on_done ~= true and nowt >= ev then
			if AR.bot_event(e, a, ev, nowt, true) then done = done + 1 end
			a.on_done = true
		end
		if nowt >= w0 + B.win then
			w0 = w0 + B.win
			a.on_w0 = w0
			a.on_ev = w0 + math.random(0, B.win - 1)
			a.on_done = false
		else
			break
		end
	end
	if done > 0 then
		R.ar_preview, R.ar_preview_epoch = nil, nil
		log("dau truong: bot khieu chien", done, "lan, hang hien tai", a.rank)
	end
	if done > 0 or nowt - (R.bot_saved or 0) >= B.save_every then
		R.bot_saved = nowt
		mark()
	end
	return done
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	local a = st()
	local d = today()
	if a.day ~= d then
		a.day = d
		a.wn = 0
		a.wor = {}
		mark()
	end
	return e, a
end

local function save()
	mark()
	LS.save_state(true)
end

-- Goi tu LS.respond (moi lenh, gioi han 15s/lan, bo qua lenh dang danh): nhip dong ho cho bot khieu chien.
function AR.bot_tick(name)
	local nowt = os.time()
	if R.bot_tick_t ~= nil and nowt - R.bot_tick_t < 15 then return end
	local n = tostring(name or "")
	if string.find(n, "launch", 1, true) or string.find(n, "fight", 1, true) or string.find(n, "battle", 1, true)
		or string.find(n, "challenge", 1, true) or string.find(n, "attack", 1, true) then return end
	R.bot_tick_t = nowt
	local ok, e, a = pcall(ctx)
	if not ok or type(e) ~= "table" or type(a) ~= "table" then return end
	local okb, errb = pcall(AR.bot_challenges, e, a)
	if not okb then log("dau truong: bot tick loi (bo qua):", tostring(errb):sub(1, 120)) end
	if AR.sh_key() ~= nil and nowt - (R.sh_pub_t or 0) >= 120 then pcall(AR.sh_refresh, e, a) end
end

