-- [ARENA REPLAY v1] Luu replay + bao cao tran Arena (tran minh danh bot va tran bot khieu chien minh).
-- a.reps = danh sach metadata (luu cung state); noi dung replay (init + block39) o R.al_rep[<t>] (file replay theo tai khoan).
AR.REP_KEEP = 30
function AR.report_add(e, a, o, res, i_attack, att_win, rank_before, rank_after, when_ms)
	if type(res) ~= "table" or type(res.init) ~= "string" or res.cut then return end
	local okb, b39 = pcall(SB.block39, res)
	if not okb or type(b39) ~= "string" then return end
	if type(a.reps) ~= "table" then a.reps = {} end
	local t = math.floor(tonumber(when_ms) or 0)
	local used = {}
	for _, r in ipairs(a.reps) do if type(r) == "table" then used[tonumber(r.t) or 0] = true end end
	while used[t] do t = t + 1 end
	if type(R.al_rep) ~= "table" then R.al_rep = {} end
	R.al_rep[tostring(t)] = { { init = res.init, b39 = b39, inf = (type(res.inf) == "string" and res.inf ~= "") and res.inf or nil } }
	table.insert(a.reps, 1, { t = t, att = i_attack and 1 or 0, win = att_win and 1 or 0, id = tonumber(o.id) or 0, name = tostring(o.name or "Bot"),
		icon = tonumber(o.icon) or 1, level = tonumber(o.level) or 1, force = tonumber(o.force) or 0, rb = tonumber(rank_before) or 0, ra = tonumber(rank_after) or 0 })
	while #a.reps > AR.REP_KEEP do
		local old = table.remove(a.reps)
		if type(old) == "table" and type(R.al_rep) == "table" then R.al_rep[tostring(old.t)] = nil end
	end
	R.ar_rep_dirty = true
end

-- Khoi 14700 (client: parse_city_resource_battle_reports_init): moi dong = 16 truong; chi liet ke tran con replay.
function AR.report_block(e, a)
	local rows, n = {}, 0
	local myid = my_id(e)
	local reps = type(a.reps) == "table" and a.reps or {}
	local function nn(v) return fint(tonumber(v) or 0) end
	for _, r in ipairs(reps) do
		local rp = type(R.al_rep) == "table" and R.al_rep[tostring(r.t)] or nil
		if type(r) == "table" and type(rp) == "table" and type(rp[1]) == "table" and type(rp[1].init) == "string" then
			n = n + 1
			-- param: [4]=hang cua minh truoc, [5]=hang cua minh sau, [6]=id nguoi PHONG THU (client dung de biet minh danh hay bi danh)
			local def = (r.att == 1) and nn(r.id) or myid
			local param = "0,0,0," .. nn(r.rb) .. "," .. nn(r.ra) .. "," .. def
			for _, v in ipairs({ nn(r.id), nn(r.icon), "0", nn(r.level), "0", "0", tostring(r.name), nn(r.force), nn(r.win), param, "11", nn(r.t), "1", "0", "-1", "-1" }) do
				rows[#rows + 1] = tostring(v)
			end
		end
	end
	return "14700\r\n" .. fint(n) .. (n > 0 and ("\r\n" .. table.concat(rows, "\r\n")) or "")
end

-- battlefield_report_battle_info_get (nType 11 / 1011): tra lai replay da luu theo khoa thoi gian.
function AR.h_replay(p, seq)
	local name = "battlefield_report_battle_info_get"
	local rp = type(R.al_rep) == "table" and R.al_rep[tostring(p[2] or "")] or nil
	local first = type(rp) == "table" and rp[1] or nil
	if type(first) ~= "table" or type(first.init) ~= "string" or type(first.b39) ~= "string" then
		return err_reply(seq, name, "LS_khong_co_replay_arena", ERR.generic)
	end
	stat_inc("ar_replay")
	local rblocks = { first.init }
	if type(first.inf) == "string" and first.inf ~= "" then rblocks[#rblocks + 1] = first.inf end
	rblocks[#rblocks + 1] = first.b39
	return reply(seq, name, rblocks)
end

-- [FIX hoi sinh] battlefield_report_get (goi 6114)
