local function blk14709(e, a, o, my_rank)
	local mine = team_str(my_team(e))
	local b = { "14709", my_name(e), fint(my_rank), mine, o.name, fint(o.rank), team_str(o.team) }
	return table.concat(b, "\r\n")
end

function AR.h_launch(p, seq)
	local name = "arena_launch"
	local e, a = ctx()
	local rank = tonumber(p[1])
	if rank == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
	rank = math.floor(rank)
	if rank < 1 or rank > MAX_RANK + 5000 then return err_reply(seq, name, "LS_hang_khong_hop_le", ERR.generic) end
	if rank == a.rank then return err_reply(seq, name, "LS_khong_tu_danh_minh", ERR.generic) end
	local batch = rank <= TOP_N and 1 or a.batch
	local o = AR.preview(e, rank, batch)
	local res, o2, err = AR.run_safe(e, o, rank, batch)
	o = o2 or o
	if res == nil then
		R.ar_errs = (R.ar_errs or 0) + 1
		AR.report_error(o, err, name)
		stat_inc("ar_fail")
		return err_reply(seq, name, "LS_loi_tinh_tran")
	end
	local win = res.win == 1 and not res.cut
	local before = a.rank
	local rb, ra = AR.settle(e, a, o, win)
	local okp, errp = pcall(AR.report_add, e, a, o, res, true, win, rb, ra, (os.time() + (tonumber(e.time_add_or_sub) or 0)) * 1000)
	if not okp then log("dau truong: luu replay loi:", tostring(errp):sub(1, 120)) end
	R.ar_last = { rank = o.rank, f = o.f, win = win, rounds = res.rounds, from = rb, to = ra }
	save()
	stat_inc("ar_fights")
	log("dau truong: danh hang", o.rank, "(f=" .. string.format("%.2f", o.f) .. ")", win and "THANG" or "THUA", res.rounds, "round, hang", rb, "->", ra)
	-- [ls-2.77 FIX Khieu chien] khoi buff dau tran 14710-14714 dat CUOI phan hoi (sau 39 va 14709).
	-- Log: moi tran co kem khoi buff deu bi "attackData nil" (arena_ladder_seat_cell.lua:313), tran khong co buff thi on.
	-- Dat buff o cuoi thi du parser client lech/loi o do, _ED.attackData (khoi 39) va hang (14709) da nap xong.
	-- Bo han khoi buff: S.cfg.ar_buff_blocks = false.
	local blocks = { res.init, SB.block39(res), blk14709(e, a, o, before) }
	local okc, buff_cfg = pcall(function() return S.cfg.ar_buff_blocks end)
	if type(res.inf) == "string" and res.inf ~= "" and not (okc and buff_cfg == false) then
		blocks[#blocks + 1] = res.inf
		log("dau truong: khoi buff dau tran 14710-14714 dat cuoi phan hoi,", #res.inf, "byte")
	end
	return reply(seq, name, blocks)
end

function AR.h_sweep(p, seq)
	local name = "arena_sweep"
	local e, a = ctx()
	local rank = tonumber(p[1])
	local n = math.max(1, math.min(10, math.floor(tonumber(p[2]) or 5)))
	if rank == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
	rank = math.floor(rank)
	if rank < 1 or rank == a.rank then return err_reply(seq, name, "LS_hang_khong_hop_le", ERR.generic) end
	local batch = rank <= TOP_N and 1 or a.batch
	local o = AR.preview(e, rank, batch)
	local wins = 0
	for i = 1, n do
		local res, o2, err = AR.run_safe(e, o, rank, batch)
		o = o2 or o
		if res == nil then
			R.ar_errs = (R.ar_errs or 0) + 1
			AR.report_error(o, err, name)
			stat_inc("ar_fail")
			if i == 1 then return err_reply(seq, name, "LS_loi_tinh_tran") end
			break
		end
		local win = res.win == 1 and not res.cut
		if win then wins = wins + 1 end
		AR.settle(e, a, o, win)
	end
	R.ar_last = { rank = o.rank, f = o.f, sweep = n, wins = wins }
	save()
	stat_inc("ar_sweeps")
	log("dau truong: quet", n, "lan hang", o.rank, "thang", wins)
	return reply(seq, name, { AR.blk45(e) })
end

function AR.h_worship(p, seq)
	local name = "arena_worship"
	local e, a = ctx()
	local targets = {}
	if tostring(p[2]) == "1" then
		for r = 1, TOP_N do targets[#targets + 1] = r end
	else
		local r = tonumber(p[3])
		if r == nil then return err_reply(seq, name, "LS_thieu_tham_so", ERR.generic) end
		targets[1] = math.floor(r)
	end
	local given, n = 0, 0
	for _, r in ipairs(targets) do
		if r >= 1 and r <= TOP_N and a.wn < WORSHIP_MAX then
			local id = (r == a.rank) and (tonumber(my_id(e)) or 0) or (ID_BASE + r)
			if a.wor[tostring(id)] == nil then
				a.wor[tostring(id)] = true
				a.wn = a.wn + 1
				a.wv[tostring(r)] = math.floor(tn(a.wv[tostring(r)], 0)) + 1
				given = given + WORSHIP_SILVER
				n = n + 1
			end
		end
	end
	if n == 0 then return err_reply(seq, name, "LS_het_luot_mo_bai", ERR.generic) end
	LS.money_add("silver", given)
	save()
	stat_inc("ar_worship", n)
	return reply(seq, name, { AR.blk45(e), "171\r\n14\r\n1\r\n-1\r\n1\r\n" .. fint(given) })
end

function AR.h_order(p, seq)
	local e, a = ctx()
	local n = math.floor(arena_cfg_num(10, 50))
	local rows = {}
	for r = 1, n do
		local en
		if r == a.rank then en = entry_self(e, a) else en = entry_from_opp(e, a, AR.preview(e, r, 1)) end
		rows[#rows + 1] = en
	end
	local b = { "62", "0", fint(a.rank), fint(#rows) }
	for _, en in ipairs(rows) do
		for _, v in ipairs({ en.id, en.icon, en.team, "0", "0", "0", en.rank, en.name, en.level, en.vip, "0", "Saiyan", "0", "0", en.force, "-1", "-1" }) do
			b[#b + 1] = tostring(v)
		end
	end
	stat_inc("ar_order")
	return reply(seq, "arena_order", { table.concat(b, "\r\n") })
end

local function draw(p, seq, name, tname, set, ok_fn)
	local e, a = ctx()
	local rows = reward_rows(tname)
	local want = tostring(p[1] or "-1")
	local picks = {}
	for _, r in ipairs(rows) do
		if set[r.idx] == nil and ok_fn(a, r) and (want == "-1" or tonumber(want) == r.idx) then picks[#picks + 1] = r end
	end
	if #picks == 0 then return err_reply(seq, name, "LS_khong_co_thuong_de_nhan", ERR.generic) end
	local items = {}
	for _, r in ipairs(picks) do
		set[r.idx] = true
		for _, t in ipairs(triples(r.info)) do
			items[#items + 1] = { item = t.item, typ = t.typ, qty = t.qty }
		end
	end
	local given = LS._apply_rewards(items)
	save()
	stat_inc("ar_draws", #picks)
	local blocks = { AR.blk45(e) }
	if #given > 0 then
		local b = { "171", "14", fint(#given) }
		for _, g in ipairs(given) do b[#b + 1] = fint(g.item); b[#b + 1] = fint(g.typ); b[#b + 1] = fint(g.qty) end
		blocks[#blocks + 1] = table.concat(b, "\r\n")
	end
	return reply(seq, name, blocks)
end

function AR.h_draw_order(p, seq)
	local a = st()
	return draw(p, seq, "draw_arena_order_reward", "arena_welfare", a.dr, function(a2, r) return a2.best <= r.target end)
end

function AR.h_draw_score(p, seq)
	local a = st()
	return draw(p, seq, "draw_arena_score_reward", "arena_score", a.ds, function(a2, r) return a2.score >= r.target end)
end

function AR.dump_line()
	local a = S ~= nil and S.ar or nil
	if type(a) ~= "table" then return "[LS dau truong] chua dung" end
	local l = R.ar_last
	local ls = ""
	if type(l) == "table" then
		ls = " | cuoi: hang " .. tostring(l.rank) .. " f=" .. string.format("%.2f", tonumber(l.f) or 0) .. (l.sweep and (" quet " .. tostring(l.sweep) .. " thang " .. tostring(l.wins)) or (l.win and " THANG" or " THUA"))
	end
	local ss = R.ar_speed_last
	local speed = type(ss) == "table" and (" | toc do ban " .. fint(ss.mine) .. " / dich " .. fint(ss.foe) .. " -> " .. tostring(ss.first) .. " truoc") or ""
	return "[LS dau truong] hang " .. fint(a.rank or 0) .. " (tot nhat " .. fint(a.best or 0) .. ") | thang " .. fint(a.win or 0) .. " thua " .. fint(a.lose or 0)
		.. " | diem " .. fint(a.score or 0) .. " | he so " .. string.format("%.2f", power_mult()) .. ls .. speed .. " | loi " .. tostring(R.ar_errs or 0) .. (tonumber(R.ar_badtok) and (" | token la " .. tostring(R.ar_badtok)) or "")
end

function AR.reset()
	S.ar = nil
	mark()
end

-- =====================================================================================================
-- [ACCOUNT v6.32] Kho replay lien server (R.cx_rep / R.cm_rep / R.ta_rep) luu ra file THEO TAI KHOAN:
--   AR.K.REP_FILE (mac dinh offline_ar_replays.txt; LS.set_account doi thanh offline_ar_replays_<tk>.txt).
-- Dinh dang nhi phan an toan (theo do dai): dong dau "#OFFLINE_AR_REPLAYS v1"; moi muc "<loai>\t<khoa>\t<n>\n" roi n chuoi,
-- moi chuoi "<so byte>\n<noi dung>\n". cx/ta = mang chuoi; cm = (init, b39) xep lien tiep. Giu moi nhat, toi da REP_MAX byte.
-- Ghi gop (toi da 1 lan / REP_GAP giay trong LS.sync) + ghi ngay khi LS.flush / doi tai khoan.
-- =====================================================================================================
AR.K = AR.K or {}
AR.K.REP_FILE = AR.K.REP_FILE or "offline_ar_replays.txt"
AR.K.REP_MAX = 12 * 1024 * 1024
AR.K.REP_GAP = 5

do
	local KIND_TBL = { cx = "cx_rep", cm = "cm_rep", ta = "ta_rep", al = "al_rep" }
	local ORDER = { "cx", "cm", "ta", "al" }
	local HEADER = "#OFFLINE_AR_REPLAYS v1"

	local function flat(kind, v)
		if type(v) ~= "table" then return nil end
		local out = {}
		if kind == "cm" or kind == "al" then
			for i = 1, #v do
				local o = v[i]
				if type(o) ~= "table" or type(o.init) ~= "string" or type(o.b39) ~= "string" then return nil end
				out[#out + 1] = o.init
				out[#out + 1] = o.b39
			end
		else
			for i = 1, #v do
				if type(v[i]) ~= "string" then return nil end
				out[i] = v[i]
			end
		end
		return out
	end

	function AR.rep_serialize()
		local ents = {}
		for _, kind in ipairs(ORDER) do
			local tbl = R[KIND_TBL[kind]]
			if type(tbl) == "table" then
				for key, v in pairs(tbl) do
					local strs = flat(kind, v)
					if strs ~= nil and #strs > 0 then
						local bytes = 0
						for i = 1, #strs do bytes = bytes + #strs[i] + 24 end
						ents[#ents + 1] = { kind = kind, key = tostring(key), t = tonumber(key) or 0, strs = strs, bytes = bytes }
					end
				end
			end
		end
		table.sort(ents, function(a, b) return a.t > b.t end)
		local out, used = { HEADER, "\n" }, 0
		for i = 1, #ents do
			local e = ents[i]
			if used + e.bytes > AR.K.REP_MAX and used > 0 then break end
			used = used + e.bytes
			out[#out + 1] = e.kind .. "\t" .. e.key .. "\t" .. #e.strs .. "\n"
			for j = 1, #e.strs do
				local s = e.strs[j]
				out[#out + 1] = tostring(#s)
				out[#out + 1] = "\n"
				out[#out + 1] = s
				out[#out + 1] = "\n"
			end
		end
		return table.concat(out)
	end

	function AR.rep_parse(txt)
		local res = { cx = {}, cm = {}, ta = {}, al = {} }
		if type(txt) ~= "string" or string.sub(txt, 1, #HEADER) ~= HEADER then return res end
		local pos = string.find(txt, "\n", 1, true)
		if pos == nil then return res end
		pos = pos + 1
		local total = #txt
		while pos <= total do
			local nl = string.find(txt, "\n", pos, true)
			if nl == nil then break end
			local kind, key, cnt = string.match(string.sub(txt, pos, nl - 1), "^(%a+)\t([^\t]+)\t(%d+)$")
			cnt = tonumber(cnt)
			if kind == nil or res[kind] == nil or cnt == nil then break end
			pos = nl + 1
			local strs, bad = {}, false
			for i = 1, cnt do
				local nl2 = string.find(txt, "\n", pos, true)
				local len = nl2 and tonumber(string.sub(txt, pos, nl2 - 1)) or nil
				if len == nil or nl2 + len + 1 > total or string.sub(txt, nl2 + len + 1, nl2 + len + 1) ~= "\n" then
					bad = true
					break
				end
				strs[i] = string.sub(txt, nl2 + 1, nl2 + len)
				pos = nl2 + len + 2
			end
			if bad then break end
			if kind == "cm" or kind == "al" then
				if cnt % 2 ~= 0 then break end
				local arr = {}
				for i = 1, cnt, 2 do arr[#arr + 1] = { init = strs[i], b39 = strs[i + 1] } end
				res[kind][key] = arr
			else
				res[kind][key] = strs
			end
		end
		return res
	end

	function AR.rep_load()
		R.cx_rep, R.cm_rep, R.ta_rep, R.al_rep = nil, nil, nil, nil
		R.ar_rep_dirty = false
		if H.read_first == nil then return 0 end
		local ok, txt = pcall(H.read_first, AR.K.REP_FILE)
		if not ok or type(txt) ~= "string" or txt == "" then return 0 end
		local okp, res = pcall(AR.rep_parse, txt)
		if not okp or type(res) ~= "table" then
			log("replay lien server: file hong, bo qua", AR.K.REP_FILE)
			return 0
		end
		local n = 0
		for _, kind in ipairs(ORDER) do
			local t = {}
			for k, v in pairs(res[kind]) do t[k] = v; n = n + 1 end
			R[KIND_TBL[kind]] = t
		end
		log("replay lien server: nap", n, "tran tu", AR.K.REP_FILE)
		return n
	end

	function AR.rep_flush()
		if not R.ar_rep_dirty or H.write_first == nil then return false end
		R.ar_rep_last = os.time()
		local ok, txt = pcall(AR.rep_serialize)
		if not ok or type(txt) ~= "string" then
			log("replay lien server: loi ghi:", tostring(txt))
			return false
		end
		local okw, where = pcall(H.write_first, AR.K.REP_FILE, txt)
		if okw and where then
			R.ar_rep_dirty = false
			return true
		end
		log("replay lien server: khong ghi duoc", AR.K.REP_FILE)
		return false
	end

	function AR.rep_tick()
		if not R.ar_rep_dirty then return end
		if os.time() - (R.ar_rep_last or 0) < AR.K.REP_GAP then return end
		AR.rep_flush()
	end
end

-- ============================================================================
-- [THAP BOT] Leo thap (Thu Thach + Fury) danh BOT FULL RANDOM nhu dau truong, moi tang bot manh hon 10%.
--  Ca hai thap deu goi FightModule:initSpecialFight tren client. FightModule.lua co 3 moc
--  ZZ_TOWER_BOTS(stage, fm, npcId) (moi moc boc pcall, loi thi bo qua, tran van dung quan dich goc):
--    "pre"  : truoc khi dung tran  -> chon doi bot random (tuong full nhu dau truong), nhan he so tang,
--             chay THU 1 tran ngan bang engine that (co watchdog) de chac chan doi nay khong gay loi / treo;
--             hong thi doi sang 'nomega' -> 'safe' -> boc lai doi khac; van hong thi dung quan dich goc.
--    "mid"  : truoc khi ghi battle_field_init -> dung FightObject cho 6 bot, nhan chi so, thay quan dich.
--    "post" : sau khi parse -> dat lai toc do dau tran (giong dau truong).
--  He so theo tang n (n = so tang, tang 1 = x1): mac dinh LUY TIEN 1.1^(n-1); nut GM doi sang
--  CONG DON 1+0.1*(n-1) hoac TAT. Nhan them he so "Buff arena (bot)" (power_mult) nhu dau truong.
-- ============================================================================
do
local TW = {}
local TW_ID0, TW_SID0 = 810000000, 890000000
local TW_VAL_ROUNDS, TW_STEP, TW_FMAX = 12, 0.10, 1e9 -- [THAP BOT] +10% moi 3 tang (cong don), luon bat

local function tw_mode()
-- [THAP BOT] Co dinh: luon BAT, cong don 1 + 0.1*floor((tang-1)/3) (moi 3 tang +10%). Khong con nut GM.
	return "linear"
end

function TW.factor(floor, mode)
	mode = mode or tw_mode()
	local n = math.max(0, math.floor(tonumber(floor) or 1) - 1)
	local v
	if mode == "off" then v = 1
	elseif mode == "linear" then v = 1 + TW_STEP * math.floor(n / 3) -- moi 3 tang them 10%
	else v = (1 + TW_STEP) ^ n end
	if v ~= v or v > TW_FMAX then v = TW_FMAX end
	return v
end

-- tang dang danh: Fury = _ED.fury_tower_battle.floor ; Thu Thach = _ED.integral_current_index
local function tw_floor()
	local e = ED()
	if type(e) ~= "table" then return nil end
	local fb = e.fury_tower_battle
	if type(fb) == "table" and tonumber(fb.floor) ~= nil then
		return math.max(1, math.floor(tonumber(fb.floor))), "fury", fb.weaken == true
	end
	local f = tonumber(e.integral_current_index)
	if f == nil or f < 1 then f = 1 end
	return math.floor(f), "trial", false
end

local function tw_prep(o, f, floor)
	local f0 = tonumber(o.f) or 1
	if f0 <= 0 then f0 = 1 end
	for slot, t in ipairs(o.team) do
		if t.bot then t.sid = fint(TW_SID0 + slot) end
	end
	o.force = math.floor((tonumber(o.force) or 0) / f0 * f)
	o.f = f
	o.id = TW_ID0 + (R.tw_n or 0) % 100000000
	o.rank = floor
	o.budget = 3
	o.tower_bot = true -- use the same action policy in validation and live tower
end

function TW.pre(fm, npc_id)
	TW.cur, TW.spd = nil, nil
	if not (R.enabled == true and S ~= nil and tw_mode() ~= "off") then return end
	local e = ED()
	if type(e) ~= "table" or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return end
	local floor, kind, weaken = tw_floor()
	if floor == nil then return end
	local fac = TW.factor(floor)
	local f = fac * power_mult()
	if f > 1e12 then f = 1e12 end
	R.tw_n = (R.tw_n or 0) + 1
	local gate = 4
	if kind ~= "fury" then gate = math.max(1, math.min(3, math.floor(tonumber(e.three_kingdoms_battle_index) or 1))) end
	local rank = 100000 + floor * 5 + gate
	local batch0 = (os.time() % 86400) * 31 + R.tw_n * 7
	local t0 = os.clock()
	local first_err = nil
	for draw = 0, 2 do
		local batch = batch0 + draw * 7919
		local chain, ci = { "full", "nomega", "safe" }, 1
		while ci <= #chain do
			local m = chain[ci]
			local o = AR.opp(e, rank, batch, m)
			if o == nil or #o.team == 0 then ci = #chain + 1; break end
			tw_prep(o, f, floor)
			local prev_lock = R.cell_lock
			R.cell_lock = TW_VAL_ROUNDS
			local tv0 = os.clock()
			local okr, res, err = pcall(AR.run, e, o)
			R.cell_lock = prev_lock
			local tv = os.clock() - tv0
			-- [FIX ZZ-DUNG-HINH] tran thu bi "dung vong" (cut: round khong tang) => KHONG dung doi nay, thu che do / lan boc khac
			if okr and res ~= nil and res.cut ~= true then
				TW.cur = { o = o, floor = floor, kind = kind, f = f, fac = fac, weaken = weaken, mode = m, draw = draw,
					vr = res.rounds, vw = res.win, vt = tv, pt = os.clock() - t0 }
				return
			end
			if okr and res ~= nil then err = "tran thu bi dung vong (cut), bo doi nay" end
			if not okr then err = res end
			if first_err == nil then first_err = err end
			R.tw_retry = (R.tw_retry or 0) + 1
			if R.tw_retry <= 6 then log("thap bot: doi '" .. m .. "' tang", floor, "bi loai sau", string.format("%.2fs", os.clock() - tv0) .. ":", tostring(err):sub(1, 110)) end
			if string.find(tostring(err), "LS_watchdog", 1, true) ~= nil and ci < 3 then ci = 3 else ci = ci + 1 end
			if os.clock() - t0 > 7 then break end
		end
		if os.clock() - t0 > 7 then break end
	end
	R.tw_fail = (R.tw_fail or 0) + 1
	log("thap bot: khong dung duoc doi bot cho tang", floor, "-> dung quan dich goc cua game:", tostring(first_err):sub(1, 140))
end

-- [FIX log 13:46] Man hinh chien dau (Fight.lua addTigerGateFightUI) doc v.signType / v.name cua tung quan dich:
-- FightObject tao bang initWithUserData KHONG co signType => "attempt to compare number with nil" moi lan vao thap bot
-- (kem theo "GO KET n nut bi khoa"). Ten hien thi cua tuong = ship_evo_mould.name_index -> word_mould[3] (nhu cac man hinh khac).
local function tw_hero_name(ship)
	local ok, name = pcall(function()
		local evo = smGetSkinEvoIdChange(ship)
		local nid = dms.int(dms["ship_evo_mould"], evo, ship_evo_mould.name_index)
		local w = dms.element(dms["word_mould"], nid)
		if type(w) == "table" and w[3] ~= nil then return tostring(w[3]) end
		return ""
	end)
	-- chi nhan ten ngan hop ly (mot so tuong moi co name_index tro toi mo ta dai / "Chua co") -> bo, dung ten quan goc
	if ok and type(name) == "string" and name ~= "" and #name <= 36 and name ~= "Chưa có" then return name end
	return ""
end

local function tw_stock_obj(stock, i)
	if type(stock) ~= "table" then return nil end
	if stock[i] ~= nil then return stock[i] end
	for k = 1, 6 do
		if stock[k] ~= nil then return stock[k] end
	end
	return nil
end

function TW.mid(fm)
	local cur = TW.cur
	TW.cur = nil
	-- [tower263] The player's full build can self-refill against stock NPCs
	-- too. Keep the same finite, symmetric turn policy if bot construction
	-- fails or tower bots are switched off. Only local tower hooks enter here.
	if R.enabled == true then
		fm._lsTowerChainPolicy = true
		fm._lsSuperChainLimit = 1
		fm._lsSuperChainRound, fm._lsSuperChainCounts, fm._lsSuperChainNotified = nil, nil, nil
	end
	if cur == nil then return end
	local e = ED()
	local _, FOC = classes()
	local bc = (type(e) == "table" and type(e.user_info) == "table") and e.user_info.battleCache or nil
	if FOC == nil or type(bc) ~= "table" or type(e.user_ship) ~= "table" then return end
	local stock = (type(bc.byAttackerObjectsList) == "table") and bc.byAttackerObjectsList[1] or nil
	local o = cur.o
	local added = { ships = {}, mega = {} }
	local objs, spd = {}, 0
	local ok, err = pcall(function()
		for i, t in ipairs(o.team) do
			local ship = AR.copy_roster(t.ship)
			if t.bot then
				ship.ship_id = t.sid
				if e.user_ship[t.sid] == nil then
					e.user_ship[t.sid] = ship
					added.ships[#added.ships + 1] = t.sid
				end
				if type(e.mega_info) == "table" then
					local en = { shipId = t.sid, info = t.mega or MEGA_EMPTY_JSON }
					e.mega_info[#e.mega_info + 1] = en
					added.mega[#added.mega + 1] = en
				end
			end
			local fo = FOC:new()
			fo:initWithUserData(i, ship, 1, o.id, fm)
			if t.bot then strip_bot_buff(fo) end
			if o.f ~= 1 then scale_obj(fo, o.f) end
			-- Fury "debilitar": giong initSpecialFight goc, quan dich mat nua cong va nua mau
			if cur.weaken then
				fo.attack = math.ceil((tonumber(fo.attack) or 0) / 2)
				fo.healthPoint = math.ceil((tonumber(fo.healthPoint) or 0) / 2)
			end
			fo.id = o.id * 10 + i
			-- UI chien dau can signType (so) va name (chuoi): lay tu quan goc neu co, khong thi 0 / ten tuong
			local so = tw_stock_obj(stock, i)
			fo.signType = tonumber(so ~= nil and so.signType or nil) or 0
			if fo.name == nil or fo.name == "" then
				local nm = tw_hero_name(ship)
				if nm == "" and so ~= nil then nm = tostring(so.name or "") end
				fo.name = nm
			end
			objs[i] = fo
			spd = spd + (tonumber(fo.attackSpeed) or 0)
		end
		if next(objs) == nil then error("doi thu rong") end
	end)
	for _, k in ipairs(added.ships) do e.user_ship[k] = nil end
	if #added.mega > 0 and type(e.mega_info) == "table" then
		local drop = {}
		for _, en in ipairs(added.mega) do drop[en] = true end
		for i = #e.mega_info, 1, -1 do
			if drop[e.mega_info[i]] then table.remove(e.mega_info, i) end
		end
	end
	if not ok then
		R.tw_fail = (R.tw_fail or 0) + 1
		log("thap bot: loi dung quan dich:", tostring(err):sub(1, 200))
		return
	end
	-- Limit only generated tower bots (both camps); preserve refilled rage for
	-- the next round so an infinite player super cannot starve enemy actions.
	fm._lsTowerChainPolicy = true
	fm._lsSuperChainLimit = 1
	fm._lsSuperChainRound, fm._lsSuperChainCounts, fm._lsSuperChainNotified = nil, nil, nil
	bc.byAttackerObjectsList = { objs }
	bc.maxBattleCount = 1
	bc.byAttackComobatForce = o.force
	if objs[1] ~= nil then objs[1].attackSpeed = spd end
	bc.defender_priority = spd
	TW.spd = spd
	R.tw_ok = (R.tw_ok or 0) + 1
	R.tw_last = { floor = cur.floor, kind = cur.kind, f = cur.f, mode = cur.mode, n = #o.team, draw = cur.draw, t = os.time() }
	log("thap bot:", cur.kind == "fury" and "Fury" or "Thu Thach", "tang", cur.floor, "x" .. string.format("%.3f", cur.f),
		"che do", tw_mode(), "doi", cur.mode, #o.team .. " tuong",
		"| thu " .. tostring(cur.vr) .. "r/" .. string.format("%.2f", tonumber(cur.vt) or 0) .. "s (tong " .. string.format("%.2f", tonumber(cur.pt) or 0) .. "s)",
		"| gioi han", tostring(LS.round_lock({ fightType = 54 }) or "10") .. "r")
end

function TW.post(fm)
	local spd = TW.spd
	TW.spd = nil
	if spd == nil then return end
	local e = ED()
	local bc = (type(e) == "table" and type(e.user_info) == "table") and e.user_info.battleCache or nil
	if type(bc) ~= "table" then return end
	bc.defender_priority = spd
	local foes = type(bc.byAttackerObjectsList) == "table" and bc.byAttackerObjectsList[1] or nil
	if type(foes) == "table" and foes[1] ~= nil then foes[1].attackSpeed = spd end
end

function LS.tower_state() return tw_mode() end
LS.tower_factor = TW.factor

function LS.gm_toggle_tower()
	if S == nil or type(S.cfg) ~= "table" then return nil end
	local m = tw_mode()
	local nxt = (m == "compound") and "linear" or ((m == "linear") and "off" or "compound")
	S.cfg.tower_mode = nxt
	mark()
	LS.save_state(true)
	log("Thap bot:", nxt)
	return nxt
end

function AR.tower_line()
	local l = R.tw_last
	return "[LS thap bot] che do " .. tw_mode() .. " | tran bot " .. fint(R.tw_ok or 0) .. " | quan goc " .. fint(R.tw_fail or 0)
		.. " | thu lai " .. fint(R.tw_retry or 0) .. " | loi " .. fint(R.tw_err or 0)
		.. (type(l) == "table" and (" | cuoi: " .. (l.kind == "fury" and "Fury" or "Thu Thach") .. " tang " .. fint(l.floor)
			.. " x" .. string.format("%.3f", l.f) .. " doi " .. tostring(l.mode)) or "")
end

-- ham ma FightModule.lua goi (moi moc deu duoc boc pcall o phia client)
rawset(_G, "ZZ_TOWER_BOTS", function(stage, fm, npc_id)
	local ok, err = xpcall(function()
		if stage == "pre" then TW.pre(fm, npc_id)
		elseif stage == "mid" then TW.mid(fm)
		elseif stage == "post" then TW.post(fm) end
	end, traceback)
	if not ok then
		TW.cur, TW.spd = nil, nil
		R.tw_err = (R.tw_err or 0) + 1
		if R.tw_err <= 5 then log("thap bot: loi", tostring(stage), tostring(err):sub(1, 300)) end
	end
end)

-- ============================================================================
-- [BOSS GUILD BOT] Boss guild = 1 TUONG FULL RANDOM (lay tu pool bot dau truong), moi boss manh hon 20%, hinh to hon 1 chut.
--  Gioi han y het THAP BOT: FightModule:initUninoFight goi ZZ_UNION_BOTS(stage, fm, npcId) (moi moc boc pcall):
--    "pre"  : chon 1 tuong bot random (full build nhu dau truong), nhan he so theo boss, chay THU 1 tran ngan bang engine that
--             (co watchdog); hong thi doi 'nomega' -> 'safe' -> boc lai; van hong thi dung boss goc cua game.
--    "mid"  : sau khi game dat mau boss (current_hp), truoc khi ghi battle_field_init -> thay boss bang tuong bot,
--             nhan chi so, giu mau = current_hp cua boss guild, PHONG TO hinh (amplifyPercent -> _scale -> FightRole:setScale).
--             Kich thuoc cung duoc phong to ca khi phai dung boss goc.
--    "post" : dat lai toc do dau tran.
--  He so theo boss n (boss 1 = x1): mac dinh CONG DON 1 + 0.2*(n-1); S.cfg.ub_mode = "compound" -> 1.2^(n-1), "off" -> tat he so.
--  S.cfg.ub_on = false -> tat ca; S.cfg.ub_size = he so phong to hinh (mac dinh 1.5). He so cung nhan vao mau toi da boss (UD.maxhp).
-- ============================================================================
local UB = {}
local UB_ID0, UB_SID0 = 830000000, 893000000
local UB_VAL_ROUNDS, UB_STEP, UB_SIZE, UB_FMAX = 12, 100, 1.5, 1e9 -- [BOSS GUILD] +10000% moi boss (cong don: boss n = 1+100*(n-1)); S.cfg.ub_step doi duoc; ub_mode="compound" -> 101^(n-1)

local function ub_cfg(k, d)
	local c = (type(S) == "table") and S.cfg or nil
	if type(c) ~= "table" or c[k] == nil then return d end
	return c[k]
end

function UB.on() return R.enabled == true and S ~= nil and ub_cfg("ub_on", true) ~= false end

function UB.size()
	local v = tonumber(ub_cfg("ub_size", UB_SIZE))
	if v == nil or v ~= v or v <= 0 then v = UB_SIZE end
	if v > 3 then v = 3 end
	return v
end

function UB.factor(idx, mode)
	mode = mode or ub_cfg("ub_mode", "linear")
	local n = math.max(0, math.floor(tonumber(idx) or 1) - 1)
	local v
	local step = tonumber(ub_cfg("ub_step", UB_STEP)) or UB_STEP
	if step ~= step or step < 0 then step = UB_STEP end
	if mode == "off" then v = 1
	elseif mode == "compound" then v = (1 + step) ^ n
	else v = 1 + step * n end
	if v ~= v or v > UB_FMAX then v = UB_FMAX end
	return v
end

-- UD.maxhp (boss guild phia server) goi ham nay de mau toi da cung tang theo boss
function LS.ub_factor(idx)
	if not UB.on() then return 1 end
	return UB.factor(idx)
end

-- [BOSS GUILD] Tuong random CO DINH theo tung boss: hat giong luu trong S.ud.seed[boss], boc 1 lan roi giu nguyen
-- cho moi lan danh lai. Khi da ha het boss -> UD.roll_full() xoa het hat giong => vong sau random tuong moi.
function UB.seed(idx)
	local ud = LS._ud
	if type(ud) ~= "table" or type(ud.st) ~= "function" then return nil end
	local okk, u = pcall(ud.st)
	if not okk or type(u) ~= "table" then return nil end
	if type(u.seed) ~= "table" then u.seed = {} end
	local k = tostring(idx)
	local v = tonumber(u.seed[k])
	if v == nil or v ~= v or v < 1 then
		math.randomseed(os.time() + math.floor(os.clock() * 1000000) + idx * 7919)
		v = math.random(1, 1000000000)
		u.seed[k] = v
		mark()
		log("boss guild bot: boc tuong co dinh cho boss", idx, "hat giong", v)
	end
	return math.floor(v)
end

local function ub_idx()
	local e = ED()
	local i = type(e) == "table" and tonumber(e.union_copy_fight_data_id) or nil
	if i == nil or i < 1 then return nil end
	return math.floor(i)
end

-- Goi tin battle_field_init tach truong bang DAU CACH: ten co dau cach / rong se lech toan bo goi (loi 'for limit must be a number').
-- Tran boss guild (fightType 7 < 10) con ghi them 1 dong TEN boss, nen ten tuong bot phai doi dau cach -> &nbsp; va khong duoc rong.
local function ub_tok(s, d)
	s = tostring(s == nil and "" or s)
	s = (string.gsub(s, "%s+", "&nbsp;"))
	s = (string.gsub(s, "%c", ""))
	if s == "" then return d end
	return s
end

local function ub_resize(fo)
	local a = tonumber(fo.amplifyPercent) or 1
	if a <= 0 or a ~= a then a = 1 end
	fo.amplifyPercent = tostring(math.floor(a * UB.size() * 1000 + 0.5) / 1000)
end

function UB.pre(fm, npc_id)
	UB.cur, UB.spd = nil, nil
	if not UB.on() then return end
	local e = ED()
	if type(e) ~= "table" or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return end
	local idx = ub_idx()
	if idx == nil then return end
	local fac = UB.factor(idx)
	R.ub_n = (R.ub_n or 0) + 1
	local rank = 200000 + idx * 5
	local batch0 = UB.seed(idx) or ((os.time() % 86400) * 37 + R.ub_n * 11)
	local t0 = os.clock()
	local first_err = nil
	for draw = 0, 2 do
		local batch = batch0 + draw * 7919
		local chain, ci = { "full", "nomega", "safe" }, 1
		while ci <= #chain do
			local m = chain[ci]
			local o = AR.opp(e, rank, batch, m)
			if o == nil or #o.team == 0 then ci = #chain + 1; break end
			-- chi giu 1 tuong (tuong random dau tien cua doi bot)
			local t = o.team[1]
			o.team = { t }
			t.sid = fint(UB_SID0 + 1)
			o.force = math.floor(tonumber(t.force) or 0)
			o.f = fac
			o.id = UB_ID0 + (R.ub_n or 0) % 100000000
			o.rank = idx
			o.budget = 3
			o.tower_bot = true -- cung chinh sach hanh dong voi tran validate (giong thap bot)
			local prev_lock = R.cell_lock
			R.cell_lock = UB_VAL_ROUNDS
			local tv0 = os.clock()
			local okr, res, err = pcall(AR.run, e, o)
			R.cell_lock = prev_lock
			local tv = os.clock() - tv0
			if okr and res ~= nil and res.cut ~= true then
				UB.cur = { o = o, idx = idx, f = fac, mode = m, draw = draw, vr = res.rounds, vt = tv, pt = os.clock() - t0 }
				return
			end
			if okr and res ~= nil then err = "tran thu bi dung vong (cut), bo tuong nay" end
			if not okr then err = res end
			if first_err == nil then first_err = err end
			R.ub_retry = (R.ub_retry or 0) + 1
			if R.ub_retry <= 6 then log("boss guild bot: tuong '" .. m .. "' boss", idx, "bi loai sau", string.format("%.2fs", os.clock() - tv0) .. ":", tostring(err):sub(1, 110)) end
			if string.find(tostring(err), "LS_watchdog", 1, true) ~= nil and ci < 3 then ci = 3 else ci = ci + 1 end
			if os.clock() - t0 > 7 then break end
		end
		if os.clock() - t0 > 7 then break end
	end
	R.ub_fail = (R.ub_fail or 0) + 1
	log("boss guild bot: khong dung duoc tuong bot cho boss", idx, "-> dung boss goc cua game:", tostring(first_err):sub(1, 140))
end

function UB.mid(fm)
	local cur = UB.cur
	UB.cur = nil
	if not UB.on() then return end
	local e = ED()
	local _, FOC = classes()
	local bc = (type(e) == "table" and type(e.user_info) == "table") and e.user_info.battleCache or nil
	if type(bc) ~= "table" then return end
	local stock = (type(bc.byAttackerObjectsList) == "table") and bc.byAttackerObjectsList[1] or nil
	-- khong dung duoc tuong bot: van phong to boss goc de hinh khong bi mac dinh
	if cur == nil or FOC == nil or type(e.user_ship) ~= "table" then
		if type(stock) == "table" then
			for _, v in pairs(stock) do if type(v) == "table" then pcall(ub_resize, v) end end
		end
		return
	end
	local o = cur.o
	local added = { ships = {}, mega = {} }
	local objs, spd = {}, 0
	local ok, err = pcall(function()
		for i, t in ipairs(o.team) do
			local ship = AR.copy_roster(t.ship)
			if t.bot then
				ship.ship_id = t.sid
				if e.user_ship[t.sid] == nil then
					e.user_ship[t.sid] = ship
					added.ships[#added.ships + 1] = t.sid
				end
				if type(e.mega_info) == "table" then
					local en = { shipId = t.sid, info = t.mega or MEGA_EMPTY_JSON }
					e.mega_info[#e.mega_info + 1] = en
					added.mega[#added.mega + 1] = en
				end
			end
			local fo = FOC:new()
			fo:initWithUserData(i, ship, 1, o.id, fm)
			if t.bot then strip_bot_buff(fo) end
			if o.f ~= 1 then scale_obj(fo, o.f) end
			-- mau boss guild la mau CON LAI cua boss (dung nhu initUninoFight goc): khong de tuong bot ghi de
			local info = type(e.union_pve_info) == "table" and e.union_pve_info[tonumber(e.union_copy_fight_data_id)] or nil
			if type(info) == "table" and (tonumber(info.max_hp) or 0) > 0 and tonumber(info.current_hp) ~= nil then
				fo.healthPoint = tonumber(info.current_hp)
			end
			fo.id = o.id * 10 + i
			local so = tw_stock_obj(stock, i)
			fo.signType = tonumber(so ~= nil and so.signType or nil) or 0
			if fo.name == nil or fo.name == "" then
				local nm = tw_hero_name(ship)
				if nm == "" and so ~= nil then nm = tostring(so.name or "") end
				fo.name = nm
			end
			fo.name = ub_tok(fo.name, "Boss")
			fo.fightName = ub_tok(fo.fightName, fo.name)
			ub_resize(fo)
			objs[i] = fo
			spd = spd + (tonumber(fo.attackSpeed) or 0)
		end
		if next(objs) == nil then error("doi thu rong") end
	end)
	for _, k in ipairs(added.ships) do e.user_ship[k] = nil end
	if #added.mega > 0 and type(e.mega_info) == "table" then
		local drop = {}
		for _, en in ipairs(added.mega) do drop[en] = true end
		for i = #e.mega_info, 1, -1 do
			if drop[e.mega_info[i]] then table.remove(e.mega_info, i) end
		end
	end
	if not ok then
		R.ub_fail = (R.ub_fail or 0) + 1
		log("boss guild bot: loi dung boss:", tostring(err):sub(1, 200))
		if type(stock) == "table" then
			for _, v in pairs(stock) do if type(v) == "table" then pcall(ub_resize, v) end end
		end
		return
	end
	fm._lsTowerChainPolicy = true
	fm._lsSuperChainLimit = 1
	fm._lsSuperChainRound, fm._lsSuperChainCounts, fm._lsSuperChainNotified = nil, nil, nil
	bc.byAttackerObjectsList = { objs }
	bc.maxBattleCount = 1
	bc.byAttackComobatForce = o.force
	if objs[1] ~= nil then objs[1].attackSpeed = spd end
	bc.defender_priority = spd
	UB.spd = spd
	R.ub_ok = (R.ub_ok or 0) + 1
	R.ub_last = { idx = cur.idx, f = cur.f, mode = cur.mode, t = os.time() }
	log("boss guild bot: boss", cur.idx, "x" .. string.format("%.3f", cur.f), "hinh x" .. string.format("%.2f", UB.size()),
		"doi", cur.mode, "| thu " .. tostring(cur.vr) .. "r/" .. string.format("%.2f", tonumber(cur.vt) or 0) .. "s")
end

function UB.post(fm)
	local spd = UB.spd
	UB.spd = nil
	if spd == nil then return end
	local e = ED()
	local bc = (type(e) == "table" and type(e.user_info) == "table") and e.user_info.battleCache or nil
	if type(bc) ~= "table" then return end
	bc.defender_priority = spd
	local foes = type(bc.byAttackerObjectsList) == "table" and bc.byAttackerObjectsList[1] or nil
	if type(foes) == "table" and foes[1] ~= nil then foes[1].attackSpeed = spd end
end

rawset(_G, "ZZ_UNION_BOTS", function(stage, fm, npc_id)
	local ok, err = xpcall(function()
		if stage == "pre" then UB.pre(fm, npc_id)
		elseif stage == "mid" then UB.mid(fm)
		elseif stage == "post" then UB.post(fm) end
	end, traceback)
	if not ok then
		UB.cur, UB.spd = nil, nil
		R.ub_err = (R.ub_err or 0) + 1
		if R.ub_err <= 5 then log("boss guild bot: loi", tostring(stage), tostring(err):sub(1, 300)) end
	end
end)

LS._ub = UB

LS._tw = TW
end


-- ============================================================================
-- [LIEN SERVER] Inter-server World War (CrossTotalWar, goi cross_arena_*)
--  Truoc day chi co ban ghi rong => nut "Danh" loi (cross_arena_matching THIEU) va Report trong.
--  Nay LocalServer tu tra loi: matching (3 doi thu lay tu bang xep hang da ghi), doi hinh cong/thu,
--  challenge (toi da 3 tran, thang 2 la thang; moi tran chay engine that nhu dau truong, doi loai tran 11 -> 219),
--  danh sach bao cao + xem lai (cross_arena_check_battle_report), chon thuong, luot danh con lai, diem.
-- ============================================================================
do
local CX = {}
local TIMES_MAX = 12
local WIN_ATK, WIN_DEF, LOSE_ATK, LOSE_DEF = 30, -20, -10, 10
local REP_MAX = 10

local function cx_st()
	local c = S.cx
	if type(c) ~= "table" then c = { v = 1 }; S.cx = c end
	c.integral = math.floor(tn(c.integral, 1000))
	local d = today()
	if c.day ~= d then c.day = d; c.times = TIMES_MAX end
	c.times = math.floor(tn(c.times, TIMES_MAX))
	c.mseq = math.floor(tn(c.mseq, 0))
	c.fseq = math.floor(tn(c.fseq, 0))
	c.win = math.floor(tn(c.win, 0))
	c.lose = math.floor(tn(c.lose, 0))
	if type(c.reports) ~= "table" then c.reports = {} end
	return c
end

local function nb(s) return (string.gsub(tostring(s or "?"), "%s", "&nbsp;")) end

local function blk(code, json) return tostring(code) .. "\r\n" .. json end

-- ban ghi that cua cross_arena_init (bang xep hang nguoi choi lien server)
local function cx_info()
	if R.cx_info ~= nil then return R.cx_info end
	if H == nil or type(H.lookup) ~= "function" then return nil end
	local ok, res = pcall(H.lookup, "cross_arena_init", "")
	if not ok or type(res) ~= "string" then return nil end
	local js = string.match(res, "14834[^{]*(%b{})")
	local jl = G("json")
	if js == nil or type(jl) ~= "table" or type(jl.decode) ~= "function" then return nil end
	local ok2, d = pcall(jl.decode, js)
	if not ok2 or type(d) ~= "table" then return nil end
	R.cx_info = { js = js, d = d }
	return R.cx_info
end

local function my_uid(e) return tonumber(e.user_info.user_id) or 0 end

local function plain_entry(r)
	return { nickName = r.nickName, serverNumber = r.serverNumber or r.serverNum or 1, serverNum = r.serverNum or r.serverNumber or 1,
		integral = r.integral or 1000, combatForce = r.combatForce or 0, headPic = r.headPic or 1,
		userId = r.userId, singletonId = r.singletonId, ranking = r.ranking }
end

local function find_rank_entry(sid)
	local inf = cx_info()
	if inf == nil or type(inf.d.ranks) ~= "table" then return nil end
	for _, r in ipairs(inf.d.ranks) do
		if tostring(r.singletonId) == tostring(sid) or tostring(r.userId) == tostring(sid) then return r end
	end
	return nil
end

local function cx_opps(e, a, c)
	local out = {}
	local inf = cx_info()
	local ranks = inf ~= nil and inf.d.ranks or nil
	if type(ranks) == "table" and #ranks > 0 then
		local pool = {}
		for _, r in ipairs(ranks) do
			if tonumber(r.userId) ~= my_uid(e) then pool[#pool + 1] = r end
		end
		local n = #pool
		if n > 0 then
			local start = (c.mseq * 3) % n
			for i = 1, math.min(3, n) do out[i] = plain_entry(pool[(start + i - 1) % n + 1]) end
		end
	end
	if #out == 0 then
		-- khong co ban ghi bang xep hang: dung ten bot dau truong
		local near = AR.near_ranks(a)
		for i = 1, 3 do
			local rk = near[i] or math.max(TOP_N + i, a.rank - i)
			local o = AR.preview(e, rk, a.batch)
			out[i] = { nickName = nb(o.name), serverNumber = 1, serverNum = 1, integral = 1000, combatForce = math.floor(tn(o.force, 0)),
				headPic = 1, userId = 700000000 + rk, singletonId = 700000000 + rk, ranking = rk }
		end
	end
	return out
end

local function own_force(e)
	local inf = cx_info()
	local f = inf ~= nil and tonumber(inf.d.myCombatForce) or nil
	if f ~= nil then return f end
	local s = 0
	for _, t in ipairs(my_team(e)) do s = s + (t.force or 0) end
	return s
end

-- doi hinh: 3 doi x 6 vi tri, moi vi tri la ship_id (chuoi) hoac "0"
local function cx_auto(e)
	local fm = e.formetion
	local f, used = { {}, {}, {} }, {}
	for j = 1, 6 do
		local sid = type(fm) == "table" and fm[j + 1] or nil
		local s = (sid ~= nil and type(e.user_ship) == "table") and e.user_ship[tostring(sid)] or nil
		if type(s) == "table" and tonumber(sid) ~= nil and tonumber(sid) > 0 then
			f[1][j] = tostring(sid)
			used[tostring(sid)] = true
		else
			f[1][j] = "0"
		end
	end
	local list = {}
	for _, s in pairs(e.user_ship or {}) do
		if type(s) == "table" and tonumber(s.ship_id) ~= nil and tonumber(s.ship_template_id) ~= nil and not used[tostring(s.ship_id)] then
			list[#list + 1] = { id = tostring(s.ship_id), f = tonumber(s.hero_fight) or 0 }
		end
	end
	table.sort(list, function(x, y)
		if x.f ~= y.f then return x.f > y.f end
		return (tonumber(x.id) or 0) < (tonumber(y.id) or 0)
	end)
	local k = 1
	for t = 2, 3 do
		for j = 1, 6 do
			local it = list[k]
			if it ~= nil then f[t][j] = it.id; k = k + 1 else f[t][j] = "0" end
		end
	end
	return f
end

local function split_ids(s)
	local out = {}
	for x in string.gmatch(tostring(s or ""), "[^,]+") do out[#out + 1] = x end
	for j = #out + 1, 6 do out[j] = "0" end
	return out
end

local function cx_form(e, c, key)
	local st_ = c[key]
	if type(st_) == "table" and type(st_[1]) == "string" and type(st_[2]) == "string" and type(st_[3]) == "string" then
		return { split_ids(st_[1]), split_ids(st_[2]), split_ids(st_[3]) }
	end
	return cx_auto(e)
end

local function ids_str(ids) return table.concat(ids, ",") end

local function has_ship(e, ids)
	for j = 1, 6 do
		local id = tonumber(ids[j]) or 0
		if id > 0 and type(e.user_ship) == "table" and e.user_ship[tostring(id)] ~= nil then return true end
	end
	return false
end

-- chay 1 tran voi doi hinh `ids` (dat tam e.formetion roi tra lai); loi thi thu lai bang doi hinh hien tai
local function cx_fight(e, o, ids, rank, batch)
	local f = e.formetion
	local changed, saved = false, {}
	if type(f) == "table" and ids ~= nil and has_ship(e, ids) then
		local as_str = true
		for i = 2, 7 do
			saved[i] = f[i]
			if f[i] ~= nil and type(f[i]) ~= "string" then as_str = false end
		end
		for j = 1, 6 do
			local id = math.floor(tonumber(ids[j]) or 0)
			if id > 0 then f[j + 1] = as_str and fint(id) or id else f[j + 1] = as_str and "0" or 0 end
		end
		changed = true
	end
	local okc, res, o2, err = pcall(AR.run_safe, e, o, rank, batch)
	if changed then for i = 2, 7 do f[i] = saved[i] end end
	if not okc then res, o2, err = nil, nil, res end
	if res == nil and changed then
		okc, res, o2, err = pcall(AR.run_safe, e, o, rank, batch)
		if not okc then res, o2, err = nil, nil, res end
	end
	return res, o2, err
end

local function now_ms(e) return (os.time() + (tonumber(e.time_add_or_sub) or 0)) * 1000 end

-- ---------------------------------------------------------------- handlers
function CX.h_init(p, seq)
	local e, a = ctx()
	local inf = cx_info()
	if inf == nil then return nil end
	local c = cx_st()
	local js = inf.js
	local rank = math.max(11, 232 - math.floor((c.integral - 1000) / 5))
	js = string.gsub(js, '"integral":%-?%d+,"myCombatForce"', '"integral":' .. fint(c.integral) .. ',"myCombatForce"', 1)
	js = string.gsub(js, '"myRank":%d+', '"myRank":' .. fint(rank), 1)
	return reply(seq, "cross_arena_init", { blk(14834, js) })
end

function CX.h_remaining(p, seq)
	ctx()
	local c = cx_st()
	return reply(seq, "cross_arena_remaining_challenges", { blk(14836, '{"challengeTimes":' .. fint(c.times) .. ',"countDown":-1}') })
end

function CX.h_report_list(p, seq)
	ctx()
	local c = cx_st()
	local parts = {}
	for i, r in ipairs(c.reports) do parts[i] = jenc(r) end
	return reply(seq, "cross_arena_battle_report_list",
		{ blk(14838, '{"battleReport":[' .. table.concat(parts, ",") .. '],"count":' .. fint(#parts) .. '}') })
end

function CX.h_matching(p, seq)
	local e, a = ctx()
	local c = cx_st()
	c.mseq = c.mseq + 1
	local opps = cx_opps(e, a, c)
	R.cx_opps = {}
	for _, o in ipairs(opps) do R.cx_opps[tostring(o.singletonId)] = o end
	mark()
	return reply(seq, "cross_arena_matching", { blk(14839, jenc({ ownCombatForce = own_force(e), list = opps })) })
end

function CX.h_att_get(p, seq)
	local e = ctx()
	local c = cx_st()
	local f = cx_form(e, c, "att")
	return reply(seq, "cross_arena_attack_formation_get",
		{ blk(14841, jenc({ formation1 = ids_str(f[1]), formation2 = ids_str(f[2]), formation3 = ids_str(f[3]) })) })
end

function CX.h_att_set(p, seq)
	ctx()
	local c = cx_st()
	if p[1] ~= nil and p[2] ~= nil and p[3] ~= nil then
		c.att = { tostring(p[1]), tostring(p[2]), tostring(p[3]) }
		mark()
	end
	return reply(seq, "cross_arena_attack_formation_set", {})
end

local function parse_template(t)
	local out = {}
	for part in string.gmatch(tostring(t or ""), "[^!]+") do
		local tid, lv, evo, star, order, force = string.match(part, "^(%d+):(%d+):([^:]*):(%d+):(%d+):(%d+)")
		if tid ~= nil then
			out[#out + 1] = { shipMould = tonumber(tid), evolutionStatus = evo, qualityLevel = tonumber(order), level = tonumber(lv),
				combatForce = tonumber(force), starLevel = tonumber(star) }
		end
	end
	return out
end

function CX.h_def_get(p, seq)
	local e = ctx()
	local c = cx_st()
	local sid = tostring(p[1] or "")
	local name = "cross_arena_defensive_formation_get"
	if sid ~= "" and sid ~= "nil" then
		local r = find_rank_entry(sid)
		if r ~= nil and r.template ~= nil then
			local t1 = parse_template(r.template)
			local t2 = {}
			for i = #t1, 1, -1 do t2[#t2 + 1] = t1[i] end
			return reply(seq, name, { blk(14835, jenc({ formation1 = t1, formation2 = t2, combatForce = r.combatForce or 0,
				unionName = "-", serverNum = r.serverNum or r.serverNumber or 1, userName = r.nickName or "?" })) })
		end
		local o = R.cx_opps ~= nil and R.cx_opps[sid] or nil
		if o ~= nil then
			local team = {}
			local pr = AR.preview(e, math.max(TOP_N + 1, tonumber(o.ranking) or (TOP_N + 1)), 1)
			for i, t in ipairs(pr.team or {}) do
				team[i] = { shipMould = t.tid, evolutionStatus = t.evo, qualityLevel = tonumber(t.order) or 1, level = t.g,
					combatForce = t.force or 0, starLevel = tonumber(t.star) or 1 }
			end
			return reply(seq, name, { blk(14835, jenc({ formation1 = team, formation2 = team, combatForce = o.combatForce or 0,
				unionName = "-", serverNum = o.serverNum or 1, userName = o.nickName or "?" })) })
		end
	end
	local f = cx_form(e, c, "def")
	return reply(seq, name, { blk(14835, jenc({ formation1 = ids_str(f[1]), formation2 = ids_str(f[2]), formation3 = ids_str(f[3]),
		combatForce = own_force(e), unionName = "-", serverNum = 1, userName = nb(e.user_info.user_name) })) })
end

function CX.h_def_set(p, seq)
	ctx()
	local c = cx_st()
	if p[1] ~= nil and p[2] ~= nil and p[3] ~= nil then
		c.def = { tostring(p[1]), tostring(p[2]), tostring(p[3]) }
		mark()
	end
	return reply(seq, "cross_arena_defensive_formation_set", {})
end

function CX.h_challenge(p, seq)
	local name = "cross_arena_challenge"
	local e, a = ctx()
	local c = cx_st()
	if c.times <= 0 then return err_reply(seq, name, "LS_het_luot_khieu_chien", ERR.generic) end
	local sid = tostring(p[1] or "")
	local opp = (R.cx_opps ~= nil and R.cx_opps[sid]) or nil
	if opp == nil then
		local r = find_rank_entry(sid)
		if r ~= nil then opp = plain_entry(r) end
	end
	if opp == nil then opp = cx_opps(e, a, c)[1] end
	local att = cx_form(e, c, "att")
	local pool = AR.near_ranks(a)
	if #pool == 0 then pool = { math.max(TOP_N + 1, a.rank - 1) } end
	local wins, losses, blocks, nf = 0, 0, {}, 0
	for f = 1, 3 do
		if wins >= 2 or losses >= 2 then break end
		local rank = pool[((c.fseq + f - 1) % #pool) + 1]
		local batch = rank <= TOP_N and 1 or a.batch
		local o = AR.copy_roster(AR.preview(e, rank, batch))
		o.name = nb(opp.nickName)
		local res, o2, err = cx_fight(e, o, att[f], rank, batch)
		if res == nil then
			R.ar_errs = (R.ar_errs or 0) + 1
			AR.report_error(o2 or o, err, name)
			stat_inc("cx_fail")
			return err_reply(seq, name, "LS_loi_tinh_tran")
		end
		local init, n = string.gsub(res.init, "^(182%s+)11(%s)", "%1219%2", 1)
		if n ~= 1 then
			AR.report_error(o, "khong doi duoc battle_init_type 11 -> 219: " .. string.sub(tostring(res.init), 1, 60), name)
			return err_reply(seq, name, "LS_loi_loai_tran")
		end
		local win = (res.win == 1 and not res.cut)
		if win then wins = wins + 1 else losses = losses + 1 end
		nf = nf + 1
		blocks[#blocks + 1] = init
		blocks[#blocks + 1] = SB.block39(res)
		log("lien server: tran", f, "vs", o.name, win and "THANG" or "THUA", res.rounds, "round")
	end
	c.fseq = c.fseq + 3
	local win = wins >= 2
	local atk, def = win and WIN_ATK or LOSE_ATK, win and WIN_DEF or LOSE_DEF
	local oldi = c.integral
	c.integral = math.max(0, c.integral + atk)
	atk = c.integral - oldi
	local t = now_ms(e)
	local jres = jenc({ attackChange = atk, defendChange = def, attackIntegral = c.integral,
		defendIntegral = math.max(0, math.floor(tn(opp.integral, 1000)) + def), battleTime = t, isWin = win and 1 or 0 })
	blocks[#blocks + 1] = blk(14842, jres)
	c.times = c.times - 1
	if win then c.win = c.win + 1 else c.lose = c.lose + 1 end
	table.insert(c.reports, 1, { result = win and 1 or 0, userId = opp.userId, nickName = opp.nickName, headPic = opp.headPic,
		combatForce = opp.combatForce, serverNumber = opp.serverNumber, singletonId = opp.singletonId, integralChange = atk, time = t })
	R.cx_rep = R.cx_rep or {}
	R.cx_rep[fint(t)] = blocks
	R.ar_rep_dirty = true
	while #c.reports > REP_MAX do
		local old = table.remove(c.reports)
		if old ~= nil and R.cx_rep ~= nil then R.cx_rep[fint(tn(old.time, 0))] = nil end
	end
	save()
	stat_inc("cx_fights")
	return reply(seq, name, blocks)
end

function CX.h_check(p, seq)
	local name = "cross_arena_check_battle_report"
	ctx()
	local c = cx_st()
	local k = math.floor(tn(p[1], 0))
	local r = c.reports[k]
	local blocks = (r ~= nil and R.cx_rep ~= nil) and R.cx_rep[fint(tn(r.time, 0))] or nil
	if blocks == nil then return err_reply(seq, name, "LS_khong_con_ban_ghi_tran_(chi_luu_den_khi_thoat_game)", ERR.generic) end
	return reply(seq, name, blocks)
end

local REWARD_POOL = { "6,231,600", "6,233,15", "6,231,1200" }

function CX.h_choose_reward(p, seq)
	local name = "cross_arena_choose_reward"
	ctx()
	local pos = math.max(1, math.min(3, math.floor(tn(p[1], 1))))
	local tkey = tostring(p[2] or "")
	R.cx_claimed = R.cx_claimed or {}
	local got = REWARD_POOL[pos]
	local blocks = {}
	local json = jenc({ reward1 = REWARD_POOL[1], reward2 = REWARD_POOL[2], reward3 = REWARD_POOL[3], gotReward = got })
	if not R.cx_claimed[tkey] then
		R.cx_claimed[tkey] = true
		local items = {}
		local ty, it, qty = string.match(got, "^(%d+),(%d+),(%d+)$")
		items[1] = { typ = tonumber(ty), item = tonumber(it), qty = tonumber(qty) }
		local given = LS._apply_rewards(items)
		save()
		blocks[1] = blk(14840, json)
		if #given > 0 then
			local b = { "171", "14", fint(#given) }
			for _, g in ipairs(given) do b[#b + 1] = fint(g.item); b[#b + 1] = fint(g.typ); b[#b + 1] = fint(g.qty) end
			blocks[2] = table.concat(b, "\r\n")
		end
	else
		blocks[1] = blk(14840, json)
	end
	return reply(seq, name, blocks)
end

AR.cx_handlers = {
	cross_arena_init = CX.h_init,
	cross_arena_remaining_challenges = CX.h_remaining,
	cross_arena_battle_report_list = CX.h_report_list,
	cross_arena_matching = CX.h_matching,
	cross_arena_attack_formation_get = CX.h_att_get,
	cross_arena_attack_formation_set = CX.h_att_set,
	cross_arena_defensive_formation_get = CX.h_def_get,
	cross_arena_defensive_formation_set = CX.h_def_set,
	cross_arena_challenge = CX.h_challenge,
	cross_arena_check_battle_report = CX.h_check,
	cross_arena_choose_reward = CX.h_choose_reward,
}
AR._cx = CX

-- ============================================================================
-- [MINE WAR 3v3] Khai mo lien server (cross_mine_*, khoi 14802-14825, man CrossServerBattel*).
--  Truoc day: lenh cross_mine_user_join_not_open (9033) THIEU -> man hinh loi "attempt to index field
--  'cross_server_battel_map_close_info' (a nil value)". Nay mo che do luon o trang thai MO (dung ban ghi that cua
--  cross_mine_init cho ban do mo + 11 ham mo), va mo phong tran cuop mo bang engine that (giong Champion Trial / Tournament):
--   * moi lan cuop = 3 tran (3 doi), moi tran la 3v3 TUONG (CM.PER_TEAM) thang 2/3 tran la cuop duoc mo;
--   * doi thu la bot lay tu bang dau truong (AR.preview) bi cat con 3 tuong;
--   * replay xem lai duoc tu man Report (luu trong RAM, mat khi thoat game).
--  Muon doi 3v3 thanh 6v6 chi can doi CM.PER_TEAM = 6.
-- ============================================================================
local CM = {}
CM.PER_TEAM = 3
CM.LOOT_MAX, CM.REV_MAX = 3, 5
CM.REP_MAX = 20
CM.SERVER = 3 -- realServerId trong ban ghi cross_mine_init

function CM.st()
	local c = S.cm
	if type(c) ~= "table" then c = { v = 1 }; S.cm = c end
	local d = today()
	if c.day ~= d then c.day = d; c.loot = CM.LOOT_MAX; c.rev = CM.REV_MAX end
	c.loot = math.floor(tn(c.loot, CM.LOOT_MAX))
	c.rev = math.floor(tn(c.rev, CM.REV_MAX))
	c.mineral = math.floor(tn(c.mineral, 4208651))
	c.rank = math.floor(tn(c.rank, 500))
	c.win = math.floor(tn(c.win, 0))
	c.lose = math.floor(tn(c.lose, 0))
	if type(c.reports) ~= "table" then c.reports = {} end
	if type(c.form) ~= "table" then c.form = {} end
	if type(c.add) ~= "table" then c.add = {} end
	return c
end

function CM.levels()
	if R.cm_lv ~= nil then return R.cm_lv end
	local lv = { minl = 1, maxl = 10 }
	local dm, cmx = G("dms"), G("cross_mine_war_encouraging_exp")
	pcall(function()
		local rows = dm.searchs(dm["cross_mine_war_encouraging_exp"], cmx._type, 1)
		local lo, hi = 1000000000, -1000000000
		for _, v in ipairs(rows) do
			local l = tonumber(v[cmx.level])
			if l ~= nil then
				if l < lo then lo = l end
				if l > hi then hi = l end
			end
		end
		if hi >= lo then lv.minl, lv.maxl = lo, hi end
	end)
	R.cm_lv = lv
	return lv
end

-- ban ghi that cua cross_mine_init (ban do mo + bang xep hang server) lam nen
function CM.rec()
	if H == nil or type(H.lookup) ~= "function" then return nil end
	local ok, res = pcall(H.lookup, "cross_mine_init", "")
	if not ok or type(res) ~= "string" or string.find(res, "14805", 1, true) == nil then return nil end
	return res
end

function CM.patch(res, seq, e, c)
	res = string.gsub(res, "^%d+", function() return tostring(seq) end, 1)
	res = string.gsub(res, "14818%s+%-?%d+", function() return "14818 1" end, 1)
	res = string.gsub(res, "14813%s+%-?%d+", function() return "14813 " .. fint(c.mineral) end, 1)
	res = string.gsub(res, '"lootCount":%b{}', function() return '"lootCount":{"buyCount":0,"freeTime":' .. fint(c.loot) .. "}" end, 1)
	res = string.gsub(res, '"revengeCount":%b{}', function() return '"revengeCount":{"buyCount":0,"freeTime":' .. fint(c.rev) .. "}" end, 1)
	-- moc dem nguoc bang xep hang: dat o tuong lai de client khong tu hoi lien tuc
	res = string.gsub(res, "14825%s+%-?%d+", function() return "14825 " .. fint(now_ms(e) + 3600000) end, 1)
	return res
end

function CM.h_init(p, seq)
	local e = ctx()
	local c = CM.st()
	local rec = CM.rec()
	if rec == nil then return nil end
	return CM.patch(rec, seq, e, c)
end

function CM.h_ref(p, seq)
	local e = ctx()
	local c = CM.st()
	local rec = CM.rec()
	if rec == nil then return nil end
	-- tra ve cac khoi 14806/14813/14821/14825 cua ban ghi init (khong co ban do)
	local blocks = {}
	for _, code in ipairs({ 14806, 14813, 14821, 14825 }) do
		local v = string.match(rec, code .. "%s+(%b[])") or string.match(rec, code .. "%s+(%b{})") or string.match(rec, code .. "%s+(%-?%d+)")
		if v ~= nil then blocks[#blocks + 1] = blk(code, v) end
	end
	return CM.patch(reply(seq, "cross_mine_ref_user_mine_and_server_info", blocks), seq, e, c)
end

function CM.h_refresh(p, seq)
	local e = ctx()
	local c = CM.st()
	local rec = CM.rec()
	if rec == nil then return nil end
	local map = string.match(rec, "14805%s+(%b{})")
	local blocks = {}
	if map ~= nil then blocks[1] = blk(14805, map) end
	blocks[#blocks + 1] = blk(14819, '{"needMineNum":0}')
	blocks[#blocks + 1] = blk(14813, fint(c.mineral))
	return reply(seq, "cross_mine_user_lounch_refresh", blocks)
end

-- ---------------------------------------------------------------- doi hinh (3 doi x 6 o, "-1" = trong)
function CM.has(e, id)
	local n = tonumber(id)
	return n ~= nil and n > 0 and type(e.user_ship) == "table" and e.user_ship[fint(n)] ~= nil
end

function CM.default(e)
	local list = {}
	for _, s in pairs(e.user_ship or {}) do
		if type(s) == "table" and tonumber(s.ship_id) ~= nil and tonumber(s.ship_template_id) ~= nil then
			list[#list + 1] = { id = fint(tonumber(s.ship_id)), f = tonumber(s.hero_fight) or 0 }
		end
	end
	table.sort(list, function(x, y)
		if x.f ~= y.f then return x.f > y.f end
		return (tonumber(x.id) or 0) < (tonumber(y.id) or 0)
	end)
	local t, k = { {}, {}, {} }, 1
	for team = 1, 3 do
		for j = 1, 6 do
			if j <= CM.PER_TEAM and list[k] ~= nil then
				t[team][j] = list[k].id
				k = k + 1
			else
				t[team][j] = "-1"
			end
		end
	end
	return t
end

function CM.parse(e, str)
	if type(str) ~= "string" or str == "" then return nil end
	local t, any = {}, false
	local ti = 0
	for grp in string.gmatch(str .. "|", "([^|]*)|") do
		ti = ti + 1
		if ti > 3 then break end
		local row, j = {}, 0
		for id in string.gmatch(grp .. ",", "([^,]*),") do
			j = j + 1
			if j > 6 then break end
			if CM.has(e, id) then row[j] = fint(tonumber(id)); any = true else row[j] = "-1" end
		end
		for x = j + 1, 6 do row[x] = "-1" end
		t[ti] = row
	end
	for x = ti + 1, 3 do t[x] = { "-1", "-1", "-1", "-1", "-1", "-1" } end
	if not any then return nil end
	return t
end

function CM.form(e, c, page)
	return CM.parse(e, c.form[tostring(page)]) or CM.default(e)
end

function CM.form_str(f)
	local parts = {}
	for i = 1, 3 do parts[i] = table.concat(f[i], ",") end
	return table.concat(parts, "|")
end

function CM.h_formation(p, seq)
	local e = ctx()
	local c = CM.st()
	if tostring(p[1]) == "2" and p[3] ~= nil then
		local page = (tostring(p[2]) == "2") and "2" or "1"
		local f = CM.parse(e, tostring(p[3]))
		if f ~= nil then c.form[page] = CM.form_str(f); mark() end
	end
	return reply(seq, "cross_mine_user_formation", { blk(14812, CM.form_str(CM.form(e, c, 1)) .. "\r\n" .. CM.form_str(CM.form(e, c, 2))) })
end

-- ---------------------------------------------------------------- co vu (buff)
function CM.add_json(c)
	local lv = CM.levels()
	local a = c.add
	local sl = math.max(lv.minl, math.min(lv.maxl, math.floor(tn(a.sl, lv.minl))))
	local ul = math.max(lv.minl, math.min(lv.maxl, math.floor(tn(a.ul, lv.minl))))
	return jenc({ MaxLevel = lv.maxl, crossMineServerOreBeastInfo = { oreBeastLevel = sl, oreBeastExp = math.floor(tn(a.se, 0)) },
		userOreBeastInfo = { level = ul, exp = math.floor(tn(a.ue, 0)) } })
end

function CM.h_feed(p, seq)
	ctx()
	local c = CM.st()
	return reply(seq, "cross_mine_user_feed", { blk(14804, CM.add_json(c)), blk(14813, fint(c.mineral)) })
end

function CM.h_buy(p, seq)
	ctx()
	local c = CM.st()
	if tostring(p[1]) == "2" then c.rev = c.rev + 1 else c.loot = c.loot + 1 end
	mark()
	return reply(seq, "cross_mine_buy_loot_or_revenge", { blk(14821, jenc({ lootCount = { buyCount = 0, freeTime = c.loot },
		revengeCount = { buyCount = 0, freeTime = c.rev } })) })
end

-- ---------------------------------------------------------------- cuop mo
function CM.cut(o)
	local team, total = {}, 0
	for i = 1, math.min(CM.PER_TEAM, #o.team) do
		team[i] = o.team[i]
		total = total + (tonumber(o.team[i].force) or 0)
	end
	o.team = team
	o.force = math.floor(total)
	return o
end

function CM.opps(e, a, uid, name)
	local pool = AR.near_ranks(a)
	if #pool == 0 then pool = { math.max(TOP_N + 1, a.rank - 1) } end
	local base = math.floor(tn(uid, 0))
	local opps = {}
	for f = 1, 3 do
		local rank = pool[((base + f - 1) % #pool) + 1]
		local batch = rank <= TOP_N and 1 or a.batch
		local o = CM.cut(AR.copy_roster(AR.preview(e, rank, batch)))
		o.name = nb(name)
		if AR.vet_team ~= nil then pcall(AR.vet_team, e, o) end
		opps[f] = { o = o, rank = rank, batch = batch }
	end
	return opps
end

function CM.ship_str(t)
	local sp = tn(t.ship and t.ship.ship_wisdom, 0)
	return table.concat({ fint(t.tid), fint(t.g), tostring(t.evo), tostring(t.star), tostring(t.order), fint(tn(t.force, 0)), "0",
		fint(sp), "0", "0", tostring(t.skin or "0") }, ":")
end

function CM.enemy_array(opps)
	local arr = {}
	for f = 1, 3 do
		local row = {}
		for j = 1, 6 do
			local t = opps[f].o.team[j]
			row[j] = (j <= CM.PER_TEAM and t ~= nil) and CM.ship_str(t) or "-1"
		end
		arr[f] = row
	end
	return arr
end

function CM.my_ships(e, f)
	-- thong tin "dai dien" moi doi (tuong dau tien) cho giao dien tran
	local out = {}
	for i = 1, 3 do
		local id = nil
		for j = 1, 6 do
			if CM.has(e, f[i][j]) then id = f[i][j]; break end
		end
		local s = id ~= nil and e.user_ship[id] or nil
		if type(s) == "table" then
			out[i] = { ship_template_id = math.floor(tn(s.ship_template_id, 0)), evolution_status = tostring(s.evolution_status or "1|0,0,0,0"),
				Order = tostring(s.Order or 1) }
		else
			out[i] = { ship_template_id = 0, evolution_status = "1|0,0,0,0", Order = "1" }
		end
	end
	return out
end

function CM.enemy_ships(opps)
	local out = {}
	for i = 1, 3 do
		local t = opps[i].o.team[1]
		if t ~= nil then
			out[i] = { ship_template_id = math.floor(tn(t.tid, 0)), evolution_status = tostring(t.evo), Order = tostring(t.order) }
		else
			out[i] = { ship_template_id = 0, evolution_status = "1|0,0,0,0", Order = "1" }
		end
	end
	return out
end

function CM.rob_json(c)
	return jenc({ lootCount = { buyCount = 0, freeTime = c.loot }, revengeCount = { buyCount = 0, freeTime = c.rev } })
end

function CM.user(e, rank)
	return { headPic = my_head(e), vipLevel = math.floor(tn(e.vip_grade, 0)), level = my_grade(e), nickName = nb(my_name(e)),
		userId = math.floor(tn(my_id(e), 0)), serverId = CM.SERVER }
end

function CM.target(p)
	local uid = tostring(p[1] or "0")
	local sid = tostring(p[2] or "0")
	local info = R.cm_targets ~= nil and R.cm_targets[uid .. ":" .. sid] or nil
	return uid, sid, info
end

-- ban ghi nguoi choi trong ban do (de lay ten/cap/vip cua chu mo)
function CM.find_owner(uid, sid)
	local rec = CM.rec()
	if rec == nil then return nil end
	local jl = G("json")
	local map = string.match(rec, "14805%s+(%b{})")
	if map == nil or type(jl) ~= "table" then return nil end
	local ok, d = pcall(jl.decode, map)
	if not ok or type(d) ~= "table" then return nil end
	for _, key in ipairs({ "lunch_list", "top_list" }) do
		for _, m in ipairs(d[key] or {}) do
			local u = m.userInfo
			if type(u) == "table" and tostring(u.userId) == uid and tostring(u.serverId) == sid then return m end
		end
	end
	return nil
end

function CM.h_loot(p, seq)
	local name = "cross_mine_user_do_loot"
	local e, a = ctx()
	local c = CM.st()
	local uid, sid = tostring(p[1] or "0"), tostring(p[2] or "0")
	local mode = tostring(p[3] or "1")
	local owner = CM.find_owner(uid, sid)
	local oname = (owner ~= nil and owner.userInfo ~= nil and owner.userInfo.nickName) or "Player"
	local key = uid .. ":" .. sid
	local gain = (owner ~= nil) and math.max(1000, math.floor(tn(owner.mineScore, 20000) * 0.5)) or 20000
	if mode ~= "2" then
		R.cm_pend = { key = key, opps = CM.opps(e, a, uid, oname) }
		local pend = R.cm_pend
		local arr = CM.enemy_array(pend.opps)
		return reply(seq, name, { blk(14804, CM.add_json(c)),
			blk(14812, CM.form_str(CM.form(e, c, 1)) .. "\r\n" .. CM.form_str(CM.form(e, c, 2))),
			blk(14821, CM.rob_json(c)),
			blk(14814, jenc({ canLootMineNum = gain, byLootPresentMineNum = gain * 2, allformationArray = arr, protectData = 0 })) })
	end
	if c.loot <= 0 then return err_reply(seq, name, "LS_het_luot_cuop_mo", ERR.generic) end
	local pend = R.cm_pend
	if pend == nil or pend.key ~= key then
		pend = { key = key, opps = CM.opps(e, a, uid, oname) }
		R.cm_pend = pend
	end
	local f = CM.form(e, c, 1)
	local wins, blocks_rep = 0, {}
	for i = 1, 3 do
		local op = pend.opps[i]
		local o = AR.copy_roster(op.o)
		local res, o2, err = cx_fight(e, o, f[i], op.rank, op.batch)
		if res == nil then
			R.ar_errs = (R.ar_errs or 0) + 1
			AR.report_error(o2 or o, err, name)
			stat_inc("cm_fail")
			return err_reply(seq, name, "LS_loi_tinh_tran")
		end
		local init, n = string.gsub(res.init, "^(182%s+)11(%s)", "%1214%2", 1)
		if n ~= 1 then
			AR.report_error(o, "khong doi duoc battle_init_type 11 -> 214: " .. string.sub(tostring(res.init), 1, 60), name)
			return err_reply(seq, name, "LS_loi_loai_tran")
		end
		local win = (res.win == 1 and not res.cut)
		if win then wins = wins + 1 end
		blocks_rep[i] = { init = init, b39 = SB.block39(res) }
		log("khai mo lien server: tran", i, "vs", o.name, win and "THANG" or "THUA", res.rounds, "round", "(" .. fint(#o.team) .. " tuong)")
	end
	local won = wins >= 2
	c.loot = c.loot - 1
	local rchg = 3 + (tonumber(uid) or 0) % 5
	local myrank, thrank = c.rank, math.max(1, c.rank - 40 - (tonumber(uid) or 0) % 90)
	if won then
		c.mineral = c.mineral + gain
		c.rank = math.max(1, c.rank - rchg)
		c.win = c.win + 1
	else
		c.rank = c.rank + rchg
		c.lose = c.lose + 1
	end
	local t = now_ms(e)
	local mine_ships, foe_ships = CM.my_ships(e, f), CM.enemy_ships(pend.opps)
	local rep = { win = wins, chg = rchg, myrank = myrank, thrank = thrank, gain = gain, t = t, uid = uid, sid = sid, name = oname,
		head = (owner ~= nil and owner.userInfo ~= nil) and owner.userInfo.headPic or 1,
		lvl = (owner ~= nil and owner.userInfo ~= nil) and owner.userInfo.level or 50,
		vip = (owner ~= nil and owner.userInfo ~= nil) and owner.userInfo.vipLevel or 0 }
	local function enc(arr)
		local parts = {}
		for i = 1, 3 do parts[i] = table.concat({ fint(arr[i].ship_template_id), arr[i].evolution_status, arr[i].Order }, "~") end
		return table.concat(parts, "^")
	end
	rep.att, rep.def = enc(mine_ships), enc(foe_ships)
	table.insert(c.reports, 1, rep)
	R.cm_rep = R.cm_rep or {}
	R.cm_rep[fint(t)] = blocks_rep
	R.ar_rep_dirty = true
	while #c.reports > CM.REP_MAX do
		local old = table.remove(c.reports)
		if old ~= nil and R.cm_rep ~= nil then R.cm_rep[fint(tn(old.t, 0))] = nil end
	end
	R.cm_pend = nil
	save()
	stat_inc("cm_fights")
	return reply(seq, name, { blk(14813, fint(c.mineral)), blk(14821, CM.rob_json(c)),
		blk(14816, jenc({ index = 1, BattleResult = wins, attackShipInfo = mine_ships, byAttackShipInfo = foe_ships,
			lootUserRank = myrank, byLootUserRank = thrank, lootProduction = 2435, byLootProduction = 2435,
			canLootMineNum = won and gain or 0 })) })
end

function CM.h_battle(p, seq)
	local name = "cross_mine_load_battle_info"
	ctx()
	local c = CM.st()
	local idx, n = math.floor(tn(p[1], 0)), math.floor(tn(p[2], 0))
	local r = c.reports[idx]
	local reps = (r ~= nil and R.cm_rep ~= nil) and R.cm_rep[fint(tn(r.t, 0))] or nil
	local one = (reps ~= nil) and reps[n] or nil
	if one == nil then return err_reply(seq, name, "LS_khong_con_ban_ghi_tran_(chi_luu_den_khi_thoat_game)", ERR.generic) end
	return reply(seq, name, { one.init, one.b39 })
end

function CM.h_reports(p, seq)
	local e = ctx()
	local c = CM.st()
	local me = CM.user(e)
	local items = {}
	local function dec(s)
		local out = {}
		for part in string.gmatch(tostring(s or ""), "[^%^]+") do
			local tid, evo, ord = string.match(part, "^(%-?%d+)~([^~]*)~(.*)$")
			out[#out + 1] = { ship_template_id = tonumber(tid) or 0, evolution_status = evo or "1|0,0,0,0", Order = ord or "1" }
		end
		return out
	end
	for i, r in ipairs(c.reports) do
		local foe = { headPic = r.head, vipLevel = r.vip, level = r.lvl, nickName = r.name, userId = math.floor(tn(r.uid, 0)),
			serverId = math.floor(tn(r.sid, 1)) }
		local won = tn(r.win, 0) >= 2
		items[#items + 1] = string.format('"%d":%s', i - 1, jenc({ battleResult = r.win, rankChangeNum = r.chg, lootUserRank = r.myrank,
			byLootUserRank = r.thrank, lootProduction = 2435, byLootProduction = 2435, lootMineNum = won and r.gain or 0,
			lootTimeStemp = r.t, lootUserInfo = me, byLootUserInfo = foe, byLootServerId = foe.serverId, realServerNumber = CM.SERVER,
			attackShipInfo = dec(r.att), byAttackShipInfo = dec(r.def) }))
	end
	return reply(seq, "cross_mine_load_all_loot_info", { blk(14817, "{" .. table.concat(items, ",") .. "}"), blk(14821, CM.rob_json(c)) })
end

AR.cx_handlers.cross_mine_init = CM.h_init
AR.cx_handlers.cross_mine_user_join_not_open = CM.h_init
AR.cx_handlers.cross_mine_ref_user_mine_and_server_info = CM.h_ref
AR.cx_handlers.cross_mine_user_lounch_refresh = CM.h_refresh
AR.cx_handlers.cross_mine_user_formation = CM.h_formation
AR.cx_handlers.cross_mine_user_feed = CM.h_feed
AR.cx_handlers.cross_mine_buy_loot_or_revenge = CM.h_buy
AR.cx_handlers.cross_mine_user_do_loot = CM.h_loot
AR.cx_handlers.cross_mine_load_battle_info = CM.h_battle
AR.cx_handlers.cross_mine_load_all_loot_info = CM.h_reports
AR._cm = CM

-- ============================================================================
-- [SQUAD ARENA / team_arena_*] DAY DU (man "Squad Arena", khoi 14844-14857)
--  Che do doi 3 nguoi: Lineup (dat doi hinh thu: formation_set/get), Assembly (tap ket: tao doi / xin vao /
--  moi / duyet / duoi / nhuong doi truong / roi doi / nop doi), Adjust (doi thu tu ra tran: change_fight_turn),
--  Challenge (matching 3 doi thu + danh 3 tran that), Record (bao cao + xem lai), Award/Rule.
--  Dong doi & doi tap ket la BOT cuc bo (khong co server that). Trang thai luu trong S.ta (ben qua lan thoat game).
--  Luong: chua dat doi hinh -> state 2 (client tu mo cua so Lineup) -> state 3 (da co doi hinh, chua nop doi)
--         -> nop doi (du 3 nguoi, la doi truong) -> state 4 (mo Challenge).
--  Tat ca ham phu nam trong bang TA (khong them `local` de khong vuot gioi han 200 local cua chunk).
-- ============================================================================
local TA = {}

TA.BOTS = {
	{ id = 810001, name = "Bot_Goku", head = 1 }, { id = 810002, name = "Bot_Vegeta", head = 2 },
	{ id = 810003, name = "Bot_Gohan", head = 3 }, { id = 810004, name = "Bot_Piccolo", head = 4 },
	{ id = 810005, name = "Bot_Trunks", head = 5 }, { id = 810006, name = "Bot_Krillin", head = 6 },
	{ id = 810007, name = "Bot_Tien", head = 7 }, { id = 810008, name = "Bot_Yamcha", head = 8 },
}
-- doi tap ket co san (bots = chi so trong TA.BOTS)
TA.TEAMS = {
	{ id = 500001, name = "Squad_Saiyan", bots = { 1, 2 } }, { id = 500002, name = "Squad_Namek", bots = { 3 } },
	{ id = 500003, name = "Squad_Frieza", bots = { 4, 5 } }, { id = 500004, name = "Squad_Cell", bots = { 6 } },
	{ id = 500005, name = "Squad_Majin", bots = { 7, 8 } }, { id = 500006, name = "Squad_Hercule", bots = { 2 } },
}
TA.MAX_TIMES = 5

function TA.me_id(e) return math.floor(tonumber(e.user_info and e.user_info.user_id) or 1) end
function TA.grade(e) return math.max(1, math.floor(tonumber(e.user_info and e.user_info.user_grade) or 120)) end
function TA.now_ms(e) return (os.time() + (tonumber(e.time_add_or_sub) or 0)) * 1000 end

function TA.st()
	local c = S.ta
	if type(c) ~= "table" then c = { v = 2 }; S.ta = c end
	c.v = 2
	c.integral = math.floor(tn(c.integral, 1000))
	local d = today()
	if c.day ~= d then c.day = d; c.times = TA.MAX_TIMES end
	c.times = math.floor(tn(c.times, TA.MAX_TIMES))
	c.fseq = math.floor(tn(c.fseq, 0))
	if type(c.reports) ~= "table" then c.reports = {} end
	if type(c.hide_app) ~= "table" then c.hide_app = {} end
	if type(c.hide_inv) ~= "table" then c.hide_inv = {} end
	if type(c.team) == "table" and type(c.team.members) ~= "table" then c.team = nil end
	return c
end

-- ---------------------------------------------------------------- tuong / doi hinh
function TA.ship(e, id)
	local s = (type(e.user_ship) == "table") and e.user_ship[tostring(id)] or nil
	if type(s) == "table" and tonumber(s.ship_template_id) ~= nil then return s end
	return nil
end

function TA.entry(s)
	if s == nil then return {} end
	local f = math.floor(tonumber(s.hero_fight) or 0)
	return { shipMould = math.floor(tonumber(s.ship_template_id) or 0), evolutionStatus = tostring(s.evolution_status or "1|2,0,0,0"),
		level = math.floor(tonumber(s.ship_grade) or 1), combat = f, combatForce = f,
		starLevel = math.floor(tonumber(s.StarRating) or 1), qualityLevel = math.floor(tonumber(s.Order) or 1) }
end

-- ids (6 chuoi ship_id) -> danh sach 6 o + tong luc chien
function TA.entries(e, ids)
	local out, sum = {}, 0
	for j = 1, 6 do
		local s = TA.ship(e, ids[j])
		out[j] = TA.entry(s)
		if s ~= nil then sum = sum + math.floor(tonumber(s.hero_fight) or 0) end
	end
	return out, sum
end

-- doi hinh phong thu cua nguoi choi (6 ship_id dang chuoi)
function TA.def_ids(e, c)
	if type(c.def) == "table" and type(c.def.ids) == "string" then
		local ids = split_ids(c.def.ids)
		local any = false
		for j = 1, 6 do
			if TA.ship(e, ids[j]) ~= nil then any = true else ids[j] = "0" end
		end
		if any then return ids end
	end
	return cx_auto(e)[1]
end

-- doi hinh cua dong doi bot thu n (1,2,..): tuong manh nhat con lai (khong trung doi hinh cua nguoi choi)
function TA.bot_ids(e, c, n)
	local used = {}
	for _, id in ipairs(TA.def_ids(e, c)) do used[tostring(id)] = true end
	local list = {}
	for _, s in pairs(e.user_ship or {}) do
		if type(s) == "table" and tonumber(s.ship_id) ~= nil and tonumber(s.ship_template_id) ~= nil and not used[tostring(s.ship_id)] then
			list[#list + 1] = { id = tostring(s.ship_id), f = tonumber(s.hero_fight) or 0 }
		end
	end
	table.sort(list, function(x, y)
		if x.f ~= y.f then return x.f > y.f end
		return (tonumber(x.id) or 0) < (tonumber(y.id) or 0)
	end)
	local start = (n - 1) * 6
	if start >= #list then start = 0 end
	local ids = {}
	for j = 1, 6 do
		local it = list[start + j]
		ids[j] = it ~= nil and it.id or "0"
	end
	return ids
end

function TA.bot_by_id(id)
	for _, b in ipairs(TA.BOTS) do
		if b.id == id then return b end
	end
	return nil
end

function TA.has(list, id)
	for _, v in ipairs(list) do
		if v == id then return true end
	end
	return false
end

function TA.me_player(e, c)
	local ents, sum = TA.entries(e, TA.def_ids(e, c))
	if sum <= 0 then sum = math.floor((own_force(e) or 0) / 3) end
	return { userId = TA.me_id(e), level = TA.grade(e), nickName = my_name(e), combat = sum, headPic = my_head(e), formation = ents }
end

function TA.bot_player(e, c, bot, n)
	local ents, sum = TA.entries(e, TA.bot_ids(e, c, n))
	if sum <= 0 then sum = math.floor((own_force(e) or 0) / 3) end
	return { userId = bot.id, level = TA.grade(e), nickName = bot.name, combat = sum, headPic = bot.head, formation = ents }
end

-- ---------------------------------------------------------------- doi cua nguoi choi
function TA.rank_of(integral)
	local r = 1
	for k = 1, 10 do
		if TA.foe_integral(k) > integral then r = r + 1 end
	end
	return r
end

function TA.foe_integral(k)
	if k <= 10 then return 1000 + 40 * (11 - k) end
	return math.max(0, 1000 - 20 * (k - 10))
end

function TA.team_players(e, c)
	local out, n = {}, 0
	local me = TA.me_id(e)
	for i, id in ipairs(c.team.members) do
		if id == me then
			out[i] = TA.me_player(e, c)
		else
			n = n + 1
			out[i] = TA.bot_player(e, c, TA.bot_by_id(id) or { id = id, name = "Bot", head = 1 }, n)
		end
	end
	return out
end

-- thong tin doi day du (dung cho 14848 / 14849 / myTeamInfo)
function TA.team_full(e, c)
	local t = c.team
	local pl = TA.team_players(e, c)
	local total, pls = 0, {}
	for i = 1, 3 do
		pls[i] = pl[i] or {}
		total = total + tn(pls[i].combat, 0)
	end
	return { teamId = tostring(t.id), teamName = t.name, joinLimit = math.floor(tn(t.limit, 0)), serverNum = 1,
		combat = total, players = pls, integral = c.integral, ranking = TA.rank_of(c.integral) }
end

-- chua co doi: tom tat 1 nguoi (de man chinh van hien so lieu, khong con "11111")
function TA.solo(e, c)
	local me = TA.me_player(e, c)
	return { teamId = "0", teamName = my_name(e) .. "_Squad", joinLimit = 0, serverNum = 1, combat = me.combat,
		players = { me, {}, {} }, integral = c.integral, ranking = TA.rank_of(c.integral) }
end

function TA.state(c)
	if c.def == nil then return 2 end
	if c.team ~= nil and c.team.committed then return 4 end
	return 3
end

function TA.is_leader(e, c) return c.team ~= nil and c.team.leader == TA.me_id(e) end

-- 14846 (+14847 chua co doi | +14848 da co doi)
function TA.hall_blocks(e, c)
	if c.team == nil then
		local teams = {}
		for _, bt in ipairs(TA.TEAMS) do teams[#teams + 1] = TA.bot_team(e, c, bt) end
		return { blk(14846, '{"state":1}'), blk(14847, jenc({ teams = teams })) }
	end
	local st_ = TA.is_leader(e, c) and 3 or 2
	return { blk(14846, '{"state":' .. fint(st_) .. '}'), blk(14848, jenc(TA.team_full(e, c))) }
end

-- ---------------------------------------------------------------- doi bot (tap ket) va doi thu
function TA.bot_team(e, c, bt)
	local pls, total = {}, 0
	for i, bi in ipairs(bt.bots) do
		pls[i] = TA.bot_player(e, c, TA.BOTS[bi], i)
		total = total + tn(pls[i].combat, 0)
	end
	for i = #pls + 1, 3 do pls[i] = {} end
	return { teamId = tostring(bt.id), teamName = bt.name, joinLimit = math.floor((own_force(e) or 0) * 0.2), serverNum = 1,
		combat = total, players = pls, integral = 1000, ranking = 99 }
end

function TA.find_bot_team(tid)
	tid = tonumber(tid)
	if tid == nil then return nil end
	for _, bt in ipairs(TA.TEAMS) do
		if bt.id == tid then return bt end
	end
	return nil
end

-- vao doi bot: nguoi choi lam doi truong (bot nhuong chuc), doi duoc lap day 3 nguoi
function TA.join_bot_team(e, c, bt)
	local me = TA.me_id(e)
	local members = { me }
	for _, bi in ipairs(bt.bots) do members[#members + 1] = TA.BOTS[bi].id end
	for _, b in ipairs(TA.BOTS) do
		if #members >= 3 then break end
		if not TA.has(members, b.id) then members[#members + 1] = b.id end
	end
	while #members > 3 do table.remove(members) end
	c.team = { id = bt.id, name = bt.name, limit = math.floor((own_force(e) or 0) * 0.2), leader = me, members = members, committed = false }
	c.hide_app, c.hide_inv = {}, {}
end

function TA.invites(e, c)
	local list = {}
	if c.team == nil then
		for i = 1, 3 do
			local bt = TA.TEAMS[i]
			if not c.hide_inv[tostring(bt.id)] then list[#list + 1] = { bt = bt, info = TA.bot_team(e, c, bt) } end
		end
	end
	return list
end

function TA.applicants(e, c)
	local list = {}
	if TA.is_leader(e, c) and #c.team.members < 3 then
		for i, b in ipairs(TA.BOTS) do
			if #list >= 3 then break end
			if not TA.has(c.team.members, b.id) and not c.hide_app[tostring(b.id)] then
				list[#list + 1] = { bot = b, info = TA.bot_player(e, c, b, (i % 3) + 1) }
			end
		end
	end
	return list
end

-- doi thu (bang xep hang / matching)
function TA.foe_forms(e, a, k)
	local out = {}
	local pool = AR.near_ranks(a)
	for j = 1, 3 do
		local ents = {}
		local ok, pr = pcall(function()
			local rank = pool[((k + j - 2) % math.max(1, #pool)) + 1] or math.max(TOP_N + 1, a.rank - k)
			local batch = rank <= TOP_N and 1 or a.batch
			return AR.preview(e, rank, batch)
		end)
		if ok and type(pr) == "table" and type(pr.team) == "table" then
			for i, t in ipairs(pr.team) do
				if i > 6 then break end
				local f = math.floor(tn(t.force, 0))
				ents[i] = { shipMould = math.floor(tn(t.tid, 0)), evolutionStatus = tostring(t.evo or "1|2,0,0,0"), level = math.floor(tn(t.g, 1)),
					combat = f, combatForce = f, starLevel = math.floor(tn(t.star, 1)), qualityLevel = math.floor(tn(t.order, 1)) }
			end
		end
		out[j] = ents
	end
	return out
end

function TA.foe(e, a, k, detail)
	local f = math.floor((own_force(e) or 0) * math.max(0.5, 1.6 - 0.07 * (k - 1)))
	local forms = detail and TA.foe_forms(e, a, k) or nil
	local pls = {}
	for j = 1, 3 do
		local p = { level = TA.grade(e), userId = 700000 + k * 10 + j, nickName = "Rival" .. k .. "_" .. j, combat = math.floor(f / 3), headPic = j }
		if forms ~= nil then p.formation = forms[j] end
		pls[j] = p
	end
	return { player1 = pls[1], player2 = pls[2], player3 = pls[3], players = pls, integral = TA.foe_integral(k), teamId = 900000 + k,
		serverNum = 1, ranking = k, combat = f, teamName = "Rival" .. k, joinLimit = 0 }
end

function TA.find_team(e, a, c, tid)
	tid = tostring(tid or "")
	if c.team ~= nil and tostring(c.team.id) == tid then return TA.team_full(e, c) end
	if tid == "" or tid == "0" then return nil end
	local n = tonumber(tid)
	if n ~= nil and n > 900000 and n <= 900100 then return TA.foe(e, a, n - 900000, true) end
	local bt = TA.find_bot_team(tid)
	if bt ~= nil then return TA.bot_team(e, c, bt) end
	return nil
end

-- ---------------------------------------------------------------- handlers
function TA.h_enter(p, seq)
	local e, a = ctx()
	local c = TA.st()
	local t = c.team
	if t ~= nil and t.leader ~= TA.me_id(e) and #t.members >= 3 and not t.committed then
		t.committed = true -- doi truong bot tu nop doi khi du nguoi
		mark()
	end
	local ranks = {}
	for k = 1, 10 do ranks[k] = TA.foe(e, a, k, false) end
	local info = (t ~= nil) and TA.team_full(e, c) or TA.solo(e, c)
	for i = 1, 3 do
		local pl = info.players[i]
		if pl ~= nil and pl.userId ~= nil then
			info["player" .. i] = { level = pl.level, nickName = pl.nickName, combat = pl.combat, headPic = pl.headPic }
		end
	end
	local d = { state = TA.state(c), isLeader = TA.is_leader(e, c) and 1 or 0, redDot = 0,
		endTime = TA.now_ms(e) + 7 * 86400000, ranks = ranks, myTeamInfo = info }
	return reply(seq, "team_arena_enter", { blk(14844, jenc(d)) })
end

function TA.h_formation_get(p, seq)
	local e = ctx()
	local c = TA.st()
	local ents = TA.entries(e, TA.def_ids(e, c))
	local ani = "-1,-1,-1"
	if type(c.def) == "table" and type(c.def.ani) == "string" and c.def.ani ~= "" then ani = c.def.ani end
	return reply(seq, "team_arena_formation_get", { blk(14845, jenc({ formation = ents, magicalAnimals1 = { magicalAnimals1 = ani } })) })
end

function TA.h_formation_set(p, seq)
	local name = "team_arena_formation_set"
	local e = ctx()
	local c = TA.st()
	local ids = split_ids(p[1])
	local out, any = {}, false
	for j = 1, 6 do
		if TA.ship(e, ids[j]) ~= nil then out[j] = tostring(ids[j]); any = true else out[j] = "0" end
	end
	if not any then return err_reply(seq, name, "LS_doi_hinh_trong", ERR.generic) end
	local ani = tostring(p[2] or "")
	if ani == "" or ani == "nil" then ani = "-1,-1,-1" end
	c.def = { ids = table.concat(out, ","), ani = ani }
	save()
	return reply(seq, name, {})
end

function TA.h_hall(p, seq)
	local e = ctx()
	return reply(seq, "team_arena_enter_build_up_hall", TA.hall_blocks(e, TA.st()))
end

function TA.h_create(p, seq)
	local name = "team_arena_create_team"
	local e = ctx()
	local c = TA.st()
	if c.team ~= nil then return err_reply(seq, name, "LS_da_co_doi", ERR.generic) end
	local tname = tostring(p[1] or "")
	if tname == "" or tname == "nil" then tname = my_name(e) .. "_Squad" end
	local me = TA.me_id(e)
	c.team = { id = 300000 + me % 100000, name = tname, limit = math.floor(tn(p[2], 0)), leader = me, members = { me }, committed = false }
	c.hide_app, c.hide_inv = {}, {}
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_apply(p, seq)
	local name = "team_arena_apply"
	local e = ctx()
	local c = TA.st()
	if c.team ~= nil then return err_reply(seq, name, "LS_da_co_doi", ERR.generic) end
	local bt = TA.find_bot_team(p[1])
	if bt == nil then return err_reply(seq, name, "LS_khong_co_doi_nay_(doi_bot_500001-500006)", ERR.generic) end
	TA.join_bot_team(e, c, bt)
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_exit(p, seq)
	ctx()
	local c = TA.st()
	c.team = nil
	c.hide_app, c.hide_inv = {}, {}
	save()
	return reply(seq, "team_arena_exit_team", {})
end

function TA.h_get_invites(p, seq)
	local e = ctx()
	local c = TA.st()
	local list = {}
	for i, it in ipairs(TA.invites(e, c)) do list[i] = it.info end
	return reply(seq, "team_arena_get_invite_infos", { blk(14850, jenc({ invites = list })) })
end

function TA.h_handle_invite(p, seq)
	local name = "team_arena_handle_invite_info"
	local e = ctx()
	local c = TA.st()
	local list = TA.invites(e, c)
	local pos, typ = math.floor(tn(p[1], 0)), math.floor(tn(p[2], 0))
	if typ == 2 then
		for _, it in ipairs(list) do c.hide_inv[tostring(it.bt.id)] = true end
	else
		local it = list[pos]
		if it == nil then return err_reply(seq, name, "LS_loi_moi_khong_con", ERR.generic) end
		if typ == 1 then
			TA.join_bot_team(e, c, it.bt)
		else
			c.hide_inv[tostring(it.bt.id)] = true
		end
	end
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_can_invite(p, seq)
	local e = ctx()
	local c = TA.st()
	local list = {}
	if c.team ~= nil then
		for i, b in ipairs(TA.BOTS) do
			if not TA.has(c.team.members, b.id) then list[#list + 1] = TA.bot_player(e, c, b, (i % 3) + 1) end
		end
	end
	return reply(seq, "team_arena_get_can_invite_users", { blk(14851, jenc({ canInvites = list })) })
end

function TA.h_invite(p, seq)
	local name = "team_arena_invite"
	local e = ctx()
	local c = TA.st()
	if not TA.is_leader(e, c) then return err_reply(seq, name, "LS_chi_doi_truong_moi_duoc_moi", ERR.generic) end
	local uid = math.floor(tn(p[1], 0))
	local b = TA.bot_by_id(uid)
	if b == nil then return err_reply(seq, name, "LS_khong_tim_thay_nguoi_choi", ERR.generic) end
	if #c.team.members >= 3 then return err_reply(seq, name, "LS_doi_da_day", ERR.generic) end
	if not TA.has(c.team.members, uid) then c.team.members[#c.team.members + 1] = uid end
	c.team.committed = false
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_get_applies(p, seq)
	local e = ctx()
	local c = TA.st()
	local list = {}
	for i, it in ipairs(TA.applicants(e, c)) do list[i] = it.info end
	return reply(seq, "team_arena_get_apply_infos", { blk(14852, jenc({ applies = list })) })
end

function TA.h_handle_apply(p, seq)
	local name = "team_arena_handle_apply_info"
	local e = ctx()
	local c = TA.st()
	local list = TA.applicants(e, c)
	local pos, typ = math.floor(tn(p[1], 0)), math.floor(tn(p[2], 0))
	if typ == 2 then
		for _, it in ipairs(list) do c.hide_app[tostring(it.bot.id)] = true end
	else
		local it = list[pos]
		if it == nil then return err_reply(seq, name, "LS_don_xin_khong_con", ERR.generic) end
		if typ == 1 then
			if #c.team.members >= 3 then return err_reply(seq, name, "LS_doi_da_day", ERR.generic) end
			c.team.members[#c.team.members + 1] = it.bot.id
			c.team.committed = false
		else
			c.hide_app[tostring(it.bot.id)] = true
		end
	end
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_transfer(p, seq)
	local name = "team_arena_transfer_captain"
	local e = ctx()
	local c = TA.st()
	if not TA.is_leader(e, c) then return err_reply(seq, name, "LS_chi_doi_truong_moi_duoc_nhuong", ERR.generic) end
	local uid = math.floor(tn(p[1], 0))
	if uid == TA.me_id(e) or not TA.has(c.team.members, uid) then return err_reply(seq, name, "LS_khong_tim_thay_thanh_vien", ERR.generic) end
	c.team.leader = uid
	c.team.committed = false
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_kick(p, seq)
	local name = "team_arena_kick_out"
	local e = ctx()
	local c = TA.st()
	if not TA.is_leader(e, c) then return err_reply(seq, name, "LS_chi_doi_truong_moi_duoc_duoi", ERR.generic) end
	local uid = math.floor(tn(p[1], 0))
	if uid == TA.me_id(e) then return err_reply(seq, name, "LS_khong_the_tu_duoi_minh", ERR.generic) end
	for i, id in ipairs(c.team.members) do
		if id == uid then table.remove(c.team.members, i); break end
	end
	c.team.committed = false
	save()
	return reply(seq, name, TA.hall_blocks(e, c))
end

function TA.h_commit(p, seq)
	local name = "team_arena_commit_team"
	local e = ctx()
	local c = TA.st()
	if not TA.is_leader(e, c) then return err_reply(seq, name, "LS_chi_doi_truong_moi_duoc_nop_doi", ERR.generic) end
	if #c.team.members < 3 then return err_reply(seq, name, "LS_doi_chua_du_3_nguoi", ERR.generic) end
	c.team.committed = true
	save()
	return reply(seq, name, {})
end

function TA.h_turn(p, seq)
	local name = "team_arena_change_fight_turn"
	local e = ctx()
	local c = TA.st()
	if not TA.is_leader(e, c) then return err_reply(seq, name, "LS_chi_doi_truong_moi_duoc_doi_thu_tu", ERR.generic) end
	local order = {}
	for x in string.gmatch(tostring(p[1] or ""), "[^,]+") do order[#order + 1] = math.floor(tn(x, 0)) end
	local ok = #order == #c.team.members
	if ok then
		for _, id in ipairs(order) do
			if not TA.has(c.team.members, id) then ok = false end
		end
	end
	if not ok then return err_reply(seq, name, "LS_thu_tu_khong_hop_le", ERR.generic) end
	c.team.members = order
	save()
	return reply(seq, name, {})
end

function TA.h_team_info_named(name)
	return function(p, seq)
		local e, a = ctx()
		local c = TA.st()
		local tid = p[1]
		local info
		if tid == nil or tostring(tid) == "" or tostring(tid) == "nil" then
			info = (c.team ~= nil) and TA.team_full(e, c) or TA.solo(e, c)
		else
			info = TA.find_team(e, a, c, tid)
			if info == nil and c.team == nil and tostring(tid) == "0" then info = TA.solo(e, c) end
		end
		if info == nil then return err_reply(seq, name, "LS_khong_tim_thay_doi", ERR.generic) end
		return reply(seq, name, { blk(14849, jenc(info)) })
	end
end

function TA.h_times(p, seq)
	ctx()
	return reply(seq, "team_arena_challenge_times", { blk(14853, '{"challengeTimes":' .. fint(TA.st().times) .. ',"countDown":-1}') })
end

function TA.h_matching(p, seq)
	local e, a = ctx()
	local l = {}
	R.ta_opps = {}
	for k = 1, 3 do
		local o = TA.foe(e, a, 10 + k, false)
		l[#l + 1] = o
		R.ta_opps[tostring(o.teamId)] = o
	end
	return reply(seq, "team_arena_matching", { blk(14854, jenc({ ownCombatForce = math.floor(own_force(e) or 0), list = l })) })
end

function TA.h_reports(p, seq)
	ctx()
	local c = TA.st()
	local parts = {}
	for i, r in ipairs(c.reports) do parts[i] = jenc(r) end
	return reply(seq, "team_arena_battle_report_list",
		{ blk(14856, '{"battleReport":[' .. table.concat(parts, ",") .. '],"count":' .. fint(#parts) .. '}') })
end

-- doi hinh 3 nguoi theo thu tu ra tran
function TA.att_forms(e, c)
	local forms, n = {}, 0
	local me = TA.me_id(e)
	for i, id in ipairs(c.team.members) do
		if id == me then
			forms[i] = TA.def_ids(e, c)
		else
			n = n + 1
			forms[i] = TA.bot_ids(e, c, n)
		end
	end
	return forms
end

function TA.h_challenge(p, seq)
	local name = "team_arena_challenge"
	local e, a = ctx()
	local c = TA.st()
	if c.team == nil or not c.team.committed or not TA.is_leader(e, c) then
		return err_reply(seq, name, "LS_chua_nop_doi_hoac_khong_phai_doi_truong", ERR.generic)
	end
	if c.times <= 0 then return err_reply(seq, name, "LS_het_luot_khieu_chien", ERR.generic) end
	local tid = tostring(p[1] or "")
	local opp = R.ta_opps ~= nil and R.ta_opps[tid] or nil
	if opp == nil then opp = TA.foe(e, a, 11, false) end
	local att = TA.att_forms(e, c)
	local pool = AR.near_ranks(a)
	if #pool == 0 then pool = { math.max(TOP_N + 1, a.rank - 1) } end
	local wins, blocks = 0, {}
	for f = 1, 3 do
		local rank = pool[((c.fseq + f - 1) % #pool) + 1]
		local batch = rank <= TOP_N and 1 or a.batch
		local o = AR.copy_roster(AR.preview(e, rank, batch))
		o.name = nb(opp.players[f] and opp.players[f].nickName or opp.teamName)
		local res, o2, err = cx_fight(e, o, att[f], rank, batch)
		if res == nil then
			R.ar_errs = (R.ar_errs or 0) + 1
			AR.report_error(o2 or o, err, name)
			return err_reply(seq, name, "LS_loi_tinh_tran")
		end
		local init, n = string.gsub(res.init, "^(182%s+)11(%s)", "%1220%2", 1)
		if n ~= 1 then
			AR.report_error(o, "khong doi duoc battle_init_type 11 -> 220: " .. string.sub(tostring(res.init), 1, 60), name)
			return err_reply(seq, name, "LS_loi_loai_tran")
		end
		if res.win == 1 and not res.cut then wins = wins + 1 end
		blocks[#blocks + 1] = init
		blocks[#blocks + 1] = SB.block39(res)
	end
	c.fseq = c.fseq + 3
	local win = wins >= 2
	local atk, def = win and 30 or -10, win and -20 or 10
	local oldi = c.integral
	c.integral = math.max(0, c.integral + atk)
	atk = c.integral - oldi
	local t = now_ms(e)
	blocks[#blocks + 1] = blk(14855, jenc({ attackChange = atk, defendChange = def, attackIntegral = c.integral,
		defendIntegral = math.max(0, math.floor(tn(opp.integral, 1000)) + def), battleTime = t, isWin = win and 1 or 0 }))
	c.times = c.times - 1
	table.insert(c.reports, 1, { result = win and 1 or 0, type = 0, time = t, integralChange = atk, serverNumber = 1,
		teamId = tostring(opp.teamId), teamName = opp.teamName, combat = opp.combat, players = opp.players })
	R.ta_rep = R.ta_rep or {}
	R.ta_rep[fint(t)] = blocks
	R.ar_rep_dirty = true
	while #c.reports > 10 do
		local old = table.remove(c.reports)
		if old ~= nil then R.ta_rep[fint(tn(old.time, 0))] = nil end
	end
	save()
	return reply(seq, name, blocks)
end

function TA.h_check(p, seq)
	local name = "team_arena_check_battle_report"
	ctx()
	local c = TA.st()
	local r = c.reports[math.floor(tn(p[1], 0))]
	local blocks = (r ~= nil and R.ta_rep ~= nil) and R.ta_rep[fint(tn(r.time, 0))] or nil
	if blocks == nil then return err_reply(seq, name, "LS_khong_con_ban_ghi_tran_(chi_luu_den_khi_thoat_game)", ERR.generic) end
	return reply(seq, name, blocks)
end

