do
local function init_tn()

-- [TOURNAMENT] Che do "Peak Duel / The King's Battle" (fight type 211) offline.
-- 8 thi sinh (moi doi 1-3 tuong do NGUOI CHOI CHON, hoac ngau nhien), 7 tran: 4 vong 1 -> 2 ban ket -> chung ket.
-- Moi tran la CHUOI cap dau 1v1 (tuong tiep theo vao khi tuong truoc chet, dung nhu client 211), mo phong bang
-- engine that, luu thanh replay va xem lai duoc ngay trong man hinh Tournament goc.
local AR = LS._ar
local SB, WB = LS._sb, LS._wb
local E = AR.tn_env
local TN = {}

local UID0, SID0 = 830000000, 885000000
local N, MAXT, NM = 8, 3, 7
local CAP, BUDGET, MAXDUEL = 20, 5, 12 -- arena round limit from supplied fight_config[22]
-- het CAP round ma ca hai van song: "hiep phu" toi da OT round, ben thua (theo % mau, giong quy tac round 10 cua client)
-- bi dua ve 1 mau de don danh tiep theo ha guc -> replay luon ket thuc bang mot cu ha guc that, khong phu thuoc quy tac
-- "round 10" cua client (client chi ap dung quy tac do khi con round ke tiep trong du lieu)
local OT = 0 -- no extra rounds beyond the configured arena limit
local TOT = CAP + OT
local REP_FILE = "offline_tn_replays.txt"
local REP_MAX = 12 * 1024 * 1024
local MODES = { "full", "nomega", "safe" }
local WAIT_FRAMES = 3

local function clampi(v, lo, hi, d)
	local n = tonumber(v)
	if n == nil or n ~= n then n = d end
	n = math.floor(n)
	if n < lo then n = lo elseif n > hi then n = hi end
	return n
end

local function num(v, d)
	v = tonumber(v)
	if v == nil or v ~= v then return d end
	return v
end

-- kiem tra cau truc ket qua giai dau da luu (S.tn.t); sai -> bo
local function t_ok(t)
	if type(t) ~= "table" or t.done ~= true or type(t.c) ~= "table" or type(t.m) ~= "table" then return false end
	for i = 1, N do
		local c = t.c[i]
		if type(c) ~= "table" or type(c.name) ~= "string" or type(c.fm) ~= "string" or type(c.tids) ~= "table" or #c.tids < 1 then return false end
		if tonumber(c.uid) == nil or tonumber(c.force) == nil then return false end
		for _, v in ipairs(c.tids) do if tonumber(v) == nil then return false end end
	end
	for k = 1, NM do
		local m = t.m[k]
		if type(m) ~= "table" or type(m.file) ~= "string" then return false end
		local w, a, b = tonumber(m.w), tonumber(m.a), tonumber(m.b)
		if w == nil or a == nil or b == nil or a < 1 or a > N or b < 1 or b > N or (w ~= a and w ~= b) then return false end
	end
	if tonumber(t.seq) == nil then return false end
	return true
end

local function st()
	local a = S.tn
	if type(a) ~= "table" then
		a = { v = 1 }
		S.tn = a
	end
	a.size = clampi(a.size, 1, MAXT, 1)
	if type(a.slots) ~= "table" then a.slots = {} end
	for i = 1, N do
		local s = a.slots[i]
		if type(s) ~= "table" then
			s = {}
			a.slots[i] = s
		end
		for j = 1, MAXT do
			local v = tonumber(s[j])
			if v == nil or v ~= v or v < 1 or v > 1e9 then v = 0 end
			s[j] = math.floor(v)
		end
	end
	a.seq = clampi(a.seq, 0, 99999999, 0)
	if a.t ~= nil and not t_ok(a.t) then a.t = nil end
	return a
end

-- ten khong chua khoang trang / ky tu phan cach cua giao thuc
local function cut_utf8(s, n)
	if #s <= n then return s end
	local i = n
	while i > 0 do
		local b = string.byte(s, i + 1)
		if b ~= nil and b >= 0x80 and b < 0xC0 then i = i - 1 else break end
	end
	return string.sub(s, 1, i)
end

local function clean_name(s, dflt)
	s = tostring(s or "")
	s = string.gsub(s, "[%c%s|!:,@%^]", "_")
	s = cut_utf8(s, 36)
	if s == "" then s = dflt or "Hero" end
	return s
end

-- ten hien thi cua tuong o dang tien hoa cuoi: ship_evo_mould.name_index -> word_mould[3] (giong tw_hero_name)
function TN.hero_name(tid)
	tid = math.floor(tonumber(tid) or 0)
	local c = R.tn_names
	if c == nil then
		c = {}
		R.tn_names = c
	end
	local v = c[tid]
	if v ~= nil then return v end
	local nm = ""
	local fn, d, sch = G("smGetSkinEvoIdChange"), G("dms"), G("ship_evo_mould")
	if type(fn) == "function" and type(d) == "table" and type(sch) == "table" and type(d["ship_evo_mould"]) == "table"
		and type(d["word_mould"]) == "table" and type(d.int) == "function" and type(d.element) == "function" then
		local ok, name = pcall(function()
			local ship = { ship_template_id = tid, evolution_status = fint(E.evo_max(tid)) .. "|2,0,0,0" }
			local eid = fn(ship)
			local nid = d.int(d["ship_evo_mould"], eid, sch.name_index)
			local w = d.element(d["word_mould"], nid)
			if type(w) == "table" and w[3] ~= nil then return tostring(w[3]) end
			return ""
		end)
		if ok and type(name) == "string" then nm = name end
	end
	if nm == "" or #nm > 36 or nm == "Chưa có" then nm = "Hero" .. fint(tid) end
	nm = clean_name(nm, "Hero" .. fint(tid))
	c[tid] = nm
	return nm
end

-- he so "diem no" chuyen sang tuong ke tiep (fight_config[21].attribute, mac dinh 0.8) va tran no toi da
local function king_pct()
	local d, sch = G("dms"), G("fight_config")
	if type(d) == "table" and type(sch) == "table" and sch.attribute ~= nil and type(d["fight_config"]) == "table" and type(d.float) == "function" then
		local ok, v = pcall(function() return d.float(d["fight_config"], 21, sch.attribute) end)
		if ok and tonumber(v) ~= nil and v >= 0 and v <= 5 then return v end
	end
	return 0.8
end

local function max_sp()
	local fm = G("FightModule")
	local v = type(fm) == "table" and tonumber(fm.MAX_SP) or nil
	if v == nil or v <= 0 then v = 1000 end
	return v
end

-- ====================================================== tuong bot (dung chung voi dau truong)
local function rec_for(tid)
	R.tn_mode = R.tn_mode or {}
	local m = R.tn_mode[tid] or 1
	while m <= #MODES do
		local ok, r = pcall(AR.bot_ship, tid, 1, MODES[m])
		if ok and r ~= nil then
			R.tn_mode[tid] = m
			return r, m
		end
		m = m + 1
	end
	return nil
end

local function degrade(tid, to)
	R.tn_mode = R.tn_mode or {}
	local cur = R.tn_mode[tid] or 1
	local nxt = to or (cur + 1)
	if nxt > #MODES then nxt = #MODES end
	if nxt > cur then R.tn_mode[tid] = nxt end
end

local function hero_set()
	local set = {}
	for _, id in ipairs(LS.hero_ids()) do set[id] = true end
	return set
end

local function fm_entry(rec, sid)
	local spd = math.ceil(num(rec.ship.ship_wisdom, 0))
	return table.concat({ fint(rec.tid), fint(rec.g), tostring(rec.evo), tostring(rec.star), tostring(rec.order),
		fint(rec.force), fint(sid), fint(spd), "0", "0", "0" }, ":")
end

-- 9 muc (3 nhom x 3): client chi dung muc 1/4/7 lam icon dau vong, ViewPeakFormation can du 9 muc
local function fm_string(recs, base)
	local n = #recs
	local ents = {}
	for _ = 1, 3 do
		for j = 1, 3 do
			local k = (j <= n) and j or 1
			ents[#ents + 1] = fm_entry(recs[k], base + #ents)
		end
	end
	return table.concat(ents, "!")
end

-- ====================================================== tat tam mod bat tu / nhan sat thuong
-- tra ve true neu subHealthPoint thuc su tru mau cho phe 0 (khong bi mod chan)
local function god_probe()
	local BO = G("BattleObject")
	if type(BO) ~= "table" or type(BO.new) ~= "function" then return true end
	local ok, immortal = pcall(function()
		local o = BO:new()
		o.battleTag = 0
		o.healthPoint = 100
		o.healthMaxPoint = 100
		o:subHealthPoint(1)
		return tonumber(o.healthPoint) == 100
	end)
	if ok and immortal then return false end
	return true
end

local function zz_off()
	local saved, ups = {}, {}
	local function setg(name, fn)
		saved[#saved + 1] = { name, rawget(_G, name) }
		rawset(_G, name, fn)
	end
	setg("ZZ_GOD", function() return false end)
	setg("ZZ_DMG_MULT", function() return 1 end)
	local dbg, BO = G("debug"), G("BattleObject")
	local f = (type(BO) == "table") and rawget(BO, "subHealthPoint") or nil
	local bad = 0
	if type(dbg) == "table" and type(f) == "function" and type(dbg.getupvalue) == "function" and type(dbg.setupvalue) == "function" then
		for i = 1, 24 do
			local okg, nm, val = pcall(dbg.getupvalue, f, i)
			if not okg or nm == nil then break end
			if val == true then
				if pcall(dbg.setupvalue, f, i, false) then ups[#ups + 1] = i else bad = bad + 1 end
			end
		end
	end
	local function restore()
		for k = #ups, 1, -1 do pcall(dbg.setupvalue, f, ups[k], true) end
		for k = #saved, 1, -1 do rawset(_G, saved[k][1], saved[k][2]) end
	end
	if bad > 0 or not god_probe() then
		restore()
		return nil, "mod bat tu (ZZ) van dang chay, khong the tat tam thoi"
	end
	return restore
end

-- tat tam noi tai hoi sinh buff 22: engine danh dau "chet" (defAState=1) roi cho tuong song lai ngay trong cung nhat cat,
-- trong game that phan hien thi duoc va bang notifyReviveVisual luc dang choi truc tiep; replay da ghi san thi tuong "chet"
-- van tiep tuc danh -> du lieu mau thuan (client doi tuong ke tiep vao san som). Hoi sinh chuan (aliveState=3) khong bi anh huong.
local function revive_off()
	local BO = G("BattleObject")
	local orig = (type(BO) == "table") and rawget(BO, "tryReviveFromBuff22") or nil
	if type(orig) ~= "function" then return function() end end
	rawset(BO, "tryReviveFromBuff22", function() return false end)
	return function() rawset(BO, "tryReviveFromBuff22", orig) end
end

-- tat tam "diem combo" cua phe nguoi choi: FightModule:rountdFight cong cho MOI don cua phe 0 mot he so combo ngau nhien
-- (setGradeAttack -> grade_attack tang len, sat thuong x2~x3 theo don) de bu cho viec bo qua man choi thu cong.
-- Tournament la 2 phe ngang nhau nen phe A (tag 0) khong duoc huong uu the nay (do duoc: dau guong cung tuong, A thang ~90%).
local function grade_off()
	local FM = G("FightModule")
	local orig = (type(FM) == "table") and rawget(FM, "setGradeAttack") or nil
	if type(orig) ~= "function" then return function() end end
	rawset(FM, "setGradeAttack", function() end)
	return function() rawset(FM, "setGradeAttack", orig) end
end

-- ====================================================== mot cap dau 1v1
local function mk_fo(FOC, fm, side, idx, tag, pos, carry, bonus)
	local fo = FOC:new()
	if fo:initWithUserData(pos, side.sh[idx], tag, side.uid, fm) == false then error("history", 0) end
	E.strip(fo)
	fo.fightName = side.hn[idx]
	if carry ~= nil then
		fo.healthPoint_from_try = carry.hp
		fo.skillPoint = carry.sp
	elseif (bonus or 0) > 0 then
		fo.skillPoint = math.floor(num(fo.skillPoint, 0) + bonus)
	end
	return fo
end

-- chay mot cap dau (tuong ia cua A vs tuong ib cua B) bang engine that, luon o vi tri 2 (client 211 ep _pos="2")
local function duel(e, A, ia, B, ib, o)
	local FM, FOC, CDB = E.classes()
	if FM == nil then return nil, "khong nap duoc engine tran" end
	local scene, npc_id = WB.boss_data(1)
	if tonumber(npc_id) == nil or npc_id <= 0 then return nil, "khong co npc mau" end
	local snap = { fm = e._fightModule, ad = e.attackData, bc = e.user_info.battleCache, sn = e._scene_npc_id,
		cs = e._current_scene_id, nd = e._npc_difficulty_index, fo = e.formetion, lock = R.cell_lock, imm = R.cell_imm }
	local out
	math.randomseed(math.floor(o.seed % 2147483000) + 1)
	R.cell_lock, R.cell_imm = TOT, nil
	-- engine tran tu dua cac khoi "influence" (14710-14714) cho parser client; parser do ghi vao _ED.battleData
	-- (nil khi chua danh tran nao -> loi "index nil battleData") va co the ghi de du lieu tran dang xem. Mo phong
	-- khong can den chung (engine khong doc lai _ED.battleData) -> tam thoi vo hieu hoa trong luc chay cap dau.
	local np = G("NetworkProtocol")
	local pf0 = (type(np) == "table") and rawget(np, "parser_func") or nil
	if pf0 ~= nil then np.parser_func = function() end end
	local wd = E.wd_start(o.budget or BUDGET)
	local ok, err = xpcall(function()
		e._scene_npc_id = npc_id
		e._current_scene_id = tostring(scene)
		e._npc_difficulty_index = "1"
		local fm = FM:new()
		fm.totalRound = TOT
		e._fightModule = fm
		e.attackData = { roundCount = fm.totalRound, roundData = {} }
		local npc = CDB.load("npc", npc_id)
		local rb = {}
		-- phe "tan cong" cua initBattleField lay tu e.formetion: de rong tam thoi (ca hai phe deu la bot do ta dung)
		local f0 = snap.fo
		e.formetion = { (type(f0) == "table" and f0[1]) or "1", "0", "0", "0", "0", "0", "0" }
		fm:initBattleField(npc, "1", 11, rb, nil, false)
		e.formetion = f0
		fm.totalRound = TOT
		local bc = e.user_info.battleCache
		if type(bc) ~= "table" then error("khong co battleCache", 0) end
		bc.animalAttackObjects, bc.animalDefenderObjects = {}, {}
		fm:updateSoulStateAndLackSoulType(A.ships, 0)
		fm:updateSoulStateAndLackSoulType(B.ships, 1)
		local foA = mk_fo(FOC, fm, A, ia, 0, 2, o.carryA, o.bonusA)
		local foB = mk_fo(FOC, fm, B, ib, 1, 2, o.carryB, o.bonusB)
		bc.attackerObjects = { [2] = foA }
		bc.byAttackerObjectsList = { { [2] = foB } }
		bc.maxBattleCount = 1
		bc.attackName, bc.byAttackName = A.name, B.name
		bc.attacker_name, bc.defender_name = A.name, B.name
		bc.attackCombatForce, bc.byAttackComobatForce = A.force, B.force
		local sa, sb = num(foA.attackSpeed, 0), num(foB.attackSpeed, 0)
		local eff = sa
		if sa == sb and o.tie_b then eff = sa - 0.5 end
		bc.attackerSpeedValue, bc.attacker_priority, bc.defender_priority = eff, eff, sb
		fm:initFightOrder(e.user_info, {})
		-- giu tham chieu ngay tu dau: engine go doi tuong chet khoi fm.attackObjects / fm.byAttackObjects
		local ba = fm.attackObjects and fm.attackObjects[2]
		local bb = fm.byAttackObjects and fm.byAttackObjects[2]
		if ba == nil or bb == nil then error("khong co doi tuong chien dau", 0) end
		local function stat(b)
			local hp = num(b.healthPoint, 0)
			local mx = math.max(1, num(b.healthMaxPoint, 1))
			if hp > mx then hp = mx end
			return { dead = (b.isDead == true) or hp <= 0, hp = hp, max = mx, sp = math.max(0, num(b.skillPoint, 0)) }
		end
		local chunks, guard, cut = {}, 0, false
		local t0 = os.clock()
		local limit = TOT * 4 + 100
		local loser, ot_n = nil, 0
		while fm.hasNextRound == true do
			guard = guard + 1
			if guard > limit or os.clock() - t0 > 30 then cut = true; break end
			local rc = fm.roundCount
			if rc > CAP then
				-- het CAP round ma ca hai van song -> hiep phu: ben co % mau thap hon (hoa -> ben DUOC uu tien toc do thang) con 1 mau
				if loser == nil then
					local sa_, sb_ = stat(ba), stat(bb)
					local pa_, pb_ = sa_.hp / sa_.max, sb_.hp / sb_.max
					if pa_ == pb_ then
						loser = o.tie_b and ba or bb
					else
						loser = (pa_ < pb_) and ba or bb
					end
				end
				if loser.isDead ~= true then pcall(loser.setHealthPoint, loser, 1) end
				ot_n = ot_n + 1
			end
			local buf = {}
			fm:rountdFight(buf)
			for i = 1, #buf do
				local tv = type(buf[i])
				if tv ~= "string" and tv ~= "number" then
					R.ar_badtok = (R.ar_badtok or 0) + 1
					buf[i] = "0"
				end
			end
			chunks[#chunks + 1] = { round = rc, text = table.concat(buf, "") }
			if rc ~= fm.roundCount then fm:resetAllRoleSkillStatus() end
		end
		if #chunks == 0 then error("cap dau khong sinh ra round nao", 0) end
		out = { chunks = chunks, cut = cut, a = stat(ba), b = stat(bb), rounds = #chunks, ot = ot_n > 0 }
	end, traceback)
	E.wd_stop(wd)
	if pf0 ~= nil then np.parser_func = pf0 end
	R.cell_lock, R.cell_imm = snap.lock, snap.imm
	e._fightModule, e.attackData, e.user_info.battleCache = snap.fm, snap.ad, snap.bc
	e._scene_npc_id, e._current_scene_id, e._npc_difficulty_index = snap.sn, snap.cs, snap.nd
	e.formetion = snap.fo
	if not ok then return nil, err end
	return out
end
TN.duel = duel

local function relabel(text, nl)
	local rest = string.match(text, "^%d+(\r\n.*)$")
	if rest == nil then return nil end
	return fint(nl) .. rest
end

local function sanitize_tokens(rb)
	for i = 1, #rb do
		local tv = type(rb[i])
		if tv ~= "string" and tv ~= "number" then
			R.ar_badtok = (R.ar_badtok or 0) + 1
			rb[i] = "0"
		end
	end
end

-- ====================================================== mot tran = chuoi cap dau
-- E.rng la Park-Miller: hai hat giong gan nhau (vd. chenh 10) cho SO DAU gan nhu bang nhau -> "tung dong xu" bang so dau cua
-- cac tran trong cung mot giai se cho cung ket qua (vd. ca 7 tran deu phe B di truoc). Bo vai so dau de tach cac hat giong.
local function trng(seed)
	local r = E.rng(seed)
	for _ = 1, 6 do r() end
	return r
end

local function match_body(e, A, B, seed)
	local FM, FOC = E.classes()
	local _, npc_id = WB.boss_data(1)
	local r = trng(seed)
	local KP, MSP = king_pct(), max_sp()
	local ia, ib = 1, 1
	local carryA, carryB, bonusA, bonusB = nil, nil, 0, 0
	local label = 0
	local chunks = {}
	local duels, stales, ots, rerolls = 0, 0, 0, 0
	while ia <= #A.recs and ib <= #B.recs do
		duels = duels + 1
		if duels > MAXDUEL then error("qua nhieu cap dau trong mot tran", 0) end
		local finalduel = (ia == #A.recs and ib == #B.recs)
		local res, err
		for attempt = 0, 3 do
			res, err = TN.duel(e, A, ia, B, ib, { carryA = carryA, carryB = carryB, bonusA = bonusA, bonusB = bonusB,
				seed = seed * 7 + duels + attempt * 100003, tie_b = (r() < 0.5), budget = BUDGET })
			if res == nil then error(err, 0) end
			-- hai tuong cuoi cung cung chet trong cung mot cap dau (khong con ai de client chon thang): chay lai voi hat giong khac
			if not (finalduel and res.a.dead and res.b.dead) then break end
			rerolls = rerolls + 1
		end
		local ad, bd = res.a.dead, res.b.dead
		local stale = false
		if res.ot then ots = ots + 1 end
		if not ad and not bd then
			-- het gioi han round ma ca hai con song: client tu xu theo % mau o round nhan 10
			-- (bi giet neu % mau THAP HON; bang nhau thi phe thu hai bi giet)
			stale = true
			stales = stales + 1
			if res.a.hp / res.a.max < res.b.hp / res.b.max then ad = true else bd = true end
		end
		local map, lastorig = {}, res.chunks[#res.chunks].round
		for _, ch in ipairs(res.chunks) do
			local nl = map[ch.round]
			if nl == nil then
				if stale and ch.round == lastorig then
					nl = 10
				else
					label = label + 1
					if label == 10 then label = 11 end
					nl = label
				end
				map[ch.round] = nl
			end
			local txt = relabel(ch.text, nl)
			if txt == nil then error("round khong co tieu de so", 0) end
			chunks[#chunks + 1] = { round = nl, text = txt }
		end
		if ad then
			ia = ia + 1
			carryA = nil
			bonusA = math.min(MSP, res.a.sp) * KP
		else
			carryA = { hp = math.max(1, math.floor(res.a.hp)), sp = res.a.sp }
			bonusA = 0
		end
		if bd then
			ib = ib + 1
			carryB = nil
			bonusB = math.min(MSP, res.b.sp) * KP
		else
			carryB = { hp = math.max(1, math.floor(res.b.hp)), sp = res.b.sp }
			bonusB = 0
		end
	end
	local a_has, b_has = ia <= #A.recs, ib <= #B.recs
	local winA
	if a_has and not b_has then winA = true
	elseif b_has and not a_has then winA = false
	else winA = (r() < 0.5) end -- hai tuong cuoi cung cung chet o cung mot cap dau: boc tham

	local body, nr = SB.wire(chunks)
	if body == nil then error(nr, 0) end
	local total = math.max(label, nr, 10)
	local b39 = SB.block39({ win = winA and 1 or 0, total = total, nr = nr, body = body })

	-- khoi khoi tao tran (182 + 206): TAT CA tuong cua hai doi; client 211 tu xep hang doi theo thu tu liet ke
	local fm2 = FM:new()
	fm2.fightType = 211
	e._fightModule = fm2
	fm2:updateSoulStateAndLackSoulType(A.ships, 0)
	fm2:updateSoulStateAndLackSoulType(B.ships, 1)
	local fa, fb = {}, {}
	local spa, spb = 0, 0
	for i = 1, #A.recs do
		fa[i] = mk_fo(FOC, fm2, A, i, 0, i, nil, 0)
		spa = spa + num(fa[i].attackSpeed, 0)
	end
	for i = 1, #B.recs do
		fb[i] = mk_fo(FOC, fm2, B, i, 1, i, nil, 0)
		spb = spb + num(fb[i].attackSpeed, 0)
	end
	local bc2 = G("BattleCache"):new()
	bc2.battleType = 211
	bc2.byAttackerId = npc_id
	bc2.difficulty = "1"
	bc2.maxBattleCount = 1
	bc2.attacker_priority, bc2.defender_priority = spa, spb
	bc2.attacker_name, bc2.defender_name = A.name, B.name
	bc2.attacker_head_pic, bc2.defender_head_pic = 0, 0
	bc2.attackerObjects = fa
	bc2.byAttackerObjectsList = { fb }
	bc2.animalAttackObjects, bc2.animalDefenderObjects = {}, {}
	bc2.attackName, bc2.byAttackName = A.name, B.name
	bc2.attackCombatForce, bc2.byAttackComobatForce = A.force, B.force
	local rb = {}
	fm2:writeBattleFieldInit(bc2, 0, 1, rb)
	sanitize_tokens(rb)
	local init = string.gsub(table.concat(rb, ""), "[\r\n]+$", "")
	if string.sub(init, 1, 5) ~= "182\r\n" then error("khoi 182 sai tieu de", 0) end
	return { init = init, b39 = b39, win = winA and 1 or 0, total = total, nr = nr, duels = duels, stales = stales, ots = ots, rerolls = rerolls,
		na = #A.recs, nb = #B.recs }
end

-- chay lai khoi vua tao bang parser THAT cua client: sai dinh dang -> khong cho vao replay
local function parser_check(e, rep)
	local np = G("NetworkProtocol")
	if type(np) ~= "table" or type(np.parser_func) ~= "function" then return true end
	local before = {}
	for k, v in pairs(e) do before[k] = v end
	local ui = e.user_info
	local keep = type(ui) == "table" and { ui.last_user_grade, ui.last_user_food, ui.last_endurance } or nil
	local ok, err = pcall(function()
		np.parser_func({ resouce = reply(100, "battle_field_init", { rep.init, rep.b39 }) })
		local ad, bd = e.attackData, e.battleData
		if type(ad) ~= "table" or type(bd) ~= "table" then error("parser khong sinh du lieu tran") end
		if tonumber(bd.battle_init_type) ~= 211 then error("loai tran sau: " .. tostring(bd.battle_init_type)) end
		if tonumber(ad.roundCount) ~= rep.nr then error("so round parser doc: " .. tostring(ad.roundCount)) end
		local n = 0
		for _ in pairs(ad.roundData or {}) do n = n + 1 end
		if n ~= rep.nr then error("so round trong roundData: " .. n) end
		if tonumber(ad.isWin) ~= rep.win then error("isWin parser doc: " .. tostring(ad.isWin)) end
		if type(bd._heros) ~= "table" or bd._heros["2"] == nil then error("khong co tuong dau o phe tan cong") end
		if #(bd.__heros or {}) ~= rep.na - 1 then error("hang doi phe tan cong: " .. #(bd.__heros or {})) end
		local army = bd._armys and bd._armys[1]
		if type(army) ~= "table" or type(army._data) ~= "table" or army._data["2"] == nil then error("khong co tuong dau o phe thu") end
		if #(army.__data or {}) ~= rep.nb - 1 then error("hang doi phe thu: " .. #(army.__data or {})) end
	end)
	local diff = {}
	for k, v in pairs(e) do
		if before[k] ~= v then diff[#diff + 1] = k end
	end
	for k in pairs(before) do
		if rawget(e, k) == nil then diff[#diff + 1] = k end
	end
	for _, k in ipairs(diff) do e[k] = before[k] end
	if keep ~= nil and type(e.user_info) == "table" then
		e.user_info.last_user_grade, e.user_info.last_user_food, e.user_info.last_endurance = keep[1], keep[2], keep[3]
	end
	if not ok then return false, err end
	return true
end

-- doi tuong thi sinh -> dung cac ban ghi tuong, id tam, dang ky tam vao _ED
local function side_prepare(e, c, added, sidn)
	local side = { uid = c.uid, name = c.name, force = c.force, recs = {}, ships = {}, sh = {}, hn = {}, tids = c.tids }
	for i, tid in ipairs(c.tids) do
		local rec = rec_for(tid)
		if rec == nil then return nil, "tuong " .. fint(tid) .. " khong dung duoc" end
		side.recs[i] = rec
		local sid = SID0 + sidn.v
		sidn.v = sidn.v + 1
		while e.user_ship[fint(sid)] ~= nil do
			sid = SID0 + sidn.v
			sidn.v = sidn.v + 1
		end
		local ship = E.shallow(rec.ship)
		ship.ship_id = fint(sid)
		e.user_ship[ship.ship_id] = ship
		added.ships[#added.ships + 1] = ship.ship_id
		if type(e.mega_info) == "table" then
			local en = { shipId = ship.ship_id, info = rec.mega or E.empty_mega }
			e.mega_info[#e.mega_info + 1] = en
			added.mega[#added.mega + 1] = en
		end
		side.sh[i] = ship
		side.ships[i] = ship
		side.hn[i] = TN.hero_name(tid)
	end
	return side
end

local function cleanup_added(e, added)
	for _, k in ipairs(added.ships) do e.user_ship[k] = nil end
	if #added.mega > 0 and type(e.mega_info) == "table" then
		local drop = {}
		for _, en in ipairs(added.mega) do drop[en] = true end
		for i = #e.mega_info, 1, -1 do
			if drop[e.mega_info[i]] then table.remove(e.mega_info, i) end
		end
	end
end

-- tinh mot tran; tra ve rep hoac nil, loi
local function play_match(e, ca, cb, seed)
	if LS._lv ~= nil and LS._lv.fix_all ~= nil then LS._lv.fix_all() end
	if LS._ts ~= nil and LS._ts.force_for_fight ~= nil then pcall(LS._ts.force_for_fight, e) end
	local added = { ships = {}, mega = {} }
	local sidn = { v = 1 }
	local snap_fm = e._fightModule
	local zrestore, zerr = zz_off()
	if zrestore == nil then return nil, zerr, true end -- khong the tat mod: thu lai vo ich, cung khong phai loi cua tuong
	local rrestore = revive_off()
	local grestore = grade_off()
	local ok, res, err = xpcall(function()
		local A, ea = side_prepare(e, ca, added, sidn)
		if A == nil then return nil, ea end
		local B, eb = side_prepare(e, cb, added, sidn)
		if B == nil then return nil, eb end
		return match_body(e, A, B, seed)
	end, traceback)
	grestore()
	rrestore()
	zrestore()
	cleanup_added(e, added)
	e._fightModule = snap_fm
	math.randomseed(os.time() + math.floor((os.clock() * 1000000) % 100000))
	if not ok then return nil, res end
	if res == nil then return nil, err end
	local pok, perr = parser_check(e, res)
	if not pok then return nil, "parser client tu choi du lieu tran: " .. tostring(perr) end
	return res
end

-- ====================================================== [GUILD WAR] tran doi hinh (fight type 213)
-- Khac match_body (chuoi cap dau 1v1 cua loai 211): day la MOT tran dong doi, moi ben toi da MAXT tuong o vi tri 1..n,
-- mo phong bang engine that. Cho phep mang mau con lai (hp) tu tran truoc sang tran sau (thanh vien guild thang lien tiep).
-- Ket qua tra ve {init (khoi 182 loai 213), b39, win, total, nr, a = {{dead,hp,max}..}, b = {..}} de luu replay va
-- phuc vu nut "xem" cua man Guild War (battlefield_report_battle_info_get, tham so dau 10007).
local GW_BUDGET = 12

local function mk_fo2(FOC, fm, side, idx, tag, pos, hp)
	local fo = FOC:new()
	if fo:initWithUserData(pos, side.sh[idx], tag, side.uid, fm) == false then error("history", 0) end
	E.strip(fo)
	fo.fightName = side.hn[idx]
	if hp ~= nil then fo.healthPoint_from_try = hp end
	return fo
end

local function team_sim(e, A, B, o)
	local FM, FOC, CDB = E.classes()
	if FM == nil then return nil, "khong nap duoc engine tran" end
	local scene, npc_id = WB.boss_data(1)
	if tonumber(npc_id) == nil or npc_id <= 0 then return nil, "khong co npc mau" end
	local snap = { fm = e._fightModule, ad = e.attackData, bc = e.user_info.battleCache, sn = e._scene_npc_id,
		cs = e._current_scene_id, nd = e._npc_difficulty_index, fo = e.formetion, lock = R.cell_lock, imm = R.cell_imm }
	local out
	math.randomseed(math.floor(o.seed % 2147483000) + 1)
	R.cell_lock, R.cell_imm = TOT, nil
	-- parser client ghi vao _ED.battleData khi engine tu day khoi "influence": tam vo hieu hoa (giong TN.duel)
	local np = G("NetworkProtocol")
	local pf0 = (type(np) == "table") and rawget(np, "parser_func") or nil
	if pf0 ~= nil then np.parser_func = function() end end
	local wd = E.wd_start(o.budget or GW_BUDGET)
	local ok, err = xpcall(function()
		e._scene_npc_id = npc_id
		e._current_scene_id = tostring(scene)
		e._npc_difficulty_index = "1"
		local fm = FM:new()
		fm.totalRound = TOT
		e._fightModule = fm
		e.attackData = { roundCount = fm.totalRound, roundData = {} }
		local npc = CDB.load("npc", npc_id)
		local rb = {}
		local f0 = snap.fo
		e.formetion = { (type(f0) == "table" and f0[1]) or "1", "0", "0", "0", "0", "0", "0" }
		fm:initBattleField(npc, "1", 11, rb, nil, false)
		e.formetion = f0
		fm.totalRound = TOT
		local bc = e.user_info.battleCache
		if type(bc) ~= "table" then error("khong co battleCache", 0) end
		bc.animalAttackObjects, bc.animalDefenderObjects = {}, {}
		fm:updateSoulStateAndLackSoulType(A.ships, 0)
		fm:updateSoulStateAndLackSoulType(B.ships, 1)
		local objA, objB, spa, spb = {}, {}, 0, 0
		for i = 1, #A.recs do
			objA[i] = mk_fo2(FOC, fm, A, i, 0, i, A.hp[i])
			spa = spa + num(objA[i].attackSpeed, 0)
		end
		for i = 1, #B.recs do
			objB[i] = mk_fo2(FOC, fm, B, i, 1, i, B.hp[i])
			spb = spb + num(objB[i].attackSpeed, 0)
		end
		bc.attackerObjects = objA
		bc.byAttackerObjectsList = { objB }
		bc.maxBattleCount = 1
		bc.attackName, bc.byAttackName = A.name, B.name
		bc.attacker_name, bc.defender_name = A.name, B.name
		bc.attackCombatForce, bc.byAttackComobatForce = A.force, B.force
		-- initFightOrder so attackerSpeedValue voi toc do cua DOI TUONG DAU TIEN ben thu: bu lai de so TONG toc do hai doi
		local eff = num(objB[1].attackSpeed, 0) + (spa - spb)
		if spa == spb and o.tie_b then eff = eff - 0.5 end
		bc.attackerSpeedValue, bc.attacker_priority, bc.defender_priority = eff, spa, spb
		fm:initFightOrder(e.user_info, {})
		-- giu tham chieu ngay tu dau: engine go doi tuong chet khoi fm.attackObjects / fm.byAttackObjects
		local refA, refB = {}, {}
		for i = 1, #A.recs do refA[i] = fm.attackObjects and fm.attackObjects[i] end
		for i = 1, #B.recs do refB[i] = fm.byAttackObjects and fm.byAttackObjects[i] end
		for i = 1, #A.recs do if refA[i] == nil then error("khong co doi tuong chien dau (A" .. fint(i) .. ")", 0) end end
		for i = 1, #B.recs do if refB[i] == nil then error("khong co doi tuong chien dau (B" .. fint(i) .. ")", 0) end end
		local chunks, guard, cut = {}, 0, false
		local t0 = os.clock()
		local limit = TOT * 4 + 100
		while fm.hasNextRound == true do
			guard = guard + 1
			if guard > limit or os.clock() - t0 > 30 then cut = true; break end
			local rc = fm.roundCount
			local buf = {}
			fm:rountdFight(buf)
			sanitize_tokens(buf)
			chunks[#chunks + 1] = { round = rc, text = table.concat(buf, "") }
			if rc ~= fm.roundCount then fm:resetAllRoleSkillStatus() end
		end
		if cut then error("tran bi cat (vuot gioi han vong lap)", 0) end
		if #chunks == 0 then error("tran khong sinh ra round nao", 0) end
		local function stat(b)
			local hp = num(b.healthPoint, 0)
			local mx = math.max(1, num(b.healthMaxPoint, 1))
			if hp > mx then hp = mx end
			return { dead = (b.isDead == true) or hp <= 0, hp = hp, max = mx }
		end
		local sa, sb = {}, {}
		local alA, alB, hpA, hpB, mxA, mxB = 0, 0, 0, 0, 0, 0
		for i = 1, #A.recs do
			local s = stat(refA[i])
			sa[i] = s
			mxA = mxA + s.max
			if not s.dead then alA = alA + 1; hpA = hpA + s.hp end
		end
		for i = 1, #B.recs do
			local s = stat(refB[i])
			sb[i] = s
			mxB = mxB + s.max
			if not s.dead then alB = alB + 1; hpB = hpB + s.hp end
		end
		-- thang: phe con song; het CAP round ma ca hai con song -> phe con nhieu % mau hon (bang nhau: phe duoc uu tien toc do)
		local winA
		if alA > 0 and alB == 0 then
			winA = true
		elseif alB > 0 and alA == 0 then
			winA = false
		elseif alA > 0 and alB > 0 then
			local pa, pb = hpA / math.max(1, mxA), hpB / math.max(1, mxB)
			if pa == pb then winA = not o.tie_b else winA = pa > pb end
		else
			winA = (tonumber(fm.fightResult) == 1) -- hai ben cung bi quet sach trong mot nhat cat: theo ket qua cua engine
		end
		out = { chunks = chunks, a = sa, b = sb, winA = winA, total = tonumber(fm.totalRound) or TOT, capped = (alA > 0 and alB > 0) }
	end, traceback)
	E.wd_stop(wd)
	if pf0 ~= nil then np.parser_func = pf0 end
	R.cell_lock, R.cell_imm = snap.lock, snap.imm
	e._fightModule, e.attackData, e.user_info.battleCache = snap.fm, snap.ad, snap.bc
	e._scene_npc_id, e._current_scene_id, e._npc_difficulty_index = snap.sn, snap.cs, snap.nd
	e.formetion = snap.fo
	if not ok then return nil, err end
	return out
end

local function team_body(e, A, B, seed)
	local FM, FOC = E.classes()
	local _, npc_id = WB.boss_data(1)
	local r = trng(seed)
	local res, err = team_sim(e, A, B, { seed = seed * 7 + 1, tie_b = (r() < 0.5), budget = GW_BUDGET })
	if res == nil then error(err, 0) end
	local body, nr = SB.wire(res.chunks)
	if body == nil then error(nr, 0) end
	local total = math.max(nr, res.total, 1)
	local win = res.winA and 1 or 0
	local b39 = SB.block39({ win = win, total = total, nr = nr, body = body })

	-- khoi khoi tao tran (182): tat ca tuong hai doi o vi tri 1..n; tuong co mang mau thi hien dung mau con lai luc vao tran
	local fm2 = FM:new()
	fm2.fightType = 213
	e._fightModule = fm2
	fm2:updateSoulStateAndLackSoulType(A.ships, 0)
	fm2:updateSoulStateAndLackSoulType(B.ships, 1)
	local fa, fb = {}, {}
	local spa, spb = 0, 0
	for i = 1, #A.recs do
		fa[i] = mk_fo2(FOC, fm2, A, i, 0, i, nil)
		if A.hp[i] ~= nil then fa[i].healthPoint = A.hp[i] end
		spa = spa + num(fa[i].attackSpeed, 0)
	end
	for i = 1, #B.recs do
		fb[i] = mk_fo2(FOC, fm2, B, i, 1, i, nil)
		if B.hp[i] ~= nil then fb[i].healthPoint = B.hp[i] end
		spb = spb + num(fb[i].attackSpeed, 0)
	end
	local bc2 = G("BattleCache"):new()
	bc2.battleType = 213
	bc2.byAttackerId = npc_id
	bc2.difficulty = "1"
	bc2.maxBattleCount = 1
	bc2.attacker_priority, bc2.defender_priority = spa, spb
	bc2.attacker_name, bc2.defender_name = A.name, B.name
	bc2.attacker_head_pic, bc2.defender_head_pic = 0, 0
	bc2.attackerObjects = fa
	bc2.byAttackerObjectsList = { fb }
	bc2.animalAttackObjects, bc2.animalDefenderObjects = {}, {}
	bc2.attackName, bc2.byAttackName = A.name, B.name
	bc2.attackCombatForce, bc2.byAttackComobatForce = A.force, B.force
	local rb = {}
	fm2:writeBattleFieldInit(bc2, 0, 1, rb)
	sanitize_tokens(rb)
	local init = string.gsub(table.concat(rb, ""), "[\r\n]+$", "")
	if string.sub(init, 1, 5) ~= "182\r\n" then error("khoi 182 sai tieu de", 0) end
	return { init = init, b39 = b39, win = win, total = total, nr = nr, na = #A.recs, nb = #B.recs, a = res.a, b = res.b,
		capped = res.capped }
end

-- chay lai khoi vua tao bang parser THAT cua client (loai 213): sai dinh dang -> khong cho vao replay
local function team_parser_check(e, rep)
	local np = G("NetworkProtocol")
	if type(np) ~= "table" or type(np.parser_func) ~= "function" then return true end
	local before = {}
	for k, v in pairs(e) do before[k] = v end
	local ui = e.user_info
	local keep = type(ui) == "table" and { ui.last_user_grade, ui.last_user_food, ui.last_endurance } or nil
	local ok, err = pcall(function()
		np.parser_func({ resouce = reply(100, "battle_field_init", { rep.init, rep.b39 }) })
		local ad, bd = e.attackData, e.battleData
		if type(ad) ~= "table" or type(bd) ~= "table" then error("parser khong sinh du lieu tran") end
		if tonumber(bd.battle_init_type) ~= 213 then error("loai tran sai: " .. tostring(bd.battle_init_type)) end
		if tonumber(ad.roundCount) ~= rep.nr then error("so round parser doc: " .. tostring(ad.roundCount)) end
		local n = 0
		for _ in pairs(ad.roundData or {}) do n = n + 1 end
		if n ~= rep.nr then error("so round trong roundData: " .. n) end
		if tonumber(ad.isWin) ~= rep.win then error("isWin parser doc: " .. tostring(ad.isWin)) end
		local ha = 0
		for _ in pairs(bd._heros or {}) do ha = ha + 1 end
		if ha ~= rep.na then error("so tuong phe tan cong: " .. ha .. "/" .. rep.na) end
		local army = bd._armys and bd._armys[1]
		local hb = 0
		if type(army) == "table" then for _ in pairs(army._data or {}) do hb = hb + 1 end end
		if hb ~= rep.nb then error("so tuong phe thu: " .. hb .. "/" .. rep.nb) end
	end)
	local diff = {}
	for k, v in pairs(e) do
		if before[k] ~= v then diff[#diff + 1] = k end
	end
	for k in pairs(before) do
		if rawget(e, k) == nil then diff[#diff + 1] = k end
	end
	for _, k in ipairs(diff) do e[k] = before[k] end
	if keep ~= nil and type(e.user_info) == "table" then
		e.user_info.last_user_grade, e.user_info.last_user_food, e.user_info.last_endurance = keep[1], keep[2], keep[3]
	end
	if not ok then return false, err end
	return true
end

-- ca = {uid, name, force, tids = {...}, hp = {[i] = mau mang theo | nil}} ; cb tuong tu. Tra ve res hoac nil, loi, fatal
local function team_play(e, ca, cb, seed)
	if LS._lv ~= nil and LS._lv.fix_all ~= nil then LS._lv.fix_all() end
	if LS._ts ~= nil and LS._ts.force_for_fight ~= nil then pcall(LS._ts.force_for_fight, e) end
	local added = { ships = {}, mega = {} }
	local sidn = { v = 1 }
	local snap_fm = e._fightModule
	local zrestore, zerr = zz_off()
	if zrestore == nil then return nil, zerr, true end
	local rrestore = revive_off()
	local grestore = grade_off()
	local ok, res, err = xpcall(function()
		local A, ea = side_prepare(e, ca, added, sidn)
		if A == nil then return nil, ea end
		local B, eb = side_prepare(e, cb, added, sidn)
		if B == nil then return nil, eb end
		A.hp, B.hp = ca.hp or {}, cb.hp or {}
		return team_body(e, A, B, seed)
	end, traceback)
	grestore()
	rrestore()
	zrestore()
	cleanup_added(e, added)
	e._fightModule = snap_fm
	math.randomseed(os.time() + math.floor((os.clock() * 1000000) % 100000))
	if not ok then return nil, res end
	if res == nil then return nil, err end
	local pok, perr = team_parser_check(e, res)
	if not pok then return nil, "parser client tu choi du lieu tran 213: " .. tostring(perr) end
	return res
end
TN.team_play = team_play

-- ====================================================== kho replay (RAM + file)
local function reps_serialize(t, reps)
	local parts = { "TN1 " .. fint(t.seq) .. "\n" }
	for k = 1, NM do
		local rp = reps[t.m[k].file]
		if rp == nil then return nil end
		parts[#parts + 1] = string.format("#TN %s %d %d %d %d %d %d %d\n", t.m[k].file, #rp.init, #rp.b39, rp.win, rp.total, rp.nr, rp.na, rp.nb)
		parts[#parts + 1] = rp.init
		parts[#parts + 1] = rp.b39
		parts[#parts + 1] = "\n"
	end
	return table.concat(parts)
end

local function reps_parse(txt, seq)
	if type(txt) ~= "string" then return nil end
	local p = string.find(txt, "\n", 1, true)
	if p == nil or string.sub(txt, 1, p - 1) ~= "TN1 " .. fint(seq) then return nil end
	local reps, pos = {}, p + 1
	while pos <= #txt do
		local q = string.find(txt, "\n", pos, true)
		if q == nil then break end
		local file, li, lb, win, total, nr, na, nb = string.match(string.sub(txt, pos, q - 1),
			"^#TN (%S+) (%d+) (%d+) (%d+) (%d+) (%d+) (%d+) (%d+)$")
		if file == nil then return nil end
		li, lb = tonumber(li), tonumber(lb)
		local s1 = q + 1
		local init = string.sub(txt, s1, s1 + li - 1)
		local b39 = string.sub(txt, s1 + li, s1 + li + lb - 1)
		if #init ~= li or #b39 ~= lb or string.sub(txt, s1 + li + lb, s1 + li + lb) ~= "\n" then return nil end
		reps[file] = { init = init, b39 = b39, win = tonumber(win), total = tonumber(total), nr = tonumber(nr),
			na = tonumber(na), nb = tonumber(nb) }
		pos = s1 + li + lb + 1
	end
	return reps
end

local function rep_get(file)
	local a = st()
	local t = a.t
	if t == nil then return nil end
	if R.tn_rep == nil or R.tn_rep_seq ~= t.seq then
		local reps = nil
		if H.read_first ~= nil then
			local okr, txt = pcall(H.read_first, LS.acct_file(REP_FILE))
			if okr then reps = reps_parse(txt, t.seq) end
		end
		R.tn_rep, R.tn_rep_seq = reps or {}, t.seq
	end
	return R.tn_rep[file]
end

-- ====================================================== giai dau: bat dau / nhip chay
local function pair_of(t, k)
	if k <= 4 then return 2 * k - 1, 2 * k end
	if k == 5 then return t.m[1].w, t.m[3].w end
	if k == 6 then return t.m[2].w, t.m[4].w end
	return t.m[5].w, t.m[6].w
end

local function busy_world()
	return R.inject ~= nil or R.grant ~= nil or R.fh ~= nil or R.refresh ~= nil
end

local function random_tid(r, pool, used, taken)
	local n = #pool
	if n > 0 then
		for _ = 1, 80 do
			local tid = pool[math.floor(r() * n) + 1]
			if tid ~= nil and not used[tid] and not taken[tid] and rec_for(tid) ~= nil then return tid end
		end
		for _ = 1, 80 do
			local tid = pool[math.floor(r() * n) + 1]
			if tid ~= nil and not used[tid] and rec_for(tid) ~= nil then return tid end
		end
	end
	local all = LS.hero_ids()
	for _ = 1, 80 do
		local tid = all[math.floor(r() * #all) + 1]
		if tid ~= nil and not used[tid] and rec_for(tid) ~= nil then return tid end
	end
	return nil
end

-- dung thi sinh so s: tuong nguoi choi chon, thieu thi lay ngau nhien
local function make_contestant(a, run, s)
	local r = trng(run.seed + s * 7919)
	local valid = run.valid
	local tids, used, notes = {}, {}, {}
	for j = 1, a.size do
		local want = a.slots[s][j]
		local tid = nil
		if want > 0 and valid[want] and not used[want] then
			if rec_for(want) ~= nil then
				tid = want
			else
				notes[#notes + 1] = TN.hero_name(want)
			end
		end
		if tid == nil then tid = random_tid(r, run.pool, used, run.taken) end
		if tid == nil then return nil, "khong dung duoc tuong ngau nhien" end
		used[tid] = true
		run.taken[tid] = true
		tids[j] = tid
	end
	local recs, force = {}, 0
	for i, tid in ipairs(tids) do
		recs[i] = rec_for(tid)
		force = force + (recs[i].force or 0)
	end
	return { uid = UID0 + s, name = fint(s) .. "." .. TN.hero_name(tids[1]), tids = tids, force = math.floor(force),
		fm = fm_string(recs, SID0 + 100000 + s * 20) }, notes
end

function TN.start()
	if S == nil or not R.ready then return false, "game chua san sang" end
	if R.tn_run ~= nil then return false, "dang tinh giai dau" end
	if R.ww_run ~= nil then return false, "dang tinh giai World War, doi xong da" end
	if busy_world() then return false, "dang cap/nang tuong, thu lai sau it giay" end
	if E.classes() == nil then return false, "chua nap duoc engine tran" end
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return false, "chua co the gioi" end
	local a = st()
	local pool = E.bot_pool()
	if #pool == 0 then pool = LS.hero_ids() end
	if #pool == 0 then return false, "khong co tuong nao de chon" end
	a.seq = a.seq + 1
	local seed = (os.time() % 1000000) * 100 + (a.seq % 100)
	R.tn_err = nil
	R.tn_run = { seed = seed, step = 0, ci = 0, k = 1, phase = "pick", pool = pool, valid = hero_set(), taken = {}, notes = {},
		t = { seq = a.seq, size = a.size, seed = seed, done = false, ts = os.time(), c = {}, m = {} },
		rep = {}, t0 = os.clock(), wait = 0 }
	mark()
	log("tournament: bat dau giai", a.seq, "doi", a.size, "tuong")
	return true
end

function TN.cancel()
	if R.tn_run == nil or R.tn_busy then return false end
	R.tn_run = nil
	log("tournament: da huy")
	return true
end

local function fail(run, err)
	local first = string.match(tostring(err), "^[^\r\n]*") or ""
	R.tn_err = string.sub(first, 1, 160)
	R.tn_run = nil
	R.tn_fail = (R.tn_fail or 0) + 1
	log("tournament: LOI:", string.sub(tostring(err), 1, 600))
	toast("Tournament loi: " .. string.sub(first, 1, 90), 8)
end

local function finish(run)
	local a = st()
	local t = run.t
	t.done = true
	if not t_ok(t) then error("giai dau sinh ra du lieu khong hop le", 0) end
	local txt = reps_serialize(t, run.rep)
	if txt == nil then error("thieu replay", 0) end
	if #txt > REP_MAX then
		log("tournament: replay qua lon (" .. #txt .. " byte), chi giu trong RAM")
	elseif H.write_first ~= nil then
		local okw, resw = pcall(H.write_first, LS.acct_file(REP_FILE), txt)
		if not okw or not resw then log("tournament: khong ghi duoc", LS.acct_file(REP_FILE)) end
	end
	a.t = t
	R.tn_rep, R.tn_rep_seq = run.rep, t.seq
	R.tn_run = nil
	mark()
	LS.save_state(true)
	local champ = t.c[t.m[NM].w]
	log("tournament: xong giai", t.seq, "vo dich", champ.name, string.format("(%.1fs)", os.clock() - run.t0))
	toast("Tournament xong! Vo dich: " .. champ.name .. ". Mo lai man Tournament de xem.", 10)
	pcall(TN.refresh_ui)
end

local function step(run)
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return end
	local a = st()
	local t = run.t
	if run.phase == "pick" then
		run.ci = run.ci + 1
		local c, notes = make_contestant(a, run, run.ci)
		if c == nil then error(notes, 0) end
		t.c[run.ci] = c
		for _, nm in ipairs(notes) do run.notes[#run.notes + 1] = nm end
		run.step = run.ci
		if run.ci >= N then
			run.phase = "play"
			if #run.notes > 0 then
				toast("Tuong khong dung duoc, da doi ngau nhien: " .. table.concat(run.notes, ", "), 8)
			end
		end
		return
	end
	local k = run.k
	local ia, ib = pair_of(t, k)
	-- engine van lech nhe ve phe 0 (tag 0) du da tat combo: moi tran boc ngau nhien thi sinh nao dung phe 0 (ben trai replay);
	-- m.a la ben trai (phe 0), m.b ben phai, res.win = 1 nghia la ben trai thang
	local flip = (trng(run.seed * 1000 + k * 10 + 3)() < 0.5)
	if flip then ia, ib = ib, ia end
	local ca, cb = t.c[ia], t.c[ib]
	local res, err, fatal
	for attempt = 1, 3 do
		res, err, fatal = play_match(e, ca, cb, run.seed * 1000 + k * 10 + attempt)
		if res ~= nil then break end
		log("tournament: tran", k, "that bai lan", attempt, ":", string.sub(tostring(err), 1, 300))
		if fatal then break end
		local to = nil
		-- bi watchdog cat (tran chay qua lau): nhay thang sang ban nhe nhat (dang goc, khong Kame)
		if string.find(tostring(err), "LS_watchdog", 1, true) ~= nil then to = #MODES end
		for _, c in ipairs({ ca, cb }) do
			for _, tid in ipairs(c.tids) do degrade(tid, to) end
		end
	end
	if res == nil then error("tran " .. fint(k) .. ": " .. tostring(err), 0) end
	local file = fint(t.seq * 100 + k)
	run.rep[file] = { init = res.init, b39 = res.b39, win = res.win, total = res.total, nr = res.nr, na = res.na, nb = res.nb }
	t.m[k] = { a = ia, b = ib, w = (res.win == 1) and ia or ib, file = file, nr = res.nr, total = res.total,
		duels = res.duels, stales = res.stales, ots = res.ots, rr = res.rerolls }
	log("tournament: tran", k, ca.name, "vs", cb.name, "->", t.c[t.m[k].w].name, res.nr, "round", res.duels, "cap dau",
		string.format("(%.1fs)", os.clock() - run.t0))
	run.k = k + 1
	run.step = N + k
	if run.k > NM then finish(run) end
end

function TN.tick()
	local run = R.tn_run
	if run == nil or R.tn_busy or not R.ready or busy_world() then return end
	-- chia nho theo frame: cho vai frame giua cac buoc de giao dien kip ve
	run.wait = (run.wait or 0) + 1
	if run.wait < WAIT_FRAMES then return end
	run.wait = 0
	R.tn_busy = true
	local ok, err = xpcall(function() step(run) end, traceback)
	R.tn_busy = false
	if not ok then fail(run, err) end
end

function TN.on_world(e)
	R.tn_run, R.tn_busy = nil, false
end

-- ====================================================== khoi du lieu cho client (12710-12714, 12609)
local function uid_of(t, i) return fint(t.c[i].uid) end

-- (so tran thang, hang) cua thi sinh s: thua vong 1 -> hang 5; thua ban ket -> 3; thua chung ket -> 2; vo dich -> 1
local function wins_of(t, s)
	local mi = math.floor((s + 1) / 2)
	if t.m[mi].w ~= s then return 0, 5 end
	local ms = (mi == 1 or mi == 3) and 5 or 6
	if t.m[ms].w ~= s then return 1, 3 end
	if t.m[7].w ~= s then return 2, 2 end
	return 3, 1
end

-- ket qua cua thi sinh s: phan 11 = vong 1 ("thang,file,doi thu,vi tri 1-8"), 12 = ban ket (vi tri 9/10 neu thang),
-- 13 = chung ket (vi tri 11 chi cho nha vo dich, 0 cho a quan); cac phan 1-10 de trong
local function result_str(t, s)
	local f = {}
	local mi = math.floor((s + 1) / 2)
	local m1 = t.m[mi]
	local opp1 = (m1.a == s) and m1.b or m1.a
	local won1 = (m1.w == s)
	f[1] = (won1 and "1" or "0") .. "," .. m1.file .. "," .. uid_of(t, opp1) .. "," .. fint(s)
	if won1 then
		local ms = (mi == 1 or mi == 3) and 5 or 6
		local m2 = t.m[ms]
		local opp2 = (m2.a == s) and m2.b or m2.a
		local won2 = (m2.w == s)
		f[2] = (won2 and "1" or "0") .. "," .. m2.file .. "," .. uid_of(t, opp2) .. "," .. (won2 and (ms == 5 and "9" or "10") or "0")
		if won2 then
			local m3 = t.m[7]
			local opp3 = (m3.a == s) and m3.b or m3.a
			local champ = (m3.w == s)
			f[3] = (champ and "1" or "0") .. "," .. m3.file .. "," .. uid_of(t, opp3) .. "," .. (champ and "11" or "0")
		end
	end
	return string.rep("|", 10) .. table.concat(f, "|")
end

function TN.blocks(e)
	local a = st()
	local t = a.t
	local now = now_ms(e)
	local out = {}
	-- 12710: trang thai chung. open_type=4 (dang thi dau) + next_time trong 10 phut -> man chinh hien thang bang dau
	out[#out + 1] = table.concat({ "12710", "4", fint(now + 600000), fint(now), fint(now + 86400000), fint(now + 3600000), t and "8" or "0" }, "\r\n")
	-- 12711: nguoi choi KHONG tham gia (chi la khan gia)
	out[#out + 1] = table.concat({ "12711", "0", "0,0", "", "", "0", "0", "0", "0" }, "\r\n")
	-- 12712: danh sach thi sinh dinh cao
	if t == nil then
		out[#out + 1] = "12712\r\n0"
	else
		local b = { "12712", "8" }
		for s = 1, N do
			local c = t.c[s]
			local w, rank = wins_of(t, s)
			b[#b + 1] = uid_of(t, s)
			b[#b + 1] = c.name
			b[#b + 1] = c.fm
			b[#b + 1] = result_str(t, s)
			b[#b + 1] = fint(rank)
			b[#b + 1] = fint(w * 10)
			b[#b + 1] = "0"
		end
		out[#out + 1] = table.concat(b, "\r\n")
	end
	out[#out + 1] = "12713\r\n0\r\n0"
	out[#out + 1] = "12714\r\n0"
	return out
end

function TN.h_init(p, seq)
	local e = ED()
	if e == nil then return nil end
	return reply(seq, "the_kings_battle_init", TN.blocks(e))
end

function TN.h_manager(p, seq)
	local e = ED()
	if e == nil then return nil end
	return reply(seq, "the_kings_battle_manager", TN.blocks(e))
end

function TN.h_share(p, seq)
	if tostring(p[2]) ~= "211" then return nil end
	local rp = rep_get(tostring(p[3] or ""))
	if rp == nil then return err_reply(seq, "get_share_message", "LS_khong_co_tran_tournament", ERR.generic) end
	return reply(seq, "get_share_message", { rp.init, rp.b39 })
end

-- bang xep hang diem Tournament (order_get_info loai 7): khoi 12609 = 3 truong dau + so luong + 20 truong moi dong
function TN.h_order(p, seq)
	if math.floor(tn(p[1], -1)) ~= 7 then return LS._cs.h_order(p, seq) end
	local e = ED()
	if e == nil then return nil end
	local a = st()
	local t = a.t
	local from = math.max(1, math.floor(tn(p[2], 1)))
	local to = math.min(N, math.floor(tn(p[3], N)))
	local list = {}
	if t ~= nil then
		for s = 1, N do
			local w, rank = wins_of(t, s)
			list[#list + 1] = { s = s, w = w, rank = rank }
		end
		table.sort(list, function(x, y)
			if x.w ~= y.w then return x.w > y.w end
			return x.s < y.s
		end)
	end
	to = math.min(to, #list)
	local n = math.max(0, to - from + 1)
	local b = { "12609", "0", "0", "0", fint(n) }
	local lv = fint(AR.lv_max())
	for i = from, to do
		local s = list[i].s
		local c = t.c[s]
		local vals = { uid_of(t, s), c.name, "1", fint(1 + (s % 8)), "0", lv, "0", "0", fint(c.force), "-", "0",
			fint(list[i].w * 10), fint(list[i].w), "0", "0", "0", "0", "-", "0", "0" }
		for _, v in ipairs(vals) do b[#b + 1] = tostring(v) end
	end
	return reply(seq, "order_get_info", { table.concat(b, "\r\n") })
end

-- cap nhat man hinh dang mo (neu co) ngay khi giai xong
function TN.refresh_ui()
	local e = ED()
	local np = G("NetworkProtocol")
	if e == nil or type(np) ~= "table" or type(np.parser_func) ~= "function" then return end
	np.parser_func({ resouce = reply(100, "the_kings_battle_init", TN.blocks(e)) })
	local sm = G("state_machine")
	if type(sm) == "table" and type(sm.excute) == "function" then
		pcall(sm.excute, "sm_battleof_kings_review_update_draw", 0, nil)
	end
end

-- ====================================================== API cho bang chon tuong (OfflineMock)
function LS.tn_info()
	if S == nil then return nil end
	local a = st()
	local run = R.tn_run
	local t = a.t
	local slots = {}
	for i = 1, N do slots[i] = { a.slots[i][1], a.slots[i][2], a.slots[i][3] } end
	local champ = nil
	if t ~= nil then champ = t.c[t.m[NM].w].name end
	return { size = a.size, slots = slots, running = run ~= nil, step = run and run.step or 0, total = N + NM,
		err = R.tn_err, has = t ~= nil, seq = t and t.seq or 0, champ = champ, ready = R.ready == true }
end

function LS.tn_pool()
	local out = {}
	for i, id in ipairs(LS.hero_ids()) do out[i] = id end
	return out
end

function LS.tn_name(tid) return TN.hero_name(tid) end

function LS.tn_set_slot(slot, idx, tid)
	if S == nil then return false end
	slot, idx = math.floor(tn(slot, 0)), math.floor(tn(idx, 0))
	if slot < 1 or slot > N or idx < 1 or idx > MAXT then return false end
	tid = math.max(0, math.floor(tn(tid, 0)))
	if tid > 0 and not hero_set()[tid] then return false end
	local a = st()
	a.slots[slot][idx] = tid
	mark()
	return true
end

function LS.tn_set_size(n)
	if S == nil then return false end
	local a = st()
	a.size = clampi(n, 1, MAXT, 1)
	mark()
	return a.size
end

function LS.tn_clear()
	if S == nil then return false end
	local a = st()
	for i = 1, N do for j = 1, MAXT do a.slots[i][j] = 0 end end
	mark()
	return true
end

-- dien ngau nhien vao cac o con trong (khong trung tuong)
function LS.tn_random()
	if S == nil then return false end
	local a = st()
	local pool = E.bot_pool()
	if #pool == 0 then pool = LS.hero_ids() end
	if #pool == 0 then return false end
	local r = trng(os.time() + (R.sync_n or 0))
	local taken = {}
	for i = 1, N do for j = 1, MAXT do if a.slots[i][j] > 0 then taken[a.slots[i][j]] = true end end end
	for i = 1, N do
		for j = 1, a.size do
			if a.slots[i][j] == 0 then
				for _ = 1, 60 do
					local tid = pool[math.floor(r() * #pool) + 1]
					if tid ~= nil and not taken[tid] then
						taken[tid] = true
						a.slots[i][j] = tid
						break
					end
				end
			end
		end
	end
	mark()
	return true
end

function LS.tn_start() return TN.start() end
function LS.tn_cancel() return TN.cancel() end

function TN.dump_line()
	local a = S ~= nil and S.tn or nil
	if type(a) ~= "table" then return "[LS Tournament] chua khoi tao" end
	local t = a.t
	return "[LS Tournament] giai #" .. tostring(a.seq or 0) .. (t_ok(t) and (" | co ket qua, vo dich " .. t.c[t.m[NM].w].name) or " | chua co ket qua")
		.. (R.tn_run ~= nil and (" | dang tinh buoc " .. tostring(R.tn_run.step)) or "")
		.. (R.tn_err ~= nil and (" | loi cuoi: " .. R.tn_err) or "")
end

TN.st, TN.t_ok, TN.play_match, TN.duel_cap = st, t_ok, play_match, CAP
TN.rec_for, TN.zz_off, TN.parser_check = rec_for, zz_off, parser_check
TN.reps_serialize, TN.reps_parse = reps_serialize, reps_parse
-- [WORLD WAR] module Inter-server World War (init_ww) dung lai cac ham nay
TN.clampi, TN.trng, TN.fm_string = clampi, trng, fm_string
TN.random_tid, TN.hero_set, TN.busy_world = random_tid, hero_set, busy_world
LS._tn = TN
end
init_tn()
end

do
local function init_ww()

-- [WORLD WAR] Che do "Inter-server World War" (Dai chien Lien server = Cross-server Kings Battle, lenh 9149-9158,
-- khoi 14826-14833) offline. GIONG Tournament: 8 thi sinh, 7 tran (4 vong 1 -> 2 ban ket -> chung ket), moi tran duoc mo phong
-- bang engine that + luu replay, xem lai bang nut "xem" co san cua man hinh lien server. KHAC Tournament: moi doi CO DINH 3 tuong (3v3).
-- Du lieu tra ve cho client la JSON (khac voi Tournament dung khoi text 12710-12714).
local AR, TN = LS._ar, LS._tn
if AR == nil or TN == nil then return end
local E = AR.tn_env
local WW = {}

local UID0 = 840000000
local N, MAXT, NM = 8, 3, 7
local NSRV = 4 -- so server gia lap (chi de hien thi ten server canh ten nguoi choi)
local REP_FILE = "offline_ww_replays.txt"
local REP_MAX = 12 * 1024 * 1024
local WAIT_FRAMES = 3
local clampi, trng, fm_string = TN.clampi, TN.trng, TN.fm_string
local random_tid, hero_set, busy_world = TN.random_tid, TN.hero_set, TN.busy_world

-- ====================================================== JSON toi gian (client dung json.decode)
local EMPTY_ARR = {}

local function jstr(s)
	s = string.gsub(tostring(s), '[%c"\\]', function(c)
		if c == '"' then return '\\"' end
		if c == "\\" then return "\\\\" end
		return string.format("\\u%04x", string.byte(c))
	end)
	return '"' .. s .. '"'
end

local function jenc(v)
	local tv = type(v)
	if v == nil then return "null" end
	if tv == "boolean" then return v and "true" or "false" end
	if tv == "number" then
		if v ~= v or v == math.huge or v == -math.huge then return "0" end
		if v == math.floor(v) then return fint(v) end
		return string.format("%.6g", v)
	end
	if tv == "string" then return jstr(v) end
	if tv == "table" then
		if v == EMPTY_ARR then return "[]" end
		if v[1] ~= nil then
			local p = {}
			for i = 1, #v do p[i] = jenc(v[i]) end
			return "[" .. table.concat(p, ",") .. "]"
		end
		local keys = {}
		for k in pairs(v) do keys[#keys + 1] = k end
		table.sort(keys)
		local p = {}
		for _, k in ipairs(keys) do p[#p + 1] = jstr(k) .. ":" .. jenc(v[k]) end
		return "{" .. table.concat(p, ",") .. "}"
	end
	return "null"
end

-- ====================================================== trang thai luu (S.ww)
local function st()
	local a = S.ww
	if type(a) ~= "table" then
		a = { v = 1 }
		S.ww = a
	end
	if type(a.slots) ~= "table" then a.slots = {} end
	for i = 1, N do
		local s = a.slots[i]
		if type(s) ~= "table" then
			s = {}
			a.slots[i] = s
		end
		for j = 1, MAXT do
			local v = tonumber(s[j])
			if v == nil or v ~= v or v < 1 or v > 1e9 then v = 0 end
			s[j] = math.floor(v)
		end
	end
	a.seq = clampi(a.seq, 0, 99999999, 0)
	if a.t ~= nil and not TN.t_ok(a.t) then a.t = nil end
	return a
end

local function srv_of(c) return ((math.floor(tn(c.uid, UID0)) - UID0 - 1) % NSRV) + 1 end
local function sid_of(c) return fint(c.uid) end
local function ship_str(c) return (string.gsub(c.fm, "!", "@")) end

local function user_info(c)
	local uid = math.floor(tn(c.uid, UID0))
	return { userId = uid, nickName = c.name, headPic = 1 + (uid % 8), level = AR.lv_max(), vipLevel = 0, titleInfo = "",
		combatForce = math.floor(tn(c.force, 0)) }
end

-- ====================================================== giai dau
local function pair_of(t, k)
	if k <= 4 then return 2 * k - 1, 2 * k end
	if k == 5 then return t.m[1].w, t.m[2].w end
	if k == 6 then return t.m[3].w, t.m[4].w end
	return t.m[5].w, t.m[6].w
end

local function make_contestant(a, run, s)
	local r = trng(run.seed + s * 7919)
	local valid = run.valid
	local tids, used, notes = {}, {}, {}
	for j = 1, MAXT do
		local want = a.slots[s][j]
		local tid = nil
		if want > 0 and valid[want] and not used[want] then
			if TN.rec_for(want) ~= nil then
				tid = want
			else
				notes[#notes + 1] = TN.hero_name(want)
			end
		end
		if tid == nil then tid = random_tid(r, run.pool, used, run.taken) end
		if tid == nil then return nil, "khong dung duoc tuong ngau nhien" end
		used[tid] = true
		run.taken[tid] = true
		tids[j] = tid
	end
	local recs, force = {}, 0
	for i, tid in ipairs(tids) do
		recs[i] = TN.rec_for(tid)
		force = force + (recs[i].force or 0)
	end
	return { uid = UID0 + s, name = fint(s) .. "." .. TN.hero_name(tids[1]), tids = tids, force = math.floor(force),
		fm = fm_string(recs, 885000000 + 200000 + s * 20) }, notes
end

function WW.start()
	if S == nil or not R.ready then return false, "game chua san sang" end
	if R.ww_run ~= nil then return false, "dang tinh giai dau" end
	if R.tn_run ~= nil then return false, "dang tinh giai Tournament, doi xong da" end
	if busy_world() then return false, "dang cap/nang tuong, thu lai sau it giay" end
	if E.classes() == nil then return false, "chua nap duoc engine tran" end
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return false, "chua co the gioi" end
	local a = st()
	local pool = E.bot_pool()
	if #pool == 0 then pool = LS.hero_ids() end
	if #pool == 0 then return false, "khong co tuong nao de chon" end
	a.seq = a.seq + 1
	local seed = (os.time() % 1000000) * 100 + (a.seq % 100) + 37
	R.ww_err = nil
	R.ww_run = { seed = seed, step = 0, ci = 0, k = 1, phase = "pick", pool = pool, valid = hero_set(), taken = {}, notes = {},
		t = { seq = a.seq, size = MAXT, seed = seed, done = false, ts = os.time(), c = {}, m = {} },
		rep = {}, t0 = os.clock(), wait = 0 }
	mark()
	log("world war: bat dau giai", a.seq, "(3v3)")
	return true
end

function WW.cancel()
	if R.ww_run == nil or R.ww_busy then return false end
	R.ww_run = nil
	log("world war: da huy")
	return true
end

local function fail(run, err)
	local first = string.match(tostring(err), "^[^\r\n]*") or ""
	R.ww_err = string.sub(first, 1, 160)
	R.ww_run = nil
	R.ww_fail = (R.ww_fail or 0) + 1
	log("world war: LOI:", string.sub(tostring(err), 1, 600))
	toast("World War loi: " .. string.sub(first, 1, 90), 8)
end

local function finish(run)
	local a = st()
	local t = run.t
	t.done = true
	if not TN.t_ok(t) then error("giai dau sinh ra du lieu khong hop le", 0) end
	local txt = TN.reps_serialize(t, run.rep)
	if txt == nil then error("thieu replay", 0) end
	if #txt > REP_MAX then
		log("world war: replay qua lon (" .. #txt .. " byte), chi giu trong RAM")
	elseif H.write_first ~= nil then
		local okw, resw = pcall(H.write_first, LS.acct_file(REP_FILE), txt)
		if not okw or not resw then log("world war: khong ghi duoc", LS.acct_file(REP_FILE)) end
	end
	a.t = t
	R.ww_rep, R.ww_rep_seq = run.rep, t.seq
	R.ww_run = nil
	mark()
	LS.save_state(true)
	local champ = t.c[t.m[NM].w]
	log("world war: xong giai", t.seq, "vo dich", champ.name, string.format("(%.1fs)", os.clock() - run.t0))
	toast("World War xong! Vo dich: " .. champ.name .. ". Bam MO LAI MAN de xem.", 10)
end

local function step(run)
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" or type(e.user_ship) ~= "table" then return end
	local a = st()
	local t = run.t
	if run.phase == "pick" then
		run.ci = run.ci + 1
		local c, notes = make_contestant(a, run, run.ci)
		if c == nil then error(notes, 0) end
		t.c[run.ci] = c
		for _, nm in ipairs(notes) do run.notes[#run.notes + 1] = nm end
		run.step = run.ci
		if run.ci >= N then
			run.phase = "play"
			if #run.notes > 0 then
				toast("Tuong khong dung duoc, da doi ngau nhien: " .. table.concat(run.notes, ", "), 8)
			end
		end
		return
	end
	local k = run.k
	local ia, ib = pair_of(t, k)
	-- boc ngau nhien ben nao la "tan cong" (ben trai/phe 0) de khong lech phe
	local flip = (trng(run.seed * 1000 + k * 10 + 3)() < 0.5)
	if flip then ia, ib = ib, ia end
	local ca, cb = t.c[ia], t.c[ib]
	local res, err, fatal
	for attempt = 1, 3 do
		res, err, fatal = TN.play_match(e, ca, cb, run.seed * 1000 + k * 10 + attempt)
		if res ~= nil then break end
		log("world war: tran", k, "that bai lan", attempt, ":", string.sub(tostring(err), 1, 300))
		if fatal then break end
		local to = nil
		if string.find(tostring(err), "LS_watchdog", 1, true) ~= nil then to = 3 end
		for _, c in ipairs({ ca, cb }) do
			for _, tid in ipairs(c.tids) do
				-- ha cap ban tuong (full -> nomega -> safe) giong Tournament
				R.tn_mode = R.tn_mode or {}
				local cur = R.tn_mode[tid] or 1
				local nxt = to or (cur + 1)
				if nxt > 3 then nxt = 3 end
				if nxt > cur then R.tn_mode[tid] = nxt end
			end
		end
	end
	if res == nil then error("tran " .. fint(k) .. ": " .. tostring(err), 0) end
	local file = fint(t.seq * 100 + k)
	run.rep[file] = { init = res.init, b39 = res.b39, win = res.win, total = res.total, nr = res.nr, na = res.na, nb = res.nb }
	t.m[k] = { a = ia, b = ib, w = (res.win == 1) and ia or ib, file = file, nr = res.nr, total = res.total,
		duels = res.duels, stales = res.stales, ots = res.ots, rr = res.rerolls }
	log("world war: tran", k, ca.name, "vs", cb.name, "->", t.c[t.m[k].w].name, res.nr, "round", res.duels, "cap dau",
		string.format("(%.1fs)", os.clock() - run.t0))
	run.k = k + 1
	run.step = N + k
	if run.k > NM then finish(run) end
end

function WW.tick()
	local run = R.ww_run
	if run == nil or R.ww_busy or not R.ready or busy_world() then return end
	run.wait = (run.wait or 0) + 1
	if run.wait < WAIT_FRAMES then return end
	run.wait = 0
	R.ww_busy = true
	local ok, err = xpcall(function() step(run) end, traceback)
	R.ww_busy = false
	if not ok then fail(run, err) end
end

function WW.on_world(e)
	R.ww_run, R.ww_busy = nil, false
end

-- ====================================================== kho replay
local function rep_get(file)
	local a = st()
	local t = a.t
	if t == nil then return nil end
	if R.ww_rep == nil or R.ww_rep_seq ~= t.seq then
		local reps = nil
		if H.read_first ~= nil then
			local okr, txt = pcall(H.read_first, LS.acct_file(REP_FILE))
			if okr then reps = TN.reps_parse(txt, t.seq) end
		end
		R.ww_rep, R.ww_rep_seq = reps or {}, t.seq
	end
	return R.ww_rep[file]
end

-- ====================================================== du lieu tra ve cho client (JSON)
-- (so tran thang, hang) cua thi sinh s: thua vong 1 -> 5; thua ban ket -> 3; thua chung ket -> 2; vo dich -> 1
local function wins_of(t, s)
	local mi = math.floor((s + 1) / 2)
	if t.m[mi].w ~= s then return 0, 5 end
	local ms = (mi <= 2) and 5 or 6
	if t.m[ms].w ~= s then return 1, 3 end
	if t.m[7].w ~= s then return 2, 2 end
	return 3, 1
end

-- ket qua cac tran cua thi sinh s: 10 muc trong, roi 1/0 cho vong 1, ban ket, chung ket (client doc muc 11-13)
local function result_str(t, s)
	local mi = math.floor((s + 1) / 2)
	local f = { (t.m[mi].w == s) and "1" or "0" }
	if t.m[mi].w == s then
		local ms = (mi <= 2) and 5 or 6
		f[2] = (t.m[ms].w == s) and "1" or "0"
		if t.m[ms].w == s then f[3] = (t.m[7].w == s) and "1" or "0" end
	end
	return string.rep("|", 10) .. table.concat(f, "|")
end

local function match_entry(t, k)
	local m = t.m[k]
	local ca, cb = t.c[m.a], t.c[m.b]
	local cnt = math.floor(tn(m.file, 0))
	return {
		battleRes = (m.w == m.a) and 1 or 0,
		baseAttackerUserInfo = jenc(user_info(ca)), baseAttackShip = ship_str(ca), attackSingletonId = sid_of(ca),
		attackUserId = math.floor(ca.uid), attackUserServerNumber = srv_of(ca), attackUserBattleCount = cnt,
		baseByAttackerUserInfo = jenc(user_info(cb)), baseByAttackShip = ship_str(cb), byAttackSingletonId = sid_of(cb),
		byAttackUserId = math.floor(cb.uid), byAttackUserServerNumber = srv_of(cb), byAttackUserBattleCount = cnt,
	}
end

function WW.init_json(e)
	local a = st()
	local now = now_ms(e)
	-- battleStatus 4 (dang thi dau) + time trong 10 phut -> client mo thang bang dau; applyStatus 0 = nguoi choi chi la khan gia
	return jenc({ serverGroup = { 1, 2, 3, 4 }, serverNumber = 1, singletonId = "0", battleStatus = 4, time = now + 600000,
		battleRoundTime = now + 3600000, applyUserCount = a.t and N or 0, applyStatus = 0 })
end

function WW.duel_json()
	local t = st().t
	if t == nil then return jenc({ peakednessDuelInfo = EMPTY_ARR }) end
	-- client tu doi cho muc 3 va 4 (cap thu 3 hien thi o vi tri 3 = muc du lieu 4), nen gui theo thu tu 1,2,4,3,5,6,7
	local list = {}
	for i, k in ipairs({ 1, 2, 4, 3, 5, 6, 7 }) do list[i] = match_entry(t, k) end
	return jenc({ peakednessDuelInfo = list })
end

local function blk(code, json) return tostring(code) .. "\r\n" .. json end

function WW.h_init(p, seq)
	local e = ED()
	if e == nil then return nil end
	return reply(seq, "the_kings_battle_self_init", { blk(14826, WW.init_json(e)) })
end

function WW.h_duel(p, seq)
	if ED() == nil then return nil end
	return reply(seq, "the_kings_battle_self_battle_peakedness_duel_info", { blk(14828, WW.duel_json()) })
end

function WW.h_other(p, seq)
	local name = "the_kings_battle_self_get_other_info"
	local t = st().t
	local uid = tonumber(p[1])
	local s = uid ~= nil and (math.floor(uid) - UID0) or 0
	if t == nil or s < 1 or s > N then return err_reply(seq, name, "LS_khong_co_thi_sinh", ERR.generic) end
	local c = t.c[s]
	return reply(seq, name, { blk(14832, jenc({ formaiton = ship_str(c), battleRes = result_str(t, s) })) })
end

function WW.h_report(p, seq)
	local name = "the_kings_battle_self_get_battle_report"
	local file = fint(tn(p[2], -1))
	local rp = rep_get(file)
	if rp == nil then return err_reply(seq, name, "LS_khong_co_tran_world_war", ERR.generic) end
	return reply(seq, name, { rp.init, rp.b39 })
end

-- bang xep hang diem (so tran thang * 10)
function WW.h_rank(p, seq)
	local name = "the_kings_battle_self_battle_rank"
	if ED() == nil then return nil end
	local t = st().t
	local list = {}
	if t ~= nil then
		for s = 1, N do
			local w, rank = wins_of(t, s)
			list[#list + 1] = { s = s, w = w, rank = rank }
		end
		table.sort(list, function(x, y)
			if x.rank ~= y.rank then return x.rank < y.rank end
			return x.s < y.s
		end)
	end
	local from = math.max(1, math.floor(tn(p[1], 1)))
	local to = math.min(#list, math.floor(tn(p[2], N)))
	local rows = {}
	for i = from, to do
		local c = t.c[list[i].s]
		rows[#rows + 1] = { baseUserInfo = jenc(user_info(c)), serverNumber = srv_of(c), battleScore = list[i].w * 10,
			winCount = list[i].w, byBottomCount = 1, bottomPourScore = 0, bottomPourType = 0, singletonId = sid_of(c) }
	end
	if #rows == 0 then rows = EMPTY_ARR end
	return reply(seq, name, { blk(14831, jenc({ rankInfo = rows, myRank = -1, myRankInfo = -1 })) })
end

-- vong loai khong ton tai trong che do nay: tra ve du lieu rong de client khong phai cho ket noi
function WW.h_match(p, seq)
	return reply(seq, "the_kings_battle_self_match_info", { blk(14829, jenc({ roundStatus = -1 })) })
end

function WW.h_text(p, seq)
	return reply(seq, "the_kings_battle_cross_base_get_battle_report", { blk(14830, "[]") })
end

-- ====================================================== API cho bang chon tuong (OfflineMock)
function LS.ww_info()
	if S == nil then return nil end
	local a = st()
	local run = R.ww_run
	local t = a.t
	local slots = {}
	for i = 1, N do slots[i] = { a.slots[i][1], a.slots[i][2], a.slots[i][3] } end
	local champ = nil
	if t ~= nil then champ = t.c[t.m[NM].w].name end
	return { size = MAXT, slots = slots, running = run ~= nil, step = run and run.step or 0, total = N + NM,
		err = R.ww_err, has = t ~= nil, seq = t and t.seq or 0, champ = champ, ready = R.ready == true }
end

function LS.ww_pool() return LS.tn_pool() end
function LS.ww_name(tid) return TN.hero_name(tid) end

function LS.ww_set_slot(slot, idx, tid)
	if S == nil then return false end
	slot, idx = math.floor(tn(slot, 0)), math.floor(tn(idx, 0))
	if slot < 1 or slot > N or idx < 1 or idx > MAXT then return false end
	tid = math.max(0, math.floor(tn(tid, 0)))
	if tid > 0 and not hero_set()[tid] then return false end
	local a = st()
	a.slots[slot][idx] = tid
	mark()
	return true
end

-- che do nay luon la 3v3: khong doi duoc so tuong moi doi
function LS.ww_set_size(n) return MAXT end

function LS.ww_clear()
	if S == nil then return false end
	local a = st()
	for i = 1, N do for j = 1, MAXT do a.slots[i][j] = 0 end end
	mark()
	return true
end

function LS.ww_random()
	if S == nil then return false end
	local a = st()
	local pool = E.bot_pool()
	if #pool == 0 then pool = LS.hero_ids() end
	if #pool == 0 then return false end
	local r = trng(os.time() + (R.sync_n or 0) + 17)
	local taken = {}
	for i = 1, N do for j = 1, MAXT do if a.slots[i][j] > 0 then taken[a.slots[i][j]] = true end end end
	for i = 1, N do
		for j = 1, MAXT do
			if a.slots[i][j] == 0 then
				for _ = 1, 60 do
					local tid = pool[math.floor(r() * #pool) + 1]
					if tid ~= nil and not taken[tid] then
						taken[tid] = true
						a.slots[i][j] = tid
						break
					end
				end
			end
		end
	end
	mark()
	return true
end

function LS.ww_start() return WW.start() end
function LS.ww_cancel() return WW.cancel() end

function WW.dump_line()
	local a = S ~= nil and S.ww or nil
	if type(a) ~= "table" then return "[LS WorldWar] chua khoi tao" end
	local t = a.t
	return "[LS WorldWar 3v3] giai #" .. tostring(a.seq or 0) .. (TN.t_ok(t) and (" | co ket qua, vo dich " .. t.c[t.m[NM].w].name) or " | chua co ket qua")
		.. (R.ww_run ~= nil and (" | dang tinh buoc " .. tostring(R.ww_run.step)) or "")
		.. (R.ww_err ~= nil and (" | loi cuoi: " .. R.ww_err) or "")
end

LS._ww = WW
end
init_ww()
end

do
local function init_af()

local AF = {}
local PROP_ID = 242
local FLOOR_LOW, FLOOR_TOP = 3000, 99999
local MAX_TIMES = 100
local DEF_COEF = { 30, 16, 150, 0.1, 0.05, 0.2 }
local MROLL = {
	[0] = { -1, 0, 1, 1, 2, 2, 3, 4 },
	[1] = { -1, 0, 1, 2, 2, 3, 4, 5 },
	[2] = { 0, 1, 2, 3, 3, 4, 5, 6 },
}
local NOT_IN_FIGHT = { [43] = true, [46] = true }

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function pairs_of(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)") do out[#out + 1] = { tonumber(a), tonumber(b) } end
	return out
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) }
	end
	return out
end

function AF.T()
	local T = R.af_t
	if T ~= nil then return T end
	T = { ok = false, ids = {}, m = {}, lim = {}, coef = DEF_COEF }
	R.af_t = T
	local mt, pt = dtab("artifact_mould"), dtab("artifact_param")
	if mt == nil or pt == nil then return T end
	local C = { id = schema("artifact_mould", "id", 1), ach = schema("artifact_mould", "achieve_id", 4), c1 = schema("artifact_mould", "primary_consume", 5),
		c2 = schema("artifact_mould", "intermediate_consume", 6), c3 = schema("artifact_mould", "advanced_consume", 7),
		up = schema("artifact_mould", "upper_limit_library", 8), rd = schema("artifact_mould", "random_library", 9) }
	for k, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local id = tonumber(r[C.id]) or tonumber(k)
			if id ~= nil then
				id = math.floor(id)
				local up, rd = pairs_of(r[C.up]), pairs_of(r[C.rd])
				if #up > 0 then
					local ug, rg = {}, {}
					for _, v in ipairs(up) do ug[v[1]] = v[2] end
					for _, v in ipairs(rd) do rg[v[1]] = v[2] end
					local keys = {}
					for key in pairs(ug) do keys[#keys + 1] = key end
					table.sort(keys)
					T.m[id] = { id = id, keys = keys, ug = ug, rg = rg, free = (tostring(r[C.ach] or "") == "-1"),
						cost = { triples(r[C.c1]), triples(r[C.c2]), triples(r[C.c3]) } }
				end
			end
		end
	end
	for id in pairs(T.m) do T.ids[#T.ids + 1] = id end
	table.sort(T.ids)

	local P = { grp = schema("artifact_param", "group_id", 2), lv = schema("artifact_param", "user_level", 3), lim = schema("artifact_param", "property_limit", 4) }
	for _, row in pairs(pt) do
		local r = cells(row)
		if r ~= nil then
			local g, lv, lim = tonumber(r[P.grp]), tonumber(r[P.lv]), tonumber(r[P.lim])
			if g ~= nil and lv ~= nil and lim ~= nil then
				g, lv = math.floor(g), math.floor(lv)
				local a = T.lim[g]
				if a == nil then a = { min = lv, max = lv, v = {} }; T.lim[g] = a end
				a.v[lv] = lim
				if lv < a.min then a.min = lv end
				if lv > a.max then a.max = lv end
			end
		end
	end

	local pc = dtab("play_config")
	if pc ~= nil then
		local r = cells(pc[77])
		local s = r ~= nil and r[schema("play_config", "param", 4)] or nil
		local co = {}
		for w in string.gmatch(tostring(s or ""), "[^,]+") do
			local x = tonumber(w)
			if x == nil or x <= 0 then co = {}; break end
			co[#co + 1] = x
		end
		if #co >= 6 then T.coef = co end
	end
	T.ok = #T.ids > 0 and next(T.lim) ~= nil
	return T
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.af_auto == false) end
local function stats_on() return not (type(S.cfg) == "table" and (S.cfg.af_stats == false)) end

local function grade()
	local e = ED()
	local g = (e ~= nil and type(e.user_info) == "table") and tonumber(e.user_info.user_grade) or nil
	return math.floor(g or 1)
end

function AF.cap(id, key)
	local T = AF.T()
	local m = T.m[id]
	if m == nil then return nil end
	local g = m.ug[key]
	local l = g ~= nil and T.lim[g] or nil
	if l == nil then return nil end
	local lv = math.max(l.min, math.min(l.max, grade()))
	local v = l.v[lv]
	while v == nil and lv > l.min do lv = lv - 1; v = l.v[lv] end
	return v
end

local function r2(x) return tonumber(string.format("%.2f", x)) end

local function fmt(v)
	v = tonumber(v) or 0
	if v == math.floor(v) then return string.format("%d", v) end
	local s = string.format("%.2f", v)
	s = string.gsub(s, "0+$", "")
	s = string.gsub(s, "%.$", "")
	return s
end

local function st()
	local a = S.af
	if type(a) ~= "table" then a = { v = 0 }; S.af = a end
	if type(a.u) ~= "table" then a.u = {} end
	if type(a.val) ~= "table" then a.val = {} end
	return a
end

-- [FIX] GM FULL THAN KHI: mo khoa toan bo + day moi chi so len gioi han
function AF.full_on()
	return type(S) == "table" and type(S.cfg) == "table" and S.cfg.af_full == true
end

-- [FIX FULL Than khi] -----------------------------------------------------------------------
-- Ban cu: gm_full chi ghi a.u/a.val dung 1 lan va KHONG dat a.v = 1 => lan dau mo man hinh
-- Than khi, AF.ensure() thay a.v ~= 1 va XOA mo khoa (chi con than khi mien phi); AF.totals()
-- cung bo qua khi a.v ~= 1 nen chua mo man hinh thi khong co chi so. Gioi han chi so lai tang
-- theo cap nguoi choi nhung gia tri khong duoc nang theo, va TAT FULL khong tra ve gi.
-- Nay: bat FULL = chup trang thai tu nang (a.manual), mo het + dat moi chi so bang gioi han
-- hien tai (AF.tick theo doi cap nguoi choi nen luon giu full), TAT FULL = khoi phuc.
local function af_copy_rows(src)
	local out = {}
	for k, row in pairs(src) do
		if type(row) == "table" then
			local r = {}
			for kk, vv in pairs(row) do r[kk] = vv end
			out[k] = r
		end
	end
	return out
end

local function af_make_full(a)
	local T = AF.T()
	if not T.ok then return false end
	local changed = false
	if not a.full then
		local u = {}
		for k, v in pairs(a.u) do u[k] = v end
		a.manual, a.full = { u = u, val = af_copy_rows(a.val) }, true
		changed = true
	end
	for _, id in ipairs(T.ids) do
		local k = tostring(id)
		if a.u[k] ~= 1 then a.u[k] = 1; changed = true end
		local row = a.val[k]
		if type(row) ~= "table" then row = {}; a.val[k] = row; changed = true end
		for _, key in ipairs(T.m[id].keys) do
			local cap = AF.cap(id, key)
			local want = (cap ~= nil and cap > 0) and r2(cap) or 0
			local ks = tostring(key)
			local cur = tonumber(row[ks])
			if cur == nil or math.abs(cur - want) > 1e-6 then row[ks] = want; changed = true end
		end
	end
	return changed
end

local function af_unfull(a)
	if not a.full then return false end
	local m = a.manual
	a.u, a.val = {}, {}
	if type(m) == "table" then
		if type(m.u) == "table" then for k, v in pairs(m.u) do a.u[k] = v end end
		if type(m.val) == "table" then a.val = af_copy_rows(m.val) end
	end
	a.manual, a.full = nil, nil
	R.af_clean = nil
	R.af_last = "tat full than khi: tra ve tien trinh tu nang"
	mark()
	return true
end

function AF.gm_reset()
	S.af = nil
	R.af_t, R.af_clean, R.af_pend = nil, nil, nil
	R.af_sig, R.af_now = nil, nil
	R.af_last = "GM tat full than khi"
	mark()
	return true
end

function AF.tick(e)
	if S == nil or not R.ready or type(e) ~= "table" or type(e.user_info) ~= "table" then return end
	local on = AF.full_on()
	local a = S.af
	if not on and not (type(a) == "table" and a.full) then
		R.af_sig = nil
		return
	end
	if not AF.T().ok then return end
	local sig = (on and "1:" or "0:") .. grade()
	if sig == R.af_sig and not R.af_now then return end
	R.af_sig, R.af_now = sig, nil
	local changed
	if on then
		a = AF.ensure()
		if a == nil then return end
		changed = af_make_full(a)
	else
		changed = af_unfull(st())
	end
	if changed then
		R.stat_dirty = true
		if on then R.af_last = "full than khi (gioi han theo cap " .. fint(grade()) .. ")" end
		mark()
		if stats_on() and LS._tl ~= nil and LS._tl.queue_all ~= nil then
			pcall(LS._tl.queue_all, e)
			R.tl_sig_l, R.tl_sig_f = nil, nil
		end
	end
end

function AF.apply_now(e)
	R.af_sig, R.af_now = nil, true
	if e ~= nil then
		local ok, err = pcall(AF.tick, e)
		if not ok then log("loi GM full than khi:", tostring(err)) end
	end
end

function AF.ensure()
	local T = AF.T()
	if not T.ok then return nil end
	local a = st()
	if a.v ~= 1 then
		a.v = 1
		a.u = {}
		for _, id in ipairs(T.ids) do
			if T.m[id].free then a.u[tostring(id)] = 1 end
		end
		mark()
	end
	if not R.af_clean then
		R.af_clean = true

		for k in pairs(a.u) do
			local id = tonumber(k)
			if id == nil or T.m[math.floor(id)] == nil or a.u[k] ~= 1 then a.u[k] = nil end
		end
		for k, row in pairs(a.val) do
			local id = tonumber(k)
			if id == nil or T.m[math.floor(id)] == nil or type(row) ~= "table" then
				a.val[k] = nil
			else
				local m = T.m[math.floor(id)]
				for kk, v in pairs(row) do
					local key = tonumber(kk)
					local x = tonumber(v)
					if key == nil or m.ug[math.floor(key)] == nil or x == nil or x ~= x then
						row[kk] = nil
					else
						local cap = AF.cap(m.id, math.floor(key))
						if x < 0 then x = 0 end
						if cap ~= nil and x > cap then x = cap end
						row[kk] = r2(x)
					end
				end
			end
		end
	end
	return a
end

local function value(id, key)
	local row = st().val[tostring(id)]
	if type(row) ~= "table" then return 0 end
	return tonumber(row[tostring(key)]) or 0
end

local function unlocked(id) return st().u[tostring(id)] == 1 end

function AF.totals()
	local T = AF.T()
	local tot = {}
	local a = S ~= nil and S.af or nil
	if type(a) ~= "table" or a.v ~= 1 then return tot end
	for _, id in ipairs(T.ids) do
		if unlocked(id) then
			for _, key in ipairs(T.m[id].keys) do
				local v = value(id, key)
				if v ~= 0 then tot[key] = (tot[key] or 0) + v end
			end
		end
	end
	return tot
end

function AF.active()
	if not stats_on() then return false end
	return next(AF.totals()) ~= nil
end

function AF.adjust(sid, tid, pn, spec, is_rec)
	if not stats_on() or type(pn) ~= "table" then return end
	local ok, err = pcall(function()
		local tot = AF.totals()
		if next(tot) == nil then return end
		for i = 1, 3 do
			local x = pn[i]
			if type(x) == "number" then
				local flat, pct = tot[i - 1] or 0, tot[i + 3] or 0
				if flat ~= 0 or pct ~= 0 then pn[i] = math.max(0, rnd(x + flat + x * pct / 100)) end
			end
		end
		if type(spec) == "table" then
			for key, v in pairs(tot) do
				if key >= 7 and not NOT_IN_FIGHT[key] then spec[key] = (spec[key] or 0) + v end
			end
		end
	end)
	if not ok then
		R.af_errs = (R.af_errs or 0) + 1
		if R.af_errs <= 5 then log("loi chi so than khi:", tostring(err)) end
	end
end

function AF.blk_info()
	local T = AF.T()
	local lock, attrs = {}, {}
	for _, id in ipairs(T.ids) do
		lock[#lock + 1] = string.format("%d:%d", id, unlocked(id) and 1 or 0)
		local row = {}
		for _, key in ipairs(T.m[id].keys) do row[#row + 1] = string.format("%d:%s", key, fmt(value(id, key))) end
		attrs[#attrs + 1] = string.format("%d=%s", id, table.concat(row, ","))
	end
	return "12563\r\n" .. table.concat(lock, "|") .. "\r\n" .. table.concat(attrs, "|")
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if AF.ensure() == nil then error("khong co bang than khi") end
	return e
end

local function floor_props()
	if auto_on() and LS.prop_get(PROP_ID) < FLOOR_LOW then
		LS.prop_set(PROP_ID, FLOOR_TOP)
		mark()
	end
end

local function finish(e, seq, name, extra)
	local blocks = { AF.blk_info() }
	for _, b in ipairs(extra or {}) do blocks[#blocks + 1] = b end
	if stats_on() and LS._tl ~= nil and LS._tl.refresh_blocks ~= nil then
		LS._tl.refresh_blocks(e, blocks)
		LS._tl.queue_all(e)
		R.tl_sig_l, R.tl_sig_f = nil, nil
	end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function AF.h_init(p, seq)
	local e = ctx()
	floor_props()
	R.af_pend = nil
	stat_inc("af_init")
	return reply(seq, "artifact_init", { AF.blk_info() })
end

function AF.h_unlock(p, seq)
	local e = ctx()
	local id = math.floor(tn(p[1], -1))
	local T = AF.T()
	if T.m[id] == nil then return err_reply(seq, "artifact_unlock", "LS_than_khi_khong_ton_tai", ERR.generic) end
	st().u[tostring(id)] = 1
	R.af_last = "mo khoa than khi " .. fint(id)
	stat_inc("af_unlock")
	return finish(e, seq, "artifact_unlock")
end

function AF.h_culture(p, seq)
	local e = ctx()
	floor_props()
	local T = AF.T()
	local id = math.floor(tn(p[1], -1))
	local mode = math.floor(tn(p[2], 0))
	local times = math.floor(tn(p[3], 1))
	local m = T.m[id]
	if m == nil then return err_reply(seq, "artifact_culture", "LS_than_khi_khong_ton_tai", ERR.generic) end
	if not unlocked(id) then return err_reply(seq, "artifact_culture", "LS_than_khi_chua_mo", ERR.generic) end
	if mode < 0 or mode > 2 then return err_reply(seq, "artifact_culture", "LS_kieu_luyen_khong_hop_le", ERR.generic) end
	if times < 1 or times > MAX_TIMES then return err_reply(seq, "artifact_culture", "LS_so_luot_khong_hop_le", ERR.generic) end

	local need_prop, need_silver = 0, 0
	for _, c in ipairs(m.cost[mode + 1] or {}) do
		if c[1] == 6 and c[2] == PROP_ID then need_prop = need_prop + c[3] * times
		elseif c[1] == 1 then need_silver = need_silver + c[3] * times end
	end
	if need_prop > 0 and LS.prop_get(PROP_ID) < need_prop then return err_reply(seq, "artifact_culture", "LS_khong_du_cuon_than_khi", ERR.items) end
	if need_silver > 0 and (S.silver or 0) < need_silver then return err_reply(seq, "artifact_culture", "LS_khong_du_bac", ERR.silver) end
	if need_prop > 0 then LS.prop_add(PROP_ID, -need_prop) end
	if need_silver > 0 then LS.money_spend("silver", need_silver) end

	local rolls, rtxt = {}, {}
	local pool = MROLL[mode]
	for i = 1, times do
		local one, ot = {}, {}
		for _, key in ipairs(m.keys) do
			local g = m.rg[key] or m.ug[key]
			local coef = T.coef[g] or T.coef[m.ug[key]] or 1
			local mm = pool[math.random(1, #pool)]
			local v = r2(mm * coef)
			one[#one + 1] = { key, v }
			ot[#ot + 1] = string.format("%d:%s", key, fmt(v))
		end
		rolls[i] = one
		rtxt[i] = table.concat(ot, ",")
	end
	R.af_pend = { id = id, rolls = rolls }
	R.af_last = "luyen than khi " .. fint(id) .. " x" .. fint(times)
	stat_inc("af_culture", times)
	mark()
	return reply(seq, "artifact_culture", { "12564\r\n" .. fint(id) .. "=" .. table.concat(rtxt, "|") })
end

function AF.h_confirm(p, seq)
	local e = ctx()
	local T = AF.T()
	local id = math.floor(tn(p[1], -1))
	local flag = math.floor(tn(p[2], 0))
	local m = T.m[id]
	if m == nil then return err_reply(seq, "artifact_confirm", "LS_than_khi_khong_ton_tai", ERR.generic) end
	local pend = R.af_pend
	if flag < 0 then
		R.af_pend = nil
		stat_inc("af_cancel")
		return finish(e, seq, "artifact_confirm")
	end
	if pend == nil or pend.id ~= id then return err_reply(seq, "artifact_confirm", "LS_khong_co_luot_luyen", ERR.generic) end
	local pick = {}
	for w in string.gmatch(tostring(p[3] or ""), "%d+") do
		local i = tonumber(w)
		if pend.rolls[i] ~= nil and not pick[i] then pick[i] = true end
	end
	if next(pick) == nil then return err_reply(seq, "artifact_confirm", "LS_chua_chon_luot", ERR.generic) end
	local sum = {}
	for i in pairs(pick) do
		for _, kv in ipairs(pend.rolls[i]) do sum[kv[1]] = (sum[kv[1]] or 0) + kv[2] end
	end
	local a = st()
	local row = a.val[tostring(id)]
	if type(row) ~= "table" then row = {}; a.val[tostring(id)] = row end
	for _, key in ipairs(m.keys) do
		local cur = tonumber(row[tostring(key)]) or 0
		local nv = cur + (sum[key] or 0)
		local cap = AF.cap(id, key)
		if nv < 0 then nv = 0 end
		if cap ~= nil and nv > cap then nv = cap end
		row[tostring(key)] = r2(nv)
	end
	-- [FIX FULL Than khi] dang FULL thi ket qua luyen (ke ca so am) khong duoc keo chi so xuong duoi gioi han
	if AF.full_on() then af_make_full(a) end
	R.af_pend = nil
	R.af_last = "luu than khi " .. fint(id)
	stat_inc("af_save")
	return finish(e, seq, "artifact_confirm")
end

function AF.dump_line()
	local a = S ~= nil and S.af or nil
	if type(a) ~= "table" or a.v ~= 1 then return "[LS than khi] chua khoi tao" end
	local T = AF.T()
	local n, sum = 0, 0
	for _, id in ipairs(T.ids) do
		if unlocked(id) then
			n = n + 1
			for _, key in ipairs(T.m[id].keys) do sum = sum + (value(id, key) ~= 0 and 1 or 0) end
		end
	end
	return "[LS than khi] mo " .. n .. "/" .. #T.ids .. " | chi so khac 0: " .. sum .. " | Cuon " .. fnum(LS.prop_get(PROP_ID))
		.. " | full " .. (AF.full_on() and "BAT" or "TAT")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.af_last ~= nil and (" | cuoi: " .. R.af_last) or "")
end

function AF.reset()
	S.af = nil
	R.af_clean = nil
	R.af_pend = nil
	R.af_sig, R.af_now = nil, nil
	mark()
end

function AF.on_world(e)
	R.af_t, R.af_clean, R.af_pend = nil, nil, nil
	R.af_sig, R.af_now = nil, nil
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if AF.active() then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._af = AF

end
init_af()
end

do
local function init_sp()

local SP = {}
local FLOOR_LOW, FLOOR_TOP = 5000, 99999
local NOT_IN_FIGHT = { [43] = true, [46] = true }

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function plist(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do out[#out + 1] = { tonumber(a), tonumber(b) } end
	return out
end

function SP.T()
	local T = R.sp_t
	if T ~= nil then return T end
	T = { ok = false, grp = {}, gids = {}, par = {}, nlv = {}, mx = {}, maxs = 0, limit = 600 }
	R.sp_t = T
	local gt, mt, pt = dtab("ship_spirit_group"), dtab("ship_spirit_mould"), dtab("ship_spirit_param")
	if gt == nil or mt == nil or pt == nil then return T end
	local GC = { id = schema("ship_spirit_group", "id", 1), need = schema("ship_spirit_group", "ship_need_id", 4),
		props = schema("ship_spirit_group", "need_props", 5), attr = schema("ship_spirit_group", "ship_attribute_group", 6) }
	for k, row in pairs(gt) do
		local r = cells(row)
		if r ~= nil then
			local id = tonumber(r[GC.id]) or tonumber(k)
			if id ~= nil then
				id = math.floor(id)
				local need, attr, props = {}, {}, {}
				for w in string.gmatch(tostring(r[GC.need] or ""), "%-?%d+") do need[#need + 1] = tonumber(w) end
				for w in string.gmatch(tostring(r[GC.attr] or ""), "%-?%d+") do attr[#attr + 1] = tonumber(w) end
				for p in string.gmatch(tostring(r[GC.props] or ""), "[^|]+") do
					local a = {}
					for w in string.gmatch(p, "%-?%d+") do a[#a + 1] = tonumber(w) end
					if a[2] ~= nil then props[#props + 1] = { id = a[2], n = math.max(1, a[3] or 1), exp = a[4] or 0 } end
				end
				T.grp[id] = { id = id, need = need, attr = attr, props = props }
			end
		end
	end
	for id in pairs(T.grp) do T.gids[#T.gids + 1] = id end
	table.sort(T.gids)
	local PC = { lv = schema("ship_spirit_param", "level", 2), exp = schema("ship_spirit_param", "next_exp", 3), st = schema("ship_spirit_param", "stalls", 4) }
	for _, row in pairs(pt) do
		local r = cells(row)
		if r ~= nil then
			local lv, ex, st = tonumber(r[PC.lv]), tonumber(r[PC.exp]), tonumber(r[PC.st])
			if lv ~= nil and ex ~= nil and st ~= nil then
				lv, st = math.floor(lv), math.floor(st)
				local a = T.par[st]
				if a == nil then a = {}; T.par[st] = a end
				a[lv] = ex
				if lv > (T.nlv[st] or 0) then T.nlv[st] = lv end
				if st > T.maxs then T.maxs = st end
			end
		end
	end
	local MC = { gid = schema("ship_spirit_mould", "group_id", 2), st = schema("ship_spirit_mould", "belong_stalls", 3),
		lv = schema("ship_spirit_mould", "belongs_grade", 4), add = schema("ship_spirit_mould", "addition", 5), sp = schema("ship_spirit_mould", "speed_add", 6) }
	for _, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local g, st, lv = tonumber(r[MC.gid]), tonumber(r[MC.st]), tonumber(r[MC.lv])
			if g ~= nil and st ~= nil and lv ~= nil then
				g, st, lv = math.floor(g), math.floor(st), math.floor(lv)
				local a = T.mx[g]
				if a == nil then a = {}; T.mx[g] = a end
				local b = a[st]
				if b == nil then b = {}; a[st] = b end
				b[lv] = { add = plist(r[MC.add]), sp = tonumber(r[MC.sp]) or 0 }
			end
		end
	end
	local cf = dtab("ship_config")
	if cf ~= nil then
		local r = cells(cf[48])
		local v = r ~= nil and tonumber(r[schema("ship_config", "param", 4)]) or nil
		if v ~= nil and v >= 1 then T.limit = math.floor(v) end
	end
	T.ok = #T.gids > 0 and T.maxs > 0 and next(T.mx) ~= nil
	return T
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.sp_auto == false) end
local function stats_on() return not (type(S.cfg) == "table" and S.cfg.sp_stats == false) end

-- [FIX FULL Party] bac + cap toi da THAT SU cua bang du lieu (cung cong thuc voi at_max)
local function max_vals()
	local T = SP.T()
	if T == nil or not T.ok then return nil end
	local s = math.max(1, math.floor(tonumber(T.maxs) or 1))
	local l = math.floor(tonumber(T.nlv[s]) or 1)
	local lim = math.floor(tonumber(T.limit) or l)
	if lim >= 1 and lim < l then l = lim end
	return s, math.max(1, l)
end

local function st()
	local a = S.wp
	if type(a) ~= "table" then a = { v = 1 }; S.wp = a end
	if type(a.h) ~= "table" then a.h = {} end
	return a
end

local function fix(h)
	local T = SP.T()
	local s = math.floor(tn(h.s, 1))
	if s < 1 then s = 1 end
	if s > T.maxs then s = T.maxs end
	local nl = T.nlv[s] or 1
	local l = math.floor(tn(h.l, 1))
	if l < 1 then l = 1 end
	if l > nl then l = nl end
	local e = math.floor(tn(h.e, 0))
	if e < 0 then e = 0 end
	local need = (T.par[s] and T.par[s][l]) or 0
	if need > 0 and e >= need then e = need - 1 end
	h.s, h.l, h.e = s, l, e
	return h
end

function SP.get(sid, create)
	local a = st()
	local k = tostring(sid)
	local h = a.h[k]
	if type(h) ~= "table" then
		if not create then return nil end
		h = { l = 1, e = 0, s = 1 }
		-- [FIX FULL Party] FULL dang bat: tuong moi mo giao dien cung la max ngay (khong cho tick)
		if SP.full_on() then
			local ms, ml = max_vals()
			if ms ~= nil then h.s, h.l = ms, ml end
		end
		a.h[k] = h
	end
	return fix(h)
end

function SP.clean()
	local a = st()
	for k, h in pairs(a.h) do
		if type(h) ~= "table" or tonumber(k) == nil then a.h[k] = nil else fix(h) end
	end
end

function SP.attr_group(tid, tid2)
	local T = SP.T()
	for _, gid in ipairs(T.gids) do
		local g = T.grp[gid]
		for i, n in ipairs(g.need) do
			if n > 0 and (n == tid or n == tid2) then return gid, g.attr[i] or -1, g end
		end
	end
	return nil
end

local function ship_of(e, sid)
	if type(e.user_ship) ~= "table" then return nil end
	local sh = e.user_ship[tostring(sid)]
	if type(sh) ~= "table" then return nil end
	return sh
end

local function mrow(g, h)
	local T = SP.T()
	local a = T.mx[g]
	local b = a ~= nil and a[h.s] or nil
	return b ~= nil and b[h.l] or nil
end

function SP.bonus(sid, tid, tid2)
	local h = SP.get(sid, false)
	if h == nil then return nil end
	local _, ag = SP.attr_group(tid, tid2)
	if ag == nil or ag <= 0 then return nil end
	return mrow(ag, h)
end

function SP.speed(sid, tid)
	if not stats_on() then return 0 end
	local e = ED()
	local sh = e ~= nil and ship_of(e, sid) or nil
	local t2 = sh ~= nil and tonumber(sh.ship_base_template_id) or nil
	local ok, b = pcall(SP.bonus, sid, tonumber(tid) or (sh ~= nil and tonumber(sh.ship_template_id)) or -1, t2)
	if not ok or b == nil then return 0 end
	return math.floor(b.sp or 0)
end

function SP.any(sid)
	if not stats_on() then return false end
	local a = S ~= nil and S.wp or nil
	if type(a) ~= "table" or type(a.h) ~= "table" then return false end
	local h = a.h[tostring(sid)]
	if type(h) ~= "table" then return false end
	return (tonumber(h.s) or 1) > 1 or (tonumber(h.l) or 1) > 1
end

function SP.adjust(sid, tid, pn, spec, is_rec)
	if not stats_on() or type(pn) ~= "table" then return end
	if not SP.any(sid) then return end
	local ok, err = pcall(function()
		local e = ED()
		local sh = e ~= nil and ship_of(e, sid) or nil
		local t2 = sh ~= nil and tonumber(sh.ship_base_template_id) or nil
		local b = SP.bonus(sid, tonumber(tid) or -1, t2)
		if b == nil then return end
		local flat = {}
		for _, kv in ipairs(b.add) do
			local key, v = kv[1], kv[2]
			if v ~= 0 then
				if key >= 0 and key <= 2 then flat[key] = (flat[key] or 0) + v
				elseif key >= 7 and not NOT_IN_FIGHT[key] and type(spec) == "table" then spec[key] = (spec[key] or 0) + v end
			end
		end
		for i = 1, 3 do
			local x = pn[i]
			if type(x) == "number" and flat[i - 1] ~= nil then pn[i] = math.max(0, rnd(x + flat[i - 1])) end
		end
	end)
	if not ok then
		R.sp_errs = (R.sp_errs or 0) + 1
		if R.sp_errs <= 5 then log("loi chi so Warrior Party:", tostring(err)) end
	end
end

-- [FIX] GM FULL WARRIOR PARTY (spirit): moi tuong max sao + max cap
function SP.full_on()
	return type(S) == "table" and type(S.cfg) == "table" and S.cfg.sp_full == true
end

-- [FIX FULL Party] Ban cu: gm_full chi dat max cho nhung tuong DA CO ban ghi trong S.wp.h
-- (tuong chua tung mo man hinh Party khong co ban ghi => FULL khong lam gi), khong giu lai khi
-- co tuong moi va TAT FULL cung khong tra ve. Nay: SP.tick (xem sau plain_hero) tao ban ghi max cho
-- MOI tuong thuoc nhom Party, giu khi co tuong moi, va TAT FULL thi khoi phuc ban chup luc bat.

local function add_exp(h, gain)
	local T = SP.T()
	local used = 0
	while gain > 0 do
		local nl = T.nlv[h.s] or 1
		local need = (T.par[h.s] and T.par[h.s][h.l]) or 0
		if need <= 0 then break end
		local at_cap = (h.s >= T.maxs) and (h.l >= math.min(nl, T.limit))
		if at_cap then break end
		local room = need - h.e
		if gain >= room then
			gain = gain - room
			used = used + room
			h.e = 0
			if h.l >= nl then
				h.s = h.s + 1
				h.l = 1
			else
				h.l = h.l + 1
			end
		else
			h.e = h.e + gain
			used = used + gain
			gain = 0
		end
	end
	return used
end

local function at_max(h)
	local T = SP.T()
	return h.s >= T.maxs and h.l >= math.min(T.nlv[h.s] or 1, T.limit)
end

function SP.blk_state(sid)
	local h = SP.get(sid, true)
	return string.format("12560\r\n%s:%d,%d,%d", tostring(sid), h.l, h.e, h.s)
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if not SP.T().ok then error("khong co bang Warrior Party") end
	local a = st()
	if not R.sp_clean then R.sp_clean = true; SP.clean() end
	return e
end

local function floor_props(g)
	if not auto_on() or g == nil then return end
	for _, p in ipairs(g.props) do
		if LS.prop_get(p.id) < FLOOR_LOW then LS.prop_set(p.id, FLOOR_TOP) end
	end
end

local function plain_hero(ship)
	local ct = tonumber(ship.captain_type)
	return ct == nil or (ct ~= 0 and ct ~= 2 and ct ~= 3)
end

-- [FIX FULL Party] ---------------------------------------------------------------------------
-- FULL = MOI tuong thuoc mot nhom Party (ship_spirit_group) deu o bac + cap toi da, ke ca tuong
-- chua tung mo man hinh Party va tuong nhan them sau do. Luc bat chup lai trang thai tu nang
-- (a.manual) de TAT FULL tra ve dung nhu cu.
local function sp_setmax(a, k, ms, ml)
	local h = a.h[k]
	if type(h) ~= "table" then
		a.h[k] = { s = ms, l = ml, e = 0 }
		return true
	end
	if h.s ~= ms or h.l ~= ml or (tonumber(h.e) or 0) ~= 0 then
		h.s, h.l, h.e = ms, ml, 0
		return true
	end
	return false
end

local function sp_make_full(a, e)
	local ms, ml = max_vals()
	if ms == nil then return false end
	local changed = false
	if not a.full then
		local m = {}
		for k, h in pairs(a.h) do
			if type(h) == "table" and tonumber(k) ~= nil then m[k] = { l = h.l, e = h.e, s = h.s } end
		end
		a.manual, a.full = m, true
		changed = true
	end
	for k in pairs(a.h) do
		if tonumber(k) ~= nil and sp_setmax(a, k, ms, ml) then changed = true end
	end
	if type(e) == "table" and type(e.user_ship) == "table" then
		for sid, ship in pairs(e.user_ship) do
			if type(ship) == "table" and tonumber(sid) ~= nil and plain_hero(ship) then
				local k = tostring(sid)
				if a.h[k] == nil then
					local gid = SP.attr_group(tonumber(ship.ship_template_id) or -1, tonumber(ship.ship_base_template_id))
					if gid ~= nil and sp_setmax(a, k, ms, ml) then changed = true end
				end
			end
		end
	end
	return changed
end

local function sp_unfull(a)
	if not a.full then return false end
	local m, n = a.manual, 0
	a.h = {}
	if type(m) == "table" then
		for k, x in pairs(m) do
			if type(x) == "table" and tonumber(k) ~= nil then
				a.h[k] = { l = math.max(1, math.floor(tn(x.l, 1))), e = math.max(0, math.floor(tn(x.e, 0))), s = math.max(1, math.floor(tn(x.s, 1))) }
				n = n + 1
			end
		end
	end
	a.manual, a.full = nil, nil
	R.sp_last = "tat full: tra Party ve tien trinh tu nang (" .. n .. " tuong)"
	mark()
	return true
end

function SP.tick(e)
	if S == nil or not R.ready or type(e) ~= "table" or type(e.user_ship) ~= "table" then return end
	-- dang cap/nap hang loat tuong: cho xong roi moi tinh 1 lan (tranh tinh lai moi frame)
	if R.inject ~= nil or R.grant ~= nil then return end
	local on = SP.full_on()
	local a = S.wp
	if not on and not (type(a) == "table" and a.full) then
		R.sp_sig = nil
		return
	end
	if not SP.T().ok then return end
	local n, sum = 0, 0
	for sid in pairs(e.user_ship) do
		n = n + 1
		sum = sum + (tonumber(sid) or 0)
	end
	local sig = (on and "1:" or "0:") .. n .. ":" .. sum
	if sig == R.sp_sig and not R.sp_now then return end
	R.sp_sig, R.sp_now = sig, nil
	a = st()
	local changed
	if on then changed = sp_make_full(a, e) else changed = sp_unfull(a) end
	if changed then
		R.stat_dirty = true
		mark()
		if LS._tl ~= nil and LS._tl.queue_all ~= nil then
			pcall(LS._tl.queue_all, e)
			R.tl_sig_l, R.tl_sig_f = nil, nil
		end
	end
end

function SP.apply_now(e)
	R.sp_sig, R.sp_now = nil, true
	if e ~= nil then
		local ok, err = pcall(SP.tick, e)
		if not ok then log("loi GM full warrior party:", tostring(err)) end
	end
end

local function refresh_blocks(e, sid, blocks)
	local key = tostring(sid)
	local ship = ship_of(e, key)
	if ship == nil or not plain_hero(ship) then return end
	local ok, err = pcall(function()
		local F = commit_hero(e, key, {})
		if F ~= nil then
			apply_hero(e, key)
			push_all(blocks, blk_ship(ship, F))
			push_all(blocks, blk_fight(e, key, F))
		end
	end)
	if not ok then
		R.sp_errs = (R.sp_errs or 0) + 1
		if R.sp_errs <= 5 then log("loi tinh lai tuong (Warrior Party):", tostring(err)) end
	end
end

local function finish(e, seq, name, sid)
	local blocks = { SP.blk_state(sid) }
	refresh_blocks(e, sid, blocks)
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function SP.h_init(p, seq)
	local e = ctx()
	local sid = tostring(p[1] or "")
	local ship = ship_of(e, sid)
	if ship == nil then return err_reply(seq, "ship_spirit_init", "LS_khong_co_tuong", ERR.generic) end
	local gid, _, g = SP.attr_group(tonumber(ship.ship_template_id) or -1, tonumber(ship.ship_base_template_id))
	if g ~= nil then floor_props(g) end
	stat_inc("sp_init")
	return reply(seq, "ship_spirit_init", { SP.blk_state(sid) })
end

local function common(seq, name, p)
	local e = ctx()
	local gid = math.floor(tn(p[1], -1))
	local sid = tostring(p[2] or "")
	local T = SP.T()
	local g = T.grp[gid]
	if g == nil then return nil, err_reply(seq, name, "LS_nhom_khong_ton_tai", ERR.generic) end
	local ship = ship_of(e, sid)
	if ship == nil then return nil, err_reply(seq, name, "LS_khong_co_tuong", ERR.generic) end
	local tid, t2 = tonumber(ship.ship_template_id) or -1, tonumber(ship.ship_base_template_id)
	local inside = false
	for _, n in ipairs(g.need) do if n > 0 and (n == tid or n == t2) then inside = true end end
	if not inside then return nil, err_reply(seq, name, "LS_tuong_khong_thuoc_nhom", ERR.generic) end
	floor_props(g)
	local h = SP.get(sid, true)
	if at_max(h) then return nil, err_reply(seq, name, "LS_hao_cam_da_toi_da", ERR.rank_max) end
	return { e = e, sid = sid, g = g, h = h }
end

function SP.h_level(p, seq)
	local c, er = common(seq, "ship_spirit_level_up", p)
	if c == nil then return er end
	local t = math.floor(tn(p[3], -1))
	local gp = c.g.props[t + 1]
	if gp == nil then return err_reply(seq, "ship_spirit_level_up", "LS_loai_qua_khong_hop_le", ERR.generic) end
	if LS.prop_get(gp.id) < gp.n then return err_reply(seq, "ship_spirit_level_up", "LS_khong_du_qua", ERR.items) end
	LS.prop_add(gp.id, -gp.n)
	add_exp(c.h, gp.exp)
	R.sp_last = "tang qua cho tuong " .. c.sid
	stat_inc("sp_gift")
	return finish(c.e, seq, "ship_spirit_level_up", c.sid)
end

function SP.h_batch(p, seq)
	local c, er = common(seq, "ship_spirit_batch_level_up", p)
	if c == nil then return er end
	local nums = {}
	for w in string.gmatch(tostring(p[3] or ""), "%-?%d+") do nums[#nums + 1] = math.floor(tonumber(w)) end
	local total = 0
	for i = 1, #c.g.props do
		local n = nums[i] or 0
		if n < 0 then return err_reply(seq, "ship_spirit_batch_level_up", "LS_so_luong_am", ERR.generic) end
		nums[i] = n
		total = total + n
	end
	if total <= 0 then return err_reply(seq, "ship_spirit_batch_level_up", "LS_chua_chon_qua", ERR.generic) end
	for i, gp in ipairs(c.g.props) do
		if LS.prop_get(gp.id) < nums[i] * gp.n then return err_reply(seq, "ship_spirit_batch_level_up", "LS_khong_du_qua", ERR.items) end
	end

	local used = 0
	for i, gp in ipairs(c.g.props) do
		for _ = 1, nums[i] do
			if at_max(c.h) then break end
			LS.prop_add(gp.id, -gp.n)
			add_exp(c.h, gp.exp)
			used = used + 1
		end
	end
	R.sp_last = "tang " .. fint(used) .. " qua cho tuong " .. c.sid
	stat_inc("sp_gift", used)
	return finish(c.e, seq, "ship_spirit_batch_level_up", c.sid)
end

function SP.dump_line()
	local a = S ~= nil and S.wp or nil
	if type(a) ~= "table" or type(a.h) ~= "table" then return "[LS warrior party] chua khoi tao" end
	local n, top_s, top_l = 0, 0, 0
	for _, h in pairs(a.h) do
		if type(h) == "table" then
			n = n + 1
			local s, l = tonumber(h.s) or 1, tonumber(h.l) or 1
			if s > top_s or (s == top_s and l > top_l) then top_s, top_l = s, l end
		end
	end
	return "[LS warrior party] " .. n .. " tuong co hao cam | cao nhat bac " .. top_s .. " cap " .. top_l
		.. " | full " .. (SP.full_on() and "BAT" or "TAT")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.sp_last ~= nil and (" | cuoi: " .. R.sp_last) or "")
end

function SP.reset()
	S.wp = nil
	R.sp_clean = nil
	R.sp_sig, R.sp_now = nil, nil
	mark()
end

function SP.on_world(e)
	R.sp_t, R.sp_clean = nil, nil
	R.sp_sig, R.sp_now = nil, nil
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if SP.any(sid) then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._sp = SP

end
init_sp()
end

do
local function init_cb()

local CB = {}
local FLOOR_LOW, FLOOR_TOP = 5000, 99999
local MAX_FIELD = 6

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	return out
end

local function plist(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do out[#out + 1] = { tonumber(a), tonumber(b) } end
	return out
end

local function cfg_row(id)
	local pc = dtab("play_config")
	if pc == nil then return nil end
	local r = cells(pc[id])
	if r == nil then return nil end
	return r[schema("pirates_config", "param", 4)]
end

function CB.T()
	local T = R.cb_t
	if T ~= nil and T.ok == true then return T end
	-- [FIX combo card reset] Truoc day ham nay cache R.cb_t NGAY khi config chua
	-- nap xong (dtab tra nil). Ket qua: T.cfg.cap = nil va T.cap = {} bi giu
	-- vinh vien -> fix_slot() clamp moi cap ve 1 -> thoat game vao lai thay
	-- nhu bi reset. Gio chi cache khi da nap du config.
	T = { ok = false, cards = {}, tids = {}, ins = {}, cap = {}, num = {}, props = {}, cfg = {} }
	local mt, it, pt = dtab("comb_mould"), dtab("comb_inset"), dtab("comb_inset_param")
	if mt == nil or it == nil then return T end
	R.cb_t = T
	local MC = { tid = schema("ship_combination_card_mould", "ship_id", 2), nf = schema("ship_combination_card_mould", "solt_num", 5),
		c1 = schema("ship_combination_card_mould", "unlock_conditon_one", 6), cons = schema("ship_combination_card_mould", "unlock_consume_prop", 11),
		s1 = schema("ship_combination_card_mould", "solt_ship_id_one", 12), g1 = schema("ship_combination_card_mould", "solt_group_one", 26),
		sort = schema("ship_combination_card_mould", "card_sort", 33) }
	for k, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local tid = tonumber(r[MC.tid])
			if tid ~= nil then
				tid = math.floor(tid)
				local defs, fixed = {}, 0
				for i = 0, 4 do
					local v = tonumber(r[MC.s1 + i]) or -1
					if v ~= -1 then fixed = fixed + 1; defs[fixed] = math.floor(v) end
				end
				local groups, conds = {}, {}
				for i = 1, 7 do
					groups[i] = math.floor(tonumber(r[MC.g1 + i - 1]) or i)
					local c = {}
					local raw = tostring(r[MC.sort + i] or "-1")
					if raw ~= "-1" then
						for a, b in string.gmatch(raw, "(%-?%d+)%s*,%s*(%-?%d+)") do c[#c + 1] = { tonumber(a), tonumber(b) } end
					end
					conds[i] = c
				end
				local heroes = {}
				for i = 0, 4 do
					local raw = tostring(r[MC.c1 + i] or "-1")
					local hid = tonumber(string.match(raw, "^(%-?%d+)"))
					if hid ~= nil and hid > 0 then heroes[#heroes + 1] = math.floor(hid) end
				end
				T.cards[tid] = { tid = tid, fixed = fixed, defs = defs, groups = groups, conds = conds, heroes = heroes,
					cons = triples(r[MC.cons]), sort = tonumber(r[MC.sort]) or 0 }
				T.tids[#T.tids + 1] = tid
			end
		end
	end
	table.sort(T.tids, function(a, b)
		local sa, sb = T.cards[a].sort, T.cards[b].sort
		if sa ~= sb then return sa < sb end
		return a < b
	end)
	-- [BO THE LOI ANH] The Combo Card nao thieu file hinh (icon / spine cua form dau tien) hoac nam trong
	-- offline_lr_ban.txt thi bo han khoi danh sach: khong mo, khong tao tuong the, khong tinh vao FULL.
	-- Tuong the da lo tao tu truoc se bi ART.prune don vi the khong con la the Combo hop le.
	do
		local A, keep, dropped = LS._art, {}, {}
		for _, tid in ipairs(T.tids) do
			local why
			if LS.ban_hit ~= nil and LS.ban_hit(tid) then
				why = "nam trong offline_lr_ban.txt"
			elseif A ~= nil and A.forms ~= nil and A.form_state ~= nil then
				local okf, forms = pcall(A.forms, tid)
				local f = (okf and type(forms) == "table") and tonumber(forms[1]) or nil
				if f ~= nil and f > 0 then
					local oks, fs = pcall(A.form_state, f)
					if oks and type(fs) == "table" and (fs.icon == false or fs.spine == false) then
						why = "thieu file hinh form " .. tostring(f) .. (fs.icon == false and " (icon)" or "") .. (fs.spine == false and " (spine)" or "")
					end
				end
			end
			if why ~= nil then
				dropped[#dropped + 1] = tid
				T.cards[tid] = nil
				log("Combo Card: BO the", tid, "-", why)
			else
				keep[#keep + 1] = tid
			end
		end
		T.tids = keep
		T.dropped = dropped
	end
	local IC = { lv = schema("ship_combination_card_level_mould", "level", 2), up = schema("ship_combination_card_level_mould", "up_consume", 3),
		bk = schema("ship_combination_card_level_mould", "breake_consume", 4), cl = schema("ship_combination_card_level_mould", "breake_level", 5),
		gp = schema("ship_combination_card_level_mould", "group_id", 6), ad = schema("ship_combination_card_level_mould", "add_params", 7) }
	for _, row in pairs(it) do
		local r = cells(row)
		if r ~= nil then
			local g, lv = tonumber(r[IC.gp]), tonumber(r[IC.lv])
			if g ~= nil and lv ~= nil then
				g, lv = math.floor(g), math.floor(lv)
				local a = T.ins[g]
				if a == nil then a = {}; T.ins[g] = a end
				local bk = tostring(r[IC.bk] or "-1")
				a[lv] = { up = triples(r[IC.up]), brk = (bk ~= "-1") and triples(bk) or nil, cls = math.floor(tonumber(r[IC.cl]) or 1), add = plist(r[IC.ad]) }
				if lv > (T.cap[g] or 0) then T.cap[g] = lv end
				for _, list in ipairs({ a[lv].up, a[lv].brk or {} }) do
					for _, t in ipairs(list) do if t[1] == 6 then T.props[t[2]] = true end end
				end
			end
		end
	end
	if pt ~= nil then
		local PC = { cl = schema("ship_combination_card_add_mould", "level", 2), nm = schema("ship_combination_card_add_mould", "num", 3), od = schema("ship_combination_card_add_mould", "order", 4) }
		for _, row in pairs(pt) do
			local r = cells(row)
			if r ~= nil then
				local cl, nm, od = tonumber(r[PC.cl]), tonumber(r[PC.nm]), tonumber(r[PC.od])
				if cl ~= nil and nm ~= nil and od ~= nil then
					local a = T.num[math.floor(od)]
					if a == nil then a = {}; T.num[math.floor(od)] = a end
					a[math.floor(cl)] = nm
				end
			end
		end
	end
	local function two(id)
		local a, b = string.match(tostring(cfg_row(id) or ""), "(%-?%d+)%s*,%s*(%-?%d+)")
		return tonumber(a), tonumber(b)
	end
	T.cfg.init_n = math.floor(tonumber(cfg_row(176)) or 1)
	T.cfg.exp_id, T.cfg.exp_n = two(177)
	T.cfg.exp_gold = math.floor(tonumber(cfg_row(178)) or 0)
	T.cfg.cap = math.floor(tonumber(cfg_row(179)) or 200)
	T.cfg.cp_id, T.cfg.cp_n = two(180)
	T.cfg.minfight = tonumber(cfg_row(181)) or 100000
	if T.cfg.exp_id ~= nil then T.props[T.cfg.exp_id] = true end
	if T.cfg.cp_id ~= nil then T.props[T.cfg.cp_id] = true end
	for _, tid in ipairs(T.tids) do
		local c = T.cards[tid]
		for _, t in ipairs(c.cons) do if t[1] == 6 then T.props[t[2]] = true end end
		for _, h in ipairs(c.heroes) do
			local pid = tonumber(mstr(h, "fitSkillOne"))
			if pid ~= nil and pid > 0 then T.props[math.floor(pid)] = true end
		end
	end
	T.ok = #T.tids > 0 and next(T.ins) ~= nil
	return T
end

local function full_on() return type(S.cfg) == "table" and S.cfg.cb_full == true end
local function auto_on() return not (type(S.cfg) == "table" and S.cfg.cb_auto == false) end
local function stats_on() return not (type(S.cfg) == "table" and S.cfg.cb_stats == false) end
local function minfight()
	if type(S.cfg) == "table" and tonumber(S.cfg.cb_minfight) ~= nil then return tonumber(S.cfg.cb_minfight) end
	return CB.T().cfg.minfight
end

local function st()
	local a = S.cb
	if type(a) ~= "table" then a = { v = 1 }; S.cb = a end
	if type(a.u) ~= "table" then a.u = {} end
	if type(a.sl) ~= "table" then a.sl = {} end
	a.ex = math.max(0, math.floor(tn(a.ex, 0)))
	return a
end

local function is_unlocked(tid)
	local a = S ~= nil and S.cb or nil
	return type(a) == "table" and type(a.u) == "table" and a.u[tostring(tid)] ~= nil
end

local function ship_of(e, sid)
	if type(e.user_ship) ~= "table" then return nil end
	local sh = e.user_ship[tostring(sid)]
	if type(sh) ~= "table" then return nil end
	return sh
end

local function default_slots(card)
	local sl = {}
	for i = 1, 7 do sl[tostring(i - 1)] = { s = (i <= card.fixed) and 0 or -1, l = 1, c = 1 } end
	return sl
end

local function fix_slot(card, i, x)
	if type(x) ~= "table" then x = { s = (i <= card.fixed) and 0 or -1, l = 1, c = 1 } end
	local T = CB.T()
	local g = card.groups[i]
	local cap = math.min(T.cfg.cap, T.cap[g] or T.cfg.cap)
	x.s = math.floor(tn(x.s, (i <= card.fixed) and 0 or -1))
	if i <= card.fixed and x.s < 0 then x.s = 0 end
	if x.s < -1 then x.s = -1 end
	x.l = math.floor(tn(x.l, 1))
	if x.l < 1 then x.l = 1 end
	if x.l > cap then x.l = cap end
	x.c = math.floor(tn(x.c, 1))
	if x.c < 1 then x.c = 1 end
	if x.c > 40 then x.c = 40 end
	return x
end

function CB.slots(tid)
	local T = CB.T()
	local card = T.cards[tid]
	if card == nil then return nil end
	local a = st()
	local key = tostring(tid)
	local sl = a.sl[key]
	if type(sl) ~= "table" then sl = default_slots(card); a.sl[key] = sl end
	for i = 1, 7 do
		local k = tostring(i - 1)
		sl[k] = fix_slot(card, i, sl[k])
	end
	return sl
end

local function copy_slots(src)
	local out = {}
	for k, x in pairs(src or {}) do
		if type(x) == "table" then
			out[tostring(k)] = { s = math.floor(tn(x.s, -1)), l = math.max(1, math.floor(tn(x.l, 1))), c = math.max(1, math.floor(tn(x.c, 1))) }
		end
	end
	return out
end

-- [FIX combo card reset] Copy 1 o (slot) duy nhat.
local function copy_slots_one(x)
	if type(x) ~= "table" then return nil end
	return { s = math.floor(tn(x.s, -1)), l = math.max(1, math.floor(tn(x.l, 1))), c = math.max(1, math.floor(tn(x.c, 1))) }
end

local function copy_progress(a)
	local u, sl = {}, {}
	for k, v in pairs(a.u or {}) do u[tostring(k)] = v end
	for k, v in pairs(a.sl or {}) do sl[tostring(k)] = copy_slots(v) end
	return { u = u, sl = sl, ex = math.max(0, math.floor(tn(a.ex, 0))) }
end

local function restore_progress(a, saved)
	-- [FIX combo card reset] Chi khoi phuc nhung o THUC SU thap hon tien trinh
	-- hien tai. Truoc day ham nay ghi de toan bo a.sl bang anh chup cu
	-- (a.manual), nen moi lan nang pham/cap sau khi tat FULL deu bi tra ve
	-- cap 1 -> thoat game vao lai thay nhu bi reset.
	local cur = a.sl
	a.u, a.sl = {}, {}
	if type(saved) == "table" then
		for k, v in pairs(saved.u or {}) do a.u[tostring(k)] = v end
		for k, v in pairs(saved.sl or {}) do a.sl[tostring(k)] = copy_slots(v) end
		a.ex = math.max(0, math.floor(tn(saved.ex, 0)))
	else
		a.ex = 0
	end
	-- Giu lai tien trinh cao hon (nguoi choi da tu nang sau khi chup a.manual)
	if type(cur) == "table" then
		for k, v in pairs(cur) do
			local kk = tostring(k)
			local dst = a.sl[kk]
			if type(dst) ~= "table" then
				a.sl[kk] = copy_slots(v)
			elseif type(v) == "table" then
				for sk, sv in pairs(v) do
					local d = dst[tostring(sk)]
					if type(d) ~= "table" then
						dst[tostring(sk)] = copy_slots_one(sv)
					elseif type(sv) == "table" then
						local sl_l = tonumber(sv.l) or 0
						local sl_c = tonumber(sv.c) or 0
						if sl_l > (tonumber(d.l) or 0) then d.l = sl_l end
						if sl_c > (tonumber(d.c) or 0) then d.c = sl_c end
					end
				end
			end
		end
	end
end

local function full_slot(card, i, x)
	local T = CB.T()
	local rows = T.ins[card.groups[i]] or {}
	local cap = math.min(T.cfg.cap, T.cap[card.groups[i]] or T.cfg.cap)
	local lv, class = 1, 1
	while lv < cap do
		local row = rows[lv]
		if row == nil then break end
		if row.brk ~= nil and row.cls >= class then class = row.cls + 1 end
		lv = lv + 1
	end
	x.s = x.s == -1 and 0 or x.s
	x.l, x.c = lv, math.min(40, class)
	return x
end

-- [FIX FULL Combo] Truoc day FULL chi mo the + dua cap/bac moi o len max, KHONG cam tuong nao vao o:
-- slot_calc chi cong chi so khi o co tuong => the "full" nhung tong cong thuc te = 0. Nay FULL con tu
-- cam tuong vao cac o dang TRONG (khong de len tuong nguoi choi tu cam):
--   o co dinh   = dung tuong mac dinh cua o (neu dang so huu)
--   o tu do     = tuong manh nhat chua dung, khong o doi hinh, khong phai tuong co dinh cua bat ky the nao
local function cb_seated(a)
	local used = {}
	local T = CB.T()
	for _, tid in ipairs(T.tids) do
		local sl = a.sl[tostring(tid)]
		if type(sl) == "table" then
			for _, x in pairs(sl) do
				if type(x) == "table" and (tonumber(x.s) or 0) > 0 then used[math.floor(tonumber(x.s))] = true end
			end
		end
	end
	return used
end

local function cb_pool(e, all_fixed)
	local T = CB.T()
	local mf = minfight()
	local list = {}
	for sid, sh in pairs(e.user_ship) do
		local n = tonumber(sid)
		if type(sh) == "table" and n ~= nil then
			local ct = tonumber(sh.captain_type)
			local tid = tonumber(sh.ship_template_id)
			if (ct == nil or (ct ~= 0 and ct ~= 2 and ct ~= 3)) and tid ~= nil and T.cards[math.floor(tid)] == nil
				and not all_fixed[math.floor(tid)] and tn(sh.formation_index, 0) <= 0
				and tostring(sh.combUpLockState or "0") ~= "1" then
				local f = tonumber(sh.hero_fight) or 0
				if f >= mf then list[#list + 1] = { sid = math.floor(n), tid = math.floor(tid), f = f } end
			end
		end
	end
	table.sort(list, function(x, y)
		if x.f ~= y.f then return x.f > y.f end
		return x.sid < y.sid
	end)
	return list
end

local function cb_fill(e, pool, used, card, sl, fixed_pass)
	local T = CB.T()
	local changed = false
	for i = 1, 7 do
		local is_fixed = i <= card.fixed
		if is_fixed == fixed_pass then
			local x = sl[tostring(i - 1)]
			local seat = math.floor(tn(x.s, -1))
			if seat == 0 or (seat > 0 and ship_of(e, seat) == nil) then
				local pick
				if is_fixed then
					local mould, best = card.defs[i], nil
					for sid, sh in pairs(e.user_ship) do
						local n = tonumber(sid)
						if type(sh) == "table" and n ~= nil and tonumber(sh.ship_template_id) == mould and not used[math.floor(n)]
							and tostring(sh.combUpLockState or "0") ~= "1" then
							-- uu tien ban khong o doi hinh, roi toi luc chien
							local score = (tonumber(sh.hero_fight) or 0) - ((tn(sh.formation_index, 0) > 0) and 1e12 or 0)
							if best == nil or score > best then pick, best = math.floor(n), score end
						end
					end
				else
					local q_best
					for _, h in ipairs(pool) do
						if not used[h.sid] then
							local nm = T.num[math.floor(mnum(h.tid, "ability", 0))]
							local q = nm ~= nil and (nm[x.c] or 0) or 0
							-- pool da sap theo luc chien giam dan => dau tien dat q cao nhat thang
							if pick == nil or q > q_best then pick, q_best = h.sid, q end
						end
					end
				end
				if pick ~= nil then
					x.s = pick
					used[pick] = true
					changed = true
				end
			end
		end
	end
	return changed
end

local function cb_seat_all(a, e)
	local T = CB.T()
	local used = cb_seated(a)
	local changed = false
	local all_fixed = {}
	for _, tid in ipairs(T.tids) do
		local card = T.cards[tid]
		for k = 1, card.fixed do all_fixed[card.defs[k]] = true end
	end
	for _, tid in ipairs(T.tids) do
		if cb_fill(e, nil, used, T.cards[tid], CB.slots(tid), true) then changed = true end
	end
	local pool = cb_pool(e, all_fixed)
	for _, tid in ipairs(T.tids) do
		if cb_fill(e, pool, used, T.cards[tid], CB.slots(tid), false) then changed = true end
	end
	return changed
end

local function make_full(a, e)
	local T = CB.T()
	local changed = false
	if not a.full then
		a.manual, a.full, a.mig38 = copy_progress(a), true, true
		changed = true
	end
	local ex = math.max(0, MAX_FIELD - (T.cfg.init_n or 1))
	if a.ex ~= ex then a.ex = ex; changed = true end
	for _, tid in ipairs(T.tids) do
		local card, key = T.cards[tid], tostring(tid)
		if a.u[key] == nil then a.u[key] = 1; changed = true end
		-- Moi the Combo la LR theo du lieu game. Chi tao dung 8 mau nay,
		-- khong mo rong danh sach "TAT CA TUONG" da loc LR.
		if CB.card_ship(e, tid) == nil then
			local ok, sh = pcall(LS.create_hero, tid, nil, true)
			if ok and type(sh) == "table" then changed = true
			elseif not ok then log("Combo Card FULL: khong tao duoc tuong the", tid, tostring(sh)) end
		end
		local sl = CB.slots(tid)
		for i = 1, 7 do
			local x = sl[tostring(i - 1)]
			local old_l, old_c, old_s = x.l, x.c, x.s
			full_slot(card, i, x)
			if old_l ~= x.l or old_c ~= x.c or old_s ~= x.s then changed = true end
		end
	end
	if cb_seat_all(a, e) then changed = true end
	return changed
end

local function all_max(a)
	local T = CB.T()
	if #T.tids == 0 then return false end
	for _, tid in ipairs(T.tids) do
		if a.u[tostring(tid)] == nil then return false end
		local card, sl = T.cards[tid], a.sl[tostring(tid)]
		if type(sl) ~= "table" then return false end
		for i = 1, 7 do
			local x = sl[tostring(i - 1)]
			local cap = math.min(T.cfg.cap, T.cap[card.groups[i]] or T.cfg.cap)
			if type(x) ~= "table" or (tonumber(x.l) or 0) < cap or (tonumber(x.s) or -1) < 0 then return false end
		end
	end
	return true
end

local function unfull(a)
	if a.mig38 == nil then
		a.mig38 = true
		-- [FIX combo card reset] Ban cu chup a.manual = RONG roi unfull() khoi phuc
		-- tu ban rong => xoa sach cap/pham vua nang. Phai chup DUNG tien trinh
		-- hien tai (da max) de khi tat FULL con duong lui.
		if a.full == nil and all_max(a) and not (type(S.cfg) == "table" and S.cfg.cb_full == false) then
			a.manual = copy_progress(a)
			a.full = true
			log("Combo Card: bo FULL cua ban cu -> giu nguyen tien trinh da max")
		end
	end
	if not a.full then return false end
	-- [FIX combo card reset] manual rong = khong co gi de khoi phuc. Khoi phuc tu
	-- ban rong se xoa sach cap/pham => chi restore khi manual that su co du lieu.
	local man = a.manual
	local has_data = type(man) == "table" and type(man.sl) == "table" and next(man.sl) ~= nil
	if has_data then restore_progress(a, man) end
	a.manual, a.full = nil, nil
	R.cb_last = "tat full: tra Combo Card ve tien trinh tu nang"
	return true
end

-- Mo san Combo Card de nguoi choi tu nang. Khong goi make_full(), nen tat ca
-- o deu o cap 1/bac 1 va van dung dung nut nang cua game goc.
function CB.gm_manual_unlock(e)
	e = e or ED()
	local T = CB.T()
	if e == nil or type(e.user_ship) ~= "table" or not T.ok then return nil end
	local a = st()
	if type(S.cfg) ~= "table" then S.cfg = {} end
	local reset_progress = a.full == true or S.cfg.cb_full == true
	S.cfg.cb_full = nil
	if a.full then restore_progress(a, a.manual) end
	a.manual, a.full = nil, nil

	local opened, made = 0, 0
	a.ex = math.max(0, MAX_FIELD - (T.cfg.init_n or 1))
	for _, tid in ipairs(T.tids) do
		local card, key = T.cards[tid], tostring(tid)
		if a.u[key] == nil then a.u[key] = 1 end
		opened = opened + 1
		if CB.card_ship(e, tid) == nil then
			local ok, sh = pcall(LS.create_hero, tid, nil, true)
			if ok and type(sh) == "table" then made = made + 1
			elseif not ok then log("Combo Card MO TAY: khong tao duoc tuong the", tid, tostring(sh)) end
		end
		local sl = CB.slots(tid)
		for i = 1, 7 do
			local x = sl[tostring(i - 1)]
			if x.s < 0 then x.s = 0 end
			if reset_progress then x.l, x.c = 1, 1 end
		end
	end
	R.cb_sig = nil
	R.cb_last = "mo " .. opened .. " the de tu nang" .. (reset_progress and " (cap o 1)" or "")
	R.stat_dirty = true
	CB.push_ed(e)
	mark()
	LS.save_state(true)
	log("Combo Card: mo tay", opened, "the; tao", made, "tuong the; tat FULL")
	return opened, made
end

local function fmt3(t)
	return fint(t[1]) .. "," .. fint(t[2]) .. "," .. fint(t[3])
end

local function slot_calc(e, card, i, x)
	local T = CB.T()
	local row = T.ins[card.groups[i]] ~= nil and T.ins[card.groups[i]][x.l] or nil
	local base, fin, ext = { 0, 0, 0 }, { 0, 0, 0 }, { 0, 0, 0 }
	if row ~= nil then
		for _, kv in ipairs(row.add) do
			if kv[1] >= 0 and kv[1] <= 2 then base[kv[1] + 1] = base[kv[1] + 1] + kv[2] end
		end
	end
	local ship = x.s > 0 and ship_of(e, x.s) or nil
	if ship ~= nil and (tonumber(ship.hero_fight) or 0) >= minfight() then
		local q = 0
		local od = mnum(tonumber(ship.ship_template_id) or -1, "ability", 0)
		local nm = T.num[math.floor(od)]
		if nm ~= nil then q = nm[x.c] or 0 end
		local extra_sum = 0
		for k = 1, 3 do
			fin[k] = math.floor(base[k] * (1 + q))
			extra_sum = extra_sum + (fin[k] - base[k])
		end
		ext[2] = extra_sum
	end
	return fin, base, ext
end

function CB.totals(tid)
	local e = ED()
	local T = CB.T()
	local card = T.cards[tid]
	local f, b, x = { 0, 0, 0 }, { 0, 0, 0 }, { 0, 0, 0 }
	if card == nil or e == nil then return f, b, x end
	local sl = is_unlocked(tid) and CB.slots(tid) or nil
	if sl == nil then return f, b, x end
	for i = 1, 7 do
		local x1 = sl[tostring(i - 1)]
		if x1.s ~= -1 then
			local ff, bb, xx = slot_calc(e, card, i, x1)
			if x1.s > 0 then
				for k = 1, 3 do f[k] = f[k] + ff[k]; b[k] = b[k] + bb[k]; x[k] = x[k] + xx[k] end
			end
		end
	end
	return f, b, x
end

local function jesc(s) return (tostring(s):gsub('\\', '\\\\'):gsub('"', '\\"')) end

function CB.json_one(tid)
	local e = ED()
	local T = CB.T()
	local card = T.cards[tid]
	local unlocked = is_unlocked(tid)
	local sl = unlocked and CB.slots(tid) or default_slots(card)
	local parts = {}
	for i = 1, 7 do
		local x = fix_slot(card, i, sl[tostring(i - 1)])
		local fin, base, ext = slot_calc(e, card, i, x)
		local shown = x.s
		if shown > 0 and ship_of(e, shown) == nil then shown = 0 end
		parts[#parts + 1] = string.format('"%d":{"shipId":%s,"defaultShipId":%s,"slotLevel":%s,"slotClass":%s,"groupId":%s,"oneSlotAddition":"%s|%s|%s"}',
			i - 1, fint(shown), fint(i <= card.fixed and card.defs[i] or -1), fint(x.l), fint(x.c), fint(card.groups[i]), fmt3(fin), fmt3(base), fmt3(ext))
	end
	local slot_json = "{" .. table.concat(parts, ",") .. "}"
	local f, b, x = CB.totals(tid)
	local total = fmt3(f) .. "|" .. fmt3(b) .. "|" .. fmt3(x)
	return '{"totalAddition":"' .. total .. '","slotInfo":"' .. jesc(slot_json) .. '"}'
end

function CB.blk_one(tid) return "14128\r\n" .. CB.json_one(tid) end

function CB.blk_list()
	local T = CB.T()
	local parts = {}
	for _, tid in ipairs(T.tids) do
		parts[#parts + 1] = string.format('{"shipId":%s,"isUnlock":%s}', fint(tid), is_unlocked(tid) and "true" or "false")
	end
	return '14121\r\n{"combMouldList":[' .. table.concat(parts, ",") .. ']}'
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3]) end
	return table.concat(b, "\r\n")
end

function CB.is_card(tid)
	local T = CB.T()
	return T.cards[tonumber(tid) or -1] ~= nil
end

function CB.any(sid)
	if not stats_on() then return false end
	local a = S ~= nil and S.cb or nil
	if type(a) ~= "table" or type(a.u) ~= "table" or next(a.u) == nil then return false end
	local e = ED()
	local sh = e ~= nil and ship_of(e, sid) or nil
	if sh == nil then return false end
	local tid = tonumber(sh.ship_template_id)
	return tid ~= nil and a.u[tostring(math.floor(tid))] ~= nil
end

function CB.adjust(sid, tid, pn, spec, is_rec)
	if not stats_on() or type(pn) ~= "table" then return end
	tid = tonumber(tid)
	if tid == nil or not is_unlocked(tid) then return end
	local ok, err = pcall(function()
		local f = CB.totals(math.floor(tid))
		for i = 1, 3 do
			local x = pn[i]
			if type(x) == "number" and f[i] ~= 0 then pn[i] = math.max(0, rnd(x + f[i])) end
		end
	end)
	if not ok then
		R.cb_errs = (R.cb_errs or 0) + 1
		if R.cb_errs <= 5 then log("loi chi so Combo Card:", tostring(err)) end
	end
end

local function plain_hero(ship)
	local ct = tonumber(ship.captain_type)
	return ct == nil or (ct ~= 0 and ct ~= 2 and ct ~= 3)
end

function CB.card_ship(e, tid)
	if type(e.user_ship) ~= "table" then return nil end
	local best
	for sid, sh in pairs(e.user_ship) do
		if type(sh) == "table" and tonumber(sh.ship_template_id) == tid and tonumber(sid) ~= nil then
			if best == nil or tonumber(sid) < tonumber(best) then best = tostring(sid) end
		end
	end
	return best
end

local function refresh_card(e, tid, blocks)
	local key = CB.card_ship(e, tid)
	local ship = key ~= nil and ship_of(e, key) or nil
	if ship == nil or not plain_hero(ship) then return end
	local ok, err = pcall(function()
		local F = commit_hero(e, key, {})
		if F ~= nil then
			apply_hero(e, key)
			push_all(blocks, blk_ship(ship, F))
			push_all(blocks, blk_fight(e, key, F))
		end
	end)
	if not ok then
		R.cb_errs = (R.cb_errs or 0) + 1
		if R.cb_errs <= 5 then log("loi tinh lai tuong the (Combo Card):", tostring(err)) end
	end
end

function CB.push_ed(e)
	e = e or ED()
	if e == nil or type(e.user_ship) ~= "table" then return end
	local T = CB.T()
	if not T.ok then return end
	local a = st()
	e.user_comb_can_filed_mould_num = tostring(math.min(MAX_FIELD, T.cfg.init_n + a.ex))
	local has, nu = {}, 0
	for _, tid in ipairs(T.tids) do
		if is_unlocked(tid) then nu = nu + 1; has[#has + 1] = { shipId = tostring(tid), mouldId = tostring(tid) } end
	end
	e.user_comb_has_mould_info = (#has > 0) and has or nil
	e.user_comb_unlock_mould_num = tostring(nu)
	local field = {}
	for _, sh in pairs(e.user_ship) do
		if type(sh) == "table" and tn(sh.formation_index, 0) > 0 then
			local tid = tonumber(sh.ship_template_id)
			if tid ~= nil and is_unlocked(math.floor(tid)) then field[#field + 1] = { userCombShipId = tostring(math.floor(tid)) } end
		end
	end
	e.user_comb_has_field_mould_info = (#field > 0) and field or nil

	local inslot = {}
	for _, tid in ipairs(T.tids) do
		if is_unlocked(tid) then
			local sl = CB.slots(tid)
			for i = 1, 7 do
				local x = sl[tostring(i - 1)]
				if x.s > 0 then inslot[tostring(x.s)] = true end
			end
		end
	end
	for sid, sh in pairs(e.user_ship) do
		if type(sh) == "table" and tonumber(sid) ~= nil then
			local want = inslot[tostring(sid)] and "1" or "0"
			if tostring(sh.combUpLockState or "0") ~= want then sh.combUpLockState = want end
		end
	end
end

local function prune(e)
	if R.inject ~= nil or R.grant ~= nil then return end
	-- [FIX combo card reset] Neu the gioi chua nap xong danh sach tuong thi
	-- KHONG duoc don o. Truoc day prune() chay ngay khi vao game, luc
	-- e.user_ship con thieu -> xoa s=0 hang loat, va lan luu ke tiep ghi
	-- trang thai rong xuong file -> thoat game vao lai mat tien trinh nang.
	if type(e) ~= "table" or type(e.user_ship) ~= "table" then return end
	if next(e.user_ship) == nil then return end
	local T = CB.T()
	local a = st()
	for key in pairs(a.u) do
		local tid = tonumber(key)
		if tid == nil or T.cards[tid] == nil then a.u[key] = nil; a.sl[key] = nil end
	end
	for key in pairs(a.sl) do
		if a.u[key] == nil then a.sl[key] = nil end
	end
	local used = {}
	for _, tid in ipairs(T.tids) do
		if is_unlocked(tid) then
			local sl = CB.slots(tid)
			for i = 1, 7 do
				local x = sl[tostring(i - 1)]
				if x.s > 0 and (ship_of(e, x.s) == nil or used[x.s]) then x.s = 0 end
				if x.s > 0 then used[x.s] = true end
			end
		end
	end
end

local function floor_props()
	if not auto_on() then return end
	local T = CB.T()
	for id in pairs(T.props) do
		if LS.prop_get(id) < FLOOR_LOW then LS.prop_set(id, FLOOR_TOP) end
	end
end

local function can_pay(list, times)
	times = times or 1
	if auto_on() then
		local want = {}
		for _, t in ipairs(list) do
			if t[1] == 6 then want[t[2]] = (want[t[2]] or 0) + t[3] * times end
		end
		for id, n in pairs(want) do
			if LS.prop_get(id) < n then LS.prop_set(id, n + FLOOR_TOP) end
		end
	end
	local need = {}
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		need[k] = (need[k] or 0) + t[3] * times
	end
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		local n = need[k]
		if n ~= nil then
			if t[1] == 6 then
				if LS.prop_get(t[2]) < n then return false, ERR.items end
			elseif t[1] == 1 then
				if (S.silver or 0) < n then return false, ERR.silver end
			elseif t[1] == 2 then
				if (S.gold or 0) < n then return false, ERR.items end
			end
			need[k] = nil
		end
	end
	return true
end

local function pay(list, times)
	times = times or 1
	for _, t in ipairs(list) do
		local n = t[3] * times
		if t[1] == 6 then LS.prop_add(t[2], -n)
		elseif t[1] == 1 then LS.money_spend("silver", n)
		elseif t[1] == 2 then LS.money_spend("gold", n) end
	end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if not CB.T().ok then error("khong co bang Combo Card") end
	prune(e)
	floor_props()
	return e
end

local function finish(e, seq, name, tid, extra)
	local blocks = {}
	for _, b in ipairs(extra or {}) do blocks[#blocks + 1] = b end
	refresh_card(e, tid, blocks)
	CB.push_ed(e)
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function card_of(seq, name, p)
	local tid = math.floor(tn(p[1], -1))
	local card = CB.T().cards[tid]
	if card == nil then return nil, nil, err_reply(seq, name, "LS_the_khong_ton_tai", ERR.generic) end
	return tid, card
end

function CB.h_init(p, seq)
	local e = ctx()
	CB.push_ed(e)
	stat_inc("cb_init")
	return reply(seq, "combine_ship_init", { CB.blk_list() })
end

function CB.h_get_one(p, seq)
	local e = ctx()
	local tid, card, er = card_of(seq, "combine_ship_get_one", p)
	if tid == nil then return er end
	return reply(seq, "combine_ship_get_one", { CB.blk_one(tid) })
end

function CB.h_unlock_card(p, seq)
	local e = ctx()
	local tid, card, er = card_of(seq, "combine_ship_unlock_card", p)
	if tid == nil then return er end
	if is_unlocked(tid) then return err_reply(seq, "combine_ship_unlock_card", "LS_the_da_mo", ERR.generic) end
	local okp, code = can_pay(card.cons)
	if not okp then return err_reply(seq, "combine_ship_unlock_card", "LS_khong_du_nguyen_lieu", code) end
	if CB.card_ship(e, tid) == nil then
		local ok, err = pcall(LS.create_hero, tid, nil, true)
		if not ok then
			log("khong tao duoc tuong the", tid, tostring(err))
			return err_reply(seq, "combine_ship_unlock_card", "LS_khong_tao_duoc_tuong_the", ERR.generic)
		end
	end
	pay(card.cons)
	local a = st()
	a.u[tostring(tid)] = 1
	a.sl[tostring(tid)] = default_slots(card)
	CB.slots(tid)
	R.cb_last = "mo the " .. tid
	stat_inc("cb_unlock_card")
	-- [FIX combo card khong hien sau khi unlock] Client chi doc co isUnlock tu
	-- goi 14121 (combine_card_list_info.comb_mould_list). Goi 14120 chi dat
	-- _ED.combine_card_unlock_card = tid, KHONG cap nhat danh sach -> the vua
	-- mo van bi coi la chua mo (getCardStateById tra false) cho den khi vao lai
	-- man hinh. Gui kem blk_list() de UI thay the da mo ngay lap tuc.
	-- Gui RIENG 2 goi: 14120 (dat the vua mo) + 14121 (danh sach the).
	-- Neu noi CB.blk_list() vao payload cua 14120 thi parser 14120 bo qua het
	-- phan sau -> danh sach khong duoc cap nhat.
	return finish(e, seq, "combine_ship_unlock_card", tid, { "14120\r\n" .. fint(tid), CB.blk_list() })
end

function CB.h_unlock_slot(p, seq)
	local e = ctx()
	local tid, card, er = card_of(seq, "combine_ship_unlock_slot", p)
	if tid == nil then return er end
	if not is_unlocked(tid) then return err_reply(seq, "combine_ship_unlock_slot", "LS_the_chua_mo", ERR.generic) end
	local idx = math.floor(tn(p[2], -1))
	if idx < card.fixed or idx > 6 then return err_reply(seq, "combine_ship_unlock_slot", "LS_o_khong_hop_le", ERR.generic) end
	local sl = CB.slots(tid)
	local x = sl[tostring(idx)]
	if x.s ~= -1 then return err_reply(seq, "combine_ship_unlock_slot", "LS_o_da_mo", ERR.generic) end
	local T = CB.T()
	local cost = {}
	if T.cfg.cp_id ~= nil then cost[1] = { 6, T.cfg.cp_id, T.cfg.cp_n or 1 } end
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "combine_ship_unlock_slot", "LS_khong_du_ve_mo_o", code) end
	pay(cost)
	x.s = 0
	R.cb_last = "mo o " .. (idx + 1) .. " cua the " .. tid
	stat_inc("cb_unlock_slot")
	return finish(e, seq, "combine_ship_unlock_slot", tid, {})
end

local function pick_hero(e, tid, card, i, mould)
	local best
	local function bestof(strict)
		best = nil
		for sid, sh in pairs(e.user_ship) do
			if type(sh) == "table" and tonumber(sid) ~= nil and tonumber(sh.ship_template_id) == mould then
				local locked = tostring(sh.combUpLockState or "0") == "1"
				local busy = tn(sh.formation_index, 0) > 0
				if not locked and (not strict or not busy) then
					local f = tonumber(sh.hero_fight) or 0
					if best == nil or f > best.f then best = { id = tostring(sid), f = f } end
				end
			end
		end
		return best
	end
	if i <= card.fixed then
		bestof(true)
		if best == nil then bestof(false) end
	else
		bestof(true)
	end
	return best ~= nil and best.id or nil
end

function CB.h_change(p, seq)
	local e = ctx()
	local tid, card, er = card_of(seq, "combine_ship_change_slot", p)
	if tid == nil then return er end
	if not is_unlocked(tid) then return err_reply(seq, "combine_ship_change_slot", "LS_the_chua_mo", ERR.generic) end
	local idx = math.floor(tn(p[2], -1))
	if idx < 0 or idx > 6 then return err_reply(seq, "combine_ship_change_slot", "LS_o_khong_hop_le", ERR.generic) end
	local sl = CB.slots(tid)
	local x = sl[tostring(idx)]
	if x.s == -1 then return err_reply(seq, "combine_ship_change_slot", "LS_o_dang_khoa", ERR.generic) end
	local mould = math.floor(tn(p[3], 0))
	local i = idx + 1
	if mould <= 0 then
		x.s = 0
		R.cb_last = "go tuong khoi o " .. i .. " cua the " .. tid
	else
		if i <= card.fixed then
			if card.defs[i] ~= mould then return err_reply(seq, "combine_ship_change_slot", "LS_sai_tuong_o_co_dinh", ERR.generic) end
		else
			if CB.is_card(mould) then return err_reply(seq, "combine_ship_change_slot", "LS_khong_cam_the_vao_o", ERR.generic) end
			for k = 1, card.fixed do
				if card.defs[k] == mould then return err_reply(seq, "combine_ship_change_slot", "LS_trung_tuong_o_co_dinh", ERR.generic) end
			end
		end

		local old = x.s
		x.s = 0
		CB.push_ed(e)
		local pick = pick_hero(e, tid, card, i, mould)
		if pick == nil then
			x.s = old
			CB.push_ed(e)
			return err_reply(seq, "combine_ship_change_slot", "LS_khong_co_tuong_phu_hop", ERR.generic)
		end
		x.s = math.floor(tonumber(pick))
		R.cb_last = "cam tuong " .. pick .. " vao o " .. i .. " cua the " .. tid
	end
	stat_inc("cb_change")
	return finish(e, seq, "combine_ship_change_slot", tid, { "14123\r\n1" })
end

local function next_step(card, i, x)
	local T = CB.T()
	local g = card.groups[i]
	local rows = T.ins[g]
	if rows == nil then return nil end
	local row = rows[x.l]
	if row == nil then return nil end
	if row.brk ~= nil and row.cls == x.c then return "bk", row.brk end
	local cap = math.min(T.cfg.cap, T.cap[g] or T.cfg.cap)
	if x.l >= cap or rows[x.l + 1] == nil then return nil end
	return "lv", row.up
end

local function slot_args(seq, name, p)
	local e = ctx()
	local tid, card, er = card_of(seq, name, p)
	if tid == nil then return nil, er end
	if not is_unlocked(tid) then return nil, err_reply(seq, name, "LS_the_chua_mo", ERR.generic) end
	local idx = math.floor(tn(p[2], -1))
	if idx < 0 or idx > 6 then return nil, err_reply(seq, name, "LS_o_khong_hop_le", ERR.generic) end
	local sl = CB.slots(tid)
	local x = sl[tostring(idx)]
	if x.s == -1 then return nil, err_reply(seq, name, "LS_o_dang_khoa", ERR.generic) end
	if x.s <= 0 or ship_of(e, x.s) == nil then return nil, err_reply(seq, name, "LS_o_chua_co_tuong", ERR.generic) end
	return { e = e, tid = tid, card = card, i = idx + 1, x = x }
end

function CB.h_update(p, seq)
	local c, er = slot_args(seq, "combine_ship_update_slot", p)
	if c == nil then return er end
	local kind, cost = next_step(c.card, c.i, c.x)
	if kind == nil then return err_reply(seq, "combine_ship_update_slot", "LS_o_da_toi_da", ERR.level_cap) end
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "combine_ship_update_slot", "LS_khong_du_nguyen_lieu", code) end
	pay(cost)
	if kind == "bk" then c.x.c = c.x.c + 1 else c.x.l = c.x.l + 1 end
	-- [FIX combo card reset] danh dau dirty ngay khi doi cap/bac
	mark()
	R.cb_last = (kind == "bk" and "len bac" or "len cap") .. " o " .. c.i .. " cua the " .. c.tid
	stat_inc(kind == "bk" and "cb_break" or "cb_level")
	return finish(c.e, seq, "combine_ship_update_slot", c.tid, { CB.blk_one(c.tid) })
end

function CB.h_onekey(p, seq)
	local c, er = slot_args(seq, "combine_ship_one_key_update_slot", p)
	if c == nil then return er end
	local T = CB.T()
	local g = c.card.groups[c.i]
	local cap = math.min(T.cfg.cap, T.cap[g] or T.cfg.cap)
	local target = math.floor(tn(p[4], 0))
	if target > cap then target = cap end
	if target <= c.x.l then return err_reply(seq, "combine_ship_one_key_update_slot", "LS_cap_dich_khong_hop_le", ERR.generic) end

	local cost, cls, lv = {}, c.x.c, c.x.l
	while lv < target do
		local row = T.ins[g] ~= nil and T.ins[g][lv] or nil
		if row == nil then break end
		for _, t in ipairs(row.up) do cost[#cost + 1] = t end
		if row.brk ~= nil and row.cls >= cls then
			for _, t in ipairs(row.brk) do cost[#cost + 1] = t end
			cls = row.cls + 1
		end
		lv = lv + 1
	end
	if lv <= c.x.l then return err_reply(seq, "combine_ship_one_key_update_slot", "LS_o_da_toi_da", ERR.level_cap) end
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "combine_ship_one_key_update_slot", "LS_khong_du_nguyen_lieu", code) end
	pay(cost)
	c.x.l, c.x.c = lv, cls
	-- [FIX combo card reset] danh dau dirty ngay khi doi cap/bac
	mark()
	R.cb_last = "len 1 phim o " .. c.i .. " cua the " .. c.tid .. " -> cap " .. lv
	stat_inc("cb_onekey")
	return finish(c.e, seq, "combine_ship_one_key_update_slot", c.tid, { CB.blk_one(c.tid) })
end

function CB.h_debris(p, seq)
	local e = ctx()
	local tid, card, er = card_of(seq, "combine_ship_debris_exchange", p)
	if tid == nil then return er end
	local n = math.floor(tn(p[2], 0))
	if n <= 0 then return err_reply(seq, "combine_ship_debris_exchange", "LS_so_luong_khong_hop_le", ERR.generic) end
	local cost = {}
	for _, h in ipairs(card.heroes) do
		local pid = tonumber(mstr(h, "fitSkillOne"))
		if pid ~= nil and pid > 0 then cost[#cost + 1] = { 6, math.floor(pid), 1 } end
	end
	local out = tonumber(mstr(tid, "fitSkillOne"))
	if out == nil or out <= 0 or #cost == 0 then return err_reply(seq, "combine_ship_debris_exchange", "LS_khong_co_manh", ERR.generic) end
	local okp, code = can_pay(cost, n)
	if not okp then return err_reply(seq, "combine_ship_debris_exchange", "LS_khong_du_manh", code) end
	pay(cost, n)
	LS.prop_add(math.floor(out), n)
	R.cb_last = "doi " .. n .. " manh the " .. tid
	stat_inc("cb_debris")
	mark()
	LS.save_state(true)
	return reply(seq, "combine_ship_debris_exchange", { blk_reward({ { math.floor(out), 6, n } }) })
end

function CB.h_expand(p, seq)
	local e = ctx()
	local T = CB.T()
	local a = st()
	local cur = math.min(MAX_FIELD, T.cfg.init_n + a.ex)
	if cur >= MAX_FIELD then return err_reply(seq, "combine_ship_filed_expansion", "LS_da_toi_da", ERR.rank_max) end
	local mode = math.floor(tn(p[1], 0))
	if mode == 0 then
		if T.cfg.exp_id == nil then return err_reply(seq, "combine_ship_filed_expansion", "LS_khong_co_ve", ERR.items) end
		local cost = { { 6, T.cfg.exp_id, T.cfg.exp_n or 1 } }
		local okp, code = can_pay(cost)
		if not okp then return err_reply(seq, "combine_ship_filed_expansion", "LS_khong_du_ve", code) end
		pay(cost)
	end
	a.ex = a.ex + 1
	R.cb_last = "mo rong cho ra tran -> " .. (cur + 1)
	stat_inc("cb_expand")
	CB.push_ed(e)
	mark()
	LS.save_state(true)
	return reply(seq, "combine_ship_filed_expansion", { "14127\r\n" .. fint(cur + 1) })
end

function CB.h_field(p, seq)
	ctx()
	return reply(seq, "combine_ship_slot_field", {})
end

function CB.dump_line()
	local a = S ~= nil and S.cb or nil
	if type(a) ~= "table" or type(a.u) ~= "table" then return "[LS combo card] chua khoi tao" end
	local n, heroes, lv = 0, 0, 0
	for key in pairs(a.u) do
		n = n + 1
		local sl = type(a.sl) == "table" and a.sl[key] or nil
		if type(sl) == "table" then
			for _, x in pairs(sl) do
				if type(x) == "table" then
					if (tonumber(x.s) or 0) > 0 then heroes = heroes + 1 end
					lv = lv + (tonumber(x.l) or 1)
				end
			end
		end
	end
	return "[LS combo card] " .. n .. " the da mo | " .. heroes .. " tuong trong o | tong cap o " .. lv
		.. " | cho ra tran " .. (CB.T().cfg.init_n + (tonumber(a.ex) or 0)) .. " | full " .. (full_on() and "BAT" or "TAT")
		.. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.cb_last ~= nil and (" | cuoi: " .. R.cb_last) or "")
end

local function dedupe_card_ships(e)
	if R.inject ~= nil or R.grant ~= nil then return 0 end
	if type(e) ~= "table" or type(e.user_ship) ~= "table" then return 0 end
	if S == nil or type(S.heroes) ~= "table" or type(S.order) ~= "table" then return 0 end
	local T = CB.T()
	if not T.ok then return 0 end
	local by = {}
	for sid, sh in pairs(e.user_ship) do
		if type(sh) == "table" and tonumber(sid) ~= nil then
			local tid = tonumber(sh.ship_template_id)
			if tid ~= nil and T.cards[math.floor(tid)] ~= nil then
				tid = math.floor(tid)
				local l = by[tid]
				if l == nil then l = {}; by[tid] = l end
				l[#l + 1] = tostring(sid)
			end
		end
	end
	local function better(sa, sb)
		local a, b = e.user_ship[sa], e.user_ship[sb]
		local ka = { tn(a.ship_grade, 0), tn(a.Order, 0), tn(a.StarRating, 0) }
		local kb = { tn(b.ship_grade, 0), tn(b.Order, 0), tn(b.StarRating, 0) }
		for i = 1, 3 do
			if ka[i] ~= kb[i] then return ka[i] > kb[i] end
		end
		return tonumber(sa) < tonumber(sb)
	end
	local gone, set = {}, {}
	for _, l in pairs(by) do
		if #l > 1 then
			table.sort(l, better)
			for i = 2, #l do
				-- Chi xoa ban do tool tao. Tuong that cua server khong bao gio bi dung toi.
				if S.heroes[l[i]] ~= nil then gone[#gone + 1] = l[i]; set[l[i]] = l[1] end
			end
		end
	end
	if #gone == 0 then return 0 end
	table.sort(gone, function(x, y) return tonumber(x) < tonumber(y) end)

	local function remap(f)
		if type(f) ~= "table" then return false end
		local used, changed = {}, false
		for i = 1, 6 do
			if f[i] ~= nil then used[tostring(f[i])] = true end
		end
		for i = 1, 6 do
			local keep = f[i] ~= nil and set[tostring(f[i])] or nil
			if keep ~= nil then
				if used[keep] then f[i] = "0" else f[i] = keep; used[keep] = true end
				changed = true
			end
		end
		return changed
	end
	local f = read_formation(e)
	if remap(f) then write_formation(e, f) end
	remap(S.formation)

	for i = 1, #gone do
		local sid = gone[i]
		e.user_ship[sid] = nil
		S.heroes[sid] = nil
		if type(S.eq) == "table" and type(S.eq.hard) == "table" then S.eq.hard[sid] = nil end
		if type(S.mega) == "table" then S.mega[sid] = nil end
		if type(S.mods) == "table" then S.mods[sid] = nil end
	end
	local order, gset = {}, {}
	for i = 1, #gone do gset[gone[i]] = true end
	for i = 1, #S.order do
		if not gset[tostring(S.order[i])] then order[#order + 1] = S.order[i] end
	end
	S.order = order
	e.user_ship_number = count_ships(e)
	R.owned = owned_set(e)
	R.hero_ids, R.pool = nil, nil
	R.stat_dirty = true
	mark()
	LS.save_state(true)
	log("Combo Card: da don", #gone, "ban sao tuong the:", table.concat(gone, ","))
	return #gone
end

function CB.tick(e)
	if e == nil or type(e.user_ship) ~= "table" then return end
	-- [FIX COMBO CLONE] Tuong da luu duoc nap lai tung dot. Combo Card chay som
	-- hon se thay "chua co tuong the" -> tao them ban moi -> moi lan vao lai
	-- them 1 ban. Nen CHO inject xong roi moi xu ly.
	if R.inject ~= nil then R.cb_sig = nil; return end
	local sig = (R.inject ~= nil and tostring(R.inject.pos) or "-") .. ":" .. (R.grant ~= nil and tostring(R.grant.pos) or "-") .. ":" .. tostring(e.user_ship_number)
	if sig == R.cb_sig then return end
	R.cb_sig = sig
	if not CB.T().ok then return end
	local a = st()
	local okd, errd = pcall(dedupe_card_ships, e)
	if not okd then
		R.cb_errs = (R.cb_errs or 0) + 1
		if R.cb_errs <= 5 then log("loi don ban sao the Combo Card:", tostring(errd)) end
	end
	local changed
	if full_on() then changed = make_full(a, e) else changed = unfull(a) end
	if changed then
		mark()
		-- [FIX FULL Combo] 8 tuong the la tuong LS (S.heroes) nen heroes_assert khong tinh lai ho:
		-- dua vao hang doi tinh lai de chi so cong cua cac o hien ngay (va tra ve khi tat FULL)
		R.stat_dirty = true
		local tl = LS._tl
		if tl ~= nil and tl.queue_list ~= nil then
			local list = {}
			for _, tid in ipairs(CB.T().tids) do
				local key = CB.card_ship(e, tid)
				if key ~= nil then list[#list + 1] = key end
			end
			if #list > 0 then pcall(tl.queue_list, list) end
		end
	end
	prune(e)
	CB.push_ed(e)
end

function CB.apply_now(e)
	if e ~= nil then
		R.cb_sig = nil
		CB.tick(e)
	end
end
CB.full_on = full_on

function CB.reset()
	S.cb = nil
	R.cb_clean = nil
	R.cb_sig = nil
	local e = ED()
	if e ~= nil then
		e.user_comb_has_mould_info, e.user_comb_has_field_mould_info = nil, nil
		e.user_comb_unlock_mould_num = "0"
		pcall(CB.push_ed, e)
	end
	mark()
end

function CB.on_world(e)
	R.cb_t, R.cb_clean = nil, nil
	if S ~= nil and S.cb ~= nil and type(S.cb) ~= "table" then S.cb = nil end
	local ok, err = pcall(function()
		if CB.T().ok then
			prune(e)
			CB.push_ed(e)
		end
	end)
	if not ok then log("loi khoi tao Combo Card:", tostring(err)) end
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if CB.any(sid) then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._cb = CB

end
init_cb()
end

do
local function init_ic()

local IC = {}
local FLOOR_LOW, FLOOR_TOP = 5000, 99999

local function split_tab(s)
	local t, pos = {}, 1
	while true do
		local p = string.find(s, "\t", pos, true)
		if p == nil then t[#t + 1] = string.sub(s, pos); break end
		t[#t + 1] = string.sub(s, pos, p - 1)
		pos = p + 1
	end
	return t
end
local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end
local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end
local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return math.floor(tonumber(sc[field])) end
	return dflt
end
local function ints(s)
	local out = {}
	for n in string.gmatch(tostring(s or ""), "%-?%d+") do out[#out + 1] = math.floor(tonumber(n)) end
	return out
end
local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	return out
end
local function attrs(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		local ty, val = tonumber(a), tonumber(b)
		if ty ~= nil and val ~= nil then out[math.floor(ty)] = (out[math.floor(ty)] or 0) + val end
	end
	return out
end
local function attr_add(dst, src) for ty, val in pairs(src or {}) do dst[ty] = (dst[ty] or 0) + val end end
local function fnum(x)
	x = tonumber(x) or 0
	if x == math.floor(x) and math.abs(x) < 1e15 then return fint(x) end
	local s = string.format("%.6f", x)
	s = string.gsub(s, "0+$", "")
	s = string.gsub(s, "%.$", "")
	return s
end
local function attr_text(a)
	local keys = {}
	for ty, val in pairs(a or {}) do if math.abs(val) > 1e-12 then keys[#keys + 1] = ty end end
	table.sort(keys)
	local out = {}
	for _, ty in ipairs(keys) do out[#out + 1] = fint(ty) .. "," .. fnum(a[ty]) end
	return table.concat(out, "|")
end

local function full_on() return type(S.cfg) == "table" and S.cfg.ic_full == true end
local function auto_on() return not (type(S.cfg) == "table" and S.cfg.ic_auto == false) end
local function stats_on()
	if type(S.cfg) == "table" and (S.cfg.ic_stats == false or S.cfg.tl_stats == false) then return false end
	return true
end

function IC.T()
	local T = R.ic_t
	if T ~= nil then return T end
	T = { ok = false, cards = {}, ids = {}, levels = {}, ach = {}, props = {} }
	R.ic_t = T
	local mt, ut, at = dtab("card_mould"), dtab("card_unblock"), dtab("card_achieve")
	if mt == nil or ut == nil then return T end
	local MC = { id = schema("ship_illustration_card_mould", "id", 1), ship = schema("ship_illustration_card_mould", "ship_id", 2),
		grp = schema("ship_illustration_card_mould", "ship_group", 3), sp = schema("ship_illustration_card_mould", "special_condition", 4) }
	for _, row in pairs(mt) do
		local r = cells(row)
		local id = r ~= nil and tonumber(r[MC.id]) or nil
		if id ~= nil and id > 0 then
			id = math.floor(id)
			local group = {}
			for _, v in ipairs(ints(r[MC.grp])) do if v > 0 then group[#group + 1] = v end end
			local special = {}
			for _, v in ipairs(ints(r[MC.sp])) do if v > 0 then special[#special + 1] = v end end
			local ship = math.floor(tonumber(r[MC.ship]) or -1)
			T.cards[id] = { id = id, ship = ship, combo = (#group > 0), group = group, special = special }
			T.ids[#T.ids + 1] = id
		end
	end
	table.sort(T.ids)
	local UC = { id = schema("ship_illustration_consume_mould", "id", 1), ab = schema("ship_illustration_consume_mould", "ability", 2),
		lv = schema("ship_illustration_consume_mould", "level", 3), cost = schema("ship_illustration_consume_mould", "consume", 4),
		mark = schema("ship_illustration_consume_mould", "mark", 6), add = schema("ship_illustration_consume_mould", "property_add", 8) }
	for _, row in pairs(ut) do
		local r = cells(row)
		local ab, lv = r ~= nil and tonumber(r[UC.ab]) or nil, r ~= nil and tonumber(r[UC.lv]) or nil
		if ab ~= nil and lv ~= nil and lv >= 0 then
			ab, lv = math.floor(ab), math.floor(lv)
			local g = T.levels[ab]
			if g == nil then g = { max = 0, rows = {} }; T.levels[ab] = g end
			local x = { lv = lv, score = tonumber(r[UC.mark]) or 0, cost = triples(r[UC.cost]), add = attrs(r[UC.add]) }
			g.rows[lv] = x
			if lv > g.max then g.max = lv end
			for _, c in ipairs(x.cost) do if c[1] == 6 then T.props[c[2]] = true end end
		end
	end
	if at ~= nil then
		local AC = { score = schema("ship_illustration_achieve_mould", "condition", 2), add = schema("ship_illustration_achieve_mould", "property_add", 3) }
		for _, row in pairs(at) do
			local r = cells(row)
			local score = r ~= nil and tonumber(r[AC.score]) or nil
			if score ~= nil then T.ach[#T.ach + 1] = { score = score, add = attrs(r[AC.add]) } end
		end
		table.sort(T.ach, function(a, b) return a.score < b.score end)
	end
	T.ok = #T.ids > 0 and next(T.levels) ~= nil
	return T
end

local function group_of(card)
	if card.combo or card.ship == -1 then return card.id end
	return math.max(15, math.floor(mnum(card.ship, "ability", 15) or 15))
end
local function levels_of(card) return IC.T().levels[group_of(card)] end
local function row_of(card, lv)
	local g = levels_of(card)
	return g ~= nil and g.rows[lv] or nil
end
local function max_level(card)
	local g = levels_of(card)
	return g ~= nil and g.max or 0
end

local function st()
	local a = S.ic
	if type(a) ~= "table" then a = { v = 1, c = {} }; S.ic = a; mark() end
	if type(a.c) ~= "table" then a.c = {} end
	for k, x in pairs(a.c) do
		if type(x) ~= "table" or tonumber(k) == nil then a.c[k] = nil
		else x.l = math.max(0, math.floor(tonumber(x.l) or 0)) end
	end
	return a
end

local function card_state(id)
	local x = st().c[tostring(id)]
	if type(x) ~= "table" then return nil end
	return x
end

local function hero_star(e, tid)
	local star, have = 0, false
	for _, sh in pairs(e.user_ship or {}) do
		if type(sh) == "table" and tonumber(sh.ship_template_id) == tid then
			have = true
			star = math.max(star, math.floor(tonumber(sh.StarRating) or 1))
		end
	end
	return have, star
end

local function combo_ready(card)
	local T = IC.T()
	for _, tid in ipairs(card.group) do
		local found = false
		for _, id in ipairs(T.ids) do
			local c = T.cards[id]
			if not c.combo and c.ship == tid then
				local x = card_state(id)
				if x ~= nil and x.l >= 7 then found = true; break end
			end
		end
		if not found then return false end
	end
	return true
end

local function make_full(a)
	local T = IC.T()
	local changed = false
	if not a.full then

		local m = {}
		for k, x in pairs(a.c) do if type(x) == "table" then m[k] = { l = math.floor(tonumber(x.l) or 0) } end end
		a.manual, a.full, a.mig16 = m, true, true
		changed = true
	end
	for _, id in ipairs(T.ids) do
		local card = T.cards[id]
		local mx = max_level(card)
		if levels_of(card) ~= nil then
			local k = tostring(id)
			local x = a.c[k]
			if x == nil then a.c[k] = { l = mx }; changed = true
			elseif x.l < mx then x.l = mx; changed = true end
		end
	end
	return changed
end

local function all_max(a)
	local T = IC.T()
	local n = 0
	for _, id in ipairs(T.ids) do
		local card = T.cards[id]
		if levels_of(card) ~= nil then
			local x = a.c[tostring(id)]
			if type(x) ~= "table" or x.l < max_level(card) then return false end
			n = n + 1
		end
	end
	return n > 0
end

local function unfull(a)
	if a.mig16 == nil then
		a.mig16 = true
		mark()

		if a.full == nil and all_max(a) and not (type(S.cfg) == "table" and S.cfg.ic_full == false) then
			a.full, a.manual = true, {}
			log("Deck: bo Deck FULL cua ban truoc -> ve chua kich hoat de tu nang")
		end
	end
	if not a.full then return false end
	local m, n = a.manual, 0
	a.c = {}
	if type(m) == "table" then
		for k, x in pairs(m) do
			if type(x) == "table" and tonumber(k) ~= nil then a.c[k] = { l = math.max(0, math.floor(tonumber(x.l) or 0)) }; n = n + 1 end
		end
	end
	a.manual, a.full = nil, nil
	R.ic_last = "tat full: tra Deck ve tien trinh tu nang (" .. n .. " the)"
	mark()
	return true
end

function IC.totals()
	local T = IC.T()
	local score, normal = 0, {}
	for _, id in ipairs(T.ids) do
		local card, x = T.cards[id], card_state(id)
		if card ~= nil and x ~= nil then
			local row = row_of(card, x.l)
			if row ~= nil then score = score + row.score; attr_add(normal, row.add) end
		end
	end
	local achieve = {}
	for _, a in ipairs(T.ach) do
		if score >= a.score then attr_add(achieve, a.add) else break end
	end
	return score, normal, achieve
end

local function entries()
	local T = IC.T()
	local out = {}
	for _, id in ipairs(T.ids) do
		local card, x = T.cards[id], card_state(id)
		if card ~= nil and x ~= nil then
			local row = row_of(card, x.l)
			out[#out + 1] = { id = id, lv = x.l, score = row ~= nil and row.score or 0, ship = card.ship }
		end
	end
	return out
end

local function cards_block(code)
	local score, normal, achieve = IC.totals()
	local list = entries()
	local b = { code, fnum(score), attr_text(achieve), attr_text(normal), fint(#list) }
	for _, x in ipairs(list) do
		b[#b + 1] = fint(x.id)
		b[#b + 1] = fint(x.lv)
		b[#b + 1] = fint(x.id)
		b[#b + 1] = fnum(x.score)
		b[#b + 1] = fint(x.ship)
	end
	return table.concat(b, "\r\n")
end

local function comb_list()
	local T = IC.T()
	local out = {}
	for _, id in ipairs(T.ids) do
		local c = T.cards[id]
		if c.combo then
			local o = { cardMouldId = id }
			for i = 1, math.max(1, #c.special) do o["condition" .. (i - 1)] = { status = true, currentProcess = 999 } end
			out[#out + 1] = o
		end
	end
	return out
end

local function comb_block()
	local parts = {}
	for _, o in ipairs(comb_list()) do
		local p = { '"cardMouldId":' .. fint(o.cardMouldId) }
		local i = 0
		while o["condition" .. i] ~= nil do
			p[#p + 1] = '"condition' .. i .. '":{"status":true,"currentProcess":999}'
			i = i + 1
		end
		parts[#parts + 1] = "{" .. table.concat(p, ",") .. "}"
	end
	return "12666\r\n[" .. table.concat(parts, ",") .. "]"
end

function IC.publish(e)
	local score, normal, achieve = IC.totals()
	local list = {}
	for i, x in ipairs(entries()) do
		list[i] = { id = x.id, cardStar = x.lv, cardMouldId = x.id, cardScore = x.score, shipMouldId = x.ship }
	end
	local info = { totalScore = score, achieveAdditionProperty = attr_text(achieve), normalAdditionProperty = attr_text(normal) }
	if #list > 0 then info.userCardInfoList = list end
	e.illustration_info_init = info
	e.illustration_comb_card_info = comb_list()
	R.ic_pub = (R.ic_pub or 0) + 1
end

function IC.active()
	if not stats_on() then return false end
	local a = S ~= nil and S.ic or nil
	return type(a) == "table" and type(a.c) == "table" and next(a.c) ~= nil
end
function IC.any(sid) return IC.active() end

function IC.adjust(sid, tid, pn, spec, is_rec)
	if not IC.active() or type(pn) ~= "table" then return end
	local ok, err = pcall(function()
		local tot = R.ic_tot
		if tot == nil then
			local _, normal, achieve = IC.totals()
			tot = {}
			attr_add(tot, normal)
			attr_add(tot, achieve)
			R.ic_tot = tot
		end
		for ty = 0, 2 do
			local add = tot[ty] or 0
			if add ~= 0 and type(pn[ty + 1]) == "number" then pn[ty + 1] = math.max(0, rnd(pn[ty + 1] + add)) end
		end
		if type(spec) == "table" then
			for _, ty in ipairs({ 33, 34 }) do
				local v = tot[ty] or 0
				if v ~= 0 then spec[ty] = (spec[ty] or 0) + v * 100 end
			end
		end
	end)
	if not ok then
		R.ic_errs = (R.ic_errs or 0) + 1
		if R.ic_errs <= 5 then log("loi chi so Deck:", tostring(err)) end
	end
end

-- [BOT FULL IC] Tong chi so Deck khi TAT CA the max cap. Bot dung cai nay thay vi tien trinh Deck cua nguoi choi
-- (bot tu max san, khong phu thuoc ban nang gi). Tinh tren bang tam, khong dong vao S.ic that.
function IC.bot_tot()
	local tot = R.ic_bot_tot
	if tot ~= nil then return tot end
	tot = {}
	if not IC.T().ok then return tot end
	local save = S.ic
	local ok, err = pcall(function()
		local a = { v = 1, c = {} }
		S.ic = a
		make_full(a)
		local _, normal, achieve = IC.totals()
		attr_add(tot, normal)
		attr_add(tot, achieve)
	end)
	S.ic = save
	if not ok then log("loi Deck full cho bot:", tostring(err)); return {} end
	R.ic_bot_tot = tot
	return tot
end

local function floor_props()
	if not auto_on() then return end
	for id in pairs(IC.T().props) do
		if LS.prop_get(id) < FLOOR_LOW then LS.prop_set(id, FLOOR_TOP) end
	end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_ship) ~= "table" then error("chua co the gioi") end
	if not IC.T().ok then error("khong co bang Deck / Card Album") end
	local a = st()
	local changed
	if full_on() then changed = make_full(a) else changed = unfull(a) end
	if changed then mark(); R.ic_tot = nil end
	floor_props()
	return e, a
end

local function finish(e, seq, name, code)
	R.ic_tot = nil
	IC.publish(e)
	local blocks = { cards_block(code), comb_block() }
	if LS._tl ~= nil and LS._tl.refresh_blocks ~= nil then
		LS._tl.refresh_blocks(e, blocks)
		LS._tl.queue_all(e)
		R.tl_sig_l, R.tl_sig_f = nil, nil
	end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

function IC.h_init(p, seq)
	local e = ctx()
	stat_inc("ic_init")
	IC.publish(e)
	return reply(seq, "user_card_info_init", { cards_block("12662"), comb_block() })
end

function IC.h_activate(p, seq)
	local name = "user_card_info_activate"
	local e, a = ctx()
	local id = math.floor(tn(p[1], -1))
	local card = IC.T().cards[id]
	if card == nil or levels_of(card) == nil then return err_reply(seq, name, "LS_the_khong_ton_tai", ERR.generic) end
	if card_state(id) ~= nil then return err_reply(seq, name, "LS_the_da_kich_hoat", ERR.generic) end
	if card.combo then
		if not combo_ready(card) then return err_reply(seq, name, "LS_chua_du_dieu_kien_the_to_hop", ERR.generic) end
	else
		if not hero_star(e, card.ship) then return err_reply(seq, name, "LS_chua_co_tuong_de_kich_hoat", ERR.generic) end
	end
	a.c[tostring(id)] = { l = 0 }
	R.ic_last = "kich hoat the " .. id
	stat_inc("ic_activate")
	return finish(e, seq, name, "12663")
end

function IC.h_advance(p, seq)
	local name = "user_card_info_advance"
	local e, a = ctx()
	local id = math.floor(tn(p[1], -1))
	local card, x = IC.T().cards[id], card_state(id)
	if card == nil or x == nil then return err_reply(seq, name, "LS_the_chua_kich_hoat", ERR.generic) end
	local nxt = row_of(card, x.l + 1)
	if nxt == nil then return err_reply(seq, name, "LS_the_da_toi_da", ERR.level_cap) end
	if not card.combo then
		local _, star = hero_star(e, card.ship)
		if nxt.lv > star then return err_reply(seq, name, "LS_tuong_chua_du_sao", ERR.star) end
	end
	local props = {}
	for _, c in ipairs(nxt.cost) do if c[1] == 6 and c[3] > 0 then props[#props + 1] = { c[2], c[3] } end end
	local silver = 0
	for _, c in ipairs(nxt.cost) do if c[1] == 1 and c[3] > 0 then silver = silver + c[3] end end
	if silver > 0 and (S.silver or 0) < silver then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
	if #props > 0 and not LS.prop_spend_all(props) then return err_reply(seq, name, "LS_khong_du_nguyen_lieu", ERR.items) end
	if silver > 0 then LS.money_spend("silver", silver) end
	x.l = nxt.lv
	R.ic_last = "nang the " .. id .. " len cap " .. x.l
	stat_inc("ic_advance")
	return finish(e, seq, name, "12664")
end

function IC.h_rank(p, seq)
	ctx()
	local score = IC.totals()
	local body = '{"rankSize":0,"rankInfo":[],"myRank":1,"myRankInfo":{"score":' .. fnum(score) .. '}}'
	return reply(seq, "user_card_info_rank", { "12665\r\n" .. body })
end

function IC.on_world(e)
	R.ic_t, R.ic_tot = nil, nil
	R.ic_n = 0
	if S ~= nil and S.ic ~= nil and type(S.ic) ~= "table" then S.ic = nil end
end

function IC.tick(e)
	if S == nil or not R.ready then return end
	if not IC.T().ok then return end
	R.ic_n = (R.ic_n or 0) + 1
	local son = stats_on()
	local toggled = (R.ic_stats_prev ~= nil and R.ic_stats_prev ~= son)
	R.ic_stats_prev = son
	if R.ic_n % 20 ~= 1 and not toggled and not R.ic_now then return end
	R.ic_now = nil
	local a = st()
	local changed
	if full_on() then changed = make_full(a) else changed = unfull(a) end
	if changed then mark(); R.ic_tot = nil end
	if changed or R.ic_n == 1 or e.illustration_info_init == nil or e.illustration_comb_card_info == nil then IC.publish(e) end

	if (changed or toggled) and LS._tl ~= nil and LS._tl.queue_all ~= nil then pcall(LS._tl.queue_all, e) end
end

function IC.apply_now(e)
	R.ic_now = true
	if e ~= nil then IC.tick(e) end
end
IC.full_on = full_on

function IC.dump_line()
	local a = S ~= nil and S.ic or nil
	if type(a) ~= "table" or type(a.c) ~= "table" then return "[LS Deck] chua khoi tao" end
	local n, lv, combo = 0, 0, 0
	for key, x in pairs(a.c) do
		if type(x) == "table" then
			n = n + 1; lv = lv + math.floor(tonumber(x.l) or 0)
			local c = IC.T().cards[tonumber(key) or -1]
			if c ~= nil and c.combo then combo = combo + 1 end
		end
	end
	local score = IC.totals()
	return "[LS Deck] " .. n .. " the da kich hoat (to hop " .. combo .. ") | tong cap " .. lv .. " | diem " .. fnum(score)
		.. " | full " .. (full_on() and "BAT" or "TAT") .. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.ic_last and (" | cuoi: " .. R.ic_last) or "") .. ((R.ic_errs or 0) > 0 and (" | loi " .. R.ic_errs) or "")
end

function IC.reset(e)
	S.ic = nil
	R.ic_tot = nil
	if type(e) == "table" then e.illustration_info_init, e.illustration_comb_card_info = nil, nil end
	mark()
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if IC.active() then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

if LS._lv ~= nil and LS._lv.add_ids ~= nil then LS._lv.add_ids({ 194 }) end

LS._ic = IC
end
init_ic()
end

do
local function init_cs()

local CS = {}

local function split_tab(s)
	local t, pos = {}, 1
	while true do
		local p = string.find(s, "\t", pos, true)
		if p == nil then t[#t + 1] = string.sub(s, pos); break end
		t[#t + 1] = string.sub(s, pos, p - 1)
		pos = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function nums(s)
	local out = {}
	for n in string.gmatch(tostring(s or ""), "%-?%d+") do
		local v = tonumber(n)
		if v ~= nil then out[#out + 1] = math.floor(v) end
	end
	return out
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do
		out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) }
	end
	return out
end

local function attrs(s)
	local out = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do
		local ty, val = tonumber(a), tonumber(b)
		if ty ~= nil and val ~= nil then out[math.floor(ty)] = (out[math.floor(ty)] or 0) + val end
	end
	return out
end

function CS.T()
	local T = R.cs_t
	if T ~= nil then return T end
	T = { ok = false, cards = {}, ids = {}, groups = {}, by_group = {} }
	R.cs_t = T
	local mt, gt = dtab("constellation_mould"), dtab("constellation_group")
	if mt == nil or gt == nil then return T end
	local MC = { id = schema("constellation_mould", "id", 1), open = schema("constellation_mould", "constellation_open_level", 3),
		typ = schema("constellation_mould", "constellation_ship_type", 4), ships = schema("constellation_mould", "constellation_ship_id", 5),
		groups = schema("constellation_mould", "constellation_group_id", 6) }
	for _, row in pairs(mt) do
		local r = cells(row)
		if r ~= nil then
			local id = tonumber(r[MC.id])
			if id ~= nil and id > 0 then
				id = math.floor(id)
				T.cards[id] = { id = id, open = math.floor(tonumber(r[MC.open]) or 1), typ = math.floor(tonumber(r[MC.typ]) or 0),
					ships = nums(r[MC.ships]), gids = nums(r[MC.groups]) }
				T.ids[#T.ids + 1] = id
			end
		end
	end
	table.sort(T.ids)
	local GC = { id = schema("constellation_group", "id", 1), group = schema("constellation_group", "group_id", 2),
		quality = schema("constellation_group", "level_id", 3), level_type = schema("constellation_group", "level_type", 4),
		lock = schema("constellation_group", "lock", 5), buy = schema("constellation_group", "buy_param", 6),
		add = schema("constellation_group", "add_additional", 7), value = schema("constellation_group", "protect_num", 8) }
	for _, row in pairs(gt) do
		local r = cells(row)
		if r ~= nil then
			local id, group = tonumber(r[GC.id]), tonumber(r[GC.group])
			if id ~= nil and group ~= nil and id > 0 then
				id, group = math.floor(id), math.floor(group)
				local x = { id = id, group = group, quality = math.floor(tonumber(r[GC.quality]) or 1),
					level_type = math.floor(tonumber(r[GC.level_type]) or 1), lock = math.floor(tonumber(r[GC.lock]) or 0),
					cost = triples(r[GC.buy]), add = attrs(r[GC.add]), value = tonumber(r[GC.value]) or 0 }
				T.groups[id] = x
				local a = T.by_group[group]
				if a == nil then a = {}; T.by_group[group] = a end
				a[#a + 1] = id
			end
		end
	end
	for _, a in pairs(T.by_group) do table.sort(a) end
	T.ok = #T.ids > 0 and next(T.groups) ~= nil
	return T
end

local function copy_groups(dst, src)
	if type(src) ~= "table" then return end
	for ck, slots in pairs(src) do
		local cid = tonumber(ck)
		if cid ~= nil and CS.T().cards[math.floor(cid)] ~= nil and type(slots) == "table" then
			local dslots = {}
			dst[tostring(math.floor(cid))] = dslots
			for sk, list in pairs(slots) do
				local slot = tonumber(sk)
				if slot ~= nil and slot >= 0 and slot <= 4 and type(list) == "table" then
					local dl, seen = {}, {}
					for _, gid in pairs(list) do
						gid = tonumber(gid)
						if gid ~= nil and CS.T().groups[math.floor(gid)] ~= nil and not seen[math.floor(gid)] then
							seen[math.floor(gid)] = true; dl[#dl + 1] = math.floor(gid)
						end
					end
					dslots[tostring(math.floor(slot))] = dl
				end
			end
		end
	end
end

local function st(e)
	local a = S.cs
	if type(a) ~= "table" then a = { v = 1, hba = {}, uc = {} }; S.cs = a end
	if type(a.hba) ~= "table" then a.hba = {} end
	if type(a.uc) ~= "table" then a.uc = {} end

	if a.seeded ~= true then
		local old = e ~= nil and e.constellation_info or nil
		if type(old) == "table" then
			copy_groups(a.hba, old.hba)
			if type(old.uc) == "table" then
				for ck, slots in pairs(old.uc) do
					local cid = tonumber(ck)
					if cid ~= nil and CS.T().cards[math.floor(cid)] ~= nil and type(slots) == "table" then
						local d = {}; a.uc[tostring(math.floor(cid))] = d
						for sk, gid in pairs(slots) do
							local slot, n = tonumber(sk), tonumber(gid)
							if slot ~= nil and n ~= nil and CS.T().groups[math.floor(n)] ~= nil then d[tostring(math.floor(slot))] = math.floor(n) end
						end
					end
				end
			end
		end
		a.seeded = true
	end
	return a
end

local function list_at(a, cid, slot, make)
	local c = a.hba[tostring(cid)]
	if c == nil and make then c = {}; a.hba[tostring(cid)] = c end
	if c == nil then return nil end
	local x = c[tostring(slot)]
	if x == nil and make then x = {}; c[tostring(slot)] = x end
	return x
end

local function contains(list, gid)
	for _, x in pairs(list or {}) do if tonumber(x) == gid then return true end end
	return false
end

local function ctv(a)
	local n = 0
	for _, slots in pairs(a.hba or {}) do
		if type(slots) == "table" then
			for _, list in pairs(slots) do
				if type(list) == "table" then
					for _, gid in pairs(list) do local g = CS.T().groups[tonumber(gid) or -1]; if g ~= nil then n = n + g.value end end
				end
			end
		end
	end
	return math.floor(n)
end

local function info_json(a)
	local hparts, uparts = {}, {}
	for _, cid in ipairs(CS.T().ids) do
		local slots = a.hba[tostring(cid)]
		if type(slots) == "table" then
			local ss = {}
			for i = 0, 4 do
				local list = slots[tostring(i)]
				local x = {}
				if type(list) == "table" then for _, gid in ipairs(list) do x[#x + 1] = fint(gid) end end

				ss[#ss + 1] = '"' .. fint(i) .. '":[' .. table.concat(x, ",") .. ']'
			end
			hparts[#hparts + 1] = '"' .. fint(cid) .. '":{' .. table.concat(ss, ",") .. '}'
		end
		local used = a.uc[tostring(cid)]
		if type(used) == "table" then
			local ss = {}
			for i = 0, 4 do if tonumber(used[tostring(i)]) ~= nil then ss[#ss + 1] = '"' .. fint(i) .. '":' .. fint(used[tostring(i)]) end end
			if #ss > 0 then uparts[#uparts + 1] = '"' .. fint(cid) .. '":{' .. table.concat(ss, ",") .. '}' end
		end
	end
	return '{"hba":{' .. table.concat(hparts, ",") .. '},"uc":{' .. table.concat(uparts, ",") .. '},"ctv":' .. fint(ctv(a)) .. '}'
end

local function push_ed(e)
	if e == nil then return end
	local a = st(e)
	e.constellation_info = { hba = a.hba, uc = a.uc, ctv = ctv(a) }
	local red = G("constellationRedotData")
	if type(red) == "function" then pcall(red) end
end

local function pct_cfg(id, index)
	local d, pc = G("dms"), G("play_config")
	if type(d) ~= "table" or type(pc) ~= "table" then return 0 end
	local text = nil
	pcall(function() text = d.string(d["play_config"], id, pc.param) end)
	for pair in string.gmatch(tostring(text or ""), "[^|]+") do
		local a, b = string.match(pair, "^%s*(%-?%d+)%s*,%s*(%-?[%d%.]+)%s*$")
		if tonumber(a) == index then return tonumber(b) or 0 end
	end
	return 0
end

local function hero_of_template(e, tid)
	if type(e) ~= "table" or type(e.user_ship) ~= "table" then return nil end
	for _, sh in pairs(e.user_ship) do if type(sh) == "table" and tonumber(sh.ship_template_id) == tid then return sh end end
	return nil
end

local function totals(e)
	local a, out = st(e), {}
	for ck, slots in pairs(a.uc or {}) do
		local cid = tonumber(ck)
		local card = cid ~= nil and CS.T().cards[math.floor(cid)] or nil
		if card ~= nil and type(slots) == "table" then
			for sk, gid in pairs(slots) do
				local slot, g = tonumber(sk), CS.T().groups[tonumber(gid) or -1]
				if slot ~= nil and g ~= nil then
					local owned = list_at(a, card.id, math.floor(slot), false) or {}
					local sh = hero_of_template(e, card.ships[math.floor(slot) + 1])
					local star = sh ~= nil and math.floor(tonumber(sh.StarRating) or 1) or 1
					local order = sh ~= nil and math.floor(tonumber(sh.Order) or 0) or 0
					local multi = 1 + (pct_cfg(81, star) + pct_cfg(82, order + 1) + pct_cfg(83, #owned)) / 100
					for ty, val in pairs(g.add) do out[ty] = (out[ty] or 0) + val * multi end
				end
			end
		end
	end
	return out
end

local function active()
	local a = S ~= nil and S.cs or nil
	return type(a) == "table" and type(a.uc) == "table" and next(a.uc) ~= nil
end

local function full_on() return type(S.cfg) == "table" and S.cfg.cs_full == true end
local function stats_on() return not (type(S.cfg) == "table" and S.cfg.cs_stats == false) end

function CS.adjust(sid, tid, pn, spec, is_rec)
	if not stats_on() or not active() or type(pn) ~= "table" then return end
	local add = totals(ED())
	for ty = 0, 2 do
		local v = add[ty] or 0
		if v ~= 0 and type(pn[ty + 1]) == "number" then pn[ty + 1] = math.max(0, rnd(pn[ty + 1] + v)) end
	end
end

local function refresh(e)
	for sid in pairs(e.user_ship or {}) do
		pcall(function() local f = commit_hero(e, tostring(sid), {}); if f ~= nil then apply_hero(e, tostring(sid)) end end)
	end
	fight_assert(e)
end

local function copy_used(dst, src)
	if type(src) ~= "table" then return end
	local T = CS.T()
	for ck, slots in pairs(src) do
		local cid = tonumber(ck)
		local card = cid ~= nil and T.cards[math.floor(cid)] or nil
		if card ~= nil and type(slots) == "table" then
			local d = {}
			for sk, gid in pairs(slots) do
				local slot, n = tonumber(sk), tonumber(gid)
				local g = n ~= nil and T.groups[math.floor(n)] or nil
				if slot ~= nil and slot >= 0 and slot <= 4 and g ~= nil and card.gids[math.floor(slot) + 1] == g.group then
					d[tostring(math.floor(slot))] = math.floor(n)
				end
			end
			if next(d) ~= nil then dst[tostring(math.floor(cid))] = d end
		end
	end
end

local function copy_state(a)
	local out = { hba = {}, uc = {} }
	copy_groups(out.hba, a.hba)
	copy_used(out.uc, a.uc)
	return out
end

local function best_group(group)
	local best, T = nil, CS.T()
	for _, gid in ipairs(T.by_group[group] or {}) do
		local g = T.groups[gid]
		if g ~= nil and (best == nil or g.quality > best.quality or (g.quality == best.quality and (g.value > best.value or (g.value == best.value and g.id > best.id)))) then best = g end
	end
	return best ~= nil and best.id or nil
end

local function make_full(a)
	local T, changed = CS.T(), false
	if not a.full then
		a.manual, a.full = copy_state(a), true
		changed = true
	end
	for _, cid in ipairs(T.ids) do
		local card = T.cards[cid]
		local used = a.uc[tostring(cid)]
		if type(used) ~= "table" then used = {}; a.uc[tostring(cid)] = used; changed = true end
		for slot = 0, 4 do
			local group = card.gids[slot + 1]
			local want = group ~= nil and T.by_group[group] or nil
			if type(want) == "table" and #want > 0 then
				-- [FIX lag 12 Universe] truoc day moi lan tick deu gan lai TOAN BO
				-- danh sach bao ho => changed luon = true => push_ed() + refresh()
				-- (tinh lai toan bo tuong) chay mai moi 15 nhip => lag nang.
				-- Chi ghi khi THUC SU khac; so sanh bang so sanh chuoi thay vi vong lap.
				local list = list_at(a, cid, slot, true)
				local ok_same = (#list == #want)
				if ok_same then
					for i = 1, #want do
						if list[i] ~= want[i] then ok_same = false; break end
					end
				end
				if not ok_same then
					for k = #list, 1, -1 do list[k] = nil end
					for i, gid in ipairs(want) do list[i] = gid end
					changed = true
				end
				local gid = best_group(group)
				if used[tostring(slot)] ~= gid then used[tostring(slot)] = gid; changed = true end
			end
		end
	end
	return changed
end

local function unfull(a)
	if not a.full then return false end
	local m = a.manual
	a.hba, a.uc = {}, {}
	if type(m) == "table" then
		copy_groups(a.hba, m.hba)
		copy_used(a.uc, m.uc)
	end
	a.manual, a.full = nil, nil
	R.cs_last = "tat full: tra 12 Universe ve tien trinh tu nang"
	return true
end

-- [BOT FULL CS] Tong chi so Constellation khi MOI o dung nhom tot nhat + he so sao/bac toi da. Bang tam, khong dong vao S.cs that.
function CS.bot_tot()
	local out = R.cs_bot_tot
	if out ~= nil then return out end
	out = {}
	local ok, err = pcall(function()
		local T = CS.T()
		local a = { v = 1, hba = {}, uc = {}, seeded = true }
		make_full(a)
		local function maxcfg(id)
			local m = 0
			for i = 0, 40 do
				local v = pct_cfg(id, i)
				if v > m then m = v end
			end
			return m
		end
		local m81, m82 = maxcfg(81), maxcfg(82)
		for ck, slots in pairs(a.uc) do
			local cid = tonumber(ck)
			local card = cid ~= nil and T.cards[math.floor(cid)] or nil
			if card ~= nil and type(slots) == "table" then
				for sk, gid in pairs(slots) do
					local slot, g = tonumber(sk), T.groups[tonumber(gid) or -1]
					if slot ~= nil and g ~= nil then
						local owned = list_at(a, card.id, math.floor(slot), false) or {}
						local multi = 1 + (m81 + m82 + pct_cfg(83, #owned)) / 100
						for ty, val in pairs(g.add) do out[ty] = (out[ty] or 0) + val * multi end
					end
				end
			end
		end
	end)
	if not ok then log("loi Constellation full cho bot:", tostring(err)); return {} end
	R.cs_bot_tot = out
	return out
end

function CS.tick(e)
	if S == nil or not R.ready or not CS.T().ok then return end
	local old = S.cs
	if not full_on() and (type(old) ~= "table" or not old.full) then return end
	R.cs_n = (R.cs_n or 0) + 1
	-- [FIX lag 12 Universe] Khi FULL da ap xong va khong co yeu cau apply_now,
	-- khong can quet lai toan bo card/slot moi 15 nhip: du lieu do make_full()
	-- ghi la ket qua tat dinh tu bang config, khong the "troi" theo thoi gian.
	-- Chi con viec dong bo lai khi nguoi choi doi (mua/doi bao ho => apply_now).
	if R.cs_settled and not R.cs_now then return end
	if R.cs_n % 15 ~= 1 and not R.cs_now then return end
	R.cs_now = nil
	local a = st(e)
	-- KHONG dung "full_on() and make_full(a) or unfull(a)": khi FULL da bat san, make_full tra false
	-- (khong co gi doi) nen bieu thuc and/or roi xuong unfull() va TAT FULL; 15 nhip sau lai bat lai
	-- -> chi so tuong nhay tang roi giam lien tuc. Phai dung if/else.
	local changed
	if full_on() then changed = make_full(a) else changed = unfull(a) end
	if not changed then
		if full_on() then R.cs_settled = true end
		return
	end
	R.cs_settled = full_on() or nil
	push_ed(e)
	refresh(e)
	if LS._tl ~= nil and LS._tl.queue_all ~= nil then pcall(LS._tl.queue_all, e); R.tl_sig_l, R.tl_sig_f = nil, nil end
	mark()
end

function CS.apply_now(e)
	-- [FIX lag 12 Universe] doi trang thai FULL / doi bao ho => phai quet lai
	R.cs_settled = nil
	R.cs_now = true
	if e ~= nil then CS.tick(e) end
end
CS.full_on = full_on

local function pay(cost)
	for _, x in ipairs(cost or {}) do
		if x[1] == 1 then LS.money_spend("silver", x[3])
		elseif x[1] == 2 then LS.money_spend("gold", x[3])
		elseif x[1] == 6 then LS.prop_add(x[2], -x[3]) end
	end
end

local function can_pay(cost)
	for _, x in ipairs(cost or {}) do
		if x[1] == 1 and (S.silver or 0) < x[3] then return false, ERR.silver end
		if x[1] == 2 and (S.gold or 0) < x[3] then return false, ERR.items end
		if x[1] == 6 and LS.prop_get(x[2]) < x[3] then return false, ERR.items end
	end
	return true
end

local function delta_block(code, cid, slot, list, used, a)
	local xs = {}; for _, gid in ipairs(list or {}) do xs[#xs + 1] = fint(gid) end
	return code .. "\r\n" .. string.format('{"ccid":%s,"cmIndex":%s,"cmList":[%s],"cugid":%s,"ctv":%s}', fint(cid), fint(slot), table.concat(xs, ","), fint(used), fint(ctv(a)))
end

function CS.h_buy(p, seq)
	local e = ED(); if e == nil or type(e.user_ship) ~= "table" then return err_reply(seq, "constellation_buy", "LS_chua_co_the_gioi", ERR.generic) end
	if not CS.T().ok then return err_reply(seq, "constellation_buy", "LS_khong_co_bang_12_universe", ERR.generic) end
	local cid, slot, gid = math.floor(tn(p[1], -1)), math.floor(tn(p[2], -1)), math.floor(tn(p[3], -1))
	local card, g = CS.T().cards[cid], CS.T().groups[gid]
	if card == nil or g == nil or slot < 0 or slot > 4 or card.gids[slot + 1] ~= g.group then return err_reply(seq, "constellation_buy", "LS_du_lieu_vu_tru_khong_hop_le", ERR.generic) end
	if math.floor(tonumber(e.user_info and e.user_info.user_grade) or 0) < card.open then return err_reply(seq, "constellation_buy", "LS_chua_du_cap_mo_vu_tru", ERR.level_cap) end
	if g.lock == 1 and hero_of_template(e, card.ships[slot + 1]) == nil then return err_reply(seq, "constellation_buy", "LS_chua_co_tuong_de_kich_hoat", ERR.generic) end
	local a, list = st(e), list_at(st(e), cid, slot, true)
	if contains(list, gid) then return err_reply(seq, "constellation_buy", "LS_bao_ho_da_mua", ERR.generic) end
	local ok, code = can_pay(g.cost); if not ok then return err_reply(seq, "constellation_buy", "LS_khong_du_nguyen_lieu", code) end
	pay(g.cost); list[#list + 1] = gid
	local used = a.uc[tostring(cid)] or {}; a.uc[tostring(cid)] = used; used[tostring(slot)] = gid
	push_ed(e); refresh(e); mark(); LS.save_state(true); stat_inc("cs_buy")
	return reply(seq, "constellation_buy", { delta_block("12567", cid, slot, list, gid, a), "12566\r\n" .. info_json(a) })
end

function CS.h_exchange(p, seq)
	local e = ED(); if e == nil or type(e.user_ship) ~= "table" then return err_reply(seq, "constellation_exchange", "LS_chua_co_the_gioi", ERR.generic) end
	local cid, slot, gid = math.floor(tn(p[1], -1)), math.floor(tn(p[2], -1)), math.floor(tn(p[3], -1))
	local card, g = CS.T().cards[cid], CS.T().groups[gid]
	if card == nil or g == nil or slot < 0 or slot > 4 or card.gids[slot + 1] ~= g.group then return err_reply(seq, "constellation_exchange", "LS_du_lieu_vu_tru_khong_hop_le", ERR.generic) end
	local a, list = st(e), list_at(st(e), cid, slot, false)
	if not contains(list, gid) then return err_reply(seq, "constellation_exchange", "LS_bao_ho_chua_mua", ERR.generic) end
	local used = a.uc[tostring(cid)] or {}; a.uc[tostring(cid)] = used; used[tostring(slot)] = gid
	push_ed(e); refresh(e); mark(); LS.save_state(true); stat_inc("cs_exchange")
	return reply(seq, "constellation_exchange", { delta_block("12568", cid, slot, list, gid, a), "12566\r\n" .. info_json(a) })
end

function CS.h_rank(p, seq)
	local e = ED(); local a = st(e); push_ed(e)
	local n = 0; for _, slots in pairs(a.hba) do for _, list in pairs(slots) do n = n + #(list or {}) end end
	return reply(seq, "order_get_info", { "12611\r\n1\r\n" .. fint(ctv(a)) .. "\r\n" .. fint(n) .. "\r\n0" })
end

function CS.h_order(p, seq)
	if math.floor(tn(p[1], -1)) == 9 then return CS.h_rank(p, seq) end
	return err_reply(seq, "order_get_info", "LS_bang_xep_hang_chua_ho_tro", ERR.generic)
end

function CS.on_world(e)
	R.cs_t = nil
	R.cs_n = 0
	if S ~= nil and S.cs ~= nil and type(S.cs) ~= "table" then S.cs = nil end
	if e ~= nil and CS.T().ok then push_ed(e) end
end

function CS.dump_line()
	local a = S ~= nil and S.cs or nil
	if type(a) ~= "table" or type(a.hba) ~= "table" then return "[LS 12 Universe] chua khoi tao" end
	local bought, used = 0, 0
	for _, slots in pairs(a.hba) do
		if type(slots) == "table" then for _, list in pairs(slots) do bought = bought + #(list or {}) end end
	end
	for _, slots in pairs(a.uc or {}) do
		if type(slots) == "table" then for _ in pairs(slots) do used = used + 1 end end
	end
	return "[LS 12 Universe] da mua " .. bought .. " bao ho | dang dung " .. used
		.. " | Universe Value " .. fint(ctv(a)) .. " | full " .. (full_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.cs_last ~= nil and (" | cuoi: " .. R.cs_last) or "")
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if active() then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._cs = CS
end
init_cs()
end

do
local function init_hs()

local HS = {}
local FLOOR_LOW, FLOOR_TOP = 5000, 99999
local RANK_N = 30

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	return out
end

local function plist(s)
	local out = {}
	if tostring(s or "") == "-1" then return out end
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do out[#out + 1] = { tonumber(a), tonumber(b) } end
	return out
end

local function cfg_row(id)
	local pc = dtab("play_config")
	if pc == nil then return nil end
	local r = cells(pc[id])
	if r == nil then return nil end
	return r[schema("pirates_config", "param", 4)]
end

local function nums(s)
	local out = {}
	for v in string.gmatch(tostring(s or ""), "(%-?[%d%.]+)") do out[#out + 1] = tonumber(v) end
	return out
end

function HS.T()
	local T = R.hs_t
	if T ~= nil then return T end
	T = { ok = false, bio = {}, ids = {}, star = {}, ach = {}, aids = {}, chapters = {}, syn = {}, props = {}, cfg = {} }
	R.hs_t = T
	local bt, st, at, ct, mt = dtab("biographies_mould"), dtab("biographies_star_mould"), dtab("biographies_achieve"), dtab("biographies_section_mould"), dtab("mark_synthesis")
	if bt == nil or st == nil or at == nil then return T end
	local BM = { id = schema("biographies_mould", "id", 1), sg = schema("biographies_mould", "signet_cost", 3), ch = schema("biographies_mould", "chapterId", 5),
		pr = schema("biographies_mould", "property_add", 6), ad = schema("biographies_mould", "achievementAdd", 7) }
	for _, row in pairs(bt) do
		local r = cells(row)
		if r ~= nil then
			local id = tonumber(r[BM.id])
			if id ~= nil then
				id = math.floor(id)
				T.bio[id] = { id = id, cost = triples(r[BM.sg]), chapter = math.floor(tonumber(r[BM.ch]) or 1), add = plist(r[BM.pr]),
					ach = math.floor(tonumber(r[BM.ad]) or 0), stars = {}, max = 0 }
				T.ids[#T.ids + 1] = id
			end
		end
	end
	table.sort(T.ids)
	local SM = { bid = schema("biographies_star_mould", "biographies_mould_id", 2), star = schema("biographies_star_mould", "star", 3),
		cost = schema("biographies_star_mould", "costProp", 4), pr = schema("biographies_star_mould", "property_add", 6) }
	for _, row in pairs(st) do
		local r = cells(row)
		if r ~= nil then
			local b, s = tonumber(r[SM.bid]), tonumber(r[SM.star])
			local bio = b ~= nil and T.bio[math.floor(b)] or nil
			if bio ~= nil and s ~= nil then
				s = math.floor(s)
				bio.stars[s] = { cost = triples(r[SM.cost]), add = plist(r[SM.pr]) }
				if s > bio.max then bio.max = s end
			end
		end
	end
	local AM = { id = schema("biographies_achieve", "id", 1), val = schema("biographies_achieve", "achievementValue", 2), ut = schema("biographies_achieve", "unlock_type", 3),
		pa = schema("biographies_achieve", "param", 4), pr = schema("biographies_achieve", "property_add", 5) }
	for _, row in pairs(at) do
		local r = cells(row)
		if r ~= nil then
			local id = tonumber(r[AM.id])
			if id ~= nil then
				id = math.floor(id)
				T.ach[id] = { id = id, val = math.floor(tonumber(r[AM.val]) or 0), ut = math.floor(tonumber(r[AM.ut]) or 0), param = math.floor(tonumber(r[AM.pa]) or -1), add = plist(r[AM.pr]) }
				T.aids[#T.aids + 1] = id
			end
		end
	end
	table.sort(T.aids)
	if ct ~= nil then
		local CI = schema("biographies_section_mould", "id", 1)
		for _, row in pairs(ct) do
			local r = cells(row)
			local id = r ~= nil and tonumber(r[CI]) or nil
			if id ~= nil then T.chapters[#T.chapters + 1] = math.floor(id) end
		end
		table.sort(T.chapters)
	end
	if #T.chapters == 0 then T.chapters = { 1, 2, 3, 4, 5 } end
	if mt ~= nil then
		local MI = { id = schema("mark_synthesis", "id", 1), cp = schema("mark_synthesis", "compound_prop", 2), cs = schema("mark_synthesis", "consume_props", 3) }
		for _, row in pairs(mt) do
			local r = cells(row)
			if r ~= nil then
				local out = triples(r[MI.cp])[1]
				if out ~= nil then T.syn[out[2]] = { out = out, need = triples(r[MI.cs]) } end
			end
		end
	end

	for _, id in ipairs(T.ids) do
		local b = T.bio[id]
		for _, t in ipairs(b.cost) do if t[1] == 6 then T.props[t[2]] = true end end
		for s = 1, b.max do
			local x = b.stars[s]
			if x ~= nil then for _, t in ipairs(x.cost) do if t[1] == 6 then T.props[t[2]] = true end end end
		end
	end
	for pid, sy in pairs(T.syn) do
		T.props[pid] = true
		for _, t in ipairs(sy.need) do if t[1] == 6 then T.props[t[2]] = true end end
	end
	local function one(id)
		local a, b = string.match(tostring(cfg_row(id) or ""), "6%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)")
		return tonumber(a), tonumber(b) or 1
	end
	T.cfg.pn_id, T.cfg.pn_n = one(203)
	T.cfg.pa_id, T.cfg.pa_n = one(204)
	if T.cfg.pn_id ~= nil then T.props[T.cfg.pn_id] = true end
	if T.cfg.pa_id ~= nil then T.props[T.cfg.pa_id] = true end
	local lim = nums(cfg_row(197))
	T.cfg.max_n, T.cfg.max_a = lim[1] or 50, lim[2] or 8000
	local free = nums(cfg_row(198))
	T.cfg.free_n, T.cfg.free_a = free[1] or 1, free[2] or 1
	local libs = nums(cfg_row(207))
	T.cfg.lib = { libs[1] or 4482, libs[2] or 4483, libs[3] or 4484, libs[4] or 4485 }
	local g = nums(cfg_row(208))
	T.cfg.sure_n, T.cfg.sure_a = math.floor(g[1] or 10), math.floor(g[2] or 10)
	T.cfg.steps = nums(cfg_row(209))
	T.cfg.rewards = triples(cfg_row(210))
	local rk = nums(cfg_row(205))
	T.cfg.rank_min = rk[2] or 2100
	T.cfg.reset_gold = 0
	do
		local t = triples(cfg_row(206))[1]
		if t ~= nil then T.cfg.reset_gold = t[3] end
	end

	T.cfg.buy = {}
	for i = 0, 3 do
		local raw = tostring(cfg_row(199 + i) or "")
		local a, b = string.match(raw, "^(.-)|(.*)$")
		local c, g2 = triples(a)[1], triples(b)[1]
		if c ~= nil and g2 ~= nil then T.cfg.buy[i] = { cost = c, get = g2 } end
	end
	T.ok = #T.ids > 0 and #T.aids > 0
	return T
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.hs_auto == false) end
local function full_on() return type(S.cfg) == "table" and S.cfg.hs_full == true end
local function stats_on()
	if type(S.cfg) == "table" and (S.cfg.hs_stats == false or S.cfg.tl_stats == false) then return false end
	return true
end
local function open_all() return not (type(S.cfg) == "table" and S.cfg.hs_open_all == false) end

local function st()
	local a = S.hs
	if type(a) ~= "table" then a = { v = 1 }; S.hs = a end
	if type(a.a) ~= "table" then a.a = {} end
	if type(a.ach) ~= "table" then a.ach = {} end
	if type(a.d) ~= "table" then a.d = {} end
	local d = a.d
	for _, k in ipairs({ "fn", "fa", "nu", "au", "gn", "ga", "tot", "got" }) do d[k] = math.max(0, math.floor(tn(d[k], 0))) end
	-- [FIX lag 13] st() duoc goi cho TUNG liet truyen / thanh tuu khi mo Hero Saga; os.date moi lan la thua => nho theo giay.
	local now = os.time()
	local dc = R.hs_daycache
	if dc == nil or dc.t ~= now then dc = { t = now, s = os.date("%Y-%m-%d", now) }; R.hs_daycache = dc end
	local day = dc.s
	if d.day ~= day then d.day = day; d.fn, d.fa, d.nu, d.au = 0, 0, 0, 0 end
	return a
end

local function copy_manual(a)
	local T = HS.T()
	local out = { a = {}, ach = {} }
	for _, id in ipairs(T.ids) do
		local k, v = tostring(id), a.a[tostring(id)]
		if v ~= nil then out.a[k] = math.max(0, math.min(T.bio[id].max, math.floor(tn(v, 0)))) end
	end
	for _, id in ipairs(T.aids) do if a.ach[tostring(id)] == 1 then out.ach[tostring(id)] = 1 end end
	return out
end

local function make_full(a)
	local T, changed = HS.T(), false
	if not a.full then
		a.manual, a.full = copy_manual(a), true
		changed = true
	end
	for _, id in ipairs(T.ids) do
		local k, mx = tostring(id), T.bio[id].max
		if a.a[k] ~= mx then a.a[k] = mx; changed = true end
	end
	for _, id in ipairs(T.aids) do
		local k = tostring(id)
		if a.ach[k] ~= 1 then a.ach[k] = 1; changed = true end
	end
	return changed
end

local function unfull(a)
	if not a.full then return false end
	local m = a.manual
	a.a, a.ach = {}, {}
	if type(m) == "table" then
		for k, v in pairs(m.a or {}) do a.a[k] = v end
		for k, v in pairs(m.ach or {}) do a.ach[k] = v end
	end
	a.manual, a.full = nil, nil
	R.hs_last = "tat full: tra Hero Saga ve tien trinh tu nang"
	return true
end

local function star_of(id)
	local v = st().a[tostring(id)]
	if v == nil then return nil end
	return math.floor(tn(v, 0))
end

local function active_count()
	local n = 0
	for _ in pairs(st().a) do n = n + 1 end
	return n
end

local function total_value()
	local T = HS.T()
	local sum = 0
	for key in pairs(st().a) do
		local b = T.bio[tonumber(key)]
		if b ~= nil then sum = sum + b.ach end
	end
	return sum
end

local function ach_active(id) return st().ach[tostring(id)] == 1 end

local function chapter_state(idx)
	if open_all() then return true, true end
	local T = HS.T()
	local unlock, adv = (idx == T.chapters[1]), false
	for _, id in ipairs(T.aids) do
		local x = T.ach[id]
		if ach_active(id) and x.param == idx then
			if x.ut == 1 then unlock = true elseif x.ut == 2 then adv = true end
		end
	end
	return unlock, adv
end

function HS.totals()
	local T = HS.T()
	local tot = {}
	local a = S ~= nil and S.hs or nil
	if type(a) ~= "table" or type(a.a) ~= "table" then return tot end
	-- [FIX lag 13] HS.adjust chay cho TUNG tuong moi lan tinh lai chi so (300+ tuong) va moi lan lai duyet het liet truyen x sao.
	-- Ket qua chi doi khi Hero Saga doi => nho theo "chu ky" re (so phan tu + tong), tinh lai khi chu ky doi. Ket qua chi doc.
	local sn, s1, s2, sm = 0, 0, 0, 0
	for key, star in pairs(a.a) do
		local k, v = tonumber(key) or 0, tonumber(star) or 0
		sn = sn + 1; s1 = s1 + k * 31 + v; s2 = s2 + k * v
	end
	if type(a.ach) == "table" then
		for key, v in pairs(a.ach) do if v == 1 then sm = sm + (tonumber(key) or 0) * 17 + 1 end end
	end
	local c = R.hs_tot
	if c ~= nil and c.T == T and c.sn == sn and c.s1 == s1 and c.s2 == s2 and c.sm == sm then return c.tot end
	local function addl(list) for _, kv in ipairs(list) do tot[kv[1]] = (tot[kv[1]] or 0) + kv[2] end end
	for key, star in pairs(a.a) do
		local b = T.bio[tonumber(key)]
		if b ~= nil then
			addl(b.add)
			star = math.floor(tn(star, 0))
			for s = 1, math.min(star, b.max) do
				if b.stars[s] ~= nil then addl(b.stars[s].add) end
			end
		end
	end
	if type(a.ach) == "table" then
		for key, v in pairs(a.ach) do
			local x = v == 1 and T.ach[tonumber(key)] or nil
			if x ~= nil then addl(x.add) end
		end
	end
	R.hs_tot = { T = T, sn = sn, s1 = s1, s2 = s2, sm = sm, tot = tot }
	return tot
end

function HS.active()
	if not stats_on() then return false end
	local a = S ~= nil and S.hs or nil
	if type(a) ~= "table" or type(a.a) ~= "table" or next(a.a) == nil then return false end
	return true
end

local NOT_IN_FIGHT = { [43] = true, [46] = true }

function HS.adjust(sid, tid, pn, spec, is_rec)
	if not HS.active() or type(pn) ~= "table" then return end
	local ok, err = pcall(function()
		local tot = HS.totals()
		if next(tot) == nil then return end
		for i = 1, 3 do
			local x = pn[i]
			if type(x) == "number" then
				local flat, pct = tot[i - 1] or 0, tot[i + 3] or 0
				if flat ~= 0 or pct ~= 0 then pn[i] = math.max(0, rnd(x + flat + x * pct / 100)) end
			end
		end
		if type(spec) == "table" then
			for key, v in pairs(tot) do
				if key >= 7 and not NOT_IN_FIGHT[key] then spec[key] = (spec[key] or 0) + v end
			end
		end
	end)
	if not ok then
		R.hs_errs = (R.hs_errs or 0) + 1
		if R.hs_errs <= 5 then log("loi chi so Hero Saga:", tostring(err)) end
	end
end

local function jnum(v)
	v = tonumber(v) or 0
	if v == math.floor(v) then return fint(v) end
	return tostring(v)
end

function HS.blk_all()
	local T = HS.T()
	local parts = {}
	for _, id in ipairs(T.ids) do
		local s = star_of(id)
		if s ~= nil then parts[#parts + 1] = string.format('{"biographiesMouldId":%s,"biographiesStar":%s}', fint(id), fint(s)) end
	end
	return "12668\r\n[" .. table.concat(parts, ",") .. "]"
end

function HS.blk_one(id)
	local s = star_of(id) or 0
	return "12669\r\n" .. string.format('{"biographiesMouldId":%s,"biographiesStar":%s}', fint(id), fint(s))
end

function HS.blk_achieve()
	local T = HS.T()
	local sts = {}
	for _, id in ipairs(T.aids) do sts[#sts + 1] = ach_active(id) and "1" or "0" end
	return "12670\r\n" .. string.format('{"totalAchieveNumber":%s,"achieveStatusInfo":"%s"}', fint(total_value()), table.concat(sts, ","))
end

function HS.blk_chapter()
	local T = HS.T()
	local parts = {}
	for i, cid in ipairs(T.chapters) do
		local u, a = chapter_state(cid)
		parts[#parts + 1] = string.format('{"index":%d,"unlock":%d,"canAdvance":%d}', i - 1, u and 1 or 0, a and 1 or 0)
	end
	return "12671\r\n[" .. table.concat(parts, ",") .. "]"
end

function HS.blk_draw()
	local T, a = HS.T(), st()
	local d = a.d
	local fn = math.max(0, T.cfg.free_n - d.fn)
	local fa = math.max(0, T.cfg.free_a - d.fa)
	return "12672\r\n" .. string.format('{"normalDrawFreeNumber":%d,"advanceDrawFreeNumber":%d,"normalDrawMaxNumber":%d,"advanceDrawMaxNumber":%d,"totalAdvanceDrawNumber":%d,"haveGet":%d}',
		fn, fa, math.min(d.nu, T.cfg.max_n), math.min(d.au, T.cfg.max_a), d.tot, d.got)
end

local function preview(lib)
	local row
	local t = dtab("scene_reward_ex")
	if t ~= nil then row = cells(t[lib]) end
	local out = {}
	if row ~= nil then
		for it, ty, n in string.gmatch(tostring(row[schema("scene_reward_ex", "show_reward", 3)] or ""), "(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)") do
			out[#out + 1] = ty .. "," .. it .. "," .. n
		end
	end
	return table.concat(out, "|")
end

function HS.blk_preview()
	local T = HS.T()
	return "12674\r\n" .. string.format('{"normal":"%s","advance":"%s"}', preview(T.cfg.lib[1]), preview(T.cfg.lib[3]))
end

local NAMES = { "Saiyan_Ace", "Namek_Sage", "Frieza_Slayer", "Majin_Z", "Capsule_Dr", "Kame_Master", "Ginyu_Boss", "Cell_Hunter", "Android_21", "Turtle_Hermit",
	"Crane_Style", "Orange_Star", "Hercule_Fan", "Gohan_Kid", "Piccolo_Dad", "Trunks_Sword", "Vegeta_Prince", "Bulma_Lab", "Krillin_Bald", "Yamcha_Wolf",
	"Tien_Eye", "Chiaotzu", "Roshi_Old", "Videl_Fight", "Goten_Fusion", "Beerus_Nap", "Whis_Staff", "Jiren_Gray", "Hit_Assassin", "Broly_Wild" }

local function my_name(e)
	local n = tostring(e.user_info and e.user_info.user_name or "Player")
	n = n:gsub("[%s\r\n|,\"\\]", "_")
	if n == "" then n = "Player" end
	return n
end

function HS.blk_rank(tab)
	local e = ED()
	local T = HS.T()
	tab = (tonumber(tab) == 1) and 1 or 0
	local list = {}
	for i = 1, RANK_N do
		local sc = 19600 - (i - 1) * 600 - (tab == 1 and 130 or 0)
		list[#list + 1] = { name = NAMES[(i - 1 + tab * 7) % #NAMES + 1] .. (tab == 1 and "_x" or ""), score = sc, head = (i % 8) + 1, lv = 90 - (i % 25), srv = tab == 1 and (2 + i % 5) or 1, me = false }
	end
	local mine = total_value()
	local myrank = -1
	if e ~= nil and mine >= T.cfg.rank_min and mine > 0 then
		local pos = #list + 1
		for i, x in ipairs(list) do if mine > x.score then pos = i; break end end
		local head = tonumber(e.user_info and e.user_info.user_head) or 1
		table.insert(list, pos, { name = my_name(e), score = mine, head = head, lv = math.max(1, math.floor(tonumber(e.user_info and e.user_info.user_grade) or 1)), srv = 1, me = true })
		if pos <= RANK_N then myrank = pos end
		while #list > RANK_N do table.remove(list) end
	end
	local parts = {}
	for i, x in ipairs(list) do
		parts[#parts + 1] = string.format('{"rankNumber":%d,"rankInfo":{"nickName":"%s","headPic":%d,"activateNumber":%d,"score":%d,"serverNumber":%d,"userLevel":%d}}',
			i, x.name, math.floor(x.head), math.floor(x.score / 100), math.floor(x.score), x.srv, math.floor(x.lv))
	end
	return "12673\r\n" .. string.format('{"allRankInfo":[%s],"myRankNumber":%d}', table.concat(parts, ","), myrank)
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3]) end
	return table.concat(b, "\r\n")
end

local function floor_props()
	if not auto_on() then return end
	local T = HS.T()
	for id in pairs(T.props) do
		if LS.prop_get(id) < FLOOR_LOW then LS.prop_set(id, FLOOR_TOP) end
	end
end

local function can_pay(list, times)
	times = times or 1
	if auto_on() then
		local want = {}
		for _, t in ipairs(list) do
			if t[1] == 6 then want[t[2]] = (want[t[2]] or 0) + t[3] * times end
		end
		for id, n in pairs(want) do
			if LS.prop_get(id) < n then LS.prop_set(id, n + FLOOR_TOP) end
		end
	end
	local need = {}
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		need[k] = (need[k] or 0) + t[3] * times
	end
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		local n = need[k]
		if n ~= nil then
			if t[1] == 6 then
				if LS.prop_get(t[2]) < n then return false, ERR.items end
			elseif t[1] == 1 then
				if (S.silver or 0) < n then return false, ERR.silver end
			end
			need[k] = nil
		end
	end
	return true
end

local function pay(list, times)
	times = times or 1
	for _, t in ipairs(list) do
		local n = t[3] * times
		if t[1] == 6 then LS.prop_add(t[2], -n)
		elseif t[1] == 1 then LS.money_spend("silver", n) end
	end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if not HS.T().ok then error("khong co bang Hero Saga") end
	st()
	floor_props()
	return e
end

local function finish(e, seq, name, extra, stats)
	local blocks = {}
	for _, b in ipairs(extra or {}) do blocks[#blocks + 1] = b end
	if stats and LS._tl ~= nil and LS._tl.refresh_blocks ~= nil then
		LS._tl.refresh_blocks(e, blocks)
		LS._tl.queue_all(e)
		R.tl_sig_l, R.tl_sig_f = nil, nil
	end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function bio_of(seq, name, p)
	local id = math.floor(tn(p[1], -1))
	local b = HS.T().bio[id]
	if b == nil then return nil, nil, err_reply(seq, name, "LS_liet_truyen_khong_ton_tai", ERR.generic) end
	return id, b
end

function HS.h_init(p, seq)
	local e = ctx()
	stat_inc("hs_init")
	return reply(seq, "biographies_init", { HS.blk_all(), HS.blk_achieve(), HS.blk_chapter(), HS.blk_draw(), HS.blk_rank(0), HS.blk_preview() })
end

function HS.h_activate(p, seq)
	local e = ctx()
	local id, b, er = bio_of(seq, "biographies_activate", p)
	if id == nil then return er end
	if star_of(id) ~= nil then return err_reply(seq, "biographies_activate", "LS_da_kich_hoat", ERR.generic) end
	local unlock = chapter_state(b.chapter)
	if not unlock then return err_reply(seq, "biographies_activate", "LS_chuong_chua_mo", ERR.generic) end
	local okp, code = can_pay(b.cost)
	if not okp then return err_reply(seq, "biographies_activate", "LS_khong_du_an_ky", code) end
	pay(b.cost)
	st().a[tostring(id)] = 0
	R.hs_last = "kich hoat " .. id
	stat_inc("hs_activate")
	return finish(e, seq, "biographies_activate", { HS.blk_one(id), HS.blk_achieve(), HS.blk_chapter() }, true)
end

function HS.h_achieve(p, seq)
	local e = ctx()
	local T = HS.T()
	local id = math.floor(tn(p[1], -1))
	local x = T.ach[id]
	if x == nil then return err_reply(seq, "biographies_achieve_activate", "LS_thanh_tuu_khong_ton_tai", ERR.generic) end
	if ach_active(id) then return err_reply(seq, "biographies_achieve_activate", "LS_thanh_tuu_da_kich_hoat", ERR.generic) end
	if total_value() < x.val then return err_reply(seq, "biographies_achieve_activate", "LS_chua_du_gia_tri_thanh_tuu", ERR.generic) end
	st().ach[tostring(id)] = 1
	R.hs_last = "thanh tuu " .. id
	stat_inc("hs_achieve")
	return finish(e, seq, "biographies_achieve_activate", { HS.blk_achieve(), HS.blk_chapter() }, true)
end

function HS.h_advance(p, seq)
	local e = ctx()
	local id, b, er = bio_of(seq, "biographies_advance", p)
	if id == nil then return er end
	local cur = star_of(id)
	if cur == nil then return err_reply(seq, "biographies_advance", "LS_chua_kich_hoat", ERR.generic) end
	if cur >= b.max or b.stars[cur + 1] == nil then return err_reply(seq, "biographies_advance", "LS_da_toi_sao_toi_da", ERR.rank_max) end
	local _, adv = chapter_state(b.chapter)
	if not adv then return err_reply(seq, "biographies_advance", "LS_chuong_chua_mo_nang_sao", ERR.generic) end
	local cost = b.stars[cur + 1].cost
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "biographies_advance", "LS_khong_du_an_ky", code) end
	pay(cost)
	st().a[tostring(id)] = cur + 1
	R.hs_last = "nang sao " .. id .. " -> " .. (cur + 1)
	stat_inc("hs_advance")
	return finish(e, seq, "biographies_advance", { HS.blk_one(id), HS.blk_achieve() }, true)
end

function HS.h_rebirth(p, seq)
	local e = ctx()
	local id, b, er = bio_of(seq, "biographies_rebirth", p)
	if id == nil then return er end
	local cur = star_of(id)
	if cur == nil then return err_reply(seq, "biographies_rebirth", "LS_chua_kich_hoat", ERR.generic) end
	if cur <= 0 then return err_reply(seq, "biographies_rebirth", "LS_chua_co_sao", ERR.generic) end
	local back = {}
	local order = {}
	for s = 1, cur do
		local x = b.stars[s]
		if x ~= nil then
			for _, t in ipairs(x.cost) do
				if t[1] == 6 then
					if back[t[2]] == nil then back[t[2]] = 0; order[#order + 1] = t[2] end
					back[t[2]] = back[t[2]] + t[3]
				end
			end
		end
	end
	local items = {}
	for _, pid in ipairs(order) do
		LS.prop_add(pid, back[pid])
		items[#items + 1] = { pid, 6, back[pid] }
	end
	st().a[tostring(id)] = 0
	R.hs_last = "dat lai sao " .. id
	stat_inc("hs_rebirth")
	return finish(e, seq, "biographies_rebirth", { HS.blk_one(id), HS.blk_achieve(), blk_reward(items) }, true)
end

function HS.h_rank(p, seq)
	ctx()
	stat_inc("hs_rank")
	return reply(seq, "biographies_rank", { HS.blk_rank(p[1]) })
end

local function prop_instance(e, tmpl)
	if type(e.user_prop) ~= "table" then return nil end
	local want = tostring(math.floor(tmpl))
	local best
	for id, r in pairs(e.user_prop) do
		if type(r) == "table" and tostring(r.user_prop_template) == want then
			if best == nil or tonumber(id) < tonumber(best) then best = id end
		end
	end
	return best
end

function HS.h_draw(p, seq)
	local e = ctx()
	local T = HS.T()
	local dtype = math.floor(tn(p[1], -1))
	local times = math.floor(tn(p[2], 0))
	if dtype ~= 0 and dtype ~= 1 then return err_reply(seq, "biographies_draw", "LS_kieu_rut_khong_hop_le", ERR.generic) end
	if times ~= 1 and times ~= 10 then return err_reply(seq, "biographies_draw", "LS_so_luot_khong_hop_le", ERR.generic) end
	local a = st()
	local d = a.d
	local pid = dtype == 0 and T.cfg.pn_id or T.cfg.pa_id
	local per = dtype == 0 and T.cfg.pn_n or T.cfg.pa_n
	if pid == nil then return err_reply(seq, "biographies_draw", "LS_khong_co_an_ky_rut", ERR.items) end
	local free_left = dtype == 0 and math.max(0, T.cfg.free_n - d.fn) or math.max(0, T.cfg.free_a - d.fa)
	local use_free = (times == 1 and free_left > 0)
	if not use_free then
		local okp, code = can_pay({ { 6, pid, per } }, times)
		if not okp then return err_reply(seq, "biographies_draw", "LS_khong_du_an_ky_rut", code) end
		LS.prop_add(pid, -(per * times))
	elseif dtype == 0 then d.fn = d.fn + 1 else d.fa = d.fa + 1 end

	e.new_prop_object, e.new_reward_object = {}, {}
	local got = {}
	for _ = 1, times do
		local sure
		if dtype == 0 then
			d.gn = d.gn + 1
			sure = d.gn >= T.cfg.sure_n
			if sure then d.gn = 0 end
			d.nu = d.nu + 1
		else
			d.ga = d.ga + 1
			sure = d.ga >= T.cfg.sure_a
			if sure then d.ga = 0 end
			d.au = d.au + 1
			d.tot = d.tot + 1
		end
		local lib = (dtype == 0) and (sure and T.cfg.lib[2] or T.cfg.lib[1]) or (sure and T.cfg.lib[4] or T.cfg.lib[3])
		local rolled = LS._roll_library(lib, 1)
		for _, it in ipairs(rolled) do
			if it.typ == 6 and it.qty > 0 then got[#got + 1] = { it.item, it.qty } end
		end
	end

	local items = {}
	for _, g in ipairs(got) do
		LS.prop_add(g[1], g[2])
		items[#items + 1] = { g[1], 6, g[2] }
		local inst = prop_instance(e, g[1])
		if inst ~= nil then
			table.insert(e.new_prop_object, { number = g[2], user_prop_id = inst })
			table.insert(e.new_reward_object, { number = g[2], mould_id = inst, m_type = 6 })
		end
	end
	R.hs_last = "rut " .. (dtype == 0 and "thuong" or "cao cap") .. " x" .. times
	stat_inc("hs_draw", times)
	return finish(e, seq, "biographies_draw", { blk_reward(items), HS.blk_draw() }, false)
end

function HS.h_buy(p, seq)
	local e = ctx()
	local T = HS.T()
	local btype = math.floor(tn(p[1], 0))
	local pack = math.floor(tn(p[2], 0))
	local n = math.floor(tn(p[3], 1))
	local x = T.cfg.buy[(btype == 1 and 2 or 0) + (pack == 1 and 1 or 0)]
	if x == nil then return err_reply(seq, "biographies_buy_prop", "LS_goi_khong_hop_le", ERR.generic) end
	local max = (pack == 0) and 999 or 99
	if n < 1 or n > max then return err_reply(seq, "biographies_buy_prop", "LS_so_luong_khong_hop_le", ERR.generic) end
	local okp, code = can_pay({ x.cost }, n)
	if not okp then return err_reply(seq, "biographies_buy_prop", "LS_khong_du_tien", code) end
	pay({ x.cost }, n)
	local qty = x.get[3] * n
	LS.prop_add(x.get[2], qty)
	R.hs_last = "mua " .. qty .. " an ky " .. x.get[2]
	stat_inc("hs_buy")
	return finish(e, seq, "biographies_buy_prop", { blk_reward({ { x.get[2], 6, qty } }) }, false)
end

function HS.h_extra(p, seq)
	local e = ctx()
	local T = HS.T()
	local d = st().d
	local steps = T.cfg.steps
	local n = #steps
	if n == 0 or #T.cfg.rewards == 0 then return err_reply(seq, "biographies_get_extra_reward", "LS_khong_co_qua", ERR.generic) end
	local nextStep = (d.got % n) + 1
	local used = 0
	for i = 0, d.got - 1 do used = used + steps[(i % n) + 1] end
	local remain = d.tot - used
	if remain < steps[nextStep] then return err_reply(seq, "biographies_get_extra_reward", "LS_chua_du_luot_rut", ERR.generic) end
	local rw = T.cfg.rewards[nextStep] or T.cfg.rewards[#T.cfg.rewards]
	local items = {}
	if rw[1] == 6 then LS.prop_add(rw[2], rw[3]); items[1] = { rw[2], 6, rw[3] } end
	d.got = d.got + 1
	R.hs_last = "nhan qua moc rut " .. d.got
	stat_inc("hs_extra")
	return finish(e, seq, "biographies_get_extra_reward", { blk_reward(items), HS.blk_draw() }, false)
end

function HS.h_synth(p, seq)
	local e = ctx()
	local T = HS.T()
	local pid = math.floor(tn(p[1], -1))
	local sy = T.syn[pid]
	if sy == nil then return err_reply(seq, "biographies_mark_synthesis", "LS_khong_tong_hop_duoc", ERR.generic) end
	local okp, code = can_pay(sy.need)
	if not okp then return err_reply(seq, "biographies_mark_synthesis", "LS_khong_du_an_ky", code) end
	pay(sy.need)
	LS.prop_add(pid, sy.out[3])
	R.hs_last = "tong hop an ky " .. pid
	stat_inc("hs_synth")
	return finish(e, seq, "biographies_mark_synthesis", { blk_reward({ { pid, 6, sy.out[3] } }) }, false)
end

function HS.tick(e)
	if S == nil or not R.ready or not HS.T().ok then return end
	local old = S.hs
	if not full_on() and (type(old) ~= "table" or not old.full) then return end
	R.hs_n = (R.hs_n or 0) + 1
	if R.hs_n % 15 ~= 1 and not R.hs_now then return end
	R.hs_now = nil
	local a = st()
	-- KHONG dung "full_on() and make_full(a) or unfull(a)": khi FULL da bat san, make_full tra false
	-- (khong co gi doi) nen bieu thuc and/or roi xuong unfull() va TAT FULL; 15 nhip sau lai bat lai
	-- -> chi so tuong nhay tang roi giam lien tuc. Phai dung if/else.
	local changed
	if full_on() then changed = make_full(a) else changed = unfull(a) end
	if not changed then return end
	if LS._tl ~= nil and LS._tl.queue_all ~= nil then pcall(LS._tl.queue_all, e); R.tl_sig_l, R.tl_sig_f = nil, nil end
	mark()
end

function HS.apply_now(e)
	R.hs_now = true
	if e ~= nil then HS.tick(e) end
end
HS.full_on = full_on

function HS.dump_line()
	local a = S ~= nil and S.hs or nil
	if type(a) ~= "table" or type(a.a) ~= "table" then return "[LS hero saga] chua khoi tao" end
	local n, stars, ach = 0, 0, 0
	for _, s in pairs(a.a) do n = n + 1; stars = stars + (tonumber(s) or 0) end
	for _, v in pairs(type(a.ach) == "table" and a.ach or {}) do if v == 1 then ach = ach + 1 end end
	return "[LS hero saga] " .. n .. " liet truyen | tong sao " .. stars .. " | " .. ach .. " thanh tuu | rut cao cap " .. (type(a.d) == "table" and (tonumber(a.d.tot) or 0) or 0)
		.. " | full " .. (full_on() and "BAT" or "TAT") .. " | mo san " .. (open_all() and "BAT" or "TAT") .. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.hs_last ~= nil and (" | cuoi: " .. R.hs_last) or "")
end

function HS.reset()
	S.hs = nil
	R.hs_t = nil
	mark()
end

function HS.on_world(e)
	R.hs_t = nil
	R.hs_n = 0
	if S ~= nil and S.hs ~= nil and type(S.hs) ~= "table" then S.hs = nil end
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if HS.active() then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._hs = HS

end
init_hs()
end

do
local function init_ma()

local MA = {}
local FLOOR_LOW, FLOOR_TOP = 5000, 99999

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end

local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end

local function schema(name, field, dflt)
	local sc = G(name)
	if type(sc) == "table" and tonumber(sc[field]) ~= nil then return sc[field] end
	return dflt
end

local function triples(s)
	local out = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do out[#out + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	return out
end

local function plist(s)
	local out = {}
	if tostring(s or "") == "-1" then return out end
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do out[#out + 1] = { tonumber(a), tonumber(b) } end
	return out
end

local function cfg_row(id)
	local pc = dtab("play_config")
	if pc == nil then return nil end
	local r = cells(pc[id])
	if r == nil then return nil end
	return r[schema("pirates_config", "param", 4)]
end

function MA.T()
	local T = R.ma_t
	if T ~= nil then return T end
	T = { ok = false, an = {}, ids = {}, star = {}, forge = {}, rel = {}, relids = {}, fate = {}, nstage = 0, tasks = { [1] = {}, [2] = {} }, props = {}, cfg = {} }
	R.ma_t = T
	local mt, st, ft, rt, ct, tt = dtab("magical_animals_mould"), dtab("magical_animals_star_mould"), dtab("magical_animals_forging_mould"),
		dtab("magical_animals_relevant_mould"), dtab("magical_animals_fate_mould"), dtab("magical_animals_fate_task_mould")
	if mt == nil or st == nil or ft == nil then return T end
	local MM = { id = schema("magical_animals_mould", "id", 1), sg = schema("magical_animals_mould", "upStarGoupId", 6), fg = schema("magical_animals_mould", "forgeGoupId", 7) }
	for _, row in pairs(mt) do
		local r = cells(row)
		local id = r ~= nil and tonumber(r[MM.id]) or nil
		if id ~= nil then
			id = math.floor(id)
			T.an[id] = { id = id, sg = math.floor(tonumber(r[MM.sg]) or id), fg = math.floor(tonumber(r[MM.fg]) or id) }
			T.ids[#T.ids + 1] = id
		end
	end
	table.sort(T.ids)
	local SM = { g = schema("magical_animals_star_mould", "groupId", 2), s = schema("magical_animals_star_mould", "curStarLvl", 3),
		pr = schema("magical_animals_star_mould", "propertyAdd", 5), co = schema("magical_animals_star_mould", "costProp", 6) }
	for _, row in pairs(st) do
		local r = cells(row)
		local g, s = r ~= nil and tonumber(r[SM.g]) or nil, r ~= nil and tonumber(r[SM.s]) or nil
		if g ~= nil and s ~= nil then
			g, s = math.floor(g), math.floor(s)
			local a = T.star[g]
			if a == nil then a = { max = 0, rows = {} }; T.star[g] = a end
			a.rows[s] = { add = plist(r[SM.pr]), cost = triples(r[SM.co])[1] }
			if s > a.max then a.max = s end
			if a.rows[s].cost ~= nil and a.rows[s].cost[1] == 6 then T.props[a.rows[s].cost[2]] = true end
		end
	end
	local FM = { g = schema("magical_animals_forging_mould", "groupId", 2), s = schema("magical_animals_forging_mould", "curStageLvl", 3),
		co = schema("magical_animals_forging_mould", "costProp", 5) }
	for _, row in pairs(ft) do
		local r = cells(row)
		local g, s = r ~= nil and tonumber(r[FM.g]) or nil, r ~= nil and tonumber(r[FM.s]) or nil
		if g ~= nil and s ~= nil then
			g, s = math.floor(g), math.floor(s)
			local a = T.forge[g]
			if a == nil then a = { max = 0, rows = {} }; T.forge[g] = a end
			a.rows[s] = { cost = triples(r[FM.co]) }
			if s > a.max then a.max = s end
			for _, t in ipairs(a.rows[s].cost) do if t[1] == 6 then T.props[t[2]] = true end end
		end
	end
	if rt ~= nil then
		local RM = { id = schema("magical_animals_relevant_mould", "id", 1), an = schema("magical_animals_relevant_mould", "animalIds", 2),
			ns = schema("magical_animals_relevant_mould", "needStar", 3), pr = schema("magical_animals_relevant_mould", "propertyAdd", 4) }
		for _, row in pairs(rt) do
			local r = cells(row)
			local id = r ~= nil and tonumber(r[RM.id]) or nil
			if id ~= nil then
				id = math.floor(id)
				local ids = {}
				for v in string.gmatch(tostring(r[RM.an]), "%d+") do ids[#ids + 1] = math.floor(tonumber(v)) end
				T.rel[id] = { id = id, ids = ids, need = math.floor(tonumber(r[RM.ns]) or 1), add = plist(r[RM.pr]) }
				T.relids[#T.relids + 1] = id
			end
		end
		table.sort(T.relids)
	end
	if ct ~= nil then
		local CM = { stage = schema("magical_animals_fate_mould", "stage", 2), de = schema("magical_animals_fate_mould", "destiny", 4),
			cat = schema("magical_animals_fate_mould", "propertyCategory", 6), pr = schema("magical_animals_fate_mould", "propertyAdd", 7), co = schema("magical_animals_fate_mould", "costProp", 8) }
		for _, row in pairs(ct) do
			local r = cells(row)
			local s, d = r ~= nil and tonumber(r[CM.stage]) or nil, r ~= nil and tonumber(r[CM.de]) or nil
			if s ~= nil and d ~= nil then
				s, d = math.floor(s), math.floor(d)
				local a = T.fate[s]
				if a == nil then a = {}; T.fate[s] = a end
				a[d] = { cat = math.floor(tonumber(r[CM.cat]) or 0), add = plist(r[CM.pr]), cost = triples(r[CM.co])[1] }
				if s > T.nstage then T.nstage = s end
				if a[d].cost ~= nil and a[d].cost[1] == 6 then T.props[a[d].cost[2]] = true end
			end
		end
	end
	if tt ~= nil then
		local TM = { id = schema("magical_animals_fate_task_mould", "id", 1), ty = schema("magical_animals_fate_task_mould", "taskType", 2),
			nm = schema("magical_animals_fate_task_mould", "taskNum", 6), rw = schema("magical_animals_fate_task_mould", "taskReward", 7) }
		local list = {}
		for _, row in pairs(tt) do
			local r = cells(row)
			local id, ty = r ~= nil and tonumber(r[TM.id]) or nil, r ~= nil and tonumber(r[TM.ty]) or nil
			if id ~= nil and ty ~= nil then list[#list + 1] = { id = math.floor(id), ty = math.floor(ty), num = math.floor(tonumber(r[TM.nm]) or 0), rw = triples(r[TM.rw])[1] } end
		end
		table.sort(list, function(a, b) return a.id < b.id end)
		for _, x in ipairs(list) do
			if T.tasks[x.ty] == nil then T.tasks[x.ty] = {} end
			table.insert(T.tasks[x.ty], x)
			if x.rw ~= nil and x.rw[1] == 6 then T.props[x.rw[2]] = true end
		end
	end

	T.cfg.stones = triples(cfg_row(211))
	for _, t in ipairs(T.cfg.stones) do if t[1] == 6 then T.props[t[2]] = true end end
	T.cfg.stone_add = plist(cfg_row(212))
	do
		local t = triples(cfg_row(215))[1]
		T.cfg.fate_prop = t ~= nil and t[2] or nil
		if T.cfg.fate_prop ~= nil then T.props[T.cfg.fate_prop] = true end
	end
	T.ok = #T.ids > 0 and next(T.star) ~= nil and next(T.forge) ~= nil
	return T
end

local function auto_on() return not (type(S.cfg) == "table" and S.cfg.ma_auto == false) end
local function full_on() return type(S.cfg) == "table" and S.cfg.ma_full == true end
local function stats_on()
	if type(S.cfg) == "table" and (S.cfg.ma_stats == false or S.cfg.tl_stats == false) then return false end
	return true
end
local function forge_cap()
	if type(S.cfg) == "table" and tonumber(S.cfg.ma_forge_cap) ~= nil then return math.max(1, math.floor(tonumber(S.cfg.ma_forge_cap))) end
	return 3000
end

local function nn(v, d, lo, hi)
	v = math.floor(tn(v, d))
	if lo ~= nil and v < lo then v = lo end
	if hi ~= nil and v > hi then v = hi end
	return v
end

local function st()
	local T = MA.T()
	local a = S.ma
	if type(a) ~= "table" then a = { v = 1 }; S.ma = a end
	if type(a.a) ~= "table" then a.a = {} end
	for key, x in pairs(a.a) do
		local id = tonumber(key)
		local an = id ~= nil and T.an[math.floor(id)] or nil
		if an == nil or type(x) ~= "table" then
			a.a[key] = nil
		else
			local sg, fg = T.star[an.sg], T.forge[an.fg]
			x.star = nn(x.star, 1, 1, sg ~= nil and sg.max or 1)
			x.stage = nn(x.stage, 0, 0, fg ~= nil and fg.max or 0)
			if type(x.u) ~= "table" then x.u = {} end
			for i = 1, 3 do x.u[i] = nn(x.u[i], 0, 0) end
		end
	end
	if type(a.lg) ~= "table" then a.lg = {} end
	for key in pairs(a.lg) do if T.rel[tonumber(key) or -1] == nil then a.lg[key] = nil end end
	if type(a.sk) ~= "table" then a.sk = {} end
	local used = {}
	for i = 1, 3 do
		local v = nn(a.sk[i], -1)
		if v ~= -1 and (a.a[tostring(v)] == nil or used[v]) then v = -1 end
		if v ~= -1 then used[v] = true end
		a.sk[i] = v
	end
	a.rel = (nn(a.rel, 0) == 1) and 1 or 0
	if type(a.fate) ~= "table" then a.fate = {} end
	a.fate.step = nn(a.fate.step, 0, 0, T.nstage)
	a.fate.prog = nn(a.fate.prog, 0, 0, 4)
	if type(a.task) ~= "table" then a.task = {} end
	a.task.got2 = nn(a.task.got2, 0, 0, #(T.tasks[2] or {}))
	a.task.d1 = (type(a.task.d1) == "string") and a.task.d1 or nil
	return a
end

local function copy_manual(a)
	local T = MA.T()
	local out = { a = {}, lg = {}, sk = { -1, -1, -1 }, rel = a.rel, fate = { step = a.fate.step, prog = a.fate.prog } }
	for _, id in ipairs(T.ids) do
		local x = a.a[tostring(id)]
		if type(x) == "table" then out.a[tostring(id)] = { star = x.star, stage = x.stage, u = { x.u[1], x.u[2], x.u[3] } } end
	end
	for _, id in ipairs(T.relids) do if a.lg[tostring(id)] == 1 then out.lg[tostring(id)] = 1 end end
	for i = 1, 3 do out.sk[i] = a.sk[i] end
	return out
end

local function make_full(a)
	local T, changed = MA.T(), false
	if not a.full then
		a.manual, a.full = copy_manual(a), true
		changed = true
	end
	for _, id in ipairs(T.ids) do
		local an = T.an[id]
		local mxs = (T.star[an.sg] and T.star[an.sg].max) or 1
		local mxf = (T.forge[an.fg] and T.forge[an.fg].max) or 0
		local k, x = tostring(id), a.a[tostring(id)]
		if type(x) ~= "table" then x = {}; a.a[k] = x; changed = true end
		if x.star ~= mxs then x.star = mxs; changed = true end
		if x.stage ~= mxf then x.stage = mxf; changed = true end
		if type(x.u) ~= "table" then x.u = {}; changed = true end
		for i = 1, 3 do if x.u[i] ~= 0 then x.u[i] = 0; changed = true end end
	end
	for _, id in ipairs(T.relids) do
		local k = tostring(id)
		if a.lg[k] ~= 1 then a.lg[k] = 1; changed = true end
	end
	for i = 1, 3 do
		local want = T.ids[i] or -1
		if a.sk[i] ~= want then a.sk[i] = want; changed = true end
	end
	if a.rel ~= 0 then a.rel = 0; changed = true end
	if a.fate.step ~= T.nstage then a.fate.step = T.nstage; changed = true end
	if a.fate.prog ~= 0 then a.fate.prog = 0; changed = true end
	return changed
end

local function unfull(a)
	if not a.full then return false end
	local m = a.manual
	if type(m) == "table" then
		a.a, a.lg = {}, {}
		for k, x in pairs(m.a or {}) do a.a[k] = { star = x.star, stage = x.stage, u = { x.u[1], x.u[2], x.u[3] } } end
		for k, v in pairs(m.lg or {}) do a.lg[k] = v end
		a.sk = { m.sk and m.sk[1] or -1, m.sk and m.sk[2] or -1, m.sk and m.sk[3] or -1 }
		a.rel = m.rel
		a.fate = { step = m.fate and m.fate.step or 0, prog = m.fate and m.fate.prog or 0 }
	end
	a.manual, a.full = nil, nil
	R.ma_last = "tat full: tra Than thu ve tien trinh tu nang"
	return true
end

local function active(id) return S ~= nil and type(S.ma) == "table" and type(S.ma.a) == "table" and S.ma.a[tostring(id)] or nil end

local function lg_status(row, a)
	if a.lg[tostring(row.id)] == 1 then return 2 end
	for _, id in ipairs(row.ids) do
		local x = a.a[tostring(id)]
		if x == nil or x.star < row.need then return 0 end
	end
	return 1
end

local function rows_of(id)
	local T = MA.T()
	local out = {}
	for _, rid in ipairs(T.relids) do
		local r = T.rel[rid]
		for _, v in ipairs(r.ids) do if v == id then out[#out + 1] = r; break end end
	end
	return out
end

local function stone_index(T, propid)
	for i, t in ipairs(T.cfg.stones) do if t[2] == propid then return i end end
	return nil
end

local function forge_used(T, an, x)
	local used = { x.u[1], x.u[2], x.u[3] }
	local f = T.forge[an.fg]
	for s = 0, x.stage do
		local row = f ~= nil and f.rows[s] or nil
		if row ~= nil then
			for _, t in ipairs(row.cost) do
				local i = stone_index(T, t[2])
				if i ~= nil and t[3] > 0 then used[i] = used[i] + t[3] end
			end
		end
	end
	return used
end

function MA.totals()
	local T = MA.T()
	local tot = { 0, 0, 0 }
	local a = S ~= nil and S.ma or nil
	if type(a) ~= "table" or type(a.a) ~= "table" then return tot end
	local function addl(list)
		for _, kv in ipairs(list) do
			if kv[1] >= 0 and kv[1] <= 2 then tot[kv[1] + 1] = tot[kv[1] + 1] + kv[2] end
		end
	end
	for key, x in pairs(a.a) do
		local an = T.an[tonumber(key)]
		if an ~= nil and type(x) == "table" then
			local sg = T.star[an.sg]
			if sg ~= nil then
				for s = 1, math.min(math.floor(tn(x.star, 1)), sg.max) do
					if sg.rows[s] ~= nil then addl(sg.rows[s].add) end
				end
			end
			local used = forge_used(T, an, { stage = math.floor(tn(x.stage, 0)), u = type(x.u) == "table" and x.u or { 0, 0, 0 } })
			for i, kv in ipairs(T.cfg.stone_add) do
				if kv[1] >= 0 and kv[1] <= 2 then tot[kv[1] + 1] = tot[kv[1] + 1] + kv[2] * (used[i] or 0) end
			end
		end
	end

	local fa = type(a.fate) == "table" and a.fate or {}
	local step, prog = math.floor(tn(fa.step, 0)), math.floor(tn(fa.prog, 0))
	for s = 1, step do
		local nodes = T.fate[s]
		if nodes ~= nil then for _, nd in pairs(nodes) do if nd.cat == 0 then addl(nd.add) end end end
	end
	local nodes = T.fate[step + 1]
	if nodes ~= nil then
		for d, nd in pairs(nodes) do if nd.cat == 0 and d <= prog then addl(nd.add) end end
	end
	return tot
end

function MA.active()
	if not stats_on() then return false end
	local a = S ~= nil and S.ma or nil
	if type(a) ~= "table" or type(a.a) ~= "table" then return false end
	if next(a.a) ~= nil then return true end
	local fa = type(a.fate) == "table" and a.fate or nil
	return fa ~= nil and ((tonumber(fa.step) or 0) > 0 or (tonumber(fa.prog) or 0) > 0)
end

function MA.adjust(sid, tid, pn, spec, is_rec)
	if not MA.active() or type(pn) ~= "table" then return end
	local ok, err = pcall(function()
		local tot = MA.totals()
		for i = 1, 3 do
			local x = pn[i]
			if type(x) == "number" and tot[i] ~= 0 then pn[i] = math.max(0, rnd(x + tot[i])) end
		end
	end)
	if not ok then
		R.ma_errs = (R.ma_errs or 0) + 1
		if R.ma_errs <= 5 then log("loi chi so Than thu:", tostring(err)) end
	end
end

local function lg_text(id, a)
	local out = {}
	for _, r in ipairs(rows_of(id)) do out[#out + 1] = fint(lg_status(r, a)) end
	return table.concat(out, ",")
end

local function json_one(id, a)
	local x = a.a[tostring(id)]
	return string.format('{"maMouldId":%s,"star":%s,"stepsInfo":"%s,%s,%s,%s","relevantActiveStatus":"%s"}',
		fint(id), fint(x.star), fint(x.stage), fint(x.u[1]), fint(x.u[2]), fint(x.u[3]), lg_text(id, a))
end

function MA.blk_all()
	local T, a = MA.T(), st()
	local parts = {}
	for _, id in ipairs(T.ids) do if a.a[tostring(id)] ~= nil then parts[#parts + 1] = json_one(id, a) end end
	return "12675\r\n[" .. table.concat(parts, ",") .. "]"
end

function MA.blk_one(id) return "12676\r\n" .. json_one(id, st()) end

function MA.blk_skill()
	local a = st()
	return "12677\r\n" .. string.format('{"equippedMAMould":"%s,%s,%s","skillReleaseMethod":%s}', fint(a.sk[1]), fint(a.sk[2]), fint(a.sk[3]), fint(a.rel))
end

function MA.blk_fate()
	local a = st()
	local pr = {}
	for i = 1, 5 do pr[i] = (i <= a.fate.prog) and "1" or "0" end
	return "12678\r\n" .. string.format('{"step":%s,"progress":"%s"}', fint(a.fate.step), table.concat(pr, ","))
end

function MA.blk_task()
	local T, a = MA.T(), st()
	local day = os.date("%Y-%m-%d")
	local out = {}
	local t1 = T.tasks[1][1]
	if t1 ~= nil then
		local done = a.task.d1 == day
		out[#out + 1] = string.format('{"taskType":1,"status":%d,"todayNumber":%s,"totalNumber":%s,"hasGetNumber":%d}', done and 2 or 1, fint(t1.num), fint(t1.num), done and 1 or 0)
	end
	local list = T.tasks[2]
	if #list > 0 then
		local got = a.task.got2
		local cur = list[math.min(got + 1, #list)]
		out[#out + 1] = string.format('{"taskType":2,"status":%d,"todayNumber":%s,"totalNumber":%s,"hasGetNumber":%d}', got >= #list and 2 or 1, fint(cur.num), fint(cur.num), got)
	end
	return "12679\r\n[" .. table.concat(out, ",") .. "]"
end

local function blk_reward(items)
	local b = { "171", "7", fint(#items) }
	for _, it in ipairs(items) do b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3]) end
	return table.concat(b, "\r\n")
end

local function floor_props()
	if not auto_on() then return end
	for id in pairs(MA.T().props) do
		if LS.prop_get(id) < FLOOR_LOW then LS.prop_set(id, FLOOR_TOP) end
	end
end

local function can_pay(list, times)
	times = times or 1
	if auto_on() then
		local want = {}
		for _, t in ipairs(list) do
			if t[1] == 6 then want[t[2]] = (want[t[2]] or 0) + t[3] * times end
		end
		for id, n in pairs(want) do
			if LS.prop_get(id) < n then LS.prop_set(id, n + FLOOR_TOP) end
		end
	end
	local need = {}
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		need[k] = (need[k] or 0) + t[3] * times
	end
	for _, t in ipairs(list) do
		local k = t[1] .. ":" .. t[2]
		local n = need[k]
		if n ~= nil then
			if t[1] == 6 then
				if LS.prop_get(t[2]) < n then return false, ERR.items end
			elseif t[1] == 1 then
				if (S.silver or 0) < n then return false, ERR.silver end
			end
			need[k] = nil
		end
	end
	return true
end

local function pay(list, times)
	times = times or 1
	for _, t in ipairs(list) do
		local n = t[3] * times
		if t[1] == 6 then LS.prop_add(t[2], -n)
		elseif t[1] == 1 then LS.money_spend("silver", n) end
	end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if not MA.T().ok then error("khong co bang Than thu") end
	st()
	floor_props()
	return e
end

local function finish(e, seq, name, extra, stats)
	local blocks = {}
	for _, b in ipairs(extra or {}) do blocks[#blocks + 1] = b end
	if stats and LS._tl ~= nil and LS._tl.refresh_blocks ~= nil then
		LS._tl.refresh_blocks(e, blocks)
		LS._tl.queue_all(e)
		R.tl_sig_l, R.tl_sig_f = nil, nil
	end
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function animal_of(seq, name, p)
	local id = math.floor(tn(p[1], -1))
	local an = MA.T().an[id]
	if an == nil then return nil, nil, err_reply(seq, name, "LS_than_thu_khong_ton_tai", ERR.generic) end
	return id, an
end

function MA.h_init(p, seq)
	local e = ctx()
	stat_inc("ma_init")
	return reply(seq, "magical_animals_init", { MA.blk_all(), MA.blk_skill(), MA.blk_fate(), MA.blk_task() })
end

function MA.h_activate(p, seq)
	local e = ctx()
	local T, a = MA.T(), st()
	local id, an, er = animal_of(seq, "magical_animals_activate", p)
	if id == nil then return er end
	if active(id) ~= nil then return err_reply(seq, "magical_animals_activate", "LS_da_kich_hoat", ERR.generic) end
	local sg = T.star[an.sg]
	local row = sg ~= nil and sg.rows[1] or nil
	local cost = row ~= nil and row.cost ~= nil and { row.cost } or {}
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "magical_animals_activate", "LS_khong_du_manh", code) end
	pay(cost)
	a.a[tostring(id)] = { star = 1, stage = 0, u = { 0, 0, 0 } }
	R.ma_last = "kich hoat than thu " .. id
	stat_inc("ma_activate")
	local blocks = { MA.blk_one(id) }
	for _, r in ipairs(rows_of(id)) do
		for _, oid in ipairs(r.ids) do if oid ~= id and active(oid) ~= nil then blocks[#blocks + 1] = MA.blk_one(oid) end end
	end
	blocks[#blocks + 1] = MA.blk_skill()
	return finish(e, seq, "magical_animals_activate", blocks, true)
end

function MA.h_star(p, seq)
	local e = ctx()
	local T, a = MA.T(), st()
	local id, an, er = animal_of(seq, "magical_animals_advance_star", p)
	if id == nil then return er end
	local x = active(id)
	if x == nil then return err_reply(seq, "magical_animals_advance_star", "LS_chua_kich_hoat", ERR.generic) end
	local sg = T.star[an.sg]
	if sg == nil or x.star >= sg.max then return err_reply(seq, "magical_animals_advance_star", "LS_da_toi_sao_toi_da", ERR.rank_max) end
	local row = sg.rows[x.star + 1]
	local cost = row ~= nil and row.cost ~= nil and { row.cost } or {}
	local okp, code = can_pay(cost)
	if not okp then return err_reply(seq, "magical_animals_advance_star", "LS_khong_du_manh", code) end
	pay(cost)
	x.star = x.star + 1
	R.ma_last = "nang sao than thu " .. id .. " -> " .. x.star
	stat_inc("ma_star")
	local blocks = { MA.blk_one(id) }
	for _, r in ipairs(rows_of(id)) do
		for _, oid in ipairs(r.ids) do if oid ~= id and active(oid) ~= nil then blocks[#blocks + 1] = MA.blk_one(oid) end end
	end
	return finish(e, seq, "magical_animals_advance_star", blocks, true)
end

function MA.h_rebirth(p, seq)
	local e = ctx()
	local T = MA.T()
	local id, an, er = animal_of(seq, "magical_animals_steps_rebirth", p)
	if id == nil then return er end
	local x = active(id)
	if x == nil then return err_reply(seq, "magical_animals_steps_rebirth", "LS_chua_kich_hoat", ERR.generic) end
	local used = forge_used(T, an, x)
	local total = 0
	for i = 1, 3 do total = total + used[i] end
	if total <= 0 then return err_reply(seq, "magical_animals_steps_rebirth", "LS_chua_ren", ERR.generic) end
	local items = {}
	for i, t in ipairs(T.cfg.stones) do
		if (used[i] or 0) > 0 then
			LS.prop_add(t[2], used[i])
			items[#items + 1] = { t[2], 6, used[i] }
		end
	end
	x.stage, x.u = 0, { 0, 0, 0 }
	R.ma_last = "dat lai bac than thu " .. id
	stat_inc("ma_rebirth")
	return finish(e, seq, "magical_animals_steps_rebirth", { MA.blk_one(id), blk_reward(items) }, true)
end

function MA.h_forge(p, seq)
	local e = ctx()
	local T = MA.T()
	local id, an, er = animal_of(seq, "magical_animals_forging", p)
	if id == nil then return er end
	local x = active(id)
	if x == nil then return err_reply(seq, "magical_animals_forging", "LS_chua_kich_hoat", ERR.generic) end
	local idx = math.floor(tn(p[2], -1)) + 1
	local ftype = math.floor(tn(p[3], -1))
	local stone = T.cfg.stones[idx]
	if stone == nil or ftype < 0 or ftype > 3 then return err_reply(seq, "magical_animals_forging", "LS_tham_so_khong_hop_le", ERR.generic) end
	local f = T.forge[an.fg]
	local nextrow = f ~= nil and f.rows[x.stage + 1] or nil
	if nextrow == nil then return err_reply(seq, "magical_animals_forging", "LS_da_toi_bac_toi_da", ERR.rank_max) end
	local need = { 0, 0, 0 }
	for _, t in ipairs(nextrow.cost) do
		local i = stone_index(T, t[2])
		if i ~= nil then need[i] = need[i] + t[3] end
	end
	local full = x.u[idx] >= need[idx]
	local n
	if ftype == 0 then
		if full then return err_reply(seq, "magical_animals_forging", "LS_thanh_da_day", ERR.generic) end
		n = 1
	elseif ftype == 1 then
		n = 1
	elseif ftype == 2 then
		n = need[idx] - x.u[idx]
		if n <= 0 then return err_reply(seq, "magical_animals_forging", "LS_thanh_da_day", ERR.generic) end
	else
		n = math.min(forge_cap(), math.max(LS.prop_get(stone[2]), 1))
	end
	local cost = { { 6, stone[2], stone[3] } }
	local okp, code = can_pay(cost, n)
	if not okp then return err_reply(seq, "magical_animals_forging", "LS_khong_du_da", code) end
	pay(cost, n)
	x.u[idx] = x.u[idx] + n * stone[3]

	local guard = 0
	while guard < 200 do
		guard = guard + 1
		local row = f.rows[x.stage + 1]
		if row == nil then break end
		local nd = { 0, 0, 0 }
		for _, t in ipairs(row.cost) do
			local i = stone_index(T, t[2])
			if i ~= nil then nd[i] = nd[i] + t[3] end
		end
		if not (x.u[1] >= nd[1] and x.u[2] >= nd[2] and x.u[3] >= nd[3]) then break end
		for i = 1, 3 do x.u[i] = x.u[i] - nd[i] end
		x.stage = x.stage + 1
	end
	if f.rows[x.stage + 1] == nil then x.u = { 0, 0, 0 } end
	R.ma_last = "than ren " .. id .. " bac " .. x.stage
	stat_inc("ma_forge")
	return finish(e, seq, "magical_animals_forging", { MA.blk_one(id) }, true)
end

function MA.h_relevant(p, seq)
	local e = ctx()
	local a = st()
	local id, an, er = animal_of(seq, "magical_animals_relevant_active", p)
	if id == nil then return er end
	if active(id) == nil then return err_reply(seq, "magical_animals_relevant_active", "LS_chua_kich_hoat", ERR.generic) end
	local idx = math.floor(tn(p[2], -1)) + 1
	local row = rows_of(id)[idx]
	if row == nil then return err_reply(seq, "magical_animals_relevant_active", "LS_lien_ket_khong_ton_tai", ERR.generic) end
	local s = lg_status(row, a)
	if s == 2 then return err_reply(seq, "magical_animals_relevant_active", "LS_lien_ket_da_kich_hoat", ERR.generic) end
	if s ~= 1 then return err_reply(seq, "magical_animals_relevant_active", "LS_chua_du_dieu_kien_lien_ket", ERR.generic) end
	a.lg[tostring(row.id)] = 1
	R.ma_last = "lien ket " .. row.id
	stat_inc("ma_relevant")
	local blocks = {}
	for _, oid in ipairs(row.ids) do if active(oid) ~= nil then blocks[#blocks + 1] = MA.blk_one(oid) end end
	return finish(e, seq, "magical_animals_relevant_active", blocks, false)
end

function MA.h_set_skill(p, seq)
	local e = ctx()
	local a = st()
	local raw = tostring(p[1] or "")
	local ids = {}
	for v in string.gmatch(raw, "[^,]+") do ids[#ids + 1] = math.floor(tn(v, -9999)) end
	if #ids ~= 3 then return err_reply(seq, "magical_animals_set_skill", "LS_tham_so_khong_hop_le", ERR.generic) end
	local used = {}
	for i = 1, 3 do
		local v = ids[i]
		if v ~= -1 then
			if active(v) == nil then return err_reply(seq, "magical_animals_set_skill", "LS_than_thu_chua_kich_hoat", ERR.generic) end
			if used[v] then return err_reply(seq, "magical_animals_set_skill", "LS_than_thu_trung", ERR.generic) end
			used[v] = true
		end
	end
	for i = 1, 3 do a.sk[i] = ids[i] end
	R.ma_last = "dat ky nang " .. raw
	stat_inc("ma_skill")
	return finish(e, seq, "magical_animals_set_skill", { MA.blk_skill() }, false)
end

function MA.h_release(p, seq)
	local e = ctx()
	local a = st()
	local m = math.floor(tn(p[1], -1))
	if m ~= 0 and m ~= 1 then return err_reply(seq, "magical_animals_set_skill_release_method", "LS_tham_so_khong_hop_le", ERR.generic) end
	a.rel = m
	stat_inc("ma_release")
	return finish(e, seq, "magical_animals_set_skill_release_method", { MA.blk_skill() }, false)
end

function MA.h_fate(p, seq)
	local e = ctx()
	local T, a = MA.T(), st()
	local fa = a.fate
	if fa.step >= T.nstage then return err_reply(seq, "magical_animals_activate_fate", "LS_da_toi_tang_cuoi", ERR.rank_max) end
	local nodes = T.fate[fa.step + 1]
	if nodes == nil then return err_reply(seq, "magical_animals_activate_fate", "LS_khong_co_tang", ERR.generic) end
	local n = 0
	while fa.prog < 5 do
		local nd = nodes[fa.prog + 1]
		if nd == nil then break end
		local cost = nd.cost ~= nil and { nd.cost } or {}
		local okp, code = can_pay(cost)
		if not okp then
			if n == 0 then return err_reply(seq, "magical_animals_activate_fate", "LS_khong_du_da_thien_menh", code) end
			break
		end
		pay(cost)
		fa.prog = fa.prog + 1
		n = n + 1
	end
	local maxn = 0
	for d in pairs(nodes) do if d > maxn then maxn = d end end
	if fa.prog >= maxn then fa.step = fa.step + 1; fa.prog = 0 end
	R.ma_last = "thien menh tang " .. fa.step .. " (+" .. n .. ")"
	stat_inc("ma_fate", n)
	return finish(e, seq, "magical_animals_activate_fate", { MA.blk_fate() }, true)
end

function MA.h_task(p, seq)
	local e = ctx()
	local T, a = MA.T(), st()
	local ty = math.floor(tn(p[1], -1))
	local day = os.date("%Y-%m-%d")
	local rw
	if ty == 1 then
		local t1 = T.tasks[1][1]
		if t1 == nil then return err_reply(seq, "magical_animals_activate_get_fate_task_reward", "LS_khong_co_nhiem_vu", ERR.generic) end
		if a.task.d1 == day then return err_reply(seq, "magical_animals_activate_get_fate_task_reward", "LS_da_nhan", ERR.generic) end
		rw = t1.rw
		a.task.d1 = day
	elseif ty == 2 then
		local list = T.tasks[2]
		if a.task.got2 >= #list then return err_reply(seq, "magical_animals_activate_get_fate_task_reward", "LS_da_nhan_het", ERR.generic) end
		rw = list[a.task.got2 + 1].rw
		a.task.got2 = a.task.got2 + 1
	else
		return err_reply(seq, "magical_animals_activate_get_fate_task_reward", "LS_khong_co_nhiem_vu", ERR.generic)
	end
	local items = {}
	if rw ~= nil and rw[1] == 6 then LS.prop_add(rw[2], rw[3]); items[1] = { rw[2], 6, rw[3] } end
	R.ma_last = "nhan nhiem vu thien menh " .. ty
	stat_inc("ma_task")
	return finish(e, seq, "magical_animals_activate_get_fate_task_reward", { blk_reward(items), MA.blk_task() }, false)
end

function MA.tick(e)
	if S == nil or not R.ready or not MA.T().ok then return end
	local old = S.ma
	if not full_on() and (type(old) ~= "table" or not old.full) then return end
	R.ma_n = (R.ma_n or 0) + 1
	if R.ma_n % 15 ~= 1 and not R.ma_now then return end
	R.ma_now = nil
	local a = st()
	-- KHONG dung "full_on() and make_full(a) or unfull(a)": khi FULL da bat san, make_full tra false
	-- (khong co gi doi) nen bieu thuc and/or roi xuong unfull() va TAT FULL; 15 nhip sau lai bat lai
	-- -> chi so tuong nhay tang roi giam lien tuc. Phai dung if/else.
	local changed
	if full_on() then changed = make_full(a) else changed = unfull(a) end
	if not changed then return end
	if LS._tl ~= nil and LS._tl.queue_all ~= nil then pcall(LS._tl.queue_all, e); R.tl_sig_l, R.tl_sig_f = nil, nil end
	mark()
end

function MA.apply_now(e)
	R.ma_now = true
	if e ~= nil then MA.tick(e) end
end
MA.full_on = full_on

function MA.dump_line()
	local a = S ~= nil and S.ma or nil
	if type(a) ~= "table" or type(a.a) ~= "table" then return "[LS than thu] chua khoi tao" end
	local n, stars, stage = 0, 0, 0
	for _, x in pairs(a.a) do
		if type(x) == "table" then n = n + 1; stars = stars + (tonumber(x.star) or 0); stage = stage + (tonumber(x.stage) or 0) end
	end
	local fa = type(a.fate) == "table" and a.fate or {}
	return "[LS than thu] " .. n .. " than thu | tong sao " .. stars .. " | tong bac ren " .. stage .. " | thien menh tang " .. (tonumber(fa.step) or 0) .. "+" .. (tonumber(fa.prog) or 0)
		.. " | full " .. (full_on() and "BAT" or "TAT") .. " | tu bu " .. (auto_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.ma_last ~= nil and (" | cuoi: " .. R.ma_last) or "")
end

function MA.reset()
	S.ma = nil
	R.ma_t = nil
	mark()
end

function MA.on_world(e)
	R.ma_t = nil
	R.ma_n = 0
	if S ~= nil and S.ma ~= nil and type(S.ma) ~= "table" then S.ma = nil end
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if MA.active() then return true end
			return td(e, sid, tid, is_rec)
		end
	end
end

LS._ma = MA

end
init_ma()
end

do
local function init_lv()

local LV = {}
local IDS = { 193, 199, 200 }

local function on() return not (type(S.cfg) == "table" and S.cfg.lv_open == false) end

function LV.add_ids(list)
	for _, id in ipairs(list or {}) do
		id = math.floor(tonumber(id) or 0)
		local have = false
		for _, x in ipairs(IDS) do if x == id then have = true end end
		if id > 0 and not have then IDS[#IDS + 1] = id end
	end
end
function LV.ids() local o = {}; for i, x in ipairs(IDS) do o[i] = x end; return o end

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end

local function level_col()
	local sc = G("fun_open_condition")
	if type(sc) == "table" and tonumber(sc.level) ~= nil then return math.floor(tonumber(sc.level)) end
	return 4
end

function LV.apply(e)
	local d = G("dms")
	local t = type(d) == "table" and d["fun_open_condition"] or nil
	if type(t) ~= "table" then return 0 end
	local col = level_col()

	local orig = rawget(_G, "__LS_LV_ORIG")
	if type(orig) ~= "table" then orig = {}; rawset(_G, "__LS_LV_ORIG", orig) end
	R.lv_orig = orig
	local n = 0
	for _, id in ipairs(IDS) do
		local row = t[id]
		if on() then
			if type(row) == "string" then
				local c = split_tab(row)
				local lv = tonumber(c[col])
				if lv ~= nil and lv > 1 then
					if R.lv_orig[id] == nil then R.lv_orig[id] = { s = row, lv = lv } end
					c[col] = "1"
					t[id] = table.concat(c, "\t")
					n = n + 1
				end
			elseif type(row) == "table" then
				local lv = tonumber(row[col])
				if lv ~= nil and lv > 1 then
					if R.lv_orig[id] == nil then R.lv_orig[id] = { v = row[col], lv = lv } end
					row[col] = "1"
					n = n + 1
				end
			end
		else
			local o = R.lv_orig[id]
			if o ~= nil then
				if o.s ~= nil then t[id] = o.s
				elseif type(row) == "table" then row[col] = o.v end
				R.lv_orig[id] = nil
				n = n + 1
			end
		end
	end
	local fs = type(e) == "table" and e.function_open_states or nil
	if on() and type(fs) == "table" then
		for _, id in ipairs(IDS) do
			local k = tostring(id)
			if fs[k] ~= nil and tonumber(fs[k]) ~= 1 then
				R.lv_states = R.lv_states or {}
				if R.lv_states[k] == nil then R.lv_states[k] = fs[k] end
				fs[k] = "1"
				n = n + 1
			end
		end
	elseif type(fs) == "table" and R.lv_states ~= nil then
		for k, v in pairs(R.lv_states) do fs[k] = v end
		R.lv_states = nil
	end
	if n > 0 then R.lv_last = n end
	return n
end

function LV.fix_battle()
	local BO = G("BattleObject")
	if type(BO) ~= "table" or type(BO.addPropertyValue) ~= "function" or rawget(BO, "_ls_this_fix") then return false end
	local EM = G("EquipmentMould")
	local T4 = (type(EM) == "table" and tonumber(EM.PROPERTY_TYPE_LIFE_ADDITIONAL_PERCENTAGE)) or 4
	local orig = BO.addPropertyValue
	BO.addPropertyValue = function(self, propertyType, propertyValue)
		if propertyType == T4 and rawget(_G, "this") == nil then
			local fo = self.fightObject
			local base = (type(fo) == "table" and tonumber(fo.healthPoint)) or tonumber(self.healthMaxPoint) or 0
			local addValue = base * (tonumber(propertyValue) or 0)
			self.healthMaxPoint = (tonumber(self.healthMaxPoint) or 0) + addValue
			if type(self.addHealthPoint) == "function" then
				self:addHealthPoint(addValue)
			else
				self.healthPoint = (tonumber(self.healthPoint) or 0) + addValue
				if tonumber(self.copyHe) ~= nil then self.copyHe = self.copyHe + addValue end
			end
			R.lv_this = (R.lv_this or 0) + 1
			return
		end
		return orig(self, propertyType, propertyValue)
	end
	rawset(BO, "_ls_this_fix", true)
	return true
end

function LV.fix_battle2()
	local BS = G("BattleSkill")
	if type(BS) ~= "table" or type(BS.executeNextSkillInfluence) ~= "function" or rawget(BS, "_ls_next_fix") then return false end
	local orig = BS.executeNextSkillInfluence
	BS.executeNextSkillInfluence = function(self, a1, a2, a3, a4, a5, inst, ...)
		local si = self.skillInfluence
		if inst == nil then
			if si == nil then R.lv_next = (R.lv_next or 0) + 1; return false end
			if type(si) == "table" and si.nextSkillInfluence == nil then
				si.nextSkillInfluence = 0
				R.lv_next = (R.lv_next or 0) + 1
			end
		elseif si == nil then

			self.skillInfluence = { level = (type(inst) == "table" and inst.level) or 1, nextSkillInfluence = 0 }
			R.lv_next = (R.lv_next or 0) + 1
			local res = { pcall(orig, self, a1, a2, a3, a4, a5, inst, ...) }
			self.skillInfluence = nil
			if not res[1] then error(res[2], 0) end
			return res[2]
		end
		return orig(self, a1, a2, a3, a4, a5, inst, ...)
	end
	rawset(BS, "_ls_next_fix", true)
	return true
end

function LV.fix_battle3()
	local BO, BS = G("BattleObject"), G("BattleSkill")
	if type(BO) ~= "table" or type(BS) ~= "table" or type(BO.influenceTalentJudgeResults) ~= "function" or rawget(BO, "_ls_bs_fix") then return false end
	local orig = BO.influenceTalentJudgeResults
	local proto = nil
	BO.influenceTalentJudgeResults = function(self, jo, fm, ui, ao, bo, bc, aos, bos, bskill, rb, ...)
		if type(bskill) == "table" and getmetatable(bskill) == nil then
			if proto == nil then
				local okp, inst = pcall(function() return BS:new() end)
				proto = okp and inst or BS
			end
			setmetatable(bskill, { __index = proto })
			R.lv_bs = (R.lv_bs or 0) + 1
		end
		return orig(self, jo, fm, ui, ao, bo, bc, aos, bos, bskill, rb, ...)
	end
	rawset(BO, "_ls_bs_fix", true)
	return true
end

function LV.fix_all()
	pcall(LV.fix_battle)
	pcall(LV.fix_battle2)
	pcall(LV.fix_battle3)
end

function LV.on_world(e)
	local ok, err = pcall(LV.apply, e)
	if not ok then log("loi mo khoa theo cap:", tostring(err)) end
	LV.fix_all()
end

function LV.tick(e)
	R.lv_n = (R.lv_n or 0) + 1
	if R.lv_n % 30 ~= 1 then return end
	LV.apply(e)
	LV.fix_all()
end

function LV.dump_line()
	local d = G("dms")
	local t = type(d) == "table" and d["fun_open_condition"] or nil
	local col = level_col()
	local parts = {}
	for _, id in ipairs(IDS) do
		local row = type(t) == "table" and t[id] or nil
		local lv
		if type(row) == "string" then lv = split_tab(row)[col] elseif type(row) == "table" then lv = row[col] end
		local o = R.lv_orig ~= nil and R.lv_orig[id] or nil
		parts[#parts + 1] = id .. "=" .. tostring(lv) .. (o ~= nil and ("(goc " .. tostring(o.lv) .. ")") or "")
	end
	return "[LS mo khoa cap] " .. (on() and "BAT" or "TAT") .. " | " .. table.concat(parts, " ") .. " | sua loi tran %HP: " .. tostring(R.lv_this or 0) .. " / nextSkill: " .. tostring(R.lv_next or 0) .. " / battleSkill: " .. tostring(R.lv_bs or 0)
end

LS._lv = LV

end
init_lv()
end

if LS._lv ~= nil and LS._lv.add_ids ~= nil then LS._lv.add_ids({ 194 }) end

do
local function init_sg()

local SG = {}
local MAXG = 4
local FLOOR_LOW, FLOOR_TOP = 5000, 99999

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end
local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end
local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end
local function nums(s)
	local o = {}
	for v in string.gmatch(tostring(s or ""), "%-?%d+") do o[#o + 1] = tonumber(v) end
	return o
end
local function triples(s)
	local o = {}
	for a, b, c in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?%d+)%s*,%s*(%-?%d+)") do o[#o + 1] = { tonumber(a), tonumber(b), tonumber(c) } end
	return o
end
local function plist(s)
	local o = {}
	for a, b in string.gmatch(tostring(s or ""), "(%-?%d+)%s*,%s*(%-?[%d%.]+)") do o[#o + 1] = { tonumber(a), tonumber(b) } end
	return o
end
local function cfg_map(id)
	local pc = dtab("play_config")
	local o, keys = {}, {}
	if pc == nil then return o, keys end
	local sc = G("play_config")
	local col = (type(sc) == "table" and tonumber(sc.param)) or 4
	local row = cells(pc[id])
	if row == nil or tonumber(row[1]) ~= id then
		for _, r in pairs(pc) do
			local c = cells(r)
			if c ~= nil and tonumber(c[1]) == id then row = c; break end
		end
	end
	if row == nil then return o, keys end
	for _, kv in ipairs(plist(row[col])) do o[math.floor(kv[1])] = kv[2]; keys[#keys + 1] = math.floor(kv[1]) end
	table.sort(keys)
	return o, keys
end
local function fnum(x)
	x = tonumber(x) or 0
	if x == math.floor(x) and math.abs(x) < 1e15 then return fint(x) end
	local s = string.format("%.6f", x)
	s = string.gsub(s, "0+$", "")
	s = string.gsub(s, "%.$", "")
	return s
end

local function full_on() return type(S.cfg) == "table" and S.cfg.sg_full == true end
local function auto_on() return not (type(S.cfg) == "table" and S.cfg.sg_auto == false) end
local function stats_on()
	if type(S.cfg) == "table" and (S.cfg.sg_stats == false or S.cfg.tl_stats == false) then return false end
	return true
end

function SG.T()
	local T = R.sg_t
	if T ~= nil then return T end
	T = { ok = false, g = {}, ids = {}, unlock = {}, lv = {}, props = {}, p_mega = {}, p_ord = {}, p_abi = {} }
	R.sg_t = T
	local gt, ut, lt = dtab("soul_guard_group_mould"), dtab("soul_guard_unlock_mould"), dtab("soul_guard_level_mould")
	if gt == nil or lt == nil then return T end
	for _, row in pairs(gt) do
		local r = cells(row)
		local id = r ~= nil and tonumber(r[1]) or nil
		if id ~= nil then
			id = math.floor(id)
			T.g[id] = { id = id, conds = nums(r[3]), max = 0, rows = {} }
			T.ids[#T.ids + 1] = id
		end
	end
	table.sort(T.ids)
	for _, row in pairs(ut or {}) do
		local r = cells(row)
		local id = r ~= nil and tonumber(r[1]) or nil
		if id ~= nil then T.unlock[math.floor(id)] = { ty = math.floor(tonumber(r[2]) or 0), a = tonumber(r[3]) or 0, b = tonumber(r[4]) or 0 } end
	end
	for _, row in pairs(lt) do
		local r = cells(row)
		local id = r ~= nil and tonumber(r[1]) or nil
		local gid = r ~= nil and tonumber(r[5]) or nil
		if id ~= nil and gid ~= nil and T.g[math.floor(gid)] ~= nil then
			local g = T.g[math.floor(gid)]
			local lv = math.floor(tonumber(r[2]) or 0)
			local x = { id = math.floor(id), lv = lv, cost = triples(r[3]), cap = plist(r[4]) }
			g.rows[lv] = x
			if lv > g.max then g.max = lv end
			for _, c in ipairs(x.cost) do if c[1] == 6 then T.props[c[2]] = true end end
		end
	end
	T.p_abi, T.k_abi = cfg_map(156)
	T.p_mega, T.k_mega = cfg_map(157)
	T.p_ord, T.k_ord = cfg_map(158)
	T.ok = #T.ids > 0
	return T
end

local function look(map, keys, k)
	k = math.floor(tonumber(k) or 0)
	if map[k] ~= nil then return map[k] end
	if keys ~= nil and #keys > 0 and k > keys[#keys] then return map[keys[#keys]] or 0 end
	return 0
end

local function ship_of(e, tid)
	local best
	for _, sh in pairs(e.user_ship or {}) do
		if type(sh) == "table" and tonumber(sh.ship_template_id) == tid then
			if best == nil or (tonumber(sh.hero_fight) or 0) > (tonumber(best.hero_fight) or 0) then best = sh end
		end
	end
	return best
end

local function mega_row(tid)
	R.sg_mrow = R.sg_mrow or {}
	local c = R.sg_mrow[tid]
	if c ~= nil then return c or nil end
	local f = G("GetMegeDataByShipID")
	local d
	if type(f) == "function" then
		local ok, r = pcall(f, tid, false)
		if ok then d = r end
	else
		local dm = G("dms")
		local sc = G("mega_ship")
		if type(dm) == "table" and type(dm.searchs) == "function" and type(sc) == "table" and sc.shipID ~= nil then
			local ok, r = pcall(dm.searchs, dm["mega_ship"], sc.shipID, tid)
			if ok then d = r end
		end
	end
	if type(d) == "table" and type(d[1]) == "table" then
		c = { pages = tonumber(d[1][7]) or 0, abi = tonumber(d[1][8]) }
	else
		c = false
	end
	R.sg_mrow[tid] = c
	return c or nil
end
local function mega_ok(tid) return mega_row(tid) ~= nil end

local function mega_parse(info)
	local js = G("json")
	local n, top = 0, 0
	if type(info) == "string" and type(js) == "table" and type(js.decode) == "function" then
		local ok, d = pcall(js.decode, info)
		info = ok and d or nil
	end
	if type(info) == "table" and type(info.megaLevel) == "table" then
		for k, lv in pairs(info.megaLevel) do
			n = n + 1
			if tostring(k) == "8" then top = tonumber(lv) or 0 end
		end
	end
	return { n = n, top = top }
end
local function mega_map(e)
	local m = {}
	local cache = R.sg_mcache
	if cache == nil or (R.sg_mcache_n or 0) > 4000 then cache = {}; R.sg_mcache = cache; R.sg_mcache_n = 0 end
	for _, v in pairs(e.mega_info or {}) do
		if type(v) == "table" and v.shipId ~= nil then
			local info = v.info
			local x
			if type(info) == "string" then
				x = cache[info]
				if x == nil then x = mega_parse(info); cache[info] = x; R.sg_mcache_n = (R.sg_mcache_n or 0) + 1 end
			else
				x = mega_parse(info)
			end
			m[tostring(v.shipId)] = x
		end
	end
	return m
end

local function mega_pages(e, sh, mm)
	mm = mm or mega_map(e)
	local x = mm[tostring(sh.ship_id)]
	if x == nil then return 0, 0 end
	return x.n, x.top
end

local function ability_of(e, sh, tid, mm)
	local ab = mnum(tid, "ability", 0) or 0
	local md = mega_row(tid)
	if md ~= nil and md.pages == 8 and md.abi ~= nil then
		local n, top = mega_pages(e, sh, mm)
		if n == 8 and top == 10 then return md.abi end
	end
	return ab
end

local function in_formation(e)
	local set = {}
	for i = 2, 7 do
		local v = type(e.formetion) == "table" and e.formetion[i] or nil
		if v ~= nil and tostring(v) ~= "0" and tostring(v) ~= "" then
			local sh = e.user_ship and e.user_ship[tostring(v)] or nil
			if type(sh) == "table" then set[tonumber(sh.ship_template_id) or -1] = true end
		end
	end
	return set
end

function SG.value(e, gid, lv, tid, mm)
	local T = SG.T()
	local g = T.g[gid]
	local out = { base = { 0, 0, 0 }, fin = { 0, 0, 0 }, ext = { 0, 0, 0 }, types = { 1, 2, 0 } }
	if g == nil then return out end
	local row = g.rows[lv]
	local caps = { 0, 0, 0 }
	if row ~= nil then
		local tys = {}
		for i, kv in ipairs(row.cap) do
			tys[i] = kv[1]
			if kv[1] == 1 then caps[1] = kv[2] elseif kv[1] == 2 then caps[2] = kv[2] elseif kv[1] == 0 then caps[3] = kv[2] end
		end
		if #tys == 3 then out.types = tys end
	end
	local sh = (tid ~= nil and tid > 0) and ship_of(e, tid) or nil
	if sh == nil then return out end
	local st = { tonumber(sh.ship_courage) or 0, tonumber(sh.ship_intellect) or 0, tonumber(sh.ship_health) or 0 }
	for i = 1, 3 do out.base[i] = math.max(0, math.min(st[i], caps[i])) end
	mm = mm or mega_map(e)
	local pages = mega_pages(e, sh, mm)
	out.ext[1] = (pages > 0) and look(T.p_mega, T.k_mega, pages) or 0
	out.ext[2] = look(T.p_ord, T.k_ord, tonumber(sh.Order) or 0)
	out.ext[3] = look(T.p_abi, T.k_abi, ability_of(e, sh, tid, mm))
	local mul = 1 + out.ext[1] + out.ext[2] + out.ext[3]
	for i = 1, 3 do out.fin[i] = rnd(out.base[i] * mul) end
	return out
end

local function rec_guards()
	local g = {}
	for k, x in pairs(R.sg_rec_raw or {}) do
		local gid = tonumber(k)
		if gid ~= nil and type(x) == "table" then
			g[tostring(math.floor(gid))] = { lv = math.floor(tonumber(x.level) or 0), ship = math.floor(tonumber(x.onUseShipMouldId) or -1), auto = true }
		end
	end
	return g
end

local function copy_guards(src)
	local g = {}
	for k, x in pairs(src or {}) do
		if type(x) == "table" and tonumber(k) ~= nil then
			g[tostring(k)] = { lv = math.floor(tonumber(x.lv) or 0), ship = math.floor(tonumber(x.ship) or -1), auto = x.auto and true or nil }
		end
	end
	return g
end

local function st()
	local a = S.sg
	if type(a) ~= "table" or a.v ~= 1 then
		a = { v = 1, g = rec_guards(), mig16 = true }
		S.sg = a
		mark()
	end
	if type(a.g) ~= "table" then a.g = {} end
	for k, x in pairs(a.g) do
		if type(x) ~= "table" or tonumber(k) == nil then a.g[k] = nil
		else
			x.lv = math.max(0, math.floor(tonumber(x.lv) or 0))
			x.ship = math.floor(tonumber(x.ship) or -1)
		end
	end
	return a
end

local function guard_ships(a, except)
	local set = {}
	for k, x in pairs(a.g) do
		if k ~= except and type(x) == "table" and (tonumber(x.ship) or -1) > 0 then set[x.ship] = true end
	end
	return set
end

local function pick_hero(e, a, gid)
	local T = SG.T()
	local g = T.g[gid]
	local lv = g ~= nil and g.max or 30
	local busy = guard_ships(a, tostring(gid))
	local form = in_formation(e)
	local best, bscore = nil, -1
	local seen = {}
	local mm = mega_map(e)
	for _, sh in pairs(e.user_ship or {}) do
		local tid = type(sh) == "table" and tonumber(sh.ship_template_id) or nil
		if tid ~= nil and not seen[tid] and not busy[tid] and not form[tid] and tonumber(sh.captain_type) ~= 0 then
			seen[tid] = true
			if mega_ok(tid) then
				local v = SG.value(e, gid, lv, tid, mm)
				local score = (v.fin[1] + v.fin[2]) * 0.425 + v.fin[3] * 0.085
				if score > bscore then best, bscore = tid, score end
			end
		end
	end
	return best or -1
end

local function roster_sig(e)
	local n, s = 0, 0
	for _, sh in pairs(e.user_ship or {}) do
		if type(sh) == "table" then
			n = n + 1
			s = s + (tonumber(sh.ship_template_id) or 0) * 31 + (tonumber(sh.Order) or 0) * 7 + (tonumber(sh.StarRating) or 0)
		end
	end
	local f = {}
	for i = 2, 7 do f[#f + 1] = tostring(type(e.formetion) == "table" and e.formetion[i] or "") end
	return n .. ":" .. s .. ":" .. table.concat(f, ",")
end

local function make_full(a, e)
	local T = SG.T()
	local changed = false
	if not a.full then
		a.manual, a.full, a.mig16 = copy_guards(a.g), true, true
		changed = true
	end
	for _, gid in ipairs(T.ids) do
		local k = tostring(gid)
		local x = a.g[k]
		if x == nil then x = { lv = 0, ship = -1, auto = true }; a.g[k] = x; changed = true end
		local mx = T.g[gid].max
		if x.lv < mx then x.lv = mx; changed = true end
	end

	if R.inject ~= nil or R.grant ~= nil then return changed end
	local rs = roster_sig(e)
	local repick = (rs ~= R.sg_roster)
	R.sg_roster = rs
	local form = in_formation(e)
	for _, gid in ipairs(T.ids) do
		local x = a.g[tostring(gid)]
		if x.ship <= 0 then x.auto = true end
		if x.auto then
			local present = x.ship > 0 and ship_of(e, x.ship) ~= nil
			if x.ship <= 0 or not present or form[x.ship] or repick then
				local nt = pick_hero(e, a, gid)
				if nt ~= x.ship then x.ship = nt; changed = true end
			end
		end
	end
	return changed
end

local function all_max(a)
	local T = SG.T()
	if #T.ids == 0 then return false end
	for _, gid in ipairs(T.ids) do
		local x = a.g[tostring(gid)]
		if type(x) ~= "table" or x.lv < T.g[gid].max then return false end
	end
	return true
end

local function unfull(a)
	if a.mig16 == nil then
		a.mig16 = true
		mark()

		if a.full == nil and all_max(a) and not (type(S.cfg) == "table" and S.cfg.sg_full == false) then
			a.full, a.manual = true, rec_guards()
			log("Soul Guard: bo FULL cua ban truoc -> ve trang thai luc dang nhap de tu nang")
		end
	end
	if not a.full then return false end
	a.g = copy_guards(a.manual)
	local n = 0
	for _ in pairs(a.g) do n = n + 1 end
	a.manual, a.full = nil, nil
	R.sg_last = "tat full: tra Soul Guard ve tien trinh tu nang (" .. n .. " thu ve mo)"
	mark()
	return true
end

local function entry(e, gid, x, mm)
	return SG.value(e, gid, x.lv, x.ship, mm)
end

function SG.json(e)
	local a = st()
	local parts = {}
	local T = SG.T()
	local mm = mega_map(e)
	for _, gid in ipairs(T.ids) do
		local x = a.g[tostring(gid)]
		if x ~= nil then
			local v = entry(e, gid, x, mm)
			local fin, base = {}, {}
			for i = 1, 3 do
				fin[i] = "[" .. fint(v.types[i]) .. "," .. fnum(v.fin[i]) .. "]"
				base[i] = "[" .. fint(v.types[i]) .. "," .. fnum(v.base[i]) .. "]"
			end
			parts[#parts + 1] = string.format('"%d":{"level":%s,"onUseShipMouldId":%s,"addFinalProperty":[%s],"addBaseProperty":[%s],"addExtraPropertyPercent":[%s,%s,%s]}',
				gid, fint(x.lv), fint(x.ship), table.concat(fin, ","), table.concat(base, ","), fnum(v.ext[1]), fnum(v.ext[2]), fnum(v.ext[3]))
		end
	end
	return "{" .. table.concat(parts, ",") .. "}", #parts
end

function SG.table(e)
	local a = st()
	local T = SG.T()
	local o, n = {}, 0
	local mm = mega_map(e)
	for _, gid in ipairs(T.ids) do
		local x = a.g[tostring(gid)]
		if x ~= nil then
			local v = entry(e, gid, x, mm)
			local fin, base = {}, {}
			for i = 1, 3 do fin[i] = { v.types[i], v.fin[i] }; base[i] = { v.types[i], v.base[i] } end
			o[tostring(gid)] = { level = x.lv, onUseShipMouldId = x.ship, addFinalProperty = fin, addBaseProperty = base,
				addExtraPropertyPercent = { v.ext[1], v.ext[2], v.ext[3] } }
			n = n + 1
		end
	end
	return o, n
end

local function totals_now(e)
	local a = st()
	local tot = { 0, 0, 0 }
	local mm = mega_map(e)
	for k, x in pairs(a.g) do
		local gid = tonumber(k)
		if gid ~= nil and x.ship > 0 then
			local v = SG.value(e, gid, x.lv, x.ship, mm)
			tot[1] = tot[1] + v.fin[3]; tot[2] = tot[2] + v.fin[1]; tot[3] = tot[3] + v.fin[2]
		end
	end
	return tot
end

function SG.publish(e)
	local o, n = SG.table(e)
	if n == 0 or o["1"] == nil then
		e.soul_warding_formation_hero = nil
		rawset(_G, "__LS_SG_PUB", nil)
	else
		e.soul_warding_formation_hero = o
		rawset(_G, "__LS_SG_PUB", o)
	end
	R.sg_pub = (R.sg_pub or 0) + 1
	R.sg_tot = totals_now(e)
end

local function same_tot(a, b)
	a, b = a or { 0, 0, 0 }, b or { 0, 0, 0 }
	for i = 1, 3 do
		if math.abs((tonumber(a[i]) or 0) - (tonumber(b[i]) or 0)) > 1e-9 then return false end
	end
	return true
end

local function sig(e)
	local a = st()
	local p = {}
	local mm = mega_map(e)
	for _, gid in ipairs(SG.T().ids) do
		local x = a.g[tostring(gid)]
		if x ~= nil then
			local v = SG.value(e, gid, x.lv, x.ship, mm)
			p[#p + 1] = gid .. ":" .. x.lv .. ":" .. x.ship .. ":" .. v.fin[1] .. ":" .. v.fin[2] .. ":" .. v.fin[3]
		end
	end
	return table.concat(p, ",")
end

function SG.active()
	return stats_on() and S ~= nil and type(S.sg) == "table" and S.sg.v == 1
end

local function is_guard(tid)
	local a = S.sg
	if type(a) ~= "table" or type(a.g) ~= "table" then return false end
	tid = tonumber(tid)
	for _, x in pairs(a.g) do if type(x) == "table" and tonumber(x.ship) == tid then return true end end
	return false
end

function SG.adjust(sid, tid, pn, spec, is_rec)
	if not SG.active() or type(pn) ~= "table" then return end
	local ok, err = pcall(function()
		if is_guard(tid) then return end
		local tot = R.sg_tot
		if tot == nil then
			local e = ED()
			if e == nil then return end
			tot = totals_now(e)
			R.sg_tot = tot
		end
		local base = { 0, 0, 0 }
		if is_rec and R.sg_rec ~= nil then base = R.sg_rec end
		for i = 1, 3 do
			local d = (tot[i] or 0) - (base[i] or 0)
			if type(pn[i]) == "number" and math.abs(d) > 1e-9 then pn[i] = math.max(0, rnd(pn[i] + d)) end
		end
	end)
	if not ok then
		R.sg_errs = (R.sg_errs or 0) + 1
		if R.sg_errs <= 5 then log("loi chi so Soul Guard:", tostring(err)) end
	end
end

local function floor_props()
	if not auto_on() then return end
	for id in pairs(SG.T().props) do
		if LS.prop_get(id) < FLOOR_LOW then LS.prop_set(id, FLOOR_TOP) end
	end
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then error("chua co the gioi") end
	if not SG.T().ok then error("khong co bang Soul Guard") end
	local a = st()
	local changed
	if full_on() then changed = make_full(a, e) else changed = unfull(a) end
	if changed then mark(); R.sg_tot = nil end
	floor_props()
	return e, a
end

local function finish(e, seq, name)
	SG.publish(e)
	local js = SG.json(e)
	local blocks = { "12661\r\n" .. js }
	if LS._tl ~= nil and LS._tl.refresh_blocks ~= nil then
		LS._tl.refresh_blocks(e, blocks)
		LS._tl.queue_all(e)
		R.tl_sig_l, R.tl_sig_f = nil, nil
	end
	R.sg_sig = nil
	mark()
	LS.save_state(true)
	return reply(seq, name, blocks)
end

local function count_heroes(e, test)
	local n = 0
	for _, sh in pairs(e.user_ship or {}) do
		if type(sh) == "table" and tonumber(sh.captain_type) ~= 0 and test(sh) then n = n + 1 end
	end
	return n
end

function SG.cond_ok(e, a, gid, cid)
	local c = SG.T().unlock[cid]
	if c == nil then return true end
	if c.ty == 1 then
		local mm = mega_map(e)
		return count_heroes(e, function(sh) return (mega_pages(e, sh, mm)) >= c.b end) >= c.a
	elseif c.ty == 2 then
		local prev = a.g[tostring(gid - 1)]
		return prev ~= nil and prev.lv >= c.a
	elseif c.ty == 3 then
		return count_heroes(e, function(sh) return (tonumber(sh.Order) or 0) >= c.b end) >= c.a
	elseif c.ty == 5 then
		return (tonumber(e.user_info.user_grade) or 0) >= c.a
	elseif c.ty == 6 then
		return count_heroes(e, function(sh) return (tonumber(sh.ship_grade) or 0) >= c.b end) >= c.a
	end
	return true
end

local function gid_of(seq, name, p)
	local gid = math.floor(tn(p[1], -1))
	if SG.T().g[gid] == nil then return nil, err_reply(seq, name, "LS_thu_ve_khong_ton_tai", ERR.generic) end
	return gid
end

function SG.h_unlock(p, seq)
	local name = "soul_gruad_un_lock"
	local e, a = ctx()
	local gid, er = gid_of(seq, name, p)
	if gid == nil then return er end
	if a.g[tostring(gid)] ~= nil then return err_reply(seq, name, "LS_thu_ve_da_mo", ERR.generic) end
	for _, cid in ipairs(SG.T().g[gid].conds) do
		if not SG.cond_ok(e, a, gid, cid) then return err_reply(seq, name, "LS_chua_du_dieu_kien_mo", ERR.generic) end
	end
	a.g[tostring(gid)] = { lv = 0, ship = -1, auto = true }
	R.sg_last = "mo thu ve " .. gid
	stat_inc("sg_unlock")
	return finish(e, seq, name)
end

function SG.h_level(p, seq)
	local name = "soul_gruad_level_up"
	local e, a = ctx()
	local gid, er = gid_of(seq, name, p)
	if gid == nil then return er end
	local x = a.g[tostring(gid)]
	if x == nil then return err_reply(seq, name, "LS_thu_ve_chua_mo", ERR.generic) end
	local g = SG.T().g[gid]
	local row = g.rows[x.lv + 1]
	if row == nil then return err_reply(seq, name, "LS_thu_ve_da_toi_da", ERR.level_cap) end

	local need = {}
	for _, c in ipairs(row.cost) do
		if c[1] == 6 then need[#need + 1] = { c[2], c[3] } end
	end
	for _, c in ipairs(row.cost) do
		if c[1] == 1 and c[3] > 0 and (S.silver or 0) < c[3] then return err_reply(seq, name, "LS_khong_du_bac", ERR.silver) end
	end
	if #need > 0 and not LS.prop_spend_all(need) then return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	for _, c in ipairs(row.cost) do
		if c[1] == 1 and c[3] > 0 then LS.money_spend("silver", c[3]) end
	end
	x.lv = x.lv + 1
	R.sg_last = "nang thu ve " .. gid .. " len cap " .. x.lv
	stat_inc("sg_level")
	return finish(e, seq, name)
end

function SG.h_use(p, seq)
	local name = "soul_gruad_use_ship_mould"
	local e, a = ctx()
	local gid, er = gid_of(seq, name, p)
	if gid == nil then return er end
	local x = a.g[tostring(gid)]
	if x == nil then return err_reply(seq, name, "LS_thu_ve_chua_mo", ERR.generic) end
	local tid = math.floor(tn(p[2], -1))
	if tid <= 0 or ship_of(e, tid) == nil then return err_reply(seq, name, "LS_khong_co_tuong", ERR.generic) end
	if not mega_ok(tid) then return err_reply(seq, name, "LS_tuong_khong_co_Kame_Sen", ERR.generic) end
	for k, y in pairs(a.g) do
		if k ~= tostring(gid) and type(y) == "table" and y.ship == tid then

			y.ship = -1
			y.auto = true
		end
	end
	x.ship = tid
	x.auto = nil
	R.sg_last = "thu ve " .. gid .. " dung tuong " .. tid
	stat_inc("sg_use")
	return finish(e, seq, name)
end

function SG.on_world(e)
	R.sg_t, R.sg_tot, R.sg_sig = nil, nil, nil
	R.sg_n = 0
	if S ~= nil and S.sg ~= nil and type(S.sg) ~= "table" then S.sg = nil end

	local cur = e.soul_warding_formation_hero
	local raw
	if type(cur) == "table" and cur ~= rawget(_G, "__LS_SG_PUB") then
		raw = cur
		rawset(_G, "__LS_SG_REC", cur)
	else
		raw = rawget(_G, "__LS_SG_REC")
	end
	R.sg_rec_raw = type(raw) == "table" and raw or {}
	local rec = { 0, 0, 0 }
	for _, x in pairs(R.sg_rec_raw) do
		if type(x) == "table" and type(x.addFinalProperty) == "table" then
			for _, kv in pairs(x.addFinalProperty) do
				if type(kv) == "table" then
					local t, v = tonumber(kv[1]), tonumber(kv[2]) or 0
					if t == 0 then rec[1] = rec[1] + v elseif t == 1 then rec[2] = rec[2] + v elseif t == 2 then rec[3] = rec[3] + v end
				end
			end
		end
	end
	R.sg_rec = rec
end

function SG.tick(e)
	if S == nil or not R.ready then return end
	if not SG.T().ok then return end
	R.sg_n = (R.sg_n or 0) + 1
	local son = stats_on()
	local toggled = (R.sg_stats_prev ~= nil and R.sg_stats_prev ~= son)
	R.sg_stats_prev = son
	if R.sg_n % 10 ~= 1 and not toggled and not R.sg_now then return end
	R.sg_now = nil
	local a = st()
	local changed
	if full_on() then changed = make_full(a, e) else changed = unfull(a) end
	if changed then mark() end

	local s = sig(e)
	if changed or toggled or s ~= R.sg_sig or R.sg_n == 1 then
		R.sg_sig = s
		local prev = R.sg_tot
		SG.publish(e)

		if (changed or toggled or not same_tot(prev, R.sg_tot)) and LS._tl ~= nil and LS._tl.queue_all ~= nil then
			pcall(LS._tl.queue_all, e)
		end
	elseif e.soul_warding_formation_hero == nil and next(a.g) ~= nil then
		SG.publish(e)
	end
end

function SG.apply_now(e)
	R.sg_now = true
	if e ~= nil then SG.tick(e) end
end
SG.full_on = full_on

function SG.dump_line()
	local a = S ~= nil and S.sg or nil
	if type(a) ~= "table" then return "[LS soul guard] chua dung" end
	local p = {}
	for _, gid in ipairs(SG.T().ids) do
		local x = a.g[tostring(gid)]
		p[#p + 1] = gid .. "=" .. (x and ("cap " .. x.lv .. " tuong " .. x.ship .. (x.auto and "(LS chon)" or "(ong chon)")) or "khoa")
	end
	local t = R.sg_tot or { 0, 0, 0 }
	return "[LS soul guard] " .. table.concat(p, " | ") .. " | cong them HP " .. fint(t[1]) .. " / cong " .. fint(t[2]) .. " / thu " .. fint(t[3])
		.. " | full " .. (full_on() and "BAT" or "TAT") .. " | chi so " .. (stats_on() and "BAT" or "TAT")
		.. (R.sg_last and (" | cuoi: " .. R.sg_last) or "") .. ((R.sg_errs or 0) > 0 and (" | loi " .. R.sg_errs) or "")
end

function SG.reset(e)
	S.sg = nil
	R.sg_tot, R.sg_sig = nil, nil
	if type(e) == "table" then
		local raw = rawget(_G, "__LS_SG_REC")
		e.soul_warding_formation_hero = (type(raw) == "table") and raw or nil
	end
	mark()
end

do
	local tl = LS._tl
	if tl ~= nil and tl.differs ~= nil then
		local td = tl.differs
		tl.differs = function(e, sid, tid, is_rec)
			if SG.active() then
				local t = R.sg_tot
				if t == nil then

					local ok, v = pcall(totals_now, e)
					if ok and type(v) == "table" then t = v; R.sg_tot = v end
				end
				if t ~= nil and (t[1] ~= 0 or t[2] ~= 0 or t[3] ~= 0) and not is_guard(tid) then return true end
			end
			return td(e, sid, tid, is_rec)
		end
	end
end

if LS._lv ~= nil and LS._lv.add_ids ~= nil then LS._lv.add_ids({ 191 }) end

LS._sg = SG

end
init_sg()
end

do
local function init_towers()

local TT, FT = {}, {}

local function tower_num(v, dflt)
	v = tonumber(v)
	if v == nil then return dflt end
	return math.floor(v)
end

local function tower_npc_exists(id)
	id = tower_num(id, 0)
	if id <= 0 then return false end
	local d = G("dms")
	local ns, fs, ss = G("npc"), G("environment_formation"), G("environment_ship")
	if type(d) ~= "table" or type(d["npc"]) ~= "table"
		or type(ns) ~= "table" or type(fs) ~= "table" or type(ss) ~= "table"
		or type(d.string) ~= "function" or type(d.int) ~= "function" then return false end
	local fcol, seat, bust = ns.environment_formation1, fs.seat_one, ss.bust_index
	if fcol == nil or seat == nil or bust == nil then return false end
	local ok, formation = pcall(d.string, d["npc"], id, fcol)
	formation = ok and tower_num(formation, 0) or 0
	if formation <= 0 then return false end
	for i = 0, 5 do
		local a, ship = pcall(d.int, d["environment_formation"], formation, seat + i)
		ship = a and tower_num(ship, 0) or 0
		if ship > 0 then
			local b, sprite = pcall(d.int, d["environment_ship"], ship, bust)
			if b and tower_num(sprite, 0) > 0 then return true end
		end
	end
	return false
end

local function tower_npc_list()
	local out, seen = {}, {}
	local function add(id)
		id = tower_num(id, 0)
		if #out < 3 and not seen[id] and tower_npc_exists(id) then
			seen[id] = true
			out[#out + 1] = id
		end
	end
	for n in string.gmatch(tostring(play_cfg(56) or ""), "%d+") do
		add(n)
	end

	if #out == 0 then
		local wb = LS._wb
		if type(wb) == "table" and type(wb.boss_data) == "function" then
			local ok, _, id = pcall(wb.boss_data, 1)
			if ok then add(id) end
		end
	end

	if #out < 3 then
		local d = G("dms")
		if type(d) == "table" and type(d["npc"]) == "table" then
			for id in pairs(d["npc"]) do
				add(id)
				if #out >= 3 then break end
			end
		end
	end
	return out
end

-- Runtime tables may be unpacked arrays or tab-separated rows. This package
-- does not ship three_kingdoms_config; never invent a floor/reward definition.
local function tower_value(name, id, field, fallback)
	local d, sc = G("dms"), G(name)
	if type(d) ~= "table" or type(d[name]) ~= "table" then return nil end
	local col = type(sc) == "table" and sc[field] or fallback
	if type(d.string) == "function" then
		local ok, v = pcall(d.string, d[name], id, col)
		if ok and v ~= nil then return tostring(v) end
	end
	local row = d[name][id] or d[name][tostring(id)]
	if type(row) == "string" then
		local t = {}; for v in (row .. "\t"):gmatch("(.-)\t") do t[#t + 1] = v end; row = t
	end
	return type(row) == "table" and row[col] ~= nil and tostring(row[col]) or nil
end

local function tower_limit()
	local d, n = G("dms"), 0
	local t = type(d) == "table" and d.three_kingdoms_config or nil
	if type(t) == "table" then for id in pairs(t) do n = math.max(n, tower_num(id, 0)) end end
	return n > 0 and n or nil
end

local function trial_reward(items)
	-- The stock parser dereferences reward[1]; zero-item 171 blocks are invalid.
	if #items == 0 then return nil end
	local b = { "171", "37", fint(#items) }
	for _, it in ipairs(items) do
		b[#b + 1] = fint(it.item); b[#b + 1] = fint(it.typ); b[#b + 1] = fint(it.qty)
	end
	return table.concat(b, "\r\n")
end

local function trial_chest(floor)
	local lib = tower_num(tower_value("three_kingdoms_config", floor, "reward_id", 4), 0)
	if lib <= 0 then return {} end
	return LS._apply_rewards(LS._roll_library(lib, 1))
end

-- [FIX THAP 2.65] Digital trial buffs use "buffId:shipId,count", NOT
-- "propertyId,totalValue". Keep old/unmapped data in the save; only send valid
-- entries to the client. Resolve legacy totals against the runtime buff table.
local function trial_attribute_parts(raw)
	local counts, pending = {}, {}
	for entry in tostring(raw or ""):gmatch("[^|]+") do
		local id, target, count = entry:match("^(%d+):(%-?%d+),([^,]+)$")
		id, target, count = tonumber(id), tonumber(target), tonumber(count)
		if id and id > 0 and target and count and count > 0 and count < math.huge then
			local key = fint(id) .. ":" .. fint(target)
			counts[key] = (counts[key] or 0) + count
		else
			local prop, total = entry:match("^(%-?%d+),([^,]+)$")
			prop, total = tonumber(prop), tonumber(total)
			local best, bestCount, bestRank
			local d = G("dms")
			local defs = type(d) == "table" and d.three_kingdoms_attribute or nil
			if prop and total and total ~= 0 and type(defs) == "table" then
				for key in pairs(defs) do
					local buff = tower_num(key, 0)
					if buff > 0 then
						local value = tower_value("three_kingdoms_attribute", buff, "attribute_value", 4) or ""
						local code, amount = value:match("^(%-?%d+),([^,]+)$")
						code, amount = tonumber(code), tonumber(amount)
						if code == prop and amount and amount ~= 0 then
							local n = total / amount
							if n > 0 and n < math.huge then
								local rank = math.abs(n - 1) < 0.000000001 and 0
									or (math.abs(n - math.floor(n + 0.5)) < 0.000000001 and 1 or 2)
								if not best or rank < bestRank or (rank == bestRank and buff < best) then
									best, bestCount, bestRank = buff, n, rank
								end
							end
						end
					end
				end
			end
			if best then
				local key = fint(best) .. ":-1"
				counts[key] = (counts[key] or 0) + bestCount
			else
				pending[#pending + 1] = entry
			end
		end
	end
	return counts, pending
end

local function trial_attribute_pack(counts, pending)
	local keys, out = {}, {}
	for key in pairs(counts) do keys[#keys + 1] = key end
	table.sort(keys)
	for _, key in ipairs(keys) do out[#out + 1] = key .. "," .. string.format("%.12g", counts[key]) end
	for _, entry in ipairs(pending) do out[#out + 1] = entry end
	return table.concat(out, "|")
end

local function trial_attribute_wire(a)
	local counts = trial_attribute_parts(a.attr)
	return trial_attribute_pack(counts, {})
end

-- [THAP RESET] Chu ky reset: "day" = moi 12h TRUA (doi ngay luc 12:00), "week" = het tuan (thu 2 00:00).
-- Lan dau chua co moc thi chi ghi moc, KHONG xoa tien trinh hien co. Tinh theo gio may, ke ca luc thoat game.
function TT.period(kind)
	if kind == "week" then return os.date("%Y%W", os.time()) end
	return os.date("%Y%m%d", os.time() - 12 * 3600)
end

local function trial_state()
	local a = S.tt
	if type(a) ~= "table" then
		a = { v = 1, floor = 0, stars = 0, attr = "" }
		S.tt = a
	end
	do
		local pk = TT.period("day")
		if a.pk == nil then
			a.pk = pk; mark()
		elseif a.pk ~= pk then
			a.pk = pk
			a.floor, a.stars, a.attr, a.ships, a.sweep_state = 0, 0, "", "", 0
			a.sweep_buff, a.sweep_box = {}, {}
			mark()
			log("thap Thu Thach: qua 12h trua -> reset ve tang 1")
		end
	end
	a.floor = math.max(0, tower_num(a.floor, 0))
	a.stars = math.max(0, tower_num(a.stars, 0))
	if type(a.attr) ~= "string" then a.attr = "" end
	local counts, pending = trial_attribute_parts(a.attr)
	local normalized = trial_attribute_pack(counts, pending)
	if normalized ~= a.attr then
		a.attr_before_v265 = a.attr_before_v265 or a.attr
		a.attr = normalized
		mark()
	end
	-- Migrate additively: retain existing floor, stars, currencies and Fury state.
	a.history = math.max(a.stars, tower_num(a.history, a.stars))
	a.score = math.max(0, tower_num(a.score, 0))
	if type(a.ships) ~= "string" then a.ships = "" end
	a.sweep_state = tower_num(a.sweep_state, 0)
	if type(a.sweep_buff) ~= "table" then a.sweep_buff = {} end
	if type(a.sweep_box) ~= "table" then a.sweep_box = {} end
	return a
end

local function trial_block()
	local a = trial_state()
	return "343\r\n" .. fint(a.history) .. "\r\n" .. fint(a.stars) .. "\r\n0\r\n" .. trial_attribute_wire(a)
		.. "\r\n" .. fint(a.floor) .. "\r\n1\r\n0"
end

local function trial_npc_block()

	return "347\r\n3\r\n3\r\n3"
end

local function trial_init_block()
	local ids = tower_npc_list()
	local one = ids[1] or 0
	local npc_infos = table.concat({
		fint(ids[1] or one), fint(ids[2] or one), fint(ids[3] or one)
	}, ",")

	local a = trial_state()
	local buffs, boxes = {}, {}
	local limit = tower_limit() or a.floor
	for floor = 1, math.min(a.floor, limit) do
		if tower_value("three_kingdoms_config", floor, "npc_id", 3) == "-1" then
			if tower_value("three_kingdoms_config", floor, "reward_id", 4) == "-1" then
				buffs[#buffs + 1] = floor .. ":" .. tostring(a.sweep_buff[tostring(floor)] or "0,0,0")
			else
				boxes[#boxes + 1] = floor .. ":" .. fint(tower_num(a.sweep_box[tostring(floor)], 1))
			end
		end
	end
	local out = table.concat({
		"12558", fint(a.score), fint(a.score), fint(a.score), "", "0", a.ships, npc_infos,
		"99999999", fint(a.sweep_state), table.concat(buffs, "|"), table.concat(boxes, "|")
	}, "\r\n")
	log("TT NPC", npc_infos)
	return out
end

function TT.h_init(p, seq)
	return reply(seq, "three_kingdoms_init", {
		trial_init_block(), trial_block(), trial_npc_block(), "345\r\n999"
	})
end

-- Both ordinary BUFF and VIP sweep clients send their remaining stars and
-- HP/SP snapshot, not an additional battle win. Store these separately.
local function trial_snapshot(a, ships, stars)
	if type(ships) == "string" and ships ~= "" and ships ~= "0" then a.ships = ships end
	if stars ~= nil then a.stars = math.max(0, math.min(a.stars, tower_num(stars, a.stars))) end
end

local function trial_attributes(a, info)
	local counts, pending = trial_attribute_parts(a.attr)
	local selected = {}
	for id, target in tostring(info or ""):gmatch("(%-?%d+):(%-?%d+)") do
		id, target = tonumber(id), tonumber(target)
		selected[#selected + 1] = id
		if id > 0 and target == -1 then
			local value = tower_value("three_kingdoms_attribute", id, "attribute_value", 4) or ""
			local code, amount = value:match("^(%-?%d+),([^,]+)$")
			code, amount = tonumber(code), tonumber(amount)
			-- HP, rage and revive were already applied to the ship snapshot.
			if code and amount and code ~= 4 and code ~= 41 and code ~= 999 then
				local key = fint(id) .. ":" .. fint(target)
				counts[key] = (counts[key] or 0) + 1
			end
		end
	end
	a.attr = trial_attribute_pack(counts, pending)
	return selected
end

function TT.h_launch(p, seq)
	local a = trial_state()
	local floor, stars = tower_num(p[6], -1), math.max(0, tower_num(p[4], 0))
	local special = tower_value("three_kingdoms_config", floor, "npc_id", 3) == "-1"
	local noncombat = special and tower_num(p[3], 0) == 0 and tower_num(p[5], 0) == 0
	local limit, items = tower_limit(), {}
	-- Only the next stage settles. Duplicate callbacks must not mint stars/silver.
	if floor == a.floor + 1 and (not limit or floor <= limit) and (stars > 0 or noncombat) then
		a.floor = floor
		if noncombat then
			local e = ED()
			trial_snapshot(a, p[7], e and e.three_kingdoms_view and e.three_kingdoms_view.current_max_stars)
			trial_attributes(a, p[8])
			if tower_num(tower_value("three_kingdoms_config", floor, "reward_id", 4), -1) > 0 then items = trial_chest(floor) end
		else
			a.stars = a.stars + stars; a.history = math.max(a.history, a.stars)
			trial_snapshot(a, p[7])
			LS.money_add("silver", 5000 + 1000 * math.max(1, floor))
			stat_inc("trial_tower_win")
		end
		mark(); R.tt_last = (noncombat and "qua BUFF/ruong tang " or "qua tang ") .. a.floor
	end
	return reply(seq, "three_kingdoms_launch", { trial_init_block(), trial_block(), trial_npc_block(), trial_reward(items) })
end

local function trial_sweep(p, seq, name)
	local a, items = trial_state(), {}
	local op = tower_num(p[1], 0)
	if op == 0 then
		-- p[4] is the NEXT playable floor (VIP cap + 1), not a cleared floor.
		local target = math.max(0, tower_num(p[4], a.floor + 1) - 1)
		local limit = tower_limit(); if limit then target = math.min(target, limit) end
		if target > a.floor then
			a.floor = target; a.stars = math.max(a.stars, tower_num(p[2], 0))
			a.history = math.max(a.history, a.stars); a.score = math.max(a.score, tower_num(p[3], 0))
			a.sweep_state = 1
			if LS.money_add("silver", 10000) then items[1] = { item = -1, typ = 1, qty = 10000 } end
			stat_inc("trial_tower_sweep"); R.tt_last = "quet den tang " .. a.floor
		end
	elseif op == 1 then
		trial_snapshot(a, p[6]); a.sweep_state = 2
	elseif op == 2 then
		local floor = tower_num(p[4], 0); local k = tostring(floor)
		if floor > 0 and floor <= a.floor and a.sweep_buff[k] == nil
			and tower_value("three_kingdoms_config", floor, "npc_id", 3) == "-1"
			and tower_value("three_kingdoms_config", floor, "reward_id", 4) == "-1" then
			local selected = trial_attributes(a, p[5])
			local status = {}; for i = 1, 3 do status[i] = tostring(selected[i] and selected[i] ~= 0 and selected[i] or -1) end
			a.sweep_buff[k] = table.concat(status, ",")
			trial_snapshot(a, p[6], p[2])
		end
	elseif op == 4 then
		-- Paid repeat chest draws are not implemented by the old local server.
		-- Do not report fake success or advance one floor on an unsupported action.
		return tostring(seq) .. "\r\n" .. name .. "\r\n1"
	end
	mark()
	return reply(seq, name, { "380\r\n0\r\n0", trial_init_block(), trial_block(), trial_npc_block(), trial_reward(items) })
end

function TT.h_sweep(p, seq) return trial_sweep(p, seq, "three_kingdoms_sweep") end
function TT.h_sweep_kingdoms(p, seq) return trial_sweep(p, seq, "sweep_kingdoms") end

function TT.h_one_key(p, seq)
	local a = trial_state()
	a.floor = a.floor + 1
	a.stars = a.stars + 3
	LS.money_add("silver", 10000)
	mark(); stat_inc("trial_tower_one_key")
	R.tt_last = "quet nhanh den tang " .. a.floor

	local one = "1302\r\n1\r\n100\r\n0\r\n10000\r\n0\r\n0\r\n\r\n0"
	return reply(seq, "one_key_sweep_three_kingdoms", { one, "1303\r\n" .. fint(a.floor), trial_block(), trial_npc_block() })
end

function TT.h_attribute(p, seq)
	local a, item = trial_state(), tostring(p[1] or "")
	if item ~= "" then
		a.attr = item
		mark()
		R.tt_last = "chon buff " .. item
	end
	return reply(seq, "get_attribute", { trial_block() })
end

function TT.h_shop_init(p, seq) return reply(seq, "dignified_shop_init", { "346\r\n0" }) end
function TT.h_shop_buy(p, seq) return reply(seq, "dignified_shop_buy", { "346\r\n0" }) end
function TT.h_secret(p, seq)
	return reply(seq, "unparallel_purchase", { "381\r\n" .. fint(tower_num(p[1], 0)) .. "\r\n1" })
end
function TT.h_draw(p, seq) return reply(seq, "three_kingdoms_draw_score_reward", { trial_block() }) end

local function trans_reply(seq, name)
	return reply(seq, name, { "226\r\n0\r\n999\r\n999" })
end
function TT.h_trans(p, seq) return trans_reply(seq, "trans_tower_init") end
function TT.h_towel_launch(p, seq) return trans_reply(seq, "towel_launch") end
function TT.h_sweep_towel(p, seq) return trans_reply(seq, "sweep_towel") end
function TT.h_towel_reset(p, seq) return trans_reply(seq, "towel_reset") end

function TT.dump_line()
	local a = trial_state()
	return "[LS Trial Tower] tang " .. a.floor .. " | sao " .. a.stars
		.. (R.tt_last ~= nil and (" | cuoi: " .. R.tt_last) or "")
end

local function fury_state(tower)
	tower = math.max(1, math.min(2, tower_num(tower, 1)))
	local all = S.ft
	if type(all) ~= "table" then all = { v = 1, t = {} }; S.ft = all end
	if type(all.t) ~= "table" then all.t = {} end
	local k, a = tostring(tower), all.t[tostring(tower)]
	if type(a) ~= "table" then
		a = { floor = 0, double = 0, weaken = 0, reset = 1 }
		all.t[k] = a
	end
	do
		local pk = TT.period(tower == 2 and "week" or "day")
		if a.pk == nil then
			a.pk = pk; mark()
		elseif a.pk ~= pk then
			a.pk = pk
			a.floor, a.double, a.weaken, a.reset = 0, 0, 0, 1
			mark()
			log(tower == 2 and "Fury tuan: het tuan -> reset ve tang 1" or "Fury ngay: qua 12h trua -> reset ve tang 1")
		end
	end
	a.floor = math.max(0, tower_num(a.floor, 0))
	a.double = tower_num(a.double, 0)
	a.weaken = tower_num(a.weaken, 0)
	a.reset = tower_num(a.reset, 1)
	return tower, a
end

local function fury_npc(tower, floor)
	local list = tower_npc_list()
	if #list > 0 then return list[((floor + tower - 2) % #list) + 1] end
	return 0
end

local function fury_block(tower, notice)
	local t, a = fury_state(tower)
	local floors, next_floor = 100, a.floor + 1
	local npc = next_floor <= floors and fury_npc(t, next_floor) or 0
	local power = 1000 + next_floor * (t == 1 and 450 or 700)
	local vals = { t, floors, a.floor, notice or 0, a.floor * 100, 0, 0, 0, a.reset, a.double, a.weaken,
		npc, power, 999, 1 }
	local out = { "29120" }
	for _, v in ipairs(vals) do out[#out + 1] = fint(v) end
	out[#out + 1] = "1"
	out[#out + 1] = fint(next_floor)
	out[#out + 1] = "6,1," .. fint(1000 + 100 * next_floor)
	return table.concat(out, "\r\n")
end

function FT.h_view(p, seq)
	return reply(seq, "fury_tower_view", { fury_block(tower_num(p[1], 1), 0) })
end

function FT.h_start(p, seq)
	local tower, a = fury_state(p[1])
	local floor = tower_num(p[2], 0)
	local notice = (floor == a.floor + 1 and floor <= 100) and 0 or 4
	return reply(seq, "fury_tower_start", { fury_block(tower, notice) })
end

function FT.h_result(p, seq)
	local tower, a = fury_state(p[1])
	local floor, win = tower_num(p[2], 0), tower_num(p[3], 0)
	local notice = 0
	if win == 1 and floor == a.floor + 1 and floor <= 100 then
		a.floor = floor
		local gain = (1000 + floor * 100) * (a.double == 1 and 2 or 1)
		LS.money_add("silver", gain)
		mark(); stat_inc("fury_tower_win")
		R.ft_last = (tower == 1 and "Fury ngay" or "Fury tuan") .. " tang " .. floor
	elseif win == 1 then
		notice = 4
	end
	return reply(seq, "fury_tower_result", { fury_block(tower, notice) })
end

function FT.h_buy(p, seq)
	local tower, a = fury_state(p[1])
	local what = tower_num(p[2], 0)
	if what == 1 then a.double = 1
	elseif what == 2 then a.weaken = 1
	elseif what == 3 then a.floor, a.double, a.weaken, a.reset = 0, 0, 0, 0
	end
	mark(); stat_inc("fury_tower_buy")
	return reply(seq, "fury_tower_buy", { fury_block(tower, 0) })
end

function FT.h_rank(p, seq)
	local _, a = fury_state(1)

	return reply(seq, "fury_tower_rank", { "29124\r\n1\r\n" .. fint(a.floor) .. "\r\n0\r\n0" })
end

function FT.h_mode_pass_view(p, seq)
	return reply(seq, "fury_mode_pass_view", {})
end

function FT.dump_line()
	local _, day = fury_state(1)
	local _, week = fury_state(2)
	return "[LS Fury Tower] ngay " .. day.floor .. "/100 | tuan " .. week.floor .. "/100"
		.. (R.ft_last ~= nil and (" | cuoi: " .. R.ft_last) or "")
end

LS._tt, LS._ft = TT, FT
end
init_towers()
end

do
local function init_bg()

local BG = {}
local ALL_LOW, ALL_TOP = 10, 99
local MAX_UNITS = 9999
local MAX_HEROES = 100
local TICK_ALL = 100

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end
local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end
local function row_of(name, id)
	local t = dtab(name)
	if t == nil then return nil end
	local r = t[id]
	if r == nil and type(id) == "number" then r = t[tostring(id)] end
	if type(r) == "string" then return split_tab(r) end
	if type(r) == "table" then return r end
	return nil
end
local function rint(a, b)
	a, b = math.floor(tonumber(a) or 0), math.floor(tonumber(b) or 0)
	if b <= a then return a end
	return math.random(a, b)
end

local DEF = { prop_name = 2, silver_price = 4, prop_type = 9, split_or_merge_count = 10, change_of_prop = 11, change_of_equipment = 12,
	change_of_equipment_count = 13, change_of_equipment2 = 14, change_of_equipment2_count = 15, change_of_equipment3 = 16,
	change_of_equipment3_count = 17, use_of_combat_food = 18, use_of_silver = 20, use_of_gold = 21, use_of_repute = 22,
	trace_npc = 28, use_of_prop = 31, use_of_prop_count = 32, use_of_prop2 = 33, use_of_prop2_count = 34, use_of_prop3 = 35,
	use_of_prop3_count = 36, need_level = 42, props_type = 43, addition_group_index = 45, can_sell = 52, storage_page_index = 53,
	is_batch_use = 56, use_type = 58 }
local function col(name)
	local sch = G("prop_mould")
	if type(sch) == "table" and tonumber(sch[name]) ~= nil then return sch[name] end
	return DEF[name]
end

local function on() return not (type(S.cfg) == "table" and S.cfg.bag == false) end
local function all_on() return type(S.cfg) == "table" and S.cfg.bag_all == true end

local function st()
	local a = S.bg
	if type(a) ~= "table" or a.v ~= 1 then a = { v = 1, n_use = 0, n_item = 0, n_sell = 0, n_comp = 0 }; S.bg = a; mark() end
	for _, k in ipairs({ "n_use", "n_item", "n_sell", "n_comp" }) do a[k] = math.max(0, math.floor(tn(a[k], 0))) end
	return a
end

function BG.item(tmpl)
	tmpl = math.floor(tonumber(tmpl) or -1)
	local C = R.bg_it
	if C == nil then C = {}; R.bg_it = C end
	local it = C[tmpl]
	if it ~= nil then return it or nil end
	local r = row_of("prop_mould", tmpl)
	if r == nil or tonumber(r[1]) == nil then C[tmpl] = false; return nil end
	local function n(name) return math.floor(tonumber(r[col(name)]) or 0) end
	it = {
		id = tmpl, use = n("use_type"), pt = n("prop_type"), pst = n("props_type"), split = n("split_or_merge_count"),
		cprop = n("change_of_prop"), ceq = {}, food = n("use_of_combat_food"), silver = n("use_of_silver"), gold = n("use_of_gold"),
		repute = n("use_of_repute"), props = {}, lib = n("addition_group_index"), lvmap = {}, need = n("need_level"),
		sell = n("can_sell"), price = n("silver_price"), page = n("storage_page_index"), batch = n("is_batch_use"),
		blank = (tostring(r[col("prop_name")] or "") == "1"),
	}
	for _, k in ipairs({ { "change_of_equipment", "change_of_equipment_count" }, { "change_of_equipment2", "change_of_equipment2_count" },
		{ "change_of_equipment3", "change_of_equipment3_count" } }) do
		local id, c = n(k[1]), n(k[2])
		if id > 0 then it.ceq[#it.ceq + 1] = { id, math.max(1, c) } end
	end
	for _, k in ipairs({ { "use_of_prop", "use_of_prop_count" }, { "use_of_prop2", "use_of_prop2_count" }, { "use_of_prop3", "use_of_prop3_count" } }) do
		local id, c = n(k[1]), n(k[2])
		if id > 0 then it.props[#it.props + 1] = { id, math.max(1, c) } end
	end
	if it.pst == 3 then
		for a, b, l in string.gmatch(tostring(r[col("trace_npc")] or ""), "(%d+)%s*,%s*(%d+)%s*,%s*(%d+)") do
			it.lvmap[#it.lvmap + 1] = { tonumber(a), tonumber(b), tonumber(l) }
		end
	end
	C[tmpl] = it
	return it
end

local function drop_entries(s)
	local out = {}
	for part in string.gmatch(tostring(s or ""), "[^|]+") do
		local item, typ, q1, q2, w1, w2, rest = string.match(part,
			"^%s*(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*%-%s*(%d+)%s*,%s*(%d+)%s*%-%s*(%d+)%s*(.*)$")
		if item ~= nil then
			out[#out + 1] = { item = tonumber(item), typ = tonumber(typ), q1 = tonumber(q1), q2 = tonumber(q2), w1 = tonumber(w1), w2 = tonumber(w2),
				x = tonumber(string.match(rest or "", "^,%s*(%-?%d+)")) }
		end
	end
	return out
end

local function drop_index()
	if R.bg_drop ~= nil then return R.bg_drop end
	local idx = {}
	local t = dtab("scene_reward_drop")
	if t ~= nil then
		local keys = {}
		for k in pairs(t) do if tonumber(k) ~= nil then keys[#keys + 1] = k end end
		table.sort(keys, function(a, b) return tonumber(a) < tonumber(b) end)
		for _, k in ipairs(keys) do
			local r = row_of("scene_reward_drop", k)
			if r ~= nil and tonumber(r[2]) ~= nil then
				local g = math.floor(tonumber(r[2]))
				local l = idx[g]
				if l == nil then l = {}; idx[g] = l end
				l[#l + 1] = { dtype = math.floor(tonumber(r[3]) or 1), times = math.max(1, math.floor(tonumber(r[4]) or 1)), ents = drop_entries(r[5]) }
			end
		end
	end
	R.bg_drop = idx
	return idx
end

local function roll_group(g, add)
	local rows = drop_index()[math.floor(tonumber(g) or -1)]
	if rows == nil then return false end
	for _, r in ipairs(rows) do
		if r.dtype == 1 then
			for _, en in ipairs(r.ents) do add(en.item, en.typ, rint(en.q1, en.q2), en.x) end
		elseif #r.ents > 0 then
			local total = 0
			for _, en in ipairs(r.ents) do if en.w2 > total then total = en.w2 end end
			for _ = 1, r.times do
				if r.dtype == 2 and total > 0 then
					local roll = math.random(1, total)
					for _, en in ipairs(r.ents) do
						if roll >= en.w1 and roll <= en.w2 then add(en.item, en.typ, rint(en.q1, en.q2), en.x); break end
					end
				else
					local en = r.ents[math.random(1, #r.ents)]
					add(en.item, en.typ, rint(en.q1, en.q2), en.x)
				end
			end
		end
	end
	return true
end

local function roll_lib(lib, add)
	local r = row_of("scene_reward_ex", lib)
	if r == nil then return false end
	local groups, weighted, total = {}, false, 0
	for g, a, b in string.gmatch(tostring(r[7] or ""), "(%d+)%s*,%s*(%d+)%s*%-%s*(%d+)") do
		a, b = tonumber(a), tonumber(b)
		groups[#groups + 1] = { g = tonumber(g), a = a, b = b }
		if b > a then weighted = true end
		if b > total then total = b end
	end
	if weighted and total > 0 then
		local roll = math.random(1, total)
		for _, x in ipairs(groups) do
			if roll >= x.a and roll <= x.b then roll_group(x.g, add) end
		end
	else
		for _, x in ipairs(groups) do roll_group(x.g, add) end
	end
	for it, ty, nn in string.gmatch(tostring(r[8] or ""), "(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)") do
		add(tonumber(it), tonumber(ty), tonumber(nn), nil)
	end
	return true
end

function BG.choices(it)
	local out = {}
	if it == nil or it.lib <= 0 then return out end
	local r = row_of("scene_reward_ex", it.lib)
	if r == nil then return out end
	local sch = G("scene_reward_ex")
	local c = (type(sch) == "table" and tonumber(sch.show_reward)) or 3
	for part in string.gmatch(tostring(r[c] or ""), "[^|]+") do
		local a, b, n, x = string.match(part, "^%s*(%-?%d+)%s*,%s*(%d+)%s*,%s*(%d+)%s*,?%s*(%-?%d*)")
		if a ~= nil then out[#out + 1] = { tonumber(a), tonumber(b), tonumber(n), tonumber(x) } end
	end
	return out
end

local function user_grade(e)
	if type(S.user) == "table" and tonumber(S.user.grade) ~= nil then return math.floor(S.user.grade) end
	return math.floor(tn(e.user_info and e.user_info.user_grade, 1))
end

function BG.lib_for(it, grade)
	if #it.lvmap > 0 then
		local last
		for _, m in ipairs(it.lvmap) do
			last = m[3]
			if grade >= m[1] and grade <= m[2] then return m[3] end
		end
		return last
	end
	if it.lib > 0 then return it.lib end
	return nil
end

local function new_bag_list()
	local order, by = {}, {}
	local cnt = { n = 0 }
	local function add(item, typ, qty, x)
		item, typ, qty = math.floor(tonumber(item) or -1), math.floor(tonumber(typ) or 0), math.floor(tonumber(qty) or 0)
		if qty <= 0 or typ <= 0 then return end
		if typ == 4 and item <= 0 then return end
		local key = typ .. ":" .. item .. ":" .. tostring(x or "")
		local o = by[key]
		if o == nil then o = { item, typ, 0, x }; by[key] = o; order[#order + 1] = o end
		o[3] = o[3] + qty
		cnt.n = cnt.n + 1
	end
	return order, add, cnt
end

local function equip_known(id) return row_of("equipment_mould", math.floor(tonumber(id) or -1)) ~= nil end

local function cur_add(e, field, dkey, n)
	local u = e.user_info
	if type(u) ~= "table" then return false end
	local now = tn(u[field], 0)
	u[field] = fint(math.max(0, now + n))
	if type(S.eq) == "table" then S.eq[dkey] = tn(S.eq[dkey], 0) + n end
	mark()
	return true
end

local GIVE = {}
GIVE[1] = function(e, it) return LS.money_add("silver", it[3]) end
GIVE[2] = function(e, it) return LS.money_add("gold", it[3]) end
GIVE[3] = function(e, it) return cur_add(e, "user_honour", "dh", it[3]) end
GIVE[18] = function(e, it) return cur_add(e, "all_glories", "dg", it[3]) end
GIVE[6] = function(e, it) return prop_known(it[1]) and LS.prop_add(it[1], it[3]) end
GIVE[7] = function(e, it)
	if not equip_known(it[1]) or EQ.bag_set == nil or EQ.bag_have == nil then return false end
	EQ.bag_set(e, it[1], EQ.bag_have(e, it[1]) + it[3])
	return true
end
GIVE[8] = function(e, it, fl)
	if CP.user_add_exp == nil or CP.user_init == nil then return false end
	CP.user_init(e)
	local lv = CP.user_add_exp(it[3])
	fl.user, fl.exp = true, fl.exp + it[3]
	if lv then fl.leveled = true end
	return true
end
GIVE[12] = function(e, it, fl)
	if CP.user_init == nil then return false end
	CP.user_init(e)
	if CP.food_regen ~= nil then CP.food_regen() end
	S.user.food = math.floor(tn(S.user.food, 0)) + it[3]
	mark()
	fl.user = true
	return true
end
GIVE[13] = function(e, it, fl)
	local made = 0
	for _ = 1, it[3] do
		if fl.heroes >= MAX_HEROES then break end
		local ov = {}
		if tonumber(it[4]) ~= nil and it[4] > 0 then ov.StarRating = math.floor(it[4]) end
		local ok, s = pcall(LS.create_hero, it[1], ov)
		if not ok or type(s) ~= "table" then
			log("tui do: khong tao duoc tuong", it[1], tostring(s))
			break
		end
		e.recruit_success_ship_id = s.ship_id
		if S.heroes[tostring(s.ship_id)] ~= nil then S.heroes[tostring(s.ship_id)].keep = true end
		made, fl.heroes = made + 1, fl.heroes + 1
	end
	if made <= 0 then return false end
	it[3] = made
	return true
end
GIVE[34] = function(e, it)
	local tl = LS._tl
	if tl ~= nil and tl.ensure ~= nil then pcall(tl.ensure, e) end
	local a = S.tl
	if type(a) ~= "table" then return false end
	a.p = math.max(0, math.floor(tn(a.p, 0))) + it[3]
	mark()
	if tl ~= nil and tl.write_points ~= nil then pcall(tl.write_points, e) end
	return true
end
GIVE[66] = function(e, it) local al = LS._al; return al ~= nil and al.give ~= nil and al.give(e, it[1], it[3]) > 0 end
GIVE[67] = function(e, it) local al = LS._al; return al ~= nil and al.give_ess ~= nil and al.give_ess(e, it[3]) end
GIVE[71] = function(e, it) local am = LS._am; return am ~= nil and am.give ~= nil and am.give(e, it[1], it[3]) > 0 end
GIVE[73] = function(e, it)
	if LS.ws_grant == nil then return false end
	local l = LS.ws_grant(it[1], it[3])
	return type(l) == "table" and #l > 0
end
BG.GIVE = GIVE

function BG.can_give(typ) return GIVE[typ] ~= nil end

function BG.give(e, list)
	local done, skipped = {}, {}
	local fl = { user = false, exp = 0, leveled = false, heroes = 0 }
	for _, it in ipairs(list) do
		local f = GIVE[it[2]]
		local ok, res = false, nil
		if f ~= nil then ok, res = pcall(f, e, it, fl) end
		if ok and res then
			done[#done + 1] = it
		else
			skipped[#skipped + 1] = it
			if not ok then log("tui do: loi cong thuong loai", it[2], "mau", it[1], tostring(res)) end
		end
	end
	if fl.user and CP.user_write ~= nil then CP.user_write(e) end
	return done, skipped, fl
end

local function blk_171(list)
	local b = { "171", "4", fint(#list) }
	for _, it in ipairs(list) do b[#b + 1] = fint(it[1]); b[#b + 1] = fint(it[2]); b[#b + 1] = fint(it[3]) end
	return b
end

function BG.plan(e, it, n, choose)
	local list, add, cnt = new_bag_list()
	local spend = n
	if it.pt == 1 and it.split > 0 and (#it.ceq > 0 or it.cprop > 0) then

		spend = n * it.split
		if #it.ceq > 0 then add(it.ceq[1][1], 7, it.ceq[1][2] * n) else add(it.cprop, 6, n) end
		return list, spend
	end
	if it.pst == 7 then
		local ch = BG.choices(it)
		if #ch == 0 then return nil, "LS_hop_chon_khong_co_du_lieu" end
		local k = math.floor(tonumber(choose) or 1)
		if k < 1 or k > #ch then k = 1 end
		local c = ch[k]
		add(c[1], c[2], c[3] * n, c[4])
	else
		local grade = user_grade(e)
		local lib = BG.lib_for(it, grade)
		if lib ~= nil and row_of("scene_reward_ex", lib) ~= nil then

			for _ = 1, n do
				local before, tries = cnt.n, 0
				repeat
					roll_lib(lib, add)
					tries = tries + 1
				until cnt.n > before or tries >= 5
			end
		end
	end
	if it.pt == 2 then
		if it.cprop > 0 then add(it.cprop, 6, math.max(1, it.split) * n) end
		for _, q in ipairs(it.ceq) do add(q[1], 7, q[2] * n) end
	end
	if it.silver > 0 then add(-1, 1, it.silver * n) end
	if it.gold > 0 then add(-1, 2, it.gold * n) end
	if it.food > 0 then add(-1, 12, it.food * n) end
	if it.repute > 0 then add(-1, 3, it.repute * n) end
	for _, q in ipairs(it.props) do add(q[1], 6, q[2] * n) end
	return list, spend
end

local function find_uid(e, uid)
	if type(e.user_prop) ~= "table" then return nil end
	local v = e.user_prop[tostring(uid)]
	if type(v) == "table" then return math.floor(tonumber(v.user_prop_template) or -1) end
	return nil
end

local function ctx()
	local e = ED()
	if e == nil or type(e.user_info) ~= "table" then return nil end
	return e
end

function BG.h_use(p, seq)
	local name = "prop_use"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local tmpl = find_uid(e, p[1])
	if tmpl == nil then return err_reply(seq, name, "LS_khong_co_vat_pham", ERR.items) end
	local it = BG.item(tmpl)
	if it == nil then return err_reply(seq, name, "LS_vat_pham_la", ERR.generic) end
	local have = LS.prop_get(tmpl)
	local n = math.floor(tn(p[2], 1))
	if n < 1 then n = 1 end
	if n > MAX_UNITS then n = MAX_UNITS end
	if it.need > 0 and user_grade(e) < it.need then return err_reply(seq, name, "LS_chua_du_cap_dung_vat_pham", ERR.hero_level) end
	local list, spend = BG.plan(e, it, n, p[3])
	if list == nil then return err_reply(seq, name, spend, ERR.generic) end
	if have < spend then return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items) end

	local nh = 0
	for _, x in ipairs(list) do if x[2] == 13 then nh = nh + x[3] end end
	if nh > MAX_HEROES and n > 1 then
		n = math.max(1, math.floor(n * MAX_HEROES / nh))
		list, spend = BG.plan(e, it, n, p[3])
		if list == nil then return err_reply(seq, name, spend, ERR.generic) end
	end
	local any = false
	for _, x in ipairs(list) do if GIVE[x[2]] ~= nil then any = true; break end end
	if not any then
		R.bg_last = "mau " .. tmpl .. ": khong dung duoc offline"
		return err_reply(seq, name, "LS_vat_pham_nay_chua_dung_duoc_offline", ERR.generic)
	end
	if not LS.prop_add(tmpl, -spend) then return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	local done, skipped, fl = BG.give(e, list)
	if #done == 0 then
		LS.prop_add(tmpl, spend)
		return err_reply(seq, name, "LS_vat_pham_nay_chua_dung_duoc_offline", ERR.generic)
	end
	local a = st()
	a.n_use, a.n_item = a.n_use + 1, a.n_item + spend
	stat_inc("bag_use")
	local sk = {}
	for _, x in ipairs(skipped) do sk[#sk + 1] = x[2] .. ":" .. x[1] .. "x" .. x[3] end
	R.bg_last = "dung " .. spend .. " x mau " .. tmpl .. " -> " .. #done .. " phan thuong" .. (#sk > 0 and (" (bo qua " .. table.concat(sk, ",") .. ")") or "")
	if #sk > 0 then log("tui do: bo qua loai thuong chua ho tro:", table.concat(sk, ",")) end
	local blocks = {}
	push_all(blocks, blk_171(done))
	if fl.user and CP.blk_user ~= nil then push_all(blocks, CP.blk_user(fl.exp, fl.leveled)) end
	mark()
	LS.save_state(true)
	log("tui do:", R.bg_last)
	return reply(seq, name, blocks)
end

function BG.h_sell(p, seq)
	local name = "prop_sell"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local want, order = {}, {}
	local i = 1
	while p[i] ~= nil and p[i] ~= "" do
		local tmpl = find_uid(e, p[i])
		local n = math.floor(tn(p[i + 1], 0))
		if tmpl == nil then return err_reply(seq, name, "LS_khong_co_vat_pham", ERR.items) end
		if n < 1 then return err_reply(seq, name, "LS_so_luong_sai", ERR.generic) end
		local it = BG.item(tmpl)
		if it == nil or it.sell ~= 1 then return err_reply(seq, name, "LS_vat_pham_khong_ban_duoc", ERR.generic) end
		if want[tmpl] == nil then order[#order + 1] = tmpl end
		want[tmpl] = (want[tmpl] or 0) + n
		i = i + 2
	end
	if #order == 0 then return err_reply(seq, name, "LS_yeu_cau_sai", ERR.generic) end
	for _, tmpl in ipairs(order) do
		if LS.prop_get(tmpl) < want[tmpl] then return err_reply(seq, name, "LS_khong_du_vat_pham", ERR.items) end
	end
	local silver, cnt = 0, 0
	for _, tmpl in ipairs(order) do
		LS.prop_add(tmpl, -want[tmpl])
		silver = silver + BG.item(tmpl).price * want[tmpl]
		cnt = cnt + want[tmpl]
	end
	if silver > 0 then LS.money_add("silver", silver) end
	local a = st()
	a.n_sell = a.n_sell + cnt
	stat_inc("bag_sell")
	R.bg_last = "ban " .. cnt .. " vat pham (" .. #order .. " loai) +" .. fint(silver) .. " bac"
	mark()
	LS.save_state(true)
	log("tui do:", R.bg_last)
	return reply(seq, name, {})
end

function BG.h_compound(p, seq)
	local name = "prop_compound"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local tmpl = find_uid(e, p[1])
	if tmpl == nil then return err_reply(seq, name, "LS_khong_co_vat_pham", ERR.items) end
	local it = BG.item(tmpl)
	if it == nil or (#it.ceq == 0 and it.cprop <= 0) then return err_reply(seq, name, "LS_vat_pham_khong_ghep_duoc", ERR.generic) end
	local need = math.max(1, it.split)
	local times = math.floor(tn(p[3], 1))
	if times < 1 then times = 1 end
	local have = LS.prop_get(tmpl)
	if have < need then return err_reply(seq, name, "LS_khong_du_manh", ERR.items) end
	if have < need * times then times = math.floor(have / need) end
	local list, add = new_bag_list()
	if #it.ceq > 0 then add(it.ceq[1][1], 7, it.ceq[1][2] * times) else add(it.cprop, 6, times) end
	if not LS.prop_add(tmpl, -need * times) then return err_reply(seq, name, "LS_khong_du_manh", ERR.items) end
	local done = BG.give(e, list)
	if #done == 0 then
		LS.prop_add(tmpl, need * times)
		return err_reply(seq, name, "LS_khong_ghep_duoc", ERR.generic)
	end
	local a = st()
	a.n_comp = a.n_comp + times
	stat_inc("bag_compound")
	R.bg_last = "ghep " .. need * times .. " manh mau " .. tmpl .. " -> " .. done[1][2] .. ":" .. done[1][1] .. " x" .. done[1][3]
	mark()
	LS.save_state(true)
	log("tui do:", R.bg_last)
	return reply(seq, name, {})
end

function BG.all_list()
	if R.bg_all ~= nil then return R.bg_all end
	local out = {}
	local t = dtab("prop_mould")
	if t ~= nil then
		for k in pairs(t) do
			local id = tonumber(k)
			if id ~= nil then
				local it = BG.item(id)
				if it ~= nil and not it.blank and it.page ~= -1 then out[#out + 1] = math.floor(id) end
			end
		end
	end
	table.sort(out)
	R.bg_all = out
	return out
end

function BG.fill_all(e)
	local list = BG.all_list()
	local idx = prop_index(e)
	local n = 0
	R.bg_inj = R.bg_inj or {}
	for _, id in ipairs(list) do
		local key = pkey(id)
		if S.props[key] ~= nil then
			if S.props[key] < ALL_LOW then LS.prop_set(id, ALL_TOP); n = n + 1 end
		else
			local cur = 0
			for _, x in ipairs(idx[key] or {}) do cur = cur + (tonumber(x.rec.prop_number) or 0) end
			if cur < ALL_LOW then
				if R.prop_rec ~= nil and R.prop_rec[key] == nil then R.prop_rec[key] = cur end
				prop_write(e, key, ALL_TOP, idx)
				R.bg_inj[key] = true
				n = n + 1
			end
		end
	end
	return n
end

function BG.tick(e)
	if S == nil or not R.ready or not on() then return end
	R.bg_n = (R.bg_n or 0) + 1
	if not all_on() then return end
	if R.inject ~= nil or R.grant ~= nil then return end
	if R.bg_n % TICK_ALL ~= 1 and R.bg_all_done then return end
	R.bg_all_done = true
	local n = BG.fill_all(e)
	if n > 0 then
		R.bg_filled = (R.bg_filled or 0) + n
		if (R.bg_fill_logs or 0) < 5 then
			R.bg_fill_logs = (R.bg_fill_logs or 0) + 1
			log("tui do day du: bu", n, "loai vat pham (tong", #BG.all_list(), "loai)")
		end
	end
end

-- ===== [THU] Nhan thuong thu offline =====
-- Nguon du lieu: _ED._reward_centre (client tu parse khi mo thu / mod them thu). Moi thu co _reward_list =
-- { {prop_item, prop_type, item_value, ship_star}, ... }, draw_state (0 chua nhan / 1 da nhan), data_type (1|2).
-- user_read_mail                  : chi tra thanh cong (client tu danh dau da doc + mo cua so thu).
-- draw_attachment_in_mail         : nhan 1 thu (param: mail_id).
-- draw_reward_center              : nhan 1 thu / "Nhan het" (param: "N-1", "id,type", "id,type", ...).
-- one_key_draw_attachment_in_mail : nhan tat ca thu chua nhan.
local function mail_each(e, fn)
	local rc = e._reward_centre
	if type(rc) ~= "table" then return end
	local keys = {}
	for k in pairs(rc) do if type(k) == "number" then keys[#keys + 1] = k end end
	table.sort(keys)
	for _, k in ipairs(keys) do
		if type(rc[k]) == "table" then fn(rc[k]) end
	end
end

local function mail_items(e, v)
	local out = {}
	if v.ls_full == true then
		-- thu "Full vat pham": danh sach that sinh luc nhan (cua so thu chi ve vai mon mau cho nhe)
		local qty = math.max(1, math.floor(tn(v.ls_qty, 99)))
		for _, id in ipairs(BG.mail_all_list()) do out[#out + 1] = { id, 6, qty } end
		if not (type(S.cfg) == "table" and S.cfg.mail_full_equip == false) then
			local eqq = 5
			if type(S.cfg) == "table" and tonumber(S.cfg.mail_full_eq_qty) ~= nil then eqq = math.max(1, math.min(99, math.floor(S.cfg.mail_full_eq_qty))) end
			for _, id in ipairs(BG.mail_equip_list()) do out[#out + 1] = { id, 7, eqq } end
		end
		return out
	end
	local src = v._reward_list
	if type(src) ~= "table" or #src == 0 then
		local ms = type(e.mail_system) == "table" and e.mail_system[tostring(v._reward_centre_id)] or nil
		if type(ms) == "table" and type(ms.mail_items) == "table" then src = ms.mail_items end
	end
	if type(src) == "table" then
		for _, it in ipairs(src) do
			if type(it) == "table" then out[#out + 1] = { it.prop_item, it.prop_type, it.item_value, it.ship_star } end
		end
	end
	return out
end

-- Mau hien thi cho thu Full: n vat pham dau tien (khong rong, co trong tui) theo id tang dan.
function BG.mail_preview(n)
	local out = {}
	local t = dtab("prop_mould")
	if t == nil then return out end
	local ids = {}
	for k in pairs(t) do
		local id = tonumber(k)
		if id ~= nil then ids[#ids + 1] = math.floor(id) end
	end
	table.sort(ids)
	for _, id in ipairs(ids) do
		local it = BG.item(id)
		if it ~= nil and not it.blank and it.page ~= -1 then
			out[#out + 1] = id
			if #out >= n then break end
		end
	end
	return out
end

-- Danh sach cho thu Full: moi mon trong prop_mould, chi bo mon blank (ten = "1").
-- Khac BG.all_list(): KHONG loai mon co storage_page_index == -1 (mon an khoi tui nhung van la vat pham that).
-- Tat bang S.cfg.mail_full_hidden = false de quay lai cach loc cu.
function BG.mail_all_list()
	local strict = type(S.cfg) == "table" and S.cfg.mail_full_hidden == false
	if strict then return BG.all_list() end
	if R.bg_mail_all ~= nil then return R.bg_mail_all end
	local out = {}
	local t = dtab("prop_mould")
	if t ~= nil then
		for k in pairs(t) do
			local id = tonumber(k)
			if id ~= nil then
				local it = BG.item(id)
				if it ~= nil and not it.blank then out[#out + 1] = math.floor(id) end
			end
		end
	end
	table.sort(out)
	R.bg_mail_all = out
	return out
end

-- Danh sach trang bi (loai 7) cho thu Full: moi mau trong equipment_mould co ten that.
function BG.mail_equip_list()
	if R.bg_mail_eq ~= nil then return R.bg_mail_eq end
	local out = {}
	local d, em = G("dms"), G("equipment_mould")
	local t = dtab("equipment_mould")
	if t ~= nil and type(d) == "table" and type(em) == "table" and em.equipment_name ~= nil then
		for k in pairs(t) do
			local id = tonumber(k)
			if id ~= nil and id > 0 then
				local ok, nm = pcall(d.string, t, id, em.equipment_name)
				nm = ok and tostring(nm or "") or ""
				if nm ~= "" and nm ~= "0" and nm ~= "1" then out[#out + 1] = math.floor(id) end
			end
		end
	end
	table.sort(out)
	R.bg_mail_eq = out
	return out
end

local function mail_claim(e, mails, name, seq)
	local list, add = new_bag_list()
	local picked = {}
	for _, v in ipairs(mails) do
		if tonumber(v.draw_state) ~= 1 then
			local items = mail_items(e, v)
			if #items > 0 then
				picked[#picked + 1] = v
				for _, it in ipairs(items) do add(it[1], it[2], it[3], it[4]) end
			else
				v.read_type = 1
			end
		end
	end
	-- Vat pham (loai 6) cong theo lo, chia nho moi frame (LS.mail_job_tick): cong tung mon bang prop_add se dung lai
	-- chi muc tui moi lan => hang nghin mon lam dung hinh.
	local props, rest, unknown, eqs = {}, {}, {}, {}
	for _, it in ipairs(list) do
		if it[2] == 6 then
			if prop_known(it[1]) then props[#props + 1] = it else unknown[#unknown + 1] = it end
		elseif it[2] == 7 then
			eqs[#eqs + 1] = it
		else
			rest[#rest + 1] = it
		end
	end
	if #eqs > 20 then
		-- nhieu trang bi: cong dan theo frame trong LS.mail_job_tick (cong 1 luc se dung hinh)
		for _, it in ipairs(eqs) do
			if equip_known(it[1]) then props[#props + 1] = it else unknown[#unknown + 1] = it end
		end
	else
		for _, it in ipairs(eqs) do rest[#rest + 1] = it end
	end
	local want_heroes = false
	for _, v in ipairs(picked) do if v.ls_full == true then want_heroes = true end end
	if want_heroes and not (type(S.cfg) == "table" and S.cfg.mail_full_heroes == false) and LS.gm_grant_all ~= nil then
		local okh, nh = pcall(LS.gm_grant_all)
		log("thu full: cap tat ca tuong ->", tostring(okh), tostring(nh))
	end
	local done, skipped, fl = BG.give(e, rest)
	for _, it in ipairs(unknown) do skipped[#skipped + 1] = it end
	if #props > 0 then LS.mail_job_add(props) end
	if type(S.mail_done) ~= "table" then S.mail_done = {} end
	for _, v in ipairs(picked) do
		v.draw_state, v.read_type = 1, 1
		S.mail_done[tostring(v._reward_centre_id)] = true
	end
	if #skipped > 0 then
		local sk = {}
		for i = 1, math.min(#skipped, 8) do sk[#sk + 1] = skipped[i][2] .. ":" .. skipped[i][1] .. "x" .. skipped[i][3] end
		log("thu: bo qua", #skipped, "muc khong cong duoc:", table.concat(sk, ","))
		if #skipped > 20 then toast("Thu: " .. #skipped .. " muc chua cong duoc", 6) else toast("Thu: " .. #skipped .. " muc chua cong duoc (" .. table.concat(sk, ",") .. ")", 6) end
	end
	local shown = {}
	for _, it in ipairs(done) do if #shown < 40 then shown[#shown + 1] = it end end
	for _, it in ipairs(props) do if #shown < 40 then shown[#shown + 1] = it end end
	local blocks = {}
	if #shown > 0 then push_all(blocks, blk_171(shown)) end
	if fl.user and CP.blk_user ~= nil then push_all(blocks, CP.blk_user(fl.exp, fl.leveled)) end
	R.bg_last = "thu: " .. #picked .. " thu -> " .. (#done + #props) .. " loai vat pham" .. (#skipped > 0 and (", bo qua " .. #skipped) or "")
	mark()
	LS.save_state(true)
	log("tui do:", R.bg_last)
	return reply(seq, name, blocks)
end

function BG.h_mail_read(p, seq)
	if not on() then return nil end
	pcall(LS.mail_fix, ctx())
	return reply(seq, "user_read_mail", {})
end

function BG.h_mail_draw(p, seq)
	local name = "draw_attachment_in_mail"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local idn = tonumber(p[1])
	local hit, any
	mail_each(e, function(v)
		if idn ~= nil and tonumber(v._reward_centre_id) == idn then
			if hit == nil and tonumber(v.data_type) ~= 1 then hit = v end
			if any == nil then any = v end
		end
	end)
	hit = hit or any
	if hit == nil then return reply(seq, name, {}) end
	return mail_claim(e, { hit }, name, seq)
end

function BG.h_mail_draw_center(p, seq)
	local name = "draw_reward_center"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local want = {}
	for i = 1, #p do
		local a, b = string.match(tostring(p[i]), "^%s*(%-?%d+)%s*,%s*(%-?%d+)%s*$")
		if a ~= nil then want[#want + 1] = { tonumber(a), tonumber(b) } end
	end
	local mails, used = {}, {}
	for _, w in ipairs(want) do
		local exact, loose
		mail_each(e, function(v)
			if not used[v] and tonumber(v._reward_centre_id) == w[1] then
				if exact == nil and tonumber(v._reward_type) == w[2] then exact = v end
				if loose == nil then loose = v end
			end
		end)
		local v = exact or loose
		if v ~= nil then used[v] = true; mails[#mails + 1] = v end
	end
	return mail_claim(e, mails, name, seq)
end

function BG.h_mail_draw_all(p, seq)
	local name = "one_key_draw_attachment_in_mail"
	if not on() then return nil end
	local e = ctx()
	if e == nil then return nil end
	local mails = {}
	mail_each(e, function(v) mails[#mails + 1] = v end)
	return mail_claim(e, mails, name, seq)
end

function BG.on_world(e)
	R.bg_all_done = false
	R.bg_inj = {}
end

function BG.dump_line()
	local a = S ~= nil and S.bg or nil
	local u = type(a) == "table" and a or { n_use = 0, n_item = 0, n_sell = 0, n_comp = 0 }
	return "[LS tui do] dung " .. fint(tn(u.n_use, 0)) .. " lan (" .. fint(tn(u.n_item, 0)) .. " vat pham) | ban " .. fint(tn(u.n_sell, 0))
		.. " | ghep " .. fint(tn(u.n_comp, 0)) .. " | tui day du " .. (all_on() and ("BAT (" .. #BG.all_list() .. " loai)") or "TAT")
		.. (on() and "" or " | MODULE TAT")
		.. (R.bg_last and (" | cuoi: " .. R.bg_last) or "")
end

function BG.reset(e)
	S.bg = nil
	if type(e) == "table" and R.bg_inj ~= nil then
		local idx = prop_index(e)
		for key in pairs(R.bg_inj) do
			if S.props[key] == nil then prop_write(e, key, (R.prop_rec and R.prop_rec[key]) or 0, idx) end
		end
	end
	R.bg_inj, R.bg_last, R.bg_all_done = {}, nil, false
	mark()
end

LS._bg = BG
end
init_bg()
end

do
local function init_ts()

local TS = {}
local EVERY = 10

local function split_tab(s)
	local t, init = {}, 1
	while true do
		local p = string.find(s, "\t", init, true)
		if p == nil then t[#t + 1] = string.sub(s, init); break end
		t[#t + 1] = string.sub(s, init, p - 1)
		init = p + 1
	end
	return t
end
local function dtab(name)
	local d = G("dms")
	if type(d) == "table" and type(d[name]) == "table" then return d[name] end
	return nil
end
local function cells(row)
	if type(row) == "string" then return split_tab(row) end
	if type(row) == "table" then return row end
	return nil
end
local function on() return not (type(S.cfg) == "table" and S.cfg.ts_sync == false) end

function TS.T()
	if R.ts_t ~= nil then return R.ts_t end
	local T = { groups = {}, bonus = 160 }
	local gt = dtab("ship_spirit_group")
	local sch = G("ship_spirit_group")
	local col = (type(sch) == "table" and tonumber(sch.ship_need_id)) or 4
	if gt ~= nil then
		for _, row in pairs(gt) do
			local r = cells(row)
			if r ~= nil and tonumber(r[1]) ~= nil then
				local need = {}
				for v in string.gmatch(tostring(r[col] or ""), "%-?%d+") do
					local n = tonumber(v)
					if n ~= nil and n > 0 then need[#need + 1] = n end
				end
				if #need > 0 then T.groups[#T.groups + 1] = need end
			end
		end
	end
	local pc = dtab("play_config")
	local psch = G("play_config")
	local pcol = (type(psch) == "table" and tonumber(psch.param)) or 4
	if pc ~= nil then
		local r = cells(pc[34])
		if r ~= nil and tonumber(r[1]) == 34 and tonumber(r[pcol]) ~= nil then T.bonus = tonumber(r[pcol]) end
	end
	R.ts_t = T
	return T
end

local function groups_done(owned)
	local n = 0
	for _, need in ipairs(TS.T().groups) do
		local all = true
		for _, tid in ipairs(need) do if not owned[tid] then all = false; break end end
		if all then n = n + 1 end
	end
	return n
end

function TS.scan(e)
	local sum, owned = 0, {}
	for sid, s in pairs(e.user_ship or {}) do
		if type(s) == "table" and tonumber(sid) ~= nil then
			sum = sum + (tonumber(s.ship_wisdom) or 0)
			local t = tonumber(s.ship_template_id)
			if t ~= nil then owned[t] = true end
			local b = tonumber(s.ship_base_template_id)
			if b ~= nil then owned[b] = true end
		end
	end
	return sum, groups_done(owned)
end

local function anchor(e)
	if R.ts_rec ~= nil then return R.ts_rec end
	if R.rec == nil then return nil end
	local sum, owned = 0, {}
	for sid, r in pairs(R.rec) do
		if type(r) == "table" then
			sum = sum + (tonumber(r.spd) or 0)
			if r.tid ~= nil then owned[r.tid] = true end
			local s = e.user_ship and e.user_ship[sid]
			local b = s and tonumber(s.ship_base_template_id)
			if b ~= nil then owned[b] = true end
		end
	end
	local g = groups_done(owned)
	local total = tonumber(e.ship_all_speed_info) or tonumber(e.user_info and e.user_info.speed_sum)

	if total ~= nil and R.ts_prev ~= nil and R.ts_last ~= nil and total == R.ts_last then total = R.ts_prev.total end
	local from_server = total ~= nil
	if total == nil then total = sum + TS.T().bonus * g end
	R.ts_rec = { sum = sum, groups = g, total = total, server = from_server }
	return R.ts_rec
end

function TS.total(e)
	local a = anchor(e)
	if a == nil then return nil end
	local sum, g = TS.scan(e)
	return math.max(0, math.floor(a.total + (sum - a.sum) + TS.T().bonus * (g - a.groups) + 0.5)), sum, g
end

function TS.publish(e, total)
	if total == nil then return false end
	local u = e.user_info
	if type(u) ~= "table" then return false end
	if tonumber(e.ship_all_speed_info) == total and tonumber(u.speed_sum) == total then return false end
	e.ship_all_speed_info = total
	local aes = G("aeslua")
	if type(aes) == "table" and aes.encrypt ~= nil then
		local ok, enc = pcall(aes.encrypt, "jar-world", total, aes.AES128, aes.ECBMODE)
		if ok and enc ~= nil then e.old_ship_all_speed = enc end
	end
	local f = G("getUserSpeedSum")
	local done = false
	if type(f) == "function" then done = pcall(f) and tonumber(u.speed_sum) == total end
	if not done then
		u.speed_sum = total
		if type(aes) == "table" and aes.encrypt ~= nil then
			local ok, enc = pcall(aes.encrypt, "jar-world", total, aes.AES128, aes.ECBMODE)
			if ok and enc ~= nil then e.old_speed_sum = enc end
		end
	end

	pcall(function()
		local fw = G("fwin")
		local w = fw and fw.find and fw:find("SmCultivateSpiritWindowClass")
		local H = G("ccui") and G("ccui").Helper
		if w ~= nil and w.roots ~= nil and w.roots[1] ~= nil and H ~= nil then
			local t = H:seekWidgetByName(w.roots[1], "Text_speed_n")
			if t ~= nil and t.setString ~= nil then t:setString(tostring(total)) end
		end
	end)
	R.ts_pub = (R.ts_pub or 0) + 1
	R.ts_last = total
	return true
end

function TS.update(e)
	if S == nil or not R.ready or not on() or e == nil then return false end
	if R.inject ~= nil then return false end
	local total = TS.total(e)
	return TS.publish(e, total)
end

function TS.force_for_fight(e)
	if S == nil or not R.ready or not on() or type(e) ~= "table" then return nil end
	if R.inject ~= nil or type(e.user_info) ~= "table" then return nil end
	local total = TS.total(e)
	if total == nil then return nil end
	total = math.max(0, math.floor(total))
	e.ship_all_speed_info = total
	e.user_info.speed_sum = total
	local aes = G("aeslua")
	if type(aes) == "table" and aes.encrypt ~= nil then
		local ok1, enc1 = pcall(aes.encrypt, "jar-world", total, aes.AES128, aes.ECBMODE)
		if ok1 and enc1 ~= nil then e.old_ship_all_speed = enc1 end
		local ok2, enc2 = pcall(aes.encrypt, "jar-world", total, aes.AES128, aes.ECBMODE)
		if ok2 and enc2 ~= nil then e.old_speed_sum = enc2 end
	end
	R.ts_last = total
	return total
end

function TS.tick(e)
	if S == nil or not R.ready then return end
	R.ts_n = (R.ts_n or 0) + 1
	if R.ts_n % EVERY ~= 1 then return end
	TS.update(e)
end

function TS.wrap(fn)
	return function(p, seq)
		local res = fn(p, seq)
		if type(res) ~= "string" or not on() then return res end
		local st = string.match(res, "^[^\r\n]*\r\n[^\r\n]*\r\n(%-?%d+)")
		if st ~= "0" then return res end
		local e = ED()
		if e == nil then return res end
		local ok, total = pcall(TS.total, e)
		if not ok or total == nil then return res end
		pcall(TS.publish, e, total)
		return res .. "\r\n12042\r\n" .. fint(total)
	end
end

function TS.on_world(e)
	if R.ts_rec ~= nil then R.ts_prev = R.ts_rec end
	R.ts_rec, R.ts_t, R.ts_n = nil, nil, 0
end

function TS.dump_line()
	local a = R.ts_rec
	local e = ED()
	local now, sum, g
	if e ~= nil and a ~= nil then now, sum, g = TS.total(e) end
	return "[LS toc do doi] luc vao game " .. (a and (fint(a.total) .. (a.server and "" or " (tu tinh)")) or "?")
		.. " | bay gio " .. (now and fint(now) or "?") .. " (tong tuong " .. (sum and fint(sum) or "?") .. ", nhom du " .. (g or "?")
		.. (a and ("/" .. a.groups) or "") .. ", +" .. fint(TS.T().bonus) .. " moi nhom) | _ED " .. tostring(e and e.ship_all_speed_info)
		.. (on() and "" or " | TAT")
end

LS._ts = TS
end
init_ts()
end

do

local function mod_of(which)
	if which == "deck" or which == "ic" then return LS._ic, "ic_full" end
	if which == "sg" or which == "soul" then return LS._sg, "sg_full" end
	if which == "cs" or which == "universe" then return LS._cs, "cs_full" end
	if which == "ma" or which == "animal" then return LS._ma, "ma_full" end
	if which == "hs" or which == "saga" then return LS._hs, "hs_full" end
	if which == "cb" or which == "combo" then return LS._cb, "cb_full" end
	if which == "af" or which == "artifact" or which == "thankhi" then return LS._af, "af_full" end
	if which == "tl" or which == "talent" or which == "thienphu" then return LS._tl, "tl_full" end
	if which == "al" or which == "alloy" or which == "hopkim" then return LS._al, "al_full" end
	if which == "sp" or which == "spirit" or which == "party" then return LS._sp, "sp_full" end
	if which == "ws" or which == "warsoul" or which == "chienhon" then return LS._ws, "ws_auto" end
	return nil
end

function LS.full_state()
	local ic, sg, cs, ma, hs, cb, af, tl, al, sp = LS._ic, LS._sg, LS._cs, LS._ma, LS._hs, LS._cb, LS._af, LS._tl, LS._al, LS._sp
	local a = (S ~= nil and ic ~= nil and ic.full_on ~= nil) and ic.full_on() or false
	local b = (S ~= nil and sg ~= nil and sg.full_on ~= nil) and sg.full_on() or false
	local c = (S ~= nil and cs ~= nil and cs.full_on ~= nil) and cs.full_on() or false
	local d = (S ~= nil and ma ~= nil and ma.full_on ~= nil) and ma.full_on() or false
	local e = (S ~= nil and hs ~= nil and hs.full_on ~= nil) and hs.full_on() or false
	local f = (S ~= nil and cb ~= nil and cb.full_on ~= nil) and cb.full_on() or false
	local g = (S ~= nil and af ~= nil and af.full_on ~= nil) and af.full_on() or false
	local h = (S ~= nil and tl ~= nil and tl.full_on ~= nil) and tl.full_on() or false
	local i = (S ~= nil and al ~= nil and al.full_on ~= nil) and al.full_on() or false
	local j = (S ~= nil and sp ~= nil and sp.full_on ~= nil) and sp.full_on() or false
	local ws = LS._ws
	local k = (S ~= nil and ws ~= nil and ws.full_on ~= nil) and ws.full_on() or false
	return a and true or false, b and true or false, c and true or false, d and true or false, e and true or false, f and true or false, g and true or false, h and true or false, i and true or false, j and true or false, k and true or false
end

function LS.gm_combo_manual()
	if not LS.ready() then return nil end
	local e, cb = ED(), LS._cb
	if e == nil or cb == nil or cb.gm_manual_unlock == nil then return nil end
	local ok, cards, heroes = pcall(cb.gm_manual_unlock, e)
	if not ok then
		log("loi GM Combo Card mo tay:", tostring(cards))
		return nil
	end
	return cards, heroes
end

function LS.gm_toggle_full(which)
	if not LS.ready() then return nil end
	local m, key = mod_of(which)
	if m == nil or m.full_on == nil then return nil end
	if type(S.cfg) ~= "table" then S.cfg = {} end
	local on = not m.full_on()
	if key == "ws_auto" then
		-- ws_auto mac dinh la TAT khi khong co (nil); chi bat khi == true
		S.cfg[key] = on and true or false
	else
		S.cfg[key] = on and true or nil
	end
	R.stat_dirty = true
	mark()
	local e = ED()
	if e ~= nil and m.apply_now ~= nil then
		local ok, err = pcall(m.apply_now, e)
		if not ok then log("loi GM full", tostring(which), tostring(err)) end
	end
	if e ~= nil then
		heroes_assert(e, true)
		fight_assert(e)
		R.stat_dirty = nil
	end
	stat_inc("gm_full_" .. key)
	LS.save_state(true)
	log("GM:", key, "=", on and "BAT (full)" or "TAT (tu nang)")
	return m.full_on() and true or false
end
end

-- ===================================================================================================
-- [THEM] DOI BIET DANH + CHU KY  (lenh user_info_modify, code 6314)
-- Client gui: p[1] = loai (0 = ten, 1 = avatar, 2 = chu ky, 3 = ca nhan hoa), p[2..] = gia tri.
-- Chi xu ly loai 0 va 2. Loai 1/3 tra nil -> OfflineMock xu ly nhu cu.
-- * Luu vao S.prof = { name=, sign=, renames= } (nam trong offline_ls_state.txt).
-- * Replay dang nhap luon nap lai ten/chu ky GOC vao _ED, nen PF.apply() duoc goi moi frame trong
--   LS.sync de ap lai ban da doi (re, chi gan khi khac).
-- * Phi doi ten lay tu user_config dong 3 ("0,100": lan dau free, tu lan 2 tro di 100 KC).
--   Dung giong UI SmPlayerChangeNickName:onUpdataDraw (change_name_number[1][1] = so lan da doi).
-- Khong them local cap file (gioi han 200 local cua Lua) -> moi thu nam trong do..end va LS._pf.
-- ===================================================================================================
do
	local PF = {}

	local function prof()
		if type(S.prof) ~= "table" then S.prof = {} end
		return S.prof
	end

	-- So lan da doi ten: uu tien gia tri da luu, neu chua co thi lay tu du lieu replay (12041).
	local function count_now(e)
		local pf = prof()
		if tonumber(pf.renames) ~= nil then return math.floor(tonumber(pf.renames)) end
		local c = e.user_info.change_name_number
		if type(c) == "table" and type(c[1]) == "table" then return math.floor(tn(c[1][1], 0)) end
		return 0
	end

	local function set_count(e, n)
		local u = e.user_info
		local c = u.change_name_number
		if type(c) ~= "table" or type(c[1]) ~= "table" then
			c = { { "0" } }
			u.change_name_number = c
		end
		c[1][1] = fint(n)
	end

	-- Phi doi ten khi da doi n lan (n = 0 -> lan dau). Hang cuoi cua user_config[3] dung cho moi lan sau.
	local function cost_for(n)
		local list = cfg_list("user_config", 3)
		if #list == 0 then list = { 0, 100 } end
		local i = n + 1
		if i > #list then i = #list end
		return list[i]
	end

	function PF.apply(e)
		local pf = (S ~= nil) and S.prof or nil
		if type(pf) ~= "table" then return end
		local u = (e ~= nil) and e.user_info or nil
		if type(u) ~= "table" then return end
		if type(pf.name) == "string" and pf.name ~= "" and u.user_name ~= pf.name then
			u.user_name = pf.name
		end
		if type(pf.sign) == "string" and u.user_signature ~= pf.sign then
			u.user_signature = pf.sign
		end
		if tonumber(pf.renames) ~= nil then
			local n = math.floor(tonumber(pf.renames))
			local c = u.change_name_number
			if type(c) ~= "table" or type(c[1]) ~= "table" or tostring(c[1][1]) ~= fint(n) then
				set_count(e, n)
			end
		end
	end

	function PF.h_modify(p, seq)
		local NAME = "user_info_modify"
		local kind = tostring(p[1] or "")
		if kind ~= "0" and kind ~= "2" then return nil end
		local e = ED()
		if e == nil or type(e.user_info) ~= "table" then
			return err_reply(seq, NAME, "LS_chua_san_sang", ERR.generic)
		end
		-- noi lai cac token sau loai bang \r\n de giu nguyen chuoi goc neu gia tri co xuong dong
		local val = ""
		if #p >= 2 then val = table.concat(p, "\r\n", 2) end
		local pf = prof()

		if kind == "2" then
			-- ===== CHU KY =====
			if #val > 240 then return err_reply(seq, NAME, "LS_chu_ky_qua_dai", ERR.generic) end
			pf.sign = val
			e.user_info.user_signature = val
			mark()
			stat_inc("sign_change")
			LS.save_state(true)
			log("doi chu ky ->", val)
			return reply(seq, NAME, {})
		end

		-- ===== BIET DANH =====
		local stripped = string.gsub(val, "%s", "")
		if stripped == "" then return err_reply(seq, NAME, "LS_ten_trong", 369) end      -- -369: Ten khong duoc de trong
		if #val > 200 then return err_reply(seq, NAME, "LS_ten_qua_dai", 132) end        -- -132: Do dai ten khong hop le
		if val == tostring(e.user_info.user_name) then return reply(seq, NAME, {}) end   -- trung ten cu: khong thu phi

		local n = count_now(e)
		local cost = cost_for(n)
		if cost > 0 then
			if tn(S.gold, 0) < cost then
				toast("Khong du KC de doi biet danh (can " .. fnum(cost) .. " KC). Mo bang GM -> BU TIEN.", 6)
				return err_reply(seq, NAME, "LS_khong_du_kc", ERR.generic)
			end
			LS.money_spend("gold", cost)
		end
		pf.name = val
		pf.renames = n + 1
		e.user_info.user_name = val
		set_count(e, n + 1)
		mark()
		stat_inc("rename")
		LS.save_state(true)
		log("doi biet danh ->", val, "| lan", n + 1, "| phi", cost, "KC")
		return reply(seq, NAME, {})
	end

	LS._pf = PF
end

