end

function LS.gm_topup(gold, silver)
	if not LS.ready() then return false end
	gold = gold or 1000000
	silver = silver or 100000000
	LS.money_add("gold", gold)
	LS.money_add("silver", silver)
	stat_inc("topups")
	pcall(LS.gm_refill_food)
	LS.save_state(true)
